INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'year', 'vi', '{"overview":"Năm nay mời bạn kiên nhẫn phát triển bản sắc, mục đích và cách sử dụng năng lượng. Ma Kết mang năng lượng Đất. Ma Kết kiên trì và biết tính đường dài. Cung này sẵn sàng đi từng bước để đạt mục tiêu mình coi trọng.","love":"Tình yêu sâu sắc hơn khi bạn nhất quán và cho kết nối phát triển theo nhịp tự nhiên. Thế mạnh sức bền, chiến lược, đáng tin cậy giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Công việc dài hạn vững vàng hơn khi hoài bão đi cùng cấu trúc bạn có thể duy trì. Dùng tham vọng, kỷ luật, kiên nhẫn, trách nhiệm làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xây dựng sự tự tin tài chính bằng thói quen lặp lại được thay vì dự đoán hoàn hảo. Nhận ra khi cứng nhắc, bi quan, đo giá trị bản thân bằng thành tích bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Xem sức khỏe tinh thần và thể chất là nền tảng cuộc sống đang xây dựng, không phải phần thưởng sau khi hoàn thành. Tiếp tục xây dựng điều lâu dài, và nhớ dành thời gian nghỉ ngơi.","guidance":"Trở lại định hướng này trong suốt năm: Tiếp tục xây dựng điều lâu dài, và nhớ dành thời gian nghỉ ngơi."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aquarius', 'vi', '{"name":"Bảo Bình","dateRange":"20/1 – 18/2","rulingPlanet":"Sao Thiên Vương","summary":"Bảo Bình suy nghĩ độc lập và quan tâm đến cộng đồng. Những ý tưởng khác biệt của cung này có thể mở ra cách làm mới.","originStory":"Bảo Bình gắn với Ganymede, người dâng chén mang nước đến cho các vị thần và, theo nghĩa biểu tượng, tri thức đến nhân loại. Dù hình ảnh mang nước, cung này thuộc nguyên tố Khí: ý tưởng, hệ thống và sự đổi mới được sẻ chia vì lợi ích chung.","traits":["Độc đáo","Độc lập","Nhân văn","Sáng kiến"],"strengths":["Đổi mới","Khách quan","Tầm nhìn cộng đồng"],"challenges":["Xa cách","Thói quen phản đối","Quan điểm cố định"],"compatibleSigns":["Song Tử","Thiên Bình","Nhân Mã"],"reflectionPrompt":"Hãy chia sẻ góc nhìn riêng theo cách giúp bạn gần mọi người hơn."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Bảo Bình mang năng lượng Khí. Bảo Bình suy nghĩ độc lập và quan tâm đến cộng đồng. Những ý tưởng khác biệt của cung này có thể mở ra cách làm mới.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh đổi mới, khách quan, tầm nhìn cộng đồng giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng độc đáo, độc lập, nhân văn, sáng kiến làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi xa cách, thói quen phản đối, quan điểm cố định bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Hãy chia sẻ góc nhìn riêng theo cách giúp bạn gần mọi người hơn.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Hãy chia sẻ góc nhìn riêng theo cách giúp bạn gần mọi người hơn."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'week', 'vi', '{"overview":"Tuần này phát triển qua lựa chọn đều đặn thay vì một khoảnh khắc kịch tính. Bảo Bình mang năng lượng Khí. Bảo Bình suy nghĩ độc lập và quan tâm đến cộng đồng. Những ý tưởng khác biệt của cung này có thể mở ra cách làm mới.","love":"Các mối quan hệ được nuôi dưỡng bởi cuộc trò chuyện có cả chân thành và ấm áp. Thế mạnh đổi mới, khách quan, tầm nhìn cộng đồng giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Tiến bộ nghề nghiệp tốt nhất đến từ việc chọn một ưu tiên và bảo vệ thời gian dành cho nó. Dùng độc đáo, độc lập, nhân văn, sáng kiến làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xem lại thói quen phía sau chi tiêu trước khi đưa ra cam kết lớn hơn. Nhận ra khi xa cách, thói quen phản đối, quan điểm cố định bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Cân bằng vận động với hồi phục thật sự trong suốt tuần. Hãy chia sẻ góc nhìn riêng theo cách giúp bạn gần mọi người hơn.","guidance":"Để câu hỏi này dẫn dắt tuần của bạn: Hãy chia sẻ góc nhìn riêng theo cách giúp bạn gần mọi người hơn."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'year', 'vi', '{"overview":"Năm nay mời bạn kiên nhẫn phát triển bản sắc, mục đích và cách sử dụng năng lượng. Bảo Bình mang năng lượng Khí. Bảo Bình suy nghĩ độc lập và quan tâm đến cộng đồng. Những ý tưởng khác biệt của cung này có thể mở ra cách làm mới.","love":"Tình yêu sâu sắc hơn khi bạn nhất quán và cho kết nối phát triển theo nhịp tự nhiên. Thế mạnh đổi mới, khách quan, tầm nhìn cộng đồng giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Công việc dài hạn vững vàng hơn khi hoài bão đi cùng cấu trúc bạn có thể duy trì. Dùng độc đáo, độc lập, nhân văn, sáng kiến làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xây dựng sự tự tin tài chính bằng thói quen lặp lại được thay vì dự đoán hoàn hảo. Nhận ra khi xa cách, thói quen phản đối, quan điểm cố định bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Xem sức khỏe tinh thần và thể chất là nền tảng cuộc sống đang xây dựng, không phải phần thưởng sau khi hoàn thành. Hãy chia sẻ góc nhìn riêng theo cách giúp bạn gần mọi người hơn.","guidance":"Trở lại định hướng này trong suốt năm: Hãy chia sẻ góc nhìn riêng theo cách giúp bạn gần mọi người hơn."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('pisces', 'vi', '{"name":"Song Ngư","dateRange":"19/2 – 20/3","rulingPlanet":"Sao Hải Vương","summary":"Song Ngư giàu trí tưởng tượng và dễ đồng cảm. Trực giác giúp cung này nhận ra những điều người khác có thể bỏ lỡ.","originStory":"Song Ngư gợi nhắc Aphrodite và Eros hóa thành cá, buộc mình với nhau để trốn Typhon. Sợi dây giữa hai con cá tượng trưng cho tận tụy, bản sắc linh hoạt, sự nhạy cảm tinh thần và khả năng tìm thấy thống nhất giữa những dòng chảy đổi thay.","traits":["Trắc ẩn","Giàu tưởng tượng","Trực giác tốt","Dịu dàng"],"strengths":["Đồng cảm","Sáng tạo","Thấu hiểu tinh thần"],"challenges":["Trốn tránh thực tại","Ranh giới mờ nhạt","Hấp thụ cảm xúc người khác"],"compatibleSigns":["Cự Giải","Bọ Cạp","Ma Kết"],"reflectionPrompt":"Trân trọng sự nhạy cảm của mình và đặt ra giới hạn để không bị quá tải."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'day', 'vi', '{"overview":"Hôm nay thuận lợi cho một bước đi rõ ràng và có chủ đích. Song Ngư mang năng lượng Nước. Song Ngư giàu trí tưởng tượng và dễ đồng cảm. Trực giác giúp cung này nhận ra những điều người khác có thể bỏ lỡ.","love":"Trong tình cảm hôm nay, hãy hiện diện thay vì suy đoán. Thế mạnh đồng cảm, sáng tạo, thấu hiểu tinh thần giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Trong công việc, hoàn thành việc ý nghĩa nhất trước khi tìm động lực mới. Dùng trắc ẩn, giàu tưởng tượng, trực giác tốt, dịu dàng làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Giữ lựa chọn tiền bạc hôm nay đơn giản và thực tế. Nhận ra khi trốn tránh thực tại, ranh giới mờ nhạt, hấp thụ cảm xúc người khác bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Một khoảng dừng nhỏ có thể giúp bạn lấy lại năng lượng. Trân trọng sự nhạy cảm của mình và đặt ra giới hạn để không bị quá tải.","guidance":"Trước khi ngày kết thúc, hãy nhớ: Trân trọng sự nhạy cảm của mình và đặt ra giới hạn để không bị quá tải."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'week', 'vi', '{"overview":"Tuần này phát triển qua lựa chọn đều đặn thay vì một khoảnh khắc kịch tính. Song Ngư mang năng lượng Nước. Song Ngư giàu trí tưởng tượng và dễ đồng cảm. Trực giác giúp cung này nhận ra những điều người khác có thể bỏ lỡ.","love":"Các mối quan hệ được nuôi dưỡng bởi cuộc trò chuyện có cả chân thành và ấm áp. Thế mạnh đồng cảm, sáng tạo, thấu hiểu tinh thần giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Tiến bộ nghề nghiệp tốt nhất đến từ việc chọn một ưu tiên và bảo vệ thời gian dành cho nó. Dùng trắc ẩn, giàu tưởng tượng, trực giác tốt, dịu dàng làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xem lại thói quen phía sau chi tiêu trước khi đưa ra cam kết lớn hơn. Nhận ra khi trốn tránh thực tại, ranh giới mờ nhạt, hấp thụ cảm xúc người khác bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Cân bằng vận động với hồi phục thật sự trong suốt tuần. Trân trọng sự nhạy cảm của mình và đặt ra giới hạn để không bị quá tải.","guidance":"Để câu hỏi này dẫn dắt tuần của bạn: Trân trọng sự nhạy cảm của mình và đặt ra giới hạn để không bị quá tải."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'year', 'vi', '{"overview":"Năm nay mời bạn kiên nhẫn phát triển bản sắc, mục đích và cách sử dụng năng lượng. Song Ngư mang năng lượng Nước. Song Ngư giàu trí tưởng tượng và dễ đồng cảm. Trực giác giúp cung này nhận ra những điều người khác có thể bỏ lỡ.","love":"Tình yêu sâu sắc hơn khi bạn nhất quán và cho kết nối phát triển theo nhịp tự nhiên. Thế mạnh đồng cảm, sáng tạo, thấu hiểu tinh thần giúp bạn kết nối mà không cần gồng mình thể hiện.","career":"Công việc dài hạn vững vàng hơn khi hoài bão đi cùng cấu trúc bạn có thể duy trì. Dùng trắc ẩn, giàu tưởng tượng, trực giác tốt, dịu dàng làm công cụ, không phải kỳ vọng phải đáp ứng cùng lúc.","finance":"Xây dựng sự tự tin tài chính bằng thói quen lặp lại được thay vì dự đoán hoàn hảo. Nhận ra khi trốn tránh thực tại, ranh giới mờ nhạt, hấp thụ cảm xúc người khác bắt đầu ảnh hưởng tới quyết định thực tế.","wellbeing":"Xem sức khỏe tinh thần và thể chất là nền tảng cuộc sống đang xây dựng, không phải phần thưởng sau khi hoàn thành. Trân trọng sự nhạy cảm của mình và đặt ra giới hạn để không bị quá tải.","guidance":"Trở lại định hướng này trong suốt năm: Trân trọng sự nhạy cảm của mình và đặt ra giới hạn để không bị quá tải."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('fool', 'es-419', '{"name":"El Loco","meaning":"Una página en blanco y un acto de fe: un nuevo viaje comienza con un corazón abierto.","advice":"Confía en el camino que tienes delante y da ese primer paso, incluso sin todas las respuestas.","yesNoMeaning":"Un nuevo comienzo rara vez conlleva una respuesta fija: el resultado depende del paso que se dé."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('magician', 'es-419', '{"name":"El Mago","meaning":"Posees todas las herramientas que necesitas. Enfoca tu voluntad y convierte la intención en acción.","advice":"Usa tus habilidades y recursos deliberadamente — ahora es el momento de hacerlo realidad.","yesNoMeaning":"Ya posees todo lo necesario: la energía apoya avanzar con enfoque."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('high-priestess', 'es-419', '{"name":"La Sacerdotisa","meaning":"La sabiduría silenciosa se esconde debajo de la superficie. Escuche su intuición y su voz interior.","advice":"Haz una pausa, ve hacia adentro y deja que tus instintos te guíen antes de actuar.","yesNoMeaning":"La respuesta está oculta bajo la superficie por ahora — confía en tu intuición en lugar de forzar un sí o no claro."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('empress', 'es-419', '{"name":"La Emperatriz","meaning":"El crecimiento, la abundancia y la energía nutritiva te rodean. Deja que florezcan la belleza y el cuidado.","advice":"Sea paciente y generoso: cree con amor y deje que las cosas maduren naturalmente.","yesNoMeaning":"El crecimiento, la abundancia y la energía enriquecedora respaldan tu deseo: la respuesta es un tranquilo sí."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('emperor', 'es-419', '{"name":"El Emperador","meaning":"Estructura, autoridad y liderazgo constante. Construye sobre bases sólidas con disciplina.","advice":"Toma el control con un plan claro; los límites firmes traen estabilidad duradera.","yesNoMeaning":"La estructura, la autoridad y la disciplina constante respaldan un sí confiado."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hierophant', 'es-419', '{"name":"El Sumo Sacerdote","meaning":"La tradición y la orientación confiable ofrecen un camino seguro. Aprende de lo que ha venido antes.","advice":"Siga la sabiduría establecida y busque el consejo de aquellos en quienes confía.","yesNoMeaning":"La tradición y la guía confiable apuntan a un sí confiable: apóyate en lo que ya ha demostrado su valía."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('lovers', 'es-419', '{"name":"Los Enamorados","meaning":"Un vínculo significativo o una elección importante. Sigue lo que tu corazón realmente valora.","advice":"Elige con honestidad y alineación: la conexión se profundiza cuando eres sincero.","yesNoMeaning":"Tu corazón y tus valores están alineados aquí: la respuesta es sí, especialmente cuando eliges con honestidad."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('chariot', 'es-419', '{"name":"El Carro","meaning":"La fuerza de voluntad y el impulso te llevan hacia adelante. Mantente enfocado y prevalecerás.","advice":"Mantén la vista en la meta y conduce con confianza a través de cada obstáculo.","yesNoMeaning":"La fuerza de voluntad y el impulso están de tu lado: un sí enfocado, siempre que te mantengas comprometido."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('strength', 'es-419', '{"name":"Fuerza","meaning":"El verdadero poder es gentil: la paciencia, el valor y la compasión doman cualquier desafío.","advice":"Lidera con calma y fuerza; una mano suave suele ser la más fuerte.","yesNoMeaning":"El coraje gentil y la resolución paciente hacen que esto sea un sí: lidere con calma, no con fuerza."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hermit', 'es-419', '{"name":"El Ermitaño","meaning":"Es momento de dar un paso atrás y buscar claridad interior. La soledad ahora trae respuestas más profundas.","advice":"Vuelve hacia tu interior, reflexiona y deja que la tranquilidad revele lo que realmente necesitas.","yesNoMeaning":"Todavía no: la carta te pide que des un paso atrás y encuentres claridad interior antes de actuar."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('wheel-of-fortune', 'es-419', '{"name":"Rueda de la Fortuna","meaning":"La fortuna cambia y los ciclos cambian. Lo que cambia ahora es parte de un ritmo más amplio.","advice":"Sigue la corriente con flexibilidad — abraza el giro, bueno o no.","yesNoMeaning":"La fortuna está cambiando: el resultado depende de cómo aproveche el cambio en lugar de un sí o un no fijo."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('justice', 'es-419', '{"name":"Justicia","meaning":"La verdad y la justicia prevalecen. La causa y el efecto ahora entran en equilibrio.","advice":"Actuar con honestidad y sopesar ambas partes; la balanza se estabilizará de manera justa.","yesNoMeaning":"Las balanzas aún están equilibrando: la respuesta justa depende de los hechos y de tu honestidad."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hanged-man', 'es-419', '{"name":"El Colgado","meaning":"Una pausa necesaria. Libera el control y mira la situación desde un nuevo ángulo.","advice":"Deja de empujar — entrégate al momento y permite que llegue una nueva perspectiva.","yesNoMeaning":"Primero es necesaria una pausa; forzar esto ahora sólo impediría una respuesta más clara."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('death', 'es-419', '{"name":"Muerte","meaning":"Un final allana el camino para la renovación. Liberen lo que ha cumplido su tiempo.","advice":"Déjalo ir sin arrepentimiento; una profunda transformación está abriendo una nueva puerta.","yesNoMeaning":"Un final está despejando el camino: el camino actual se está cerrando para que pueda comenzar uno nuevo."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('temperance', 'es-419', '{"name":"Templanza","meaning":"El equilibrio y la paciencia traen armonía. Combina los opuestos con gracia.","advice":"Muévete con moderación y mantén la calma: con pasos firmes llegas al destino.","yesNoMeaning":"El equilibrio y la paciencia traen armonía: un sí medido, dado paso firme a la vez."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('devil', 'es-419', '{"name":"El Diablo","meaning":"Tenga cuidado con el apego, la tentación o un patrón vinculante. Reconocer las cadenas.","advice":"Nombra lo que te retiene y reclama tu libertad: la cadena solo te ata si tú lo permites.","yesNoMeaning":"El apego o un patrón vinculante se interpone en el camino; todavía no, hasta que la cadena sea nombrada y rota."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('tower', 'es-419', '{"name":"La Torre","meaning":"El cambio repentino rompe lo falso y revela la verdad. Lo que cae nunca estuvo destinado a mantenerse en pie.","advice":"Da la bienvenida al cambio; de entre los escombros se puede construir una base más clara.","yesNoMeaning":"El cambio súbito está destrozando lo antiguo; el terreno debe asentarse antes de que un sí firme sea posible."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('star', 'es-419', '{"name":"La Estrella","meaning":"La esperanza, la curación y la tranquila inspiración renuevan tu espíritu después de la tormenta.","advice":"Confía en la luz que tienes delante y sigue creyendo: tus deseos están al alcance.","yesNoMeaning":"La esperanza y la tranquila renovación indican que sí: confía en la luz que te espera y mantén vivo tu deseo."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('moon', 'es-419', '{"name":"La Luna","meaning":"La ilusión y la incertidumbre empañan el camino. Confía en tu intuición, no en las apariencias.","advice":"Reduce la velocidad y mira más profundo; la claridad vendrá cuando la niebla se disipe.","yesNoMeaning":"La ilusión y la incertidumbre desdibujan el camino: la respuesta no está clara hasta que se mira más allá de las apariencias."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('sun', 'es-419', '{"name":"El Sol","meaning":"Alegría, éxito y claridad radiante. Todo es luminoso y lleno de vida.","advice":"Celebre y brille: la energía positiva atrae los resultados que desea.","yesNoMeaning":"La alegría y la claridad radiante confirman un sí brillante: todo está funcionando a tu favor."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('judgement', 'es-419', '{"name":"Juicio","meaning":"Un llamado a levantarte, renovarte y ser honesto contigo mismo. Un veredicto de despertar.","advice":"Responde al llamado con valentía; perdona el pasado y entra en tu próximo capítulo.","yesNoMeaning":"Un llamado a levantarse y renovarse, sí, especialmente una vez que perdonas el pasado y respondes con honestidad."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('world', 'es-419', '{"name":"El Mundo","meaning":"Finalización y cumplimiento: un ciclo se cierra en perfecta totalidad.","advice":"Celebra lo que has logrado; la puerta está abierta a un mundo más amplio.","yesNoMeaning":"La plenitud y la plenitud marcan esto como un sí cumplido: el ciclo se cierra a tu favor."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-wands', 'es-419', '{"name":"As de bastos","meaning":"Una chispa de inspiración abre un camino creativo audaz.","advice":"Comienza mientras la energía está fresca y dale a la idea un primer paso real.","yesNoMeaning":"El As de Bastos se inclina hacia sí: comienza mientras la energía es fresca y da a la idea un primer paso real."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-wands', 'es-419', '{"name":"Dos de Bastos","meaning":"Un futuro está tomando forma a través de la planificación y la elección de dirección.","advice":"Mire más allá de lo que le resulta familiar y luego comprométase con el camino que tiene espacio para crecer.","yesNoMeaning":"El Dos de Bastos sigue siendo condicional: mira más allá de lo que es familiar, luego comprométete con el camino con espacio para crecer."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-wands', 'es-419', '{"name":"Tres de Bastos","meaning":"El esfuerzo inicial se expande a medida que aparecen oportunidades y horizontes más amplios.","advice":"Continúe construyendo y prepárese para encontrar la respuesta que atrae su trabajo.","yesNoMeaning":"El Tres de Bastos se inclina hacia sí: sigue construyendo y estate preparado para recibir la respuesta que atrae tu trabajo."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-wands', 'es-419', '{"name":"cuatro de bastos","meaning":"La estabilidad, la bienvenida y la celebración compartida crean una base fuerte.","advice":"Marque el hito y deje que las personas que lo apoyen lo compartan.","yesNoMeaning":"El Cuatro de Bastos se inclina hacia sí: marca el hito y deja que las personas que apoyan lo compartan."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-wands', 'es-419', '{"name":"cinco de bastos","meaning":"Los objetivos en competencia crean fricción, ruido o una prueba de confianza.","advice":"Convierte la rivalidad en práctica útil y rechaza el conflicto que no tiene propósito.","yesNoMeaning":"El Cinco de Bastos sigue siendo condicional: convierte la rivalidad en práctica útil y rechaza el conflicto que no tiene propósito."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-wands', 'es-419', '{"name":"Seis de Bastos","meaning":"El reconocimiento sigue a un esfuerzo decidido y un progreso visible.","advice":"Acepte el estímulo, pero mantenga su confianza ligada al trabajo honesto.","yesNoMeaning":"El Seis de Bastos se inclina hacia el sí: acepta el estímulo, pero mantiene tu confianza ligada al trabajo honesto."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-wands', 'es-419', '{"name":"Siete de Bastos","meaning":"Mantienes terreno valioso mientras la presión prueba tu determinación.","advice":"Defiende lo que importa con límites claros en lugar de luchar contra todos los desafíos.","yesNoMeaning":"El Siete de Bastos se inclina hacia el sí: defiende lo que importa con límites claros en lugar de luchar contra cada desafío."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-wands', 'es-419', '{"name":"Ocho de Bastos","meaning":"Los acontecimientos se aceleran, llegan mensajes y el impulso elimina los retrasos.","advice":"Actúe con prontitud y mantenga la comunicación directa mientras el camino esté abierto.","yesNoMeaning":"El Ocho de Bastos se inclina hacia sí: actúa con prontitud y mantén la comunicación directa mientras el camino esté abierto."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-wands', 'es-419', '{"name":"Nueve de Bastos","meaning":"La resiliencia es fuerte, aunque las tensiones pasadas te hacen estar alerta.","advice":"Protege tu energía y da el siguiente paso sin esperar que cada herida se repita.","yesNoMeaning":"El Nueve de Bastos permanece condicional: protege tu energía y da el siguiente paso sin esperar que cada herida se repita."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-wands', 'es-419', '{"name":"Diez de Bastos","meaning":"La responsabilidad se ha vuelto pesada y el éxito ahora conlleva una carga.","advice":"Delega, simplifica y deja de lado el trabajo que ya no es tuyo.","yesNoMeaning":"El Diez de Bastos dice que no: delega, simplifica y deja de lado el trabajo que ya no es realmente tuyo."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-wands', 'es-419', '{"name":"Sota de Bastos","meaning":"La curiosidad trae un mensaje animado, un experimento o un nuevo interés creativo.","advice":"Explora con valentía y deja que la energía del principiante te enseñe a través de la acción.","yesNoMeaning":"El Paje de Bastos se inclina hacia sí: explora con coraje y deja que la energía de principiante te enseñe a través de la acción."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-wands', 'es-419', '{"name":"Caballero de Bastos","meaning":"La pasión avanza rápidamente, trayendo aventura y posible impaciencia.","advice":"Usa el impulso, pero elige una dirección antes de que la velocidad disperse tu esfuerzo.","yesNoMeaning":"El Caballero de Bastos sigue siendo condicional: usa el impulso, pero elige una dirección antes de que la velocidad disperse tu esfuerzo."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-wands', 'es-419', '{"name":"reina de bastos","meaning":"La cálida confianza y la independencia creativa atraen a otros hacia tu visión.","advice":"Confía en tu presencia, anima a los demás y no reduzcas tu ambición.","yesNoMeaning":"La Reina de Bastos se inclina hacia el sí: confía en tu presencia, anima a los demás y no reduzcas tu ambición."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-wands', 'es-419', '{"name":"rey de bastos","meaning":"La visión madura convierte la inspiración en un liderazgo decisivo y ético.","advice":"Lidera desde un propósito más amplio y da a otros espacio para contribuir.","yesNoMeaning":"El Rey de Bastos se inclina al sí: lidera desde un propósito más grande y da espacio a los demás para contribuir."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-cups', 'es-419', '{"name":"As de copas","meaning":"El corazón se abre a un nuevo afecto, compasión y renovación emocional.","advice":"Reciba el sentimiento con honestidad y deje que la atención fluya sin forzar un resultado.","yesNoMeaning":"El As de Copas se inclina por el sí: recibe el sentimiento honestamente y deja que el cuidado fluya sin forzar un resultado."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-cups', 'es-419', '{"name":"Dos de Copas","meaning":"El reconocimiento mutuo crea asociación, atracción o acuerdo sincero.","advice":"Conoce a la otra persona como a un igual y habla desde el corazón.","yesNoMeaning":"El Dos de Copas se inclina hacia el sí: encuentra a la otra persona como un igual y habla desde el corazón."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-cups', 'es-419', '{"name":"Tres de Copas","meaning":"La amistad, la comunidad y la alegría compartida brindan apoyo emocional.","advice":"Celebren juntos y recuerden quién realmente aparece por ustedes.","yesNoMeaning":"El Tres de Copas inclina hacia el sí: celebren juntos y recuerden quién realmente se presenta por ustedes."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-cups', 'es-419', '{"name":"Cuatro de Copas","meaning":"El retraimiento emocional hace que sea difícil notar un regalo disponible.","advice":"Haga una pausa en la comparación y observe nuevamente lo que se ofrece silenciosamente.","yesNoMeaning":"El Cuatro de Copas se inclina hacia no: pausa la comparación y observa de nuevo lo que se ofrece silenciosamente."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-cups', 'es-419', '{"name":"Cinco de Copas","meaning":"La pérdida llama la atención sobre lo que se derramó mientras queda algo significativo.","advice":"Honre la decepción y luego recurra al apoyo que todavía está presente.","yesNoMeaning":"El Cinco de Copas se inclina hacia no: honra la decepción y luego vuelve tu atención hacia el apoyo que aún está presente."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-cups', 'es-419', '{"name":"Seis de Copas","meaning":"El recuerdo, la inocencia o un vínculo familiar regresan con suave calidez.","advice":"Da la bienvenida a la bondad del pasado sin pretender que debes vivir allí de nuevo.","yesNoMeaning":"El Seis de Copas se inclina hacia el sí: da la bienvenida a la bondad del pasado sin pretender que debes vivir allí nuevamente."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-cups', 'es-419', '{"name":"Siete de Copas","meaning":"Muchas posibilidades atractivas desdibujan la diferencia entre visión e ilusión.","advice":"Limite las opciones y compare un sueño con la realidad antes de comprometerse.","yesNoMeaning":"El Siete de Copas todavía no está claro: reduce las opciones y prueba un sueño contra la realidad antes de comprometerte."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-cups', 'es-419', '{"name":"Ocho de Copas","meaning":"Una situación que alguna vez fue significativa ya no nutre el corazón.","advice":"Vete con honestidad y avanza hacia la satisfacción más profunda que ahora necesitas.","yesNoMeaning":"El Ocho de Copas se inclina hacia no: vete con honestidad y avanza hacia la realización más profunda que ahora necesitas."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-cups', 'es-419', '{"name":"Nueve de Copas","meaning":"La alegría y la gratitud hacen que un deseo sincero se sienta cercano.","advice":"Disfruta lo que hay aquí y pregúntate si el deseo también sirve a tus valores más profundos.","yesNoMeaning":"El Nueve de Copas se inclina al sí: disfruta lo que está aquí y pregunta si el deseo también sirve a tus valores más profundos."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-cups', 'es-419', '{"name":"Diez de Copas","meaning":"La armonía emocional, la pertenencia y la conexión duradera rodean el hogar.","advice":"Fomentar los vínculos que hacen que la alegría sea sostenible y compartida.","yesNoMeaning":"El Diez de Copas se inclina hacia el sí: cultiva los lazos que hacen que la alegría sea sostenible y compartida."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-cups', 'es-419', '{"name":"Sota de Copas","meaning":"Un mensaje tierno o un descubrimiento intuitivo invita a la apertura emocional.","advice":"Mantente curioso sobre la sensación y responde con sinceridad en lugar de suponer.","yesNoMeaning":"El Paje de Copas permanece condicional: mantente curioso sobre el sentimiento y responde con sinceridad en lugar de suposiciones."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-cups', 'es-419', '{"name":"Caballero de Copas","meaning":"El romance, la imaginación o un ideal atrae el corazón hacia adelante.","advice":"Siga la invitación, pero mantenga un pie en la tierra a medida que se desarrollen las promesas.","yesNoMeaning":"El Caballero de Copas se inclina al sí: sigue la invitación, pero mantén un pie en la tierra mientras se desarrollan las promesas."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-cups', 'es-419', '{"name":"reina de copas","meaning":"La empatía y la intuición profundas crean un espacio tranquilo para la verdad.","advice":"Escuche con compasión mientras preserva los límites que mantienen la atención saludable.","yesNoMeaning":"La Reina de Copas se inclina hacia el sí: escucha con compasión mientras preservas los límites que mantienen el cuidado saludable."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-cups', 'es-419', '{"name":"rey de copas","meaning":"La madurez emocional estabiliza los sentimientos fuertes sin reprimirlos.","advice":"Responda con compasión y dominio propio, especialmente cuando los demás sean reactivos.","yesNoMeaning":"El Rey de Copas se inclina hacia sí: responde con compasión y autodominio, especialmente cuando otros son reactivos."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-swords', 'es-419', '{"name":"As de espadas","meaning":"Una visión clara rompe la confusión y revela una nueva verdad.","advice":"Nombra el problema claramente y utiliza la claridad al servicio de una decisión justa.","yesNoMeaning":"El As de Espadas se inclina hacia sí: nombra el problema claramente y usa la claridad al servicio de una decisión justa."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-swords', 'es-419', '{"name":"Dos de Espadas","meaning":"Un estancamiento cauteloso retrasa una elección que no puede permanecer suspendida para siempre.","advice":"Quítese la venda de los ojos con cuidado, recopile el dato que falta y decida desde el equilibrio.","yesNoMeaning":"El Dos de Espadas aún no está claro: quita la venda suavemente, reúne el hecho que falta y decide desde el equilibrio."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-swords', 'es-419', '{"name":"Tres de Espadas","meaning":"Una verdad dolorosa, una separación o una decepción piden ser reconocidas.","advice":"Deja que el sentimiento te atraviese y evita convertir el dolor en una historia permanente.","yesNoMeaning":"El Tres de Espadas dice no: deja que el sentimiento pase por ti y evita convertir el dolor en una historia permanente."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-swords', 'es-419', '{"name":"cuatro de espadas","meaning":"Se necesita descanso y tranquilidad mental después de una presión o un conflicto.","advice":"Haga una pausa antes de responder; la recuperación es productiva cuando restablece el pensamiento claro.","yesNoMeaning":"El Cuatro de Espadas se inclina hacia no: pausa antes de responder; la recuperación es productiva cuando restaura un pensamiento claro."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-swords', 'es-419', '{"name":"Cinco de Espadas","meaning":"El conflicto puede producir una victoria vacía o dañar la confianza.","advice":"Elija la dignidad antes que ganar y aléjese de tácticas que cuestan demasiado.","yesNoMeaning":"El Cinco de Espadas se inclina hacia no: elige la dignidad sobre la victoria y aléjate de tácticas que cuestan demasiado."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-swords', 'es-419', '{"name":"Seis de Espadas","meaning":"Un pasaje difícil avanza gradualmente hacia condiciones más tranquilas.","advice":"Toma lo que has aprendido, acepta apoyo y sigue alejándote del caos.","yesNoMeaning":"El Seis de Espadas se inclina hacia el sí: toma lo que has aprendido, acepta apoyo y sigue alejándote de la agitación."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-swords', 'es-419', '{"name":"Siete de Espadas","meaning":"La estrategia, el secreto o la evasión complican el camino.","advice":"Actuar con inteligencia pero con transparencia; Los atajos que traicionan la confianza volverán en forma de problemas.","yesNoMeaning":"El Siete de Espadas se inclina hacia el no: actúa con astucia pero de manera transparente; los atajos que traicionan la confianza regresarán como problemas."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-swords', 'es-419', '{"name":"Ocho de espadas","meaning":"El miedo y las creencias restrictivas hacen que sea difícil ver las opciones disponibles.","advice":"Cuestiona el pensamiento que dice que estás atrapado y realiza una pequeña acción liberadora.","yesNoMeaning":"El Ocho de Espadas se inclina hacia no: cuestiona el pensamiento que dice que estás atrapado y da una pequeña acción liberadora."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-swords', 'es-419', '{"name":"Nueve de espadas","meaning":"La ansiedad magnifica el peligro en la oscuridad y agota la mente.","advice":"Saque el miedo a la luz del día, busque apoyo y separe los hechos de los resultados imaginados.","yesNoMeaning":"El Nueve de Espadas se inclina hacia no: trae el miedo a la luz del día, busca apoyo y separa los hechos de los resultados imaginados."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-swords', 'es-419', '{"name":"Diez de Espadas","meaning":"Un ciclo doloroso llega a su límite final y no puede continuar sin cambios.","advice":"Acepta el final, protege tu recuperación y permite que surja un comienzo diferente.","yesNoMeaning":"El Diez de Espadas advierte: acepta el final, protege tu recuperación y permite que emerja un nuevo comienzo."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-swords', 'es-419', '{"name":"Sota de espadas","meaning":"La curiosidad alerta busca hechos, hace preguntas y observa cambios.","advice":"Investigue detenidamente y hable con precisión en lugar de reaccionar a cada señal.","yesNoMeaning":"El Paje de Espadas permanece condicional: investiga cuidadosamente y habla con precisión en lugar de reaccionar a cada señal."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-swords', 'es-419', '{"name":"Caballero de espadas","meaning":"El intelecto enfocado se mueve rápido y enfrenta los obstáculos directamente.","advice":"Avanza con valentía, pero lo suficientemente lento como para escuchar lo que tu certeza podría pasar por alto.","yesNoMeaning":"El Caballero de Espadas sigue siendo condicional: avanza con coraje, pero lo suficientemente despacio como para escuchar lo que tu certeza podría pasar por alto."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-swords', 'es-419', '{"name":"reina de espadas","meaning":"La percepción clara y los límites honestos eliminan la confusión.","advice":"Di lo que es verdadero con compasión y deja que la experiencia te afile, no te endurezca.","yesNoMeaning":"La Reina de Espadas se inclina hacia el sí: di lo que es verdad con compasión y deja que la experiencia te agudice, no te endurezca."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-swords', 'es-419', '{"name":"rey de espadas","meaning":"La razón, la justicia y el juicio disciplinado guían una decisión importante.","advice":"Usa evidencia, define el estándar y mantén el sesgo personal fuera del veredicto.","yesNoMeaning":"El Rey de Espadas se inclina al sí: usa evidencia, define el estándar y mantén el sesgo personal fuera del veredicto."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-pentacles', 'es-419', '{"name":"As de Oros","meaning":"Una oportunidad tangible ofrece la semilla de la prosperidad, el trabajo o el bienestar.","advice":"Fundamente la oportunidad en un plan práctico y cuídela constantemente.","yesNoMeaning":"El As de Oros se inclina hacia sí: cimenta la oportunidad en un plan práctico y cuídala de manera constante."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-pentacles', 'es-419', '{"name":"Dos de Pentáculos","meaning":"Varias prioridades avanzan al mismo tiempo y requieren un equilibrio flexible.","advice":"Ajusta el ritmo, protege lo esencial y evita prometer más de lo que puedes cumplir.","yesNoMeaning":"El Dos de Pentáculos sigue siendo condicional: ajusta el ritmo, protege lo esencial y evita prometer más de lo que puedes cargar."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-pentacles', 'es-419', '{"name":"Tres de Pentáculos","meaning":"La habilidad crece a través de la colaboración, la retroalimentación y la cuidadosa elaboración.","advice":"Contribuya con su fuerza, respete su experiencia y construya un estándar compartido.","yesNoMeaning":"El Tres de Pentáculos se inclina a sí: contribuye con tu fuerza, respeta la experiencia y construye según un estándar compartido."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-pentacles', 'es-419', '{"name":"Cuatro de Oros","meaning":"Mantener estrictamente la seguridad puede preservar los recursos pero restringir el flujo saludable.","advice":"Protege lo que importa sin dejar que el miedo tome todas las decisiones por ti.","yesNoMeaning":"El Cuatro de Oros sigue siendo condicional: protege lo que importa sin dejar que el miedo tome todas tus decisiones."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-pentacles', 'es-419', '{"name":"Cinco de Oros","meaning":"La tensión material o la exclusión crean preocupación y una sensación de escasez.","advice":"Pida ayuda práctica y observe la puerta que las dificultades han hecho fácil pasar por alto.","yesNoMeaning":"El Cinco de Oros se inclina hacia no: pide ayuda práctica y nota la puerta que la adversidad ha hecho fácil de pasar por alto."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-pentacles', 'es-419', '{"name":"Seis de Pentáculos","meaning":"Se intercambian recursos, lo que plantea cuestiones de generosidad, poder y justicia.","advice":"Dar o recibir con términos claros para que el apoyo preserve la dignidad de ambas partes.","yesNoMeaning":"El Seis de Oros se inclina hacia el sí: da o recibe con condiciones claras para que el apoyo preserve la dignidad de ambos lados."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-pentacles', 'es-419', '{"name":"Siete de Pentáculos","meaning":"La inversión paciente llega a un punto de evaluación antes del siguiente esfuerzo.","advice":"Revisa lo que está creciendo, mejora el método y permite tiempo a los resultados valiosos.","yesNoMeaning":"El Siete de Oros sigue siendo condicional: revisa lo que está creciendo, mejora el método y permite tiempo para resultados valiosos."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-pentacles', 'es-419', '{"name":"Ocho de Oros","meaning":"La repetición enfocada desarrolla dominio y resultados confiables.","advice":"Practique la habilidad esencial, agradezca las correcciones y deje que la calidad se acumule.","yesNoMeaning":"El Ocho de Oros se inclina hacia sí: practica la habilidad esencial, acepta la corrección y deja que la calidad se acumule."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-pentacles', 'es-419', '{"name":"Nueve de Oros","meaning":"La autosuficiencia y el confort cultivado reflejan un progreso disciplinado.","advice":"Disfruta de lo que has construido y mantén la independencia conectada con la gratitud.","yesNoMeaning":"El Nueve de Oros se inclina hacia sí: disfruta lo que has construido y mantén la independencia conectada con la gratitud."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-pentacles', 'es-419', '{"name":"Diez de Oros","meaning":"La seguridad a largo plazo crece a través del legado, la familia y las fundaciones compartidas.","advice":"Planifique más allá de la victoria inmediata y proteja lo que pueda ayudar a otros con el tiempo.","yesNoMeaning":"El Diez de Oros se inclina hacia el sí: planifica más allá de la victoria inmediata y protege lo que puede apoyar a otros con el tiempo."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-pentacles', 'es-419', '{"name":"Sota de Oros","meaning":"Un mensaje práctico invita al estudio, la planificación o un nuevo emprendimiento fundamentado.","advice":"Aprenda los conceptos básicos, defina la siguiente tarea y demuestre la idea mediante un trabajo constante.","yesNoMeaning":"El Paje de Oros se inclina hacia sí: aprende lo básico, define la siguiente tarea y prueba la idea mediante trabajo constante."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-pentacles', 'es-419', '{"name":"Caballero de Oros","meaning":"El esfuerzo confiable avanza lentamente pero rara vez abandona la tarea.","advice":"Mantenga la rutina honesta y consistente; El progreso importa más que la emoción.","yesNoMeaning":"El Caballero de Oros se inclina al sí: mantén la rutina honesta y consistente; el progreso importa más que la emoción."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-pentacles', 'es-419', '{"name":"Reina de Oros","meaning":"El cuidado ingenioso crea comodidad, salud y abundancia práctica.","advice":"Cuide a las personas y los planes de manera que sigan siendo sostenibles para usted.","yesNoMeaning":"La Reina de Oros se inclina hacia el sí: nutre a las personas y los planes de maneras que sigan siendo sostenibles para ti."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-pentacles', 'es-419', '{"name":"Rey de Oros","meaning":"El liderazgo material convierte la experiencia en una mayordomía estable y generosa.","advice":"Tome la decisión acertada a largo plazo y utilice el éxito de manera responsable.","yesNoMeaning":"El Rey de Oros se inclina hacia sí: toma la decisión sólida a largo plazo y usa el éxito responsablemente."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aries', 'es-419', '{"name":"Aries","dateRange":"21 de marzo – 19 de abril","rulingPlanet":"Marte","summary":"Los comienzos audaces y la acción directa definen al Carnero, cuya chispa convierte la intención en impulso.","originStory":"Aries está vinculado al carnero dorado que rescató a Frixo en el mito griego. Su vellón se convirtió más tarde en el premio de Jasón y los argonautas, conservándose el signo como símbolo de valentía, rescate y primer paso valiente.","traits":["Valiente","Energético","Independiente","Directo"],"strengths":["Iniciativa","Confianza","Resiliencia"],"challenges":["Impaciencia","Impulsividad","Comenzando más rápido de lo que puedes sostener"],"compatibleSigns":["León","Sagitario","Géminis"],"reflectionPrompt":"Elige un comienzo valiente y dale suficiente paciencia para crecer."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'day', 'es-419', '{"overview":"Hoy favorece un paso claro e intencional. Aries se mueve a través de la energía del fuego. Comienzos audaces y acción directa definen al Carnero, cuya chispa convierte la intención en impulso.","love":"En el amor hoy, elige la presencia sobre la suposición. Tus dones de iniciativa, confianza y resiliencia pueden ayudarte a conectarte sin actuar.","career":"En el trabajo, complete la tarea más significativa antes de buscar un nuevo impulso. Utilice como herramientas personas valientes, enérgicas, independientes y directas, no expectativas que deba satisfacer todas a la vez.","finance":"Mantenga las decisiones monetarias de hoy simples y fundamentadas. Observe cuando la impaciencia, la impulsividad, comenzar más rápido de lo que puede sostener comienza a influir en una decisión práctica.","wellbeing":"Una pequeña pausa puede restablecer tu energía. Elige un comienzo valiente y dale suficiente paciencia para crecer.","guidance":"Antes de que termine el día, recuerda: elige un comienzo valiente y dale suficiente paciencia para crecer."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'week', 'es-419', '{"overview":"Esta semana se desarrolla a través de elecciones constantes en lugar de un momento dramático. Aries se mueve a través de la energía del fuego. Comienzos audaces y acción directa definen al Carnero, cuya chispa convierte la intención en impulso.","love":"Las relaciones se benefician de una conversación que deja espacio tanto para la honestidad como para la calidez. Tus dones de iniciativa, confianza y resiliencia pueden ayudarte a conectarte sin actuar.","career":"Tu mejor progreso profesional proviene de elegir una prioridad y proteger tiempo para ella. Usa valiente, enérgico, independiente, directo como herramientas, no como expectativas que debes cumplir todas a la vez.","finance":"Revise el patrón detrás de sus gastos antes de hacer un compromiso mayor. Observe cuando la impaciencia, la impulsividad, comenzar más rápido de lo que puede sostener comienza a influir en una decisión práctica.","wellbeing":"Equilibre el movimiento con una recuperación genuina durante toda la semana. Elige un comienzo valiente y dale suficiente paciencia para crecer.","guidance":"Deja que esta pregunta guíe la semana: elige un comienzo valiente y dale suficiente paciencia para crecer."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'year', 'es-419', '{"overview":"Este año invita a un crecimiento paciente en torno a la identidad, el propósito y la manera en que usas tu energía. Aries se mueve a través de la energía del fuego. Comienzos audaces y acción directa definen al Carnero, cuya chispa convierte la intención en impulso.","love":"El amor se profundiza cuando practicas la coherencia y permites que la conexión evolucione a un ritmo humano. Tus dones de iniciativa, confianza y resiliencia pueden ayudarte a conectarte sin actuar.","career":"El trabajo a largo plazo se fortalece cuando la ambición se combina con una estructura que se puede sostener. Utilice como herramientas personas valientes, enérgicas, independientes y directas, no expectativas que deba satisfacer todas a la vez.","finance":"Genere confianza financiera a través de hábitos repetibles en lugar de predicciones perfectas. Observe cuando la impaciencia, la impulsividad, comenzar más rápido de lo que puede sostener comienza a influir en una decisión práctica.","wellbeing":"Trata el bienestar como una base para la vida que estás construyendo, no como una recompensa después de terminarla. Elige un comienzo valiente y dale suficiente paciencia para crecer.","guidance":"Vuelve a esta brújula durante todo el año: elige un comienzo valiente y dale la paciencia suficiente para que crezca."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('taurus', 'es-419', '{"name":"Tauro","dateRange":"20 de abril – 20 de mayo","rulingPlanet":"Venus","summary":"Firme, sensual y con los pies en la tierra, el Toro construye valor duradero a través de la paciencia y el cuidado.","originStory":"Tauro recuerda a Zeus tomando la forma de un magnífico toro blanco para llevar a Europa a través del mar. La imagen se asoció con la belleza, la fertilidad, la abundancia terrestre y el poder expresado a través de la persistencia tranquila.","traits":["Conectado a tierra","Leal","Paciente","Sensual"],"strengths":["Fiabilidad","Sabiduría práctica","Devoción"],"challenges":["Terquedad","Resistencia al cambio","Aguantando demasiado"],"compatibleSigns":["Virgo","Capricornio","Cáncer"],"reflectionPrompt":"Protege lo que importa sin confundir comodidad con permanencia."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'day', 'es-419', '{"overview":"Hoy favorece un paso claro e intencional. Tauro se mueve a través de la energía de la tierra. Firme, sensual y con los pies en la tierra, el Toro construye valor duradero a través de la paciencia y el cuidado.","love":"En el amor hoy, elige la presencia sobre la suposición. Tus dones de confiabilidad, sabiduría práctica y devoción pueden ayudarte a conectarte sin actuar.","career":"En el trabajo, complete la tarea más significativa antes de buscar un nuevo impulso. Utilice herramientas sólidas, leales, pacientes y sensuales, no expectativas que deba satisfacer todas a la vez.","finance":"Mantenga las decisiones monetarias de hoy simples y fundamentadas. Observe cuándo la terquedad, la resistencia al cambio y el aferrarse demasiado comienzan a influir en una decisión práctica.","wellbeing":"Una pequeña pausa puede restablecer tu energía. Protege lo que importa sin confundir comodidad con permanencia.","guidance":"Antes de que termine el día, recuerda: Protege lo que importa sin confundir comodidad con permanencia."}');
