INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('virgo', 'es-419', '{"name":"Virgo","dateRange":"23 de agosto – 22 de septiembre","rulingPlanet":"Mercurio","summary":"El discernimiento y el servicio guían a la Doncella, convirtiendo la observación cuidadosa en mejora práctica.","originStory":"Virgo a menudo se asocia con Astrea, la doncella de la justicia que permaneció con la humanidad después de que otros dioses se retiraran. El trigo que lleva vincula al signo con la cosecha, la habilidad, la pureza de intención y el cuidado de lo que sostiene la vida.","traits":["Observante","Práctico","Reflexivo","Preciso"],"strengths":["Análisis","Artesanía","Servicio útil"],"challenges":["perfeccionismo","Autocrítica","Preocuparse por los detalles"],"compatibleSigns":["Tauro","Capricornio","Cáncer"],"reflectionPrompt":"Mejore lo que pueda y permita que el buen trabajo esté completo antes de que sea perfecto."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'day', 'es-419', '{"overview":"Hoy favorece un paso claro e intencional. Virgo se mueve a través de la energía de la tierra. El discernimiento y el servicio guían a la Doncella, convirtiendo la observación cuidadosa en mejora práctica.","love":"En el amor hoy, elige la presencia sobre la suposición. Sus dotes de análisis, destreza y servicio útil pueden ayudarlo a conectarse sin tener que actuar.","career":"En el trabajo, complete la tarea más significativa antes de buscar un nuevo impulso. Utilice herramientas observadoras, prácticas, reflexivas y precisas, no expectativas que deba satisfacer todas a la vez.","finance":"Mantenga las decisiones monetarias de hoy simples y fundamentadas. Observe cuándo el perfeccionismo, la autocrítica y la preocupación por los detalles comienzan a influir en una decisión práctica.","wellbeing":"Una pequeña pausa puede restablecer tu energía. Mejore lo que pueda y permita que el buen trabajo esté completo antes de que sea perfecto.","guidance":"Antes de que termine el día, recuerde: mejore lo que pueda y permita que el buen trabajo esté completo antes de que sea perfecto."}');
