INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'year', 'es-419', '{"overview":"Este año invita al crecimiento paciente en torno a la identidad, el propósito y la manera en que usas tu energía. Virgo se mueve a través de la energía de la tierra. El discernimiento y el servicio guían a la Virgen, convirtiendo la observación cuidadosa en mejora práctica.","love":"El amor se profundiza cuando practicas la coherencia y permites que la conexión evolucione a un ritmo humano. Sus dotes de análisis, destreza y servicio útil pueden ayudarlo a conectarse sin tener que actuar.","career":"El trabajo a largo plazo se fortalece cuando la ambición se combina con una estructura que se puede sostener. Utilice herramientas observadoras, prácticas, reflexivas y precisas, no expectativas que deba satisfacer todas a la vez.","finance":"Genere confianza financiera a través de hábitos repetibles en lugar de predicciones perfectas. Observe cuándo el perfeccionismo, la autocrítica y la preocupación por los detalles comienzan a influir en una decisión práctica.","wellbeing":"Trata el bienestar como una base para la vida que estás construyendo, no como una recompensa después de terminarla. Mejora lo que puedas y permite que el buen trabajo esté completo antes de que sea perfecto.","guidance":"Vuelve a esta brújula durante todo el año: mejora lo que puedas y permite que el buen trabajo esté completo antes de que sea perfecto."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('libra', 'es-419', '{"name":"Libra","dateRange":"23 de septiembre – 22 de octubre","rulingPlanet":"Venus","summary":"El equilibrio, la belleza y la reciprocidad guían la Balanza hacia elecciones que honran cada voz.","originStory":"La balanza de Libra la lleva Astraea, diosa de la justicia, y forma el único símbolo inanimado del zodíaco. Representan el juicio mesurado, la armonía social y el trabajo continuo para restaurar el equilibrio en lugar de suponer que ya existe.","traits":["Diplomático","imparcial","Encantador","Colaborativo"],"strengths":["Mediación","Perspectiva","Creando armonía"],"challenges":["Indecisión","complacer a la gente","Evitar el conflicto necesario"],"compatibleSigns":["Géminis","Acuario","León"],"reflectionPrompt":"Busca la justicia sin abandonar la verdad de tus propias necesidades."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'day', 'es-419', '{"overview":"Hoy favorece un paso claro e intencional. Libra se mueve a través de la energía del aire. El equilibrio, la belleza y la reciprocidad guían a la Balanza hacia elecciones que honran cada voz.","love":"En el amor hoy, elige la presencia sobre la suposición. Tus dones de mediación, perspectiva y creación de armonía pueden ayudarte a conectarte sin actuar.","career":"En el trabajo, complete la tarea más significativa antes de buscar un nuevo impulso. Utilice herramientas diplomáticas, imparciales, encantadoras y colaborativas, no expectativas que deba satisfacer todas a la vez.","finance":"Mantenga las decisiones monetarias de hoy simples y fundamentadas. Observe cuándo la indecisión, el agradar a la gente y el evitar el conflicto necesario comienzan a influir en una decisión práctica.","wellbeing":"Una pequeña pausa puede restablecer tu energía. Busque la justicia sin abandonar la verdad de sus propias necesidades.","guidance":"Antes de que termine el día, recuerda: busca la justicia sin abandonar la verdad de tus propias necesidades."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'week', 'es-419', '{"overview":"Esta semana se desarrolla a través de elecciones constantes más que de un momento dramático. Libra se mueve a través de la energía del aire. El equilibrio, la belleza y la reciprocidad guían a las Balanzas hacia decisiones que honran cada voz.","love":"Las relaciones se benefician de una conversación que deja espacio tanto para la honestidad como para la calidez. Tus dones de mediación, perspectiva y creación de armonía pueden ayudarte a conectarte sin actuar.","career":"Tu mejor progreso profesional proviene de elegir una prioridad y proteger tiempo para ella. Usa diplomático, justo, encantador, colaborador como herramientas, no como expectativas que debes cumplir todas a la vez.","finance":"Revise el patrón detrás de sus gastos antes de hacer un compromiso mayor. Observe cuándo la indecisión, el agradar a la gente y el evitar el conflicto necesario comienzan a influir en una decisión práctica.","wellbeing":"Equilibre el movimiento con una recuperación genuina durante toda la semana. Busque la justicia sin abandonar la verdad de sus propias necesidades.","guidance":"Deje que esta pregunta guíe la semana: busque la justicia sin abandonar la verdad de sus propias necesidades."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'year', 'es-419', '{"overview":"Este año invita al crecimiento paciente en torno a la identidad, el propósito y la manera en que usas tu energía. Libra se mueve a través de la energía del aire. El equilibrio, la belleza y la reciprocidad guían a la Balanza hacia decisiones que honran cada voz.","love":"El amor se profundiza cuando practicas la coherencia y permites que la conexión evolucione a un ritmo humano. Tus dones de mediación, perspectiva y creación de armonía pueden ayudarte a conectarte sin actuar.","career":"El trabajo a largo plazo se fortalece cuando la ambición se combina con una estructura que se puede sostener. Utilice herramientas diplomáticas, imparciales, encantadoras y colaborativas, no expectativas que deba satisfacer todas a la vez.","finance":"Genere confianza financiera a través de hábitos repetibles en lugar de predicciones perfectas. Observe cuándo la indecisión, el agradar a la gente y el evitar el conflicto necesario comienzan a influir en una decisión práctica.","wellbeing":"Trata el bienestar como una base para la vida que estás construyendo, no como una recompensa tras terminarla. Busca la justicia sin abandonar la verdad de tus propias necesidades.","guidance":"Vuelve a esta brújula durante todo el año: busca la justicia sin abandonar la verdad de tus propias necesidades."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('scorpio', 'es-419', '{"name":"Escorpio","dateRange":"23 de octubre – 21 de noviembre","rulingPlanet":"Plutón","summary":"La profundidad y la transformación definen al Escorpión, cuya perspicacia encuentra la verdad debajo de la superficie.","originStory":"Escorpio recuerda al escorpión enviado a enfrentar al cazador Orión después de que su orgullo perturbó el orden natural. Sus lugares opuestos en el cielo evocan límites, consecuencia, misterio y el poder regenerativo que se encuentra después de un final.","traits":["Intenso","Perceptivo","Leal","Ingenioso"],"strengths":["coraje emocional","Enfocar","Transformación"],"challenges":["Secretismo","Sospecha","guardar rencores"],"compatibleSigns":["Cáncer","Piscis","Virgo"],"reflectionPrompt":"Usa tu profundidad para transformar la verdad, no para esconderla."}');
