INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('sagittarius', 'es-419', '{"name":"Sagitario","dateRange":"22 de noviembre – 21 de diciembre","rulingPlanet":"Júpiter","summary":"El Arquero busca horizontes más amplios a través de la verdad, los viajes, el aprendizaje y el optimismo con propósito.","originStory":"Sagitario se asocia comúnmente con Quirón, el sabio centauro y maestro cuya flecha apunta más allá de lo familiar. La constelación simboliza la unión del instinto y la comprensión superior, siempre apuntando hacia un horizonte más significativo.","traits":["Aventurero","Optimista","Honesto","Filosófico"],"strengths":["Visión","Entusiasmo","Mente abierta"],"challenges":["Franqueza","demasiado prometedor","Escapar de la rutina"],"compatibleSigns":["Aries","León","Acuario"],"reflectionPrompt":"Apunta lejos, pero elige una dirección que tus acciones diarias puedan respaldar."}');
