INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('capricorn', 'es-419', '{"name":"Capricornio","dateRange":"22 de diciembre – 19 de enero","rulingPlanet":"Saturno","summary":"La disciplina y la visión de largo alcance ayudan a la Cabra Marina a escalar sin perder de vista las profundidades que se encuentran debajo.","originStory":"La cabra marina de Capricornio está asociada con Pan, quien se transformó parcialmente en pez mientras escapaba de Tifón. Su naturaleza montañosa y oceánica une la ambición con la supervivencia emocional, honrando la maestría ganada a través del tiempo y la responsabilidad.","traits":["Ambicioso","Disciplinado","Paciente","Responsable"],"strengths":["Resistencia","Estrategia","Confianza"],"challenges":["Rigidez","Pesimismo","Medir el valor a través de los logros"],"compatibleSigns":["Tauro","Virgo","Escorpio"],"reflectionPrompt":"Construya a largo plazo recordando que el descanso es parte de la estructura."}');
