INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aquarius', 'es-419', '{"name":"Acuario","dateRange":"20 de enero – 18 de febrero","rulingPlanet":"Urano","summary":"El pensamiento independiente y la visión colectiva guían al Portador de Agua para verter nuevas ideas en el mundo.","originStory":"Acuario está vinculado a Ganímedes, el copero cuya vasija llevaba agua a los dioses y, simbólicamente, conocimiento a la humanidad. Aunque su imagen lleva agua, el signo pertenece al aire: ideas, sistemas y renovación compartidos para el bien común.","traits":["Original","Independiente","Humanitario","Inventivo"],"strengths":["Innovación","Objetividad","Visión comunitaria"],"challenges":["Desapego","Hábitos contrarios","Opiniones fijas"],"compatibleSigns":["Géminis","Libra","Sagitario"],"reflectionPrompt":"Deje que su diferencia sirva de conexión en lugar de distancia."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'day', 'es-419', '{"overview":"Hoy favorece un paso claro e intencional. Acuario se mueve a través de la energía del aire. El pensamiento independiente y la visión colectiva guían al Portador de Agua para verter nuevas ideas en el mundo.","love":"En el amor hoy, elige la presencia sobre la suposición. Sus dones de innovación, objetividad y visión comunitaria pueden ayudarlo a conectarse sin actuar.","career":"En el trabajo, complete la tarea más significativa antes de buscar un nuevo impulso. Utilice herramientas originales, independientes, humanitarias e inventivas, no expectativas que deba satisfacer todas a la vez.","finance":"Mantenga las decisiones monetarias de hoy simples y fundamentadas. Observe cuándo el desapego, los hábitos contrarios y las opiniones fijas comienzan a influir en una decisión práctica.","wellbeing":"Una pequeña pausa puede restablecer tu energía. Deje que su diferencia sirva de conexión en lugar de distancia.","guidance":"Antes de que termine el día, recuerda: deja que tu diferencia sirva de conexión en lugar de distancia."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'week', 'es-419', '{"overview":"Esta semana se desarrolla a través de elecciones constantes más que en un momento dramático. Acuario se mueve a través de la energía del aire. El pensamiento independiente y la visión colectiva guían al Portador de Agua para derramar nuevas ideas en el mundo.","love":"Las relaciones se benefician de una conversación que deja espacio tanto para la honestidad como para la calidez. Sus dones de innovación, objetividad y visión comunitaria pueden ayudarlo a conectarse sin actuar.","career":"Tu mejor progreso profesional proviene de elegir una prioridad y proteger tiempo para ella. Usa original, independiente, humanitario, inventivo como herramientas, no como expectativas que debas cumplir todas a la vez.","finance":"Revise el patrón detrás de sus gastos antes de hacer un compromiso mayor. Observe cuándo el desapego, los hábitos contrarios y las opiniones fijas comienzan a influir en una decisión práctica.","wellbeing":"Equilibre el movimiento con una recuperación genuina durante toda la semana. Deje que su diferencia sirva de conexión en lugar de distancia.","guidance":"Deje que esta pregunta guíe la semana: deje que su diferencia sirva para la conexión en lugar de la distancia."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'year', 'es-419', '{"overview":"Este año invita a un crecimiento paciente en torno a la identidad, el propósito y la manera en que usas tu energía. Acuario se mueve a través de la energía del aire. El pensamiento independiente y la visión colectiva guían al Portador de Agua para derramar nuevas ideas en el mundo.","love":"El amor se profundiza cuando practicas la coherencia y permites que la conexión evolucione a un ritmo humano. Sus dones de innovación, objetividad y visión comunitaria pueden ayudarlo a conectarse sin actuar.","career":"El trabajo a largo plazo se fortalece cuando la ambición se combina con una estructura que se puede sostener. Utilice herramientas originales, independientes, humanitarias e inventivas, no expectativas que deba satisfacer todas a la vez.","finance":"Genere confianza financiera a través de hábitos repetibles en lugar de predicciones perfectas. Observe cuándo el desapego, los hábitos contrarios y las opiniones fijas comienzan a influir en una decisión práctica.","wellbeing":"Trata el bienestar como una base para la vida que estás construyendo, no como una recompensa después de terminarla. Deja que tu diferencia sirva para la conexión en lugar de la distancia.","guidance":"Vuelve a esta brújula durante todo el año: deja que tu diferencia sirva de conexión más que de distancia."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('pisces', 'es-419', '{"name":"Piscis","dateRange":"19 de febrero – 20 de marzo","rulingPlanet":"Neptuno","summary":"La compasión y la imaginación guían a los Peces entre la intuición, los sueños y los sentimientos compartidos.","originStory":"Piscis recuerda que Afrodita y Eros se convirtieron en peces y se ataron para escapar de Tifón. El vínculo entre los dos peces representa devoción, identidad fluida, sensibilidad espiritual y búsqueda de unidad mientras se avanza a través de corrientes cambiantes.","traits":["Compasivo","Imaginativo","Intuitivo","Amable"],"strengths":["Empatía","Creatividad","Percepción espiritual"],"challenges":["Evasión","Límites borrosos","Absorber las emociones de los demás"],"compatibleSigns":["Cáncer","Escorpio","Capricornio"],"reflectionPrompt":"Honra tu sensibilidad con límites lo suficientemente fuertes como para protegerla."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'day', 'es-419', '{"overview":"Hoy favorece un paso claro e intencional. Piscis se mueve a través de la energía del agua. La compasión y la imaginación guían a los Peces entre la intuición, los sueños y el sentimiento compartido.","love":"En el amor hoy, elige la presencia sobre la suposición. Tus dones de empatía, creatividad y perspicacia espiritual pueden ayudarte a conectarte sin actuar.","career":"En el trabajo, complete la tarea más significativa antes de buscar un nuevo impulso. Utilice herramientas compasivas, imaginativas, intuitivas y amables, no expectativas que deba satisfacer todas a la vez.","finance":"Mantenga las decisiones monetarias de hoy simples y fundamentadas. Observe cuándo el escapismo, los límites borrosos y la absorción de las emociones de los demás comienzan a influir en una decisión práctica.","wellbeing":"Una pequeña pausa puede restablecer tu energía. Honra tu sensibilidad con límites lo suficientemente fuertes como para protegerla.","guidance":"Antes de que termine el día, recuerda: honra tu sensibilidad con límites lo suficientemente fuertes como para protegerla."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'week', 'es-419', '{"overview":"Esta semana se desarrolla a través de decisiones constantes en lugar de un momento dramático. Piscis se mueve a través de la energía del agua. La compasión y la imaginación guían a los Peces entre la intuición, los sueños y los sentimientos compartidos.","love":"Las relaciones se benefician de una conversación que deja espacio tanto para la honestidad como para la calidez. Tus dones de empatía, creatividad y perspicacia espiritual pueden ayudarte a conectarte sin actuar.","career":"Tu mejor progreso profesional proviene de elegir una prioridad y proteger tiempo para ella. Usa compasivo, imaginativo, intuitivo, gentil como herramientas, no como expectativas que debes cumplir todas a la vez.","finance":"Revise el patrón detrás de sus gastos antes de hacer un compromiso mayor. Observe cuándo el escapismo, los límites borrosos y la absorción de las emociones de los demás comienzan a influir en una decisión práctica.","wellbeing":"Equilibre el movimiento con una recuperación genuina durante toda la semana. Honra tu sensibilidad con límites lo suficientemente fuertes como para protegerla.","guidance":"Deje que esta pregunta guíe la semana: Honre su sensibilidad con límites lo suficientemente fuertes como para protegerla."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'year', 'es-419', '{"overview":"Este año invita a un crecimiento paciente en torno a la identidad, el propósito y la manera en que usas tu energía. Piscis se mueve a través de la energía del agua. La compasión y la imaginación guían a los Peces entre la intuición, los sueños y el sentimiento compartido.","love":"El amor se profundiza cuando practicas la coherencia y permites que la conexión evolucione a un ritmo humano. Tus dones de empatía, creatividad y perspicacia espiritual pueden ayudarte a conectarte sin actuar.","career":"El trabajo a largo plazo se fortalece cuando la ambición se combina con una estructura que se puede sostener. Utilice herramientas compasivas, imaginativas, intuitivas y amables, no expectativas que deba satisfacer todas a la vez.","finance":"Genere confianza financiera a través de hábitos repetibles en lugar de predicciones perfectas. Observe cuándo el escapismo, los límites borrosos y la absorción de las emociones de los demás comienzan a influir en una decisión práctica.","wellbeing":"Trata el bienestar como una base para la vida que estás construyendo, no como una recompensa después de terminarla. Honra tu sensibilidad con límites lo suficientemente fuertes como para protegerla.","guidance":"Vuelve a esta brújula durante todo el año: Honra tu sensibilidad con límites lo suficientemente fuertes como para protegerla."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('fool', 'pt-BR', '{"name":"O Louco","meaning":"Uma página em branco e um salto de fé — uma nova jornada começa com o coração aberto.","advice":"Confie no caminho à sua frente e dê o primeiro passo, mesmo sem todas as respostas.","yesNoMeaning":"Um novo começo raramente traz uma resposta fixa — o resultado depende do passo que você dá."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('magician', 'pt-BR', '{"name":"O Mágico","meaning":"Você possui todas as ferramentas de que precisa. Foque sua vontade e transforme intenção em ação.","advice":"Use suas habilidades e recursos deliberadamente — agora é o momento de fazer acontecer.","yesNoMeaning":"Você já possui tudo o que é necessário — a energia apoia avançar com foco."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('high-priestess', 'pt-BR', '{"name":"A Sacerdotisa","meaning":"Sabedoria silenciosa se esconde abaixo da superfície. Ouça sua intuição e voz interior.","advice":"Faça uma pausa, volte-se para dentro e deixe seus instintos guiarem você antes de agir.","yesNoMeaning":"A resposta está escondida abaixo da superfície por enquanto — confie na sua intuição em vez de forçar um sim ou não claro."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('empress', 'pt-BR', '{"name":"A Imperatriz","meaning":"Crescimento, abundância e energia de cuidado estão ao seu redor. Deixe a beleza e a atenção florescerem.","advice":"Seja paciente e generoso — crie com amor e deixe as coisas amadurecerem naturalmente.","yesNoMeaning":"Crescimento, abundância e energia de cuidado apoiam seu desejo — a resposta é um sim silencioso."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('emperor', 'pt-BR', '{"name":"O Imperador","meaning":"Estrutura, autoridade e liderança constante. Construa sobre terreno sólido com disciplina.","advice":"Assuma o controle com um plano claro; limites firmes trazem estabilidade duradoura.","yesNoMeaning":"Estrutura, autoridade e disciplina constante estão por trás de um sim confiante."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hierophant', 'pt-BR', '{"name":"O Hierofante","meaning":"Tradição e orientação confiável oferecem um caminho seguro. Aprenda com o que veio antes.","advice":"Siga a sabedoria estabelecida e busque conselho daqueles em quem você confia.","yesNoMeaning":"Tradição e orientação confiável apontam para um sim confiável — apoie-se no que já se provou."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('lovers', 'pt-BR', '{"name":"Os Amantes","meaning":"Um vínculo significativo ou uma escolha importante. Siga o que seu coração realmente valoriza.","advice":"Escolha com honestidade e alinhamento — a conexão se aprofunda quando você é sincero.","yesNoMeaning":"Seu coração e valores estão alinhados aqui — a resposta é sim, especialmente quando você escolhe com honestidade."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('chariot', 'pt-BR', '{"name":"O Carro","meaning":"Força de vontade e impulso te carregam adiante. Mantenha o foco e você prevalecerá.","advice":"Mantenha seus olhos no objetivo e conduza com confiança através de cada obstáculo.","yesNoMeaning":"Força de vontade e impulso estão ao seu lado — um sim focado, desde que você permaneça comprometido."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('strength', 'pt-BR', '{"name":"Força","meaning":"O verdadeiro poder é gentil — paciência, coragem e compaixão dominam qualquer desafio.","advice":"Lidere com força tranquila; uma mão suave é frequentemente a mais forte.","yesNoMeaning":"Coragem gentil e resolução paciente fazem deste um sim — conduza com calma, não com força."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hermit', 'pt-BR', '{"name":"O Eremita","meaning":"Hora de dar um passo atrás e buscar clareza interior. A solidão agora traz respostas mais profundas.","advice":"Volte-se para dentro, reflita e deixe o silêncio revelar o que você realmente precisa.","yesNoMeaning":"Ainda não — a carta pede que você dê um passo atrás e encontre clareza interior antes de agir."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('wheel-of-fortune', 'pt-BR', '{"name":"Roda da Fortuna","meaning":"A sorte muda e os ciclos se alteram. O que muda agora faz parte de um ritmo maior.","advice":"Siga a maré com flexibilidade — abrace a mudança, seja ela boa ou não.","yesNoMeaning":"A sorte está mudando — o resultado depende de como você lida com a mudança, em vez de um sim ou não fixo."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('justice', 'pt-BR', '{"name":"Justiça","meaning":"Verdade e justiça prevalecem. Causa e efeito agora entram em equilíbrio.","advice":"Aja com honestidade e pese ambos os lados; a balança se equilibrará de forma justa.","yesNoMeaning":"As balanças ainda estão pesando — a resposta justa depende dos fatos e da sua honestidade."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hanged-man', 'pt-BR', '{"name":"O Enforcado","meaning":"Uma pausa necessária. Liberte o controle e veja a situação de um novo ângulo.","advice":"Pare de insistir — entregue-se ao momento e deixe uma nova perspectiva chegar.","yesNoMeaning":"Pausa é necessária primeiro — forçar isso agora só atrasaria uma resposta mais clara."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('death', 'pt-BR', '{"name":"Morte","meaning":"Um fim abre caminho para a renovação. Liberte o que já cumpriu seu tempo.","advice":"Deixe ir sem arrependimentos; uma transformação profunda está abrindo uma nova porta.","yesNoMeaning":"Um fim está abrindo caminho — o caminho atual está se fechando para que um novo possa começar."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('temperance', 'pt-BR', '{"name":"Temperança","meaning":"Equilíbrio e paciência trazem harmonia. Misture opostos com graça.","advice":"Mova-se com moderação e mantenha a calma — passos firmes alcançam o destino.","yesNoMeaning":"Equilíbrio e paciência trazem harmonia — um sim ponderado, dado um passo firme de cada vez."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('devil', 'pt-BR', '{"name":"O Diabo","meaning":"Cuidado com apego, tentação ou um padrão restritivo. Reconheça as correntes.","advice":"Nomeie o que te mantém preso e recupere sua liberdade — a corrente só prende se você permitir.","yesNoMeaning":"O apego ou um padrão vinculativo impede — ainda não, até que a corrente seja nomeada e quebrada."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('tower', 'pt-BR', '{"name":"A Torre","meaning":"A mudança súbita destrói o falso e revela a verdade. O que cai nunca foi feito para permanecer.","advice":"Aceite a turbulência; dos escombros pode-se construir uma base mais clara.","yesNoMeaning":"A mudança súbita está destruindo o antigo — o terreno deve se acomodar antes que um sim firme seja possível."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('star', 'pt-BR', '{"name":"A Estrela","meaning":"Esperança, cura e inspiração tranquila renovam seu espírito após a tempestade.","advice":"Confie na luz à frente e continue acreditando — seus desejos estão ao alcance.","yesNoMeaning":"Esperança e renovação tranquila apontam para o sim — confie na luz à frente e mantenha seu desejo vivo."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('moon', 'pt-BR', '{"name":"A Lua","meaning":"Ilusão e incerteza confundem o caminho. Confie na sua intuição, não nas aparências.","advice":"Desacelere e olhe mais fundo; a clareza virá quando a névoa se dissipar.","yesNoMeaning":"Ilusão e incerteza confundem o caminho — a resposta não é clara até você olhar além das aparências."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('sun', 'pt-BR', '{"name":"O Sol","meaning":"Alegria, sucesso e clareza radiante. Tudo está brilhante e cheio de vida.","advice":"Celebre e brilhe — a energia positiva atrai os resultados que você deseja.","yesNoMeaning":"Alegria e clareza radiante confirmam um sim brilhante — tudo está funcionando a seu favor."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('judgement', 'pt-BR', '{"name":"Julgamento","meaning":"Um chamado para se erguer, se renovar e ser honesto consigo mesmo. Um veredito de despertar.","advice":"Responda ao chamado com coragem; perdoe o passado e entre no seu próximo capítulo.","yesNoMeaning":"Um chamado para se erguer e se renovar — sim, especialmente quando você perdoa o passado e responde honestamente."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('world', 'pt-BR', '{"name":"O Mundo","meaning":"Conclusão e realização — um ciclo se fecha em total plenitude.","advice":"Celebre o que você conquistou; a porta está aberta para um mundo mais amplo.","yesNoMeaning":"Conclusão e plenitude marcam este como um sim realizado — o ciclo se fecha a seu favor."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-wands', 'pt-BR', '{"name":"Ás de Paus","meaning":"Uma faísca de inspiração abre um caminho criativo ousado.","advice":"Comece enquanto a energia está fresca e dê à ideia um verdadeiro primeiro passo.","yesNoMeaning":"O Ás de Paus aponta sim: comece enquanto a energia está fresca e dê à ideia um primeiro passo real."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-wands', 'pt-BR', '{"name":"Dois de Paus","meaning":"Um futuro está se formando através do planejamento e da escolha de um direcionamento.","advice":"Olhe além do que é familiar, então comprometa-se com o caminho com espaço para crescer.","yesNoMeaning":"O Dois de Paus permanece condicional: olhe além do que é familiar, então comprometa-se com o caminho deixando espaço para crescer."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-wands', 'pt-BR', '{"name":"Três de Paus","meaning":"O esforço inicial se expande à medida que oportunidades e horizontes mais amplos surgem.","advice":"Continue construindo e esteja pronto para receber a resposta que seu trabalho atrai.","yesNoMeaning":"O Três de Paus inclina-se para o sim: continue construindo e esteja pronto para receber a resposta que seu trabalho atrai."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-wands', 'pt-BR', '{"name":"Quatro de Paus","meaning":"Estabilidade, boas-vindas e celebração compartilhada criam uma base sólida.","advice":"Marque o marco e permita que pessoas de apoio compartilhem deste momento.","yesNoMeaning":"O Quatro de Paus inclina-se para sim: marque o marco e deixe que pessoas apoiadoras compartilhem disso."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-wands', 'pt-BR', '{"name":"Cinco de Paus","meaning":"Objetivos concorrentes criam atrito, ruído ou um teste de confiança.","advice":"Transforme a rivalidade em prática útil e recuse conflitos que não têm propósito.","yesNoMeaning":"O Cinco de Paus permanece condicional: transforme a rivalidade em prática útil e recuse conflitos que não têm propósito."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-wands', 'pt-BR', '{"name":"Seis de Varinhas","meaning":"O reconhecimento segue o esforço determinado e o progresso visível.","advice":"Aceite o incentivo, mas mantenha sua confiança vinculada ao trabalho honesto.","yesNoMeaning":"O Seis de Paus tende para sim: aceite o incentivo, mas mantenha sua confiança vinculada ao trabalho honesto."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-wands', 'pt-BR', '{"name":"Sete de Paus","meaning":"Você mantém um terreno valioso enquanto a pressão testa sua determinação.","advice":"Defenda o que importa com limites claros em vez de lutar contra todos os desafios.","yesNoMeaning":"O Sete de Paus tende para sim: defenda o que importa com limites claros em vez de lutar contra todos os desafios."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-wands', 'pt-BR', '{"name":"Oito de Paus","meaning":"Os eventos se aceleram, mensagens chegam e o impulso elimina o atraso.","advice":"Aja prontamente e mantenha a comunicação direta enquanto o caminho estiver aberto.","yesNoMeaning":"O Oito de Paus aponta sim: aja prontamente e mantenha a comunicação direta enquanto o caminho estiver aberto."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-wands', 'pt-BR', '{"name":"Nove de Paus","meaning":"A resiliência é forte, embora tensões passadas façam você ficar atento.","advice":"Proteja sua energia e dê o próximo passo sem esperar que toda ferida se repita.","yesNoMeaning":"O Nove de Paus permanece condicional: proteja sua energia e dê o próximo passo sem esperar que cada ferida se repita."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-wands', 'pt-BR', '{"name":"Dez de Paus","meaning":"A responsabilidade se tornou pesada e o sucesso agora carrega um fardo.","advice":"Delegue, simplifique e deixe de lado trabalhos que não são mais realmente seus.","yesNoMeaning":"O Dez de Paus tende para não: delegue, simplifique e largue o trabalho que não é mais verdadeiramente seu."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-wands', 'pt-BR', '{"name":"Pajem de Paus","meaning":"A curiosidade traz uma mensagem animada, experimento ou novo interesse criativo.","advice":"Explore com coragem e deixe que a energia de iniciante o ensine por meio da ação.","yesNoMeaning":"O Pajem de Paus tende ao sim: explore com coragem e deixe que a energia de iniciante ensine você por meio da ação."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-wands', 'pt-BR', '{"name":"Cavaleiro de Paus","meaning":"A paixão avança rapidamente, trazendo aventura e possível impaciência.","advice":"Use o momentum, mas escolha uma direção antes que a velocidade disperse seu esforço.","yesNoMeaning":"O Cavaleiro de Paus permanece condicional: use o impulso, mas escolha uma direção antes que a velocidade disperse seu esforço."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-wands', 'pt-BR', '{"name":"Rainha de Paus","meaning":"Confiança calorosa e independência criativa atraem os outros para a sua visão.","advice":"Confie em sua presença, incentive os outros e não diminua sua ambição.","yesNoMeaning":"A Rainha de Paus tende para sim: confie na sua presença, encoraje os outros e não diminua sua ambição."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-wands', 'pt-BR', '{"name":"Rei de Paus","meaning":"Visão madura transforma inspiração em liderança decisiva e ética.","advice":"Lidere a partir de um propósito maior e dê aos outros espaço para contribuir.","yesNoMeaning":"O Rei de Paus inclina-se para sim: lidere a partir de um propósito maior e dê aos outros espaço para contribuir."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-cups', 'pt-BR', '{"name":"Ás de Copas","meaning":"O coração se abre para novo afeto, compaixão e renovação emocional.","advice":"Receba o sentimento honestamente e deixe o cuidado fluir sem forçar um resultado.","yesNoMeaning":"O Ás de Copas indica sim: receba o sentimento honestamente e deixe o cuidado fluir sem forçar um resultado."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-cups', 'pt-BR', '{"name":"Dois de Copas","meaning":"O reconhecimento mútuo cria parceria, atração ou acordo sincero.","advice":"Encontre a outra pessoa como igual e fale com o coração.","yesNoMeaning":"O Dois de Copas inclina-se sim: encontre a outra pessoa como igual e fale do coração."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-cups', 'pt-BR', '{"name":"Três de Copas","meaning":"Amizade, comunidade e alegria compartilhada trazem apoio emocional.","advice":"Celebre junto e lembre-se de quem realmente aparece para você.","yesNoMeaning":"O Três de Copas tende para sim: celebre junto e lembre-se de quem realmente está presente para você."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-cups', 'pt-BR', '{"name":"Quatro de Copas","meaning":"Retirada emocional torna difícil perceber um presente disponível.","advice":"Pause a comparação e olhe novamente para o que está sendo oferecido silenciosamente.","yesNoMeaning":"O Quatro de Copas inclina-se para não: pause a comparação e olhe novamente para o que está sendo oferecido silenciosamente."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-cups', 'pt-BR', '{"name":"Cinco de Copas","meaning":"A perda chama atenção para o que derramou enquanto algo significativo permanece.","advice":"Honre a decepção, depois volte-se para o apoio que ainda está presente.","yesNoMeaning":"O Cinco de Copas inclina-se para não: honre a decepção, depois volte-se para o apoio que ainda está presente."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-cups', 'pt-BR', '{"name":"Seis de Copas","meaning":"Memória, inocência ou um vínculo familiar retorna com um calor suave.","advice":"Receba a bondade do passado sem fingir que você deve viver lá novamente.","yesNoMeaning":"O Seis de Copas tende para sim: receba a bondade do passado sem fingir que precisa viver lá de novo."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-cups', 'pt-BR', '{"name":"Sete de Copas","meaning":"Muitas possibilidades atraentes confundem a diferença entre visão e ilusão.","advice":"Reduza as escolhas e teste um sonho contra a realidade antes de se comprometer.","yesNoMeaning":"O Sete de Copas ainda não está claro: restrinja as escolhas e teste um sonho contra a realidade antes de se comprometer."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-cups', 'pt-BR', '{"name":"Oito de Copas","meaning":"Uma situação outrora significativa não nutre mais o coração.","advice":"Saia com honestidade e siga em direção à realização mais profunda que você agora precisa.","yesNoMeaning":"O Oito de Copas aponta não: saia com honestidade e mova-se em direção à realização mais profunda que você agora precisa."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-cups', 'pt-BR', '{"name":"Nove de Copas","meaning":"Satisfação e gratidão fazem um desejo sincero parecer próximo.","advice":"Aproveite o que está aqui e pergunte se o desejo também serve aos seus valores mais profundos.","yesNoMeaning":"O Nove de Copas inclina-se para sim: aproveite o que está aqui e pergunte se o desejo também serve aos seus valores mais profundos."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-cups', 'pt-BR', '{"name":"Dez de Copas","meaning":"Harmonia emocional, pertencimento e conexão duradoura cercam o lar.","advice":"Nutra os laços que tornam a alegria sustentável e compartilhada.","yesNoMeaning":"O Dez de Copas tende para sim: nutra os laços que tornam a alegria sustentável e compartilhada."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-cups', 'pt-BR', '{"name":"Pajem de Copas","meaning":"Uma mensagem carinhosa ou descoberta intuitiva convida à abertura emocional.","advice":"Fique curioso sobre o sentimento e responda com sinceridade, em vez de suposições.","yesNoMeaning":"O Pajem de Copas permanece condicional: mantenha-se curioso sobre o sentimento e responda com sinceridade em vez de presunção."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-cups', 'pt-BR', '{"name":"Cavaleiro de Copas","meaning":"O romance, a imaginação ou um ideal movimenta o coração para frente.","advice":"Siga o convite, mas mantenha um pé no chão enquanto as promessas se desenrolam.","yesNoMeaning":"O Cavaleiro de Copas inclina-se para sim: siga o convite, mas mantenha um pé no chão enquanto as promessas se desenrolam."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-cups', 'pt-BR', '{"name":"Rainha de Copas","meaning":"Empatia profunda e intuição criam um espaço calmo para a verdade.","advice":"Ouça com compaixão enquanto mantém os limites que mantêm o cuidado saudável.","yesNoMeaning":"A Rainha de Copas tende ao sim: escute com compaixão enquanto preserva os limites que mantêm o cuidado saudável."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-cups', 'pt-BR', '{"name":"Rei de Copas","meaning":"Maturidade emocional estabiliza fortes sentimentos sem suprimi-los.","advice":"Responda com compaixão e autocontrole, especialmente quando os outros estiverem reativos.","yesNoMeaning":"O Rei de Copas inclina-se para sim: responda com compaixão e autocontrole, especialmente quando os outros estão reativos."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-swords', 'pt-BR', '{"name":"Ás de Espadas","meaning":"Uma percepção clara atravessa a confusão e revela uma nova verdade.","advice":"Nomeie o problema claramente e use a clareza a serviço de uma decisão justa.","yesNoMeaning":"O Ás de Espadas aponta sim: nomeie a questão claramente e use a clareza a serviço de uma decisão justa."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-swords', 'pt-BR', '{"name":"Dois de Espadas","meaning":"Um impasse cauteloso atrasa uma escolha que não pode permanecer suspensa para sempre.","advice":"Remova a venda suavemente, reúna o fato faltante e decida a partir do equilíbrio.","yesNoMeaning":"O Dois de Espadas ainda não está claro: remova a venda suavemente, reúna o fato que falta e decida a partir do equilíbrio."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-swords', 'pt-BR', '{"name":"Três de Espadas","meaning":"Uma verdade dolorosa, separação ou decepção pede para ser reconhecida.","advice":"Deixe o sentimento percorrer você e evite transformar a dor em uma história permanente.","yesNoMeaning":"O Três de Espadas inclina-se para não: deixe o sentimento passar por você e evite transformar a dor em uma história permanente."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-swords', 'pt-BR', '{"name":"Quatro de Espadas","meaning":"Descanso e tranquilidade mental são necessários após pressão ou conflito.","advice":"Pausa antes de responder; a recuperação é produtiva quando restaura o pensamento claro.","yesNoMeaning":"O Quatro de Espadas inclina-se para não: pause antes de responder; a recuperação é produtiva quando restaura o pensamento claro."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-swords', 'pt-BR', '{"name":"Cinco de Espadas","meaning":"Conflito pode produzir uma vitória vazia ou deixar a confiança abalada.","advice":"Escolha a dignidade em vez de vencer e afaste-se de táticas que custam muito.","yesNoMeaning":"O Cinco de Espadas inclina-se para não: escolha dignidade em vez de vencer e afaste-se de táticas que custam demais."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-swords', 'pt-BR', '{"name":"Seis de Espadas","meaning":"Uma passagem difícil avança gradualmente em direção a condições mais calmas.","advice":"Pegue o que você aprendeu, aceite apoio e continue se afastando da turbulência.","yesNoMeaning":"O Seis de Espadas tende para sim: leve o que você aprendeu, aceite apoio e continue se afastando da turbulência."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-swords', 'pt-BR', '{"name":"Sete de Espadas","meaning":"Estratégia, segredo ou evasão complicam o caminho.","advice":"Aja com inteligência, mas de forma transparente; atalhos que traem a confiança voltarão como problemas.","yesNoMeaning":"O Sete de Espadas tende para não: aja de forma inteligente, mas transparente; atalhos que traem a confiança voltarão como problemas."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-swords', 'pt-BR', '{"name":"Oito de Espadas","meaning":"O medo e crenças restritivas tornam difícil ver as opções disponíveis.","advice":"Questione o pensamento que diz que você está preso e tome uma pequena ação libertadora.","yesNoMeaning":"O Oito de Espadas aponta não: questione o pensamento que diz que você está preso e tome uma pequena ação libertadora."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-swords', 'pt-BR', '{"name":"Nove de Espadas","meaning":"A ansiedade amplia o perigo no escuro e exaure a mente.","advice":"Traga o medo para a luz do dia, busque apoio e separe fatos de resultados imaginados.","yesNoMeaning":"O Nove de Espadas inclina-se para não: traga o medo à luz do dia, busque apoio e separe os fatos dos resultados imaginados."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-swords', 'pt-BR', '{"name":"Dez de Espadas","meaning":"Um ciclo doloroso chega ao seu limite final e não pode continuar sem mudanças.","advice":"Aceite o fim, proteja sua recuperação e permita que um novo começo surja.","yesNoMeaning":"O Dez de Espadas tende para não: aceite o fim, proteja sua recuperação e permita que um novo começo surja."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-swords', 'pt-BR', '{"name":"Pajem de Espadas","meaning":"Alerta a curiosidade busca fatos, faz perguntas e observa mudanças.","advice":"Pesquise cuidadosamente e fale com precisão em vez de reagir a cada sinal.","yesNoMeaning":"O Pajem de Espadas permanece condicional: pesquise cuidadosamente e fale com precisão, em vez de reagir a todo sinal."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-swords', 'pt-BR', '{"name":"Cavaleiro de Espadas","meaning":"O intelecto focado se move rapidamente e enfrenta obstáculos diretamente.","advice":"Avance com coragem, mas devagar o suficiente para ouvir o que sua certeza pode estar perdendo.","yesNoMeaning":"O Cavaleiro de Espadas permanece condicional: avance com coragem, mas devagar o suficiente para ouvir o que sua certeza pode estar perdendo."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-swords', 'pt-BR', '{"name":"Rainha de Espadas","meaning":"Percepção clara e limites honestos cortam a confusão.","advice":"Diga o que é verdade com compaixão e deixe que a experiência te refine, não te endureça.","yesNoMeaning":"A Rainha de Espadas tende ao sim: diga o que é verdadeiro com compaixão e deixe que a experiência te refine, não endureça."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-swords', 'pt-BR', '{"name":"Rei de Espadas","meaning":"Razão, justiça e julgamento disciplinado guiam uma decisão consequencial.","advice":"Use evidências, defina o padrão e mantenha o viés pessoal fora do veredicto.","yesNoMeaning":"O Rei de Espadas inclina-se para sim: use evidências, defina o padrão e mantenha o viés pessoal fora do veredicto."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-pentacles', 'pt-BR', '{"name":"Ás de Ouros","meaning":"Uma oportunidade tangível oferece a semente da prosperidade, trabalho ou bem-estar.","advice":"Baseie a oportunidade em um plano prático e cuide dela de forma consistente.","yesNoMeaning":"O Ás de Ouros indica sim: concretize a oportunidade em um plano prático e cuide dela de forma consistente."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-pentacles', 'pt-BR', '{"name":"Dois de Ouros","meaning":"Várias prioridades se movem ao mesmo tempo e exigem equilíbrio flexível.","advice":"Ajuste o ritmo, proteja o essencial e evite prometer mais do que você pode carregar.","yesNoMeaning":"O Dois de Ouros permanece condicional: ajuste o ritmo, proteja o essencial e evite prometer mais do que pode carregar."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-pentacles', 'pt-BR', '{"name":"Três de Ouros","meaning":"A habilidade cresce por meio da colaboração, feedback e um trabalho artesanal cuidadoso.","advice":"Contribua com sua força, respeite a expertise e construa um padrão compartilhado.","yesNoMeaning":"O Três de Ouros inclina-se para sim: contribua com sua força, respeite a experiência e construa de acordo com um padrão compartilhado."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-pentacles', 'pt-BR', '{"name":"Quatro de Ouros","meaning":"Apegar-se fortemente à segurança pode preservar recursos, mas restringe o fluxo saudável.","advice":"Proteja o que importa sem deixar que o medo tome todas as suas decisões.","yesNoMeaning":"O Quatro de Ouros permanece condicional: proteja o que importa sem deixar que o medo tome todas as suas decisões."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-pentacles', 'pt-BR', '{"name":"Cinco de Ouros","meaning":"Tensão ou exclusão material cria preocupação e sensação de escassez.","advice":"Peça ajuda prática e perceba a porta que a dificuldade tornou fácil de ser ignorada.","yesNoMeaning":"O Cinco de Ouros inclina-se para não: peça ajuda prática e perceba a porta que a dificuldade tornou fácil de ignorar."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-pentacles', 'pt-BR', '{"name":"Seis de Pentáculos","meaning":"Recursos são trocados, levantando questões de generosidade, poder e justiça.","advice":"Dar ou receber com termos claros para que o apoio preserve a dignidade de ambos os lados.","yesNoMeaning":"O Seis de Ouros tende para sim: dê ou receba com termos claros para que o apoio preserve a dignidade de ambos os lados."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-pentacles', 'pt-BR', '{"name":"Sete de Ouros","meaning":"Investimento paciente chega a um ponto de avaliação antes do próximo esforço.","advice":"Revise o que está crescendo, melhore o método e dê tempo para resultados valiosos.","yesNoMeaning":"O Sete de Ouros permanece condicional: reveja o que está crescendo, melhore o método e dê tempo para resultados que valham a pena."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-pentacles', 'pt-BR', '{"name":"Oito de Ouros","meaning":"A repetição focada desenvolve domínio e resultados confiáveis.","advice":"Pratique a habilidade essencial, aceite correções e deixe a qualidade se acumular.","yesNoMeaning":"O Oito de Ouros aponta sim: pratique a habilidade essencial, aceite correções e deixe a qualidade se acumular."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-pentacles', 'pt-BR', '{"name":"Nove de Ouros","meaning":"Autossuficiência e conforto cultivado refletem progresso disciplinado.","advice":"Aproveite o que você construiu e mantenha a independência conectada à gratidão.","yesNoMeaning":"O Nove de Ouros inclina-se para sim: aproveite o que você construiu e mantenha a independência conectada à gratidão."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-pentacles', 'pt-BR', '{"name":"Dez de Ouros","meaning":"A segurança a longo prazo cresce através de legados, família e fundamentos compartilhados.","advice":"Planeje além da vitória imediata e proteja o que pode apoiar os outros ao longo do tempo.","yesNoMeaning":"O Dez de Ouros tende para sim: planeje além da vitória imediata e proteja o que pode apoiar outros ao longo do tempo."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-pentacles', 'pt-BR', '{"name":"Pajem de Ouros","meaning":"Uma mensagem prática convida ao estudo, planejamento ou a um novo empreendimento fundamentado.","advice":"Aprenda o básico, defina a próxima tarefa e prove a ideia através de trabalho constante.","yesNoMeaning":"O Pajem de Ouros tende ao sim: aprenda o básico, defina a próxima tarefa e comprove a ideia por meio de trabalho constante."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-pentacles', 'pt-BR', '{"name":"Cavaleiro de Ouros","meaning":"O esforço confiável avança lentamente, mas raramente abandona a tarefa.","advice":"Mantenha a rotina honesta e consistente; progresso importa mais do que entusiasmo.","yesNoMeaning":"O Cavaleiro de Ouros inclina-se para sim: mantenha a rotina honesta e consistente; o progresso importa mais do que a empolgação."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-pentacles', 'pt-BR', '{"name":"Rainha de Ouros","meaning":"O cuidado engenhoso cria conforto, saúde e abundância prática.","advice":"Nutra pessoas e planos de maneiras que permaneçam sustentáveis para você.","yesNoMeaning":"A Rainha de Ouros tende ao sim: cuide de pessoas e planos de maneiras que permaneçam sustentáveis para você."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-pentacles', 'pt-BR', '{"name":"Rei de Ouros","meaning":"A liderança material transforma a experiência em uma administração estável e generosa.","advice":"Faça a escolha de longo prazo e use o sucesso de forma responsável.","yesNoMeaning":"O Rei de Ouros inclina-se para sim: faça a escolha sólida de longo prazo e use o sucesso de forma responsável."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aries', 'pt-BR', '{"name":"Áries","dateRange":"21 de mar – 19 de abr","rulingPlanet":"Marte","summary":"Inícios ousados e ação direta definem o Carneiro, cuja faísca transforma intenção em impulso.","originStory":"Áries está ligado ao carneiro dourado que resgatou Frixo na mitologia grega. Seu velo mais tarde se tornou o prêmio de Jasão e os Argonautas, preservando o signo como símbolo de coragem, resgate e o primeiro passo de bravura.","traits":["Corajoso","Energético","Independente","Direto"],"strengths":["Iniciativa","Confiança","Resiliência"],"challenges":["Impaciência","Impulsividade","Começando mais rápido do que você consegue sustentar"],"compatibleSigns":["Leão","Sagitário","Gêmeos"],"reflectionPrompt":"Escolha um começo corajoso e dê a ele paciência suficiente para crescer."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'day', 'pt-BR', '{"overview":"Hoje favorece um passo claro e intencional. Áries se move através da energia do fogo. Começos ousados e ação direta definem o Carneiro, cuja centelha transforma intenção em momentum.","love":"No amor hoje, escolha a presença em vez da suposição. Seus dons de iniciativa, confiança e resiliência podem ajudá-lo a se conectar sem precisar atuar.","career":"No trabalho, complete a tarefa mais significativa antes de buscar um novo impulso. Use corajoso, enérgico, independente, direto como ferramentas, não como expectativas que você deve satisfazer tudo de uma vez.","finance":"Mantenha as escolhas financeiras de hoje simples e fundamentadas. Perceba quando a impaciência, impulsividade, começar mais rápido do que você pode sustentar começa a influenciar uma decisão prática.","wellbeing":"Uma pequena pausa pode redefinir sua energia. Escolha um início corajoso e dê a ele paciência suficiente para crescer.","guidance":"Antes que o dia acabe, lembre-se: Escolha um começo corajoso e dê a ele paciência suficiente para crescer."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'week', 'pt-BR', '{"overview":"Esta semana se desenvolve por meio de escolhas constantes ao invés de um momento dramático. Áries se move através da energia do fogo. Começos ousados e ação direta definem o Carneiro, cuja faísca transforma intenção em impulso.","love":"Os relacionamentos se beneficiam de uma conversa que abra espaço tanto para a honestidade quanto para a cordialidade. Seus dons de iniciativa, confiança e resiliência podem ajudá-lo a se conectar sem precisar se mostrar.","career":"Seu melhor progresso profissional vem de escolher uma prioridade e proteger tempo para ela. Use corajoso, energético, independente, direto como ferramentas, não como expectativas que você deve satisfazer todas de uma vez.","finance":"Revise o padrão por trás dos seus gastos antes de fazer um compromisso maior. Observe quando a impaciência, impulsividade, começar mais rápido do que você consegue sustentar começa a influenciar uma decisão prática.","wellbeing":"Equilibre o movimento com recuperação genuína ao longo da semana. Escolha um começo corajoso e dê a ele paciência suficiente para crescer.","guidance":"Deixe esta pergunta guiar a semana: Escolha um começo corajoso e dê a ele paciência suficiente para crescer."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'year', 'pt-BR', '{"overview":"Este ano convida ao crescimento paciente ao redor da identidade, propósito e da forma como você usa sua energia. Áries se move através da energia do fogo. Inícios ousados e ação direta definem o Carneiro, cuja faísca transforma intenção em impulso.","love":"O amor se aprofunda quando você pratica consistência e permite que a conexão evolua em um ritmo humano. Seus dons de iniciativa, confiança e resiliência podem ajudá-lo a se conectar sem precisar atuar.","career":"O trabalho a longo prazo se torna mais forte quando a ambição é combinada com uma estrutura que você pode sustentar. Use corajoso, enérgico, independente, direto como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Construa confiança financeira por meio de hábitos repetíveis em vez de previsões perfeitas. Observe quando a impaciência, impulsividade, começar mais rápido do que se pode sustentar começam a influenciar uma decisão prática.","wellbeing":"Trate o bem-estar como uma base para a vida que você está construindo, não como uma recompensa depois de terminá-la. Escolha um começo corajoso e dê a ele paciência suficiente para crescer.","guidance":"Volte a esta bússola ao longo do ano: Escolha um começo corajoso e dê a ele paciência suficiente para crescer."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('taurus', 'pt-BR', '{"name":"Touro","dateRange":"20 de abril – 20 de maio","rulingPlanet":"Vênus","summary":"Firme, sensual e com os pés no chão, o Touro constrói valor duradouro por meio da paciência e do cuidado.","originStory":"Touro lembra Zeus assumindo a forma de um magnífico touro branco para levar Europa através do mar. A imagem tornou-se associada à beleza, fertilidade, abundância terrena e poder expressado através da persistência calma.","traits":["Com base","Leal","Paciente","Sensual"],"strengths":["Confiabilidade","Sabedoria prática","Devoção"],"challenges":["Teimosia","Resistência à mudança","Apegando-se por muito tempo"],"compatibleSigns":["Virgem","Capricórnio","Câncer"],"reflectionPrompt":"Proteja o que importa sem confundir conforto com permanência."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'day', 'pt-BR', '{"overview":"Hoje favorece um passo claro e intencional. Touro se move através da energia da terra. Firme, sensual e centrado, o Touro constrói valor duradouro através da paciência e do cuidado.","love":"No amor hoje, escolha a presença em vez da suposição. Seus dons de confiabilidade, sabedoria prática e devoção podem ajudá-lo a se conectar sem precisar atuar.","career":"No trabalho, complete a tarefa mais significativa antes de buscar um novo impulso. Use centrado, leal, paciente, sensual como ferramentas, não como expectativas que você deve satisfazer tudo de uma vez.","finance":"Mantenha as escolhas financeiras de hoje simples e fundamentadas. Perceba quando a teimosia, a resistência à mudança, ou se apegar por muito tempo começam a influenciar uma decisão prática.","wellbeing":"Uma pequena pausa pode redefinir sua energia. Proteja o que importa sem confundir conforto com permanência.","guidance":"Antes que o dia acabe, lembre-se: Proteja o que importa sem confundir conforto com permanência."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'week', 'pt-BR', '{"overview":"Esta semana se desenvolve por meio de escolhas constantes, e não de um momento dramático. Touro se move através da energia da terra. Constante, sensual e com os pés no chão, o Touro constrói valor duradouro por meio da paciência e do cuidado.","love":"Os relacionamentos se beneficiam de uma conversa que dê espaço tanto para a honestidade quanto para a cordialidade. Seus dons de confiabilidade, sabedoria prática e devoção podem ajudá-lo a se conectar sem precisar atuar.","career":"Seu melhor progresso profissional vem de escolher uma prioridade e proteger tempo para ela. Use centrado, leal, paciente, sensual como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Revise o padrão por trás de seus gastos antes de assumir um compromisso maior. Perceba quando teimosia, resistência à mudança, insistir por muito tempo começa a influenciar uma decisão prática.","wellbeing":"Equilibre o movimento com recuperação genuína ao longo da semana. Proteja o que importa sem confundir conforto com permanência.","guidance":"Deixe esta pergunta guiar a semana: Proteja o que importa sem confundir conforto com permanência."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'year', 'pt-BR', '{"overview":"Este ano convida ao crescimento paciente em torno da identidade, propósito e da forma como você usa sua energia. Touro transita pela energia da terra. Estável, sensual e centrado, o Touro constrói valor duradouro através da paciência e cuidado.","love":"O amor se aprofunda quando você pratica a consistência e permite que a conexão evolua no ritmo humano. Seus dons de confiabilidade, sabedoria prática, devoção podem ajudá-lo a se conectar sem precisar se exibir.","career":"O trabalho de longo prazo se torna mais forte quando a ambição é combinada com uma estrutura que você pode sustentar. Use equilibrado, leal, paciente, sensual como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Construa confiança financeira por meio de hábitos repetíveis em vez de previsões perfeitas. Observe quando teimosia, resistência à mudança e insistência por muito tempo começam a influenciar uma decisão prática.","wellbeing":"Trate o bem-estar como uma base para a vida que você está construindo, e não como uma recompensa depois de terminá-la. Proteja o que importa sem confundir conforto com permanência.","guidance":"Volte a esta bússola ao longo do ano: Proteja o que importa sem confundir conforto com permanência."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('gemini', 'pt-BR', '{"name":"Gêmeos","dateRange":"21 de mai – 20 de jun","rulingPlanet":"Mercúrio","summary":"Curiosidade e conexão guiam os Gêmeos, que coletam ideias e revelam mais de um lado da história.","originStory":"Gêmeos representa Cástor e Pólux, gêmeos inseparáveis que compartilhavam a imortalidade em vez de ficarem separados. Sua constelação traz temas de companheirismo, perspectiva dupla, comunicação e movimento entre mundos.","traits":["Curioso","Adaptável","Expressivo","Ágil de raciocínio"],"strengths":["Comunicação","Versatilidade","Aprendizado rápido"],"challenges":["Inquietação","Foco disperso","Pensar demais"],"compatibleSigns":["Libra","Aquário","Áries"],"reflectionPrompt":"Deixe a curiosidade abrir a porta, depois fique tempo suficiente para entender o que você encontra."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'day', 'pt-BR', '{"overview":"Hoje favorece um passo claro e intencional. Gêmeos se move através da energia do ar. Curiosidade e conexão guiam os Gêmeos, que recolhem ideias e revelam mais de um lado de uma história.","love":"No amor hoje, escolha presença em vez de suposições. Seus dons de comunicação, versatilidade, aprendizado rápido podem ajudá-lo a se conectar sem precisar se exibir.","career":"No trabalho, complete a tarefa mais significativa antes de buscar um novo impulso. Use curioso, adaptável, expressivo, de raciocínio rápido como ferramentas, não como expectativas que você deve satisfazer tudo de uma vez.","finance":"Mantenha as escolhas financeiras de hoje simples e fundamentadas. Perceba quando a inquietação, a dispersão de foco, ou pensar demais começam a influenciar uma decisão prática.","wellbeing":"Uma pequena pausa pode redefinir sua energia. Deixe a curiosidade abrir a porta, depois permaneça tempo suficiente para entender o que você encontrar.","guidance":"Antes que o dia acabe, lembre-se: Deixe a curiosidade abrir a porta, depois fique tempo suficiente para entender o que você encontrar."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'week', 'pt-BR', '{"overview":"Esta semana se desenvolve por meio de escolhas constantes em vez de um momento dramático. Gêmeos se move através da energia do ar. Curiosidade e conexão guiam os Gêmeos, que recolhem ideias e revelam mais de um lado da história.","love":"Os relacionamentos se beneficiam de uma conversa que cria espaço tanto para a honestidade quanto para o calor humano. Seus talentos de comunicação, versatilidade, aprendizado rápido podem ajudá-lo a se conectar sem precisar atuar.","career":"Seu melhor progresso profissional vem de escolher uma prioridade e proteger tempo para ela. Use curioso, adaptável, expressivo, perspicaz como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Revise o padrão por trás de seus gastos antes de assumir um compromisso maior. Perceba quando inquietação, foco disperso, pensar demais começa a influenciar uma decisão prática.","wellbeing":"Equilibre o movimento com recuperação genuína ao longo da semana. Deixe a curiosidade abrir a porta, depois fique tempo suficiente para entender o que encontra.","guidance":"Deixe esta pergunta guiar a semana: Deixe a curiosidade abrir a porta, então permaneça tempo suficiente para entender o que você encontra."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'year', 'pt-BR', '{"overview":"Este ano convida ao crescimento paciente em torno da identidade, propósito e da forma como você usa sua energia. Gêmeos se move através da energia do ar. Curiosidade e conexão guiam os Gêmeos, que reúnem ideias e revelam mais de um lado de uma história.","love":"O amor se aprofunda quando você pratica consistência e permite que a conexão evolua em um ritmo humano. Seus talentos de comunicação, versatilidade, aprendizado rápido podem ajudá-lo a se conectar sem precisar atuar.","career":"O trabalho de longo prazo se torna mais forte quando a ambição é combinada com uma estrutura que você pode sustentar. Use curioso, adaptável, expressivo, perspicaz como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Construa confiança financeira por meio de hábitos repetíveis em vez de previsões perfeitas. Observe quando inquietação, foco disperso e excesso de pensamentos começam a influenciar uma decisão prática.","wellbeing":"Trate o bem-estar como uma base para a vida que você está construindo, e não como uma recompensa depois de terminá-la. Deixe a curiosidade abrir a porta e permaneça tempo suficiente para entender o que encontrar.","guidance":"Volte a esta bússola ao longo do ano: Deixe a curiosidade abrir a porta, depois fique tempo suficiente para entender o que encontrar."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('cancer', 'pt-BR', '{"name":"Câncer","dateRange":"21 de jun – 22 de jul","rulingPlanet":"Lua","summary":"Protetor e intuitivo, o Caranguejo cria pertencimento ao honrar a memória, os sentimentos e o lar.","originStory":"Câncer está associado ao caranguejo Karkinos, colocado entre as estrelas após demonstrar lealdade durante a batalha de Hércules com a Hidra. Sua carapaça e a regência lunar refletem proteção, marés emocionais e devoção ao círculo íntimo.","traits":["Intuitivo","Cuidado","Protetor","Imaginativo"],"strengths":["Empatia","Lealdade","Percepção emocional"],"challenges":["Oscilação de humor","Recuando por trás das defesas","Levando as coisas para o lado pessoal"],"compatibleSigns":["Escorpião","Peixes","Touro"],"reflectionPrompt":"Cuide do seu mundo interior enquanto mantém uma porta aberta para uma conexão honesta."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'day', 'pt-BR', '{"overview":"Hoje favorece um passo claro e intencional. Câncer se move através da energia da água. Protetor e intuitivo, o Caranguejo cria senso de pertencimento ao honrar a memória, o sentimento e o lar.","love":"No amor hoje, escolha a presença em vez de suposições. Seus dons de empatia, lealdade e percepção emocional podem ajudá-lo a se conectar sem atuar.","career":"No trabalho, complete a tarefa mais significativa antes de buscar um novo impulso. Use intuitivo, cuidadoso, protetor, imaginativo como ferramentas, não como expectativas que você deve satisfazer de uma só vez.","finance":"Mantenha as escolhas financeiras de hoje simples e fundamentadas. Perceba quando mudanças de humor, se retraindo atrás de defesas, levar as coisas para o lado pessoal começam a influenciar uma decisão prática.","wellbeing":"Uma pequena pausa pode redefinir sua energia. Cuide do seu mundo interior enquanto mantém uma porta aberta para uma conexão honesta.","guidance":"Antes que o dia acabe, lembre-se: Cuide do seu mundo interior enquanto deixa uma porta aberta para uma conexão honesta."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'week', 'pt-BR', '{"overview":"Esta semana se desenvolve por meio de escolhas constantes ao invés de um momento dramático. Câncer se move através da energia da água. Protetor e intuitivo, o Caranguejo cria pertencimento honrando a memória, o sentimento e o lar.","love":"Os relacionamentos se beneficiam de uma conversa que dê espaço tanto para a honestidade quanto para a cordialidade. Seus dons de empatia, lealdade e percepção emocional podem ajudá-lo a se conectar sem precisar atuar.","career":"Seu melhor progresso profissional vem de escolher uma prioridade e proteger tempo para ela. Use intuitivo, carinhoso, protetor, imaginativo como ferramentas, não como expectativas que você deve satisfazer de uma só vez.","finance":"Revise o padrão por trás de seus gastos antes de fazer um compromisso maior. Observe quando a mudança de humor, se retrair atrás de defesas, levar as coisas para o lado pessoal começa a influenciar uma decisão prática.","wellbeing":"Equilibre o movimento com recuperação genuína ao longo da semana. Cuide do seu mundo interior enquanto deixa uma porta aberta para conexões honestas.","guidance":"Deixe esta pergunta guiar a semana: Cuide do seu mundo interno enquanto mantém uma porta aberta para uma conexão honesta."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'year', 'pt-BR', '{"overview":"Este ano convida ao crescimento paciente em torno da identidade, propósito e da forma como você usa sua energia. Câncer se move através da energia da água. Protetor e intuitivo, o Caranguejo cria pertencimento ao honrar a memória, o sentimento e o lar.","love":"O amor se aprofunda quando você pratica consistência e permite que a conexão evolua em um ritmo humano. Seus dons de empatia, lealdade e percepção emocional podem ajudá-lo a se conectar sem precisar atuar.","career":"O trabalho de longo prazo se torna mais forte quando a ambição é combinada com uma estrutura que você pode sustentar. Use intuitivo, cuidadoso, protetor, imaginativo como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Construa confiança financeira por meio de hábitos repetíveis em vez de previsões perfeitas. Observe quando mudanças de humor, retração atrás de defesas e levar as coisas para o lado pessoal começam a influenciar uma decisão prática.","wellbeing":"Trate o bem-estar como uma base para a vida que você está construindo, não como uma recompensa depois de terminá-la. Cuide do seu mundo interior enquanto mantém uma porta aberta para conexões honestas.","guidance":"Volte a esta bússola ao longo do ano: Cuide do seu mundo interior enquanto deixa uma porta aberta para uma conexão honesta."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('leo', 'pt-BR', '{"name":"Leão","dateRange":"23 de jul – 22 de ago","rulingPlanet":"Sol","summary":"Calor, criatividade e expressão generosa fazem do Leão uma fonte natural de luz.","originStory":"Leão está ligado ao Leão de Nemeia, a criatura quase invulnerável derrotada no primeiro trabalho de Hércules. Elevado aos céus, tornou-se um emblema de coragem, presença soberana e da força criativa do Sol.","traits":["Quente","Criativo","Generoso","Confiante"],"strengths":["Liderança","Lealdade","Expressão sincera"],"challenges":["Orgulho","Necessidade de reconhecimento","Dramatizando contratempos"],"compatibleSigns":["Áries","Sagitário","Libra"],"reflectionPrompt":"Compartilhe sua luz generosamente e deixe outros brilharem ao seu lado."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'day', 'pt-BR', '{"overview":"Hoje favorece um passo claro e intencional. Leão se move através da energia do fogo. Calor, criatividade e expressão generosa de si tornam o Leão uma fonte natural de luz.","love":"No amor hoje, escolha a presença em vez da suposição. Seus dons de liderança, lealdade e expressão sincera podem ajudá-lo a se conectar sem precisar atuar.","career":"No trabalho, complete a tarefa mais significativa antes de buscar um novo impulso. Use calor, criatividade, generosidade e confiança como ferramentas, não como expectativas que você deve satisfazer de uma vez só.","finance":"Mantenha as escolhas financeiras de hoje simples e fundamentadas. Perceba quando o orgulho, a necessidade de reconhecimento, ou dramatizar retrocessos começam a influenciar uma decisão prática.","wellbeing":"Uma pequena pausa pode restaurar sua energia. Compartilhe sua luz generosamente e deixe que outros brilhem ao seu lado.","guidance":"Antes que o dia termine, lembre-se: Compartilhe sua luz generosamente e deixe que outros brilhem ao seu lado."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'week', 'pt-BR', '{"overview":"Esta semana se desenvolve por meio de escolhas constantes em vez de um momento dramático. Leão se move através da energia do fogo. Calor, criatividade e autoexpressão generosa tornam o Leão uma fonte natural de luz.","love":"Os relacionamentos se beneficiam de uma conversa que dê espaço tanto para a honestidade quanto para a cordialidade. Seus dons de liderança, lealdade e expressão sincera podem ajudá-lo a se conectar sem precisar atuar.","career":"Seu melhor progresso profissional vem de escolher uma prioridade e proteger tempo para ela. Use caloroso, criativo, generoso, confiante como ferramentas, não como expectativas que você deve satisfazer de uma só vez.","finance":"Revise o padrão por trás de seus gastos antes de fazer um compromisso maior. Observe quando o orgulho, a necessidade de reconhecimento, dramatizar contratempos começa a influenciar uma decisão prática.","wellbeing":"Equilibre o movimento com recuperação genuína ao longo da semana. Compartilhe sua luz generosamente e deixe que outros brilhem ao seu lado.","guidance":"Deixe esta pergunta guiar a semana: Compartilhe sua luz generosamente e deixe que outros brilhem ao seu lado."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'year', 'pt-BR', '{"overview":"Este ano convida ao crescimento paciente em torno da identidade, propósito e da maneira como você usa sua energia. Leão transita pela energia do fogo. Calor, criatividade e expressão generosa de si mesmo tornam o Leão uma fonte natural de luz.","love":"O amor se aprofunda quando você pratica a consistência e permite que a conexão evolua no ritmo humano. Seus dons de liderança, lealdade, expressão com o coração podem ajudá-lo a se conectar sem precisar se exibir.","career":"O trabalho de longo prazo se torna mais forte quando a ambição é combinada com uma estrutura que você pode sustentar. Use caloroso, criativo, generoso, confiante como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Construa confiança financeira através de hábitos repetíveis em vez de previsões perfeitas. Perceba quando o orgulho, a necessidade de reconhecimento e a dramatização de contratempos começam a influenciar uma decisão prática.","wellbeing":"Trate o bem-estar como uma base para a vida que você está construindo, não como uma recompensa após terminá-la. Compartilhe sua luz generosamente e deixe que os outros brilhem ao seu lado.","guidance":"Volte a esta bússola ao longo do ano: Compartilhe sua luz generosamente e deixe que outros brilhem ao seu lado."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('virgo', 'pt-BR', '{"name":"Virgem","dateRange":"23 de ago – 22 de set","rulingPlanet":"Mercúrio","summary":"Discernimento e serviço guiam a Virgem, transformando observação cuidadosa em melhoria prática.","originStory":"Virgem é frequentemente conectada com Astreia, a donzela da justiça que permaneceu com a humanidade após os outros deuses se retirarem. O trigo que ela carrega liga o signo à colheita, habilidade, pureza de intenção e cuidado com o que sustenta a vida.","traits":["Observador","Prático","Atento","Preciso"],"strengths":["Análise","Artesanato","Serviço útil"],"challenges":["Perfeccionismo","Autocrítica","Preocupando-se com detalhes"],"compatibleSigns":["Touro","Capricórnio","Câncer"],"reflectionPrompt":"Melhore o que você puder e permita que um bom trabalho seja concluído antes de estar perfeito."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'day', 'pt-BR', '{"overview":"Hoje favorece um passo claro e intencional. Virgem se move através da energia da terra. Discernimento e serviço guiam a Virgem, transformando observação cuidadosa em melhoria prática.","love":"No amor hoje, escolha presença em vez de suposições. Seus dons de análise, habilidade manual, serviço útil podem ajudá-lo a se conectar sem precisar se exibir.","career":"No trabalho, complete a tarefa mais significativa antes de buscar um novo impulso. Use observador, prático, reflexivo, preciso como ferramentas, não como expectativas que você deve satisfazer de uma só vez.","finance":"Mantenha as escolhas financeiras de hoje simples e fundamentadas. Perceba quando o perfeccionismo, autocritica, preocupar-se com detalhes começa a influenciar uma decisão prática.","wellbeing":"Uma pequena pausa pode redefinir sua energia. Melhore o que você pode e permita que o bom trabalho esteja completo antes de ser perfeito.","guidance":"Antes que o dia acabe, lembre-se: Melhore o que você puder e permita que um bom trabalho seja considerado completo antes de ser perfeito."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'week', 'pt-BR', '{"overview":"Esta semana se desenvolve por meio de escolhas constantes em vez de um momento dramático. Virgem se move através da energia da terra. Discernimento e serviço guiam a Virgem, transformando a observação cuidadosa em melhoria prática.","love":"Os relacionamentos se beneficiam de uma conversa que cria espaço tanto para a honestidade quanto para o calor humano. Seus talentos de análise, habilidade manual, serviço útil podem ajudá-lo a se conectar sem precisar atuar.","career":"Seu melhor progresso profissional vem de escolher uma prioridade e proteger tempo para ela. Use observador, prático, atencioso, preciso como ferramentas, não como expectativas que você deve satisfazer de uma só vez.","finance":"Revise o padrão por trás de seus gastos antes de fazer um compromisso maior. Observe quando o perfeccionismo, a autocrítica, a preocupação com detalhes começa a influenciar uma decisão prática.","wellbeing":"Equilibre o movimento com recuperação genuína ao longo da semana. Melhore o que puder, e permita que um bom trabalho seja completo antes de ser perfeito.","guidance":"Deixe esta pergunta guiar a semana: Melhore o que você puder, e permita que um bom trabalho esteja completo antes de ser perfeito."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'year', 'pt-BR', '{"overview":"Este ano convida ao crescimento paciente em torno da identidade, propósito e da forma como você usa sua energia. Virgem move-se através da energia da terra. Discernimento e serviço guiam a Donzela, transformando observação cuidadosa em melhoria prática.","love":"O amor se aprofunda quando você pratica consistência e permite que a conexão evolua em um ritmo humano. Seus talentos de análise, habilidade manual, serviço útil podem ajudá-lo a se conectar sem precisar atuar.","career":"O trabalho de longo prazo se torna mais forte quando a ambição é combinada com uma estrutura que você pode sustentar. Use observador, prático, atencioso, preciso como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Construa confiança financeira por meio de hábitos repetíveis em vez de previsões perfeitas. Perceba quando o perfeccionismo, a autocrítica e a preocupação com os detalhes começam a influenciar uma decisão prática.","wellbeing":"Trate o bem-estar como uma base para a vida que você está construindo, e não como uma recompensa depois de terminá-la. Melhore o que você puder e permita que um bom trabalho seja completo antes de ser perfeito.","guidance":"Volte a esta bússola ao longo do ano: Melhore o que você puder e permita que o bom trabalho esteja completo antes de ser perfeito."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('libra', 'pt-BR', '{"name":"Libra","dateRange":"23 de setembro – 22 de outubro","rulingPlanet":"Vênus","summary":"Equilíbrio, beleza e reciprocidade guiam as Escalas em direção a escolhas que honram cada voz.","originStory":"As balanças de Libra são carregadas por Astraea, deusa da justiça, e formam o único símbolo inanimado do zodíaco. Elas representam julgamento ponderado, harmonia social e o trabalho contínuo de restaurar o equilíbrio, em vez de presumir que ele já existe.","traits":["Diplomático","Justo","Encantador","Colaborativo"],"strengths":["Mediação","Perspectiva","Criando harmonia"],"challenges":["Indecisão","Satisfazer os outros","Evitando conflitos necessários"],"compatibleSigns":["Gêmeos","Aquário","Leão"],"reflectionPrompt":"Busque justiça sem abandonar a verdade de suas próprias necessidades."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'day', 'pt-BR', '{"overview":"Hoje favorece um passo claro e intencional. Libra se move através da energia do ar. Equilíbrio, beleza e reciprocidade guiam a Balança em direção a escolhas que honram cada voz.","love":"No amor hoje, escolha a presença em vez da suposição. Seus dons de mediação, perspectiva e criação de harmonia podem ajudá-lo a se conectar sem precisar atuar.","career":"No trabalho, complete a tarefa mais significativa antes de buscar um novo impulso. Use diplomático, justo, encantador, colaborativo como ferramentas, não como expectativas que você deve satisfazer tudo de uma vez.","finance":"Mantenha as escolhas financeiras de hoje simples e fundamentadas. Perceba quando a indecisão, agradar aos outros, evitar conflitos necessários começa a influenciar uma decisão prática.","wellbeing":"Uma pequena pausa pode restaurar sua energia. Busque a justiça sem abandonar a verdade de suas próprias necessidades.","guidance":"Antes que o dia termine, lembre-se: Busque justiça sem abandonar a verdade de suas próprias necessidades."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'week', 'pt-BR', '{"overview":"Esta semana se desenvolve por meio de escolhas constantes em vez de um momento dramático. Libra se move através da energia do ar. Equilíbrio, beleza e reciprocidade guiam a Balança para escolhas que honram cada voz.","love":"Os relacionamentos se beneficiam de uma conversa que dê espaço tanto para a honestidade quanto para a cordialidade. Seus dons de mediação, perspectiva e criação de harmonia podem ajudá-lo a se conectar sem precisar atuar.","career":"Seu melhor progresso profissional vem de escolher uma prioridade e proteger tempo para ela. Use diplomático, justo, encantador, colaborativo como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Revise o padrão por trás de seus gastos antes de fazer um compromisso maior. Observe quando a indecisão, o prazer em agradar os outros, evitar conflitos necessários começa a influenciar uma decisão prática.","wellbeing":"Equilibre o movimento com recuperação genuína ao longo da semana. Busque justiça sem abandonar a verdade de suas próprias necessidades.","guidance":"Deixe esta pergunta guiar a semana: Busque a justiça sem abandonar a verdade das suas próprias necessidades."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'year', 'pt-BR', '{"overview":"Este ano convida ao crescimento paciente em torno da identidade, propósito e da maneira como você usa sua energia. Libra se move através da energia do ar. Equilíbrio, beleza e reciprocidade guiam a Balança em direção a escolhas que honram cada voz.","love":"O amor se aprofunda quando você pratica a consistência e permite que a conexão evolua no ritmo humano. Seus dons de mediação, perspectiva, criar harmonia podem ajudá-lo a se conectar sem precisar se exibir.","career":"O trabalho de longo prazo se torna mais forte quando a ambição é combinada com uma estrutura que você pode sustentar. Use diplomático, justo, encantador, colaborativo como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Construa confiança financeira por meio de hábitos repetíveis em vez de previsões perfeitas. Perceba quando a indecisão, o desejo de agradar os outros e evitar conflitos necessários começam a influenciar uma decisão prática.","wellbeing":"Trate o bem-estar como uma base para a vida que você está construindo, e não como uma recompensa depois de terminá-la. Busque a justiça sem abandonar a verdade de suas próprias necessidades.","guidance":"Volte a esta bússola ao longo do ano: Busque a justiça sem abandonar a verdade de suas próprias necessidades."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('scorpio', 'pt-BR', '{"name":"Escorpião","dateRange":"23 de out – 21 de nov","rulingPlanet":"Plutão","summary":"Profundidade e transformação definem o Escorpião, cujo insight encontra a verdade abaixo da superfície.","originStory":"Escorpião lembra o escorpião enviado para confrontar o caçador Orion depois que seu orgulho perturbou a ordem natural. Seus lugares opostos no céu evocam limites, consequências, mistério e o poder regenerativo encontrado após um fim.","traits":["Intenso","Perceptivo","Leal","Ingênuo"],"strengths":["Coragem emocional","Foco","Transformação"],"challenges":["Segredo","Suspeita","Guardar rancores"],"compatibleSigns":["Câncer","Peixes","Virgem"],"reflectionPrompt":"Use sua profundidade para transformar a verdade, não para escondê-la."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'day', 'pt-BR', '{"overview":"Hoje favorece um passo claro e intencional. Escorpião se move através da energia da água. Profundidade e transformação definem o Escorpião, cuja percepção encontra a verdade abaixo da superfície.","love":"No amor hoje, escolha presença em vez de suposições. Seus dons de coragem emocional, foco, transformação podem ajudá-lo a se conectar sem precisar se exibir.","career":"No trabalho, complete a tarefa mais significativa antes de buscar um novo impulso. Use intenso, perceptivo, leal, engenhoso como ferramentas, não como expectativas que você deve satisfazer de uma só vez.","finance":"Mantenha as escolhas financeiras de hoje simples e fundamentadas. Perceba quando o segredo, a suspeita, ou guardar ressentimentos começam a influenciar uma decisão prática.","wellbeing":"Uma pequena pausa pode restaurar sua energia. Use sua profundidade para transformar a verdade, não para escondê-la.","guidance":"Antes que o dia termine, lembre-se: Use sua profundidade para transformar a verdade, não para escondê-la."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'week', 'pt-BR', '{"overview":"Esta semana se desenvolve por meio de escolhas constantes, e não de um momento dramático. Escorpião se move através da energia da água. Profundidade e transformação definem o Escorpião, cuja percepção encontra a verdade sob a superfície.","love":"Os relacionamentos se beneficiam de uma conversa que cria espaço tanto para a honestidade quanto para o calor humano. Seus talentos de coragem emocional, foco, transformação podem ajudá-lo a se conectar sem precisar atuar.","career":"Seu melhor progresso profissional vem de escolher uma prioridade e proteger tempo para ela. Use intenso, perceptivo, leal, engenhoso como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Revise o padrão por trás de seus gastos antes de assumir um compromisso maior. Perceba quando segredo, suspeita, guardar rancor começa a influenciar uma decisão prática.","wellbeing":"Equilibre o movimento com recuperação genuína ao longo da semana. Use sua profundidade para transformar a verdade, não para escondê-la.","guidance":"Deixe que esta pergunta guie a semana: Use sua profundidade para transformar a verdade, não para escondê-la."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'year', 'pt-BR', '{"overview":"Este ano convida ao crescimento paciente em torno da identidade, propósito e da forma como você usa sua energia. Escorpião transita pela energia da água. Profundidade e transformação definem o Escorpião, cuja percepção encontra a verdade abaixo da superfície.","love":"O amor se aprofunda quando você pratica consistência e permite que a conexão evolua em um ritmo humano. Seus talentos de coragem emocional, foco, transformação podem ajudá-lo a se conectar sem precisar atuar.","career":"O trabalho de longo prazo se torna mais forte quando a ambição é combinada com uma estrutura que você pode sustentar. Use intenso, perceptivo, leal, engenhoso como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Construa confiança financeira por meio de hábitos repetíveis em vez de previsões perfeitas. Observe quando segredo, desconfiança e guardar rancor começam a influenciar uma decisão prática.","wellbeing":"Trate o bem-estar como uma base para a vida que você está construindo, não como uma recompensa após terminá-la. Use sua profundidade para transformar a verdade, não para escondê-la.","guidance":"Volte a esta bússola ao longo do ano: Use sua profundidade para transformar a verdade, não para escondê-la."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('sagittarius', 'pt-BR', '{"name":"Sagitário","dateRange":"22 de nov – 21 de dez","rulingPlanet":"Júpiter","summary":"O Arqueiro busca horizontes mais amplos através da verdade, viagem, aprendizado e otimismo intencional.","originStory":"Sagitário é comumente ligado a Quíron, o sábio centauro e professor cuja flecha aponta além do familiar. A constelação simboliza a união do instinto com a compreensão superior, sempre mirando um horizonte mais significativo.","traits":["Aventureiro","Otimista","Honesto","Filosófico"],"strengths":["Visão","Entusiasmo","Mente aberta"],"challenges":["Franqueza","Prometer demais","Escapando da rotina"],"compatibleSigns":["Áries","Leão","Aquário"],"reflectionPrompt":"Mire alto, mas escolha uma direção que suas ações diárias possam apoiar."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'day', 'pt-BR', '{"overview":"Hoje favorece um passo claro e intencional. Sagitário se move através da energia do fogo. O Arqueiro busca horizontes mais amplos através da verdade, viagens, aprendizado e otimismo com propósito.","love":"No amor hoje, escolha a presença em vez da suposição. Seus dons de visão, entusiasmo e mente aberta podem ajudá-lo a se conectar sem precisar atuar.","career":"No trabalho, complete a tarefa mais significativa antes de buscar um novo impulso. Use aventureiro, otimista, honesto, filosófico como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Mantenha as escolhas financeiras de hoje simples e fundamentadas. Observe quando a franqueza, prometer demais ou escapar da rotina começa a influenciar uma decisão prática.","wellbeing":"Uma pequena pausa pode restaurar sua energia. Mire longe, mas escolha uma direção que suas ações diárias possam apoiar.","guidance":"Antes do dia acabar, lembre-se: Mire longe, mas escolha uma direção que suas ações diárias possam apoiar."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'week', 'pt-BR', '{"overview":"Esta semana se desenvolve por meio de escolhas constantes, em vez de um momento dramático. Sagitário se move através da energia do fogo. O Arqueiro busca horizontes mais amplos por meio da verdade, viagens, aprendizado e otimismo intencional.","love":"Relacionamentos se beneficiam de uma conversa que dê espaço tanto para a honestidade quanto para a cordialidade. Seus dons de visão, entusiasmo e mente aberta podem ajudá-lo a se conectar sem precisar atuar.","career":"Seu melhor progresso profissional vem de escolher uma prioridade e proteger tempo para ela. Use aventureiro, otimista, honesto, filosófico como ferramentas, não como expectativas que você deve satisfazer todas de uma vez.","finance":"Revise o padrão por trás dos seus gastos antes de fazer um compromisso maior. Observe quando a franqueza, prometer demais, escapar da rotina começa a influenciar uma decisão prática.","wellbeing":"Equilibre movimento com recuperação genuína ao longo da semana. Mire longe, mas escolha uma direção que suas ações diárias possam apoiar.","guidance":"Deixe esta pergunta guiar a semana: Mire longe, mas escolha uma direção que suas ações diárias possam apoiar."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'year', 'pt-BR', '{"overview":"Este ano convida ao crescimento paciente em torno da identidade, propósito e da forma como você usa sua energia. Sagitário transita pela energia do fogo. O Arqueiro busca horizontes mais amplos através da verdade, viagens, aprendizado e otimismo intencional.","love":"O amor se aprofunda quando você pratica consistência e permite que a conexão evolua em um ritmo humano. Seus dons de visão, entusiasmo e mente aberta podem ajudá-lo a se conectar sem precisar se apresentar.","career":"O trabalho a longo prazo se torna mais forte quando a ambição é combinada com uma estrutura que você pode sustentar. Use aventureiro, otimista, honesto, filosófico como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Construa confiança financeira por meio de hábitos repetíveis em vez de previsões perfeitas. Observe quando a franqueza, prometer demais, fugir da rotina começam a influenciar uma decisão prática.","wellbeing":"Trate o bem-estar como uma base para a vida que você está construindo, não como uma recompensa depois de terminá-la. Mire longe, mas escolha uma direção que suas ações diárias possam apoiar.","guidance":"Volte a esta bússola ao longo do ano: Mire longe, mas escolha uma direção que suas ações diárias possam apoiar."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('capricorn', 'pt-BR', '{"name":"Capricórnio","dateRange":"22 de Dez – 19 de Jan","rulingPlanet":"Saturno","summary":"Disciplina e visão de longo alcance ajudam o Capricórnio a subir enquanto permanece sábio sobre as profundezas abaixo.","originStory":"O bode-do-mar de Capricórnio está associado a Pan, que se transformou parcialmente em peixe enquanto escapava de Tifão. Sua natureza de montanha e oceano une ambição com sobrevivência emocional, honrando a maestria conquistada com o tempo e a responsabilidade.","traits":["Ambicioso","Disciplinado","Paciente","Responsável"],"strengths":["Resistência","Estratégia","Confiabilidade"],"challenges":["Rigidez","Pessimismo","Medir valor através da conquista"],"compatibleSigns":["Touro","Virgem","Escorpião"],"reflectionPrompt":"Construa para o longo prazo, lembrando que o descanso faz parte da estrutura."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'day', 'pt-BR', '{"overview":"Hoje favorece um passo claro e intencional. Capricórnio se move através da energia da terra. Disciplina e visão de longo alcance ajudam o Bode do Mar a subir, permanecendo sábio sobre as profundezas abaixo.","love":"No amor hoje, escolha a presença em vez de suposições. Seus talentos de resistência, estratégia e confiabilidade podem ajudá-lo a se conectar sem precisar desempenhar.","career":"No trabalho, complete a tarefa mais significativa antes de buscar um novo impulso. Use ambicioso, disciplinado, paciente, responsável como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Mantenha as escolhas financeiras de hoje simples e fundamentadas. Perceba quando a rigidez, o pessimismo, ou medir o valor através das conquistas começam a influenciar uma decisão prática.","wellbeing":"Uma pequena pausa pode restaurar sua energia. Construa para o longo prazo, lembrando que o descanso faz parte da estrutura.","guidance":"Antes que o dia acabe, lembre-se: Construa para o longo prazo enquanto lembra que o descanso faz parte da estrutura."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'week', 'pt-BR', '{"overview":"Esta semana se desenvolve por meio de escolhas constantes em vez de um momento dramático. Capricórnio se move através da energia da terra. Disciplina e visão de longo prazo ajudam o Bode do Mar a subir, enquanto permanece sábio sobre as profundezas abaixo.","love":"Os relacionamentos se beneficiam de uma conversa que dê espaço tanto para a honestidade quanto para a cordialidade. Seus dons de resistência, estratégia e confiabilidade podem ajudá-lo a se conectar sem precisar atuar.","career":"Seu melhor progresso profissional vem de escolher uma prioridade e proteger tempo para ela. Use ambicioso, disciplinado, paciente, responsável como ferramentas, não como expectativas que você deve satisfazer todas de uma vez.","finance":"Revise o padrão por trás de seus gastos antes de assumir um compromisso maior. Perceba quando rigidez, pessimismo, medir o valor através das conquistas começa a influenciar uma decisão prática.","wellbeing":"Equilibre movimento com recuperação genuína ao longo da semana. Construa para o longo prazo, lembrando que o descanso faz parte da estrutura.","guidance":"Deixe esta pergunta guiar a semana: Construa para o longo prazo lembrando que o descanso faz parte da estrutura."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'year', 'pt-BR', '{"overview":"Este ano convida ao crescimento paciente em torno da identidade, propósito e da forma como você usa sua energia. Capricórnio se move através da energia da terra. Disciplina e visão de longo alcance ajudam a Cabra-do-Mar a subir enquanto permanece sábia sobre as profundezas abaixo.","love":"O amor se aprofunda quando você pratica consistência e permite que a conexão evolua em um ritmo humano. Seus dons de resistência, estratégia e confiabilidade podem ajudá-lo a se conectar sem precisar atuar.","career":"O trabalho a longo prazo se torna mais forte quando a ambição é combinada com uma estrutura que você pode sustentar. Use ambicioso, disciplinado, paciente, responsável como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Construa confiança financeira por meio de hábitos repetíveis em vez de previsões perfeitas. Observe quando rigidez, pessimismo e medir o valor por meio de conquistas começam a influenciar uma decisão prática.","wellbeing":"Trate o bem-estar como uma base para a vida que você está construindo, não como uma recompensa depois de terminá-la. Construa para o longo prazo enquanto lembra que o descanso faz parte da estrutura.","guidance":"Volte a esta bússola ao longo do ano: Construa para o longo prazo enquanto lembra que o descanso faz parte da estrutura."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aquarius', 'pt-BR', '{"name":"Aquário","dateRange":"20 de jan – 18 de fev","rulingPlanet":"Urano","summary":"O pensamento independente e a visão coletiva guiam o Aquário a derramar novas ideias no mundo.","originStory":"Aquário está ligado a Ganimedes, o copeiro cujo vaso trouxe água para os deuses e, simbolicamente, conhecimento para a humanidade. Embora sua imagem carregue água, o signo pertence ao ar: ideias, sistemas e renovação compartilhados para o bem comum.","traits":["Original","Independente","Humanitário","Inventivo"],"strengths":["Inovação","Objetividade","Visão comunitária"],"challenges":["Desapego","Hábitos contrários","Opiniões fixas"],"compatibleSigns":["Gêmeos","Libra","Sagitário"],"reflectionPrompt":"Deixe sua diferença servir para a conexão em vez da distância."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'day', 'pt-BR', '{"overview":"Hoje favorece um passo claro e intencional. Aquário se move através da energia do ar. Pensamento independente e visão coletiva guiam o Portador de Água a derramar novas ideias no mundo.","love":"No amor hoje, escolha a presença em vez da suposição. Seus dons de inovação, objetividade e visão comunitária podem ajudá-lo a se conectar sem precisar atuar.","career":"No trabalho, complete a tarefa mais significativa antes de buscar um novo impulso. Use original, independente, humanitário, inventivo como ferramentas, não como expectativas que você deve satisfazer de uma só vez.","finance":"Mantenha as escolhas financeiras de hoje simples e fundamentadas. Observe quando o distanciamento, hábitos contrários ou opiniões fixas começam a influenciar uma decisão prática.","wellbeing":"Uma pequena pausa pode redefinir sua energia. Deixe sua diferença servir à conexão em vez de à distância.","guidance":"Antes que o dia acabe, lembre-se: Deixe sua diferença servir à conexão em vez de à distância."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'week', 'pt-BR', '{"overview":"Esta semana se desenvolve por meio de escolhas constantes ao invés de um momento dramático. Aquário se move através da energia do ar. Pensamento independente e visão coletiva guiam o Portador de Água a trazer novas ideias ao mundo.","love":"Os relacionamentos se beneficiam de uma conversa que abre espaço tanto para a honestidade quanto para a cordialidade. Seus dons de inovação, objetividade e visão comunitária podem ajudá-lo a se conectar sem precisar atuar.","career":"Seu melhor progresso profissional vem de escolher uma prioridade e proteger tempo para ela. Use original, independente, humanitário, inventivo como ferramentas, não como expectativas que você deve satisfazer de uma só vez.","finance":"Revise o padrão por trás dos seus gastos antes de fazer um compromisso maior. Observe quando o distanciamento, hábitos contrários, opiniões fixas começam a influenciar uma decisão prática.","wellbeing":"Equilibre o movimento com recuperação genuína ao longo da semana. Deixe sua diferença servir à conexão em vez de ao afastamento.","guidance":"Deixe esta pergunta guiar a semana: Deixe sua diferença servir à conexão em vez da distância."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'year', 'pt-BR', '{"overview":"Este ano convida ao crescimento paciente ao redor da identidade, propósito e da forma como você usa sua energia. Aquário se move através da energia do ar. Pensamento independente e visão coletiva guiam o Aquariano a derramar novas ideias no mundo.","love":"O amor se aprofunda quando você pratica a consistência e permite que a conexão evolua no ritmo humano. Seus dons de inovação, objetividade, visão comunitária podem ajudá-lo a se conectar sem precisar se exibir.","career":"O trabalho de longo prazo se torna mais forte quando a ambição é combinada com uma estrutura que você pode sustentar. Use original, independente, humanitário, inventivo como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Construa confiança financeira por meio de hábitos repetíveis em vez de previsões perfeitas. Observe quando o distanciamento, hábitos contrários, opiniões fixas começam a influenciar uma decisão prática.","wellbeing":"Trate o bem-estar como uma base para a vida que você está construindo, e não como uma recompensa depois de terminá-la. Deixe sua diferença servir à conexão, e não ao afastamento.","guidance":"Volte a esta bússola ao longo do ano: Deixe sua diferença servir à conexão em vez da distância."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('pisces', 'pt-BR', '{"name":"Peixes","dateRange":"19 de fev – 20 de mar","rulingPlanet":"Netuno","summary":"Compaixão e imaginação guiam os Peixes entre intuição, sonhos e sentimentos compartilhados.","originStory":"Peixes lembra Afrodite e Eros tornando-se peixes e se prendendo juntos para escapar de Tifão. O vínculo entre os dois peixes representa devoção, identidade fluida, sensibilidade espiritual e encontrar unidade enquanto se move por correntes cambiantes.","traits":["Compassivo","Imaginativo","Intuitivo","Gentil"],"strengths":["Empatia","Criatividade","Insight espiritual"],"challenges":["Evasão","Limites confusos","Absorvendo as emoções dos outros"],"compatibleSigns":["Câncer","Escorpião","Capricórnio"],"reflectionPrompt":"Honre sua sensibilidade com limites fortes o suficiente para protegê-la."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'day', 'pt-BR', '{"overview":"Hoje favorece um passo claro e intencional. Peixes se move através da energia da água. Compaixão e imaginação guiam os Peixes entre intuição, sonhos e sentimentos compartilhados.","love":"No amor hoje, escolha presença em vez de suposições. Seus dons de empatia, criatividade, percepção espiritual podem ajudá-lo a se conectar sem precisar se exibir.","career":"No trabalho, complete a tarefa mais significativa antes de buscar um novo impulso. Use compassivo, imaginativo, intuitivo, gentil como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Mantenha as escolhas financeiras de hoje simples e fundamentadas. Perceba quando o escapismo, limites confusos, absorver as emoções dos outros começam a influenciar uma decisão prática.","wellbeing":"Uma pequena pausa pode redefinir sua energia. Honre sua sensibilidade com limites fortes o suficiente para protegê-la.","guidance":"Antes que o dia acabe, lembre-se: Honre sua sensibilidade com limites fortes o suficiente para protegê-la."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'week', 'pt-BR', '{"overview":"Esta semana se desenvolve por meio de escolhas constantes, em vez de um momento dramático. Peixes se move através da energia da água. Compaixão e imaginação guiam os peixes entre a intuição, os sonhos e o sentimento compartilhado.","love":"Os relacionamentos se beneficiam de uma conversa que dê espaço tanto para a honestidade quanto para a cordialidade. Seus dons de empatia, criatividade e percepção espiritual podem ajudá-lo a se conectar sem precisar atuar.","career":"Seu melhor progresso profissional vem de escolher uma prioridade e proteger tempo para ela. Use compassivo, imaginativo, intuitivo, gentil como ferramentas, não como expectativas que você deve satisfazer todas de uma vez.","finance":"Revise o padrão por trás dos seus gastos antes de fazer um compromisso maior. Observe quando o escapismo, fronteiras confusas, absorver as emoções dos outros começa a influenciar uma decisão prática.","wellbeing":"Equilibre o movimento com recuperação genuína ao longo da semana. Honre sua sensibilidade com limites fortes o suficiente para protegê-la.","guidance":"Deixe esta pergunta guiar a semana: Honre sua sensibilidade com limites fortes o bastante para protegê-la."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'year', 'pt-BR', '{"overview":"Este ano convida ao crescimento paciente em torno da identidade, propósito e da forma como você usa sua energia. Peixes se move através da energia da água. Compaixão e imaginação guiam os Peixes entre intuição, sonhos e sentimentos compartilhados.","love":"O amor se aprofunda quando você pratica consistência e permite que a conexão evolua em um ritmo humano. Seus dons de empatia, criatividade e percepção espiritual podem ajudá-lo a se conectar sem precisar atuar.","career":"O trabalho a longo prazo se torna mais forte quando a ambição é combinada com uma estrutura que você pode sustentar. Use compassivo, imaginativo, intuitivo, gentil como ferramentas, não como expectativas que você deve satisfazer de uma vez.","finance":"Construa confiança financeira por meio de hábitos repetíveis em vez de previsões perfeitas. Observe quando o escapismo, limites borrados, absorver as emoções dos outros começam a influenciar uma decisão prática.","wellbeing":"Trate o bem-estar como uma base para a vida que você está construindo, não como uma recompensa depois de terminá-la. Honre sua sensibilidade com limites fortes o suficiente para protegê-la.","guidance":"Volte a esta bússola ao longo do ano: Honre sua sensibilidade com limites fortes o suficiente para protegê-la."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('fool', 'id', '{"name":"The Fool","meaning":"Sebuah halaman kosong dan lompatan iman — sebuah perjalanan baru dimulai dengan hati yang terbuka.","advice":"Percayalah pada jalur di depan Anda dan ambil langkah pertama itu, bahkan tanpa semua jawaban.","yesNoMeaning":"Sebuah awal baru jarang membawa jawaban yang pasti — hasilnya tergantung pada langkah yang kamu ambil."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('magician', 'id', '{"name":"Sang Penyihir","meaning":"Anda memegang semua alat yang Anda butuhkan. Fokuskan kehendak Anda dan ubah niat menjadi tindakan.","advice":"Gunakan keterampilan dan sumber daya Anda dengan sengaja — sekaranglah waktunya untuk mewujudkannya.","yesNoMeaning":"Anda sudah memegang semua yang dibutuhkan — energi mendukung bergerak maju dengan fokus."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('high-priestess', 'id', '{"name":"Pendeta Agung Perempuan","meaning":"Kebijaksanaan yang tenang tersembunyi di bawah permukaan. Dengarkan intuisi dan suara batinmu.","advice":"Berhenti sejenak, masuk ke dalam diri, dan biarkan nalurimu membimbingmu sebelum bertindak.","yesNoMeaning":"Jawabannya tersembunyi di bawah permukaan untuk saat ini — percayai intuisi Anda daripada memaksakan jawaban ya atau tidak yang jelas."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('empress', 'id', '{"name":"The Empress","meaning":"Pertumbuhan, kelimpahan, dan energi yang mendampingi Anda. Biarkan keindahan dan perawatan berkembang.","advice":"Bersabarlah dan murah hati — ciptakan dengan cinta dan biarkan segala sesuatu matang secara alami.","yesNoMeaning":"Pertumbuhan, kelimpahan, dan energi yang mendukung kembali keinginan Anda — jawabannya adalah ya yang tenang."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('emperor', 'id', '{"name":"The Emperor","meaning":"Struktur, otoritas, dan kepemimpinan yang stabil. Bangun di atas dasar yang kokoh dengan disiplin.","advice":"Ambil kendali dengan rencana yang jelas; batasan yang tegas membawa kestabilan yang langgeng.","yesNoMeaning":"Struktur, otoritas, dan disiplin yang konsisten mendukung jawaban ''ya'' dengan percaya diri."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hierophant', 'id', '{"name":"Hierofant","meaning":"Tradisi dan panduan yang dipercaya menawarkan jalur yang dapat diandalkan. Belajar dari apa yang telah terjadi sebelumnya.","advice":"Ikuti kebijaksanaan yang sudah ada dan carilah nasihat dari mereka yang Anda percayai.","yesNoMeaning":"Tradisi dan panduan yang dipercaya menunjukkan jawaban yang dapat diandalkan — bersandar pada apa yang telah terbukti."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('lovers', 'id', '{"name":"Para Kekasih","meaning":"Ikatan yang berarti atau pilihan penting. Ikuti apa yang benar-benar dihargai oleh hati Anda.","advice":"Pilih dengan kejujuran dan keselarasan — koneksi akan lebih dalam saat Anda tulus.","yesNoMeaning":"Hati dan nilai-nilai Anda selaras di sini — jawabannya adalah ya, terutama ketika Anda memilih dengan kejujuran."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('chariot', 'id', '{"name":"The Chariot","meaning":"Kemauan dan momentum membawa Anda maju. Tetap fokus dan Anda akan berhasil.","advice":"Tetap fokus pada tujuan dan kendalikan dengan percaya diri melalui setiap rintangan.","yesNoMeaning":"Kemauan dan momentum ada di pihak Anda — sebuah ya yang terfokus, selama Anda tetap berkomitmen."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('strength', 'id', '{"name":"Kekuatan","meaning":"Kekuatan sejati adalah lembut — kesabaran, keberanian, dan kasih sayang menaklukkan setiap tantangan.","advice":"Pimpin dengan kekuatan yang tenang; tangan yang lembut sering kali adalah yang terkuat.","yesNoMeaning":"Keberanian lembut dan ketekunan yang sabar membuat ini menjadi ya — pimpin dengan tenang, bukan dengan paksa."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hermit', 'id', '{"name":"Pertapa","meaning":"Saatnya mundur sejenak dan mencari kejernihan batin. Kesendirian sekarang membawa jawaban yang lebih mendalam.","advice":"Berbalik ke dalam, renungkan, dan biarkan keheningan mengungkap apa yang benar-benar Anda butuhkan.","yesNoMeaning":"Belum — kartu meminta kamu untuk mundur sejenak dan menemukan kejelasan batin sebelum bertindak."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('wheel-of-fortune', 'id', '{"name":"Roda Keberuntungan","meaning":"Peruntungan berubah dan siklus bergeser. Apa yang berubah sekarang adalah bagian dari ritme yang lebih besar.","advice":"Naik gelombang dengan fleksibilitas — sambut perubahan, baik atau buruk.","yesNoMeaning":"Peruntungan sedang berbalik — hasilnya tergantung bagaimana Anda menghadapi perubahan tersebut daripada jawaban ya atau tidak yang tetap."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('justice', 'id', '{"name":"Keadilan","meaning":"Kebenaran dan keadilan akan menang. Sebab dan akibat sekarang menjadi seimbang.","advice":"Bertindaklah dengan jujur dan timbang kedua sisi; timbangan akan menyeimbangkan dengan adil.","yesNoMeaning":"Timbangan masih menimbang — jawaban yang adil tergantung pada fakta dan kejujuran Anda."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hanged-man', 'id', '{"name":"Orang yang Digantung","meaning":"Jeda yang diperlukan. Lepaskan kontrol dan lihat situasi dari sudut pandang baru.","advice":"Berhenti mendorong — menyerahlah pada momen dan biarkan perspektif baru muncul.","yesNoMeaning":"Berhenti sejenak diperlukan terlebih dahulu — memaksakan ini sekarang hanya akan menahan jawaban yang lebih jelas."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('death', 'id', '{"name":"Kematian","meaning":"Sebuah akhir membuka jalan untuk pembaruan. Lepaskan apa yang telah habis masa gunanya.","advice":"Lepaskan tanpa penyesalan; transformasi yang mendalam membuka pintu baru.","yesNoMeaning":"Sebuah akhir sedang membuka jalan — jalur saat ini menutup sehingga yang baru dapat dimulai."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('temperance', 'id', '{"name":"Kesederhanaan","meaning":"Keseimbangan dan kesabaran membawa harmoni. Gabungkan hal-hal yang berlawanan dengan anggun.","advice":"Bergeraklah dengan moderasi dan tetap tenang — langkah yang mantap mencapai tujuan.","yesNoMeaning":"Keseimbangan dan kesabaran membawa harmoni — sebuah ''ya'' yang terukur, diambil satu langkah mantap dalam satu waktu."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('devil', 'id', '{"name":"The Devil","meaning":"Waspadalah terhadap keterikatan, godaan, atau pola yang membelenggu. Kenali rantainya.","advice":"Sebutkan apa yang menahanmu dan pulihkan kebebasanmu — rantai hanya mengikat jika kamu membiarkannya.","yesNoMeaning":"Keterikatan atau pola yang mengikat menghalangi — belum, sampai rantai itu dinamai dan diputus."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('tower', 'id', '{"name":"Menara","meaning":"Perubahan tiba-tiba menghancurkan yang palsu dan mengungkapkan kebenaran. Apa yang jatuh tidak pernah dimaksudkan untuk berdiri.","advice":"Sambut gejolak; dari reruntuhan, fondasi yang lebih jelas bisa dibangun.","yesNoMeaning":"Perubahan tiba-tiba menghancurkan yang lama — tanah harus menetap sebelum kata ya yang mantap bisa terjadi."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('star', 'id', '{"name":"Bintang","meaning":"Harapan, penyembuhan, dan inspirasi yang tenang memperbarui semangat Anda setelah badai.","advice":"Percayalah pada cahaya di depan dan teruslah percaya — keinginan Anda ada dalam jangkauan.","yesNoMeaning":"Harapan dan pembaruan yang tenang menunjukkan ya — percayalah pada cahaya di depan dan pertahankan harapan Anda tetap hidup."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('moon', 'id', '{"name":"Bulan","meaning":"Ilusi dan ketidakpastian mengaburkan jalan. Percayalah pada intuisi Anda, bukan penampilan.","advice":"Perlambat dan pandang lebih dalam; kejelasan akan datang saat kabut menghilang.","yesNoMeaning":"Ilusi dan ketidakpastian mengaburkan jalan — jawabannya tidak jelas sampai Anda melihat di balik penampilan."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('sun', 'id', '{"name":"Matahari","meaning":"Kegembiraan, kesuksesan, dan kejernihan yang bersinar. Segalanya cerah dan penuh kehidupan.","advice":"Rayakan dan bersinarlah — energi positif menarik hasil yang kamu inginkan.","yesNoMeaning":"Kegembiraan dan kejernihan yang bersinar menegaskan jawaban ya yang cerah — semuanya bekerja sesuai keinginanmu."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('judgement', 'id', '{"name":"Pengadilan","meaning":"Seruan untuk bangkit, memperbarui, dan jujur pada diri sendiri. Sebuah putusan tentang kesadaran.","advice":"Jawablah panggilan dengan keberanian; maafkan masa lalu dan melangkahlah ke bab berikutnya dalam hidupmu.","yesNoMeaning":"Seruan untuk bangkit dan memperbarui — ya, terutama setelah Anda memaafkan masa lalu dan menjawab dengan jujur."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('world', 'id', '{"name":"Dunia","meaning":"Penyelesaian dan pemenuhan — sebuah siklus berakhir dalam kesempurnaan utuh.","advice":"Rayakan apa yang telah Anda capai; pintu terbuka ke dunia yang lebih luas.","yesNoMeaning":"Penyelesaian dan kesempurnaan menandai ini sebagai ya yang terpenuhi — siklus berakhir menguntungkan Anda."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-wands', 'id', '{"name":"As Tongkat","meaning":"Sebuah percikan inspirasi membuka jalur kreatif yang berani.","advice":"Mulailah saat energi masih segar dan berikan ide itu langkah pertama yang nyata.","yesNoMeaning":"The Ace of Wands condong ke ya: mulai ketika energinya masih segar dan berikan ide itu langkah pertama yang nyata."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-wands', 'id', '{"name":"Dua Tongkat","meaning":"Masa depan terbentuk melalui perencanaan dan pilihan arah.","advice":"Lihat melampaui apa yang sudah dikenal, kemudian berkomitmen pada jalan dengan ruang untuk tumbuh.","yesNoMeaning":"Dua Tongkat tetap bersifat kondisional: lihat melampaui apa yang sudah dikenal, lalu berkomitmen pada jalan dengan ruang untuk berkembang."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-wands', 'id', '{"name":"Tiga Tongkat","meaning":"Upaya awal berkembang seiring peluang dan cakrawala yang lebih luas muncul.","advice":"Terus membangun dan bersiaplah menerima respons yang ditarik oleh pekerjaanmu.","yesNoMeaning":"Tiga Tongkat condong ya: teruslah membangun dan bersiaplah untuk menghadapi respons yang ditarik oleh pekerjaanmu."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-wands', 'id', '{"name":"Empat Tongkat","meaning":"Stabilitas, sambutan, dan perayaan bersama menciptakan fondasi yang kuat.","advice":"Tandai tonggak sejarah dan biarkan orang-orang yang mendukung berbagi dalam hal itu.","yesNoMeaning":"Empat Tong condong ke ya: tandai pencapaian dan biarkan orang-orang yang mendukung ikut merayakannya."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-wands', 'id', '{"name":"Lima Tongkat","meaning":"Tujuan yang bersaing menciptakan gesekan, kebisingan, atau ujian kepercayaan.","advice":"Ubah persaingan menjadi praktik yang berguna dan tolak konflik yang tidak memiliki tujuan.","yesNoMeaning":"Lima Tongkat tetap bersyarat: ubah persaingan menjadi latihan yang berguna dan tolak konflik yang tidak memiliki tujuan."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-wands', 'id', '{"name":"Enam Tongkat","meaning":"Pengakuan mengikuti usaha yang tekun dan kemajuan yang terlihat.","advice":"Terimalah dorongan itu, tetapi pertahankan kepercayaan diri Anda terkait dengan kerja jujur.","yesNoMeaning":"Enam Tongkat condong ya: terima dorongan, tetapi tetap pertahankan kepercayaan diri yang terikat pada kerja jujur."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-wands', 'id', '{"name":"Tujuh Tongkat","meaning":"Anda mempertahankan posisi berharga saat tekanan menguji keteguhan Anda.","advice":"Pertahankan apa yang penting dengan batasan yang jelas daripada menghadapi setiap tantangan.","yesNoMeaning":"Tujuh Tongkat condong ke ya: pertahankan apa yang penting dengan batasan yang jelas daripada menghadapi setiap tantangan."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-wands', 'id', '{"name":"Delapan Tongkat","meaning":"Peristiwa meningkat, pesan tiba, dan momentum membersihkan keterlambatan.","advice":"Bertindaklah segera dan jaga komunikasi tetap langsung selama jalannya terbuka.","yesNoMeaning":"The Eight of Wands condong ke ya: bertindaklah dengan cepat dan jaga komunikasi tetap langsung selagi jalan terbuka."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-wands', 'id', '{"name":"Sembilan Tongkat","meaning":"Ketahanan kuat, meskipun ketegangan masa lalu membuat Anda waspada.","advice":"Lindungi energimu dan ambil langkah berikutnya tanpa mengharapkan setiap luka terulang.","yesNoMeaning":"Sembilan Tongkat tetap bersyarat: lindungi energimu dan ambil langkah berikutnya tanpa mengharapkan setiap luka terulang."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-wands', 'id', '{"name":"Sepuluh Tongkat","meaning":"Tanggung jawab telah menjadi berat dan kesuksesan sekarang membawa beban.","advice":"Mendelegasikan, menyederhanakan, dan meletakkan pekerjaan yang tidak lagi benar-benar milikmu.","yesNoMeaning":"Sepuluh Tongkat condong tidak: delegasikan, sederhanakan, dan letakkan pekerjaan yang tidak benar-benar menjadi milikmu lagi."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-wands', 'id', '{"name":"Halaman Tongkat","meaning":"Rasa ingin tahu membawa pesan yang hidup, eksperimen, atau minat kreatif baru.","advice":"Jelajahi dengan keberanian dan biarkan energi pemula mengajarimu melalui tindakan.","yesNoMeaning":"Page of Wands condong ke ya: jelajahi dengan keberanian dan biarkan energi pemula mengajarkanmu melalui tindakan."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-wands', 'id', '{"name":"Kesatria Tongkat","meaning":"Gairah bergerak cepat, membawa petualangan dan kemungkinan ketidaksabaran.","advice":"Manfaatkan momentum, tetapi pilih arah sebelum kecepatan menyebar upaya Anda.","yesNoMeaning":"Ksatria Tongkat tetap bersyarat: gunakan momentum, tetapi pilih arah sebelum kecepatan menyebarkan usahamu."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-wands', 'id', '{"name":"Ratu Tongkat","meaning":"Kepercayaan diri yang hangat dan kemandirian kreatif menarik orang lain menuju visi Anda.","advice":"Percayalah pada kehadiran Anda, dorong orang lain, dan jangan kurangi ambisi Anda.","yesNoMeaning":"Ratu Tongkat condong ya: percayai kehadiranmu, dorong orang lain, dan jangan kecilkan ambisimu."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-wands', 'id', '{"name":"Raja Tongkat","meaning":"Visi matang mengubah inspirasi menjadi kepemimpinan yang tegas dan etis.","advice":"Pimpin dari tujuan yang lebih besar dan beri ruang bagi orang lain untuk berkontribusi.","yesNoMeaning":"Raja Tong condong ke ya: pimpin dengan tujuan yang lebih besar dan beri ruang bagi orang lain untuk berkontribusi."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-cups', 'id', '{"name":"As Piala","meaning":"Hati terbuka untuk kasih sayang baru, belas kasih, dan pembaruan emosional.","advice":"Terima perasaan itu dengan jujur dan biarkan perhatian mengalir tanpa memaksakan hasil.","yesNoMeaning":"Ace of Cups condong ya: terima perasaan dengan jujur dan biarkan kepedulian mengalir tanpa memaksakan hasil."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-cups', 'id', '{"name":"Dua Piala","meaning":"Pengakuan bersama menciptakan kemitraan, ketertarikan, atau kesepakatan yang tulus.","advice":"Temui orang lain sebagai setara dan berbicaralah dari hati.","yesNoMeaning":"Dua Cawan condong ke ya: temui orang lain sebagai setara dan berbicaralah dari hati."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-cups', 'id', '{"name":"Tiga Piala","meaning":"Persahabatan, komunitas, dan kegembiraan yang dibagikan membawa dukungan emosional.","advice":"Rayakan bersama dan ingat siapa yang benar-benar hadir untuk Anda.","yesNoMeaning":"Tiga Piala condong ya: rayakan bersama dan ingat siapa yang benar-benar hadir untukmu."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-cups', 'id', '{"name":"Empat Gelas","meaning":"Penarikan emosional membuat hadiah yang tersedia sulit diperhatikan.","advice":"Jeda perbandingan dan lihat lagi apa yang sedang ditawarkan dengan tenang.","yesNoMeaning":"Empat Cawan condong tidak: berhentilah membandingkan dan lihat lagi apa yang dengan tenang ditawarkan."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-cups', 'id', '{"name":"Lima Piala","meaning":"Kehilangan menarik perhatian pada apa yang tumpah sementara sesuatu yang bermakna tetap ada.","advice":"Hormati kekecewaan, lalu beralih ke dukungan yang masih ada.","yesNoMeaning":"Lima Cawan condong tidak: hargai kekecewaan, lalu beralihlah pada dukungan yang masih ada."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-cups', 'id', '{"name":"Enam Cangkir","meaning":"Memori, kepolosan, atau ikatan yang akrab kembali dengan hangat yang lembut.","advice":"Sambut kebaikan masa lalu tanpa berpura-pura bahwa Anda harus hidup di sana lagi.","yesNoMeaning":"Enam Cawan condong ke ya: sambutlah kebaikan masa lalu tanpa berpura-pura bahwa kamu harus hidup di sana lagi."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-cups', 'id', '{"name":"Tujuh Cawan","meaning":"Banyak kemungkinan menarik yang membingungkan perbedaan antara visi dan ilusi.","advice":"Persempit pilihan dan uji satu impian terhadap kenyataan sebelum berkomitmen.","yesNoMeaning":"Tujuh Cawan belum jelas: persempit pilihan dan uji satu mimpi terhadap kenyataan sebelum berkomitmen."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-cups', 'id', '{"name":"Delapan Piala","meaning":"Sebuah situasi yang dulunya berarti tidak lagi memberi nutrisi bagi hati.","advice":"Pergi dengan jujur dan bergerak menuju pemenuhan yang lebih dalam yang kini Anda butuhkan.","yesNoMeaning":"The Eight of Cups condong ke tidak: pergi dengan kejujuran dan bergerak menuju pemenuhan yang lebih dalam yang sekarang Anda butuhkan."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-cups', 'id', '{"name":"Sembilan Piala","meaning":"Kepuasan dan rasa syukur membuat keinginan dari hati terasa dekat.","advice":"Nikmati apa yang ada di sini dan tanyakan apakah keinginan itu juga melayani nilai-nilai terdalam Anda.","yesNoMeaning":"Sembilan Piala condong ya: nikmati apa yang ada dan tanyakan apakah keinginan itu juga sesuai dengan nilai-nilai terdalammu."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-cups', 'id', '{"name":"Sepuluh Piala","meaning":"Harmoni emosional, rasa memiliki, dan ikatan yang langgeng melingkupi rumah.","advice":"Rawat ikatan yang membuat kebahagiaan berkelanjutan dan bisa dibagikan.","yesNoMeaning":"Sepuluh Piala condong ya: rawat ikatan yang membuat kebahagiaan berkelanjutan dan dapat dibagikan."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-cups', 'id', '{"name":"Halaman Cangkir","meaning":"Pesan lembut atau penemuan intuitif mengundang keterbukaan emosional.","advice":"Tetap penasaran terhadap perasaan dan tanggapi dengan tulus daripada berasumsi.","yesNoMeaning":"Page of Cups tetap bersyarat: tetaplah ingin tahu tentang perasaan dan tanggapi dengan ketulusan daripada asumsi."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-cups', 'id', '{"name":"Kesatria Cawan","meaning":"Romansa, imajinasi, atau suatu ideal menarik hati ke depan.","advice":"Ikuti undangan, tetapi tetap berpijak pada kenyataan seiring janji-janji terungkap.","yesNoMeaning":"Ksatria Piala condong ke ya: ikuti undangan, tetapi tetap berpijak pada kenyataan saat janji-janji terwujud."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-cups', 'id', '{"name":"Ratu Cawan","meaning":"Empati dan intuisi yang mendalam menciptakan ruang tenang untuk kebenaran.","advice":"Dengarkan dengan penuh kasih sambil menjaga batas yang membuat perhatian tetap sehat.","yesNoMeaning":"Queen of Cups condong ke ya: dengarkan dengan penuh kasih sambil menjaga batasan yang membuat perhatian tetap sehat."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-cups', 'id', '{"name":"Raja Cawan","meaning":"Kematangan emosional menstabilkan perasaan kuat tanpa menekannya.","advice":"Responlah dengan kasih sayang dan pengendalian diri, terutama ketika orang lain bereaksi.","yesNoMeaning":"Raja Piala condong ke ya: tanggapi dengan kasih sayang dan pengendalian diri, terutama ketika orang lain bereaksi."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-swords', 'id', '{"name":"As Pedang","meaning":"Wawasan yang bersih menembus kebingungan dan mengungkap kebenaran baru.","advice":"Sebutkan masalah dengan jelas dan gunakan kejelasan untuk mendukung keputusan yang adil.","yesNoMeaning":"The Ace of Swords condong ke ya: sebutkan masalah dengan jelas dan gunakan kejelasan untuk melayani keputusan yang adil."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-swords', 'id', '{"name":"Dua Pedang","meaning":"Kebuntuan yang dijaga menunda sebuah pilihan yang tidak dapat tetap tergantung selamanya.","advice":"Lepaskan penutup mata dengan lembut, kumpulkan fakta yang hilang, dan putuskan dari keseimbangan.","yesNoMeaning":"Dua Pedang belum jelas: lepaskan penutup mata dengan lembut, kumpulkan fakta yang hilang, dan putuskan dari keseimbangan."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-swords', 'id', '{"name":"Tiga Pedang","meaning":"Kebenaran yang menyakitkan, perpisahan, atau kekecewaan meminta untuk diakui.","advice":"Biarkan perasaan itu mengalir melalui dirimu dan hindari mengubah rasa sakit menjadi cerita yang permanen.","yesNoMeaning":"Tiga Pedang tidak condong: biarkan perasaan itu mengalir melalui kamu dan hindari mengubah rasa sakit menjadi cerita yang permanen."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-swords', 'id', '{"name":"Empat Pedang","meaning":"Istirahat dan ketenangan pikiran dibutuhkan setelah tekanan atau konflik.","advice":"Berhenti sejenak sebelum menjawab; pemulihan produktif ketika mengembalikan pikiran yang jernih.","yesNoMeaning":"Empat Pedang condong tidak: berhenti sejenak sebelum menjawab; pemulihan menjadi produktif ketika mengembalikan pikiran yang jernih."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-swords', 'id', '{"name":"Lima Pedang","meaning":"Konflik mungkin menghasilkan kemenangan kosong atau meninggalkan kepercayaan yang rusak.","advice":"Pilih martabat daripada menang dan jauhi taktik yang terlalu mahal.","yesNoMeaning":"Lima Pedang condong tidak: pilih martabat daripada kemenangan dan hindari taktik yang terlalu mahal harganya."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-swords', 'id', '{"name":"Enam Pedang","meaning":"Sebuah jalan sulit bergerak perlahan menuju kondisi yang lebih tenang.","advice":"Ambil apa yang telah kamu pelajari, terima dukungan, dan terus bergerak menjauh dari kekacauan.","yesNoMeaning":"Enam Pedang condong ya: ambil apa yang telah Anda pelajari, terima dukungan, dan terus menjauh dari kekacauan."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-swords', 'id', '{"name":"Tujuh Pedang","meaning":"Strategi, kerahasiaan, atau penghindaran memperumit jalan.","advice":"Bertindaklah dengan cerdik tetapi transparan; jalan pintas yang mengkhianati kepercayaan akan kembali sebagai masalah.","yesNoMeaning":"Seven of Swords condong ke tidak: bertindaklah cerdik tetapi transparan; jalan pintas yang mengkhianati kepercayaan akan kembali sebagai masalah."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-swords', 'id', '{"name":"Delapan Pedang","meaning":"Ketakutan dan keyakinan yang membatasi membuat opsi yang tersedia sulit dilihat.","advice":"Pertanyakan pikiran yang mengatakan kamu terjebak dan ambil satu tindakan kecil untuk membebaskan diri.","yesNoMeaning":"The Eight of Swords condong ke tidak: pertanyakan pikiran yang mengatakan Anda terjebak dan ambil satu tindakan kecil untuk membebaskan diri."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-swords', 'id', '{"name":"Sembilan Pedang","meaning":"Kecemasan memperbesar bahaya dalam kegelapan dan melelahkan pikiran.","advice":"Bawa rasa takut ke cahaya hari, cari dukungan, dan pisahkan fakta dari hasil yang dibayangkan.","yesNoMeaning":"Sembilan Pedang condong tidak: bawa ketakutan ke cahaya, cari dukungan, dan pisahkan fakta dari hasil yang dibayangkan."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-swords', 'id', '{"name":"Sepuluh Pedang","meaning":"Siklus yang menyakitkan mencapai batas akhirnya dan tidak dapat terus berlanjut tanpa perubahan.","advice":"Terimalah akhir itu, lindungi pemulihan Anda, dan biarkan awal yang berbeda muncul.","yesNoMeaning":"Sepuluh Pedang condong tidak: terima akhir, lindungi pemulihanmu, dan biarkan awal yang berbeda muncul."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-swords', 'id', '{"name":"Halaman Pedang","meaning":"Rasa ingin tahu waspada mencari fakta, mengajukan pertanyaan, dan memperhatikan perubahan.","advice":"Riset dengan cermat dan berbicaralah dengan presisi daripada bereaksi terhadap setiap sinyal.","yesNoMeaning":"Halaman Pedang tetap bersifat kondisional: teliti dengan cermat dan berbicaralah dengan tepat daripada bereaksi terhadap setiap sinyal."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-swords', 'id', '{"name":"Kesatria Pedang","meaning":"Intelek yang fokus bergerak cepat dan menghadapi rintangan secara langsung.","advice":"Maju dengan keberanian, tetapi cukup lambat untuk mendengar apa yang mungkin terlewatkan oleh kepastian Anda.","yesNoMeaning":"Ksatria Pedang tetap bersyarat: maju dengan keberanian, tetapi cukup lambat untuk mendengar apa yang mungkin terlewat oleh keyakinanmu."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-swords', 'id', '{"name":"Ratu Pedang","meaning":"Persepsi yang jelas dan batasan yang jujur menghilangkan kebingungan.","advice":"Katakan yang benar dengan penuh kasih dan biarkan pengalaman mengasah, bukan mengeraskan, dirimu.","yesNoMeaning":"Queen of Swords condong ke ya: katakan apa yang benar dengan kasih dan biarkan pengalaman menajamkan, bukan mengeraskan, dirimu."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-swords', 'id', '{"name":"Raja Pedang","meaning":"Alasan, keadilan, dan penilaian yang disiplin membimbing keputusan yang berakibat.","advice":"Gunakan bukti, tentukan standar, dan jangan biarkan bias pribadi mempengaruhi putusan.","yesNoMeaning":"Raja Pedang condong ke ya: gunakan bukti, tetapkan standar, dan jangan biarkan bias pribadi mempengaruhi putusan."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-pentacles', 'id', '{"name":"As Koin","meaning":"Kesempatan nyata menawarkan benih kemakmuran, pekerjaan, atau kesejahteraan.","advice":"Dasarkan peluang pada rencana praktis dan rawat secara konsisten.","yesNoMeaning":"Ace of Pentacles condong ya: tanamkan kesempatan dalam rencana yang praktis dan rawat secara konsisten."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-pentacles', 'id', '{"name":"Dua Pentakel","meaning":"Beberapa prioritas bergerak sekaligus dan memerlukan keseimbangan yang fleksibel.","advice":"Sesuaikan ritme, lindungi hal-hal penting, dan hindari berjanji lebih dari yang bisa Anda tanggung.","yesNoMeaning":"Dua Pentakel tetap bersifat kondisional: sesuaikan ritme, lindungi hal-hal penting, dan hindari berjanji lebih dari yang dapat Anda tanggung."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-pentacles', 'id', '{"name":"Tiga Koin","meaning":"Keterampilan berkembang melalui kolaborasi, umpan balik, dan pengerjaan yang cermat.","advice":"Kontribusikan kekuatan Anda, hormati keahlian, dan bangun hingga standar bersama.","yesNoMeaning":"Tiga Pentakel condong ke ya: kontribusikan kekuatanmu, hormati keahlian, dan bangun sesuai standar bersama."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-pentacles', 'id', '{"name":"Empat Pentakel","meaning":"Memegang erat keamanan dapat mempertahankan sumber daya tetapi membatasi aliran yang sehat.","advice":"Lindungi apa yang penting tanpa membiarkan rasa takut menentukan setiap keputusanmu.","yesNoMeaning":"Empat Pentakel tetap bersyarat: lindungi apa yang penting tanpa membiarkan ketakutan mengontrol setiap keputusanmu."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-pentacles', 'id', '{"name":"Lima Pentakel","meaning":"Ketegangan atau pengecualian material menimbulkan kekhawatiran dan rasa kekurangan.","advice":"Minta bantuan praktis dan perhatikan pintu yang telah dibuat mudah untuk diabaikan oleh kesulitan.","yesNoMeaning":"Lima Pentakel condong tidak: mintalah bantuan praktis dan perhatikan pintu yang sulit yang mungkin terlewatkan karena kesulitan."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-pentacles', 'id', '{"name":"Enam Pentakel","meaning":"Sumber daya dipertukarkan, menimbulkan pertanyaan tentang kemurahan hati, kekuasaan, dan keadilan.","advice":"Berikan atau terima dengan ketentuan yang jelas sehingga dukungan menjaga martabat di kedua sisi.","yesNoMeaning":"Enam Pentakel condong ke ya: memberi atau menerima dengan ketentuan yang jelas sehingga dukungan menjaga martabat di kedua sisi."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-pentacles', 'id', '{"name":"Tujuh Pentakel","meaning":"Investasi yang sabar mencapai titik penilaian sebelum upaya berikutnya.","advice":"Tinjau apa yang sedang berkembang, perbaiki metode, dan beri waktu untuk hasil yang berharga.","yesNoMeaning":"Tujuh Pentakel tetap bersyarat: tinjau apa yang sedang tumbuh, perbaiki metode, dan beri waktu untuk hasil yang berharga."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-pentacles', 'id', '{"name":"Delapan Koin","meaning":"Pengulangan yang fokus mengembangkan penguasaan dan hasil yang dapat diandalkan.","advice":"Latih keterampilan penting, sambut koreksi, dan biarkan kualitas terkumpul.","yesNoMeaning":"The Eight of Pentacles condong ke ya: latih keterampilan yang esensial, sambut koreksi, dan biarkan kualitas menumpuk."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-pentacles', 'id', '{"name":"Sembilan Pentakel","meaning":"Kemandirian dan kenyamanan yang dibudidayakan mencerminkan kemajuan yang disiplin.","advice":"Nikmati apa yang telah Anda bangun dan pertahankan kemandirian yang terhubung dengan rasa syukur.","yesNoMeaning":"Sembilan Koin condong ya: nikmati apa yang telah kamu bangun dan pertahankan kemandirian dengan mengaitkannya pada rasa syukur."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-pentacles', 'id', '{"name":"Sepuluh Koin","meaning":"Keamanan jangka panjang tumbuh melalui warisan, keluarga, dan fondasi yang dibagikan.","advice":"Rencanakan lebih dari sekadar kemenangan sesaat dan lindungi apa yang dapat mendukung orang lain seiring waktu.","yesNoMeaning":"Sepuluh Koin condong ya: rencanakan melampaui kemenangan langsung dan lindungi apa yang dapat mendukung orang lain seiring waktu."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-pentacles', 'id', '{"name":"Halaman Koin","meaning":"Sebuah pesan praktis mengundang studi, perencanaan, atau usaha baru yang terencana.","advice":"Pelajari dasar-dasarnya, tentukan tugas selanjutnya, dan buktikan ide melalui kerja yang konsisten.","yesNoMeaning":"Halaman Pentakel condong ke ya: pelajari dasar-dasarnya, tentukan tugas berikutnya, dan buktikan ide melalui kerja yang konsisten."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-pentacles', 'id', '{"name":"Kesatria Koin","meaning":"Usaha yang dapat diandalkan maju perlahan tetapi jarang meninggalkan tugas.","advice":"Pertahankan rutinitas jujur dan konsisten; kemajuan lebih penting daripada kegembiraan.","yesNoMeaning":"Ksatria Koin condong ke ya: jaga rutinitas tetap jujur dan konsisten; kemajuan lebih penting daripada kegembiraan."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-pentacles', 'id', '{"name":"Ratu Pentakel","meaning":"Perhatian yang cekatan menciptakan kenyamanan, kesehatan, dan kelimpahan praktis.","advice":"Rawat orang dan rencana dengan cara yang tetap berkelanjutan untukmu.","yesNoMeaning":"Queen of Pentacles condong ke ya: rawat orang dan rencana dengan cara yang tetap berkelanjutan untukmu."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-pentacles', 'id', '{"name":"Raja Koin","meaning":"Kepemimpinan material mengubah pengalaman menjadi pengelolaan yang stabil dan murah hati.","advice":"Buat pilihan jangka panjang yang bijaksana dan gunakan kesuksesan dengan bertanggung jawab.","yesNoMeaning":"Raja Koin condong ke ya: buat pilihan jangka panjang yang bijaksana dan gunakan keberhasilan secara bertanggung jawab."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aries', 'id', '{"name":"Aries","dateRange":"21 Mar – 19 Apr","rulingPlanet":"Mars","summary":"Awal yang berani dan tindakan langsung mendefinisikan Aries, yang percikannya mengubah niat menjadi momentum.","originStory":"Aries dikaitkan dengan domba emas yang menyelamatkan Phrixus dalam mitologi Yunani. Bulu domba itu kemudian menjadi hadiah bagi Jason dan Argonaut, mempertahankan tanda ini sebagai simbol keberanian, penyelamatan, dan langkah berani pertama.","traits":["Berani","Berenergi","Mandiri","Langsung"],"strengths":["Inisiatif","Percaya diri","Ketahanan"],"challenges":["Ketidaksabaran","Impulsivitas","Memulai lebih cepat daripada yang bisa dipertahankan"],"compatibleSigns":["Leo","Sagitarius","Gemini"],"reflectionPrompt":"Pilih satu awal yang berani dan beri cukup kesabaran untuk tumbuh."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'day', 'id', '{"overview":"Hari ini mendukung satu langkah yang jelas dan disengaja. Aries bergerak melalui energi api. Awal yang berani dan tindakan langsung mendefinisikan Sang Domba, yang percikannya mengubah niat menjadi momentum.","love":"Dalam cinta hari ini, pilih kehadiran daripada asumsi. Karunia inisiatif, kepercayaan diri, ketangguhanmu dapat membantumu terhubung tanpa harus tampil.","career":"Di tempat kerja, selesaikan tugas yang paling bermakna sebelum mengejar momentum baru. Gunakan keberanian, energi, kemandirian, dan ketegasan sebagai alat, bukan harapan yang harus Anda penuhi sekaligus.","finance":"Jaga pilihan uang hari ini tetap sederhana dan realistis. Perhatikan ketika ketidaksabaran, impulsif, atau memulai lebih cepat daripada yang bisa Anda pertahankan mulai memengaruhi keputusan praktis.","wellbeing":"Jeda kecil bisa mengatur ulang energi Anda. Pilih satu awal yang berani dan beri kesabaran cukup untuk berkembang.","guidance":"Sebelum hari berakhir, ingatlah: Pilihlah satu awal yang berani dan berikan kesabaran yang cukup untuk tumbuh."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'week', 'id', '{"overview":"Minggu ini berkembang melalui pilihan yang mantap daripada satu momen dramatis. Aries bergerak melalui energi api. Awal yang berani dan tindakan langsung mendefinisikan Si Domba, yang percikannya mengubah niat menjadi momentum.","love":"Hubungan mendapat manfaat dari percakapan yang memberi ruang untuk kejujuran dan kehangatan. Hadiah Anda berupa inisiatif, kepercayaan diri, dan ketahanan dapat membantu Anda terhubung tanpa harus berpura-pura.","career":"Kemajuan profesional terbaik Anda datang dari memilih prioritas dan melindungi waktu untuk itu. Gunakan keberanian, energi, kemandirian, dan ketegasan sebagai alat, bukan sebagai harapan yang harus Anda penuhi sekaligus.","finance":"Tinjau pola di balik pengeluaran Anda sebelum membuat komitmen yang lebih besar. Perhatikan ketika ketidaksabaran, impulsif, memulai lebih cepat daripada yang bisa Anda pertahankan mulai memengaruhi keputusan praktis.","wellbeing":"Seimbangkan gerakan dengan pemulihan yang nyata sepanjang minggu. Pilih satu awal yang berani dan berikan kesabaran yang cukup agar dapat berkembang.","guidance":"Biarkan pertanyaan ini membimbing minggu: Pilih satu awal yang berani dan berikan kesabaran yang cukup untuk tumbuh."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'year', 'id', '{"overview":"Tahun ini mengundang pertumbuhan yang sabar seputar identitas, tujuan, dan cara Anda menggunakan energi Anda. Aries bergerak melalui energi api. Awal yang berani dan tindakan langsung mendefinisikan Aries, yang percikannya mengubah niat menjadi momentum.","love":"Cinta akan semakin dalam ketika kamu mempraktikkan konsistensi dan membiarkan hubungan berkembang pada kecepatan manusia. Bakatmu dalam inisiatif, rasa percaya diri, dan ketahanan dapat membantumu terhubung tanpa harus berperan.","career":"Pekerjaan jangka panjang menjadi lebih kuat ketika ambisi dipadukan dengan struktur yang dapat Anda pertahankan. Gunakan keberanian, energi, kemandirian, dan keterusterangan sebagai alat, bukan ekspektasi yang harus Anda penuhi sekaligus.","finance":"Bangun kepercayaan diri finansial melalui kebiasaan yang dapat diulang alih-alih prediksi yang sempurna. Perhatikan ketika kurang sabar, impulsif, memulai lebih cepat daripada yang bisa Anda pertahankan mulai memengaruhi keputusan yang praktis.","wellbeing":"Anggap kesejahteraan sebagai fondasi untuk kehidupan yang sedang Anda bangun, bukan sebagai hadiah setelah menyelesaikannya. Pilih satu awal yang berani dan beri cukup kesabaran agar ia tumbuh.","guidance":"Kembali ke kompas ini sepanjang tahun: Pilih satu permulaan yang berani dan beri cukup kesabaran agar dapat berkembang."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('taurus', 'id', '{"name":"Taurus","dateRange":"20 Apr – 20 Mei","rulingPlanet":"Venus","summary":"Teguh, sensual, dan membumi, Banteng membangun nilai yang bertahan lama melalui kesabaran dan perhatian.","originStory":"Taurus mengingat Zeus yang mengambil bentuk seekor banteng putih yang luar biasa untuk membawa Europa menyeberangi laut. Gambaran ini menjadi terkait dengan kecantikan, kesuburan, kelimpahan duniawi, dan kekuatan yang diekspresikan melalui ketekunan yang tenang.","traits":["Berdasarkan kenyataan","Setia","Sabar","Sensual"],"strengths":["Keandalan","Kebijaksanaan praktis","Pengabdian"],"challenges":["Kekerasan kepala","Ketahanan terhadap perubahan","Terlalu lama bertahan"],"compatibleSigns":["Virgo","Capricorn","Kanker"],"reflectionPrompt":"Lindungi apa yang penting tanpa salah mengartikan kenyamanan sebagai sesuatu yang permanen."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'day', 'id', '{"overview":"Hari ini mendukung satu langkah yang jelas dan disengaja. Taurus bergerak melalui energi bumi. Stabil, sensual, dan membumi, Si Banteng membangun nilai yang tahan lama melalui kesabaran dan perhatian.","love":"Dalam cinta hari ini, pilih kehadiran daripada asumsi. Bakat Anda dalam dapat diandalkan, kebijaksanaan praktis, pengabdian dapat membantu Anda terhubung tanpa harus tampil.","career":"Di tempat kerja, selesaikan tugas yang paling bermakna sebelum mengejar momentum baru. Gunakan sifat-sifat yang membumi, setia, sabar, dan sensual sebagai alat, bukan sebagai harapan yang harus Anda penuhi sekaligus.","finance":"Pertahankan pilihan uang hari ini tetap sederhana dan realistis. Perhatikan ketika sifat keras kepala, penolakan terhadap perubahan, atau terlalu bertahan mulai memengaruhi keputusan yang praktis.","wellbeing":"Jeda kecil bisa mengatur ulang energi Anda. Lindungi hal-hal yang penting tanpa salah mengira kenyamanan sebagai sesuatu yang abadi.","guidance":"Sebelum hari berakhir, ingatlah: Lindungi apa yang penting tanpa salah mengira kenyamanan sebagai sesuatu yang abadi."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'week', 'id', '{"overview":"Minggu ini berkembang melalui pilihan yang mantap daripada satu momen dramatis. Taurus bergerak melalui energi bumi. Stabil, sensual, dan berpijak kuat, Sang Banteng membangun nilai yang bertahan lama melalui kesabaran dan perhatian.","love":"Hubungan mendapatkan manfaat dari percakapan yang memberi ruang untuk kejujuran dan kehangatan. Bakat Anda dalam keandalan, kebijaksanaan praktis, dan pengabdian dapat membantu Anda terhubung tanpa perlu berpura-pura.","career":"Kemajuan profesional terbaik Anda datang dari memilih prioritas dan melindungi waktu untuk itu. Gunakan berakar, setia, sabar, sensual sebagai alat, bukan ekspektasi yang harus Anda penuhi sekaligus.","finance":"Tinjau pola di balik pengeluaran Anda sebelum membuat komitmen yang lebih besar. Perhatikan kapan kekerasan kepala, resistensi terhadap perubahan, bertahan terlalu lama mulai memengaruhi keputusan praktis.","wellbeing":"Seimbangkan gerakan dengan pemulihan yang nyata sepanjang minggu. Lindungi apa yang penting tanpa salah mengartikan kenyamanan sebagai sesuatu yang permanen.","guidance":"Biarkan pertanyaan ini membimbing minggu: Lindungi apa yang penting tanpa salah mengira kenyamanan sebagai sesuatu yang tetap."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'year', 'id', '{"overview":"Tahun ini mengundang pertumbuhan yang sabar seputar identitas, tujuan, dan cara Anda menggunakan energi Anda. Taurus bergerak melalui energi bumi. Tetap, sensual, dan membumi, Sang Banteng membangun nilai yang bertahan lama melalui kesabaran dan perhatian.","love":"Cinta semakin dalam ketika kamu mempraktikkan konsistensi dan membiarkan hubungan berkembang pada kecepatan manusia. Hadiahmu berupa keandalan, kebijaksanaan praktis, dan pengabdian dapat membantumu terhubung tanpa harus tampil sempurna.","career":"Pekerjaan jangka panjang menjadi lebih kuat ketika ambisi dipadukan dengan struktur yang dapat Anda pertahankan. Gunakan sifat yang berpijak, setia, sabar, dan sensual sebagai alat, bukan ekspektasi yang harus Anda penuhi sekaligus.","finance":"Bangun kepercayaan finansial melalui kebiasaan yang bisa diulang daripada prediksi yang sempurna. Perhatikan ketika keingkaran, penolakan terhadap perubahan, atau terus bertahan terlalu lama mulai memengaruhi keputusan yang praktis.","wellbeing":"Anggap kesejahteraan sebagai dasar untuk kehidupan yang sedang Anda bangun, bukan sebagai hadiah setelah menyelesaikannya. Lindungi apa yang penting tanpa salah mengartikan kenyamanan sebagai sesuatu yang permanen.","guidance":"Kembali ke kompas ini sepanjang tahun: Lindungi apa yang penting tanpa keliru menganggap kenyamanan sebagai kepastian."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('gemini', 'id', '{"name":"Gemini","dateRange":"21 Mei – 20 Jun","rulingPlanet":"Merkurius","summary":"Rasa ingin tahu dan koneksi membimbing Kembar, yang mengumpulkan ide dan mengungkap lebih dari satu sisi cerita.","originStory":"Gemini melambangkan Castor dan Pollux, kembar yang tak terpisahkan yang berbagi keabadian daripada tetap terpisah. Rasi bintang mereka membawa tema kebersamaan, perspektif ganda, komunikasi, dan pergerakan antar dunia.","traits":["Ingin tahu","Dapat menyesuaikan","Ekspresif","Cerdas"],"strengths":["Komunikasi","Fleksibilitas","Belajar dengan cepat"],"challenges":["Gelisah","Fokus yang tersebar","Berpikir berlebihan"],"compatibleSigns":["Libra","Aquarius","Aries"],"reflectionPrompt":"Biarkan rasa ingin tahu membuka pintu, lalu tinggal cukup lama untuk memahami apa yang kamu temukan."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'day', 'id', '{"overview":"Hari ini mendukung satu langkah yang jelas dan disengaja. Gemini bergerak melalui energi udara. Rasa ingin tahu dan koneksi membimbing si Kembar, yang mengumpulkan ide-ide dan mengungkap lebih dari satu sisi cerita.","love":"Dalam cinta hari ini, pilih kehadiran daripada asumsi. Bakat Anda dalam komunikasi, fleksibilitas, dan belajar cepat dapat membantu Anda terhubung tanpa harus tampil.","career":"Di tempat kerja, selesaikan tugas yang paling bermakna sebelum mengejar momentum baru. Gunakan rasa ingin tahu, kemampuan beradaptasi, ekspresif, cerdas tanggap sebagai alat, bukan harapan yang harus Anda penuhi sekaligus.","finance":"Jaga pilihan uang hari ini tetap sederhana dan realistis. Perhatikan saat kegelisahan, fokus yang tersebar, dan overthinking mulai memengaruhi keputusan yang praktis.","wellbeing":"Jeda kecil bisa mengatur ulang energi Anda. Biarkan rasa ingin tahu membuka pintu, lalu tetaplah cukup lama untuk memahami apa yang Anda temukan.","guidance":"Sebelum hari berakhir, ingatlah: Biarkan rasa ingin tahu membuka pintu, lalu tinggallah cukup lama untuk memahami apa yang kamu temukan."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'week', 'id', '{"overview":"Minggu ini berkembang melalui pilihan yang mantap daripada satu momen dramatis. Gemini bergerak melalui energi udara. Rasa ingin tahu dan koneksi membimbing Si Kembar, yang mengumpulkan ide dan mengungkap lebih dari satu sisi cerita.","love":"Hubungan mendapat manfaat dari percakapan yang memberi ruang bagi kejujuran dan kehangatan. Bakat Anda dalam komunikasi, fleksibilitas, belajar cepat dapat membantu Anda terhubung tanpa harus tampil.","career":"Kemajuan profesional terbaik Anda datang dari memilih prioritas dan melindungi waktu untuk itu. Gunakan rasa ingin tahu, mudah beradaptasi, ekspresif, cerdas sebagai alat, bukan ekspektasi yang harus Anda penuhi sekaligus.","finance":"Tinjau pola di balik pengeluaran Anda sebelum membuat komitmen yang lebih besar. Perhatikan kapan kegelisahan, fokus yang terpecah, terlalu banyak berpikir mulai memengaruhi keputusan praktis.","wellbeing":"Seimbangkan gerakan dengan pemulihan yang nyata sepanjang minggu. Biarkan rasa ingin tahu membuka pintu, lalu tetaplah cukup lama untuk memahami apa yang kamu temukan.","guidance":"Biarkan pertanyaan ini membimbing minggu: Biarkan rasa ingin tahu membuka pintu, lalu tinggal cukup lama untuk memahami apa yang kamu temukan."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'year', 'id', '{"overview":"Tahun ini mengundang pertumbuhan yang sabar seputar identitas, tujuan, dan cara Anda menggunakan energi Anda. Gemini bergerak melalui energi udara. Rasa ingin tahu dan koneksi membimbing si Kembar, yang mengumpulkan ide-ide dan mengungkap lebih dari satu sisi cerita.","love":"Cinta semakin dalam ketika Anda mempraktikkan konsistensi dan membiarkan hubungan berkembang pada kecepatan manusia. Bakat Anda dalam komunikasi, fleksibilitas, belajar cepat dapat membantu Anda terhubung tanpa harus berpenampilan.","career":"Pekerjaan jangka panjang menjadi lebih kuat ketika ambisi dipadukan dengan struktur yang bisa Anda pertahankan. Gunakan rasa ingin tahu, kemampuan beradaptasi, kemampuan mengekspresikan diri, dan kecerdikan sebagai alat, bukan harapan yang harus Anda penuhi sekaligus.","finance":"Bangun kepercayaan finansial melalui kebiasaan yang dapat diulang alih-alih prediksi yang sempurna. Perhatikan ketika kegelisahan, fokus yang terpecah, dan overthinking mulai memengaruhi keputusan praktis.","wellbeing":"Anggap kesejahteraan sebagai dasar untuk kehidupan yang sedang Anda bangun, bukan sebagai hadiah setelah menyelesaikannya. Biarkan rasa ingin tahu membuka pintu, lalu tetaplah cukup lama untuk memahami apa yang Anda temukan.","guidance":"Kembali ke kompas ini sepanjang tahun: Biarkan rasa ingin tahu membuka pintu, lalu tetaplah cukup lama untuk memahami apa yang Anda temukan."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('cancer', 'id', '{"name":"Kanker","dateRange":"21 Jun – 22 Jul","rulingPlanet":"Bulan","summary":"Protektif dan intuitif, Kepiting menciptakan rasa memiliki dengan menghormati memori, perasaan, dan rumah.","originStory":"Kanker dikaitkan dengan kepiting Karkinos, yang ditempatkan di antara bintang-bintang setelah menunjukkan kesetiaan selama pertarungan Herakles dengan Hydra. Cangkangnya dan penguasaannya atas bulan mencerminkan perlindungan, pasang surut emosional, dan kesetiaan kepada lingkaran batin seseorang.","traits":["Intuitif","Peduli","Protektif","Imaginatif"],"strengths":["Empati","Kesetiaan","Wawasan emosional"],"challenges":["Sifat murung","Menarik diri di balik pertahanan","Mengambil sesuatu secara pribadi"],"compatibleSigns":["Scorpio","Pisces","Taurus"],"reflectionPrompt":"Rawat dunia batinmu sambil tetap membuka pintu untuk koneksi yang jujur."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'day', 'id', '{"overview":"Hari ini mendukung satu langkah yang jelas dan disengaja. Cancer bergerak melalui energi air. Pelindung dan intuitif, Kepiting menciptakan rasa memiliki dengan menghormati ingatan, perasaan, dan rumah.","love":"Dalam cinta hari ini, pilih kehadiran daripada asumsi. Karunia empati, kesetiaan, wawasan emosionalmu dapat membantumu terhubung tanpa harus tampil.","career":"Di tempat kerja, selesaikan tugas yang paling bermakna sebelum mengejar momentum baru. Gunakan intuitif, peduli, protektif, imajinatif sebagai alat, bukan harapan yang harus Anda penuhi sekaligus.","finance":"Pertahankan pilihan uang hari ini tetap sederhana dan realistis. Perhatikan ketika suasana hati yang tidak menentu, menjauh di balik pertahanan, atau mengambil sesuatu secara pribadi mulai memengaruhi keputusan praktis.","wellbeing":"Jeda kecil bisa mengatur ulang energi Anda. Rawat dunia batin Anda sembari membiarkan pintu terbuka untuk koneksi yang jujur.","guidance":"Sebelum hari berakhir, ingatlah: Rawatlah dunia batinmu sambil meninggalkan pintu terbuka untuk hubungan yang jujur."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'week', 'id', '{"overview":"Minggu ini berkembang melalui pilihan yang mantap daripada satu momen dramatis. Cancer bergerak melalui energi air. Perlindungan dan intuitif, Si Kepiting menciptakan rasa memiliki dengan menghormati memori, perasaan, dan rumah.","love":"Hubungan mendapat manfaat dari percakapan yang memberi ruang untuk kejujuran dan kehangatan. Hadiah Anda berupa empati, kesetiaan, dan wawasan emosional dapat membantu Anda terhubung tanpa harus berpura-pura.","career":"Kemajuan profesional terbaik Anda datang dari memilih prioritas dan melindungi waktu untuk itu. Gunakan intuitif, peduli, protektif, imajinatif sebagai alat, bukan ekspektasi yang harus Anda penuhi sekaligus.","finance":"Tinjau pola di balik pengeluaran Anda sebelum membuat komitmen yang lebih besar. Perhatikan kapan perubahan suasana hati, mundur di balik pertahanan, atau mengambil sesuatu secara pribadi mulai memengaruhi keputusan praktis.","wellbeing":"Seimbangkan gerakan dengan pemulihan yang nyata sepanjang minggu. Rawat dunia batinmu sambil tetap membuka pintu untuk hubungan yang jujur.","guidance":"Biarkan pertanyaan ini membimbing minggu ini: Rawat dunia batinmu sambil meninggalkan pintu terbuka untuk koneksi yang jujur."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'year', 'id', '{"overview":"Tahun ini mengundang pertumbuhan yang sabar seputar identitas, tujuan, dan cara Anda menggunakan energi Anda. Cancer bergerak melalui energi air. Protektif dan intuitif, Kepiting menciptakan rasa memiliki dengan menghormati memori, perasaan, dan rumah.","love":"Cinta semakin dalam ketika kamu mempraktikkan konsistensi dan membiarkan hubungan berkembang pada kecepatan manusia. Bakatmu dalam empati, kesetiaan, dan wawasan emosional dapat membantumu terhubung tanpa harus berpura-pura.","career":"Pekerjaan jangka panjang menjadi lebih kuat ketika ambisi dipadukan dengan struktur yang dapat Anda pertahankan. Gunakan intuitif, peduli, melindungi, imajinatif sebagai alat, bukan sebagai harapan yang harus Anda penuhi sekaligus.","finance":"Bangun kepercayaan finansial melalui kebiasaan yang bisa diulang daripada prediksi yang sempurna. Perhatikan ketika suasana hati yang buruk, mundur di balik pertahanan, atau mengambil sesuatu secara pribadi mulai memengaruhi keputusan praktis.","wellbeing":"Anggaplah kesejahteraan sebagai fondasi untuk kehidupan yang sedang Anda bangun, bukan sebagai hadiah setelah menyelesaikannya. Rawatlah dunia batin Anda sambil tetap membuka pintu untuk hubungan yang jujur.","guidance":"Kembali ke kompas ini sepanjang tahun: Rawatlah dunia batinmu sambil meninggalkan pintu terbuka untuk koneksi yang jujur."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('leo', 'id', '{"name":"Leo","dateRange":"23 Jul – 22 Agu","rulingPlanet":"Matahari","summary":"Keakraban, kreativitas, dan ekspresi diri yang murah hati membuat Singa menjadi sumber cahaya alami.","originStory":"Leo terikat pada Singa Nemean, makhluk yang hampir kebal yang dikalahkan dalam tugas pertama Heracles. Diangkat ke langit, ia menjadi lambang keberanian, kehadiran berdaulat, dan kekuatan kreatif Matahari.","traits":["Hangat","Kreatif","Dermawan","Percaya diri"],"strengths":["Kepemimpinan","Kesetiaan","Ungkapan yang tulus"],"challenges":["Kebanggaan","Memerlukan pengakuan","Mendramatisasi kemunduran"],"compatibleSigns":["Aries","Sagitarius","Libra"],"reflectionPrompt":"Bagikan cahaya Anda dengan murah hati dan biarkan orang lain bersinar di samping Anda."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'day', 'id', '{"overview":"Hari ini menguntungkan satu langkah yang jelas dan disengaja. Leo bergerak melalui energi api. Kehangatan, kreativitas, dan ekspresi diri yang murah hati membuat Sang Singa menjadi sumber cahaya yang alami.","love":"Dalam cinta hari ini, pilih kehadiran daripada asumsi. Karunia kepemimpinan, kesetiaan, ekspresi dari hati dapat membantumu terhubung tanpa harus tampil.","career":"Di tempat kerja, selesaikan tugas yang paling bermakna sebelum mengejar momentum baru. Gunakan hangat, kreatif, murah hati, percaya diri sebagai alat, bukan harapan yang harus Anda penuhi sekaligus.","finance":"Jaga pilihan uang hari ini tetap sederhana dan realistis. Perhatikan saat rasa bangga, kebutuhan untuk diakui, atau membesar-besarkan kemunduran mulai memengaruhi keputusan yang praktis.","wellbeing":"Sebuah jeda kecil dapat mengatur ulang energi Anda. Bagikan cahaya Anda dengan murah hati dan biarkan orang lain bersinar di samping Anda.","guidance":"Sebelum hari berakhir, ingatlah: Bagikan cahaya-mu dengan murah hati dan biarkan orang lain bersinar di sampingmu."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'week', 'id', '{"overview":"Minggu ini berkembang melalui pilihan yang mantap daripada satu momen dramatis. Leo bergerak melalui energi api. Kehangatan, kreativitas, dan ekspresi diri yang murah hati menjadikan Singa sumber cahaya alami.","love":"Hubungan mendapatkan manfaat dari percakapan yang memberi ruang untuk kejujuran dan kehangatan. Bakat Anda dalam kepemimpinan, kesetiaan, dan ekspresi yang tulus dapat membantu Anda terhubung tanpa perlu berpura-pura.","career":"Kemajuan profesional terbaik Anda datang dari memilih prioritas dan melindungi waktu untuk itu. Gunakan hangat, kreatif, dermawan, percaya diri sebagai alat, bukan ekspektasi yang harus Anda penuhi sekaligus.","finance":"Tinjau pola di balik pengeluaran Anda sebelum membuat komitmen yang lebih besar. Perhatikan kapan rasa bangga, kebutuhan untuk diakui, atau membesar-besarkan kemunduran mulai memengaruhi keputusan yang praktis.","wellbeing":"Seimbangkan gerakan dengan pemulihan yang nyata sepanjang minggu. Bagikan cahaya mu dengan murah hati dan biarkan orang lain bersinar di sampingmu.","guidance":"Biarkan pertanyaan ini membimbing minggu: Bagikan cahaya-mu dengan murah hati dan biarkan orang lain bersinar di sisimu."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'year', 'id', '{"overview":"Tahun ini mengundang pertumbuhan yang sabar seputar identitas, tujuan, dan cara Anda menggunakan energi Anda. Leo bergerak melalui energi api. Kehangatan, kreativitas, dan ekspresi diri yang dermawan membuat Singa menjadi sumber cahaya alami.","love":"Cinta semakin dalam ketika kamu mempraktikkan konsistensi dan membiarkan hubungan berkembang pada kecepatan manusia. Bakatmu dalam kepemimpinan, kesetiaan, dan ekspresi yang tulus dapat membantumu terhubung tanpa harus berpura-pura.","career":"Pekerjaan jangka panjang menjadi lebih kuat ketika ambisi dipadukan dengan struktur yang dapat Anda pertahankan. Gunakan hangat, kreatif, dermawan, percaya diri sebagai alat, bukan ekspektasi yang harus Anda penuhi sekaligus.","finance":"Bangun kepercayaan finansial melalui kebiasaan yang dapat diulang alih-alih prediksi yang sempurna. Perhatikan ketika kesombongan, kebutuhan akan pengakuan, atau membesar-besarkan kemunduran mulai memengaruhi keputusan praktis.","wellbeing":"Anggap kesejahteraan sebagai dasar untuk kehidupan yang sedang Anda bangun, bukan sebagai hadiah setelah menyelesaikannya. Bagikan cahaya Anda dengan murah hati dan biarkan orang lain bersinar di samping Anda.","guidance":"Kembali ke kompas ini sepanjang tahun: Bagikan cahaya Anda dengan murah hati dan biarkan orang lain bersinar di samping Anda."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('virgo', 'id', '{"name":"Virgo","dateRange":"23 Agu – 22 Sep","rulingPlanet":"Merkurius","summary":"Kebijaksanaan dan pelayanan membimbing Virgo, mengubah pengamatan yang cermat menjadi perbaikan praktis.","originStory":"Virgo sering dikaitkan dengan Astraea, gadis keadilan yang tetap bersama umat manusia setelah dewa-dewa lain menarik diri. Gandum yang dibawanya menghubungkan tanda ini dengan panen, keterampilan, kemurnian niat, dan merawat apa yang menopang hidup.","traits":["Pengamat","Praktis","Penuh pertimbangan","Tepat"],"strengths":["Analisis","Keahlian kerajinan","Layanan yang membantu"],"challenges":["Perfeksionisme","Kritik diri","Khawatir tentang hal-hal kecil"],"compatibleSigns":["Taurus","Capricorn","Kanker"],"reflectionPrompt":"Tingkatkan apa yang bisa Anda tingkatkan, dan biarkan pekerjaan yang baik selesai sebelum menjadi sempurna."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'day', 'id', '{"overview":"Hari ini mendukung satu langkah yang jelas dan disengaja. Virgo bergerak melalui energi bumi. Kearifan dan pelayanan membimbing Si Perawan, mengubah pengamatan yang cermat menjadi peningkatan praktis.","love":"Dalam cinta hari ini, pilih kehadiran daripada asumsi. Bakat Anda dalam analisis, keahlian, dan pelayanan yang membantu dapat membantu Anda terhubung tanpa harus tampil.","career":"Di tempat kerja, selesaikan tugas yang paling bermakna sebelum mengejar momentum baru. Gunakan pengamat, praktis, penuh perhatian, tepat sebagai alat, bukan harapan yang harus Anda penuhi sekaligus.","finance":"Pertahankan pilihan uang hari ini tetap sederhana dan realistis. Perhatikan ketika perfeksionisme, kritik diri, dan kekhawatiran terhadap detail mulai memengaruhi keputusan yang praktis.","wellbeing":"Jeda kecil bisa mengatur ulang energi Anda. Tingkatkan apa yang Anda bisa, dan biarkan pekerjaan baik selesai sebelum menjadi sempurna.","guidance":"Sebelum hari berakhir, ingatlah: Perbaiki apa yang bisa kamu perbaiki, dan izinkan pekerjaan yang baik selesai sebelum sempurna."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'week', 'id', '{"overview":"Minggu ini berkembang melalui pilihan yang stabil daripada satu momen dramatis. Virgo bergerak melalui energi bumi. Kebijaksanaan dan pelayanan membimbing Sang Perawan, mengubah pengamatan yang cermat menjadi perbaikan praktis.","love":"Hubungan mendapat manfaat dari percakapan yang memberi ruang bagi kejujuran dan kehangatan. Bakat Anda dalam analisis, keterampilan, pelayanan yang membantu dapat membantu Anda terhubung tanpa harus tampil.","career":"Kemajuan profesional terbaik Anda datang dari memilih prioritas dan melindungi waktu untuk itu. Gunakan pengamat, praktis, penuh pertimbangan, tepat sebagai alat, bukan ekspektasi yang harus Anda penuhi sekaligus.","finance":"Tinjau pola di balik pengeluaran Anda sebelum membuat komitmen yang lebih besar. Perhatikan kapan perfeksionisme, mengkritik diri sendiri, dan khawatir tentang detail mulai memengaruhi keputusan praktis.","wellbeing":"Seimbangkan gerakan dengan pemulihan yang nyata sepanjang minggu. Tingkatkan apa yang bisa kamu tingkatkan, dan biarkan pekerjaan yang baik selesai sebelum sempurna.","guidance":"Biarkan pertanyaan ini membimbing minggu: Perbaiki apa yang bisa kamu perbaiki, dan biarkan pekerjaan yang baik selesai sebelum menjadi sempurna."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'year', 'id', '{"overview":"Tahun ini mengundang pertumbuhan yang sabar seputar identitas, tujuan, dan cara Anda menggunakan energi Anda. Virgo bergerak melalui energi bumi. Penilaian dan pelayanan membimbing Gadis Perawan, mengubah pengamatan yang cermat menjadi perbaikan praktis.","love":"Cinta semakin dalam ketika Anda mempraktikkan konsistensi dan membiarkan hubungan berkembang pada kecepatan manusia. Bakat Anda dalam analisis, kerajinan, pelayanan yang membantu dapat membantu Anda terhubung tanpa harus berpenampilan.","career":"Pekerjaan jangka panjang menjadi lebih kuat ketika ambisi dipadukan dengan struktur yang dapat Anda pertahankan. Gunakan sifat waspada, praktis, penuh perhatian, dan tepat sebagai alat, bukan ekspektasi yang harus Anda penuhi sekaligus.","finance":"Bangun kepercayaan finansial melalui kebiasaan yang bisa diulang daripada prediksi yang sempurna. Perhatikan ketika perfeksionisme, kritik diri, atau kekhawatiran tentang detail mulai memengaruhi keputusan yang praktis.","wellbeing":"Anggap kesejahteraan sebagai dasar untuk kehidupan yang sedang Anda bangun, bukan sebagai hadiah setelah menyelesaikannya. Perbaiki apa yang bisa, dan biarkan pekerjaan yang baik selesai sebelum menjadi sempurna.","guidance":"Kembali ke kompas ini sepanjang tahun: Perbaiki apa yang bisa Anda perbaiki, dan biarkan pekerjaan baik selesai sebelum sempurna."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('libra', 'id', '{"name":"Libra","dateRange":"23 Sep – 22 Okt","rulingPlanet":"Venus","summary":"Keseimbangan, keindahan, dan timbal balik membimbing Timbangan menuju pilihan yang menghormati setiap suara.","originStory":"Timbangan Libra dibawa oleh Astraea, dewi keadilan, dan membentuk satu-satunya simbol tak hidup dalam zodiak. Mereka mewakili penilaian yang terukur, harmoni sosial, dan pekerjaan berkelanjutan untuk memulihkan keseimbangan daripada menganggapnya sudah ada.","traits":["Diplomatis","Adil","Menawan","Kolaboratif"],"strengths":["Mediasi","Perspektif","Menciptakan harmoni"],"challenges":["Keragu-raguan","Menyenangkan orang","Menghindari konflik yang diperlukan"],"compatibleSigns":["Gemini","Aquarius","Leo"],"reflectionPrompt":"Carilah keadilan tanpa mengabaikan kebenaran dari kebutuhanmu sendiri."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'day', 'id', '{"overview":"Hari ini menguntungkan satu langkah yang jelas dan disengaja. Libra bergerak melalui energi udara. Keseimbangan, keindahan, dan timbal balik membimbing Timbangan menuju pilihan yang menghormati setiap suara.","love":"Dalam cinta hari ini, pilih kehadiran daripada asumsi. Bakat Anda dalam mediasi, perspektif, menciptakan harmoni dapat membantu Anda terhubung tanpa harus tampil.","career":"Di tempat kerja, selesaikan tugas yang paling bermakna sebelum mengejar momentum baru. Gunakan diplomatis, berpikir adil, menawan, kolaboratif sebagai alat, bukan harapan yang harus Anda penuhi sekaligus.","finance":"Pertahankan pilihan uang hari ini tetap sederhana dan realistis. Perhatikan saat ketidakpastian, keinginan untuk menyenangkan orang lain, menghindari konflik yang perlu mulai memengaruhi keputusan praktis.","wellbeing":"Sebuah jeda kecil dapat mengatur ulang energi Anda. Carilah keadilan tanpa meninggalkan kebenaran dari kebutuhan Anda sendiri.","guidance":"Sebelum hari berakhir, ingatlah: Carilah keadilan tanpa meninggalkan kebenaran tentang kebutuhanmu sendiri."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'week', 'id', '{"overview":"Minggu ini berkembang melalui pilihan yang mantap daripada satu momen dramatis. Libra bergerak melalui energi udara. Keseimbangan, keindahan, dan timbal balik membimbing Timbangan menuju pilihan yang menghormati setiap suara.","love":"Hubungan mendapatkan manfaat dari percakapan yang memberi ruang untuk kejujuran dan kehangatan. Bakat Anda dalam mediasi, perspektif, dan menciptakan harmoni dapat membantu Anda terhubung tanpa perlu berpura-pura.","career":"Kemajuan profesional terbaik Anda datang dari memilih prioritas dan melindungi waktu untuk itu. Gunakan diplomatis, adil, menawan, kolaboratif sebagai alat, bukan ekspektasi yang harus Anda penuhi sekaligus.","finance":"Tinjau pola di balik pengeluaran Anda sebelum membuat komitmen yang lebih besar. Perhatikan saat keraguan, keinginan untuk menyenangkan orang lain, menghindari konflik yang perlu mulai memengaruhi keputusan yang praktis.","wellbeing":"Seimbangkan gerakan dengan pemulihan yang nyata sepanjang minggu. Carilah keadilan tanpa meninggalkan kebenaran tentang kebutuhanmu sendiri.","guidance":"Biarkan pertanyaan ini membimbing minggu: Carilah keadilan tanpa meninggalkan kebenaran akan kebutuhanmu sendiri."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'year', 'id', '{"overview":"Tahun ini mengundang pertumbuhan yang sabar seputar identitas, tujuan, dan cara Anda menggunakan energi Anda. Libra bergerak melalui energi udara. Keseimbangan, keindahan, dan timbal balik membimbing Timbangan menuju pilihan yang menghormati setiap suara.","love":"Cinta semakin dalam ketika kamu mempraktikkan konsistensi dan membiarkan hubungan berkembang pada kecepatan manusia. Bakatmu dalam mediasi, perspektif, dan menciptakan harmoni dapat membantumu terhubung tanpa harus menunjukkan kemampuanmu.","career":"Pekerjaan jangka panjang menjadi lebih kuat ketika ambisi dipadukan dengan struktur yang dapat Anda pertahankan. Gunakan diplomatis, adil, menawan, kolaboratif sebagai alat, bukan sebagai harapan yang harus Anda penuhi sekaligus.","finance":"Bangun kepercayaan finansial melalui kebiasaan yang bisa diulang daripada prediksi yang sempurna. Perhatikan ketika ketidakpastian, keinginan untuk menyenangkan orang lain, menghindari konflik yang diperlukan mulai memengaruhi keputusan yang praktis.","wellbeing":"Anggap kesejahteraan sebagai dasar untuk kehidupan yang sedang Anda bangun, bukan sebagai hadiah setelah menyelesaikannya. Carilah keadilan tanpa meninggalkan kebenaran dari kebutuhan Anda sendiri.","guidance":"Kembali ke kompas ini sepanjang tahun: Carilah keadilan tanpa meninggalkan kebenaran akan kebutuhan Anda sendiri."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('scorpio', 'id', '{"name":"Scorpio","dateRange":"23 Okt – 21 Nov","rulingPlanet":"Pluto","summary":"Kedalaman dan transformasi mendefinisikan Scorpio, yang wawasan-nya menemukan kebenaran di balik permukaan.","originStory":"Scorpio mengingat kalajengking yang dikirim untuk menghadapi pemburu Orion setelah kesombongannya mengganggu tatanan alam. Posisi mereka yang berlawanan di langit membangkitkan batasan, konsekuensi, misteri, dan kekuatan regeneratif yang ditemukan setelah sebuah akhir.","traits":["Intens","Perseptif","Setia","Cekatan"],"strengths":["Keberanian emosional","Fokus","Transformasi"],"challenges":["Kerahasiaan","Kecurigaan","Menyimpan dendam"],"compatibleSigns":["Kanker","Pisces","Virgo"],"reflectionPrompt":"Gunakan kedalaman Anda untuk mengubah kebenaran, bukan untuk menyembunyikannya."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'day', 'id', '{"overview":"Hari ini menguntungkan satu langkah yang jelas dan disengaja. Scorpio bergerak melalui energi air. Kedalaman dan transformasi mendefinisikan Kalajengking, yang wawasan menemukan kebenaran di bawah permukaan.","love":"Dalam cinta hari ini, pilih kehadiran daripada asumsi. Bakat Anda dalam keberanian emosional, fokus, dan transformasi dapat membantu Anda terhubung tanpa harus tampil.","career":"Di tempat kerja, selesaikan tugas yang paling bermakna sebelum mengejar momentum baru. Gunakan intens, peka, setia, pandai mencari solusi sebagai alat, bukan harapan yang harus Anda penuhi sekaligus.","finance":"Jaga pilihan uang hari ini tetap sederhana dan realistis. Perhatikan ketika kerahasiaan, kecurigaan, dan menyimpan dendam mulai memengaruhi keputusan yang praktis.","wellbeing":"Sebuah jeda kecil dapat mengatur ulang energi Anda. Gunakan kedalaman Anda untuk mengubah kebenaran, bukan untuk menyembunyikannya.","guidance":"Sebelum hari berakhir, ingatlah: Gunakan kedalamanmu untuk mengubah kebenaran, bukan untuk menyembunyikannya."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'week', 'id', '{"overview":"Minggu ini berkembang melalui pilihan yang stabil daripada satu momen dramatis. Scorpio bergerak melalui energi air. Kedalaman dan transformasi mendefinisikan Scorpio, yang wawasannya menemukan kebenaran di bawah permukaan.","love":"Hubungan mendapat manfaat dari percakapan yang memberi ruang bagi kejujuran dan kehangatan. Bakat Anda dalam keberanian emosional, fokus, transformasi dapat membantu Anda terhubung tanpa harus tampil.","career":"Kemajuan profesional terbaik Anda datang dari memilih prioritas dan melindungi waktu untuk itu. Gunakan intens, tanggap, setia, penuh akal sebagai alat, bukan ekspektasi yang harus Anda penuhi sekaligus.","finance":"Tinjau pola di balik pengeluaran Anda sebelum membuat komitmen yang lebih besar. Perhatikan kapan kerahasiaan, kecurigaan, menyimpan dendam mulai memengaruhi keputusan praktis.","wellbeing":"Seimbangkan gerakan dengan pemulihan yang nyata sepanjang minggu. Gunakan kedalamanmu untuk mengubah kebenaran, bukan untuk menyembunyikannya.","guidance":"Biarkan pertanyaan ini membimbing minggu ini: Gunakan kedalamanmu untuk mengubah kebenaran, bukan untuk menyembunyikannya."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'year', 'id', '{"overview":"Tahun ini mengundang pertumbuhan yang sabar seputar identitas, tujuan, dan cara Anda menggunakan energi Anda. Scorpio bergerak melalui energi air. Kedalaman dan transformasi mendefinisikan Si Kalajengking, yang wawasannya menemukan kebenaran di bawah permukaan.","love":"Cinta semakin dalam ketika Anda mempraktikkan konsistensi dan membiarkan hubungan berkembang pada kecepatan manusia. Bakat Anda dalam keberanian emosional, fokus, transformasi dapat membantu Anda terhubung tanpa harus berpenampilan.","career":"Pekerjaan jangka panjang menjadi lebih kuat ketika ambisi dipadukan dengan struktur yang bisa Anda pertahankan. Gunakan intens, tajam, setia, dan cerdas sebagai alat, bukan sebagai ekspektasi yang harus Anda penuhi sekaligus.","finance":"Bangun kepercayaan diri finansial melalui kebiasaan yang dapat diulang alih-alih prediksi yang sempurna. Perhatikan ketika kerahasiaan, kecurigaan, dan menyimpan dendam mulai memengaruhi keputusan yang praktis.","wellbeing":"Anggap kesejahteraan sebagai dasar untuk kehidupan yang sedang Anda bangun, bukan sebagai hadiah setelah menyelesaikannya. Gunakan kedalaman Anda untuk mengubah kebenaran, bukan untuk menyembunyikannya.","guidance":"Kembali ke kompas ini sepanjang tahun: Gunakan kedalaman Anda untuk mengubah kebenaran, bukan untuk menyembunyikannya."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('sagittarius', 'id', '{"name":"Sagitarius","dateRange":"22 Nov – 21 Des","rulingPlanet":"Yupiter","summary":"The Archer mencari cakrawala yang lebih luas melalui kebenaran, perjalanan, belajar, dan optimisme yang bertujuan.","originStory":"Sagitarius umumnya dikaitkan dengan Chiron, centaur bijak dan guru yang panahnya mengarah melampaui yang biasa. Rasi bintang ini melambangkan persatuan antara naluri dan pemahaman yang lebih tinggi, selalu mengarah ke cakrawala yang lebih bermakna.","traits":["Petualang","Optimis","Jujur","Filosofis"],"strengths":["Visi","Antusiasme","Keterbukaan pikiran"],"challenges":["Keterusterangan","Janji berlebihan","Melarikan diri dari rutinitas"],"compatibleSigns":["Aries","Leo","Aquarius"],"reflectionPrompt":"Bidik jauh, tetapi pilih arah yang dapat didukung oleh tindakan sehari-hari Anda."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'day', 'id', '{"overview":"Hari ini menguntungkan satu langkah yang jelas dan disengaja. Sagitarius bergerak melalui energi api. Pemanah mencari cakrawala yang lebih luas melalui kebenaran, perjalanan, pembelajaran, dan optimisme yang bertujuan.","love":"Dalam cinta hari ini, pilih kehadiran daripada asumsi. Bakat Anda dalam visi, antusiasme, berpikiran terbuka dapat membantu Anda terhubung tanpa harus tampil.","career":"Di tempat kerja, selesaikan tugas yang paling bermakna sebelum mengejar momentum baru. Gunakan petualang, optimis, jujur, filosofis sebagai alat, bukan harapan yang harus Anda penuhi sekaligus.","finance":"Pertahankan pilihan uang hari ini sederhana dan terhubung dengan kenyataan. Perhatikan ketika keterusterangan, janji berlebihan, atau melarikan diri dari rutinitas mulai memengaruhi keputusan praktis.","wellbeing":"Istirahat sejenak dapat mengatur ulang energi Anda. Bidik jauh, tetapi pilih arah yang dapat didukung oleh tindakan harian Anda.","guidance":"Sebelum hari berakhir, ingat: Bidik jauh, tapi pilih arah yang bisa didukung oleh tindakanmu sehari-hari."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'week', 'id', '{"overview":"Minggu ini berkembang melalui pilihan yang stabil daripada satu momen dramatis. Sagitarius bergerak melalui energi api. Sang Pemanah mencari cakrawala yang lebih luas melalui kebenaran, perjalanan, pembelajaran, dan optimisme yang bertujuan.","love":"Hubungan mendapatkan manfaat dari percakapan yang memberi ruang untuk kejujuran dan kehangatan. Hadiah Anda berupa visi, antusiasme, dan keterbukaan dapat membantu Anda terhubung tanpa harus berperan.","career":"Kemajuan profesional terbaik Anda datang dari memilih prioritas dan melindungi waktu untuk itu. Gunakan petualang, optimis, jujur, filosofis sebagai alat, bukan harapan yang harus Anda penuhi sekaligus.","finance":"Tinjau pola di balik pengeluaran Anda sebelum membuat komitmen yang lebih besar. Perhatikan ketika ketegasan, janji berlebihan, melarikan diri dari rutinitas mulai memengaruhi keputusan praktis.","wellbeing":"Seimbangkan pergerakan dengan pemulihan yang sejati sepanjang minggu. Bidik jauh, tetapi pilih arah yang dapat didukung oleh tindakan harianmu.","guidance":"Biarkan pertanyaan ini membimbing minggu: Tuju jauh, tetapi pilih arah yang dapat didukung oleh tindakan harianmu."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'year', 'id', '{"overview":"Tahun ini mengundang pertumbuhan yang sabar seputar identitas, tujuan, dan cara Anda menggunakan energi Anda. Sagitarius bergerak melalui energi api. Sang Pemanah mencari cakrawala yang lebih luas melalui kebenaran, perjalanan, pembelajaran, dan optimisme yang penuh tujuan.","love":"Cinta semakin dalam ketika Anda mempraktekkan konsistensi dan membiarkan koneksi berkembang dengan tempo manusia. Hadiah Anda berupa visi, antusiasme, dan keterbukaan pikiran dapat membantu Anda terhubung tanpa harus berperforma.","career":"Pekerjaan jangka panjang menjadi lebih kuat ketika ambisi dipadukan dengan struktur yang dapat Anda pertahankan. Gunakan petualang, optimis, jujur, filosofis sebagai alat, bukan sebagai harapan yang harus Anda penuhi sekaligus.","finance":"Bangun kepercayaan diri finansial melalui kebiasaan yang dapat diulang alih-alih prediksi yang sempurna. Perhatikan ketika ketus, berjanji berlebihan, melarikan diri dari rutinitas mulai memengaruhi keputusan yang praktis.","wellbeing":"Perlakukan kesejahteraan sebagai dasar untuk kehidupan yang sedang Anda bangun, bukan sebagai hadiah setelah menyelesaikannya. Bidik jauh, tetapi pilih arah yang dapat didukung oleh tindakan harian Anda.","guidance":"Kembali ke kompas ini sepanjang tahun: Tujulah jauh, tetapi pilih arah yang dapat didukung oleh tindakan harianmu."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('capricorn', 'id', '{"name":"Capricorn","dateRange":"22 Des – 19 Jan","rulingPlanet":"Saturnus","summary":"Disiplin dan visi jangka panjang membantu Capricorn mendaki sambil tetap bijak tentang kedalaman di bawahnya.","originStory":"Kambing laut Capricorn dikaitkan dengan Pan, yang sebagian berubah menjadi ikan saat melarikan diri dari Typhon. Sifatnya yang di pegunungan dan lautan menggabungkan ambisi dengan kelangsungan emosional, menghormati penguasaan yang diperoleh melalui waktu dan tanggung jawab.","traits":["Ambisius","Disiplin","Sabar","Bertanggung jawab"],"strengths":["Ketahanan","Strategi","Ketergantungan"],"challenges":["Kekakuan","Pesimisme","Mengukur harga diri melalui pencapaian"],"compatibleSigns":["Taurus","Virgo","Scorpio"],"reflectionPrompt":"Bangun untuk jangka panjang sambil mengingat bahwa istirahat adalah bagian dari struktur."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'day', 'id', '{"overview":"Hari ini mendukung satu langkah yang jelas dan disengaja. Capricorn bergerak melalui energi bumi. Disiplin dan visi jangka panjang membantu Kambing Laut mendaki sambil tetap bijaksana tentang kedalaman di bawahnya.","love":"Dalam cinta hari ini, pilih kehadiran daripada asumsi. Karunia ketahanan, strategi, dapat diandalkanmu dapat membantumu terhubung tanpa harus tampil.","career":"Di tempat kerja, selesaikan tugas yang paling bermakna sebelum mengejar momentum baru. Gunakan ambisius, disiplin, sabar, bertanggung jawab sebagai alat, bukan harapan yang harus Anda penuhi sekaligus.","finance":"Jaga pilihan uang hari ini tetap sederhana dan realistis. Perhatikan saat kekakuan, pesimisme, dan mengukur nilai melalui pencapaian mulai memengaruhi keputusan praktis.","wellbeing":"Jeda kecil bisa mengatur ulang energi Anda. Bangunlah untuk jangka panjang sambil mengingat bahwa istirahat adalah bagian dari struktur.","guidance":"Sebelum hari berakhir, ingatlah: Bangunlah untuk jangka panjang sambil mengingat bahwa istirahat adalah bagian dari struktur."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'week', 'id', '{"overview":"Minggu ini berkembang melalui pilihan-pilihan yang mantap daripada satu momen dramatis. Capricorn bergerak melalui energi bumi. Disiplin dan visi jangka panjang membantu Sea-Goat mendaki sambil tetap bijaksana tentang kedalaman di bawahnya.","love":"Hubungan mendapat manfaat dari percakapan yang memberi ruang untuk kejujuran dan kehangatan. Hadiah Anda berupa ketahanan, strategi, dan dapat diandalkan dapat membantu Anda terhubung tanpa harus berpura-pura.","career":"Kemajuan profesional terbaik Anda datang dari memilih prioritas dan melindungi waktu untuk itu. Gunakan ambisius, disiplin, sabar, bertanggung jawab sebagai alat, bukan harapan yang harus Anda penuhi sekaligus.","finance":"Tinjau pola di balik pengeluaran Anda sebelum membuat komitmen yang lebih besar. Perhatikan kapan kekakuan, pesimisme, menilai nilai melalui pencapaian mulai memengaruhi keputusan praktis.","wellbeing":"Seimbangkan pergerakan dengan pemulihan yang sejati sepanjang minggu. Bangun untuk jangka panjang sambil mengingat bahwa istirahat adalah bagian dari strukturnya.","guidance":"Biarkan pertanyaan ini membimbing minggu ini: Bangun untuk jangka panjang sambil mengingat bahwa istirahat adalah bagian dari struktur."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'year', 'id', '{"overview":"Tahun ini mengundang pertumbuhan yang sabar seputar identitas, tujuan, dan cara Anda menggunakan energi Anda. Capricorn bergerak melalui energi bumi. Disiplin dan visi jangka panjang membantu Kambing Laut mendaki sambil tetap bijaksana mengenai kedalaman di bawah.","love":"Cinta semakin dalam ketika kamu mempraktikkan konsistensi dan membiarkan hubungan berkembang pada kecepatan manusia. Hadiahmu berupa ketahanan, strategi, dan dapat diandalkan dapat membantumu terhubung tanpa harus menunjukkan performa.","career":"Pekerjaan jangka panjang menjadi lebih kuat ketika ambisi dipadukan dengan struktur yang dapat Anda pertahankan. Gunakan ambisius, disiplin, sabar, bertanggung jawab sebagai alat, bukan sebagai harapan yang harus Anda penuhi sekaligus.","finance":"Bangun kepercayaan diri finansial melalui kebiasaan yang dapat diulang daripada prediksi yang sempurna. Perhatikan ketika kekakuan, pesimisme, dan menilai nilai melalui pencapaian mulai memengaruhi keputusan praktis.","wellbeing":"Anggap kesejahteraan sebagai fondasi untuk kehidupan yang sedang Anda bangun, bukan sebagai hadiah setelah menyelesaikannya. Bangunlah untuk jangka panjang sambil mengingat bahwa istirahat adalah bagian dari strukturnya.","guidance":"Kembali ke kompas ini sepanjang tahun: Bangunlah untuk jangka panjang sambil mengingat bahwa istirahat adalah bagian dari struktur."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aquarius', 'id', '{"name":"Aquarius","dateRange":"20 Jan – 18 Feb","rulingPlanet":"Uranus","summary":"Pemikiran independen dan visi kolektif membimbing Pembawa Air untuk menuangkan ide-ide baru ke dunia.","originStory":"Aquarius terkait dengan Ganymede, pembawa cawan yang wadahnya membawa air kepada para dewa dan, secara simbolis, pengetahuan bagi umat manusia. Meskipun gambarnya membawa air, tanda ini termasuk elemen udara: gagasan, sistem, dan pembaruan yang dibagikan untuk kebaikan bersama.","traits":["Asli","Mandiri","Kemanusiaan","Inventif"],"strengths":["Inovasi","Objektivitas","Visi komunitas"],"challenges":["Keterlepasan","Kebiasaan berlawanan","Pendapat tetap"],"compatibleSigns":["Gemini","Libra","Sagitarius"],"reflectionPrompt":"Biarkan perbedaanmu melayani koneksi daripada jarak."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'day', 'id', '{"overview":"Hari ini mendukung satu langkah yang jelas dan disengaja. Aquarius bergerak melalui energi udara. Pemikiran independen dan visi kolektif membimbing Pembawa Air untuk menuangkan ide-ide baru ke dunia.","love":"Dalam cinta hari ini, pilih kehadiran daripada asumsi. Karunia inovasi, objektivitas, visi komunitasmu dapat membantumu terhubung tanpa harus tampil.","career":"Di tempat kerja, selesaikan tugas yang paling bermakna sebelum mengejar momentum baru. Gunakan asli, mandiri, kemanusiaan, inventif sebagai alat, bukan harapan yang harus Anda penuhi sekaligus.","finance":"Pertahankan pilihan uang hari ini sederhana dan terhubung dengan kenyataan. Perhatikan ketika keterlepasan, kebiasaan bertentangan, atau opini tetap mulai memengaruhi keputusan praktis.","wellbeing":"Jeda kecil bisa mengatur ulang energi Anda. Biarkan perbedaan Anda melayani koneksi daripada menjadi jarak.","guidance":"Sebelum hari berakhir, ingatlah: Biarkan perbedaanmu melayani hubungan daripada menjauhkan."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'week', 'id', '{"overview":"Minggu ini berkembang melalui pilihan yang mantap daripada satu momen dramatis. Aquarius bergerak melalui energi udara. Pikiran yang mandiri dan visi kolektif membimbing Si Pembawa Air untuk menuangkan ide-ide baru ke dunia.","love":"Hubungan mendapatkan manfaat dari percakapan yang memberi ruang untuk kejujuran dan kehangatan. Bakat Anda dalam inovasi, objektivitas, dan visi komunitas dapat membantu Anda terhubung tanpa perlu berpura-pura.","career":"Kemajuan profesional terbaik Anda datang dari memilih prioritas dan melindungi waktu untuk itu. Gunakan orisinal, mandiri, kemanusiaan, inventif sebagai alat, bukan ekspektasi yang harus Anda penuhi sekaligus.","finance":"Tinjau pola di balik pengeluaran Anda sebelum membuat komitmen yang lebih besar. Perhatikan ketika keterlepasan, kebiasaan bertentangan, pendapat yang kaku mulai memengaruhi keputusan praktis.","wellbeing":"Seimbangkan gerakan dengan pemulihan yang nyata sepanjang minggu. Biarkan perbedaanmu menjadi penghubung, bukan pemisah.","guidance":"Biarkan pertanyaan ini membimbing minggu: Biarkan perbedaanmu menjadi sarana untuk menghubungkan, bukan menciptakan jarak."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'year', 'id', '{"overview":"Tahun ini mengundang pertumbuhan yang sabar seputar identitas, tujuan, dan cara Anda menggunakan energi. Aquarius bergerak melalui energi udara. Pemikiran mandiri dan visi kolektif membimbing Pembawa Air untuk menuangkan ide-ide baru ke dunia.","love":"Cinta semakin dalam ketika Anda menerapkan konsistensi dan membiarkan hubungan berkembang pada kecepatan manusia. Bakat Anda dalam inovasi, objektivitas, dan visi komunitas dapat membantu Anda terhubung tanpa harus tampil.","career":"Pekerjaan jangka panjang menjadi lebih kuat ketika ambisi dipadukan dengan struktur yang dapat Anda pertahankan. Gunakan asli, mandiri, humanis, inventif sebagai alat, bukan harapan yang harus Anda penuhi sekaligus.","finance":"Bangun kepercayaan diri finansial melalui kebiasaan yang dapat diulang alih-alih prediksi yang sempurna. Perhatikan ketika keterlepasan, kebiasaan kontrarian, pendapat yang tetap mulai memengaruhi keputusan yang praktis.","wellbeing":"Anggap kesejahteraan sebagai dasar untuk kehidupan yang sedang Anda bangun, bukan sebagai hadiah setelah menyelesaikannya. Biarkan perbedaan Anda melayani keterhubungan daripada menjauhkan.","guidance":"Kembali ke kompas ini sepanjang tahun: Biarkan perbedaan Anda melayani koneksi daripada menjauhkan."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('pisces', 'id', '{"name":"Pisces","dateRange":"19 Feb – 20 Mar","rulingPlanet":"Neptunus","summary":"Belas kasih dan imajinasi membimbing Ikan di antara intuisi, mimpi, dan perasaan bersama.","originStory":"Pisces mengingat kembali Aphrodite dan Eros yang menjadi ikan dan saling mengikat untuk melarikan diri dari Typhon. Ikatan antara kedua ikan tersebut melambangkan pengabdian, identitas yang luwes, sensitivitas spiritual, dan menemukan kesatuan saat bergerak melalui aliran yang berubah.","traits":["Penuh belas kasih","Imaginatif","Intuitif","Lembut"],"strengths":["Empati","Kreativitas","Wawasan spiritual"],"challenges":["Pelarian","Batas yang kabur","Menyerap emosi orang lain"],"compatibleSigns":["Kanker","Scorpio","Capricorn"],"reflectionPrompt":"Hormati kepekaan Anda dengan batasan yang cukup kuat untuk melindunginya."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'day', 'id', '{"overview":"Hari ini menguntungkan satu langkah yang jelas dan disengaja. Pisces bergerak melalui energi air. Belas kasih dan imajinasi membimbing Ikan antara intuisi, mimpi, dan perasaan yang dibagi.","love":"Dalam cinta hari ini, pilih kehadiran daripada asumsi. Bakat Anda dalam empati, kreativitas, dan wawasan spiritual dapat membantu Anda terhubung tanpa harus tampil.","career":"Di tempat kerja, selesaikan tugas yang paling bermakna sebelum mengejar momentum baru. Gunakan penuh kasih, imajinatif, intuitif, lembut sebagai alat, bukan harapan yang harus Anda penuhi sekaligus.","finance":"Jaga pilihan uang hari ini tetap sederhana dan terarah. Perhatikan ketika pelarian, batas yang kabur, dan menyerap emosi orang lain mulai memengaruhi keputusan praktis.","wellbeing":"Jeda kecil bisa mengatur ulang energi Anda. Hargai kepekaan Anda dengan batasan yang cukup kuat untuk melindunginya.","guidance":"Sebelum hari berakhir, ingatlah: Hormatilah sensitivitasmu dengan batasan yang cukup kuat untuk melindunginya."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'week', 'id', '{"overview":"Minggu ini berkembang melalui pilihan yang stabil daripada satu momen dramatis. Pisces bergerak melalui energi air. Belas kasih dan imajinasi membimbing para Ikan antara intuisi, mimpi, dan perasaan yang dibagikan.","love":"Hubungan mendapat manfaat dari percakapan yang memberi ruang untuk kejujuran dan kehangatan. Karunia Anda dalam empati, kreativitas, dan wawasan spiritual dapat membantu Anda terhubung tanpa harus berpura-pura.","career":"Kemajuan profesional terbaik Anda datang dari memilih prioritas dan melindungi waktu untuk itu. Gunakan belas kasih, imajinatif, intuitif, lembut sebagai alat, bukan harapan yang harus Anda penuhi sekaligus.","finance":"Tinjau pola di balik pengeluaran Anda sebelum membuat komitmen yang lebih besar. Perhatikan ketika melarikan diri dari kenyataan, batasan yang kabur, menyerap emosi orang lain mulai memengaruhi keputusan praktis.","wellbeing":"Seimbangkan gerakan dengan pemulihan yang nyata sepanjang minggu. Hormati kepekaanmu dengan batasan yang cukup kuat untuk melindunginya.","guidance":"Biarkan pertanyaan ini membimbing minggu: Hormati kepekaanmu dengan batasan yang cukup kuat untuk melindunginya."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'year', 'id', '{"overview":"Tahun ini mengundang pertumbuhan yang sabar seputar identitas, tujuan, dan cara Anda menggunakan energi. Pisces bergerak melalui energi air. Belas kasih dan imajinasi membimbing Pisces antara intuisi, mimpi, dan perasaan yang dibagi.","love":"Cinta semakin dalam ketika kamu mempraktikkan konsistensi dan membiarkan hubungan berkembang pada kecepatan manusia. Bakatmu dalam empati, kreativitas, dan wawasan spiritual dapat membantumu terhubung tanpa harus menunjukkan performa.","career":"Pekerjaan jangka panjang menjadi lebih kuat ketika ambisi dipadukan dengan struktur yang dapat Anda pertahankan. Gunakan penuh kasih, imajinatif, intuitif, lembut sebagai alat, bukan ekspektasi yang harus Anda penuhi sekaligus.","finance":"Bangun kepercayaan diri finansial melalui kebiasaan yang dapat diulang alih-alih prediksi yang sempurna. Perhatikan ketika pelarian, batas yang kabur, menyerap emosi orang lain mulai memengaruhi keputusan yang praktis.","wellbeing":"Anggap kesejahteraan sebagai dasar untuk hidup yang sedang Anda bangun, bukan sebagai hadiah setelah menyelesaikannya. Hormati kepekaan Anda dengan batasan yang cukup kuat untuk melindunginya.","guidance":"Kembali ke kompas ini sepanjang tahun: Hormati kepekaanmu dengan batasan yang cukup kuat untuk melindunginya."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('fool', 'hi', '{"name":"मूर्ख","meaning":"एक खाली पृष्ठ और विश्वास की छलांग — एक नई यात्रा खुले दिल से शुरू होती है।","advice":"अपने सामने के रास्ते पर भरोसा करें और पहला कदम उठाएँ, भले ही सभी उत्तर आपके पास न हों।","yesNoMeaning":"एक नई शुरुआत शायद ही कभी एक निश्चित उत्तर लेकर आती है — परिणाम उस कदम पर निर्भर करता है जो आप उठाते हैं।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('magician', 'hi', '{"name":"मैजिशियन","meaning":"आपके पास सभी आवश्यक उपकरण हैं। अपनी इच्छा पर ध्यान केंद्रित करें और इरादे को क्रिया में बदलें।","advice":"अपने कौशल और संसाधनों का जानबूझकर उपयोग करें — अब इसे करने का समय है।","yesNoMeaning":"आपके पास पहले से ही सब कुछ है जो आवश्यक है — ऊर्जा आगे बढ़ने और केंद्रित रहने में सहायक है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('high-priestess', 'hi', '{"name":"द हाई प्रीस्टेस","meaning":"शांत बुद्धिमत्ता सतह के नीचे छिपी होती है। अपनी अंतरदृष्टि और आंतरिक आवाज़ सुनें।","advice":"रोकें, अंदर की ओर जाएं, और कार्रवाई करने से पहले अपने अंतर्ज्ञान को मार्गदर्शन करने दें।","yesNoMeaning":"उत्तर अभी सतह के नीचे छिपा है — स्पष्ट हाँ या नहीं को जबरदस्ती करने के बजाय अपनी अंतर्दृष्टि पर भरोसा करें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('empress', 'hi', '{"name":"रानी","meaning":"विकास, समृद्धि और पोषणकारी ऊर्जा आपके चारों ओर है। सुंदरता और देखभाल को खिलने दें।","advice":"धैर्यशील और उदार बनें — प्यार के साथ सृजन करें और चीज़ों को स्वाभाविक रूप से पकने दें।","yesNoMeaning":"विकास, समृद्धि और पोषणकारी ऊर्जा आपकी इच्छा का समर्थन करती हैं — उत्तर एक शांत हाँ है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('emperor', 'hi', '{"name":"साम्राज्यकारी","meaning":"संरचना, अधिकार, और स्थिर नेतृत्व। अनुशासन के साथ ठोस जमीन पर निर्माण करें।","advice":"साफ़ योजना के साथ जिम्मेदारी लें; ठोस सीमाएं स्थायी स्थिरता लाती हैं।","yesNoMeaning":"संरचना, अधिकार और स्थिर अनुशासन आत्मविश्वासी हाँ के पीछे खड़ा है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hierophant', 'hi', '{"name":"द हायरोफैंट","meaning":"परंपरा और भरोसेमंद मार्गदर्शन एक विश्वसनीय रास्ता प्रदान करते हैं। जो पहले आया है उससे सीखें।","advice":"स्थापित ज्ञान का पालन करें और उन लोगों से परामर्श लें जिन पर आप भरोसा करते हैं।","yesNoMeaning":"परंपरा और भरोसेमंद मार्गदर्शन एक विश्वसनीय हाँ की ओर संकेत करते हैं — उस पर भरोसा करें जो पहले से ही अपने आप को साबित कर चुका है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('lovers', 'hi', '{"name":"लवर्स","meaning":"एक महत्वपूर्ण संबंध या एक महत्वपूर्ण विकल्प। उस चीज़ का पालन करें जिसे आपका दिल वास्तव में महत्व देता है।","advice":"ईमानदारी और संरेखण के साथ चुनें — जब आप सच्चे होते हैं तो संबंध गहरा होता है।","yesNoMeaning":"यहाँ आपका दिल और मूल्य संरेखित हैं — उत्तर हाँ है, खासकर जब आप ईमानदारी के साथ चुनाव करते हैं।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('chariot', 'hi', '{"name":"सिंहासन","meaning":"इच्छाशक्ति और गति आपको आगे बढ़ाती हैं। केंद्रित रहें और आप सफल होंगे।","advice":"अपने लक्ष्य पर ध्यान रखें और हर बाधा के माध्यम से आत्मविश्वास के साथ मार्गदर्शन करें।","yesNoMeaning":"इच्छाशक्ति और गति आपके पक्ष में हैं — एक केंद्रित हाँ, बशर्ते आप प्रतिबद्ध रहें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('strength', 'hi', '{"name":"शक्ति","meaning":"सच्ची शक्ति कोमल होती है — धैर्य, साहस, और सहानुभूति किसी भी चुनौती को काबू में कर सकती है।","advice":"शांत ताकत के साथ नेतृत्व करें; एक नरम हाथ अक्सर सबसे मजबूत होता है।","yesNoMeaning":"नम्र साहस और धैर्यपूर्ण संकल्प इसे हाँ बनाते हैं — शक्ति से नहीं, शांति से नेतृत्व करें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hermit', 'hi', '{"name":"द हर्मिट","meaning":"समय है पीछे हटने और आंतरिक स्पष्टता खोजने का। विश्राम अब गहरे उत्तर लाता है।","advice":"अंदर की ओर मुड़ें, विचार करें, और शांति से यह जानने दें कि आपको वास्तव में क्या चाहिए।","yesNoMeaning":"अभी नहीं — कार्ड आपसे कहता है कि कार्रवाई करने से पहले पीछे हटकर आंतरिक स्पष्टता खोजें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('wheel-of-fortune', 'hi', '{"name":"भाग्य का चक्र","meaning":"भाग्य बदलता है और चक्र बदलते हैं। अब जो बदलाव हो रहे हैं, वह एक बड़े लय का हिस्सा हैं।","advice":"लचीलापन के साथ प्रवाह का आनंद लें — मोड़ को स्वीकार करें, चाहे अच्छा हो या अन्यथा।","yesNoMeaning":"भाग्य बदल रहा है — परिणाम इस बात पर निर्भर करता है कि आप बदलाव को कैसे संभालते हैं, न कि एक निश्चित हाँ या ना पर।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('justice', 'hi', '{"name":"न्याय","meaning":"सच्चाई और निष्पक्षता ही दिन को जीताते हैं। कारण और परिणाम अब संतुलन में आते हैं।","advice":"ईमानदारी से काम करें और दोनों पक्षों को तौलें; तराजू निष्पक्ष रूप से संतुलित होंगे।","yesNoMeaning":"तराजू अभी भी तौल रहे हैं — निष्पक्ष उत्तर तथ्यों और आपकी ईमानदारी पर निर्भर करता है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hanged-man', 'hi', '{"name":"हैंग्ड मैन","meaning":"एक आवश्यक विराम। नियंत्रण छोड़ें और स्थिति को नए दृष्टिकोण से देखें।","advice":"धक्कामुक्की करना बंद करें — क्षण को स्वीकार करें और नई दृष्टि आने दें।","yesNoMeaning":"पहले विराम की आवश्यकता है — इसे अभी जबरदस्ती करना केवल स्पष्ट उत्तर को रोक देगा।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('death', 'hi', '{"name":"मृत्यु","meaning":"एक अंत नवीनीकरण के लिए रास्ता साफ करता है। जिसे अपना समय पूरा कर लिया है उसे छोड़ दें।","advice":"पछतावा किए बिना छोड़ दें; एक गहन परिवर्तन एक नया दरवाज़ा खोल रहा है।","yesNoMeaning":"एक अंत रास्ता साफ कर रहा है — वर्तमान मार्ग बंद हो रहा है ताकि एक नया मार्ग शुरू हो सके।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('temperance', 'hi', '{"name":"संयम","meaning":"संतुलन और धैर्य सामंजस्य लाते हैं। विपरीतों को कृपा के साथ मिलाएँ।","advice":"संतुलन में चलें और अपनी शांति बनाए रखें — स्थिर कदम मंजिल तक पहुंचते हैं।","yesNoMeaning":"संतुलन और धैर्य सामंजस्य लाते हैं — एक मापा हुआ हाँ, धीरे-धीरे एक कदम में लिया गया।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('devil', 'hi', '{"name":"शैतान","meaning":"आसक्ति, प्रलोभन, या बंधनकारी पैटर्न से सावधान रहें। श्रृंखलाओं को पहचानें।","advice":"उस चीज़ को नाम दें जो आपको रोकती है और अपनी स्वतंत्रता वापस पाएं — जंजीर केवल तब बंधती है जब आप इसे अनुमति दें।","yesNoMeaning":"असक्ति या एक बंधन पैटर्न रास्ते में खड़ा होता है — अभी नहीं, जब तक श्रृंखला का नाम न रखा जाए और तोड़ा न जाए।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('tower', 'hi', '{"name":"टॉवर","meaning":"अचानक परिवर्तन झूठ को तोड़ता है और सत्य को प्रकट करता है। जो गिरता है वह कभी स्थायी नहीं था।","advice":"विपरीत परिस्थितियों का स्वागत करें; मलबे से एक स्पष्ट नींव बनाई जा सकती है।","yesNoMeaning":"अचानक परिवर्तन पुराना तोड़ रहा है — स्थिर हाँ संभव होने से पहले जमीन को जमना चाहिए।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('star', 'hi', '{"name":"स्टार","meaning":"आशा, उपचार और शांत प्रेरणा तूफान के बाद आपकी आत्मा को नवीनीकरण देती है।","advice":"आगे की रोशनी पर विश्वास रखें और विश्वास करते रहें — आपकी इच्छाएँ पहुँच के भीतर हैं।","yesNoMeaning":"आशा और शांत नवीनीकरण हाँ की ओर संकेत करते हैं — आने वाले प्रकाश पर भरोसा करें और अपनी इच्छा को जीवित रखें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('moon', 'hi', '{"name":"मून","meaning":"भ्रम और अनिश्चितता रास्ते को धुंधला कर देते हैं। appearances पर नहीं, अपनी अंतर्ज्ञान पर भरोसा करें।","advice":"धीरे हो जाएँ और गहराई से देखें; स्पष्टता तब आएगी जब धुंध छट जाएगी।","yesNoMeaning":"भ्रम और अनिश्चितता रास्ते को धुंधला कर देते हैं — जवाब स्पष्ट नहीं होता जब तक आप बाहरी रूपों के नीचे नहीं देखते।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('sun', 'hi', '{"name":"सन","meaning":"खुशी, सफलता, और प्रज्वलित स्पष्टता। सब कुछ उज्ज्वल और जीवन से भरा हुआ है।","advice":"जश्न मनाएं और चमकें — सकारात्मक ऊर्जा उन परिणामों को आकर्षित करती है जो आप चाहते हैं।","yesNoMeaning":"खुशी और प्रज्वलित स्पष्टता एक उज्ज्वल हां की पुष्टि करती है — सब कुछ आपके पक्ष में काम कर रहा है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('judgement', 'hi', '{"name":"न्याय","meaning":"उठने, नवीनीकृत होने और अपने साथ ईमानदार होने का आह्वान। जागृति का निर्णय।","advice":"साहस के साथ कॉल का जवाब दें; अतीत को क्षमा करें और अपने अगले अध्याय में कदम रखें।","yesNoMeaning":"उठने और नवीनीकरण का आह्वान — हाँ, विशेष रूप से जब आप अतीत को माफ कर देते हैं और ईमानदारी से उत्तर देते हैं।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('world', 'hi', '{"name":"दुनिया","meaning":"समापन और पूर्ति — एक चक्र पूर्णता में बंद होता है।","advice":"आपने जो हासिल किया है उसका जश्न मनाएं; दरवाजा एक व्यापक दुनिया के लिए खुला है।","yesNoMeaning":"समापन और पूर्णता इसे एक पूर्ण हां के रूप में चिह्नित करती है — चक्र आपके पक्ष में बंद होता है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-wands', 'hi', '{"name":"छड़ी का एस","meaning":"प्रेरणा की एक चिंगारी एक साहसी रचनात्मक रास्ता खोलती है।","advice":"ताजगी भरी ऊर्जा के समय शुरू करें और विचार को एक वास्तविक पहला कदम दें।","yesNoMeaning":"डंडों का ऐस हां की ओर झुकाव रखता है: जब ऊर्जा ताज़ा हो, तब शुरुआत करें और विचार को वास्तविक पहला कदम दें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-wands', 'hi', '{"name":"दो छड़ें","meaning":"भविष्य योजना और दिशा के चुनाव के माध्यम से आकार ले रहा है।","advice":"जो परिचित है उसके परे देखें, फिर उस रास्ते के लिए प्रतिबद्ध हों जिसमें बढ़ने की जगह हो।","yesNoMeaning":"छड़ी की दोहरी शर्तों पर निर्भर रहती है: परिचित चीजों के परे देखें, फिर बढ़ने की जगह के साथ मार्ग को अपनाएँ।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-wands', 'hi', '{"name":"तीन छड़ें","meaning":"प्रारंभिक प्रयास जैसे-जैसे अवसर और व्यापक दृष्टिकोण सामने आते हैं, बढ़ता है।","advice":"निर्माण करते रहें और तैयार रहें कि आपका काम जिस प्रतिक्रिया को आकर्षित करता है उसे देखें।","yesNoMeaning":"डंडों का तीन हाँ की ओर झुकता है: निर्माण जारी रखें और अपने काम द्वारा आकर्षित प्रतिक्रिया के लिए तैयार रहें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-wands', 'hi', '{"name":"वांड का चार","meaning":"स्थिरता, स्वागत और साझा उत्सव एक मजबूत आधार बनाते हैं।","advice":"चिह्नित करें और सहायक लोगों को इसमें शामिल होने दें।","yesNoMeaning":"चार वैंड्स हां की ओर झुकते हैं: इस मील के पत्थर को चिह्नित करें और इसे साझा करने के लिए सहायक लोगों को अनुमति दें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-wands', 'hi', '{"name":"पाँच कांटे","meaning":"प्रतिस्पर्धी लक्ष्य घर्षण, शोर या आत्मविश्वास की परीक्षा उत्पन्न करते हैं।","advice":"प्रतिस्पर्धा को उपयोगी अभ्यास में बदलें और ऐसे संघर्ष से इंकार करें जिसका कोई उद्देश्य न हो।","yesNoMeaning":"दस्तों का पांच शर्तीय बना रहता है: प्रतिद्वंद्विता को उपयोगी अभ्यास में बदलें और उस संघर्ष से इंकार करें जिसका कोई उद्देश्य नहीं है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-wands', 'hi', '{"name":"सिक्स ऑफ वैंड्स","meaning":"मान्यता का अनुसरण निर्धारित प्रयास और दृश्य प्रगति से होता है।","advice":"प्रोत्साहन को स्वीकार करें, लेकिन अपने आत्मविश्वास को ईमानदार काम से जोड़े रखें।","yesNoMeaning":"सिक्स ऑफ वैंड्स हाँ की ओर झुकता है: प्रोत्साहन को स्वीकार करें, लेकिन अपनी आत्मविश्वास ईमानदार काम से जुड़ा रखें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-wands', 'hi', '{"name":"कैंट का सात","meaning":"आप_PRESSURE परीक्षणों के बीच मूल्यवान जमीन बनाए रखते हैं।","advice":"जिन बातों की अहमियत है, उनकी रक्षा स्पष्ट सीमाओं के साथ करें बजाय हर चुनौती से लड़ने के।","yesNoMeaning":"सेवन ऑफ वैंड्स हाँ की ओर झुकता है: हर चुनौती से लड़ने के बजाय स्पष्ट सीमाओं के साथ महत्वपूर्ण चीजों की रक्षा करें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-wands', 'hi', '{"name":"डंडों के आठ","meaning":"घटनाएँ तेजी से घटित होती हैं, संदेश आते हैं, और गति देरी को दूर करती है।","advice":"तुरंत कार्रवाई करें और रास्ता खुला होने पर संचार को सीधा रखें।","yesNoMeaning":"छड़ी का आठ संकेत हाँ दर्शाता है: तुरंत कार्य करें और जब रास्ता खुला हो तो संचार को सीधे रखें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-wands', 'hi', '{"name":"नाइन ऑफ वैंड्स","meaning":"लचीलापन मजबूत होता है, हालांकि अतीत की कठिनाइयाँ आपको सतर्क बनाती हैं।","advice":"अपनी ऊर्जा की सुरक्षा करें और अगला कदम उठाएँ बिना यह उम्मीद किए कि हर घाव दोहराएगा।","yesNoMeaning":"नाइन ऑफ वांड्स शर्तीय बना रहता है: अपनी ऊर्जा की रक्षा करें और अगले कदम को बिना हर घाव दोहराए होने की उम्मीद किए उठाएं।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-wands', 'hi', '{"name":"डंडों का दस","meaning":"जिम्मेदारी भारी हो गई है और सफलता अब बोझ उठाती है।","advice":"कार्य सौंपें, सरल बनाएं, और उस काम को छोड़ दें जो अब वास्तव में आपका नहीं है।","yesNoMeaning":"डंडों का दस नहीं की ओर झुकता है: कार्य सौंपें, सरल बनाएं, और उस काम को छोड़ दें जो अब वास्तव में आपका नहीं है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-wands', 'hi', '{"name":"वैंड्स का पृष्ठ","meaning":"जिज्ञासा एक जीवंत संदेश, प्रयोग या नए रचनात्मक रुचि को लाती है।","advice":"साहस के साथ खोज करें और शुरुआत की ऊर्जा आपको क्रियाओं के माध्यम से सिखाए।","yesNoMeaning":"पेज ऑफ वांड्स हाँ की ओर झुकाव रखता है: साहस के साथ खोज करें और शुरुआती ऊर्जा को क्रिया के माध्यम से सीखने दें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-wands', 'hi', '{"name":"वैंड्स का नाइट","meaning":"जोशीली भावना जल्दी आगे बढ़ती है, साहसिक कार्य और संभावित अधीरता लाती है।","advice":"गति का उपयोग करें, लेकिन गति आपके प्रयास को फैलाने से पहले दिशा चुनें।","yesNoMeaning":"वांड्स का नाइट शर्तीय रहता है: गति का उपयोग करें, लेकिन दिशा चुनें इससे पहले कि गति आपके प्रयास को बिखेर दे।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-wands', 'hi', '{"name":"वांड्स की रानी","meaning":"गर्मी भरोसा और रचनात्मक स्वतंत्रता दूसरों को आपकी दृष्टि की ओर खींचती है।","advice":"अपनी उपस्थिति पर भरोसा करें, दूसरों को प्रोत्साहित करें, और अपनी महत्वाकांक्षा को छोटा न करें।","yesNoMeaning":"वैंड्स की रानी झुकती है हाँ की ओर: अपनी उपस्थिति पर विश्वास करें, दूसरों को प्रोत्साहित करें, और अपनी महत्वाकांक्षा को मत घटाएं।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-wands', 'hi', '{"name":"वैंड्स का राजा","meaning":"परिपक्व दृष्टि प्रेरणा को निर्णायक और नैतिक नेतृत्व में बदल देती है।","advice":"बड़े उद्देश्य से नेतृत्व करें और दूसरों को योगदान करने की जगह दें।","yesNoMeaning":"किंग ऑफ वैंड्स हां की ओर झुकते हैं: बड़े उद्देश्य से नेतृत्व करें और दूसरों को योगदान देने के लिए स्थान दें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-cups', 'hi', '{"name":"कप्स का ऐस","meaning":"दिल नए स्नेह, करुणा, और भावनात्मक पुनर्नवीनीकरण के लिए खुलता है।","advice":"भावना को ईमानदारी से स्वीकार करें और बिना किसी परिणाम की मजबूरी के देखभाल का प्रवाह होने दें।","yesNoMeaning":"कपों का ऐस हां की ओर झुकाव रखता है: भावना को ईमानदारी से स्वीकार करें और परिणाम को ज़बरदस्ती किए बिना देखभाल बहने दें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-cups', 'hi', '{"name":"दो कप्स","meaning":"पारस्परिक मान्यता साझेदारी, आकर्षण, या सच्चे समझौते को जन्म देती है।","advice":"दूसरे व्यक्ति से समानता के साथ मिलें और दिल से बोलें।","yesNoMeaning":"कप की दोहरी हाँ की ओर झुकती है: दूसरे व्यक्ति से बराबरी के रूप में मिलें और दिल से बोलें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-cups', 'hi', '{"name":"तीन प्यालों का","meaning":"मित्रता, समुदाय और साझा खुशी भावनात्मक समर्थन लाती हैं।","advice":"साथ में जश्न मनाएं और याद रखें कि वास्तव में कौन आपके लिए मौजूद है।","yesNoMeaning":"प्यालों का तीन हाँ की ओर झुकता है: साथ मिलकर जश्न मनाएं और याद रखें कि वास्तव में कौन आपके लिए उपस्थित होता है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-cups', 'hi', '{"name":"कप का चार","meaning":"भावनात्मक पीछे हटना किसी उपलब्ध उपहार को नोटिस करना मुश्किल बना देता है।","advice":"तुलना को रोकें और फिर से देखें कि क्या चुपचाप प्रस्तुत किया जा रहा है।","yesNoMeaning":"कप का चार झुकाव नहीं: तुलना को रोकें और फिर से देखें कि क्या शांतिपूर्वक प्रस्तुत किया जा रहा है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-cups', 'hi', '{"name":"पांच पत्तों का कप","meaning":"हानि उस चीज़ की ओर ध्यान खींचती है जो बिखरी, जबकि कुछ महत्वपूर्ण बना रहता है।","advice":"निराशा का सम्मान करें, फिर उस समर्थन की ओर मुड़ें जो अभी भी मौजूद है।","yesNoMeaning":"कप का पांच संकेत नहीं दर्शाता: निराशा का सम्मान करें, फिर उस समर्थन की ओर मुड़ें जो अभी भी मौजूद है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-cups', 'hi', '{"name":"सिक्स ऑफ कप्स","meaning":"स्मृति, मासूमियत, या परिचित संबंध सौम्य गर्माहट के साथ लौटता है।","advice":"भूत की दया का स्वागत करें बिना यह दिखावा किए कि आपको फिर से वहां रहना चाहिए।","yesNoMeaning":"सिक्स ऑफ कप्स हाँ की ओर झुकता है: अतीत की दयालुता का स्वागत करें बिना यह दिखावे के कि आपको फिर से वहां जीना होगा।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-cups', 'hi', '{"name":"कप का सात","meaning":"कई आकर्षक संभावनाएं दृष्टि और भ्रम के बीच का अंतर धुंधला करती हैं।","advice":"विकल्पों को सीमित करें और किसी एक सपने की वास्तविकता के साथ जाँच करें, फिर ही प्रतिबद्ध हों।","yesNoMeaning":"कप्स का सात अभी स्पष्ट नहीं है: विकल्पों को सीमित करें और प्रतिबद्ध होने से पहले एक सपना को वास्तविकता के खिलाफ परखें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-cups', 'hi', '{"name":"कप के आठ","meaning":"एक बार अर्थपूर्ण स्थिति अब हृदय को पोषण नहीं देती।","advice":"ईमानदारी के साथ छोड़ें और उस गहरे संतोष की ओर बढ़ें जिसकी आपको अब आवश्यकता है।","yesNoMeaning":"कप का आठ संकेत नहीं दर्शाता: ईमानदारी के साथ छोड़ें और उस गहरी पूर्ति की ओर बढ़ें जिसकी अब आपको आवश्यकता है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-cups', 'hi', '{"name":"नाइन ऑफ कप्स","meaning":"संतोष और कृतज्ञता एक दिल से की गई इच्छा को करीब महसूस कराते हैं।","advice":"जो यहाँ है उसका आनंद लें और पूछें कि क्या आपकी इच्छा आपके गहरे मूल्यों की भी सेवा करती है।","yesNoMeaning":"कप्स का नौ हां की ओर झुकता है: जो है उसका आनंद लें और यह पूछें कि क्या यह इच्छा आपके गहरे मूल्यों की भी सेवा करती है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-cups', 'hi', '{"name":"कपों का दस","meaning":"घर में भावनात्मक सामंजस्य, अपनापन और स्थायी संबंध मौजूद हैं।","advice":"उन बंधनों का पोषण करें जो खुशी को स्थायी और साझा बनाते हैं।","yesNoMeaning":"टेन ऑफ कप्स हाँ की ओर झुकता है: उन संबंधों को पोषित करें जो खुशी को टिकाऊ और साझा बनाते हैं।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-cups', 'hi', '{"name":"कप्स का पृष्ठ","meaning":"एक कोमल संदेश या सहज खोज भावनात्मक openness को आमंत्रित करता है।","advice":"भावना के प्रति जिज्ञासु रहें और अनुमान के बजाय ईमानदारी से प्रतिक्रिया दें।","yesNoMeaning":"पेज ऑफ कप्स शर्तीय बना रहता है: भावना के प्रति जिज्ञासु रहें और अनुमान के बजाय ईमानदारी से प्रतिक्रिया दें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-cups', 'hi', '{"name":"कप्स का नाइट","meaning":"रोमांस, कल्पना, या कोई आदर्श हृदय को आगे की तरफ खींचता है।","advice":"आमंत्रण का पालन करें, लेकिन वादों के खुलने के साथ एक पैर जमीन पर रखें।","yesNoMeaning":"नाइट ऑफ कप्स हां की ओर झुकते हैं: निमंत्रण का पालन करें, लेकिन जैसे-जैसे वादे खुलते हैं, एक पैर जमीन पर रखें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-cups', 'hi', '{"name":"कव्स की रानी","meaning":"गहरी सहानुभूति और Intuition सत्य के लिए एक शांत स्थान बनाती है।","advice":"सहानुभूतिपूर्वक सुनें जबकि उन सीमाओं को बनाए रखें जो देखभाल को स्वस्थ बनाए रखती हैं।","yesNoMeaning":"क्वीन ऑफ कप्स हाँ की ओर झुकाव रखती है: सहानुभूतिपूर्ण सुनें जबकि उन सीमाओं को बनाए रखें जो देखभाल को स्वस्थ रखती हैं।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-cups', 'hi', '{"name":"कप्स का राजा","meaning":"भावनात्मक परिपक्वता मजबूत भावनाओं को दबाए बिना स्थिर करता है।","advice":"करुणा और आत्म-आदेश के साथ जवाब दें, खासकर जब दूसरे प्रतिक्रियाशील हों।","yesNoMeaning":"किंग ऑफ कप्स हां की ओर झुकते हैं: सहानुभूति और आत्म-नियंत्रण के साथ प्रतिक्रिया दें, विशेष रूप से जब अन्य लोग प्रतिक्रिया कर रहे हों।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-swords', 'hi', '{"name":"तलवार का एस","meaning":"एक साफ़ समझ उलझन को काट देती है और एक नई सच्चाई प्रकट करती है।","advice":"मुद्दा स्पष्ट रूप से नाम दें और निष्पक्ष निर्णय के लिए स्पष्टता का उपयोग करें।","yesNoMeaning":"तलवारों का ऐस हां की ओर झुकाव रखता है: मुद्दे को स्पष्ट नाम दें और निष्पक्ष निर्णय की सेवा में स्पष्टता का उपयोग करें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-swords', 'hi', '{"name":"दो तलवारें","meaning":"सावधानीपूर्वक लंबित संतुलन उस चुनाव को स्थगित कर देता है जो हमेशा नहीं टाला जा सकता।","advice":"अन्धे पट्टे को धीरे-धीरे हटाएँ, गायब तथ्य इकट्ठा करें, और संतुलन से निर्णय लें।","yesNoMeaning":"तलवार की दोहरी अभी स्पष्ट नहीं है: आंखों पर पट्टी को धीरे से हटाएं, गायब तथ्य इकट्ठा करें, और संतुलन से निर्णय लें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-swords', 'hi', '{"name":"तीन तलवारें","meaning":"एक दुखद सत्य, अलगाव, या निराशा को स्वीकार करने की आवश्यकता होती है।","advice":"इस भावना को आपमें बहने दें और चोट को स्थायी कहानी में बदलने से बचें।","yesNoMeaning":"तलवारों का तीन नहीं की ओर झुकता है: भावना को अपने माध्यम से गुजरने दें और चोट को स्थायी कहानी में बदलने से बचें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-swords', 'hi', '{"name":"तलवार का चार","meaning":"दबाव या संघर्ष के बाद आराम और मानसिक शांति की आवश्यकता होती है।","advice":"उत्तर देने से पहले विराम लें; पुनर्प्राप्ति उत्पादक होती है जब यह स्पष्ट विचार को बहाल करता है।","yesNoMeaning":"तलवारों का चार झुकाव नहीं: उत्तर देने से पहले ठहरें; पुनर्प्राप्ति तब उत्पादक होती है जब यह स्पष्ट सोच को बहाल करती है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-swords', 'hi', '{"name":"पाँच तलवारें","meaning":"संघर्ष एक खोखली विजय उत्पन्न कर सकता है या विश्वास को नुकसान पहुंचा सकता है।","advice":"जीतने के बजाय गरिमा चुनें और उन रणनीतियों से दूर रहें जो बहुत महंगी पड़ती हैं।","yesNoMeaning":"तलवारों का पांच झुकाव नहीं: जीतने के बजाय प्रतिष्ठा को चुनें और उन रणनीतियों से दूर रहें जो बहुत अधिक कीमत लेती हैं।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-swords', 'hi', '{"name":"सिक्स ऑफ स्वॉर्ड्स","meaning":"एक कठिन मार्ग धीरे-धीरे शांत परिस्थितियों की ओर बढ़ता है।","advice":"जो आपने सीखा है उसे लें, समर्थन स्वीकार करें, और अराजकता से दूर चलते रहें।","yesNoMeaning":"सिक्स ऑफ स्वॉर्ड्स हाँ की ओर झुकता है: आपने जो सीखा है उसे अपनाएं, सहायता स्वीकार करें, और झगड़े से दूर चलते रहें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-swords', 'hi', '{"name":"तलवार का सात","meaning":"रणनीति, गोपनीयता, या परहेज़ मार्ग को जटिल बनाता है।","advice":"चतुराई से लेकिन पारदर्शी रूप से कार्य करें; ऐसे शॉर्टकट जो विश्वास को धोखा देंगे, वे समस्याओं के रूप में लौटेंगे।","yesNoMeaning":"स्वॉर्ड्स का सात झुकता है नहीं की ओर: चालाकी से लेकिन पारदर्शी रूप से कार्य करें; ट्रस्ट को धोखा देने वाले शॉर्टकट्स समस्याओं के रूप में वापस आएंगे।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-swords', 'hi', '{"name":"तलवारों के आठ","meaning":"भय और सीमित मान्यताएँ उपलब्ध विकल्पों को देखना कठिन बना देती हैं।","advice":"उस विचार पर सवाल करें जो कहता है कि आप फंसे हुए हैं और एक छोटा मुक्त करने वाला कदम उठाएँ।","yesNoMeaning":"तलवार का आठ संकेत नहीं दर्शाता: उस विचार पर प्रश्न उठाएं जो कहता है कि आप फंसे हुए हैं और एक छोटी मुक्ति की कार्रवाई करें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-swords', 'hi', '{"name":"नाइन ऑफ स्वोर्ड्स","meaning":"अवसाद अंधेरे में खतरे को बढ़ा देता है और मन को थका देता है।","advice":"भय को उजाले में लाएं, समर्थन मांगें, और तथ्यों को कल्पित परिणामों से अलग करें।","yesNoMeaning":"स्वॉर्ड्स का नौ नहीं की ओर झुकता है: डर को उजाले में लाएं, समर्थन खोजें, और तथ्यों को कल्पित परिणामों से अलग करें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-swords', 'hi', '{"name":"तलवारों का दस","meaning":"एक दर्दनाक चक्र अपनी अंतिम सीमा तक पहुँचता है और बिना बदले जारी नहीं रह सकता।","advice":"अंत को स्वीकार करें, अपनी रिकवरी की रक्षा करें, और एक अलग शुरुआत को उभरने दें।","yesNoMeaning":"तलवारों का दस नहीं की ओर झुकता है: अंत को स्वीकार करें, अपनी रिकवरी की रक्षा करें, और एक अलग शुरुआत को उभरने की अनुमति दें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-swords', 'hi', '{"name":"तलवारों का पृष्ठ","meaning":"सतर्क जिज्ञासा तथ्यों की खोज करती है, प्रश्न पूछती है, और बदलाव पर ध्यान देती है।","advice":"सावधानीपूर्वक अनुसंधान करें और हर संकेत पर प्रतिक्रिया देने के बजाय सटीकता के साथ बात करें।","yesNoMeaning":"पेज ऑफ स्वोर्ड्स शर्तीय बना रहता है: सावधानी से शोध करें और हर संकेत पर प्रतिक्रिया देने के बजाय सटीक बोलें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-swords', 'hi', '{"name":"स्वोर्ड्स का नाइट","meaning":"संकेंद्रित बुद्धि तेजी से चलती है और सीधे अवरोधों का सामना करती है।","advice":"साहस के साथ आगे बढ़ो, लेकिन इतना धीमे कि आप सुन सकें कि आपकी निश्चितता क्या मिस कर सकती है।","yesNoMeaning":"स्वॉर्ड्स का नाइट शर्तीय रहता है: साहस के साथ आगे बढ़ें, लेकिन इतना धीमा कि आप यह सुन सकें कि आपकी निश्चितता क्या छूट सकती है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-swords', 'hi', '{"name":"स्वॉर्ड्स की रानी","meaning":"स्पष्ट दृष्टि और ईमानदार सीमाएं भ्रम को दूर कर देती हैं।","advice":"सहानुभूति के साथ सत्य कहें और अनुभव को आपको कठोर बनाने न दें, बल्कि परिपक्व करें।","yesNoMeaning":"स्वॉर्ड्स की रानी झुकती है हाँ की ओर: सहानुभूति के साथ सच बोलें और अनुभव को आपको कठोर बनाने के बजाय तेज़ करे।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-swords', 'hi', '{"name":"स्वोर्ड्स का राजा","meaning":"तर्क, निष्पक्षता, और अनुशासित निर्णय एक महत्वपूर्ण निर्णय को मार्गदर्शित करते हैं।","advice":"साक्ष्यों का उपयोग करें, मानक को परिभाषित करें, और फैसले में व्यक्तिगत पक्षपात को बाहर रखें।","yesNoMeaning":"किंग ऑफ स्वॉर्ड्स हां की ओर झुकते हैं: साक्ष्य का उपयोग करें, मानक को परिभाषित करें, और व्यक्तिगत पक्षपात को निर्णय से दूर रखें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-pentacles', 'hi', '{"name":"पेंटाकल्स का ऐस","meaning":"एक ठोस अवसर समृद्धि, काम, या कल्याण का बीज प्रदान करता है।","advice":"अवसर को व्यावहारिक योजना में आधारित करें और इसका लगातार ख्याल रखें।","yesNoMeaning":"सिक्कों का ऐस हां की ओर झुकाव रखता है: अवसर को व्यावहारिक योजना में जमीन पर उतारें और लगातार इसका ख्याल रखें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-pentacles', 'hi', '{"name":"दो पेंटाकल्स","meaning":"कई प्राथमिकताएँ एक साथ गतिशील होती हैं और लचीले संतुलन की आवश्यकता होती है।","advice":"ताल को समायोजित करें, आवश्यकताओं की रक्षा करें, और उतना ही वादा करें जितना आप संभाल सकते हैं।","yesNoMeaning":"पैसों की दोहरी शर्तों पर निर्भर रहती है: तालमेल एडजस्ट करें, आवश्यकताओं की रक्षा करें, और जितना आप वहन कर सकते हैं उससे अधिक वादा करने से बचें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-pentacles', 'hi', '{"name":"तीन पेंटाकल्स","meaning":"कौशल सहयोग, प्रतिक्रिया और सावधानीपूर्वक शिल्पकला के माध्यम से बढ़ता है।","advice":"अपनी शक्ति का योगदान दें, विशेषज्ञता का सम्मान करें, और साझा मानक के अनुसार निर्माण करें।","yesNoMeaning":"पेंटाकल्स का तीन हाँ की ओर झुकता है: अपनी शक्ति का योगदान दें, विशेषज्ञता का सम्मान करें, और साझा मानक पर निर्माण करें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-pentacles', 'hi', '{"name":"पेंटाकल का चार","meaning":"सुरक्षा को मजबूती से पकड़ना संसाधनों को बचा सकता है लेकिन स्वस्थ प्रवाह को रोक सकता है।","advice":"जो महत्वपूर्ण है उसकी सुरक्षा करें बिना यह सोचे कि डर हर निर्णय आपके लिए ले।","yesNoMeaning":"पेंटाकल्स का चार शर्तीय बना रहता है: जो महत्वपूर्ण है उसकी रक्षा करें बिना यह डरने के कि हर निर्णय डर द्वारा प्रभावित हो।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-pentacles', 'hi', '{"name":"पाँच पेंटाकल्स","meaning":"भौतिक तनाव या बहिष्कार चिंता और कमी की भावना पैदा करता है।","advice":"व्यावहारिक मदद मांगें और उस दरवाजे पर ध्यान दें जिसे कठिनाई ने नजरअंदाज करने में आसान बना दिया है।","yesNoMeaning":"पेंटाकल्स का पांच झुकाव नहीं: व्यावहारिक मदद मांगें और उस दरवाजे पर ध्यान दें जिसे कठिनाई ने अनदेखा करना आसान बना दिया है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-pentacles', 'hi', '{"name":"सिक्स ऑफ पेंटाकल्स","meaning":"संसाधनों का आदान-प्रदान किया जाता है, जो उदारता, शक्ति, और निष्पक्षता के प्रश्न उठाता है।","advice":"स्पष्ट शर्तों के साथ दें या प्राप्त करें ताकि समर्थन दोनों पक्षों की गरिमा बनाए रखे।","yesNoMeaning":"सिक्स ऑफ पेंटाकल्स हाँ की ओर झुकता है: स्पष्ट शर्तों के साथ दें या प्राप्त करें ताकि सहायता दोनों पक्षों की गरिमा बनाए रखे।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-pentacles', 'hi', '{"name":"पेंटकल का सात","meaning":"धैर्यपूर्ण निवेश अगली कोशिश से पहले आकलन के बिंदु तक पहुँचता है।","advice":"जो बढ़ रहा है उसकी समीक्षा करें, विधि में सुधार करें, और मूल्यवान परिणामों को समय दें।","yesNoMeaning":"पेंटाकल्स का सात शर्तों पर निर्भर रहता है: जो बढ़ रहा है उसकी समीक्षा करें, तरीका सुधारें, और मूल्यवान परिणामों को समय दें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-pentacles', 'hi', '{"name":"पेंटकल के आठ","meaning":"संकेंद्रित पुनरावृत्ति महारत और भरोसेमंद परिणाम विकसित करती है।","advice":"मुख्य कौशल का अभ्यास करें, सुधार का स्वागत करें, और गुणवत्ता को जमा होने दें।","yesNoMeaning":"पेंटाकल का आठ संकेत हाँ दर्शाता है: आवश्यक कौशल का अभ्यास करें, सुधार का स्वागत करें, और गुणवत्ता को जमा होने दें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-pentacles', 'hi', '{"name":"नाइन ऑफ पेंटाकल्स","meaning":"आत्म-निर्भरता और संवर्धित आराम अनुशासित प्रगति को दर्शाते हैं।","advice":"जो आपने बनाया है उसका आनंद लें और स्वतंत्रता को कृतज्ञता से जोड़े रखें।","yesNoMeaning":"पेंटाकल्स का नौ हां की ओर झुकता है: जो आपने बनाया है उसका आनंद लें और स्वतंत्रता को कृतज्ञता से जोड़ें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-pentacles', 'hi', '{"name":"सिक्कों का दस","meaning":"दीर्घकालिक सुरक्षा विरासत, परिवार, और साझा आधारों के माध्यम से बढ़ती है।","advice":"तत्काल जीत से आगे योजना बनाएं और वह रक्षा करें जो समय के साथ दूसरों का समर्थन कर सकती है।","yesNoMeaning":"पेंटाकल्स का दस हाँ की ओर झुकता है: तत्काल जीत के परे योजना बनाएं और उस चीज की रक्षा करें जो समय के साथ दूसरों का समर्थन कर सकती है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-pentacles', 'hi', '{"name":"पेंटाकल्स का पृष्ठ","meaning":"एक व्यावहारिक संदेश अध्ययन, योजना या एक ठोस नई पहल का आमंत्रण देता है।","advice":"बुनियादी चीज़ें सीखें, अगला कार्य निर्धारित करें, और लगातार मेहनत से विचार को सिद्ध करें।","yesNoMeaning":"पेज ऑफ पेंटाकल्स हाँ की ओर झुकाव रखता है: मूल बातें सीखें, अगले कार्य को परिभाषित करें, और लगातार काम के माध्यम से विचार को प्रमाणित करें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-pentacles', 'hi', '{"name":"पेंटाकल्स का नाइट","meaning":"भरोसेमंद प्रयास धीरे-धीरे आगे बढ़ता है लेकिन ज़्यादातर काम को छोड़ता नहीं है।","advice":"रूटीन को ईमानदार और लगातार बनाए रखें; प्रगति उत्साह से अधिक महत्वपूर्ण है।","yesNoMeaning":"पेंटाकल्स का नाइट हां की ओर झुकता है: दिनचर्या ईमानदार और लगातार रखें; प्रगति उत्साह से अधिक महत्व रखती है।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-pentacles', 'hi', '{"name":"पेंटाकल्स की रानी","meaning":"संसाधन संपन्न देखभाल आराम, स्वास्थ्य, और व्यावहारिक समृद्धि पैदा करती है।","advice":"लोगों और योजनाओं की देखभाल ऐसे तरीकों से करें जो आपके लिए स्थायी हों।","yesNoMeaning":"पेंटाकल्स की रानी झुकती है हाँ की ओर: लोगों और योजनाओं का पोषण ऐसे तरीके से करें जो आपके लिए टिकाऊ रहें।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-pentacles', 'hi', '{"name":"पेंटाकल्स का राजा","meaning":"भौतिक नेतृत्व अनुभव को स्थिर और उदार प्रबंधन में बदल देता है।","advice":"दीर्घकालिक विकल्प बनाएं और सफलता का जिम्मेदारी से उपयोग करें।","yesNoMeaning":"किंग ऑफ पेंटाकल्स हां की ओर झुकते हैं: सही दीर्घकालिक विकल्प चुनें और सफलता का जिम्मेदारी से उपयोग करें।"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aries', 'hi', '{"name":"मेष","dateRange":"21 मार्च – 19 अप्रैल","rulingPlanet":"मंगल","summary":"साहसी शुरुआत और प्रत्यक्ष क्रियाएं राम को परिभाषित करती हैं, जिसकी चिंगारी इरादे को गति में बदल देती है।","originStory":"मेष को उस सुनहरे मेम्ने से जोड़ा जाता है जिसने ग्रीक पौराणिक कथा में फ्रीक्सस को बचाया। इसका ऊन बाद में जेसन और अर्गोनॉट्स का इनाम बन गया, जिससे यह संकेत साहस, बचाव और पहला साहसिक कदम का प्रतीक बन गया।","traits":["साहसी","ऊर्जावान","स्वतंत्र","प्रत्यक्ष"],"strengths":["पहल","आत्मविश्वास","लचीलापन"],"challenges":["अधीरता","आवेगशीलता","जितनी जल्दी आप शुरू करते हैं, उसे बनाए रखने से तेज़"],"compatibleSigns":["सिंह","धनु","मिथुन"],"reflectionPrompt":"एक साहसी शुरुआत चुनें और इसे बढ़ने के लिए पर्याप्त धैर्य दें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'day', 'hi', '{"overview":"आज एक स्पष्ट, जानबूझकर कदम लेने का दिन है। मेष अग्नि की ऊर्जा के माध्यम से चलता है। साहसी शुरुआतें और सीधे कार्य मेष को परिभाषित करते हैं, जिसकी चिंगारी इरादे को गति में बदल देती है।","love":"आज प्यार में, अनुमान के बजाय उपस्थिति चुनें। पहल, आत्मविश्वास, लचीलापन के आपके उपहार आपको बिना प्रदर्शन किए जुड़ने में मदद कर सकते हैं।","career":"काम पर, नए उत्साह का पीछा करने से पहले सबसे महत्वपूर्ण कार्य पूरा करें। साहसी, ऊर्जावान, स्वतंत्र, सीधा को उपकरण के रूप में उपयोग करें, ऐसी अपेक्षाएँ नहीं जिन्हें आपको एक बार में पूरा करना है।","finance":"आज के पैसे के फैसलों को सरल और ठोस रखें। ध्यान दें कि कब अधीरता, आवेग, अपने क्षमता से जल्दी शुरू करना एक व्यावहारिक निर्णय को प्रभावित करना शुरू करता है।","wellbeing":"एक छोटा विराम आपके ऊर्जा को पुनःस्थापित कर सकता है। एक साहसी शुरुआत चुनें और इसे बढ़ने के लिए पर्याप्त धैर्य दें।","guidance":"दिन खत्म होने से पहले, याद रखें: एक साहसी शुरुआत चुनें और उसे बढ़ने के लिए पर्याप्त धैर्य दें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'week', 'hi', '{"overview":"इस सप्ताह एक नाटकीय क्षण की बजाय स्थिर चुनावों के माध्यम से विकसित होता है। मेष अग्नि ऊर्जा के माध्यम से आगे बढ़ता है। साहसी शुरुआत और प्रत्यक्ष कार्रवाई मेष को परिभाषित करती है, जिसकी चिंगारी इरादे को गति में बदल देती है।","love":"रिश्ते उस बातचीत से लाभान्वित होते हैं जो ईमानदारी और गर्मजोशी दोनों के लिए जगह बनाती है। पहल, आत्मविश्वास, लचीलापन के आपके गुण बिना प्रदर्शन किए जुड़ने में मदद कर सकते हैं।","career":"आपकी सबसे अच्छी पेशेवर प्रगति प्राथमिकता चुनने और इसके लिए समय की रक्षा करने से आती है। साहसी, ऊर्जावान, स्वतंत्र, उपकरण के रूप में प्रत्यक्ष का उपयोग करें, अपेक्षाओं को नहीं जिन्हें आपको एक ही बार में पूरा करना चाहिए।","finance":"बड़ी प्रतिबद्धता बनाने से पहले अपनी खर्च करने की आदतों के पैटर्न की समीक्षा करें। ध्यान दें कि जब अधैर्य, आवेगपूर्ण व्यवहार, अपनी क्षमता से तेज़ शुरू करना व्यावहारिक निर्णय को प्रभावित करने लगते हैं।","wellbeing":"सप्ताह भर में असली पुनर्प्राप्ति के साथ गति को संतुलित करें। एक साहसी शुरुआत चुनें और इसे बढ़ने के लिए पर्याप्त धैर्य दें।","guidance":"इस प्रश्न को इस सप्ताह का मार्गदर्शन बनने दें: एक साहसी शुरुआत चुनें और उसे बढ़ने के लिए पर्याप्त धैर्य दें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'year', 'hi', '{"overview":"इस वर्ष पहचान, उद्देश्य और आपके ऊर्जा उपयोग के तरीके के आसपास धैर्यपूर्ण विकास का आमंत्रण है। मेष आग की ऊर्जा के माध्यम से चलता है। साहसी शुरुआत और प्रत्यक्ष कार्रवाई मेष को परिभाषित करती है, जिसकी चिंगारी इरादे को गति में बदल देती है।","love":"जब आप लगातार अभ्यास करते हैं और रिश्तों को मानव गति से विकसित होने देते हैं, तो प्यार गहरा होता है। आपकी पहल, आत्मविश्वास, लचीलापन की प्रतिभाएं आपको बिना प्रदर्शन किए जुड़ने में मदद कर सकती हैं।","career":"दीर्घकालिक कार्य अधिक मजबूत हो जाता है जब महत्वाकांक्षा को ऐसी संरचना के साथ जोड़ा जाए जिसे आप बनाए रख सकें। साहसी, ऊर्जावान, स्वतंत्र, और प्रत्यक्ष को उपकरण के रूप में इस्तेमाल करें, ऐसी उम्मीदें नहीं जिन्हें आपको एक साथ पूरी करनी हो।","finance":"सटीक भविष्यवाणियों के बजाय दोहराए जाने वाले आदतों के माध्यम से वित्तीय आत्मविश्वास बनाएं। ध्यान दें जब अधीरता, आवेग, जितनी तेजी से आप सहन कर सकते हैं उससे तेज़ी से शुरुआत करना एक व्यावहारिक निर्णय को प्रभावित करना शुरू करता है।","wellbeing":"कल्याण को उस जीवन के आधार के रूप में मानें जिसे आप बना रहे हैं, इसे समाप्त करने के बाद मिलने वाले इनाम के रूप में नहीं। एक साहसी शुरुआत चुनें और इसे बढ़ने के लिए पर्याप्त धैर्य दें।","guidance":"पूरे साल इस कंपास की ओर लौटें: एक साहसी शुरुआत चुनें और इसे बढ़ने के लिए पर्याप्त धैर्य दें।"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('taurus', 'hi', '{"name":"वृषभ","dateRange":"20 अप्रैल – 20 मई","rulingPlanet":"वीनस","summary":"स्थिर, कामुक और जमी हुई, बैल धैर्य और देखभाल के माध्यम से स्थायी मूल्य बनाता है।","originStory":"वृषभ जियस को एक भव्य सफेद बैल का रूप लेने और यूरोपा को समुद्र पार ले जाने के रूप में याद करता है। यह छवि सुंदरता, प्रजनन, सांसारिक समृद्धि, और शांत धैर्य के माध्यम से प्रकट शक्ति से जुड़ी हुई है।","traits":["जमीन से जुड़ा हुआ","वफादार","धैर्यशील","कामुक"],"strengths":["भरोसेमंदी","व्यावहारिक बुद्धि","भक्ति"],"challenges":["जिदगी","परिवर्तन के प्रति प्रतिरोध","बहुत लंबे समय तक पकड़े रहना"],"compatibleSigns":["कन्या","मकर","कैंसर"],"reflectionPrompt":"जो महत्वपूर्ण है उसकी सुरक्षा करें बिना आराम को स्थायित्व समझे।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'day', 'hi', '{"overview":"आज एक स्पष्ट, जानबूझकर किया गया कदम अनुकूल है। वृषभ पृथ्वी ऊर्जा के माध्यम से चलता है। स्थिर, संवेदनशील और जमीनी, वृषभ धैर्य और देखभाल के माध्यम से लंबी अवधि का मूल्य बनाता है।","love":"आज प्रेम में, अटकलों के बजाय उपस्थिति को चुनें। आपकी विश्वसनीयता, व्यावहारिक बुद्धि और भक्ति के उपहार आपको बिना प्रदर्शन किए जुड़ने में मदद कर सकते हैं।","career":"काम पर, नए उत्साह का पीछा करने से पहले सबसे महत्वपूर्ण कार्य पूरा करें। ज़मीन से जुड़ा हुआ, वफादार, धैर्यशील, और इंद्रियसंपन्न को उपकरण के रूप में उपयोग करें, न कि ऐसी अपेक्षाएँ जिन्हें आपको एक साथ पूरा करना है।","finance":"आज के धन के विकल्पों को सरल और ठोस रखें। ध्यान दें कि जब जिद, बदलाव का विरोध, लंबे समय तक पकड़ बनाए रखना किसी व्यावहारिक निर्णय को प्रभावित करना शुरू कर दे।","wellbeing":"एक छोटा विराम आपकी ऊर्जा को फिर से ताज़ा कर सकता है। जो महत्वपूर्ण है उसकी रक्षा करें, लेकिन आराम को स्थायित्व समझने की गलती न करें।","guidance":"दिन खत्म होने से पहले याद रखें: जो महत्वपूर्ण है उसकी रक्षा करें, बिना आराम को स्थायित्व समझे।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'week', 'hi', '{"overview":"इस सप्ताह धीरे-धीरे किए गए विकल्पों के माध्यम से विकसित होता है, न कि किसी एक नाटकीय क्षण से। वृषभ पृथ्वी की ऊर्जा के माध्यम से चलता है। स्थिर, संवेदी और जमीन से जुड़े, वृषभ धैर्य और देखभाल के माध्यम से स्थायी मूल्य बनाता है।","love":"संबंध उस बातचीत से लाभान्वित होते हैं जो ईमानदारी और गर्मजोशी दोनों के लिए स्थान बनाती है। आपकी विश्वसनीयता, व्यावहारिक बुद्धिमत्ता, और समर्पण की क्षमताएँ आपको प्रदर्शन किए बिना जुड़ने में मदद कर सकती हैं।","career":"आपकी सर्वोत्तम पेशेवर प्रगति किसी प्राथमिकता चुनने और उसके लिए समय सुरक्षित करने से आती है। निष्पक्ष, वफादार, धैर्यशील, संवेदनशील को उपकरण के रूप में इस्तेमाल करें, न कि ऐसी अपेक्षाएं जिन्हें आपको एक साथ पूरा करना हो।","finance":"बड़ी प्रतिबद्धता करने से पहले अपने खर्च करने की आदत का पैटर्न देखें। ध्यान दें कि कब जिद, बदलाव के प्रति प्रतिरोध, बहुत लंबे समय तक पकड़ बनाए रखना एक व्यावहारिक निर्णय को प्रभावित करना शुरू करता है।","wellbeing":"सप्ताह भर में वास्तविक पुनर्प्राप्ति के साथ आंदोलन का संतुलन बनाए रखें। जो महत्वपूर्ण है उसकी रक्षा करें, बिना आराम को स्थायित्व समझे।","guidance":"इस प्रश्न को सप्ताह का मार्गदर्शन करने दें: जो महत्वपूर्ण है उसकी रक्षा करें बिना आराम को स्थायित्व समझे।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'year', 'hi', '{"overview":"इस वर्ष पहचान, उद्देश्य और आपकी ऊर्जा के उपयोग के तरीके के आसपास धैर्यपूर्ण वृद्धि का आमंत्रण देता है। वृषभ पृथ्वी की ऊर्जा के माध्यम से चलता है। स्थिर, संवेदी, और जमी हुई, बैल धैर्य और देखभाल के माध्यम से स्थायी मूल्य बनाता है।","love":"जब आप निरंतरता का अभ्यास करते हैं और संबंध को मानवीय गति से विकसित होने देते हैं तो प्रेम गहरा होता है। आपकी विश्वसनीयता, व्यावहारिक बुद्धिमत्ता, और भक्ति की विशेषताएँ बिना प्रदर्शन के जुड़ने में आपकी मदद कर सकती हैं।","career":"दीर्घकालिक कार्य अधिक मजबूत हो जाता है जब महत्वाकांक्षा को ऐसी संरचना के साथ जोड़ा जाए जिसे आप बनाए रख सकें। जमीनी, वफादार, धैर्यवान, संवेदी को उपकरण के रूप में उपयोग करें, अपेक्षाओं के रूप में नहीं जिन्हें आपको एक बार में पूरा करना हो।","finance":"परफेक्ट भविष्यवाणियों के बजाय दोहराए जाने वाले अभ्यासों के माध्यम से वित्तीय आत्मविश्वास बनाएं। जब जिद, बदलाव के प्रति प्रतिरोध, या ज़्यादा देर तक पकड़ बनाए रखने की आदत व्यावहारिक निर्णय को प्रभावित करने लगे, तो उसका ध्यान दें।","wellbeing":"कल्याण को उस जीवन की नींव के रूप में मानें जिसे आप बना रहे हैं, न कि इसे खत्म करने के बाद मिलने वाले इनाम के रूप में। जो महत्वपूर्ण है उसकी रक्षा करें और आराम को स्थायित्व के रूप में न समझें।","guidance":"पूरा साल इस कम्पास की ओर लौटते रहो: जो महत्वपूर्ण है उसकी रक्षा करो बिना आराम को स्थायी समझे।"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('gemini', 'hi', '{"name":"मिथुन","dateRange":"21 मई – 20 जून","rulingPlanet":"बुध","summary":"जिज्ञासा और जुड़ाव जुड़वाँ राशि का मार्गदर्शन करते हैं, जो विचार इकट्ठा करते हैं और कहानी के एक से अधिक पहलू प्रकट करते हैं।","originStory":"मिथुन प्रतिनिधित्व करता है कास्टर और पॉलक्स, अविभाज्य जुड़वाँ जिन्होंने अलग न रहने के बजाय अमरता साझा की। उनका नक्षत्र साथ, दोहरी दृष्टिकोण, संवाद और दुनियाओं के बीच गति के विषय लाता है।","traits":["जिज्ञासु","अनुकूलनीय","अभिव्यक्तिशील","चतुर"],"strengths":["संचार","बहुमुखी प्रतिभा","तेज़ी से सीखना"],"challenges":["बेचैनी","बिखरी हुई एकाग्रता","अति सोच"],"compatibleSigns":["तुला","कुंभ","मेष"],"reflectionPrompt":"जिज्ञासा को दरवाज़ा खोलने दें, फिर उतनी देर रहें कि आप जो खोजते हैं उसे समझ सकें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'day', 'hi', '{"overview":"आज एक स्पष्ट, जानबूझकर कदम को प्रोत्साहन मिलता है। मिथुन वायु ऊर्जा के माध्यम से गतिशील होता है। जिज्ञासा और संबंध जुड़ाव उन जुड़वांओं का मार्गदर्शन करते हैं, जो विचार इकट्ठा करते हैं और किसी कहानी के एक से अधिक पहलू उजागर करते हैं।","love":"आज प्यार में, अनुमान के बजाय उपस्थिति को चुनें। संचार, बहुमुखी प्रतिभा, जल्दी सीखने की आपकी क्षमताएँ बिना प्रदर्शन किए जुड़ने में आपकी मदद कर सकती हैं।","career":"काम पर, नए उत्साह का पीछा करने से पहले सबसे महत्वपूर्ण कार्य पूरा करें। जिज्ञासु, अनुकूलनीय, अभिव्यक्तिशील, जल्दी समझने वाला को उपकरण के रूप में उपयोग करें, ऐसी अपेक्षाएँ नहीं जिन्हें आपको एक बार में पूरा करना है।","finance":"आज के पैसे के फैसलों को सरल और ठोस रखें। ध्यान दें कि कब बेचैनी, बिखरी हुई ध्यान, अत्यधिक सोच एक व्यावहारिक निर्णय को प्रभावित करने लगती है।","wellbeing":"एक छोटा विराम आपकी ऊर्जा को फिर से सेट कर सकता है। जिज्ञासा को दरवाजा खोलने दें, फिर जो आप पाते हैं उसे समझने के लिए पर्याप्त समय तक रुके रहें।","guidance":"दिन खत्म होने से पहले याद रखें: जिज्ञासा को दरवाजा खोलने दें, फिर जितना समझने के लिए समय लगे वहां रुके रहें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'week', 'hi', '{"overview":"इस सप्ताह एक नाटकीय क्षण की बजाय स्थिर विकल्पों के माध्यम से आगे बढ़ता है। मिथुन वायु ऊर्जा के माध्यम से चलता है। जिज्ञासा और संबंध जुड़नारों का मार्गदर्शन करते हैं, जो विचार इकट्ठा करते हैं और किसी कहानी के एक से अधिक पहलू उजागर करते हैं।","love":"संबंधों को ऐसे संवाद से लाभ मिलता है जो ईमानदारी और गर्मजोशी दोनों के लिए स्थान बनाता है। आपकी संचार, बहुमुखी प्रतिभा, और तेजी से सीखने की क्षमताएँ आपको प्रदर्शन किए बिना जुड़ने में मदद कर सकती हैं।","career":"आपकी सबसे अच्छी पेशेवर प्रगति प्राथमिकता चुनने और इसके लिए समय की रक्षा करने से आती है। उपकरण के रूप में जिज्ञासु, अनुकूलनीय, अभिव्यंजक, तेज-तर्रार का उपयोग करें, न कि अपेक्षाओं को आपको एक ही बार में पूरा करना चाहिए।","finance":"बड़ी प्रतिबद्धता करने से पहले अपने खर्च करने की आदत का पैटर्न देखें। ध्यान दें कि कब बेचैनी, ध्यान भटकना, अधिक सोचने की आदत एक व्यावहारिक निर्णय को प्रभावित करना शुरू करती है।","wellbeing":"सप्ताह भर में वास्तविक पुनर्प्राप्ति के साथ आंदोलन का संतुलन बनाए रखें। जिज्ञासा को दरवाजा खोलने दें, फिर जो आप पाते हैं उसे समझने के लिए पर्याप्त समय तक वहीं रहें।","guidance":"इस प्रश्न को इस सप्ताह का मार्गदर्शन बनने दें: जिज्ञासा को दरवाजा खोलने दें, फिर वहां इतने समय तक रहें कि आप जो पाते हैं उसे समझ सकें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'year', 'hi', '{"overview":"इस वर्ष पहचान, उद्देश्य, और आपकी ऊर्जा के उपयोग के तरीके के आसपास धैर्यपूर्वक वृद्धि का आमंत्रण है। मिथुन वायु ऊर्जा के माध्यम से चलता है। जिज्ञासा और संबंध जुड़वाँ की राह दिखाते हैं, जो विचार इकट्ठा करते हैं और कहानी के केवल एक पहलू से अधिक प्रकट करते हैं।","love":"प्यार गहरा होता है जब आप स्थिरता का अभ्यास करते हैं और संबंध को मानवीय गति से विकसित होने देते हैं। आपके संचार, बहुमुखी प्रतिभा, तेज़ सीखने की क्षमताएं आपको बिना प्रदर्शन किए जुड़ने में मदद कर सकती हैं।","career":"दीर्घकालिक काम अधिक मजबूत बनता है जब महत्वाकांक्षा को ऐसी संरचना के साथ जोड़ा जाए जिसे आप बनाए रख सकें। जिज्ञासु, अनुकूलनशील, अभिव्यक्तिपूर्ण, चतुर को उपकरण के रूप में उपयोग करें, न कि ऐसी उम्मीदें जिनको आपको एक साथ पूरा करना है।","finance":"पूर्ण भविष्यवाणियों के बजाय दोहराए जाने योग्य आदतों के माध्यम से वित्तीय आत्मविश्वास बनाएं। जब बेचैनी, बिखरी हुई दिशा, अत्यधिक सोच विचार किसी व्यावहारिक निर्णय को प्रभावित करना शुरू करे, तो इसे नोटिस करें।","wellbeing":"कल्याण को उस जीवन के आधार के रूप में मानें जिसे आप बना रहे हैं, इसे समाप्त करने के बाद मिलने वाले इनाम के रूप में नहीं। जिज्ञासा को दरवाजा खोलने दें, फिर यह समझने के लिए पर्याप्त समय तक रुके रहें कि आपने क्या पाया।","guidance":"पूरा साल इस कम्पास की ओर लौटते रहो: जिज्ञासा को दरवाजा खोलने दो, फिर जो कुछ भी मिले उसे समझने के लिए पर्याप्त समय तक वहीं रुको।"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('cancer', 'hi', '{"name":"कैंसर","dateRange":"21 जून – 22 जुलाई","rulingPlanet":"मून","summary":"संरक्षक और सहज ज्ञानयुक्त, केकड़ा स्मृति, भावना और घर का सम्मान करके अपनापन बनाता है।","originStory":"कैंसर को केकड़ा कर्किनोस से जोड़ा जाता है, जिसे हेराक्ल्स की हाइड्रा से लड़ाई के दौरान उसकी निष्ठा दिखाने के बाद तारों के बीच रखा गया था। इसका खोल और चंद्रमा का शासन सुरक्षा, भावनात्मक उतार-चढ़ाव, और अपने अंतरंग लोग के प्रति समर्पण को दर्शाता है।","traits":["सहज","देखभाल करने वाला","संरक्षक","कल्पनाशील"],"strengths":["सहानुभूति","निष्ठा","भावनात्मक अंतर्दृष्टि"],"challenges":["मूडिनेस","बचाव के पीछे पीछे हटना","व्यक्तिगत रूप से चीजों को लेना"],"compatibleSigns":["वृश्चिक","मीन","वृषभ"],"reflectionPrompt":"जैसे ही ईमानदार संबंध के लिए एक दरवाजा खुला रखें, अपने अंदर की दुनिया का ख्याल रखें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'day', 'hi', '{"overview":"आज एक स्पष्ट, जानबूझकर कदम लेने का दिन है। कर्क जल की ऊर्जा के माध्यम से चलता है। रक्षात्मक और सहज, केकड़ा स्मृति, भावना और घर का सम्मान करके अपनापन बनाता है।","love":"आज प्यार में, अनुमान के बजाय उपस्थिति चुनें। सहानुभूति, वफादारी, भावनात्मक समझ के आपके उपहार आपको बिना प्रदर्शन किए जुड़ने में मदद कर सकते हैं।","career":"काम पर, नए उत्साह का पीछा करने से पहले सबसे महत्वपूर्ण कार्य पूरा करें। सहजज्ञानशील, देखभाल करने वाला, सुरक्षा प्रदान करने वाला, और सृजनात्मक को उपकरण के रूप में उपयोग करें, न कि ऐसी अपेक्षाएँ जिन्हें आपको एक साथ पूरा करना है।","finance":"आज के पैसे के फैसलों को सरल और ठोस रखें। ध्यान दें कि कब मूडी होना, रक्षाओं के पीछे पीछे पीछे हटना, चीज़ों को व्यक्तिगत रूप से लेना एक व्यावहारिक निर्णय को प्रभावित करने लगता है।","wellbeing":"एक छोटा विराम आपकी ऊर्जा को पुनः सेट कर सकता है। ईमानदार सम्बन्ध के लिए एक दरवाज़ा खुला रखते हुए अपने अंदरूनी दुनिया की देखभाल करें।","guidance":"दिन खत्म होने से पहले, याद रखें: अपने आंतरिक संसार की देखभाल करें, जबकि ईमानदार संबंध के लिए एक दरवाज़ा खुला छोड़ें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'week', 'hi', '{"overview":"इस सप्ताह एक नाटकीय क्षण की बजाय स्थिर चुनावों के माध्यम से विकसित होता है। कर्क जल ऊर्जा के माध्यम से आगे बढ़ता है। सुरक्षात्मक और सहज ज्ञान युक्त, केकड़ा स्मृति, भावना और घर का सम्मान करके आत्मीयता पैदा करता है।","love":"संबंधों को ऐसे संवाद से लाभ मिलता है जो ईमानदारी और गर्मजोशी दोनों के लिए स्थान बनाता है। आपकी सहानुभूति, निष्ठा, भावनात्मक अंतर्दृष्टि की उपहार आपको प्रदर्शन किए बिना जुड़ने में मदद कर सकते हैं।","career":"आपकी सर्वोत्तम पेशेवर प्रगति किसी प्राथमिकता चुनने और उसके लिए समय सुरक्षित करने से आती है। सहजज्ञानपूर्ण, देखभाल करने वाले, सुरक्षात्मक, कल्पनाशील को उपकरण के रूप में इस्तेमाल करें, न कि ऐसी अपेक्षाएं जिन्हें आपको एक साथ पूरा करना हो।","finance":"बड़ी प्रतिबद्धता करने से पहले अपने खर्च के पीछे के पैटर्न की समीक्षा करें। ध्यान दें कि कब मूड बदलना, रक्षाओं के पीछे पीछे हटना, चीजों को व्यक्तिगत तौर पर लेना एक व्यावहारिक निर्णय को प्रभावित करना शुरू करता है।","wellbeing":"सप्ताह भर में वास्तविक रिकवरी के साथ गतिशीलता को संतुलित करें। ईमानदार संबंध के लिए एक दरवाजा खुले रहते हुए अपने आंतरिक संसार की देखभाल करें।","guidance":"इस प्रश्न को इस सप्ताह का मार्गदर्शन बनने दें: अपनी आंतरिक दुनिया की देखभाल करें जबकि ईमानदार संपर्क के लिए एक दरवाज़ा खुला छोड़ें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'year', 'hi', '{"overview":"इस वर्ष पहचान, उद्देश्य और अपनी ऊर्जा के उपयोग के तरीके के आसपास धैर्यपूर्ण विकास का आमंत्रण देता है। कर्क जल ऊर्जा के माध्यम से चलता है। सुरक्षात्मक और सहजज्ञान से युक्त, केकड़ा स्मृति, भावना और घर का सम्मान करके अपनापन पैदा करता है।","love":"जब आप लगातार अभ्यास करते हैं और रिश्तों को मानव गति से विकसित होने देते हैं, तो प्यार गहरा होता है। आपकी सहानुभूति, वफादारी, भावनात्मक अंतर्दृष्टि की प्रतिभाएं आपको बिना प्रदर्शन किए जुड़ने में मदद कर सकती हैं।","career":"दीर्घकालिक कार्य तब मजबूत होता है जब महत्वाकांक्षा को एक ऐसे ढांचे के साथ जोड़ा जाए जिसे आप बनाए रख सकते हैं। सहज, सहानुभूतिपूर्ण, रक्षात्मक, कल्पनाशील का उपयोग उपकरण के रूप में करें, ऐसी अपेक्षाओं के रूप में नहीं जिन्हें आपको एक बार में पूरा करना चाहिए।","finance":"पूर्ण भविष्यवाणियों के बजाय दोहराए जाने योग्य आदतों के माध्यम से वित्तीय आत्मविश्वास बनाएं। जब मूडी होना, रक्षा के पीछे retreat करना, चीजों को व्यक्तिगत रूप से लेना किसी व्यावहारिक निर्णय को प्रभावित करना शुरू करे, तो इसे नोटिस करें।","wellbeing":"कल्याण को उस जीवन की नींव के रूप में मानें जिसे आप बना रहे हैं, इसे पूरा करने के बाद मिलने वाले इनाम के रूप में नहीं। ईमानदार जुड़ाव के लिए एक दरवाजा खुले रहने दें, जबकि अपने आंतरिक संसार की देखभाल करें।","guidance":"पूरे साल इस कंपास की ओर लौटें: अपने अंदरूनी संसार का ध्यान रखें जबकि ईमानदार संबंध के लिए एक दरवाजा खुला छोड़ें।"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('leo', 'hi', '{"name":"सिंह","dateRange":"23 जुलाई – 22 अगस्त","rulingPlanet":"सूर्य","summary":"गरमी, रचनात्मकता, और उदार आत्म-अभिव्यक्ति सिंह को प्राकृतिक रूप से प्रकाश का स्रोत बनाती है।","originStory":"सिंह का संबंध नेमियन शेर से है, जो लगभग अजेय प्राणी था जिसे हेराक्लेस के पहले श्रम में हराया गया। स्वर्ग में उठा दिया गया, यह साहस, सार्वभौमिक उपस्थिति और सूर्य की रचनात्मक शक्ति का प्रतीक बन गया।","traits":["गर्म","रचनात्मक","उदार","आत्मविश्वासी"],"strengths":["नेतृत्व","निष्ठा","हार्दिक अभिव्यक्ति"],"challenges":["अभिमान","मान्यता की आवश्यकता","असफलताओं को नाटकात्मक बनाना"],"compatibleSigns":["मेष","धनु","तुला"],"reflectionPrompt":"अपनी रोशनी उदारतापूर्वक साझा करें और दूसरों को आपके पास चमकने दें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'day', 'hi', '{"overview":"आज एक स्पष्ट, जानबूझकर किया गया कदम अनुकूल है। सिंह अग्नि ऊर्जा के माध्यम से आगे बढ़ता है। गर्मजोशी, रचनात्मकता, और उदार आत्म-अभिव्यक्ति शेर को प्राकृतिक प्रकाश का स्रोत बनाती हैं।","love":"आज प्यार में, अनुमान के बजाय उपस्थिति चुनें। नेतृत्व, वफादारी, दिल से अभिव्यक्ति के आपके उपहार आपको बिना प्रदर्शन किए जुड़ने में मदद कर सकते हैं।","career":"काम पर, नई गति का पीछा करने से पहले सबसे महत्वपूर्ण कार्य पूरा करें। गर्मजोशी, रचनात्मक, उदार, आत्मविश्वासी को उपकरण के रूप में इस्तेमाल करें, ऐसी अपेक्षाएं नहीं जिन्हें आपको एक साथ पूरा करना है।","finance":"आज के पैसे के फैसलों को सरल और ठोस रखें। ध्यान दें कि कब गर्व, मान्यता की आवश्यकता, असफलताओं को नाटकीय रूप में पेश करना एक व्यावहारिक निर्णय को प्रभावित करने लगता है।","wellbeing":"एक छोटा सा विराम आपके ऊर्जा को पुनःस्थापित कर सकता है। अपनी रोशनी उदारतापूर्वक साझा करें और दूसरों को आपके साथ चमकने दें।","guidance":"दिन खत्म होने से पहले याद रखें: अपनी रोशनी उदारता से साझा करें और दूसरों को आपके साथ चमकने दें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'week', 'hi', '{"overview":"यह सप्ताह एक नाटकीय क्षण की बजाय लगातार विकल्पों के माध्यम से विकसित होता है। सिंह अग्नि ऊर्जा के माध्यम से चलता है। गर्मजोशी, रचनात्मकता, और उदार आत्म-अभिव्यक्ति सिंह को प्राकृतिक प्रकाश का स्रोत बनाते हैं।","love":"रिश्ते उस बातचीत से लाभान्वित होते हैं जो ईमानदारी और गर्मजोशी दोनों के लिए जगह बनाती है। नेतृत्व, निष्ठा, हृदयपूर्वक अभिव्यक्ति के आपके गुण बिना प्रदर्शन किए जुड़ने में मदद कर सकते हैं।","career":"आपकी सबसे अच्छी पेशेवर प्रगति किसी प्राथमिकता को चुनने और उसके लिए समय की रक्षा करने से आती है। गर्मजोशी, रचनात्मक, उदार, आत्मविश्वासी को उपकरण के रूप में उपयोग करें, न कि ऐसी अपेक्षाएँ जिन्हें आपको एक बार में पूरा करना चाहिए।","finance":"बड़ी प्रतिबद्धता करने से पहले अपने खर्च के पैटर्न की समीक्षा करें। ध्यान दें कि कब गर्व, पहचान की आवश्यकता, या असफलताओं को बढ़ा-चढ़ा कर दिखाना एक व्यावहारिक निर्णय को प्रभावित करना शुरू कर देता है।","wellbeing":"सप्ताह भर में वास्तविक पुनर्प्राप्ति के साथ आंदोलन का संतुलन बनाए रखें। अपनी रोशनी उदारता से साझा करें और दूसरों को आपके साथ चमकने दें।","guidance":"इस प्रश्न को सप्ताह का मार्गदर्शन करने दें: अपनी रोशनी उदारतापूर्वक साझा करें और दूसरों को आपके बगल में चमकने दें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'year', 'hi', '{"overview":"यह वर्ष पहचान, उद्देश्य, और आप अपनी ऊर्जा का उपयोग कैसे करते हैं, इसके चारों ओर धैर्यपूर्ण विकास का आमंत्रण देता है। सिंह अग्नि ऊर्जा के माध्यम से चलता है। गर्मजोशी, रचनात्मकता, और उदार आत्म-अभिव्यक्ति सिंह को प्रकाश का स्वाभाविक स्रोत बनाते हैं।","love":"जब आप निरंतरता का अभ्यास करते हैं और संबंध को मानवीय गति से विकसित होने देते हैं तो प्रेम गहरा होता है। आपका नेतृत्व, निष्ठा, और हृदयस्पर्शी अभिव्यक्ति का उपहार बिना प्रदर्शन के जुड़ने में आपकी मदद कर सकता है।","career":"दीर्घकालिक कार्य तब मजबूत होता है जब महत्वाकांक्षा को एक ऐसे ढांचे के साथ जोड़ा जाए जिसे आप बनाए रख सकते हैं। गर्म, रचनात्मक, उदार, आत्मविश्वासी का उपयोग उपकरण के रूप में करें, ऐसी अपेक्षाओं के रूप में नहीं जिन्हें आपको एक बार में पूरा करना चाहिए।","finance":"पूर्ण भविष्यवाणियों के बजाय दोहराए जाने योग्य आदतों के माध्यम से वित्तीय आत्मविश्वास बनाएं। जब घमंड, पहचान की आवश्यकता, असफलताओं को बढ़ा-चढ़ा कर पेश करना किसी व्यावहारिक निर्णय को प्रभावित करना शुरू करे, तो इसे नोटिस करें।","wellbeing":"कल्याण को उस जीवन की नींव के रूप में मानें जिसे आप बना रहे हैं, इसे पूरा करने के बाद मिलने वाले इनाम के रूप में नहीं। अपनी रोशनी उदारतापूर्वक साझा करें और दूसरों को आपके साथ चमकने दें।","guidance":"पूरा साल इस कम्पास की ओर लौटते रहो: अपनी रोशनी उदारतापूर्वक साझा करो और दूसरों को अपने पास चमकने दो।"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('virgo', 'hi', '{"name":"कन्या","dateRange":"23 अगस्त – 22 सितम्बर","rulingPlanet":"बुध","summary":"विवेक और सेवा कन्या की मार्गदर्शिका हैं, जो सतर्क निरीक्षण को व्यावहारिक सुधार में बदल देती हैं।","originStory":"कन्या को अक्सर अस्त्राया, न्याय की कन्या, के साथ जोड़ा जाता है, जो अन्य देवताओं के पीछे हटने के बाद मानवता के साथ रही। वह गेहूं जो वह ले जाती है, इस राशि को फसल, कौशल, उद्देश्य की शुद्धता, और जीवन को बनाए रखने वाली चीजों की देखभाल से जोड़ता है।","traits":["सवेध्य","व्यावहारिक","विचारशील","सटीक"],"strengths":["विश्लेषण","कला कौशल","सहायक सेवा"],"challenges":["परिपूर्णतावाद","आत्म-आलोचना","विवरणों की चिंता करना"],"compatibleSigns":["वृषभ","मकर","कैंसर"],"reflectionPrompt":"जो आप कर सकते हैं उसे सुधारें, और अच्छे काम को पूर्ण होने से पहले ही सही होने की प्रतीक्षा न करें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'day', 'hi', '{"overview":"आज एक स्पष्ट, जानबूझकर कदम को बढ़ावा देता है। कन्या पृथ्वी की ऊर्जा से गुजरती है। विवेक और सेवा कन्या का मार्गदर्शन करते हैं, सावधानीपूर्वक अवलोकन को व्यावहारिक सुधार में बदलते हैं।","love":"आज प्यार में, अनुमान के बजाय उपस्थिति को चुनें। विश्लेषण, शिल्प कौशल, सहायक सेवा की आपकी क्षमताएँ बिना प्रदर्शन किए जुड़ने में आपकी मदद कर सकती हैं।","career":"काम पर, नए उत्साह का पीछा करने से पहले सबसे महत्वपूर्ण कार्य पूरा करें। पर्यवेक्षक, व्यावहारिक, विचारशील, और सटीक को उपकरण के रूप में उपयोग करें, न कि ऐसी अपेक्षाएँ जिन्हें आपको एक साथ पूरा करना है।","finance":"आज के पैसे के फैसलों को सरल और ठोस रखें। ध्यान दें कि कब परिपूर्णता की चाह, आत्म-आलोचना, विवरणों की चिंता करना एक व्यावहारिक निर्णय को प्रभावित करने लगता है।","wellbeing":"एक छोटा विराम आपकी ऊर्जा को पुनः सेट कर सकता है। जो कर सकते हैं उसे सुधारें, और अच्छे काम को पूरा होने दें इससे पहले कि वह परफेक्ट हो जाए।","guidance":"दिन खत्म होने से पहले याद रखें: जो आप सुधार सकते हैं उसे सुधारें, और अच्छे काम को पूरा होने दें, भले ही वह परिपूर्ण न हो।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'week', 'hi', '{"overview":"इस सप्ताह धीरे-धीरे किए गए विकल्पों के माध्यम से विकसित होता है, न कि किसी एक नाटकीय क्षण से। कन्या पृथ्वी की ऊर्जा के माध्यम से चलती है। विवेक और सेवा कन्या का मार्गदर्शन करते हैं, सावधान अवलोकन को व्यावहारिक सुधार में बदलते हैं।","love":"संबंध एक ऐसी बातचीत से लाभान्वित होते हैं जो दोनों ईमानदारी और गर्मजोशी के लिए जगह बनाती है। आपके विश्लेषण, शिल्पकौशल, सहायक सेवा के उपहार बिना प्रदर्शन किए जुड़ने में मदद कर सकते हैं।","career":"आपकी सर्वोत्तम पेशेवर प्रगति किसी प्राथमिकता चुनने और उसके लिए समय सुरक्षित करने से आती है। सतर्क, व्यावहारिक, विचारशील, सटीक को उपकरण के रूप में इस्तेमाल करें, न कि ऐसी अपेक्षाएं जिन्हें आपको एक साथ पूरा करना हो।","finance":"बड़ी प्रतिबद्धता करने से पहले अपने खर्च के पीछे के पैटर्न की समीक्षा करें। ध्यान दें कि कब परफेक्शनिज़्म, आत्म-आलोचना, और विवरणों की चिंता व्यावहारिक निर्णय को प्रभावित करने लगती है।","wellbeing":"सप्ताह भर में वास्तविक पुनर्प्राप्ति के साथ आंदोलन का संतुलन बनाए रखें। जिसे आप सुधार सकते हैं उसे सुधारें, और यह पूर्ण होने से पहले ही अच्छे कार्य को पूरा होने दें।","guidance":"इस प्रश्न को इस सप्ताह का मार्गदर्शन बनने दें: जो सुधार सकते हैं उसे सुधारें, और अच्छे कार्य को पूर्ण होने दें इससे पहले कि यह परिपूर्ण हो।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'year', 'hi', '{"overview":"इस वर्ष पहचान, उद्देश्य और आपकी ऊर्जा के उपयोग के तरीके के आसपास धैर्यपूर्ण वृद्धि का आमंत्रण देता है। कन्या पृथ्वी की ऊर्जा के माध्यम से चलता है। विवेक और सेवा कन्या का मार्गदर्शन करती है, सावधानीपूर्वक निरीक्षण को व्यावहारिक सुधार में बदल देती है।","love":"प्यार गहरा होता है जब आप स्थिरता का अभ्यास करते हैं और संबंध को मानवीय गति से विकसित होने देते हैं। आपके विश्लेषण, कौशल, सहायक सेवा के उपहार आपको बिना प्रदर्शन किए जुड़ने में मदद कर सकते हैं।","career":"दीर्घकालिक कार्य तब मजबूत होता है जब महत्वाकांक्षा को एक ऐसे ढांचे के साथ जोड़ा जाए जिसे आप बनाए रख सकते हैं। सतर्क, व्यावहारिक, विचारशील, सटीक का उपयोग उपकरण के रूप में करें, ऐसी अपेक्षाओं के रूप में नहीं जिन्हें आपको एक बार में पूरा करना चाहिए।","finance":"पूर्ण भविष्यवाणियों के बजाय दोहराए जाने योग्य आदतों के माध्यम से वित्तीय आत्मविश्वास बनाएं। जब परिपूर्णता की चाह, आत्म-आलोचना, विवरणों की चिंता किसी व्यावहारिक निर्णय को प्रभावित करना शुरू करे, तो इसे नोटिस करें।","wellbeing":"कल्याण को उस जीवन के आधार के रूप में मानें जिसे आप बना रहे हैं, इसे समाप्त करने के बाद मिलने वाले इनाम के रूप में नहीं। जो आप कर सकते हैं उसे सुधारें, और अच्छे काम को पूर्ण होने दें इससे पहले कि वह पूर्णतया परिपूर्ण हो।","guidance":"पूरे साल इस कंपास की ओर लौटें: जिसे सुधार सकते हैं उसे सुधारें, और अच्छे काम को सही होने से पहले पूरा होने की अनुमति दें।"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('libra', 'hi', '{"name":"तुला","dateRange":"23 सितम्बर – 22 अक्तूबर","rulingPlanet":"वीनस","summary":"संतुलन, सुंदरता, और पारस्परिकता तराजू को उन विकल्पों की ओर मार्गदर्शन करती है जो हर आवाज़ का सम्मान करते हैं।","originStory":"तुला का तराजू न्याय की देवी अस्त्रिया द्वारा उठाए जाते हैं, और यह राशि चक्र का केवल एक निर्जीव प्रतीक है। यह मापी गई निर्णय क्षमता, सामाजिक सामंजस्य और संतुलन को पुनर्स्थापित करने के लगातार प्रयास का प्रतीक है, बजाय इसके कि यह पहले से ही मौजूद है।","traits":["कूटनीतिक","निष्पक्ष","मोहनसाध्य","सहयोगात्मक"],"strengths":["मध्यस्थता","दृष्टिकोण","संगीत और मेल बनाना"],"challenges":["अनिर्णय","लोगों को खुश करना","ज़रूरी संघर्ष से बचना"],"compatibleSigns":["मिथुन","कुंभ","सिंह"],"reflectionPrompt":"अपनी स्वयं की आवश्यकताओं के सत्य को छोड़ दिए बिना न्याय की तलाश करें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'day', 'hi', '{"overview":"आज एक स्पष्ट, योजना बना हुआ कदम लेना अनुकूल है। तुला वायु ऊर्जा के माध्यम से चलता है। संतुलन, सुंदरता, और आपसी सहयोग तराजू को ऐसे विकल्पों की ओर ले जाते हैं जो हर आवाज़ का सम्मान करते हैं।","love":"आज प्रेम में, अटकलों के बजाय उपस्थिति को चुनें। मध्यस्थता, दृष्टिकोण, और सामंजस्य बनाने की आपके उपहार आपको प्रदर्शन किए बिना जुड़ने में मदद कर सकते हैं।","career":"काम पर, नए उत्साह का पीछा करने से पहले सबसे महत्वपूर्ण कार्य पूरा करें। कूटनीतिक, निष्पक्ष, आकर्षक, सहयोगी को उपकरण के रूप में उपयोग करें, ऐसी अपेक्षाएँ नहीं जिन्हें आपको एक बार में पूरा करना है।","finance":"आज के पैसे के फैसलों को सरल और ठोस रखें। ध्यान दें कि कब अनिर्णय, लोगों को खुश करना, जरूरी संघर्ष से बचना एक व्यावहारिक निर्णय को प्रभावित करना शुरू करता है।","wellbeing":"एक छोटा सा विराम आपके ऊर्जा को पुनःस्थापित कर सकता है। अपनी आवश्यकताओं की सच्चाई को छोड़ दिए बिना न्याय की तलाश करें।","guidance":"दिन खत्म होने से पहले याद रखें: निष्पक्षता की तलाश करें, लेकिन अपनी आवश्यकताओं की सच्चाई को त्यागें नहीं।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'week', 'hi', '{"overview":"इस सप्ताह धीरे-धीरे किए गए विकल्पों के माध्यम से विकसित होता है, न कि किसी एक नाटकीय क्षण से। तुला वायु ऊर्जा के माध्यम से आगे बढ़ती है। संतुलन, सुंदरता, और परस्परता तराजू को ऐसे विकल्पों की ओर मार्गदर्शन करते हैं जो हर आवाज़ का सम्मान करते हैं।","love":"संबंध उस बातचीत से लाभान्वित होते हैं जो ईमानदारी और गर्मजोशी दोनों के लिए स्थान बनाती है। मध्यस्थता, दृष्टिकोण, और सामंजस्य बनाने के आपके उपहार आपको प्रदर्शन किए बिना जुड़ने में मदद कर सकते हैं।","career":"आपकी सबसे अच्छी पेशेवर प्रगति प्राथमिकता चुनने और इसके लिए समय की रक्षा करने से आती है। कूटनीतिक, निष्पक्ष दिमाग, आकर्षक, सहयोगी को उपकरण के रूप में उपयोग करें, न कि अपेक्षाओं को आपको एक ही बार में पूरा करना चाहिए।","finance":"बड़ी प्रतिबद्धता करने से पहले अपने खर्च के पीछे के पैटर्न की समीक्षा करें। ध्यान दें कि कब अनिर्णय, लोगों को खुश करने की प्रवृत्ति, ज़रूरी संघर्ष से बचना व्यावहारिक निर्णय को प्रभावित करना शुरू करता है।","wellbeing":"सप्ताह भर में वास्तविक पुनर्प्राप्ति के साथ आंदोलन का संतुलन बनाए रखें। अपने स्वयं के जरूरतों की सच्चाई को त্যागे बिना न्याय की तलाश करें।","guidance":"इस प्रश्न को सप्ताह का मार्गदर्शन करने दें: निष्पक्षता की तलाश करें बिना अपनी आवश्यकताओं की सत्यता को छोड़ें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'year', 'hi', '{"overview":"यह वर्ष पहचान, उद्देश्य, और आप अपनी ऊर्जा का उपयोग कैसे करते हैं, इसके चारों ओर धैर्यपूर्ण विकास का आमंत्रण देता है। तुला वायु ऊर्जा के माध्यम से आगे बढ़ता है। संतुलन, सुंदरता, और पारस्परिकता तराजू को उन विकल्पों की ओर मार्गदर्शन करती हैं जो हर आवाज का सम्मान करें।","love":"जब आप निरंतरता का अभ्यास करते हैं और संबंध को मानवीय गति से विकसित होने देते हैं तो प्रेम गहरा होता है। आपकी मध्यस्थता, दृष्टिकोण, और सामंजस्य बनाने की विशेषताएँ बिना प्रदर्शन के जुड़ने में आपकी मदद कर सकती हैं।","career":"दीर्घकालिक काम तब मजबूत होता है जब महत्वाकांक्षा को ऐसी संरचना के साथ जोड़ा जाए जिसे आप बनाए रख सकें। राजनयिक, निष्पक्ष-मन, आकर्षक, सहयोगी का उपयोग उपकरण के रूप में करें, उन अपेक्षाओं के रूप में नहीं जिन्हें आपको एक साथ पूरा करना चाहिए।","finance":"परफेक्ट भविष्यवाणियों के बजाय दोहराए जाने वाले अभ्यासों के माध्यम से वित्तीय आत्मविश्वास बनाएं। ध्यान दें कि जब अनिश्चितता, सबको खुश करने की कोशिश, आवश्यक संघर्ष से बचना किसी व्यावहारिक निर्णय को प्रभावित करने लगे।","wellbeing":"कल्याण को उस जीवन की नींव के रूप में मानें जिसे आप बना रहे हैं, इसे पूरा करने के बाद मिलने वाले इनाम के रूप में नहीं। अपनी आवश्यकताओं की सच्चाई को छोड़ दिए बिना न्याय की खोज करें।","guidance":"पूरा साल इस कम्पास की ओर लौटते रहो: अपने अपने जरूरतों की सच्चाई को छोड़े बिना न्याय की तलाश करो।"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('scorpio', 'hi', '{"name":"वृश्चिक","dateRange":"23 अक्टूबर – 21 नव","rulingPlanet":"प्लूटो","summary":"गहनता और परिवर्तन का प्रतीक है वृश्चिक, जिसकी अंतर्दृष्टि सतह के नीचे सच्चाई पाती है।","originStory":"वृश्चिक उस बिच्छू को याद करता है जिसे शिकारी ओरियन का सामना करने के लिए भेजा गया था जब उसका गर्व प्राकृतिक क्रम को परेशान कर रहा था। आकाश में उनकी विरोधी जगहें सीमाओं, परिणाम, रहस्य, और एक अंत के बाद मिलने वाली नवीनीकरण शक्ति को दर्शाती हैं।","traits":["तीव्र","संज्ञाशील","वफादार","संसाधन संपन्न"],"strengths":["भावनात्मक साहस","ध्यान केंद्रित करना","परिवर्तन"],"challenges":["गोपनीयता","संदेह","नराजगी रखना"],"compatibleSigns":["कैंसर","मीन","कन्या"],"reflectionPrompt":"सत्य को बदलने के लिए अपनी गहराई का उपयोग करें, इसे छुपाने के लिए नहीं।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'day', 'hi', '{"overview":"आज एक स्पष्ट, जानबूझकर कदम को बढ़ावा देता है। वृश्चिक जल ऊर्जा से गुजरता है। गहराई और परिवर्तन वृश्चिक को परिभाषित करते हैं, जिसकी अंतर्दृष्टि सतह के नीचे सच्चाई पाती है।","love":"आज प्यार में, अनुमान के बजाय उपस्थिति को चुनें। भावनात्मक साहस, ध्यान, परिवर्तन की आपकी क्षमताएँ बिना प्रदर्शन किए जुड़ने में आपकी मदद कर सकती हैं।","career":"काम पर, नए उत्साह का पीछा करने से पहले सबसे महत्वपूर्ण कार्य पूरा करें। तीव्र, प्रबुद्ध, वफादार, और संसाधन संपन्न को उपकरण के रूप में उपयोग करें, न कि ऐसी अपेक्षाएँ जिन्हें आपको एक साथ पूरा करना है।","finance":"आज के धन के विकल्पों को सरल और ठोस रखें। ध्यान दें कि जब गोपनीयता, संदेह, बुरा मानना किसी व्यावहारिक निर्णय को प्रभावित करना शुरू कर दे।","wellbeing":"एक छोटी सी विराम आपकी ऊर्जा को रीसेट कर सकती है। इसका प्रयोग सच को छुपाने के लिए नहीं, बल्कि उसे बदलने के लिए करें।","guidance":"दिन खत्म होने से पहले, याद रखें: सच्चाई को छुपाने के लिए नहीं, उसे बदलने के लिए अपनी गहराई का उपयोग करें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'week', 'hi', '{"overview":"इस सप्ताह धीरे-धीरे किए गए विकल्पों के माध्यम से विकसित होता है, न कि किसी एक नाटकीय क्षण से। वृश्चिक जल ऊर्जा के माध्यम से चलता है। गहराई और परिवर्तन वृश्चिक को परिभाषित करते हैं, जिसकी अंतर्दृष्टि सतह के नीचे सच्चाई पाती है।","love":"संबंधों को ऐसे संवाद से लाभ मिलता है जो ईमानदारी और गर्मजोशी दोनों के लिए स्थान बनाता है। आपकी भावनात्मक साहस, फोकस, परिवर्तन जैसी क्षमताएँ आपको बिना प्रदर्शन किए जुड़ने में मदद कर सकती हैं।","career":"आपकी सर्वोत्तम पेशेवर प्रगति किसी प्राथमिकता चुनने और उसके लिए समय सुरक्षित करने से आती है। तीव्र, अनुभवी, वफादार, संसाधनपूर्ण को उपकरण के रूप में इस्तेमाल करें, न कि ऐसी अपेक्षाएं जिन्हें आपको एक साथ पूरा करना हो।","finance":"बड़ी प्रतिबद्धता करने से पहले अपने खर्च करने की आदत का पैटर्न देखें। ध्यान दें कि कब गुप्तता, संशय, बदला रखने की आदत एक व्यावहारिक निर्णय को प्रभावित करना शुरू करती है।","wellbeing":"सप्ताह भर में असली रिकवरी के साथ गतिशीलता को संतुलित करें। सच्चाई को छुपाने के लिए नहीं, बल्कि उसे बदलने के लिए अपनी गहराई का उपयोग करें।","guidance":"इस प्रश्न को सप्ताह का मार्गदर्शन करने दें: सच्चाई को छिपाने के लिए नहीं बल्कि इसे बदलने के लिए अपनी गहराई का उपयोग करें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'year', 'hi', '{"overview":"इस वर्ष पहचान, उद्देश्य और आपकी ऊर्जा के उपयोग के तरीके के आसपास धैर्यपूर्ण वृद्धि का आमंत्रण देता है। वृश्चिक पानी की ऊर्जा के माध्यम से चलता है। गहराई और परिवर्तन वृश्चिक को परिभाषित करते हैं, जिसकी अंतर्दृष्टि सतह के नीचे सत्य खोजती है।","love":"प्यार गहरा होता है जब आप स्थिरता का अभ्यास करते हैं और संबंध को मानवीय गति से विकसित होने देते हैं। आपके भावनात्मक साहस, ध्यान, परिवर्तन के उपहार आपको बिना प्रदर्शन किए जुड़ने में मदद कर सकते हैं।","career":"दीर्घकालिक काम अधिक मजबूत बनता है जब महत्वाकांक्षा को ऐसी संरचना के साथ जोड़ा जाए जिसे आप बनाए रख सकें। तीव्र, सूक्ष्मदर्शी, वफादार, संसाधनपूर्ण को उपकरण के रूप में इस्तेमाल करें, उन अपेक्षाओं के रूप में नहीं जिन्हें आपको एक बार में पूरा करना चाहिए।","finance":"परफेक्ट भविष्यवाणियों के बजाय दोहराए जाने वाले आदतों के माध्यम से वित्तीय आत्मविश्वास बनाएं। जब गोपनीयता, संदेह, या मनमुटाव व्यावहारिक निर्णय को प्रभावित करना शुरू करें, तो इसे नोटिस करें।","wellbeing":"कल्याण को उस जीवन के लिए आधार मानें जिसे आप बना रहे हैं, इसे पूरा करने के बाद मिलने वाला इनाम मत समझें। सच्चाई को छिपाने के बजाय उसे बदलने के लिए अपनी गहराई का उपयोग करें।","guidance":"पूरा साल इस कम्पास की ओर लौटते रहो: अपनी गहराई का उपयोग सत्य को बदलने के लिए करो, इसे छिपाने के लिए नहीं।"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('sagittarius', 'hi', '{"name":"धनु","dateRange":"22 नव – 21 दिस","rulingPlanet":"बृहस्पति","summary":"धनु का राशि चिन्ह सत्य, यात्रा, सीखने और उद्देश्यपूर्ण आशावाद के माध्यम से व्यापक क्षितिज की खोज करता है।","originStory":"धनु को अक्सर चिरोन से जोड़ा जाता है, जो बुद्धिमान सेंटॉर और शिक्षक हैं, जिनका तीर परिचित से परे इंगित करता है। यह नक्षत्र प्रवृत्ति और उच्चतर समझ के संघ का प्रतीक है, जो हमेशा अधिक अर्थपूर्ण क्षितिज की ओर लक्षित करता है।","traits":["साहसिक","आशावादी","ईमानदार","दार्शनिक"],"strengths":["दृष्टि","उत्साह","मरीज खुले विचार वाले"],"challenges":["साफगोई","अति वादा करना","रूटीन से बचना"],"compatibleSigns":["मेष","सिंह","कुंभ"],"reflectionPrompt":"दूर तक लक्ष्य निर्धारित करें, लेकिन ऐसा मार्ग चुनें जिसे आपके दैनिक कार्य सहारा दे सकें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'day', 'hi', '{"overview":"आज एक स्पष्ट, उद्देश्यपूर्ण कदम के पक्ष में है। धनुजी आग की ऊर्जा से गुजरते हैं। धनु का प्रतीक धनुर्धारी सच्चाई, यात्रा, सीखने और उद्देश्यपूर्ण आशावाद के माध्यम से व्यापक क्षितिज खोजता है।","love":"आज प्यार में, अनुमान की बजाय उपस्थिति का चयन करें। आपके दृष्टि, उत्साह और खुले दिमाग के उपहार आपको प्रदर्शन किए बिना जुड़ने में मदद कर सकते हैं।","career":"काम पर, नए प्रोत्साहन का पीछा करने से पहले सबसे महत्वपूर्ण कार्य पूरा करें। साहसी, आशावादी, ईमानदार, दार्शनिक को उपकरण के रूप में उपयोग करें, वे अपेक्षाएँ नहीं हैं जिन्हें आपको एक बार में पूरा करना है।","finance":"आज के पैसे के चुनाव को सरल और आधारभूत रखें। जब सीधी बात, अधिक वादे करना, रूटीन से बचना किसी व्यावहारिक निर्णय को प्रभावित करने लगे तो इसका ध्यान रखें।","wellbeing":"एक छोटी सी विराम आपकी ऊर्जा को रीसेट कर सकती है। दूर तक लक्ष्य रखें, लेकिन एक ऐसा मार्ग चुनें जिसका समर्थन आपके दैनिक कार्य कर सकें।","guidance":"दिन खत्म होने से पहले, याद रखें: दूर का लक्ष्य रखें, लेकिन ऐसा दिशा चुनें, जिसे आपके दैनिक कार्य समर्थन दे सकें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'week', 'hi', '{"overview":"इस सप्ताह धीरे-धीरे किए गए विकल्पों के माध्यम से विकसित होता है, न कि किसी एक नाटकीय क्षण से। धनु आग ऊर्जा के माध्यम से आगे बढ़ता है। धनुच्चर सच्चाई, यात्रा, सीखने, और उद्देश्यपूर्ण आशावाद के माध्यम से व्यापक क्षितिज की खोज करता है।","love":"संबंध उस बातचीत से लाभान्वित होते हैं जो ईमानदारी और गर्मजोशी दोनों के लिए स्थान बनाती है। आपकी दृष्टि, उत्साह, और खुले मन की सोच आपको प्रदर्शन किए बिना जुड़ने में मदद कर सकती है।","career":"आपकी सर्वश्रेष्ठ पेशेवर प्रगति प्राथमिकता चुनने और उसके लिए समय सुरक्षित करने से आती है। साहसी, आशावादी, ईमानदार, दार्शनिक को औजार के रूप में उपयोग करें, न कि ऐसी अपेक्षाओं के रूप में जिन्हें आपको एक साथ पूरा करना है।","finance":"बड़ी प्रतिबद्धता लेने से पहले अपने खर्च के पीछे के पैटर्न की समीक्षा करें। देखें कि कब सीधापन, अधिक वादे करना, या रूटीन से बचना व्यावहारिक निर्णय को प्रभावित करने लगते हैं।","wellbeing":"सप्ताह भर में वास्तविक पुनर्प्राप्ति के साथ गति को संतुलित करें। दूर की सोचें, लेकिन ऐसा मार्ग चुनें जिसे आपके दैनिक कार्य समर्थित कर सकें।","guidance":"इस प्रश्न को इस सप्ताह का मार्गदर्शन बनने दें: दूर का लक्ष्य रखें, लेकिन ऐसा मार्ग चुनें जिसे आपके दैनिक क्रियाकलाप समर्थन कर सकें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'year', 'hi', '{"overview":"इस वर्ष पहचान, उद्देश्य और आपके ऊर्जा उपयोग के तरीके के आसपास धैर्यपूर्ण विकास का आमंत्रण देता है। धनु आग की ऊर्जा से गुजरता है। धनु अपने धनुषधारी के रूप में सच्चाई, यात्रा, अध्ययन और उद्देश्यपूर्ण आशावाद के माध्यम से व्यापक दृष्टिकोण खोजता है।","love":"जब आप निरंतरता का अभ्यास करते हैं और कनेक्शन को मानव गति से विकसित होने देते हैं, तो प्रेम गहराता है। आपकी दृष्टि, उत्साह, खुले दिमाग के उपहार आपको प्रदर्शन किए बिना जुड़ने में मदद कर सकते हैं।","career":"दीर्घकालिक कार्य अधिक मजबूत हो जाता है जब महत्वाकांक्षा को ऐसी संरचना के साथ जोड़ा जाए जिसे आप बनाए रख सकें। साहसी, आशावादी, ईमानदार, दार्शनिक को उपकरण के रूप में इस्तेमाल करें, ऐसी अपेक्षाएं नहीं जिन्हें आपको एक साथ पूरा करना हो।","finance":"सटीक भविष्यवाणियों के बजाय दोहराए जाने वाले आदतों के माध्यम से वित्तीय आत्मविश्वास बनाएं। ध्यान दें जब साफगोई, अधिक वादा करना, या दिनचर्या से बचना व्यावहारिक निर्णय को प्रभावित करने लगे।","wellbeing":"कल्याण को उस जीवन के लिए आधार मानें जिसे आप बना रहे हैं, इसे पूरा करने के बाद मिलने वाला इनाम नहीं। बड़े लक्ष्य रखें, लेकिन ऐसा मार्ग चुनें जिसे आपके दैनिक कार्य समर्थन कर सकें।","guidance":"पूरे साल इस कंपास की ओर लौटें: दूर का लक्ष्य रखें, लेकिन उस दिशा का चयन करें जिसे आपके दैनिक कार्य समर्थन दे सकें।"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('capricorn', 'hi', '{"name":"मकर","dateRange":"22 दिसंबर – 19 जनवरी","rulingPlanet":"शनि","summary":"अनुशासन और दीर्घकालिक दृष्टि समुद्री बकरी को चढ़ाई में मदद करती हैं जबकि नीचे की गहराइयों के बारे में बुद्धिमान बने रहते हैं।","originStory":"मकर का समुद्री-बकरी पान से जुड़ा है, जो टायफ़न से बचते समय आंशिक रूप से मछली में बदल गया था। इसका पहाड़ी और समुद्री स्वभाव महत्वाकांक्षा को भावनात्मक अस्तित्व के साथ जोड़ता है, समय और जिम्मेदारी के माध्यम से अर्जित प्रभुत्व का सम्मान करता है।","traits":["महत्वाकांक्षी","अनुशासित","धैर्यशील","जिम्मेदार"],"strengths":["धैर्य","रणनीति","भरोसेमंदिता"],"challenges":["कठोरता","निराशावाद","उपलब्धि के माध्यम से मूल्य मापना"],"compatibleSigns":["वृषभ","कन्या","वृश्चिक"],"reflectionPrompt":"दीर्घकालिक के लिए निर्माण करें जबकि यह याद रखें कि विश्राम संरचना का हिस्सा है।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'day', 'hi', '{"overview":"आज एक स्पष्ट, जानबूझकर कदम लेने का दिन है। मकर पृथ्वी की ऊर्जा के माध्यम से चलता है। अनुशासन और दीर्घकालीन दृष्टि समुद्री बकरी को चढ़ने में मदद करती है जबकि नीचे की गहराइयों के बारे में समझदार बने रहने में।","love":"आज प्यार में, अनुमान के बजाय उपस्थिति चुनें। सहनशीलता, रणनीति, भरोसेमंदी के आपके उपहार आपको बिना प्रदर्शन किए जुड़ने में मदद कर सकते हैं।","career":"काम पर, नए प्रोत्साहन का पीछा करने से पहले सबसे महत्वपूर्ण कार्य पूरा करें। महत्त्वाकांक्षी, अनुशासित, धैर्यवान, जिम्मेदार को उपकरण के रूप में उपयोग करें, वे अपेक्षाएँ नहीं हैं जिन्हें आपको एक बार में पूरा करना है।","finance":"आज के पैसे के फैसलों को सरल और ठोस रखें। ध्यान दें कि कब जड़ता, निराशावाद, उपलब्धियों के माध्यम से मूल्य मापना एक व्यावहारिक निर्णय को प्रभावित करने लगता है।","wellbeing":"एक छोटा सा विराम आपकी ऊर्जा को फिर से ताज़ा कर सकता है। लंबी अवधि के लिए निर्माण करें, जबकि यह याद रखें कि आराम संरचना का हिस्सा है।","guidance":"दिन खत्म होने से पहले, याद रखें: दीर्घकालिक निर्माण करें, जबकि याद रखें कि विश्राम संरचना का हिस्सा है।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'week', 'hi', '{"overview":"यह सप्ताह एक नाटकीय पल की बजाय लगातार विकल्पों के माध्यम से विकसित होता है। मकर पृथ्वी की ऊर्जा के माध्यम से चलता है। अनुशासन और दीर्घकालिक दृष्टि समुद्री बकरी को चढ़ाई करने में मदद करती है जबकि नीचे की गहराइयों के बारे में समझदार बनी रहती है।","love":"रिश्ते उस बातचीत से लाभान्वित होते हैं जो ईमानदारी और गर्मजोशी दोनों के लिए जगह बनाती है। सहनशक्ति, रणनीति, विश्वसनीयता के आपके गुण बिना प्रदर्शन किए जुड़ने में मदद कर सकते हैं।","career":"आपकी सर्वश्रेष्ठ पेशेवर प्रगति प्राथमिकता चुनने और उसके लिए समय सुरक्षित करने से आती है। महत्वाकांक्षी, अनुशासित, धैर्यवान, जिम्मेदार को औजार के रूप में उपयोग करें, न कि ऐसी अपेक्षाओं के रूप में जिन्हें आपको एक साथ पूरा करना है।","finance":"बड़ी प्रतिबद्धता करने से पहले अपने खर्च करने की आदत का पैटर्न देखें। ध्यान दें कि कब कठोरता, निराशावाद, उपलब्धियों के माध्यम से मूल्य मापना एक व्यावहारिक निर्णय को प्रभावित करना शुरू करता है।","wellbeing":"सप्ताह भर में वास्तविक पुनर्वास के साथ गति को संतुलित करें। लंबी अवधि के लिए निर्माण करें और याद रखें कि आराम संरचना का हिस्सा है।","guidance":"इस प्रश्न को इस सप्ताह का मार्गदर्शन बनने दें: लंबी अवधि के लिए निर्माण करें जबकि यह याद रखें कि विश्राम संरचना का हिस्सा है।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'year', 'hi', '{"overview":"यह वर्ष पहचान, उद्देश्य, और आपके ऊर्जा के उपयोग के तरीके के चारों ओर धैर्यपूर्वक वृद्धि का आमंत्रण देता है। मकर पृथ्वी ऊर्जा के माध्यम से आगे बढ़ता है। अनुशासन और दीर्घकालिक दृष्टिकोण समुद्र-बकरी को चढ़ने में मदद करते हैं जबकि नीचे की गहराइयों के बारे में बुद्धिमान बने रहते हैं।","love":"जब आप लगातार अभ्यास करते हैं और रिश्तों को मानव गति से विकसित होने देते हैं, तो प्यार गहरा होता है। आपकी सहनशीलता, रणनीति, भरोसेमंद होने की प्रतिभाएं आपको बिना प्रदर्शन किए जुड़ने में मदद कर सकती हैं।","career":"दीर्घकालिक कार्य अधिक मजबूत हो जाता है जब महत्वाकांक्षा को ऐसी संरचना के साथ जोड़ा जाए जिसे आप बनाए रख सकें। महत्वाकांक्षी, अनुशासित, धैर्यवान, जिम्मेदार को उपकरण के रूप में उपयोग करें, ऐसे अपेक्षाओं के रूप में नहीं जिन्हें आपको एक साथ पूरा करना चाहिए।","finance":"सटीक भविष्यवाणियों के बजाय दोहराए जाने वाले आदतों के माध्यम से वित्तीय आत्मविश्वास बनाएं। जब कठोरता, निराशावाद, उपलब्धि के माध्यम से मूल्य मापना किसी व्यावहारिक निर्णय को प्रभावित करना शुरू करता है तो इसे महसूस करें।","wellbeing":"कल्याण को उस जीवन की नींव के रूप में मानें जो आप बना रहे हैं, इसे पूरा करने के बाद मिलने वाला पुरस्कार नहीं। लंबी अवधि के लिए निर्माण करें, यह याद रखते हुए कि विश्राम संरचना का हिस्सा है।","guidance":"पूरे साल इस कंपास की ओर लौटें: दीर्घकालिक के लिए निर्माण करें जबकि यह याद रखें कि विश्राम भी संरचना का हिस्सा है।"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aquarius', 'hi', '{"name":"कुंभ","dateRange":"20 जनवरी – 18 फरवरी","rulingPlanet":"यूरैनस","summary":"स्वतंत्र विचार और सामूहिक दृष्टि जलधर को दुनिया में नए विचार डालने के लिए मार्गदर्शन करती है।","originStory":"कुंभ राशि का संबंध गैनीमेड से है, जो कप-पोषक था और जिसका पात्र देवताओं के लिए पानी लाता था और प्रतीकात्मक रूप से मानवता के लिए ज्ञान लाता था। हालांकि इसका चित्र पानी ले जाता है, यह राशि वायु तत्व की है: विचार, प्रणाली, और सामान्य भले के लिए साझा की जाने वाली नवीनीकरण।","traits":["मूल","स्वतंत्र","मानवतावादी","आविष्कारशील"],"strengths":["नवाचार","वस्तुनिष्ठता","सामुदायिक दृष्टि"],"challenges":["अलगाव","विपरीत आदतें","स्थिर राय"],"compatibleSigns":["मिथुन","तुला","धनु"],"reflectionPrompt":"आपकी भिन्नता को दूरी के बजाय संबंध के लिए सेवा करने दें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'day', 'hi', '{"overview":"आज एक स्पष्ट, जानबूझकर कदम लेने का दिन है। कुंभ हवा की ऊर्जा के माध्यम से चलता है। स्वतंत्र सोच और सामूहिक दृष्टि जल-धारक को नई विचार दुनिया में डालने के लिए मार्गदर्शन करती है।","love":"आज प्यार में, अनुमान के बजाय उपस्थिति चुनें। नवाचार, वस्तुनिष्ठता, सामुदायिक दृष्टि के आपके उपहार आपको बिना प्रदर्शन किए जुड़ने में मदद कर सकते हैं।","career":"काम पर, नई गति का पीछा करने से पहले सबसे महत्वपूर्ण कार्य पूरा करें। मूल, स्वतंत्र, मानवतावादी, आविष्कारशील को उपकरण के रूप में इस्तेमाल करें, ऐसी अपेक्षाएं नहीं जिन्हें आपको एक साथ पूरा करना है।","finance":"आज के पैसे के फैसलों को सरल और ठोस रखें। ध्यान दें कि कब अलगाव, विरोधी आदतें, ठोस राय एक व्यावहारिक निर्णय को प्रभावित करना शुरू करती हैं।","wellbeing":"एक छोटी सी विराम आपकी ऊर्जा को रीसेट कर सकती है। अपने अंतर को दूरी की बजाय संबंध के लिए काम आने दें।","guidance":"दिन खत्म होने से पहले याद रखें: अपने भिन्नता को दूरी बढ़ाने के बजाय संबंध बनाए रखने में काम आने दें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'week', 'hi', '{"overview":"इस सप्ताह एक नाटकीय क्षण की बजाय स्थिर चुनावों के माध्यम से विकसित होता है। कुम्भ वायु ऊर्जा के माध्यम से आगे बढ़ता है। स्वतंत्र विचार और सामूहिक दृष्टि जलधारी को नई सोच दुनिया में डालने के लिए मार्गदर्शन करते हैं।","love":"रिश्ते उस बातचीत से लाभान्वित होते हैं जो ईमानदारी और गर्मजोशी दोनों के लिए जगह बनाती है। नवाचार, वस्तुनिष्ठता, सामुदायिक दृष्टि के आपके गुण बिना प्रदर्शन किए जुड़ने में मदद कर सकते हैं।","career":"आपकी सबसे अच्छी पेशेवर प्रगति किसी प्राथमिकता को चुनने और उसके लिए समय की रक्षा करने से आती है। मूल, स्वतंत्र, मानवीय, आविष्कारशील को उपकरण के रूप में उपयोग करें, न कि ऐसी अपेक्षाएँ जिन्हें आपको एक बार में पूरा करना चाहिए।","finance":"बड़ी प्रतिबद्धता लेने से पहले अपने खर्च के पीछे के पैटर्न की समीक्षा करें। देखें कि कब अलगाव, विपरीत आदतें, स्थिर विचार एक व्यावहारिक निर्णय को प्रभावित करना शुरू करते हैं।","wellbeing":"सप्ताह भर में वास्तविक पुनर्प्राप्ति के साथ आंदोलन का संतुलन बनाए रखें। अपने भिन्नता को दूरी बनाने के बजाय संबंध बनाने में काम में आने दें।","guidance":"इस प्रश्न को सप्ताह का मार्गदर्शन करने दें: आपकी भिन्नता को दूरी के बजाय संबंध के लिए सेवा करने दें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'year', 'hi', '{"overview":"यह वर्ष पहचान, उद्देश्य, और आपके ऊर्जा के उपयोग के तरीके के चारों ओर धैर्यपूर्वक वृद्धि का आमंत्रण देता है। कुम्भ राशि वायु ऊर्जा के माध्यम से चलती है। स्वतंत्र विचार और सामूहिक दृष्टि जलपात्रवाहक को दुनिया में नए विचार डालने के लिए मार्गदर्शन करती है।","love":"जब आप निरंतरता का अभ्यास करते हैं और संबंध को मानवीय गति से विकसित होने देते हैं तो प्रेम गहरा होता है। आपकी नवाचार, विश्लेषणात्मकता, और सामुदायिक दृष्टि की विशेषताएँ बिना प्रदर्शन के जुड़ने में आपकी मदद कर सकती हैं।","career":"दीर्घकालिक कार्य तब मजबूत होता है जब महत्वाकांक्षा को एक ऐसे ढांचे के साथ जोड़ा जाए जिसे आप बनाए रख सकते हैं। मौलिक, स्वतंत्र, मानवतावादी, आविष्कारक का उपयोग उपकरण के रूप में करें, ऐसी अपेक्षाओं के रूप में नहीं जिन्हें आपको एक बार में पूरा करना चाहिए।","finance":"सटीक भविष्यवाणियों के बजाय दोहराए जाने वाले आदतों के माध्यम से वित्तीय आत्मविश्वास बनाएं। ध्यान दें जब अलगाव, विरोधी आदतें, निश्चित राय एक व्यावहारिक निर्णय को प्रभावित करना शुरू कर दें।","wellbeing":"कल्याण को उस जीवन की नींव के रूप में मानें जिसे आप बना रहे हैं, इसे पूरा करने के बाद मिलने वाला इनाम न समझें। अपने अंतर को दूरी के बजाय संबंध की सेवा करने दें।","guidance":"पूरा साल इस कम्पास की ओर लौटते रहो: अपने अंतर को दूरी बजाय संबंध के लिए सेवा करने दो।"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('pisces', 'hi', '{"name":"मीन","dateRange":"19 फरवरी – 20 मार्च","rulingPlanet":"नेपच्यून","summary":"दया और कल्पना मछलियों को अंतर्ज्ञान, सपनों और साझा भावना के बीच मार्गदर्शन करती है।","originStory":"मीन एफ़्रोडाइट और अरोज़ को याद दिलाता है, जो मछली बनकर अपने आप को टाइफॉन से बचाने के लिए एक-दूसरे से बंधते हैं। इन दो मछलियों के बीच का बंधन भक्ति, प्रवाही पहचान, आध्यात्मिक संवेदनशीलता और बदलती धारा के माध्यम से चलते हुए एकता खोजने का प्रतिनिधित्व करता है।","traits":["दयालु","कल्पनाशील","सहज","कोमल"],"strengths":["सहानुभूति","रचनात्मकता","आध्यात्मिक अंतर्दृष्टि"],"challenges":["पलायनवाद","धुंधली सीमाएं","दूसरों की भावनाओं को आत्मसात करना"],"compatibleSigns":["कैंसर","वृश्चिक","मकर"],"reflectionPrompt":"अपनी संवेदनशीलता का सम्मान करें और इसे सुरक्षित रखने के लिए पर्याप्त मजबूत सीमाएँ रखें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'day', 'hi', '{"overview":"आज एक स्पष्ट, योजना बना हुआ कदम लेना अनुकूल है। मीन जल ऊर्जा के माध्यम से चलता है। सहानुभूति और कल्पना मीन को अंतर्ज्ञान, सपनों, और साझा भावनाओं के बीच मार्गदर्शन करते हैं।","love":"आज प्यार में, अनुमान के बजाय उपस्थिति को चुनें। सहानुभूति, रचनात्मकता, आध्यात्मिक अंतर्दृष्टि की आपकी क्षमताएँ बिना प्रदर्शन किए जुड़ने में आपकी मदद कर सकती हैं।","career":"काम पर, नए उत्साह का पीछा करने से पहले सबसे महत्वपूर्ण कार्य पूरा करें। सहानुभूतिशील, कल्पनाशील, सहज, कोमल को उपकरण के रूप में उपयोग करें, ऐसे अपेक्षाएँ नहीं जिन्हें आपको एक बार में पूरा करना है।","finance":"आज के पैसे के फैसलों को सरल और ठोस रखें। ध्यान दें कि कब बचकाना व्यवहार, धुंधली सीमाएँ, दूसरों की भावनाओं को अवशोषित करना एक व्यावहारिक निर्णय को प्रभावित करना शुरू करता है।","wellbeing":"एक छोटा सा विराम आपके ऊर्जा को पुनःस्थापित कर सकता है। अपनी संवेदनशीलता का सम्मान करें और इसे सुरक्षित रखने के लिए पर्याप्त मजबूत सीमाएँ बनाएं।","guidance":"दिन खत्म होने से पहले याद रखें: अपनी संवेदनशीलता का सम्मान करें और उसे सुरक्षित रखने के लिए पर्याप्त मजबूत सीमाओं का निर्माण करें।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'week', 'hi', '{"overview":"इस सप्ताह धीरे-धीरे किए गए विकल्पों के माध्यम से विकसित होता है, न कि किसी एक नाटकीय क्षण से। मीन जल ऊर्जा के माध्यम से आगे बढ़ते हैं। करुणा और कल्पना मछलियों को अंतर्ज्ञान, सपनों, और साझा भावना के बीच मार्गदर्शन करती हैं।","love":"संबंधों को ऐसे संवाद से लाभ मिलता है जो ईमानदारी और गर्मजोशी दोनों के लिए स्थान बनाता है। आपकी सहानुभूति, रचनात्मकता, आध्यात्मिक अंतर्दृष्टि के उपहार आपको बिना अभिनय किए जुड़ने में मदद कर सकते हैं।","career":"आपकी सबसे अच्छी पेशेवर प्रगति प्राथमिकता चुनने और इसके लिए समय की रक्षा करने से आती है। उपकरण के रूप में दयालु, कल्पनाशील, सहज, कोमल का उपयोग करें, न कि अपेक्षाओं को जो आपको एक ही बार में पूरा करना चाहिए।","finance":"बड़ी प्रतिबद्धता बनाने से पहले अपनी खर्च करने की आदतों के पैटर्न की समीक्षा करें। ध्यान दें कि जब बचावात्मक व्यवहार, धुंधली सीमाएं, दूसरों की भावनाओं को आत्मसात करना व्यावहारिक निर्णय को प्रभावित करने लगते हैं।","wellbeing":"सप्ताह भर वास्तविक सुधार के साथ संतुलित गतिविधि बनाएँ। अपनी संवेदनशीलता का सम्मान उन सीमाओं के साथ करें जो इसे सुरक्षित रखने के लिए पर्याप्त मजबूत हों।","guidance":"इस प्रश्न को इस सप्ताह का मार्गदर्शन बनने दें: अपनी संवेदनशीलता का सम्मान करें, इतनी मजबूत सीमाओं के साथ कि यह सुरक्षित रहे।"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'year', 'hi', '{"overview":"इस वर्ष पहचान, उद्देश्य और आपके ऊर्जा उपयोग के तरीके के आसपास धैर्यपूर्ण विकास का आमंत्रण देता है। मीन पानी की ऊर्जा से गुजरता है। सहानुभूति और कल्पना मछलियों को अंतर्ज्ञान, सपनों और साझा भावना के बीच मार्गदर्शन करती हैं।","love":"जब आप लगातार अभ्यास करते हैं और रिश्तों को मानव गति से विकसित होने देते हैं, तो प्यार गहरा होता है। आपकी सहानुभूति, रचनात्मकता, आध्यात्मिक अंतर्दृष्टि की प्रतिभाएं आपको बिना प्रदर्शन किए जुड़ने में मदद कर सकती हैं।","career":"दीर्घकालिक कार्य अधिक मजबूत हो जाता है जब महत्वाकांक्षा को ऐसी संरचना के साथ जोड़ा जाए जिसे आप बनाए रख सकें। करुणामय, कल्पनाशील, सहज, мяг्क को उपकरणों के रूप में प्रयोग करें, न कि अपेक्षाएं जिन्हें आपको एक साथ पूरा करना जरूरी हो।","finance":"संपूर्ण भविष्यवाणियों के बजाय दोहराए जाने वाले आदतों के माध्यम से वित्तीय आत्मविश्वास बनाएं। जब पलायनवाद, अस्पष्ट सीमाएँ, दूसरों की भावनाओं को अपने में समेटना किसी व्यावहारिक निर्णय को प्रभावित करना शुरू कर दे, तो इसे नोटिस करें।","wellbeing":"कल्याण को उस जीवन के आधार के रूप में मानें जिसे आप बना रहे हैं, इसे समाप्त करने के बाद मिलने वाले इनाम के रूप में नहीं। अपनी संवेदनशीलता का सम्मान करें और इसे सुरक्षित रखने के लिए मजबूत सीमाएं रखें।","guidance":"पूरे साल इस कंपास की ओर लौटें: अपनी संवेदनशीलता का सम्मान करें, इतनी मजबूत सीमाओं के साथ कि यह सुरक्षित रहे।"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('fool', 'th', '{"name":"คนโง่","meaning":"หน้ากระดาษว่างและการก้าวด้วยความเชื่อ — การเดินทางใหม่เริ่มต้นด้วยใจที่เปิดกว้าง","advice":"วางใจในเส้นทางที่อยู่ข้างหน้าคุณและก้าวก้าวแรกนั้น แม้ยังไม่มีคำตอบทั้งหมด","yesNoMeaning":"การเริ่มต้นใหม่มักไม่มาพร้อมคำตอบที่แน่นอน — ผลลัพธ์ขึ้นอยู่กับก้าวที่คุณเลือก"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('magician', 'th', '{"name":"จอมเวทย์","meaning":"คุณถือเครื่องมือทั้งหมดที่คุณต้องการไว้ในมือ จดจ่อกับความตั้งใจและเปลี่ยนความตั้งใจเป็นการกระทำ","advice":"ใช้ทักษะและทรัพยากรของคุณอย่างรอบคอบ — ตอนนี้เป็นเวลาที่จะทำให้มันเกิดขึ้น","yesNoMeaning":"คุณมีทุกอย่างที่จำเป็นอยู่แล้ว — พลังงานช่วยสนับสนุนให้ก้าวไปข้างหน้าอย่างมีสมาธิ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('high-priestess', 'th', '{"name":"The High Priestess","meaning":"ภูมิปัญญาเงียบซ่อนอยู่ใต้ผิวเผิน ฟังสัญชาตญาณและเสียงภายในของคุณ","advice":"หยุด, มองเข้าไปข้างใน, และปล่อยให้สัญชาตญาณนำทางคุณก่อนที่จะลงมือทำ","yesNoMeaning":"คำตอบซ่อนอยู่ใต้พื้นผิวในตอนนี้ — เชื่อสัญชาตญาณของคุณแทนที่จะบังคับให้มีคำตอบใช่หรือไม่"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('empress', 'th', '{"name":"จักรพรรดินี","meaning":"พลังแห่งการเติบโต ความอุดมสมบูรณ์ และการเลี้ยงดูล้อมรอบคุณ ให้ความงามและการดูแลเบ่งบาน","advice":"จงอดทนและใจกว้าง — สร้างสรรค์ด้วยความรักและปล่อยให้สิ่งต่าง ๆ เจริญเติบโตตามธรรมชาติ","yesNoMeaning":"พลังแห่งการเติบโต ความอุดมสมบูรณ์ และการเลี้ยงดูสนับสนุนความปรารถนาของคุณ — คำตอบคือคำว่าใช้อย่างเงียบ ๆ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('emperor', 'th', '{"name":"จักรพรรดิ","meaning":"โครงสร้าง อำนาจ และความเป็นผู้นำที่มั่นคง สร้างบนพื้นฐานที่มั่นคงด้วยวินัย","advice":"ควบคุมสถานการณ์ด้วยแผนที่ชัดเจน ขอบเขตที่แน่นอนนำมาซึ่งความมั่นคงที่ยั่งยืน","yesNoMeaning":"โครงสร้าง อำนาจ และวินัยที่มั่นคงยืนอยู่เบื้องหลังคำว่าใช้อย่างมั่นใจ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hierophant', 'th', '{"name":"The Hierophant","meaning":"ประเพณีและคำแนะนำที่ไว้วางใจได้มอบเส้นทางที่เชื่อถือได้ เรียนรู้จากสิ่งที่เกิดขึ้นมาก่อน","advice":"ติดตามปัญญาที่สืบทอดมาและขอคำปรึกษาจากผู้ที่คุณไว้วางใจ","yesNoMeaning":"ประเพณีและคำแนะนำที่เชื่อถือได้ชี้ไปที่คำตอบใช่ที่น่าเชื่อถือ — พึ่งพาสิ่งที่ได้พิสูจน์แล้วว่าได้ผล"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('lovers', 'th', '{"name":"คู่รัก","meaning":"ความสัมพันธ์ที่มีความหมายหรือการตัดสินใจที่สำคัญ ทำตามสิ่งที่หัวใจคุณให้คุณค่าจริง ๆ","advice":"เลือกด้วยความซื่อสัตย์และสอดคล้อง — การเชื่อมโยงลึกซึ้งขึ้นเมื่อคุณจริงใจ","yesNoMeaning":"หัวใจและค่านิยมของคุณสอดคล้องกันที่นี่ — คำตอบคือใช่ โดยเฉพาะเมื่อคุณเลือกด้วยความซื่อสัตย์"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('chariot', 'th', '{"name":"รถม้า","meaning":"พลังใจและแรงผลักดันช่วยให้คุณก้าวไปข้างหน้า จงมุ่งมั่นและคุณจะสำเร็จ","advice":"จงมุ่งมั่นสู่เป้าหมายและควบคุมด้วยความมั่นใจผ่านอุปสรรคทุกอย่าง","yesNoMeaning":"พลังใจและแรงผลักดันอยู่ข้างคุณ — ตอบว่าใช่แบบมุ่งมั่น แต่ต้องยึดมั่นเสมอ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('strength', 'th', '{"name":"ความแข็งแกร่ง","meaning":"พลังที่แท้จริงนั้นอ่อนโยน — ความอดทน ความกล้า และความเห็นอกเห็นใจสามารถควบคุมความท้าทายใด ๆ ได้","advice":"นำด้วยความแข็งแกร่งที่สงบ มือที่อ่อนโยนมักเป็นมือที่แข็งแกร่งที่สุด","yesNoMeaning":"ความกล้าอันอ่อนโยนและความมุ่งมั่นอย่างอดทนทำให้สิ่งนี้เป็นคำตอบว่าใช่ — นำด้วยความสงบ ไม่ใช่กำลัง"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hermit', 'th', '{"name":"The Hermit","meaning":"ถึงเวลาถอยกลับและแสวงหาความชัดเจนภายใน ความโดดเดี่ยวตอนนี้นำคำตอบที่ลึกซึ้งมากขึ้น","advice":"หันเข้าไปภายใน ใคร่ครวญ และปล่อยให้ความสงบเปิดเผยสิ่งที่คุณต้องการจริง ๆ","yesNoMeaning":"ยังไม่ — ไพ่กำลังบอกให้คุณถอยกลับไปและหาความชัดเจนภายในก่อนที่จะลงมือทำ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('wheel-of-fortune', 'th', '{"name":"วงล้อโชคชะตา","meaning":"โชคชะตาหมุนเวียนและวัฏจักรเปลี่ยนไป สิ่งที่เปลี่ยนตอนนี้เป็นส่วนหนึ่งของจังหวะที่ใหญ่กว่า","advice":"ล่องตามกระแสด้วยความยืดหยุ่น — ยอมรับการเปลี่ยนแปลง ไม่ว่าจะดีหรือไม่ดี","yesNoMeaning":"โชคชะตากำลังเปลี่ยน — ผลลัพธ์ขึ้นอยู่กับว่าคุณปรับตัวต่อการเปลี่ยนแปลงอย่างไร แทนที่จะเป็นใช่หรือไม่ใช่ที่แน่นอน"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('justice', 'th', '{"name":"ความยุติธรรม","meaning":"ความจริงและความยุติธรรมชนะเสมอ เหตุและผลในตอนนี้อยู่ในความสมดุล","advice":"ทำอย่างซื่อสัตย์และชั่งน้ำหนักทั้งสองด้าน ตาชั่งจะปรับสมดุลอย่างยุติธรรม","yesNoMeaning":"ตาชั่งยังคงชั่งน้ำหนัก — คำตอบที่ยุติธรรมขึ้นอยู่กับข้อเท็จจริงและความซื่อสัตย์ของคุณ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hanged-man', 'th', '{"name":"The Hanged Man","meaning":"การหยุดชะงักที่จำเป็น ปล่อยการควบคุมและมองสถานการณ์จากมุมมองใหม่","advice":"หยุดการผลักดัน — ยอมรับช่วงเวลาและปล่อยให้มุมมองใหม่เข้ามา","yesNoMeaning":"จำเป็นต้องหยุดก่อน — การบังคับตอนนี้จะทำให้คำตอบชัดเจนน้อยลง"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('death', 'th', '{"name":"ความตาย","meaning":"การสิ้นสุดเปิดทางสำหรับการเริ่มใหม่ ปล่อยสิ่งที่ใช้เวลาของมันแล้วออกไป","advice":"ปล่อยวางโดยไม่เสียใจ การเปลี่ยนแปลงอย่างลึกซึ้งกำลังเปิดประตูใหม่","yesNoMeaning":"การสิ้นสุดคือการเคลียร์ทาง — เส้นทางปัจจุบันกำลังปิดเพื่อให้เส้นทางใหม่เริ่มต้น"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('temperance', 'th', '{"name":"ความสมดุล","meaning":"ความสมดุลและความอดทนสร้างความกลมกลืน ผสมผสานสิ่งตรงข้ามด้วยความสง่างาม","advice":"เคลื่อนไหวอย่างพอประมาณและรักษาความเยือกเย็น — ก้าวที่มั่นคงจะถึงจุดหมาย","yesNoMeaning":"ความสมดุลและความอดทนสร้างความกลมกลืน — การตอบตกลงอย่างรอบคอบทีละก้าวอย่างมั่นคง"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('devil', 'th', '{"name":"ปีศาจ","meaning":"ระวังการยึดติด การล่อลวง หรือรูปแบบที่ยึดเหนี่ยว จงตระหนักถึงโซ่ตรวน","advice":"ระบุสิ่งที่ผูกมัดคุณและเรียกคืนอิสรภาพของคุณ — โซ่ผูกมัดก็ต่อเมื่อคุณยอมให้","yesNoMeaning":"การยึดติดหรือรูปแบบการผูกมัดจะขวางทาง — ยังไม่ใช่ตอนนี้ จนกว่าสายโซ่จะถูกตั้งชื่อและถูกตัดขาด"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('tower', 'th', '{"name":"เดอะทาวเวอร์","meaning":"การเปลี่ยนแปลงอย่างกะทันหันทำลายสิ่งที่เป็นเท็จและเผยความจริง สิ่งที่ล้มลงไม่เคยถูกสร้างให้ยืนอยู่","advice":"ต้อนรับความว้าวุ่น; จากซากสามารถสร้างรากฐานที่ชัดเจนขึ้นได้","yesNoMeaning":"การเปลี่ยนแปลงอย่างกะทันหันกำลังทำลายสิ่งเก่า — พื้นที่ต้องสงบก่อนที่คำว่าใช้อย่างมั่นคงจะเป็นไปได้"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('star', 'th', '{"name":"ไพ่ The Star","meaning":"ความหวัง การเยียวยา และแรงบันดาลใจอย่างเงียบสงบ ฟื้นฟูจิตวิญญาณของคุณหลังพายุ","advice":"วางใจในแสงสว่างข้างหน้าและเชื่อมั่นต่อไป — ความปรารถนาของคุณอยู่แค่เอื้อม","yesNoMeaning":"ความหวังและการฟื้นฟูอย่างเงียบสงบชี้ไปที่ใช่ — ไว้วางใจแสงสว่างข้างหน้าและรักษาความปรารถนาของคุณให้คงอยู่"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('moon', 'th', '{"name":"พระจันทร์","meaning":"ภาพลวงตาและความไม่แน่นอนทำให้เส้นทางพร่ามัว ไว้วางใจสัญชาตญาณของคุณ ไม่ใช่สิ่งที่เห็น","advice":"ชะลอและมองลึกลงไป; ความชัดจะมาถึงเมื่อหมอกจางลง","yesNoMeaning":"ภาพลวงตาและความไม่แน่นอนทำให้เส้นทางพร่ามัว — คำตอบไม่ชัดเจนจนกว่าคุณจะมองใต้ผิวเผิน"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('sun', 'th', '{"name":"ไพ่ The Sun","meaning":"ความยินดี ความสำเร็จ และความชัดเจนเจิดจ้า ทุกสิ่งสดใสและเต็มไปด้วยชีวิตชีวา","advice":"เฉลิมฉลองและเปล่งประกาย — พลังบวกดึงดูดผลลัพธ์ที่คุณปรารถนา","yesNoMeaning":"ความยินดีและความชัดเจนเจิดจ้าชี้ให้เห็นคำตอบที่สดใส — ทุกสิ่งกำลังเป็นไปในทางที่คุณได้เปรียบ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('judgement', 'th', '{"name":"การตัดสิน","meaning":"การเรียกร้องให้ลุกขึ้น ฟื้นฟู และซื่อสัตย์กับตัวเอง คำตัดสินแห่งการตื่นรู้","advice":"ตอบรับการเรียกร้องด้วยความกล้า; อภัยในอดีตและก้าวเข้าสู่บทต่อไปของคุณ","yesNoMeaning":"การเรียกร้องให้ลุกขึ้นและฟื้นฟู — ใช่ โดยเฉพาะเมื่อคุณให้อภัยอดีตและตอบอย่างซื่อสัตย์"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('world', 'th', '{"name":"ไพ่ The World","meaning":"ความสมบูรณ์และความสำเร็จ — วงจรปิดลงในความสมบูรณ์แบบ","advice":"เฉลิมฉลองสิ่งที่คุณทำสำเร็จ; ประตูเปิดสู่โลกที่กว้างขึ้น","yesNoMeaning":"ความสมบูรณ์และความครบถ้วนเป็นเครื่องหมายว่านี่คือการตอบรับที่สมบูรณ์ — วงจรปิดลงในความโปรดปรานของคุณ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-wands', 'th', '{"name":"เอซแห่งไม้เท้า","meaning":"ประกายของแรงบันดาลใจเปิดทางสร้างสรรค์ที่กล้าหาญ","advice":"เริ่มต้นในขณะที่พลังยังสดใหม่และให้ไอเดียก้าวแรกที่แท้จริง","yesNoMeaning":"เอซของไม้เท้าโน้มเอียงไปใช่: เริ่มต้นขณะที่พลังงานสดใหม่และให้แนวคิดนั้นมีขั้นตอนแรกที่เป็นจริง"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-wands', 'th', '{"name":"สองไม้เท้า","meaning":"อนาคตกำลังถูกสร้างขึ้นผ่านการวางแผนและการเลือกเส้นทาง","advice":"มองไกลกว่าสิ่งที่คุ้นเคย แล้วจงมุ่งมั่นไปบนเส้นทางที่มีพื้นที่ให้เติบโต","yesNoMeaning":"ไพ่ Two of Wands ยังคงแบบมีเงื่อนไข: มองไกลออกไปเกินสิ่งที่คุ้นเคย แล้วจึงมุ่งมั่นไปในเส้นทางที่มีโอกาสเติบโต"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-wands', 'th', '{"name":"ไพ่สามไม้เท้า","meaning":"ความพยายามตั้งแต่ต้นจะขยายตัวเมื่อโอกาสและขอบฟ้าที่กว้างขึ้นปรากฏ","advice":"สร้างต่อไปและเตรียมพร้อมรับผลตอบรับจากงานของคุณ","yesNoMeaning":"ไพ่สามไม้เท้าโน้มไปทางใช่: สร้างต่อไปและเตรียมพร้อมที่จะพบกับผลลัพธ์จากงานของคุณ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-wands', 'th', '{"name":"สี่คฑา","meaning":"ความมั่นคง, การต้อนรับ, และการเฉลิมฉลองร่วมกันสร้างรากฐานที่แข็งแรง","advice":"ทำเครื่องหมายเหตุการณ์สำคัญและให้ผู้สนับสนุนร่วมแบ่งปัน","yesNoMeaning":"The Four of Wands มีแนวโน้มว่าใช่: ทำเครื่องหมายเหตุการณ์สำคัญและให้คนที่สนับสนุนได้มีส่วนร่วมในมัน"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-wands', 'th', '{"name":"ไพ่ห้าไม้","meaning":"เป้าหมายที่แข่งขันกันสร้างความเสียดทาน เสียงรบกวน หรือเป็นการทดสอบความมั่นใจ","advice":"เปลี่ยนการแข่งขันให้เป็นการฝึกฝนที่เป็นประโยชน์และปฏิเสธความขัดแย้งที่ไม่มีประโยชน์","yesNoMeaning":"ไพไม้เท้าห้าใบยังคงมีเงื่อนไข: เปลี่ยนการแข่งขันให้เป็นการฝึกฝนที่มีประโยชน์และปฏิเสธความขัดแย้งที่ไม่มีจุดประสงค์"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-wands', 'th', '{"name":"ไพ่หกไม้เท้า","meaning":"การรับรู้ตามมาจากความพยายามที่มุ่งมั่นและความก้าวหน้าที่มองเห็นได้","advice":"ยอมรับคำปลุกใจ แต่คงความมั่นใจของคุณไว้กับการทำงานอย่างซื่อสัตย์","yesNoMeaning":"ไพ่ Six of Wands โน้มไปทางใช่: ยอมรับกำลังใจ แต่เก็บความมั่นใจของคุณไว้กับงานที่ซื่อสัตย์"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-wands', 'th', '{"name":"เจ็ดแท่ง","meaning":"คุณครองพื้นที่ที่มีค่าในขณะที่แรงกดดันทดสอบความแน่วแน่ของคุณ","advice":"ปกป้องสิ่งที่สำคัญด้วยขอบเขตที่ชัดเจน แทนที่จะต่อสู้กับทุกความท้าทาย","yesNoMeaning":"ไพ่ Seven of Wands โน้มไปทางใช่: ปกป้องสิ่งที่สำคัญด้วยขอบเขตที่ชัดเจน แทนที่จะต่อสู้กับทุกความท้าทาย"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-wands', 'th', '{"name":"แปดของไม้เท้า","meaning":"เหตุการณ์เร่งรีบ ข้อความมาถึง และโมเมนตัมช่วยเคลียร์ความล่าช้า","advice":"ลงมือทำอย่างรวดเร็วและติดต่อสื่อสารตรงไปตรงมาตลอดเส้นทางที่เปิดอยู่","yesNoMeaning":"แปดของไม้เท้าเอนโน้ต: ลงมืออย่างรวดเร็วและสื่อสารโดยตรงในขณะที่เส้นทางเปิดอยู่"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-wands', 'th', '{"name":"เก้าไม้เท้า","meaning":"ความยืดหยุ่นเข้มแข็ง แม้ความตึงเคยเกิดขึ้นจะทำให้คุณระมัดระวัง","advice":"ปกป้องพลังงานของตัวเองและก้าวต่อไปโดยไม่คาดหวังว่าบาดแผลทุกครั้งจะเกิดซ้ำ","yesNoMeaning":"ไพ่เก้าไม้เท้ายังคงมีเงื่อนไข: ปกป้องพลังงานของคุณและก้าวไปข้างหน้าโดยไม่คาดหวังว่าบาดแผลทุกอย่างจะเกิดซ้ำ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-wands', 'th', '{"name":"สิบไม้เท้า","meaning":"ความรับผิดชอบกลายเป็นภาระ และความสำเร็จตอนนี้มีภาระติดตาม","advice":"มอบหมายงาน ทำให้เรียบง่าย และวางงานที่ไม่ใช่ของคุณอีกต่อไป","yesNoMeaning":"ไพ่สิบไม้เท้าโน้มไปทางไม่: มอบหมายงาน ทำให้เรียบง่าย และวางงานที่ไม่ใช่ของคุณอีกต่อไป"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-wands', 'th', '{"name":"หน้าไพ่ไม้เท้า","meaning":"ความอยากรู้อยากเห็นนำข้อความที่มีชีวิต ช่วยในการทดลอง หรือความสนใจสร้างสรรค์ใหม่ๆ","advice":"สำรวจด้วยความกล้าและให้พลังของผู้เริ่มต้นสอนคุณผ่านการลงมือทำ","yesNoMeaning":"ไพ่เพจไม้เท้ามีแนวโน้มไปทางใช่: สำรวจด้วยความกล้าหาญและให้พลังงานของผู้เริ่มต้นสอนคุณผ่านการกระทำ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-wands', 'th', '{"name":"อัศวินไม้เท้า","meaning":"ความหลงใหลมักพุ่งไปข้างหน้าอย่างรวดเร็ว นำมาซึ่งการผจญภัยและความอาจขาดความอดทน","advice":"ใช้แรงส่ง แต่เลือกทิศทางก่อนที่ความเร็วจะกระจายความพยายามของคุณ","yesNoMeaning":"อัศวินแห่งไม้เท้า ยังมีเงื่อนไข: ใช้แรงผลักดัน แต่เลือกทิศทางก่อนที่ความเร็วจะกระจายความพยายามของคุณ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-wands', 'th', '{"name":"ราชินีแห่งไม้เท้า","meaning":"ความมั่นใจแบบอบอุ่นและความเป็นอิสระในการสร้างสรรค์ดึงดูดผู้อื่นเข้าสู่วิสัยทัศน์ของคุณ","advice":"วางใจในตัวตนของคุณ ส่งเสริมผู้อื่น และอย่ากดความทะเยอทะยานของคุณ","yesNoMeaning":"ราชินีแห่งไม้เท้าเอียงไปทางใช่: ไว้วางใจในตัวตนของคุณ สนับสนุนผู้อื่น และอย่าลดทอนความทะเยอทะยานของคุณ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-wands', 'th', '{"name":"ราชาไม้เท้า","meaning":"วิสัยทัศน์ที่เติบโตทำให้แรงบันดาลใจกลายเป็นความเป็นผู้นำที่เด็ดขาดและมีจริยธรรม","advice":"นำจากความตั้งใจใหญ่และให้ผู้อื่นมีพื้นที่ในการมีส่วนร่วม","yesNoMeaning":"The King of Wands มีแนวโน้มว่าใช่: นำจากเป้าหมายที่ใหญ่ขึ้นและให้ผู้อื่นมีพื้นที่ในการมีส่วนร่วม"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-cups', 'th', '{"name":"เอซแห่งถ้วย","meaning":"หัวใจเปิดรับความรักใหม่ ความเมตตา และการฟื้นฟูทางอารมณ์","advice":"รับรู้ความรู้สึกอย่างซื่อสัตย์และปล่อยให้ความเอาใจใส่ไหลโดยไม่บังคับผลลัพธ์","yesNoMeaning":"เอซของถ้วยโน้มเอียงไปใช่: รับความรู้สึกอย่างแท้จริงและปล่อยให้ความเอาใจใส่ไหลโดยไม่บังคับผลลัพธ์"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-cups', 'th', '{"name":"สองถ้วย","meaning":"การยอมรับซึ่งกันและกันสร้างความเป็นหุ้นส่วน ความดึงดูด หรือความเห็นชอบอย่างจริงใจ","advice":"พบคนอื่นในฐานะที่เท่าเทียมและพูดจากใจ","yesNoMeaning":"ไพ่ Two of Cups โน้มไปทางใช่: พบกับอีกฝ่ายในฐานะที่เท่าเทียมและพูดจากใจ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-cups', 'th', '{"name":"ไพ่สามถ้วย","meaning":"มิตรภาพ ชุมชน และความสุขที่แบ่งปันนำการสนับสนุนทางอารมณ์","advice":"เฉลิมฉลองร่วมกันและจดจำผู้ที่เข้ามาอย่างจริงใจ","yesNoMeaning":"ไพ่สามถ้วยโน้มไปทางใช่: เฉลิมฉลองร่วมกันและจำคนที่อยู่เคียงข้างคุณอย่างแท้จริง"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-cups', 'th', '{"name":"สี่ถ้วย","meaning":"การถอนตัวทางอารมณ์ทำให้ของขวัญที่มีอยู่สังเกตได้ยาก","advice":"หยุดการเปรียบเทียบและมองสิ่งที่กำลังถูกเสนออย่างเงียบ ๆ อีกครั้ง","yesNoMeaning":"ไพถ้วยสี่ใบเอียงไปไม่: หยุดการเปรียบเทียบและมองอีกครั้งในสิ่งที่กำลังถูกมอบให้อย่างเงียบ ๆ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-cups', 'th', '{"name":"ไพ่ห้าถ้วย","meaning":"ความสูญเสียดึงความสนใจไปยังสิ่งที่รั่วไหล ขณะที่บางสิ่งที่มีความหมายยังคงอยู่","advice":"เคารพความผิดหวัง จากนั้นหันไปหาการสนับสนุนที่ยังมีอยู่","yesNoMeaning":"ห้าของถ้วยเอนโน้ต: ให้เกียรติความผิดหวัง จากนั้นหันไปสู่การสนับสนุนที่ยังคงอยู่"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-cups', 'th', '{"name":"ไพ่หกถ้วย","meaning":"ความทรงจำ ความไร้เดียงสา หรือความผูกพันที่คุ้นเคยกลับมาพร้อมกับความอบอุ่นอย่างอ่อนโยน","advice":"ยอมรับความใจดีในอดีตโดยไม่ต้องแสร้งว่าคุณต้องกลับไปใช้ชีวิตที่นั่นอีกครั้ง","yesNoMeaning":"ไพ่ Six of Cups โน้มไปทางใช่: ยอมรับความเมตตาของอดีตโดยไม่ต้องแกล้งทำเหมือนว่าคุณต้องกลับไปอยู่ที่นั่นอีกครั้ง"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-cups', 'th', '{"name":"เจ็ดดวงถ้วย","meaning":"ความเป็นไปได้ที่น่าสนใจหลายอย่างทำให้ความแตกต่างระหว่างวิสัยทัศน์และภาพลวงตาไม่ชัดเจน","advice":"จำกัดทางเลือกและทดสอบความฝันหนึ่งกับความจริงก่อนที่จะตัดสินใจ","yesNoMeaning":"เจ็ดถ้วยยังไม่ชัดเจน: จำกัดทางเลือกและทดสอบความฝันหนึ่งกับความจริงก่อนจะมุ่งมั่น"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-cups', 'th', '{"name":"แปดของถ้วย","meaning":"สถานการณ์ที่เคยมีความหมายไม่ทำให้หัวใจอิ่มเอมอีกต่อไป","advice":"จากไปอย่างซื่อสัตย์และมุ่งสู่ความพึงพอใจที่ลึกซึ้งกว่าที่คุณต้องการในตอนนี้","yesNoMeaning":"แปดของถ้วยเอนโน้ต: ออกไปด้วยความซื่อสัตย์และมุ่งสู่ความเติมเต็มที่ลึกซึ้งที่คุณต้องการในตอนนี้"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-cups', 'th', '{"name":"เก้าถ้วย","meaning":"ความพอใจและความกตัญญูทำให้ความปรารถนาที่แท้จริงรู้สึกใกล้ชิด","advice":"สนุกกับสิ่งที่มีอยู่ที่นี่และถามว่าความปรารถนานั้นสอดคล้องกับค่านิยมลึกซึ้งของคุณด้วยหรือไม่","yesNoMeaning":"เก้าถ้วยคว่ำไปทางใช่: เพลิดเพลินกับสิ่งที่อยู่ตรงหน้าและถามว่าความปรารถนานั้นสอดคล้องกับคุณค่าลึกๆ ของคุณหรือไม่"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-cups', 'th', '{"name":"สิบถ้วย","meaning":"ความกลมกลืนทางอารมณ์ ความเป็นเจ้าของ และความเชื่อมโยงที่ยั่งยืนล้อมรอบบ้าน","advice":"บำรุงความสัมพันธ์ที่ทำให้ความสุขยั่งยืนและแบ่งปันกันได้","yesNoMeaning":"ไพ่ Ten of Cups โน้มไปทางใช่: ดูแลความสัมพันธ์ที่ทำให้ความสุขเป็นสิ่งที่ยั่งยืนและแบ่งปันร่วมกัน"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-cups', 'th', '{"name":"หน้าไพ่ถ้วย","meaning":"ข้อความอ่อนโยนหรือการค้นพบด้วยสัญชาตญาณเชิญชวนการเปิดใจทางอารมณ์","advice":"รักษาความอยากรู้อยากเห็นเกี่ยวกับความรู้สึกและตอบสนองด้วยความจริงใจแทนการสันนิษฐาน","yesNoMeaning":"ไพ่เพจถ้วยยังคงมีเงื่อนไข: อย่าหยุดสงสัยในความรู้สึกและตอบสนองด้วยความจริงใจแทนการสมมติ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-cups', 'th', '{"name":"อัศวินถ้วย","meaning":"โรแมนติก จินตนาการ หรืออุดมคติ ดึงหัวใจไปข้างหน้า","advice":"ตอบรับคำเชิญ แต่จงวางเท้าหนึ่งข้างบนพื้นในขณะที่คำสัญญาถูกเปิดเผย","yesNoMeaning":"The Knight of Cups มีแนวโน้มว่าใช่: ทำตามคำเชิญ แต่ให้หนึ่งเท้ายังคงอยู่บนพื้นขณะที่คำสัญญาค่อย ๆ เกิดขึ้น"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-cups', 'th', '{"name":"ราชินีแห่งถ้วย","meaning":"ความเห็นอกเห็นใจลึกซึ้งและสัญชาตญาณสร้างพื้นที่ที่สงบเพื่อความจริง","advice":"ฟังด้วยความเอาใจใส่อย่างมีเมตตาในขณะที่รักษาขอบเขตที่ทำให้การดูแลมีสุขภาพดี","yesNoMeaning":"ไพ่ควีนถ้วยมีแนวโน้มไปทางใช่: ฟังด้วยความเมตตาในขณะที่รักษาขอบเขตที่ทำให้การดูแลเป็นไปอย่างมีสุขภาพดี"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-cups', 'th', '{"name":"ราชาถ้วย","meaning":"ความ成熟ทางอารมณ์ช่วยให้ความรู้สึกที่แรงกล้าอยู่มั่นคงโดยไม่กดข่มพวกมัน","advice":"ตอบสนองด้วยความเห็นอกเห็นใจและการควบคุมตนเอง โดยเฉพาะเมื่อผู้อื่นมีปฏิกิริยา","yesNoMeaning":"The King of Cups มีแนวโน้มว่าใช่: ตอบสนองด้วยความเห็นอกเห็นใจและควบคุมตนเอง โดยเฉพาะเมื่อคนอื่นมีปฏิกิริยา"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-swords', 'th', '{"name":"เอซแห่งดาบ","meaning":"ความเข้าใจที่สดใสตัดผ่านความสับสนและเผยให้เห็นความจริงใหม่","advice":"ระบุปัญหาอย่างชัดเจนและใช้ความชัดเจนเพื่อการตัดสินใจอย่างเป็นธรรม","yesNoMeaning":"เอซของดาบโน้มเอียงไปใช่: ระบุปัญหาอย่างชัดเจนและใช้ความชัดเจนในการตัดสินใจอย่างเป็นธรรม"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-swords', 'th', '{"name":"สองดาบ","meaning":"ความลำเอียงที่ระมัดระวังชะลอการตัดสินใจ ซึ่งไม่สามารถค้างคาไปได้ตลอด","advice":"ค่อยๆ เอาผ้าปิดตาออก รวบรวมข้อเท็จจริงที่ขาดหายไป และตัดสินใจจากความสมดุล","yesNoMeaning":"ไพ่ Two of Swords ยังไม่ชัดเจน: ค่อย ๆ ถอดผ้าปิดตา เก็บข้อเท็จจริงที่ขาดหาย และตัดสินใจจากสมดุล"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-swords', 'th', '{"name":"ไพ่สามดาบ","meaning":"ความจริงที่เจ็บปวด การแยกจาก หรือความผิดหวังต้องการให้รับรู้","advice":"ปล่อยให้ความรู้สึกไหลผ่านตัวคุณและหลีกเลี่ยงการเปลี่ยนความเจ็บปวดให้กลายเป็นเรื่องเล่าที่ถาวร","yesNoMeaning":"ไพ่สามดาบโน้มไปทางไม่: ให้ความรู้สึกผ่านตัวคุณและหลีกเลี่ยงการเปลี่ยนความเจ็บปวดให้เป็นเรื่องราวถาวร"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-swords', 'th', '{"name":"สี่ดาบ","meaning":"ต้องการการพักผ่อนและความสงบทางจิตใจหลังจากความกดดันหรือความขัดแย้ง","advice":"หยุดก่อนตอบ; การฟื้นฟูเป็นสิ่งที่มีประสิทธิภาพเมื่อทำให้ความคิดชัดเจนขึ้น","yesNoMeaning":"ไพดาบสี่ใบเอียงไปไม่: หยุดก่อนตอบ; การฟื้นตัวมีประสิทธิภาพเมื่อมันฟื้นความคิดที่ชัดเจน"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-swords', 'th', '{"name":"ไพ่ห้าอาวุธ","meaning":"ความขัดแย้งอาจนำไปสู่ชัยชนะที่ว่างเปล่าหรือทำให้ความเชื่อถือเสียหาย","advice":"เลือกความมีศักดิ์ศรีมากกว่าการชนะ และละทิ้งกลยุทธ์ที่มีค่าใช้จ่ายสูงเกินไป","yesNoMeaning":"ไพดาบห้าใบเอียงไปไม่: เลือกศักดิ์ศรีเหนือชัยชนะและหลีกเลี่ยงกลยุทธ์ที่มีค่าใช้จ่ายสูงเกินไป"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-swords', 'th', '{"name":"ไพ่หกดาบ","meaning":"การผ่านช่วงที่ยากลำบากค่อย ๆ เคลื่อนเข้าสู่สภาพที่สงบขึ้น","advice":"นำสิ่งที่คุณได้เรียนรู้ ยอมรับการสนับสนุน และเดินหน้าห่างจากความวุ่นวาย","yesNoMeaning":"ไพ่ Six of Swords โน้มไปทางใช่: นำสิ่งที่คุณได้เรียนรู้ รับการสนับสนุน และก้าวต่อไปให้พ้นจากความวุ่นวาย"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-swords', 'th', '{"name":"เจ็ดดาบ","meaning":"กลยุทธ์ ความลับ หรือการหลีกเลี่ยงทำให้เส้นทางซับซ้อนขึ้น","advice":"ทำตัวอย่างฉลาดแต่โปร่งใส ทางลัดที่ทรยศต่อความไว้วางใจจะกลับมาพร้อมปัญหา","yesNoMeaning":"เจ็ดดาบเอียงไปทางไม่: ลงมืออย่างชาญฉลาดแต่โปร่งใส; ทางลัดที่ทรยศต่อความไว้วางใจจะกลับมาสร้างปัญหา"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-swords', 'th', '{"name":"แปดของดาบ","meaning":"ความกลัวและความเชื่อที่จำกัดทำให้ตัวเลือกที่มีอยู่มองเห็นได้ยาก","advice":"ตั้งคำถามต่อความคิดที่บอกว่าคุณติดอยู่และทำการปลดปล่อยเพียงเล็กน้อย","yesNoMeaning":"แปดของดาบเอนโน้ต: ตั้งคำถามกับความคิดที่บอกว่าคุณติดอยู่และทำการกระทำเล็ก ๆ เพื่อปลดปล่อย"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-swords', 'th', '{"name":"เก้าดาบ","meaning":"ความวิตกกังวลทำให้ความอันตรายในความมืดถูกขยายและทำให้จิตใจเหนื่อยล้า","advice":"นำความกลัวออกมาให้สว่างในวัน พยายามหาการสนับสนุน และแยกข้อเท็จจริงออกจากผลลัพธ์ที่จินตนาการ","yesNoMeaning":"เก้าดาบคว่ำไปทางไม่: นำความกลัวออกสู่แสงสว่าง หาแนวทางสนับสนุน และแยกข้อเท็จจริงออกจากผลลัพธ์ที่จินตนาการขึ้น"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-swords', 'th', '{"name":"สิบทวน","meaning":"วัฏจักรที่เจ็บปวดถึงขีดสุดไม่สามารถดำเนินต่อไปโดยไม่เปลี่ยนแปลง","advice":"ยอมรับจุดจบ ปกป้องการฟื้นตัวของคุณ และอนุญาตให้การเริ่มต้นใหม่เกิดขึ้น","yesNoMeaning":"ไพ่สิบดาบโน้มไปทางไม่: ยอมรับการสิ้นสุด ปกป้องการฟื้นตัวของคุณ และเปิดโอกาสให้การเริ่มต้นใหม่เกิดขึ้น"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-swords', 'th', '{"name":"หน้าไพ่ดาบ","meaning":"ความอยากรู้อยากเห็นตื่นตัวแสวงหาข้อเท็จจริง ถามคำถาม และสังเกตการเปลี่ยนแปลง","advice":"ค้นคว้าอย่างรอบคอบและพูดอย่างแม่นยำ แทนที่จะตอบสนองต่อทุกสัญญาณ","yesNoMeaning":"ไพ่เพจดาบยังคงมีเงื่อนไข: ศึกษาอย่างรอบคอบและพูดอย่างแม่นยำ แทนที่จะตอบสนองต่อทุกสัญญาณ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-swords', 'th', '{"name":"อัศวินดาบ","meaning":"สติปัญญาที่มีสมาธิทำงานอย่างรวดเร็วและเผชิญอุปสรรคโดยตรง","advice":"ก้าวไปด้วยความกล้าหาญ แต่ช้าเพียงพอที่จะฟังสิ่งที่ความมั่นใจของคุณอาจพลาด","yesNoMeaning":"อัศวินแห่งดาบยังคงมีเงื่อนไข: ก้าวไปด้วยความกล้า แต่ช้าเพียงพอที่จะได้ยินสิ่งที่ความมั่นใจของคุณอาจพลาด"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-swords', 'th', '{"name":"ราชินีแห่งดาบ","meaning":"การรับรู้ที่ชัดเจนและขอบเขตที่ซื่อสัตย์ช่วยตัดความสับสน","advice":"พูดความจริงด้วยความเมตตาและให้ประสบการณ์ลับคมคุณ ไม่ใช่ทำให้คุณแข็ง","yesNoMeaning":"ราชินีแห่งดาบเอียงไปทางใช่: พูดความจริงด้วยความเมตตาและให้ประสบการณ์ทำให้คุณเฉียบคม แต่ไม่แข็งกระด้าง"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-swords', 'th', '{"name":"ราชาดาบ","meaning":"เหตุผล ความยุติธรรม และการตัดสินอย่างมีวินัยนำทางการตัดสินใจที่สำคัญ","advice":"ใช้หลักฐาน กำหนดมาตรฐาน และควรตัดอคติส่วนตัวออกจากคำตัดสิน","yesNoMeaning":"The King of Swords มีแนวโน้มว่าใช่: ใช้หลักฐาน กำหนดมาตรฐาน และเก็บความลำเอียงส่วนตัวออกจากคำตัดสิน"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-pentacles', 'th', '{"name":"เอซแห่งเหรียญ","meaning":"โอกาสที่จับต้องได้มอบเมล็ดพันธุ์ของความเจริญรุ่งเรือง งาน หรือความเป็นอยู่ที่ดี","advice":"จุดรากโอกาสในแผนปฏิบัติและดูแลมันอย่างสม่ำเสมอ","yesNoMeaning":"เอซของเหรียญโน้มเอียงไปใช่: วางโอกาสบนแผนปฏิบัติและดูแลมันอย่างต่อเนื่อง"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-pentacles', 'th', '{"name":"สองเหรียญ","meaning":"หลายลำดับความสำคัญเคลื่อนไหวพร้อมกันและต้องการการปรับสมดุลอย่างยืดหยุ่น","advice":"ปรับจังหวะ ปกป้องสิ่งสำคัญ และหลีกเลี่ยงการสัญญามากเกินกว่าที่คุณรับไหว","yesNoMeaning":"ไพ่ Two of Pentacles ยังคงแบบมีเงื่อนไข: ปรับจังหวะ ปกป้องสิ่งสำคัญ และหลีกเลี่ยงการสัญญามากเกินกว่าที่คุณจะรับได้"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-pentacles', 'th', '{"name":"ไพ่สามเหรียญ","meaning":"ทักษะเติบโตผ่านการทำงานร่วมกัน, การให้ข้อเสนอแนะ, และความประณีตในการสร้างงาน","advice":"ร่วมแรงร่วมใจ ให้เกียรติเฉพาะด้าน และสร้างไปสู่มาตรฐานร่วม","yesNoMeaning":"ไพ่สามดวงเพนทาเคิลโน้มไปทางใช่: มีส่วนร่วมด้วยความสามารถของคุณ ให้เกียรติผู้เชี่ยวชาญ และสร้างตามมาตรฐานร่วมกัน"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-pentacles', 'th', '{"name":"สี่เหรียญ","meaning":"การยึดมั่นในความมั่นคงมากเกินไปสามารถรักษาทรัพยากร แต่จำกัดการไหลที่ดีต่อสุขภาพ","advice":"ปกป้องสิ่งที่สำคัญโดยไม่ให้ความกลัวเป็นตัวกำหนดทุกการตัดสินใจ","yesNoMeaning":"ไพพิณสี่ใบยังคงมีเงื่อนไข: ปกป้องสิ่งที่สำคัญโดยไม่ให้ความกลัวเป็นตัวกำหนดทุกการตัดสินใจของคุณ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-pentacles', 'th', '{"name":"ไพ่ห้าเหรียญ","meaning":"ความตึงเครียดหรือการถูกกีดกันในเรื่องทรัพย์สินสร้างความกังวลและความรู้สึกขาดแคลน","advice":"ขอความช่วยเหลือในทางปฏิบัติและสังเกตประตูที่ความลำบากทำให้มองข้ามได้ง่าย","yesNoMeaning":"ไพพิณห้าใบเอียงไปไม่: ขอความช่วยเหลือที่เป็นรูปธรรมและสังเกตประตูที่ความยากลำบากทำให้มองข้ามได้ง่าย"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-pentacles', 'th', '{"name":"ไพ่หกเหรียญ","meaning":"ทรัพยากรถูกแลกเปลี่ยน ซึ่งก่อให้เกิดคำถามเกี่ยวกับความใจกว้าง อำนาจ และความยุติธรรม","advice":"ให้หรือรับด้วยเงื่อนไขชัดเจนเพื่อให้การสนับสนุนยังคงรักษาศักดิ์ศรีทั้งสองฝ่าย","yesNoMeaning":"ไพ่ Six of Pentacles โน้มไปทางใช่: ให้หรือรับอย่างมีเงื่อนไขชัดเจนเพื่อให้การสนับสนุนรักษาศักดิ์ศรีของทั้งสองฝ่าย"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-pentacles', 'th', '{"name":"เจ็ดดวงเหรียญ","meaning":"การลงทุนที่อดทนถึงจุดที่ต้องประเมินผลก่อนความพยายามครั้งต่อไป","advice":"ทบทวนสิ่งที่กำลังเติบโต ปรับปรุงวิธีการ และให้เวลาสำหรับผลลัพธ์ที่คุ้มค่า","yesNoMeaning":"เจ็ดเหรียญยังคงเป็นไปตามเงื่อนไข: ตรวจสอบสิ่งที่กำลังเติบโต ปรับปรุงวิธีการ และให้เวลาผลลัพธ์ที่คุ้มค่า"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-pentacles', 'th', '{"name":"แปดของเหรียญ","meaning":"การทำซ้ำอย่างมีสมาธิพัฒนาฝีมือและผลลัพธ์ที่เชื่อถือได้","advice":"ฝึกทักษะที่จำเป็น ยินดีรับการแก้ไข และปล่อยให้คุณภาพสะสม","yesNoMeaning":"แปดของเงินเหรียญเอนโน้ต: ฝึกฝนทักษะที่จำเป็น ยินรับการแก้ไข และปล่อยให้คุณภาพสะสม"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-pentacles', 'th', '{"name":"เก้าเหรียญ","meaning":"การพึ่งพาตนเองและความสะดวกสบายที่ฝึกฝนสะท้อนความก้าวหน้าที่มีวินัย","advice":"สนุกกับสิ่งที่คุณสร้างขึ้นและรักษาอิสระที่เชื่อมโยงกับความกตัญญู","yesNoMeaning":"เก้าเหรียญคว่ำไปทางใช่: เพลิดเพลินกับสิ่งที่คุณสร้างขึ้นและเก็บความเป็นอิสระเชื่อมโยงกับความกตัญญู"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-pentacles', 'th', '{"name":"สิบเหรียญ","meaning":"ความมั่นคงในระยะยาวเติบโตผ่านมรดก ครอบครัว และรากฐานที่ใช้ร่วมกัน","advice":"วางแผนเกินกว่าชัยชนะในทันทีและปกป้องสิ่งที่สามารถสนับสนุนผู้อื่นในระยะยาว","yesNoMeaning":"ไพ่สิบดวงเพนทาเคิลโน้มไปทางใช่: วางแผนเกินกว่าชัยชนะทันทีและปกป้องสิ่งที่สามารถสนับสนุนผู้อื่นในระยะยาว"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-pentacles', 'th', '{"name":"หน้าไพ่เหรียญ","meaning":"ข้อความที่เป็นประโยชน์ชวนให้ศึกษา วางแผน หรือเริ่มโครงการใหม่ที่มีพื้นฐาน","advice":"เรียนรู้พื้นฐาน กำหนดงานต่อไป และพิสูจน์แนวคิดผ่านการทำงานอย่างมั่นคง","yesNoMeaning":"ไพ่เพจเพนตาเคิลมีแนวโน้มไปทางใช่: เรียนรู้พื้นฐาน กำหนดงานต่อไป และพิสูจน์แนวคิดด้วยการทำงานอย่างมั่นคง"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-pentacles', 'th', '{"name":"อัศวินเหรียญ","meaning":"ความพยายามที่เชื่อถือได้ก้าวไปอย่างช้าๆ แต่แทบไม่ทิ้งงาน","advice":"รักษากิจวัตรให้น่าเชื่อถือและสม่ำเสมอ ความก้าวหน้าสำคัญกว่าความตื่นเต้น","yesNoMeaning":"อัศวินแห่งเหรียญคว่ำไปทางใช่: รักษากิจวัตรให้น่าเชื่อถือและสม่ำเสมอ; ความก้าวหน้าสำคัญกว่าความตื่นเต้น"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-pentacles', 'th', '{"name":"ราชินีแห่งเพนทาเคิล","meaning":"ความเอาใจใส่ที่มีไหวพริบสร้างความสบาย สุขภาพ และความอุดมสมบูรณ์ในทางปฏิบัติ","advice":"ดูแลผู้คนและแผนการในวิธีที่ยั่งยืนสำหรับตัวคุณ","yesNoMeaning":"ราชินีแห่งเหรียญเอียงไปทางใช่: ดูแลผู้คนและแผนการในวิธีที่ยั่งยืนสำหรับคุณ"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-pentacles', 'th', '{"name":"ราชาเหรียญ","meaning":"การเป็นผู้นำด้านวัตถุเปลี่ยนประสบการณ์ให้เป็นการดูแลที่มั่นคงและเอื้ออาทร","advice":"ตัดสินใจเลือกเสียงในระยะยาวและใช้ความสำเร็จอย่างรับผิดชอบ","yesNoMeaning":"The King of Pentacles มีแนวโน้มว่าใช่: ทำทางเลือกที่เป็นประโยชน์ในระยะยาวและใช้ความสำเร็จอย่างรับผิดชอบ"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aries', 'th', '{"name":"ราศีเมษ","dateRange":"21 มี.ค. – 19 เม.ย.","rulingPlanet":"ดาวอังคาร","summary":"การเริ่มต้นอย่างกล้าหาญและการลงมือทำโดยตรงเป็นลักษณะของราศีเมษ ซึ่งประกายไฟของพวกเขาเปลี่ยนเจตนาให้กลายเป็นแรงขับเคลื่อน","originStory":"ราศีเมษเกี่ยวข้องกับแกะทองที่ช่วยชีวิตฟริกซัสในตำนานกรีก ขนแกะของมันต่อมากลายเป็นรางวัลของเจสันและผู้เดินทางอาร์โกนอต ซึ่งทำให้เครื่องหมายนี้กลายเป็นสัญลักษณ์ของความกล้า การช่วยเหลือ และก้าวแรกแห่งความกล้า","traits":["กล้าหาญ","มีพลัง","เป็นอิสระ","ตรง"],"strengths":["ความสามารถในการริเริ่ม","ความมั่นใจ","ความยืดหยุ่น"],"challenges":["ความใจร้อน","ความหุนหันพลันแล่น","เริ่มเร็วกว่าที่คุณจะรักษาได้"],"compatibleSigns":["ราศีสิงห์","ราศีธนู","ราศีเมถุน"],"reflectionPrompt":"เลือกการเริ่มต้นที่กล้าหาญเพียงหนึ่งครั้งและให้ความอดทนเพียงพอในการเติบโต"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'day', 'th', '{"overview":"วันนี้เหมาะกับการก้าวไปทีละขั้นที่ชัดเจนและมีจุดประสงค์ ดวงดาวราศีเมษเคลื่อนผ่านพลังงานไฟ การเริ่มต้นอย่างกล้าหาญและการกระทำตรงไปตรงมาคือคุณสมบัติของราศีแกะ ที่เปลวไฟของเขาเปลี่ยนความตั้งใจให้กลายเป็นแรงผลักดัน","love":"ในความรักวันนี้ เลือกการอยู่ร่วมกันมากกว่าการคาดเดา ของขวัญจากความสามารถในการริเริ่ม ความมั่นใจ และความยืดหยุ่นของคุณสามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงออก","career":"ที่ทำงาน จงทำงานที่มีความหมายที่สุดให้เสร็จก่อนที่จะไล่ตามแรงผลักดันใหม่ ใช้ความกล้าหาญ พลังงาน ความเป็นอิสระ และความตรงไปตรงมาเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดพร้อมกัน","finance":"ทำให้การตัดสินใจเกี่ยวกับเงินในวันนี้เรียบง่ายและมีเหตุผล สังเกตเมื่อความใจร้อน ความหุนหันพลันแล่น หรือการเริ่มต้นเร็วกว่าที่สามารถรักษาได้นั้นเริ่มมีอิทธิพลต่อการตัดสินใจที่เป็นประโยชน์","wellbeing":"การหยุดพักเล็กๆ สามารถรีเซ็ตพลังงานของคุณได้ เลือกเริ่มต้นอย่างกล้าหาญสักหนึ่งอย่างและให้ความอดทนเพียงพอแก่การเติบโต","guidance":"ก่อนวันจะหมดไป จงจำไว้: เลือกการเริ่มต้นที่กล้าหาญหนึ่งอย่างและให้ความอดทนเพียงพอเพื่อให้มันเติบโต"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'week', 'th', '{"overview":"สัปดาห์นี้พัฒนาด้วยการตัดสินใจอย่างมั่นคงมากกว่าช่วงเวลาอันน่าตื่นเต้นเพียงครั้งเดียว ราศีเมษเคลื่อนผ่านพลังงานแห่งไฟ การเริ่มต้นที่กล้าหาญและการกระทำโดยตรงเป็นลักษณะของราศีแกะ ซึ่งประกายไฟของมันเปลี่ยนเจตนาให้กลายเป็นแรงขับเคลื่อน","love":"ความสัมพันธ์จะได้ประโยชน์จากบทสนทนาที่เปิดโอกาสทั้งความซื่อสัตย์และความอบอุ่น ของขวัญของคุณในเรื่องความริเริ่ม ความมั่นใจ และความยืดหยุ่น สามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงบทบาท","career":"ความก้าวหน้าทางวิชาชีพที่ดีที่สุดของคุณมาจากการเลือกความสำคัญและปกป้องเวลาให้กับมัน ใช้ความกล้าหาญ มีพลังงาน เป็นอิสระ ตรงไปตรงมาเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดในครั้งเดียว","finance":"ทบทวนลักษณะพฤติกรรมด้านการใช้จ่ายของคุณก่อนที่จะทำการลงทุนหรือผูกมัดในสิ่งที่ใหญ่ขึ้น สังเกตว่าเมื่อความใจร้อน การใจร้อนเกินไป การเริ่มเร็วกว่าที่จะรักษาได้เริ่มมีอิทธิพลต่อการตัดสินใจที่เป็นจริง","wellbeing":"สร้างสมดุลระหว่างการเคลื่อนไหวกับการฟื้นฟูอย่างแท้จริงตลอดทั้งสัปดาห์ เลือกการเริ่มต้นที่กล้าหาญหนึ่งครั้งและให้เวลาเพียงพอแก่มันในการเติบโต","guidance":"ให้คำถามนี้นำทางสัปดาห์: เลือกการเริ่มต้นที่กล้าหาญหนึ่งครั้งและให้ความอดทนเพียงพอเพื่อให้มันเติบโต"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'year', 'th', '{"overview":"ปีนี้เชิญชวนให้เติบโตอย่างอดทนรอบๆ ความเป็นตัวตน จุดประสงค์ และวิธีที่คุณใช้พลังงาน เมษเคลื่อนผ่านพลังงานไฟ การเริ่มต้นอย่างกล้าหาญและการกระทำตรงไปตรงมานิยามแพะผู้พลัดถิ่น ซึ่งประกายของมันเปลี่ยนเจตนาให้กลายเป็นแรงขับเคลื่อน","love":"ความรักจะลึกซึ้งยิ่งขึ้นเมื่อคุณฝึกความสม่ำเสมอและปล่อยให้ความสัมพันธ์พัฒนาไปตามจังหวะของมนุษย์ ของขวัญของคุณในการริเริ่ม ความมั่นใจ และความยืดหยุ่นสามารถช่วยให้คุณเชื่อมต่อได้โดยไม่ต้องแสดงออก","career":"งานระยะยาวจะเข้มแข็งขึ้นเมื่อความทะเยอทะยานมาคู่กับโครงสร้างที่คุณสามารถรักษาได้ ใช้ความกล้าหาญ มีพลัง เป็นอิสระ และตรงไปตรงมาเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดในครั้งเดียว","finance":"สร้างความมั่นใจทางการเงินผ่านนิสัยที่ทำซ้ำได้ แทนการทำนายที่สมบูรณ์แบบ สังเกตเมื่อความใจร้อน ความหุนหันพลันแล่น การเริ่มต้นเร็วกว่าที่สามารถรักษาได้เริ่มส่งผลต่อการตัดสินใจที่เป็นจริง","wellbeing":"ให้ความเป็นอยู่ที่ดีเป็นรากฐานของชีวิตที่คุณกำลังก่อสร้าง ไม่ใช่รางวัลหลังจากที่เสร็จสิ้นแล้ว เลือกการเริ่มต้นที่กล้าหาญหนึ่งครั้งและให้ความอดทนเพียงพอเพื่อให้มันเติบโต","guidance":"กลับมาหาเข็มทิศนี้ตลอดทั้งปี: เลือกการเริ่มต้นที่กล้าหาญหนึ่งครั้งและให้ความอดทนเพียงพอเพื่อให้มันเติบโต"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('taurus', 'th', '{"name":"ราศีพฤษภ","dateRange":"20 เม.ย. – 20 พ.ค.","rulingPlanet":"ดาวศุกร์","summary":"มั่นคง เย้ายวน และรากฐานมั่นคง วัวกระทิงสร้างคุณค่าที่ยั่งยืนผ่านความอดทนและการดูแล","originStory":"ราศีพฤษภระลึกถึงเทพซูสที่ปรากฏในรูปกระทิงขาวงดงามเพื่อนำยูโรปาข้ามทะเล ภาพนี้เกี่ยวข้องกับความงาม ความอุดมสมบูรณ์ ความมั่งคั่งในโลกวัตถุ และพลังที่แสดงออกผ่านความอดทนสงบ","traits":["มีรากฐาน","จงรักภักดี","อดทน","เรื่องกามารมณ์"],"strengths":["ความน่าเชื่อถือ","ปัญญาเชิงปฏิบัติ","ความศรัทธา"],"challenges":["ความดื้อรั้น","ความต้านทานการเปลี่ยนแปลง","การยึดถือเกินไป"],"compatibleSigns":["ราศีกันย์","มังกร","โรคมะเร็ง"],"reflectionPrompt":"ปกป้องสิ่งที่สำคัญโดยไม่ผิดพลาดคิดว่าสะดวกสบายคือความถาวร"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'day', 'th', '{"overview":"วันนี้เอื้อต่อการก้าวเดินที่ชัดเจนและมีเจตนา ราศีพฤษภเคลื่อนผ่านพลังแห่งธาตุดิน มั่นคง อารมณ์สัมผัส และมีรากฐานที่มั่นคง วัวสร้างคุณค่าที่ยั่งยืนผ่านความอดทนและการเอาใจใส่","love":"ในเรื่องความรักวันนี้ เลือกที่จะอยู่กับปัจจุบันมากกว่าการคาดเดา ของขวัญของคุณที่มีความน่าเชื่อถือ ปัญญาที่ใช้ได้จริง ความทุ่มเท สามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงออก","career":"ที่ทำงาน ทำงานที่มีความหมายที่สุดให้เสร็จก่อนที่จะไล่ตามแรงผลักดันใหม่ ใช้ความมั่นคง ความจงรัก ความอดทน และความรู้สึกเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดในครั้งเดียว","finance":"รักษาการเลือกเรื่องเงินในวันนี้ให้เรียบง่ายและมีเหตุผล สังเกตเมื่อความดื้อรั้น การต่อต้านการเปลี่ยนแปลง การยึดมั่นเกินไปเริ่มมีอิทธิพลต่อการตัดสินใจอย่างเป็นจริง","wellbeing":"การหยุดพักเล็ก ๆ สามารถรีเซ็ตพลังงานของคุณได้ ปกป้องสิ่งที่สำคัญโดยไม่เข้าใจผิดว่าความสบายคือความถาวร","guidance":"ก่อนที่วันจะสิ้นสุด จำไว้ว่า: ปกป้องสิ่งที่สำคัญโดยไม่สับสนระหว่างความสะดวกสบายกับความยั่งยืน"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'week', 'th', '{"overview":"สัปดาห์นี้พัฒนาผ่านทางการเลือกอย่างมั่นคง มากกว่าช่วงเวลาที่น่าตื่นเต้นครั้งเดียว ราศีพฤษภเคลื่อนผ่านพลังงานแห่งดิน มั่นคง มีความสุขทางประสาทสัมผัส และมีรากฐานที่มั่นคง วัวสร้างคุณค่าที่ยั่งยืนด้วยความอดทนและเอาใจใส่","love":"ความสัมพันธ์ได้รับประโยชน์จากการสนทนาที่เปิดโอกาสทั้งความซื่อสัตย์และความอบอุ่น ของขวัญของคุณในการไว้วางใจ ความฉลาดเชิงปฏิบัติ ความทุ่มเทสามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงตัว","career":"ความก้าวหน้าทางวิชาชีพที่ดีที่สุดของคุณมาจากการเลือกความสำคัญและปกป้องเวลาให้กับมัน ใช้ความมีเหตุผล ภักดี อดทน และมีสัมผัสทางประสาทสัมผัสเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดในครั้งเดียว","finance":"ทบทวนรูปแบบการใช้จ่ายของคุณก่อนที่จะตัดสินใจลงทุนใหญ่ สังเกตว่าเมื่อไหร่ที่ความดื้อรั้น การต่อต้านการเปลี่ยนแปลง หรือการยึดถือสิ่งใดนานเกินไปเริ่มมีผลต่อการตัดสินใจเชิงปฏิบัติ","wellbeing":"สมดุลการเคลื่อนไหวด้วยการฟื้นฟูอย่างแท้จริงตลอดสัปดาห์ ปกป้องสิ่งที่สำคัญโดยไม่เข้าใจผิดว่าความสบายคือความถาวร","guidance":"ให้คำถามนี้เป็นแนวทางของสัปดาห์: ปกป้องสิ่งที่สำคัญโดยไม่เข้าใจผิดว่าสบายคือความถาวร"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'year', 'th', '{"overview":"ปีนี้เชิญชวนให้เติบโตอย่างอดทนรอบ ๆ ตัวตน วัตถุประสงค์ และวิธีการใช้พลังงานของคุณ ราศีพฤษภเคลื่อนผ่านพลังของโลก มั่นคง มีสัมผัสทางร่างกาย และตั้งอยู่บนความจริง วัวสร้างคุณค่าที่ยั่งยืนผ่านความอดทนและการดูแล","love":"ความรักลึกซึ้งขึ้นเมื่อคุณฝึกฝนความสม่ำเสมอและปล่อยให้ความสัมพันธ์พัฒนาตามจังหวะของมนุษย์ ของขวัญของคุณด้านความน่าเชื่อถือ ปัญญาเชิงปฏิบัติ และความทุ่มเทสามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงออก","career":"งานระยะยาวจะเข้มแข็งขึ้นเมื่อความทะเยอทะยานมาคู่กับโครงสร้างที่คุณสามารถรักษาได้ ใช้ความเป็นจริง ความจงรักภักดี ความอดทน และความรู้สึกทางประสาทสัมผัสเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องตอบสนองทั้งหมดในคราวเดียว","finance":"สร้างความมั่นใจทางการเงินผ่านนิสัยที่สามารถทำซ้ำได้แทนการพยากรณ์ที่สมบูรณ์แบบ สังเกตเมื่อความดื้อรั้น ความต้านทานต่อการเปลี่ยนแปลง หรือการยึดมั่นนานเกินไปเริ่มมีอิทธิพลต่อการตัดสินใจเชิงปฏิบัติ","wellbeing":"ถือความสุขเป็นรากฐานของชีวิตที่คุณกำลังก่อสร้าง ไม่ใช่รางวัลหลังจากทำสำเร็จ ปกป้องสิ่งที่สำคัญโดยไม่เข้าใจผิดว่า ความสะดวกสบายคือความคงทน","guidance":"กลับมาหาเข็มทิศนี้ตลอดทั้งปี: ปกป้องสิ่งที่สำคัญโดยไม่สับสนความสบายกับความถาวร"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('gemini', 'th', '{"name":"ราศีเมถุน","dateRange":"21 พฤษภาคม – 20 มิถุนายน","rulingPlanet":"พุธ","summary":"ความอยากรู้อยากเห็นและการเชื่อมโยงนำทางฝาแฝด ผู้ซึ่งรวบรวมความคิดและเผยให้เห็นมากกว่าหนึ่งด้านของเรื่องราว","originStory":"ราศีเมถุนแทนคาสเตอร์และพอลลักซ์ ฝาแฝดที่แยกกันไม่ได้ ซึ่งแบ่งปันความเป็นอมตะแทนที่จะอยู่ห่างกัน กลุ่มดาวของพวกเขามีธีมเกี่ยวกับมิตรภาพ มุมมองสองด้าน การสื่อสาร และการเคลื่อนย้ายระหว่างโลก","traits":["อยากรู้อยากเห็น","ปรับตัวได้","ช่างแสดงออก","ไวปัญญา"],"strengths":["การสื่อสาร","ความหลากหลาย","การเรียนรู้อย่างรวดเร็ว"],"challenges":["ความกระสับกระส่าย","สมาธิที่กระจาย","คิดมากเกินไป"],"compatibleSigns":["ราศีตุลย์","ราศีกุมภ์","ราศีเมษ"],"reflectionPrompt":"ปล่อยให้ความอยากรู้อยากเห็นเปิดประตู แล้วอยู่ต่อให้นานพอที่จะเข้าใจสิ่งที่คุณพบ"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'day', 'th', '{"overview":"วันนี้เป็นวันที่เลือกก้าวที่ชัดเจนและมีเจตนาราศีเมถุนเคลื่อนที่ผ่านพลังงานอากาศความอยากรู้อยากเห็นและการเชื่อมโยงนําทางฝาแฝด ซึ่งรวบรวมไอเดียและเปิดเผยเรื่องราวมากกว่าหนึ่งด้าน","love":"ในเรื่องความรักวันนี้ เลือกการอยู่ร่วมกันมากกว่าการสมมุติของใจ ของขวัญของคุณด้านการสื่อสาร ความหลากหลาย และการเรียนรู้ได้อย่างรวดเร็วสามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดง","career":"ในการทำงาน ให้ทำงานที่มีความหมายที่สุดให้เสร็จก่อนที่จะไล่ตามแรงขับเคลื่อนใหม่ ใช้ความอยากรู้อยากเห็น ความสามารถปรับตัว การแสดงออก และไหวพริบเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดในครั้งเดียว","finance":"รักษาการเลือกใช้จ่ายเงินในวันนี้ให้ง่ายและมีเหตุผล สังเกตเมื่อความกระสับกระส่าย สมาธิกระจัดกระจาย การคิดมากเกินไปเริ่มกระทบต่อการตัดสินใจที่เป็นจริง","wellbeing":"การหยุดพักเล็กๆ สามารถรีเซ็ตพลังงานของคุณได้ ให้ความอยากรู้อยากเห็นเปิดประตู แล้วอยู่ต่อให้นานพอที่จะเข้าใจสิ่งที่คุณพบ","guidance":"ก่อนที่วันจะสิ้นสุด จำไว้ว่า: ให้ความอยากรู้อยากเห็นเปิดประตู จากนั้นอยู่ต่อให้นานพอที่จะเข้าใจสิ่งที่คุณพบ"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'week', 'th', '{"overview":"สัปดาห์นี้พัฒนาไปด้วยการเลือกที่มั่นคงมากกว่าช่วงเวลาที่ตื่นเต้นเพียงครั้งเดียว ราศีเมถุนเคลื่อนผ่านพลังงานธาตุลม ความอยากรู้อยากเห็นและการเชื่อมโยงเป็นแนวทางให้ฝาแฝดซึ่งรวบรวมแนวคิดและเผยมากกว่าหนึ่งด้านของเรื่องราว","love":"ความสัมพันธ์จะได้ประโยชน์จากบทสนทนาที่เปิดโอกาสทั้งความซื่อสัตย์และความอบอุ่น ของขวัญด้านการสื่อสาร ความสามารถปรับตัวได้ เรียนรู้เร็วของคุณ สามารถช่วยให้คุณสร้างความสัมพันธ์ได้โดยไม่ต้องแสร้งทำ","career":"ความก้าวหน้าทางวิชาชีพที่ดีที่สุดของคุณมาจากการเลือกความสำคัญและปกป้องเวลาให้กับมัน ใช้ความอยากรู้อยากเห็น ปรับตัวได้ แสดงออกชัดเจน มีไหวพริบเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดในครั้งเดียว","finance":"ตรวจสอบรูปแบบการใช้จ่ายของคุณก่อนที่จะทำข้อผูกมัดที่ใหญ่ขึ้น สังเกตว่าเมื่อไหร่ความกระสับกระส่าย ความสนใจที่กระจัดกระจาย หรือการคิดมากเริ่มมีอิทธิพลต่อการตัดสินใจที่เป็นไปตามเหตุผล","wellbeing":"สร้างสมดุลระหว่างการเคลื่อนไหวกับการฟื้นฟูอย่างแท้จริงตลอดทั้งสัปดาห์ ให้ความอยากรู้อยากเห็นเปิดประตู จากนั้นอยู่ต่อให้นานพอที่จะเข้าใจสิ่งที่คุณพบ","guidance":"ให้คำถามนี้นำทางสัปดาห์: ให้ความอยากรู้อยากเห็นเปิดประตู จากนั้นอยู่พอที่จะเข้าใจสิ่งที่คุณพบ"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'year', 'th', '{"overview":"ปีนี้เชิญชวนให้เติบโตอย่างอดทนรอบ ๆ ตัวตน จุดมุ่งหมาย และวิธีการใช้พลังงานของคุณ ราศีเมถุนเคลื่อนไหวผ่านพลังงานแห่งอากาศ ความอยากรู้และการเชื่อมโยงชี้นำคู่แฝด ซึ่งรวบรวมแนวคิดและเผยมากกว่าหนึ่งด้านของเรื่องราว","love":"ความรักลึกซึ้งขึ้นเมื่อตอนที่คุณฝึกความสม่ำเสมอและให้ความสัมพันธ์เติบโตตามจังหวะของมนุษย์ ของขวัญของคุณในการสื่อสาร ความยืดหยุ่น การเรียนรู้ได้รวดเร็วสามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดง","career":"งานระยะยาวจะเข้มแข็งขึ้นเมื่อความมุ่งมั่นถูกจับคู่กับโครงสร้างที่คุณสามารถรักษาได้ ใช้ความอยากรู้อยากเห็น ความสามารถในการปรับตัว การสื่อสาร และไหวพริบเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดในคราวเดียว","finance":"สร้างความมั่นใจทางการเงินผ่านนิสัยที่สามารถทำซ้ำได้ แทนที่จะมุ่งหวังการทำนายที่สมบูรณ์ สังเกตเมื่อความกระสับกระส่าย สมาธิกระจัดกระจาย และการคิดมากเริ่มมีอิทธิพลต่อการตัดสินใจเชิงปฏิบัติ","wellbeing":"ให้ความเป็นอยู่ที่ดีเป็นรากฐานของชีวิตที่คุณกำลังก่อสร้าง ไม่ใช่รางวัลหลังจากที่เสร็จสิ้นแล้ว ให้ความอยากรู้อยากเห็นเป็นประตู เปิดมันแล้วอยู่พอที่จะเข้าใจสิ่งที่คุณค้นพบ","guidance":"กลับมาหาเข็มทิศนี้ตลอดทั้งปี: ให้ความอยากรู้อยากเห็นเปิดประตู แล้วอยู่ต่อให้นานพอที่จะเข้าใจสิ่งที่คุณค้นพบ"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('cancer', 'th', '{"name":"โรคมะเร็ง","dateRange":"21 มิ.ย. – 22 ก.ค.","rulingPlanet":"พระจันทร์","summary":"ปกป้องและมีสัญชาตญาณ ราศีปูสร้างความเป็นส่วนหนึ่งด้วยการเคารพความทรงจำ ความรู้สึก และบ้าน","originStory":"โรคมะเร็งเกี่ยวข้องกับปูคาร์คิโนส ซึ่งถูกวางอยู่ในหมู่ดาวหลังจากแสดงความจงรักภักดีระหว่างการต่อสู้ของเฮอร์คิวลีสกับไฮดรา เปลือกของมันและการปกครองโดยดวงจันทร์สะท้อนถึงการปกป้อง ความอ่อนไหวทางอารมณ์ และความทุ่มเทต่อวงในของตน","traits":["สัญชาตญาณ","ความเอาใจใส่","ป้องกัน","มีจินตนาการ"],"strengths":["ความเห็นอกเห็นใจ","ความจงรักภักดี","ความเข้าใจทางอารมณ์"],"challenges":["อารมณ์แปรปรวน","ถอยกลับไปอยู่เบื้องหลังการป้องกัน","เอาเรื่องราวมาเป็นเรื่องส่วนตัว"],"compatibleSigns":["ราศีพิจิก","ราศีมีน","ราศีพฤษภ"],"reflectionPrompt":"ดูแลโลกภายในของคุณในขณะที่เปิดประตูสู่การเชื่อมต่ออย่างจริงใจ"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'day', 'th', '{"overview":"วันนี้เหมาะกับการก้าวไปทีละขั้นที่ชัดเจนและมีจุดประสงค์ ดวงดาวราศีกรกฎเคลื่อนผ่านพลังงานน้ำ มีลักษณะปกป้องและมีสัญชาตญาณ กุ้งล็อบสเตอร์สร้างความเป็นเจ้าของโดยการให้เกียรติความทรงจำ ความรู้สึก และบ้าน","love":"ในความรักวันนี้ เลือกการมีอยู่มากกว่าการคาดเดา ของขวัญของคุณอย่างความเห็นอกเห็นใจ ความจงรักภักดี และความเข้าใจด้านอารมณ์สามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงออก","career":"ที่ทำงาน จงทำงานที่มีความหมายที่สุดให้เสร็จก่อนที่จะไล่ตามแรงผลักดันใหม่ ใช้สัญชาตญาณ ความเอาใจใส่ การปกป้อง และจินตนาการเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดในครั้งเดียว","finance":"รักษาการเลือกใช้จ่ายเงินในวันนี้ให้ง่ายและมีเหตุผล สังเกตเมื่ออารมณ์ไม่ดี การถอยหลังหลังกำแพงป้องกันตัวเอง การเอาเรื่องส่วนตัวมานำร่องเริ่มกระทบต่อการตัดสินใจที่เป็นจริง","wellbeing":"การหยุดพักเล็กๆ สามารถรีเซ็ตพลังงานของคุณได้ ดูแลโลกภายในของคุณในขณะที่เปิดประตูสู่การเชื่อมต่ออย่างซื่อสัตย์","guidance":"ก่อนวันจะหมดไป จงจำไว้: ดูแลโลกภายในของคุณในขณะเดียวกันก็เปิดประตูให้กับการเชื่อมต่ออย่างซื่อสัตย์"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'week', 'th', '{"overview":"สัปดาห์นี้พัฒนาด้วยการตัดสินใจอย่างมั่นคงมากกว่าช่วงเวลาอันน่าตื่นเต้นเพียงครั้งเดียว ราศีกรกฎเคลื่อนผ่านพลังงานแห่งน้ำ ปกป้องและมีสัญชาตญาณสูง ปูสร้างความรู้สึกเป็นส่วนหนึ่งโดยการให้เกียรติความทรงจำ ความรู้สึก และบ้าน","love":"ความสัมพันธ์จะได้ประโยชน์จากบทสนทนาที่เปิดโอกาสทั้งความซื่อสัตย์และความอบอุ่น ของขวัญด้านความเห็นอกเห็นใจ ความจงรักภักดี และสติปัญญาทางอารมณ์ของคุณ สามารถช่วยให้คุณสร้างความสัมพันธ์ได้โดยไม่ต้องแสร้งทำ","career":"ความก้าวหน้าทางวิชาชีพที่ดีที่สุดของคุณมาจากการเลือกความสำคัญและปกป้องเวลาให้กับมัน ใช้สัญชาตญาณ ความเอาใจใส่ การปกป้อง และจินตนาการเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดในครั้งเดียว","finance":"ทบทวนรูปแบบการใช้จ่ายของคุณก่อนที่จะตัดสินใจใช้จ่ายมากขึ้น สังเกตว่าเมื่อใดที่อารมณ์แปรปรวน การถอยกลับไปอยู่หลังเกราะป้องกัน หรือการเอาเรื่องส่วนตัวมาพิจารณาเริ่มมีผลต่อการตัดสินใจที่เป็นประโยชน์","wellbeing":"สร้างสมดุลระหว่างการเคลื่อนไหวกับการฟื้นฟูอย่างแท้จริงตลอดทั้งสัปดาห์ ดูแลโลกภายในของคุณในขณะที่เปิดประตูให้กับการเชื่อมต่อที่ซื่อสัตย์","guidance":"ให้คำถามนี้นำทางสัปดาห์: ดูแลโลกภายในของคุณในขณะที่เปิดประตูไว้สำหรับการเชื่อมต่ออย่างจริงใจ"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'year', 'th', '{"overview":"ปีนี้เชิญชวนให้เติบโตอย่างอดทนรอบๆ ความเป็นตัวตน จุดประสงค์ และวิธีที่คุณใช้พลังงาน ราศีกรกฎเคลื่อนผ่านพลังงานน้ำ ปกป้องและมีสัญชาตญาณ ปูสร้างความเป็นเจ้าของโดยการเคารพความทรงจำ ความรู้สึก และบ้าน","love":"ความรักจะลึกซึ้งยิ่งขึ้นเมื่อคุณฝึกความสม่ำเสมอและปล่อยให้ความสัมพันธ์พัฒนาไปตามจังหวะของมนุษย์ ของขวัญของคุณในการมีความเห็นอกเห็นใจ ความจงรักภักดี และสติปัญญาทางอารมณ์สามารถช่วยให้คุณเชื่อมต่อได้โดยไม่ต้องแสดงออก","career":"งานระยะยาวจะเข้มแข็งขึ้นเมื่อความทะเยอทะยานมาคู่กับโครงสร้างที่คุณสามารถรักษาได้ ใช้ความเข้าใจ ความเอาใจใส่ การปกป้อง และจินตนาการเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องตอบสนองทั้งหมดในคราวเดียว","finance":"สร้างความมั่นใจทางการเงินผ่านนิสัยที่ทำซ้ำได้ แทนการทำนายที่สมบูรณ์แบบ สังเกตเมื่ออารมณ์แปรปรวน การถอยหลังเข้าเกราะ การรับเรื่องต่างๆ แบบส่วนตัวเริ่มส่งผลต่อการตัดสินใจที่เป็นจริง","wellbeing":"ปฏิบัติต่อความเป็นอยู่ที่ดีเป็นรากฐานสำหรับชีวิตที่คุณกำลังสร้าง ไม่ใช่รางวัลหลังจากทำมันเสร็จ ดูแลโลกภายในของคุณในขณะที่เปิดประตูไว้สำหรับการเชื่อมต่ออย่างจริงใจ","guidance":"กลับมาหาเข็มทิศนี้ตลอดทั้งปี: ดูแลโลกภายในของคุณในขณะเดียวกันก็เปิดประตูให้การเชื่อมต่ออย่างจริงใจ"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('leo', 'th', '{"name":"ราศีสิงห์","dateRange":"23 ก.ค. – 22 ส.ค.","rulingPlanet":"ดวงอาทิตย์","summary":"ความอบอุ่น ความคิดสร้างสรรค์ และการแสดงออกอย่างใจกว้างทำให้ราศีสิงห์เป็นแหล่งแสงตามธรรมชาติ","originStory":"ราศีสิงห์เกี่ยวข้องกับสิงโตเนเมียน สิ่งมีชีวิตที่เกือบจะไร้พ่ายซึ่งถูกเอาชนะในงานแรกของเฮรากลิสด์ หลังจากถูกยกขึ้นสู่สวรรค์ มันกลายเป็นสัญลักษณ์ของความกล้าหาญ การปรากฏตัวเป็นผู้ปกครอง และพลังสร้างสรรค์ของดวงอาทิตย์","traits":["อบอุ่น","สร้างสรรค์","ใจกว้าง","มั่นใจ"],"strengths":["ความเป็นผู้นำ","ความจงรักภักดี","การแสดงออกอย่างจริงใจจากใจ"],"challenges":["ความภาคภูมิใจ","ต้องการการยอมรับ","การนําเสนอความล้มเหลว"],"compatibleSigns":["ราศีเมษ","ราศีธนู","ราศีตุลย์"],"reflectionPrompt":"แบ่งปันแสงของคุณอย่างเอื้อเฟื้อและให้ผู้อื่นส่องสว่างข้างคุณ"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'day', 'th', '{"overview":"วันนี้เป็นวันที่เน้นย้ําก้าวแรกที่ชัดเจนและมีเจตนาราศีสิงห์เคลื่อนที่ผ่านพลังงานไฟความอบอุ่น ความคิดสร้างสรรค์ และการแสดงออกอย่างเอื้อเฟื้อทําให้สิงโตเป็นแหล่งแสงธรรมชาติ","love":"ในเรื่องความรักวันนี้ เลือกที่จะอยู่กับปัจจุบันมากกว่าการสมมติ ความสามารถของคุณด้านความเป็นผู้นำ ความจงรักภักดี และการแสดงออกด้วยหัวใจสามารถช่วยให้คุณเชื่อมต่อกับผู้อื่นโดยไม่ต้องแสร้งทำ","career":"ที่ทํางาน ให้ทํางานที่มีความหมายที่สุดให้เสร็จก่อนจะตามหาแรงผลักดันใหม่ใช้ความอบอุ่น สร้างสรรค์ ใจกว้าง และมั่นใจเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่ต้องทําให้สําเร็จทั้งหมดในคราวเดียว","finance":"รักษาการเลือกใช้จ่ายเงินในวันนี้ให้ง่ายและมีเหตุผล สังเกตเมื่อความภาคภูมิใจ ความต้องการการยอมรับ การทำให้ความล้มเหลวดูรุนแรงเริ่มกระทบต่อการตัดสินใจที่เป็นจริง","wellbeing":"การหยุดพักเล็ก ๆ สามารถรีเซ็ตพลังงานของคุณได้ แบ่งปันแสงสว่างของคุณอย่างใจกว้างและให้คนอื่นเปล่งประกายอยู่ข้างคุณ","guidance":"ก่อนที่วันจะสิ้นสุด จำไว้ว่า: แบ่งปันแสงสว่างของคุณอย่างใจกว้างและปล่อยให้ผู้อื่นส่องประกายเคียงข้างคุณ"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'week', 'th', '{"overview":"สัปดาห์นี้พัฒนาไปด้วยการเลือกที่มั่นคงมากกว่าช่วงเวลาที่ตื่นเต้นเพียงครั้งเดียว ราศีสิงห์เคลื่อนผ่านพลังงานธาตุไฟ ความอบอุ่น ความคิดสร้างสรรค์ และการแสดงออกอย่างใจกว้างทำให้สิงห์เป็นแหล่งแสงตามธรรมชาติ","love":"ความสัมพันธ์จะได้ประโยชน์จากบทสนทนาที่เปิดโอกาสทั้งความซื่อสัตย์และความอบอุ่น ของขวัญของคุณในเรื่องความเป็นผู้นำ ความจงรักภักดี และการแสดงออกด้วยหัวใจ สามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงบทบาท","career":"ความก้าวหน้าที่ดีที่สุดในอาชีพของคุณมาจากการเลือกความสำคัญและปกป้องเวลาเพื่อมัน ใช้ความอบอุ่น, สร้างสรรค์, ใจกว้าง, มั่นใจเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องตอบสนองทั้งหมดในคราวเดียว","finance":"ตรวจสอบรูปแบบเบื้องหลังการใช้จ่ายของคุณก่อนที่จะตัดสินใจลงทุนใหญ่ สังเกตว่าเมื่อไหร่ที่ความภูมิใจ ความต้องการการยอมรับ หรือการทำให้ความล้มเหลวดูรุนแรงเริ่มมีอิทธิพลต่อการตัดสินใจที่เป็นไปตามเหตุผล","wellbeing":"สมดุลการเคลื่อนไหวด้วยการฟื้นฟูอย่างแท้จริงตลอดสัปดาห์ แบ่งปันความสว่างของคุณอย่างใจกว้างและให้ผู้อื่นเปล่งประกายเคียงข้างคุณ","guidance":"ให้คำถามนี้เป็นแนวทางของสัปดาห์: แบ่งปันแสงสว่างของคุณอย่างใจกว้างและให้คนอื่นเปล่งประกายเคียงข้างคุณ"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'year', 'th', '{"overview":"ปีนี้เชิญชวนให้เติบโตอย่างอดทนรอบ ๆ ตัวตน จุดมุ่งหมาย และวิธีการใช้พลังงานของคุณ ราศีสิงห์เคลื่อนไหวผ่านพลังงานแห่งไฟ ความอบอุ่น ความคิดสร้างสรรค์ และการแสดงออกอย่างเอื้อเฟื้อช่วยให้สิงโตเป็นแหล่งแสงตามธรรมชาติ","love":"ความรักลึกซึ้งขึ้นเมื่อคุณฝึกฝนความสม่ำเสมอและปล่อยให้ความสัมพันธ์พัฒนาตามจังหวะของมนุษย์ ของขวัญของคุณด้านความเป็นผู้นำ ความจงรักภักดี และการแสดงออกอย่างจริงใจสามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงออก","career":"งานระยะยาวจะเข้มแข็งขึ้นเมื่อความทะเยอทะยานมาคู่กับโครงสร้างที่คุณสามารถรักษาได้ ใช้ความอบอุ่น ความสร้างสรรค์ ความเอื้อเฟื้อ และความมั่นใจเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องตอบสนองทั้งหมดในครั้งเดียว","finance":"สร้างความมั่นใจทางการเงินผ่านนิสัยที่ทำซ้ำได้ แทนการทำนายที่สมบูรณ์แบบ สังเกตเมื่อความภาคภูมิใจ ความต้องการการยอมรับ หรือการขยายความล้มเหลวเริ่มมีอิทธิพลต่อการตัดสินใจที่เป็นจริง","wellbeing":"ถือความสุขเป็นรากฐานของชีวิตที่คุณกำลังก่อสร้าง ไม่ใช่รางวัลหลังจากทำสำเร็จ แบ่งปันแสงสว่างของคุณอย่างใจกว้างและให้ผู้อื่นเปล่งประกายเคียงข้างคุณ","guidance":"กลับมาหาเข็มทิศนี้ตลอดทั้งปี: แบ่งปันแสงของคุณอย่างใจกว้างและปล่อยให้คนอื่นเปล่งประกายข้างคุณ"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('virgo', 'th', '{"name":"ราศีกันย์","dateRange":"23 ส.ค. – 22 ก.ย.","rulingPlanet":"พุธ","summary":"การแยกแยะและการรับใช้นําทางหญิงสาว เปลี่ยนการสังเกตอย่างรอบคอบให้กลายเป็นการปรับปรุงที่เป็นรูปธรรม","originStory":"ราศีกันย์มักเชื่อมโยงกับแอสทรีอา หญิงสาวแห่งความยุติธรรมที่อยู่กับมนุษยชาติหลังจากที่เทพเจ้าอื่นถอนตัว ข้าวสาลีที่เธอถือเชื่อมโยงราศีกับการเก็บเกี่ยว ความสามารถ ความบริสุทธิ์ของเจตนา และการดูแลสิ่งที่คงชีวิตไว้","traits":["รอบคอบ","ใช้ได้จริง","รอบคอบ","แม่นยำ"],"strengths":["การวิเคราะห์","งานฝีมือ","การบริการที่เป็นประโยชน์"],"challenges":["ความสมบูรณ์แบบ","การวิจารณ์ตนเอง","กังวลเกี่ยวกับรายละเอียด"],"compatibleSigns":["ราศีพฤษภ","มังกร","โรคมะเร็ง"],"reflectionPrompt":"ปรับปรุงสิ่งที่คุณทำได้ และปล่อยให้งานที่ดีสมบูรณ์ก่อนที่มันจะสมบูรณ์แบบ"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'day', 'th', '{"overview":"วันนี้เอื้อต่อการก้าวเดินที่ชัดเจนและมีเจตนา ราศีกันย์เคลื่อนผ่านพลังแห่งธาตุดิน การวินิจฉัยและการบริการนำทางหญิงสาว เปลี่ยนการสังเกตอย่างรอบคอบให้เป็นการปรับปรุงที่เป็นประโยชน์","love":"ในเรื่องความรักวันนี้ เลือกการอยู่ร่วมกันมากกว่าการสมมุติของใจ ของขวัญของคุณด้านการวิเคราะห์ ความชำนาญ และการบริการช่วยเหลือสามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดง","career":"ในการทำงาน จงทำงานที่มีความหมายที่สุดให้เสร็จก่อนที่จะไล่ตามแรงขับเคลื่อนใหม่ ใช้ความสังเกต เป็นประโยชน์ ใช้ความคิดรอบคอบ และแม่นยำเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดในคราวเดียว","finance":"รักษาการเลือกใช้จ่ายเงินในวันนี้ให้ง่ายและมีเหตุผล สังเกตเมื่อความเพอร์เฟ็กชันนิสม์ การวิจารณ์ตนเอง ความกังวลเรื่องรายละเอียดเริ่มกระทบต่อการตัดสินใจที่เป็นจริง","wellbeing":"การหยุดพักเล็กๆ สามารถรีเซ็ตพลังงานของคุณได้ พัฒนาสิ่งที่คุณทำได้ และยอมให้งานที่ดีสมบูรณ์ก่อนที่จะสมบูรณ์แบบจริงๆ","guidance":"ก่อนวันจะหมดไป จงจำไว้: ปรับปรุงสิ่งที่คุณทำได้ และอนุญาตให้งานดีเสร็จสมบูรณ์ก่อนที่จะสมบูรณ์แบบ"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'week', 'th', '{"overview":"สัปดาห์นี้พัฒนาผ่านทางการเลือกอย่างมั่นคง มากกว่าช่วงเวลาที่น่าตื่นเต้นครั้งเดียว ราศีกันย์เคลื่อนผ่านพลังงานแห่งดิน การใช้สติและการให้บริการชี้นำหญิงสาวพรหมจรรย์ เปลี่ยนการสังเกตอย่างรอบคอบให้เป็นการปรับปรุงเชิงปฏิบัติได้","love":"ความสัมพันธ์ได้รับประโยชน์จากการสนทนาที่เปิดทางให้ความซื่อสัตย์และอบอุ่นของแต่ละฝ่ายของคุณ ของขวัญในการวิเคราะห์ งานฝีมือ การให้บริการที่เป็นประโยชน์สามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงออก","career":"ความก้าวหน้าทางวิชาชีพที่ดีที่สุดของคุณมาจากการเลือกความสำคัญและปกป้องเวลาให้กับมัน ใช้การสังเกต ความเป็นจริง การใคร่ครวญ และความแม่นยำเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดในครั้งเดียว","finance":"ทบทวนรูปแบบการใช้จ่ายของคุณก่อนที่จะตัดสินใจลงทุนใหญ่ สังเกตว่าเมื่อไหร่ที่ความสมบูรณ์แบบ การวิจารณ์ตัวเอง หรือความกังวลเกี่ยวกับรายละเอียดเริ่มมีอิทธิพลต่อการตัดสินใจที่เป็นประโยชน์ต่อการปฏิบัติจริง","wellbeing":"สร้างสมดุลระหว่างการเคลื่อนไหวกับการฟื้นฟูอย่างแท้จริงตลอดทั้งสัปดาห์ ปรับปรุงสิ่งที่คุณทำได้ และยอมให้ผลงานดี ๆ เสร็จสมบูรณ์ก่อนที่จะสมบูรณ์แบบ","guidance":"ให้คำถามนี้นำทางสัปดาห์: ปรับปรุงสิ่งที่คุณทำได้ และอนุญาตให้งานที่ดีสมบูรณ์ก่อนที่จะสมบูรณ์แบบ"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'year', 'th', '{"overview":"ปีนี้เชิญชวนให้เติบโตอย่างอดทนรอบ ๆ ตัวตน วัตถุประสงค์ และวิธีการใช้พลังงานของคุณ ราศีกันย์เคลื่อนผ่านพลังของโลก การแยกแยะและการบริการนำทางหญิงพรหมจารี เปลี่ยนการสังเกตรอบคอบให้เป็นการปรับปรุงที่ใช้ได้จริง","love":"ความรักลึกซึ้งขึ้นเมื่อตอนที่คุณฝึกความสม่ำเสมอและให้ความสัมพันธ์เติบโตตามจังหวะของมนุษย์ ของขวัญของคุณในการวิเคราะห์ งานฝีมือ การให้บริการช่วยเหลือสามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดง","career":"การทำงานระยะยาวจะเข้มแข็งขึ้นเมื่อความทะเยอทะยานมาพร้อมกับโครงสร้างที่คุณสามารถรักษาได้ ใช้ความสังเกต ประสบการณ์จริง ความรอบคอบ และความแม่นยำเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องตอบสนองทั้งหมดในครั้งเดียว","finance":"สร้างความมั่นใจทางการเงินผ่านนิสัยที่ทำซ้ำได้แทนการคาดการณ์ที่สมบูรณ์แบบ สังเกตว่าเมื่อความสมบูรณ์แบบ การวิจารณ์ตนเอง หรือความวิตกกังวลเรื่องรายละเอียดเริ่มมีอิทธิพลต่อการตัดสินใจที่เป็นประโยชน์","wellbeing":"ให้ความเป็นอยู่ที่ดีเป็นรากฐานของชีวิตที่คุณกำลังก่อสร้าง ไม่ใช่รางวัลหลังจากที่เสร็จสิ้นแล้ว พัฒนาสิ่งที่คุณทำได้ และอนุญาตให้งานที่ดีเสร็จสมบูรณ์ก่อนที่จะสมบูรณ์แบบ","guidance":"กลับมาหาเข็มทิศนี้ตลอดทั้งปี: ปรับปรุงสิ่งที่คุณทำได้ และอนุญาตให้ผลงานที่ดีเสร็จสมบูรณ์ก่อนที่จะสมบูรณ์แบบ"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('libra', 'th', '{"name":"ราศีตุลย์","dateRange":"23 ก.ย. – 22 ต.ค.","rulingPlanet":"ดาวศุกร์","summary":"สมดุล ความงาม และการตอบแทนเป็นแนวทางให้ราศีตุลย์ไปสู่ทางเลือกที่ให้เกียรติทุกเสียง","originStory":"ตราชั่งของราศีตุลย์ถูกถือโดยอัสตราเรีย เทพธิดาแห่งความยุติธรรม และเป็นสัญลักษณ์เดียวของราศีที่ไม่ใช่สิ่งมีชีวิต พวกมันแทนการตัดสินใจอย่างรอบคอบ ความสามัคคีในสังคม และการทำงานอย่างต่อเนื่องในการฟื้นฟูสมดุล แทนที่จะคิดว่ามันมีอยู่แล้ว","traits":["ทางการทูต","มีความยุติธรรม","มีเสน่ห์","ร่วมมือกัน"],"strengths":["การไกล่เกลี่ย","มุมมอง","สร้างความกลมกลืน"],"challenges":["ความลังเล","การประจบประแจงผู้คน","หลีกเลี่ยงความขัดแย้งที่จําเป็น"],"compatibleSigns":["ราศีเมถุน","ราศีกุมภ์","ราศีสิงห์"],"reflectionPrompt":"แสวงหาความยุติธรรมโดยไม่ละทิ้งความจริงของความต้องการของตนเอง"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'day', 'th', '{"overview":"วันนี้สนับสนุนก้าวที่ชัดเจนและมีเจตนาราศีตุลย์เคลื่อนที่ผ่านพลังงานอากาศความสมดุล ความงาม และการตอบแทน นําทางตาชั่งไปสู่การเลือกที่เคารพทุกเสียง","love":"ในความรักวันนี้ เลือกการมีอยู่มากกว่าการคาดเดา ของขวัญของคุณในการเป็นสื่อกลาง มุมมอง การสร้างความสามัคคี สามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงออก","career":"ในการทำงาน จงทำงานที่มีความหมายที่สุดให้เสร็จก่อนที่จะไล่ตามแรงขับเคลื่อนใหม่ ใช้ความสามารถในการเจรจา มีใจยุติธรรม มีเสน่ห์ และการทำงานร่วมกันเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องตอบสนองทั้งหมดในครั้งเดียว","finance":"ทำให้การตัดสินใจเกี่ยวกับเงินในวันนี้เรียบง่ายและมีเหตุผล สังเกตเมื่อความลังเล การยอมใจคนอื่น การหลีกเลี่ยงความขัดแย้งที่จำเป็นเริ่มมีอิทธิพลต่อการตัดสินใจที่เป็นประโยชน์","wellbeing":"การหยุดพักเล็ก ๆ สามารถรีเซ็ตพลังงานของคุณได้ แสวงหาความยุติธรรมโดยไม่ทอดทิ้งความจริงของความต้องการของตนเอง","guidance":"ก่อนที่วันจะสิ้นสุด จำไว้ว่า: แสวงหาความยุติธรรมโดยไม่ละทิ้งความจริงเกี่ยวกับความต้องการของตัวเอง"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'week', 'th', '{"overview":"สัปดาห์นี้พัฒนาผ่านทางการเลือกอย่างมั่นคงมากกว่าช่วงเวลาที่น่าตื่นเต้นครั้งเดียว ราศีตุลย์เคลื่อนผ่านพลังงานแห่งอากาศ ความสมดุล ความงาม และความเป็นการตอบแทนเป็นแนวทางให้ราศีตุลย์สู่การเลือกที่ให้เกียรติทุกเสียง","love":"ความสัมพันธ์ได้รับประโยชน์จากการสนทนาที่เปิดโอกาสทั้งความซื่อสัตย์และความอบอุ่น ของขวัญของคุณในการไกล่เกลี่ย มุมมอง การสร้างความสามัคคีสามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงตัว","career":"ความก้าวหน้าทางวิชาชีพที่ดีที่สุดของคุณมาจากการเลือกความสำคัญและปกป้องเวลาให้กับมัน ใช้ความมีไหวพริบทางการทูต มีความยุติธรรม มีเสน่ห์ ทำงานร่วมกันเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดในครั้งเดียว","finance":"ทบทวนรูปแบบการใช้จ่ายของคุณก่อนที่จะตัดสินใจใช้จ่ายมากขึ้น สังเกตว่าเมื่อใดที่ความลังเล การพยายามเอาใจผู้อื่น หรือการหลีกเลี่ยงความขัดแย้งที่จำเป็น เริ่มมีผลต่อการตัดสินใจเชิงปฏิบัติ","wellbeing":"สมดุลการเคลื่อนไหวด้วยการฟื้นฟูอย่างแท้จริงตลอดสัปดาห์ แสวงหาความยุติธรรมโดยไม่ทอดทิ้งความจริงเกี่ยวกับความต้องการของคุณเอง","guidance":"ให้คำถามนี้เป็นแนวทางของสัปดาห์: แสวงหาความยุติธรรมโดยไม่ละทิ้งความจริงเกี่ยวกับความต้องการของตัวเอง"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'year', 'th', '{"overview":"ปีนี้เชิญชวนให้มีการเติบโตอย่างอดทนรอบๆ อัตลักษณ์ วัตถุประสงค์ และวิธีที่คุณใช้พลังงาน ราศีตุลย์เคลื่อนตัวผ่านพลังงานอากาศ ความสมดุล ความงาม และการให้เกียรติซึ่งกันและกันชี้นำราศีตุลย์ไปสู่การตัดสินใจที่เคารพทุกเสียง","love":"ความรักลึกซึ้งขึ้นเมื่อคุณฝึกฝนความสม่ำเสมอและปล่อยให้ความสัมพันธ์พัฒนาตามจังหวะของมนุษย์ ของขวัญของคุณด้านการไกล่เกลี่ย มุมมอง และการสร้างความสามัคคีสามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงออก","career":"การทำงานระยะยาวจะเข้มแข็งขึ้นเมื่อความทะเยอทะยานมาพร้อมกับโครงสร้างที่คุณสามารถรักษาได้ ใช้ความสามารถทางการทูต ความยุติธรรม มีเสน่ห์ และการทำงานร่วมกันเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องตอบสนองทั้งหมดในครั้งเดียว","finance":"สร้างความมั่นใจทางการเงินผ่านนิสัยที่ทำซ้ำได้ แทนการทำนายที่สมบูรณ์แบบ สังเกตเมื่อการลังเล การทำเพื่อเอาใจคนอื่น การหลีกเลี่ยงความขัดแย้งที่จำเป็นเริ่มส่งผลต่อการตัดสินใจที่เป็นจริง","wellbeing":"ถือความสุขเป็นรากฐานของชีวิตที่คุณกำลังก่อสร้าง ไม่ใช่รางวัลหลังจากทำสำเร็จ แสวงหาความยุติธรรมโดยไม่ละทิ้งความจริงของความต้องการของตัวเอง","guidance":"กลับมาหาเข็มทิศนี้ตลอดทั้งปี: แสวงหาความยุติธรรมโดยไม่ทอดทิ้งความจริงเกี่ยวกับความต้องการของคุณเอง"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('scorpio', 'th', '{"name":"ราศีพิจิก","dateRange":"23 ต.ค. – 21 พ.ย.","rulingPlanet":"ดาวพลูโต","summary":"ความลึกซึ้งและการเปลี่ยนแปลงคือสิ่งที่นิยามของราศีแมงป่อง ซึ่งความเข้าใจของมันค้นหาความจริงใต้ผิวเผิน","originStory":"ราศีพิจิกระลึกถึงแมงป่องที่ถูกส่งไปเผชิญกับ นักล่าโอไรออน หลังจากความภาคภูมิใจของเขาได้รบกวนลำดับธรรมชาติ ตำแหน่งตรงข้ามของพวกเขาในท้องฟ้าเรียกถึงขอบเขต ผลที่ตามมา ความลึกลับ และพลังฟื้นฟูที่พบหลังจากการสิ้นสุด","traits":["เข้มข้น","มีความเข้าใจ","จงรักภักดี","มีไหวพริบ"],"strengths":["ความกล้าในด้านอารมณ์","สมาธิ","การเปลี่ยนแปลง"],"challenges":["ความลับ","ความสงสัย","การเก็บความโกรธแค้น"],"compatibleSigns":["โรคมะเร็ง","ราศีมีน","ราศีกันย์"],"reflectionPrompt":"ใช้ความลึกของคุณในการเปลี่ยนแปลงความจริง ไม่ใช่เพื่อปกปิดมัน"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'day', 'th', '{"overview":"วันนี้เอื้อต่อการก้าวไปทีละขั้นตอนที่ชัดเจนและมีจุดมุ่งหมาย ราศีพิจิกเคลื่อนผ่านพลังงานแห่งน้ำ ความลึกซึ้งและการเปลี่ยนแปลงเป็นตัวกำหนดราศีพิจิก ซึ่งการเข้าใจของเขาพบความจริงใต้ผิวน้ำ","love":"ในความรักวันนี้ เลือกการมีอยู่มากกว่าการสันนิษฐาน ของขวัญของคุณที่มีกำลังใจทางอารมณ์ สมาธิ การเปลี่ยนแปลง สามารถช่วยให้คุณเชื่อมต่อได้โดยไม่ต้องแสดง","career":"ในการทำงาน ให้ทำงานที่มีความหมายที่สุดให้เสร็จก่อนที่จะไล่ตามแรงขับเคลื่อนใหม่ ใช้ความเข้มข้น การสังเกตที่ละเอียด ความจงรักภักดี และความสามารถในการจัดการทรัพยากรเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องตอบสนองทั้งหมดในครั้งเดียว","finance":"รักษาการเลือกเรื่องเงินในวันนี้ให้เรียบง่ายและมีเหตุผล สังเกตเมื่อความลับ ความสงสัย การถือโกรธเริ่มมีอิทธิพลต่อการตัดสินใจอย่างเป็นจริง","wellbeing":"การหยุดพักเล็ก ๆ สามารถรีเซ็ตพลังงานของคุณได้ ใช้ความลึกของคุณในการเปลี่ยนแปลงความจริง ไม่ใช่เพี่อซ่อนมัน","guidance":"ก่อนที่วันจะสิ้นสุด จำไว้ว่า: ใช้ความลึกซึ้งของคุณเพื่อเปลี่ยนแปลงความจริง ไม่ใช่เพื่อปกปิดมัน"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'week', 'th', '{"overview":"สัปดาห์นี้พัฒนาผ่านทางการเลือกอย่างมั่นคง มากกว่าช่วงเวลาที่น่าตื่นเต้นครั้งเดียว ราศีพิจิกเคลื่อนผ่านพลังงานแห่งน้ำ ความลึกและการเปลี่ยนแปลงคือสิ่งที่นิยามราศีพิจิก ผู้ซึ่งมีสัญชาตญาณสามารถค้นหาความจริงใต้ผิวเผิน","love":"ความสัมพันธ์จะได้ประโยชน์จากบทสนทนาที่เปิดโอกาสทั้งความซื่อสัตย์และความอบอุ่น ของขวัญด้านความกล้าเชิงอารมณ์ ความมุ่งมั่น การเปลี่ยนแปลงของคุณ สามารถช่วยให้คุณสร้างความสัมพันธ์ได้โดยไม่ต้องแสร้งทำ","career":"ความก้าวหน้าทางวิชาชีพที่ดีที่สุดของคุณมาจากการเลือกความสำคัญและปกป้องเวลาให้กับมัน ใช้ความเข้มข้น การสังเกตที่เฉียบแหลม ความภักดี และความรอบรู้เป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดในครั้งเดียว","finance":"ทบทวนรูปแบบเบื้องหลังการใช้จ่ายของคุณก่อนที่จะตัดสินใจลงทุนใหญ่ สังเกตว่าเมื่อไรที่ความลับ ความสงสัย หรือการเก็บความแค้นเริ่มมีอิทธิพลต่อการตัดสินใจอย่างเป็นเหตุเป็นผล","wellbeing":"สมดุลการเคลื่อนไหวด้วยการฟื้นฟูอย่างแท้จริงตลอดสัปดาห์ ใช้ความลึกของคุณในการเปลี่ยนแปลงความจริง ไม่ใช่ปกปิดมัน","guidance":"ให้คำถามนี้เป็นแนวทางของสัปดาห์: ใช้ความลึกของคุณเพื่อเปลี่ยนความจริง ไม่ใช่เพื่อปิดบังมัน"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'year', 'th', '{"overview":"ปีนี้เชิญชวนให้เติบโตอย่างอดทนรอบ ๆ ตัวตน วัตถุประสงค์ และวิธีการใช้พลังงานของคุณ ราศีพิจิกเคลื่อนผ่านพลังของน้ำ ความลึกและการเปลี่ยนแปลงเป็นสิ่งที่กำหนดราศีพิจิกซึ่งการเข้าใจของเขาหา ความจริงใต้พื้นผิว","love":"ความรักลึกซึ้งขึ้นเมื่อตอนที่คุณฝึกความสม่ำเสมอและให้ความสัมพันธ์เติบโตตามจังหวะของมนุษย์ ของขวัญของคุณในการกล้าทางอารมณ์ สมาธิ การเปลี่ยนแปลงสามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดง","career":"งานระยะยาวจะเข้มแข็งขึ้นเมื่อความมุ่งมั่นถูกจับคู่กับโครงสร้างที่คุณสามารถรักษาได้ ใช้ความเข้มข้น ความละเอียดรอบคอบ ความซื่อสัตย์ และความมีไหวพริบเป็นเครื่องมือ ไม่ใช่เป็นความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดในครั้งเดียว","finance":"สร้างความมั่นใจทางการเงินผ่านนิสัยที่สามารถทำซ้ำได้แทนการพยากรณ์ที่สมบูรณ์แบบ สังเกตเมื่อความลับ ความสงสัย หรือการจองเวรเริ่มมีอิทธิพลต่อการตัดสินใจเชิงปฏิบัติ","wellbeing":"ถือความสุขเป็นรากฐานของชีวิตที่คุณกำลังก่อสร้าง ไม่ใช่รางวัลหลังจากทำสำเร็จ ใช้ความลึกซึ้งของคุณเพื่อเปลี่ยนแปลงความจริง ไม่ใช่เพื่อปกปิดมัน","guidance":"กลับมาหาเข็มทิศนี้ตลอดทั้งปี: ใช้ความลึกซึ้งของคุณเพื่อเปลี่ยนแปลงความจริง ไม่ใช่เพื่อซ่อนมัน"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('sagittarius', 'th', '{"name":"ราศีธนู","dateRange":"22 พ.ย. – 21 ธ.ค.","rulingPlanet":"ดาวพฤหัส","summary":"นักธนูแสวงหาเส้นขอบฟ้าที่กว้างขึ้นผ่านความจริง การเดินทาง การเรียนรู้ และความมุ่งมั่นอย่างมีจุดมุ่งหมาย","originStory":"ราศีธนูมักเกี่ยวข้องกับไครอน เซนทอร์ผู้มีปัญญาและครู ซึ่งลูกศรของเขาชี้ไปเกินสิ่งที่คุ้นเคย กลุ่มดาวสัญลักษณ์นี้เป็นตัวแทนของการรวมกันของสัญชาตญาณและความเข้าใจที่สูงขึ้น มุ่งไปสู่ขอบฟ้าที่มีความหมายมากขึ้นเสมอ","traits":["ชอบการผจญภัย","มองโลกในแง่ดี","ซื่อสัตย์","ทางปรัชญา"],"strengths":["วิสัยทัศน์","ความกระตือรือร้น","ความคิดเปิดกว้าง"],"challenges":["ความตรงไปตรงมา","สัญญามากเกินไป","หลีกหนีจากกิจวัตร"],"compatibleSigns":["ราศีเมษ","ราศีสิงห์","ราศีกุมภ์"],"reflectionPrompt":"ตั้งเป้าให้ไกล แต่เลือกทิศทางที่การกระทำประจำวันของคุณสามารถสนับสนุนได้"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'day', 'th', '{"overview":"วันนี้เอื้อต่อการก้าวไปทีละขั้นตอนที่ชัดเจนและมีจุดมุ่งหมาย ราศีธนูเคลื่อนผ่านพลังงานแห่งไฟ นักธนูแสวงหาขอบฟ้าที่กว้างขึ้นผ่านความจริง การเดินทาง การเรียนรู้ และความมองโลกในแง่ดีอย่างมีจุดมุ่งหมาย","love":"ในเรื่องความรักวันนี้ เลือกที่จะอยู่กับปัจจุบันมากกว่าการคาดเดา ของขวัญของคุณที่มีวิสัยทัศน์ ความกระตือรือร้น ใจเปิด สามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงออก","career":"ในการทำงาน ให้ทำงานที่มีความหมายที่สุดให้เสร็จก่อนที่จะไล่ตามพลังใหม่ ใช้ความกล้า, ความมองโลกในแง่ดี, ความซื่อสัตย์, และปรัชญาเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้ครบทั้งหมดในทันที","finance":"รักษาการตัดสินใจเรื่องเงินของวันนี้ให้ง่ายและมีเหตุผล สังเกตเมื่อความตรงไปตรงมา การให้สัญญามากเกินไป หรือการหนีจากกิจวัตรเริ่มมีอิทธิพลต่อการตัดสินใจที่ใช้เหตุผล","wellbeing":"การหยุดชะงักเล็ก ๆ สามารถรีเซ็ตพลังงานของคุณ ตั้งเป้าหมายให้ไกล แต่เลือกทิศทางที่การกระทำประจำวันของคุณสามารถสนับสนุนได้","guidance":"ก่อนวันจะหมดไป จงจำไว้: มุ่งหวังสูง แต่เลือกทิศทางที่การกระทำประจำวันของคุณสามารถสนับสนุนได้"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'week', 'th', '{"overview":"สัปดาห์นี้พัฒนาผ่านทางการเลือกอย่างมั่นคงมากกว่าช่วงเวลาที่น่าตื่นเต้นครั้งเดียว ราศีธนูเคลื่อนผ่านพลังงานแห่งไฟ นักธนูแสวงหาขอบฟ้าที่กว้างขึ้นผ่านความจริง การเดินทาง การเรียนรู้ และความมองโลกในแง่ดีที่มีจุดมุ่งหมาย","love":"ความสัมพันธ์ได้รับประโยชน์จากการสนทนาที่เปิดโอกาสทั้งความซื่อสัตย์และความอบอุ่น ของขวัญของคุณในวิสัยทัศน์ ความกระตือรือร้น ใจเปิดกว้างสามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงตัว","career":"ความก้าวหน้าทางอาชีพที่ดีที่สุดของคุณมาจากการเลือกเรื่องที่สำคัญและปกป้องเวลาให้กับมัน ใช้ความกล้า ความมองโลกในแง่ดี ความซื่อสัตย์ และปรัชญา เป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดพร้อมกัน","finance":"ทบทวนลักษณะพฤติกรรมด้านการใช้จ่ายของคุณก่อนที่จะทำการลงทุนหรือผูกมัดในสิ่งที่ใหญ่ขึ้น สังเกตว่าเมื่อตรงไปตรงมา การให้สัญญามากเกินไป การหลีกเลี่ยงกิจวัตรเริ่มมีอิทธิพลต่อการตัดสินใจที่เป็นจริง","wellbeing":"สมดุลการเคลื่อนไหวกับการฟื้นฟูที่แท้จริงตลอดสัปดาห์ ตั้งเป้าให้ไกล แต่เลือกทิศทางที่การกระทำประจำวันของคุณสนับสนุนได้","guidance":"ให้คำถามนี้นำทางสัปดาห์: ตั้งเป้าให้ไกล แต่เลือกทิศทางที่การกระทำประจำวันของคุณสามารถสนับสนุนได้"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'year', 'th', '{"overview":"ปีนี้เชิญชวนการเติบโตอย่างอดทนเกี่ยวกับอัตลักษณ์ วัตถุประสงค์ และวิธีที่คุณใช้พลังงาน นักธนูเคลื่อนผ่านพลังงานแห่งไฟ นักธนูมองหาขอบฟ้าที่กว้างขึ้นผ่านความจริง การเดินทาง การเรียนรู้ และความมุ่งมั่นเชิงบวกที่มีวัตถุประสงค์","love":"ความรักจะลึกซึ้งขึ้นเมื่อคุณฝึกความสม่ำเสมอและปล่อยให้ความสัมพันธ์พัฒนาไปตามจังหวะของมนุษย์ ของขวัญของคุณในการมองการณ์ไกล ความกระตือรือร้น และความเปิดกว้างทางความคิดสามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงบทบาท","career":"งานระยะยาวจะเข้มแข็งขึ้นเมื่อความทะเยอทะยานมาคู่กับโครงสร้างที่คุณสามารถรักษาได้ ใช้ความกล้าได้กล้าเสีย มองโลกในแง่ดี ซื่อสัตย์ และเชิงปรัชญาเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องตอบสนองทั้งหมดในคราวเดียว","finance":"สร้างความมั่นใจทางการเงินผ่านนิสัยที่ทำซ้ำได้แทนการทำนายอย่างสมบูรณ์สังเกตเมื่อความตรงไปตรงมา การให้สัญญาเกินจริง การหลีกหนีจากกิจวัตรเริ่มมีอิทธิพลต่อการตัดสินใจอย่างเป็นจริง","wellbeing":"ปฏิบัติต่อความเป็นอยู่ที่ดีเป็นรากฐานสำหรับชีวิตที่คุณกำลังสร้าง ไม่ใช่รางวัลหลังจากทำมันเสร็จ ตั้งเป้าสูง แต่เลือทิศทางที่การกระทำประจำวันของคุณสามารถสนับสนุนได้","guidance":"กลับมาหาเข็มทิศนี้ตลอดทั้งปี: มุ่งไปไกล แต่เลือกทิศทางที่การกระทำประจำวันของคุณรองรับได้"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('capricorn', 'th', '{"name":"มังกร","dateRange":"22 ธ.ค. – 19 ม.ค.","rulingPlanet":"ดาวเสาร์","summary":"วินัยและวิสัยทัศน์ระยะไกลช่วยให้ Sea-Goat ปีนขึ้นไปได้ในขณะที่ยังคงมีสติปัญญาเกี่ยวกับความลึกของน้ํา","originStory":"ราศีมังกรซึ่งสัญลักษณ์เป็นแพะทะเลเกี่ยวข้องกับเทพพาน ผู้ซึ่งเปลี่ยนร่างบางส่วนเป็นปลาเพื่อหนีไทฟอน ธาตุภูเขาและมหาสมุทรของมันรวมความทะเยอทะยานกับการเอาตัวรอดทางอารมณ์ ให้ความสำคัญกับความเชี่ยวชาญที่ได้รับจากเวลาและความรับผิดชอบ","traits":["ทะเยอทะยาน","มีวินัย","อดทน","มีความรับผิดชอบ"],"strengths":["ความอดทน","กลยุทธ์","ความน่าเชื่อถือ"],"challenges":["ความแข็งทื่อ","ทัศนคติลบ","วัดคุณค่าผ่านความสำเร็จ"],"compatibleSigns":["ราศีพฤษภ","ราศีกันย์","ราศีพิจิก"],"reflectionPrompt":"สร้างระยะยาวในขณะที่จำไว้ว่าการพักผ่อนเป็นส่วนหนึ่งของโครงสร้าง"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'day', 'th', '{"overview":"วันนี้เหมาะกับการก้าวไปทีละขั้นที่ชัดเจนและมีจุดประสงค์ ดวงดาวราศีมังกรเคลื่อนผ่านพลังงานดิน วินัยและวิสัยทัศน์ระยะยาวช่วยให้นักษัตรทะเลปีนขึ้นไปในขณะรักษาความรอบคอบเกี่ยวกับความลึกข้างล่าง","love":"ในความรักวันนี้ เลือกการมีอยู่มากกว่าการคาดเดา ของขวัญของคุณอย่างความอดทน กลยุทธ์ ความน่าเชื่อถือสามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงออก","career":"ที่ทำงาน จงทำงานที่มีความหมายที่สุดให้เสร็จก่อนที่จะไล่ตามแรงผลักดันใหม่ ใช้ความทะเยอทะยาน วินัย ความอดทน และความรับผิดชอบเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จพร้อมกันทั้งหมด","finance":"รักษาการเลือกใช้จ่ายเงินในวันนี้ให้ง่ายและมีเหตุผล สังเกตเมื่อความแข็งกร้าว ความคิดลบ การประเมินค่าความสามารถตนเองผ่านความสำเร็จเริ่มกระทบต่อการตัดสินใจที่เป็นจริง","wellbeing":"การหยุดพักเล็กๆ สามารถรีเซ็ตพลังงานของคุณได้ สร้างสิ่งต่างๆ เพื่อระยะยาว พร้อมทั้งจำไว้ว่าการพักผ่อนเป็นส่วนหนึ่งของโครงสร้าง","guidance":"ก่อนวันจะหมดไป จงจำไว้: สร้างสิ่งต่าง ๆ ในระยะยาวพร้อมกับจำไว้ว่าการพักผ่อนเป็นส่วนหนึ่งของโครงสร้าง"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'week', 'th', '{"overview":"สัปดาห์นี้พัฒนาไปด้วยการเลือกที่มั่นคงมากกว่าช่วงเวลาที่ตื่นเต้นเพียงครั้งเดียว ราศีมังกรเคลื่อนผ่านพลังงานธาตุดิน วินัยและวิสัยทัศน์ระยะยาวช่วยให้แพะทะเลปีนขึ้นไปในขณะที่ยังมีความรอบคอบเกี่ยวกับความลึกด้านล่าง","love":"ความสัมพันธ์จะได้ประโยชน์จากบทสนทนาที่เปิดโอกาสทั้งความซื่อสัตย์และความอบอุ่น ของขวัญของคุณในเรื่องความอดทน กลยุทธ์ และความน่าเชื่อถือ สามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงบทบาท","career":"ความก้าวหน้าทางอาชีพที่ดีที่สุดของคุณมาจากการเลือกเรื่องที่สำคัญและปกป้องเวลาให้กับมัน ใช้ความทะเยอทะยาน วินัย ความอดทน และความรับผิดชอบ เป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดพร้อมกัน","finance":"ตรวจสอบรูปแบบการใช้จ่ายของคุณก่อนที่จะทำข้อผูกมัดที่ใหญ่ขึ้น สังเกตว่าเมื่อไหร่อาการฝืด ความคิดในแง่ร้าย หรือการวัดคุณค่าผ่านความสำเร็จเริ่มมีอิทธิพลต่อการตัดสินใจที่เป็นไปตามเหตุผล","wellbeing":"สมดุลการเคลื่อนไหวกับการฟื้นฟูที่แท้จริงตลอดสัปดาห์ สร้างเพื่อระยะยาวในขณะที่จำไว้ว่าการพักผ่อนเป็นส่วนหนึ่งของโครงสร้าง","guidance":"ให้คำถามนี้นำทางสัปดาห์: สร้างสิ่งต่าง ๆ ในระยะยาวในขณะที่จำได้ว่าการพักผ่อนเป็นส่วนหนึ่งของโครงสร้าง"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'year', 'th', '{"overview":"ปีนี้เชิญชวนให้เติบโตอย่างอดทนรอบ ๆ ตัวตน จุดมุ่งหมาย และวิธีการใช้พลังงานของคุณ มังกรเคลื่อนไหวผ่านพลังงานแห่งดิน วินัยและวิสัยทัศน์ระยะยาวช่วยให้แพะทะเลปีนขึ้นไปได้ในขณะที่ยังคงมีปัญญาเกี่ยวกับความลึกด้านล่าง","love":"ความรักจะลึกซึ้งยิ่งขึ้นเมื่อคุณฝึกความสม่ำเสมอและปล่อยให้ความสัมพันธ์พัฒนาไปตามจังหวะของมนุษย์ ของขวัญของคุณในการมีความอดทน กลยุทธ์ และความน่าเชื่อถือสามารถช่วยให้คุณเชื่อมต่อได้โดยไม่ต้องแสดงออก","career":"งานระยะยาวจะเข้มแข็งขึ้นเมื่อความทะเยอทะยานมาคู่กับโครงสร้างที่คุณสามารถรักษาได้ ใช้ความทะเยอทะยาน มีวินัย อดทน และมีความรับผิดชอบเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดพร้อมกัน","finance":"สร้างความมั่นใจทางการเงินผ่านนิสัยที่ทำซ้ำได้ แทนที่จะมุ่งหวังการทำนายที่สมบูรณ์ สังเกตเมื่อความแข็งกร้าว ความมองโลกในแง่ร้าย และการวัดคุณค่าผ่านความสำเร็จเริ่มมีอิทธิพลต่อการตัดสินใจที่เป็นประโยชน์","wellbeing":"ปฏิบัติต่อความเป็นอยู่ที่ดีเป็นรากฐานสำหรับชีวิตที่คุณกำลังสร้าง ไม่ใช่รางวัลหลังจากทำมันเสร็จ สร้างเพื่อระยะยาวในขณะที่จำไว้ว่าการพักผ่อนก็เป็นส่วนหนึ่งของโครงสร้าง","guidance":"กลับมาหาเข็มทิศนี้ตลอดทั้งปี: สร้างสิ่งต่าง ๆ ในระยะยาวพร้อมกับจำไว้ว่าการพักผ่อนเป็นส่วนหนึ่งของโครงสร้าง"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aquarius', 'th', '{"name":"ราศีกุมภ์","dateRange":"20 ม.ค. – 18 ก.พ.","rulingPlanet":"ดาวยูเรนัส","summary":"ความคิดเป็นอิสระและวิสัยทัศน์ร่วมกันเป็นแนวทางให้ผู้ถือขันน้ำเทแนวคิดใหม่ ๆ ลงสู่โลก","originStory":"ราศีกุมภ์เกี่ยวข้องกับกาไนมีด ผู้ถือถ้วยซึ่งภาชนะของเขานำพาน้ำไปสู่เทพเจ้า และในเชิงสัญลักษณ์ก็นำพาความรู้สู่มนุษยชาติ แม้ว่าภาพลักษณ์ของราศีนี้จะถือว่าหยดน้ำ แต่ราศีนี้อยู่ในธาตุลม: ความคิด ระบบ และการฟื้นฟูที่แบ่งปันเพื่อประโยชน์ร่วม","traits":["ต้นฉบับ","เป็นอิสระ","มนุษยธรรม","คิดประดิษฐ์"],"strengths":["ความคิดสร้างสรรค์","ความเป็นกลาง","วิสัยทัศน์ของชุมชน"],"challenges":["กองกําลังย่อย","นิสัยที่ตรงข้าม","ความคิดเห็นที่แน่นอน"],"compatibleSigns":["ราศีเมถุน","ราศีตุลย์","ราศีธนู"],"reflectionPrompt":"ให้ความแตกต่างของคุณสร้างความสัมพันธ์แทนที่จะสร้างระยะห่าง"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'day', 'th', '{"overview":"วันนี้เหมาะกับการก้าวไปทีละขั้นที่ชัดเจนและมีจุดประสงค์ ดวงดาวราศีกุมภ์เคลื่อนผ่านพลังงานอากาศ ความคิดอิสระและวิสัยทัศน์รวมหมู่ชี้นำผู้ที่ถือเหยือกน้ำให้เทไอเดียใหม่สู่โลก","love":"ในความรักวันนี้ เลือกที่จะอยู่กับปัจจุบันมากกว่าการสมมติ ความสามารถของคุณด้านนวัตกรรม ความเป็นกลาง และวิสัยทัศน์ชุมชน สามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงออก","career":"ที่ทำงาน จงทำงานที่มีความหมายที่สุดให้เสร็จก่อนที่จะไล่ตามแรงผลักดันใหม่ ใช้ความเป็นต้นฉบับ อิสระ มนุษยธรรม และความคิดสร้างสรรค์เป็นเครื่องมือ ไม่ใช่คาดหวังที่คุณต้องทำให้ครบทั้งหมดพร้อมกัน","finance":"ทำให้การตัดสินใจเรื่องเงินในวันนี้เรียบง่ายและมีเหตุผล สังเกตเมื่อการแยกตัว นิสัยตรงข้าม ความคิดเห็นที่ตายตัวเริ่มมีอิทธิพลต่อการตัดสินใจที่เป็นรูปธรรม","wellbeing":"การหยุดพักเล็ก ๆ สามารถรีเซ็ตพลังงานของคุณได้ ให้ความแตกต่างของคุณสร้างการเชื่อมต่อแทนที่จะสร้างความห่างเหิน","guidance":"ก่อนที่วันจะสิ้นสุด จำไว้ว่า: ให้ความแตกต่างของคุณสร้างความเชื่อมโยงแทนที่จะสร้างระยะห่าง"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'week', 'th', '{"overview":"สัปดาห์นี้พัฒนาด้วยการตัดสินใจอย่างมั่นคงมากกว่าช่วงเวลาอันน่าตื่นเต้นเพียงครั้งเดียว ราศีกุมภ์เคลื่อนผ่านพลังงานแห่งอากาศ ความคิดอิสระและวิสัยทัศน์ร่วมกันนำพานักรบแห่งน้ำให้ถ่ายทอดความคิดใหม่ ๆ สู่โลก","love":"ความสัมพันธ์จะได้ประโยชน์จากบทสนทนาที่เปิดโอกาสทั้งความซื่อสัตย์และความอบอุ่น ของขวัญของคุณในเรื่องนวัตกรรม ความเป็นกลาง และวิสัยทัศน์ต่อชุมชน สามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงบทบาท","career":"ความก้าวหน้าที่ดีที่สุดในอาชีพของคุณมาจากการเลือกความสำคัญและปกป้องเวลาเพื่อมัน ใช้ความเป็นต้นฉบับ, เป็นอิสระ, เป็นมนุษยธรรม, และมีความคิดสร้างสรรค์เป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องตอบสนองทั้งหมดในคราวเดียว","finance":"ทบทวนลักษณะพฤติกรรมด้านการใช้จ่ายของคุณก่อนที่จะทำการลงทุนหรือผูกมัดในสิ่งที่ใหญ่ขึ้น สังเกตว่าเมื่อตัวคุณแยกตัว นิสัยขัดแย้ง ความคิดเห็นที่มั่นคงเริ่มมีอิทธิพลต่อการตัดสินใจที่เป็นจริง","wellbeing":"สมดุลการเคลื่อนไหวด้วยการฟื้นฟูอย่างแท้จริงตลอดสัปดาห์ ให้ความแตกต่างของคุณเป็นเครื่องเชื่อมต่อมากกว่าการสร้างระยะห่าง","guidance":"ให้คำถามนี้เป็นแนวทางของสัปดาห์: ให้ความแตกต่างของคุณสร้างความสัมพันธ์แทนที่จะสร้างระยะห่าง"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'year', 'th', '{"overview":"ปีนี้เชิญชวนให้เติบโตอย่างอดทนรอบๆ ความเป็นตัวตน จุดประสงค์ และวิธีที่คุณใช้พลังงาน กุมภ์เคลื่อนผ่านพลังงานอากาศ ความคิดอิสระและวิสัยทัศน์ร่วมกันชี้นำผู้ชี้น้ำให้เทแนวคิดใหม่เข้าสู่โลก","love":"ความรักลึกซึ้งขึ้นเมื่อคุณฝึกฝนความสม่ำเสมอและปล่อยให้ความสัมพันธ์พัฒนาตามจังหวะของมนุษย์ ของขวัญของคุณด้านนวัตกรรม ความเป็นกลาง และวิสัยทัศน์ชุมชนสามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงออก","career":"งานระยะยาวจะเข้มแข็งขึ้นเมื่อความทะเยอทะยานมาคู่กับโครงสร้างที่คุณสามารถรักษาได้ ใช้ความเป็นต้นฉบับ ความเป็นอิสระ ความเมตตากรุณา ความคิดสร้างสรรค์เป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดในครั้งเดียว","finance":"สร้างความมั่นใจทางการเงินผ่านนิสัยที่ทำซ้ำได้แทนการทำนายอย่างสมบูรณ์ สังเกตเมื่อการแยกตัว นิสัยที่ตรงข้าม ความเชื่อที่ตายตัว เริ่มมีอิทธิพลต่อการตัดสินใจอย่างเป็นจริง","wellbeing":"ถือความสุขเป็นรากฐานของชีวิตที่คุณกำลังก่อสร้าง ไม่ใช่รางวัลหลังจากทำสำเร็จ ให้ความแตกต่างของคุณช่วยสร้างความเชื่อมโยง แทนที่จะสร้างระยะห่าง","guidance":"กลับมาหาเข็มทิศนี้ตลอดทั้งปี: ให้ความแตกต่างของคุณเป็นสะพานเชื่อมแทนที่จะสร้างระยะห่าง"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('pisces', 'th', '{"name":"ราศีมีน","dateRange":"19 ก.พ. – 20 มี.ค.","rulingPlanet":"ดาวเนปจูน","summary":"ความเมตตาและจินตนาการนำทางปลาระหว่างสัญชาตญาณ ความฝัน และความรู้สึกที่แบ่งปัน","originStory":"ราศีมีนระลึกถึงอาโฟรไดท์และอีรอสที่กลายเป็นปลาและผูกพันกันเพื่อหลบหนีไทฟอน ความผูกพันระหว่างปลาทั้งสองตัวแสดงถึงความทุ่มเท, อัตลักษณ์ที่ยืดหยุ่น, ความอ่อนไหวทางจิตวิญญาณ, และการค้นพบเอกภาพขณะเคลื่อนผ่านกระแสที่เปลี่ยนแปลง","traits":["ใจเมตตา","มีจินตนาการ","สัญชาตญาณ","อ่อนโยน"],"strengths":["ความเห็นอกเห็นใจ","ความคิดสร้างสรรค์","ความเข้าใจทางจิตวิญญาณ"],"challenges":["การหนีความจริง","ขอบเขตที่พร่ามัว","การดูดซับอารมณ์ของผู้อื่น"],"compatibleSigns":["โรคมะเร็ง","ราศีพิจิก","มังกร"],"reflectionPrompt":"เคารพความอ่อนไหวของคุณด้วยขอบเขตที่แข็งแรงเพียงพอที่จะปกป้องมัน"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'day', 'th', '{"overview":"วันนี้เป็นวันที่เอื้ออํานวยต่อก้าวที่ชัดเจนและมีเจตนาราศีมีนเคลื่อนที่ผ่านพลังงานน้ําความเมตตาและจินตนาการนําทางปลาระหว่างสัญชาตญาณ ความฝัน และความรู้สึกร่วมกัน","love":"ในความรักวันนี้ เลือกการมีอยู่มากกว่าการสันนิษฐาน ของขวัญของคุณคือความเห็นอกเห็นใจ ความคิดสร้างสรรค์ และความเข้าใจทางจิตวิญญาณ ซึ่งสามารถช่วยให้คุณเชื่อมต่อโดยไม่ต้องแสดงออก","career":"ที่ทำงาน จงทำงานที่มีความหมายที่สุดให้เสร็จก่อนที่จะไล่ตามแรงผลักดันใหม่ ใช้ความเมตตา จินตนาการ สัญชาตญาณ และความอ่อนโยนเป็นเครื่องมือ ไม่ใช่คาดหวังที่คุณต้องทำให้ครบทั้งหมดพร้อมกัน","finance":"ทำให้การตัดสินใจเกี่ยวกับเงินในวันนี้เรียบง่ายและมีพื้นฐานสอดคล้อง สังเกตเมื่อความอยากหนี ความไม่ชัดเจนของขอบเขต หรือการรับอารมณ์ของผู้อื่นเริ่มมีอิทธิพลต่อการตัดสินใจที่เป็นประโยชน์จริง","wellbeing":"การหยุดพักเล็กๆ สามารถรีเซ็ตพลังงานของคุณได้ ให้เกียรติความอ่อนไหวของคุณด้วยขอบเขตที่แข็งแรงพอที่จะปกป้องมัน","guidance":"ก่อนวันจะหมดไป จงจำไว้: ให้เกียรติความไวต่อความรู้สึกของคุณด้วยขอบเขตที่แข็งแรงพอที่จะปกป้องมัน"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'week', 'th', '{"overview":"สัปดาห์นี้พัฒนาผ่านทางการเลือกอย่างมั่นคงมากกว่าช่วงเวลาที่น่าตื่นเต้นครั้งเดียว ราศีปลาเคลื่อนผ่านพลังงานแห่งน้ำ ความเห็นอกเห็นใจและจินตนาการนำทางราศีปลาระหว่างสัญชาตญาณ ความฝัน และความรู้สึกร่วม","love":"ความสัมพันธ์จะได้ประโยชน์จากบทสนทนาที่เปิดโอกาสทั้งความซื่อสัตย์และความอบอุ่น ของขวัญด้านความเห็นอกเห็นใจ ความคิดสร้างสรรค์ และสติปัญญาทางจิตวิญญาณของคุณ สามารถช่วยให้คุณสร้างความสัมพันธ์ได้โดยไม่ต้องแสร้งทำ","career":"ความก้าวหน้าทางวิชาชีพที่ดีที่สุดของคุณมาจากการเลือกความสำคัญและปกป้องเวลาให้กับมัน ใช้ความเมตตา มีจินตนาการ มีสัญชาตญาณ มีความอ่อนโยนเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องทำให้สำเร็จทั้งหมดในครั้งเดียว","finance":"ทบทวนลักษณะพฤติกรรมด้านการใช้จ่ายของคุณก่อนที่จะทำการลงทุนหรือผูกมัดในสิ่งที่ใหญ่ขึ้น สังเกตว่าเมื่อการหนีปัญหา ขอบเขตไม่ชัดเจน การซึมซับอารมณ์ของผู้อื่นเริ่มมีอิทธิพลต่อการตัดสินใจที่เป็นจริง","wellbeing":"สร้างสมดุลระหว่างการเคลื่อนไหวกับการฟื้นฟูอย่างแท้จริงตลอดทั้งสัปดาห์ ให้เกียรติความอ่อนไหวของคุณด้วยขอบเขตที่เข้มแข็งเพียงพอที่จะปกป้องมัน","guidance":"ให้คำถามนี้นำทางสัปดาห์: ให้เกียรติความอ่อนไหวของคุณด้วยขอบเขตที่แข็งแรงพอที่จะปกป้องมัน"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'year', 'th', '{"overview":"ปีนี้เชิญชวนการเติบโตอย่างอดทนเกี่ยวกับอัตลักษณ์ วัตถุประสงค์ และวิธีที่คุณใช้พลังงาน ปลาเคลื่อนผ่านพลังงานของน้ำ ความเมตตาและจินตนาการนำทางปลาทั้งหลายระหว่างสัญชาตญาณ ความฝัน และความรู้สึกที่แบ่งปัน","love":"ความรักจะลึกซึ้งยิ่งขึ้นเมื่อคุณฝึกความสม่ำเสมอและปล่อยให้ความสัมพันธ์พัฒนาไปตามจังหวะของมนุษย์ ของขวัญของคุณในการมีความเห็นอกเห็นใจ ความคิดสร้างสรรค์ และสติปัญญาทางจิตวิญญาณสามารถช่วยให้คุณเชื่อมต่อได้โดยไม่ต้องแสดงออก","career":"งานระยะยาวจะเข้มแข็งขึ้นเมื่อความทะเยอทะยานมาคู่กับโครงสร้างที่คุณสามารถรักษาได้ ใช้ความเมตตา ความคิดสร้างสรรค์ สัญชาตญาณ และความอ่อนโยนเป็นเครื่องมือ ไม่ใช่ความคาดหวังที่คุณต้องตอบสนองทั้งหมดในคราวเดียว","finance":"สร้างความมั่นใจทางการเงินผ่านนิสัยที่ทำซ้ำได้ แทนการทำนายที่สมบูรณ์แบบ สังเกตเมื่อการหลีกหนีความจริง ขอบเขตที่พร่ามัว การรับอารมณ์ของผู้อื่นเริ่มส่งผลต่อการตัดสินใจที่เป็นจริง","wellbeing":"ให้ความเป็นอยู่ที่ดีเป็นรากฐานของชีวิตที่คุณกำลังก่อสร้าง ไม่ใช่รางวัลหลังจากที่เสร็จสิ้นแล้ว ให้เกียรติความอ่อนไหวของคุณด้วยขอบเขตที่แข็งแรงพอที่จะปกป้องมัน","guidance":"กลับมาหาเข็มทิศนี้ตลอดทั้งปี: ให้เกียรติความอ่อนไหวของคุณด้วยขอบเขตที่แข็งแรงพอที่จะปกป้องมัน"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('fool', 'fr', '{"name":"Le Mat","meaning":"Une page blanche et un saut de foi — un nouveau voyage commence avec un cœur ouvert.","advice":"Faites confiance au chemin devant vous et faites ce premier pas, même sans toutes les réponses.","yesNoMeaning":"Un nouveau départ ne porte rarement une réponse fixe — le résultat dépend de la mesure que vous prenez."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('magician', 'fr', '{"name":"Le Magicien","meaning":"Vous possédez tous les outils dont vous avez besoin. Concentrez votre volonté et transformez l''intention en action.","advice":"Utilisez vos compétences et ressources délibérément — le moment est venu de passer à l''action.","yesNoMeaning":"Vous détenez déjà tout ce qui est nécessaire — l''énergie soutient l''avancement avec concentration."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('high-priestess', 'fr', '{"name":"La Grande Prêtresse","meaning":"Une sagesse tranquille se cache sous la surface. Écoutez votre intuition et votre voix intérieure.","advice":"Faites une pause, tournez-vous vers l''intérieur et laissez vos instincts vous guider avant d''agir.","yesNoMeaning":"La réponse est cachée sous la surface pour l''instant — faites confiance à votre intuition plutôt que de forcer un oui ou un non clair."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('empress', 'fr', '{"name":"L''Impératrice","meaning":"La croissance, l''abondance et une énergie nourricière vous entourent. Laissez la beauté et le soin s''épanouir.","advice":"Soyez patient et généreux — créez avec amour et laissez les choses mûrir naturellement.","yesNoMeaning":"Croissance, abondance et énergie nourricière soutiennent votre souhait — la réponse est un oui silencieux."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('emperor', 'fr', '{"name":"L''Empereur","meaning":"Structure, autorité et leadership stable. Construisez sur des bases solides avec discipline.","advice":"Prenez les commandes avec un plan clair ; des limites fermes apportent une stabilité durable.","yesNoMeaning":"Structure, autorité et discipline constante soutiennent un oui confiant."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hierophant', 'fr', '{"name":"Le Hiérophante","meaning":"La tradition et les conseils de confiance offrent un chemin fiable. Apprenez de ce qui a précédé.","advice":"Suivez la sagesse établie et demandez conseil à ceux en qui vous avez confiance.","yesNoMeaning":"La tradition et les conseils de confiance indiquent un oui fiable — appuyez-vous sur ce qui a déjà fait ses preuves."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('lovers', 'fr', '{"name":"Les Amoureux","meaning":"Un lien significatif ou un choix important. Suivez ce que votre cœur valorise vraiment.","advice":"Choisissez avec honnêteté et alignement — la connexion s''approfondit lorsque vous êtes sincère.","yesNoMeaning":"Votre cœur et vos valeurs sont alignés ici — la réponse est oui, surtout lorsque vous choisissez avec honnêteté."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('chariot', 'fr', '{"name":"Le Chariot","meaning":"La volonté et l''élan vous portent en avant. Restez concentré et vous réussirez.","advice":"Gardez les yeux sur le but et dirigez avec confiance à travers chaque obstacle.","yesNoMeaning":"La volonté et l''élan sont de votre côté — un oui concentré, à condition de rester engagé."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('strength', 'fr', '{"name":"Force","meaning":"Le vrai pouvoir est doux — la patience, le courage et la compassion domptent n''importe quel défi.","advice":"Dirigez avec une force calme; une main douce est souvent la plus forte.","yesNoMeaning":"Un courage doux et une résolution patiente font de cela un oui — avancez avec calme, et non par la force."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hermit', 'fr', '{"name":"L''Hermite","meaning":"Il est temps de prendre du recul et de chercher la clarté intérieure. La solitude apporte maintenant des réponses plus profondes.","advice":"Tournez-vous vers l''intérieur, réfléchissez, et laissez le calme révéler ce dont vous avez vraiment besoin.","yesNoMeaning":"Pas encore — la carte vous demande de prendre du recul et de trouver la clarté intérieure avant d''agir."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('wheel-of-fortune', 'fr', '{"name":"Roue de la Fortune","meaning":"La fortune tourne et les cycles changent. Ce qui change maintenant fait partie d''un rythme plus large.","advice":"Surfez sur la vague avec flexibilité — acceptez le tournant, qu''il soit bon ou non.","yesNoMeaning":"La fortune tourne — le résultat dépend de la façon dont vous traversez le changement plutôt que d''un oui ou non fixe."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('justice', 'fr', '{"name":"Justice","meaning":"La vérité et l''équité triomphent. La cause et l''effet entrent maintenant en équilibre.","advice":"Agis avec honnêteté et pèse les deux côtés ; les balances se régleront équitablement.","yesNoMeaning":"Les balances sont encore en train de se peser — la réponse juste dépend des faits et de votre honnêteté."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hanged-man', 'fr', '{"name":"L''Homme Pendu","meaning":"Une pause nécessaire. Relâchez le contrôle et voyez la situation sous un nouvel angle.","advice":"Arrêtez de pousser — abandonnez-vous au moment et laissez arriver une nouvelle perspective.","yesNoMeaning":"Une pause est nécessaire d’abord — forcer cela maintenant ne ferait que retarder une réponse plus claire."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('death', 'fr', '{"name":"Mort","meaning":"Une fin ouvre la voie au renouveau. Libérez ce qui a eu son temps.","advice":"Lâche prise sans regret ; une transformation profonde ouvre une nouvelle porte.","yesNoMeaning":"Une fin est en train de dégager le chemin — le chemin actuel se ferme pour qu''un nouveau puisse commencer."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('temperance', 'fr', '{"name":"Tempérance","meaning":"L''équilibre et la patience apportent l''harmonie. Mélangez les opposés avec grâce.","advice":"Avancez avec modération et gardez votre calme — des pas réguliers atteignent la destination.","yesNoMeaning":"L''équilibre et la patience apportent l''harmonie — un oui mesuré, pris un pas stable à la fois."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('devil', 'fr', '{"name":"Le Diable","meaning":"Méfiez-vous de l''attachement, de la tentation ou d''un schéma contraignant. Reconnaissez les chaînes.","advice":"Nomme ce qui te retient et reprends ta liberté — la chaîne ne te lie que si tu le permets.","yesNoMeaning":"L''attachement ou un schéma contraignant fait obstacle — pas encore, jusqu''à ce que la chaîne soit nommée et brisée."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('tower', 'fr', '{"name":"La Tour","meaning":"Un changement soudain brise le faux et révèle la vérité. Ce qui tombe n''était jamais destiné à tenir.","advice":"Accueillez le bouleversement ; des décombres, une fondation plus claire peut être construite.","yesNoMeaning":"Un changement soudain brise l''ancien — le sol doit se stabiliser avant qu''un oui ferme soit possible."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('star', 'fr', '{"name":"L''Étoile","meaning":"L''espoir, la guérison et l''inspiration tranquille renouvellent votre esprit après la tempête.","advice":"Faites confiance à la lumière qui vous attend et continuez à croire — vos souhaits sont à portée de main.","yesNoMeaning":"L''espoir et le renouveau tranquille indiquent oui — faites confiance à la lumière à venir et gardez votre souhait vivant."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('moon', 'fr', '{"name":"La Lune","meaning":"L''illusion et l''incertitude brouillent le chemin. Faites confiance à votre intuition, pas aux apparences.","advice":"Ralentissez et regardez plus profondément ; la clarté viendra lorsque le brouillard se dissipe.","yesNoMeaning":"L''illusion et l''incertitude brouillent le chemin — la réponse n''est pas claire tant que vous ne regardez pas au-delà des apparences."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('sun', 'fr', '{"name":"Le Soleil","meaning":"Joie, succès et clarté éclatante. Tout est lumineux et plein de vie.","advice":"Célébrez et brillez — l''énergie positive attire les résultats que vous désirez.","yesNoMeaning":"La joie et une clarté radieuse confirment un oui éclatant — tout fonctionne en votre faveur."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('judgement', 'fr', '{"name":"Jugement","meaning":"Un appel à se lever, à se renouveler et à être honnête avec soi-même. Un verdict d''éveil.","advice":"Répondez à l''appel avec courage ; pardonnez le passé et entrez dans votre prochain chapitre.","yesNoMeaning":"Un appel à se lever et à se renouveler — oui, surtout une fois que vous avez pardonné le passé et répondu honnêtement."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('world', 'fr', '{"name":"Le Monde","meaning":"Accomplissement et plénitude — un cycle se termine dans une complétude parfaite.","advice":"Célébrez ce que vous avez accompli ; la porte est ouverte vers un monde plus vaste.","yesNoMeaning":"Accomplissement et plénitude marquent cela comme un oui accompli — le cycle se termine en votre faveur."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-wands', 'fr', '{"name":"As de Bâtons","meaning":"Une étincelle d''inspiration ouvre un chemin créatif audacieux.","advice":"Commencez pendant que l''énergie est fraîche et donnez à l''idée un véritable premier pas.","yesNoMeaning":"L''As de Bâtons penche pour oui : commencez tant que l''énergie est fraîche et donnez à l''idée un vrai premier pas."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-wands', 'fr', '{"name":"Deux de Bâtons","meaning":"Un avenir se dessine à travers la planification et un choix de direction.","advice":"Regarde au-delà de ce qui est familier, puis engage-toi sur le chemin avec de la place pour grandir.","yesNoMeaning":"Le Deux de Bâtons reste conditionnel : regardez au-delà de ce qui est familier, puis engagez-vous sur le chemin offrant de la place pour grandir."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-wands', 'fr', '{"name":"Trois de Bâtons","meaning":"Un effort précoce s''élargit à mesure que des opportunités et des horizons plus larges apparaissent.","advice":"Continuez à construire et soyez prêt à faire face à la réaction que votre travail suscite.","yesNoMeaning":"Le Trois de Bâtons penche vers oui : continuez à construire et soyez prêt à rencontrer la réponse que votre travail attire."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-wands', 'fr', '{"name":"Quatre de Bâtons","meaning":"Stabilité, accueil et célébration partagée créent une base solide.","advice":"Marquez l''étape et laissez les personnes de soutien en profiter.","yesNoMeaning":"Le Quatre de Bâtons penche vers oui : marquez l''étape et laissez les personnes de soutien en profiter."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-wands', 'fr', '{"name":"Cinq de Bâtons","meaning":"Des objectifs concurrents créent friction, bruit ou mise à l''épreuve de la confiance.","advice":"Transformez la rivalité en pratique utile et refusez les conflits qui n''ont aucun but.","yesNoMeaning":"Le Cinq de Bâtons reste conditionnel : transformez la rivalité en pratique utile et refusez le conflit qui n''a aucun but."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-wands', 'fr', '{"name":"Six de Bâtons","meaning":"La reconnaissance suit un effort déterminé et des progrès visibles.","advice":"Acceptez l''encouragement, mais gardez votre confiance liée à un travail honnête.","yesNoMeaning":"Le Six de Bâtons penche vers oui : acceptez les encouragements, mais gardez votre confiance liée à un travail honnête."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-wands', 'fr', '{"name":"Sept de Bâtons","meaning":"Vous maintenez une position précieuse tandis que la pression teste votre détermination.","advice":"Défendez ce qui compte avec des limites claires au lieu de combattre chaque défi.","yesNoMeaning":"Le Sept de Bâtons penche vers oui : défendez ce qui compte avec des limites claires plutôt que de combattre chaque défi."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-wands', 'fr', '{"name":"Huit de Baguettes","meaning":"Les événements s''accélèrent, les messages arrivent et l''élan supprime les retards.","advice":"Agissez rapidement et maintenez une communication directe tant que la voie est ouverte.","yesNoMeaning":"Le Huit de Bâtons penche pour oui : agissez rapidement et gardez la communication directe tant que le chemin est ouvert."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-wands', 'fr', '{"name":"Neuf de Bâtons","meaning":"La résilience est forte, bien que les tensions passées vous rendent vigilant.","advice":"Protégez votre énergie et faites le prochain pas sans vous attendre à ce que chaque blessure se répète.","yesNoMeaning":"Le Neuf de Bâtons reste conditionnel : protégez votre énergie et faites le prochain pas sans vous attendre à ce que chaque blessure se répète."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-wands', 'fr', '{"name":"Dix de Bâtons","meaning":"La responsabilité est devenue lourde et le succès porte désormais un fardeau.","advice":"Déléguez, simplifiez et abandonnez le travail qui n''est plus vraiment le vôtre.","yesNoMeaning":"Le Dix de Bâtons penche vers non : déléguez, simplifiez et laissez tomber le travail qui n''est plus vraiment le vôtre."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-wands', 'fr', '{"name":"Valet de Bâtons","meaning":"La curiosité apporte un message vivant, une expérience ou un nouvel intérêt créatif.","advice":"Explorez avec courage et laissez l''énergie du débutant vous enseigner par l''action.","yesNoMeaning":"Le Valet de Bâtons penche vers le oui : explorez avec courage et laissez l''énergie de débutant vous enseigner par l''action."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-wands', 'fr', '{"name":"Chevalier de Bâtons","meaning":"La passion avance rapidement, apportant aventure et possible impatience.","advice":"Utilisez l''élan, mais choisissez une direction avant que la vitesse ne disperse vos efforts.","yesNoMeaning":"Le Chevalier de Bâtons reste conditionnel : utilisez l''élan, mais choisissez une direction avant que la vitesse ne disperse votre effort."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-wands', 'fr', '{"name":"Reine de Bâtons","meaning":"Une confiance chaleureuse et une indépendance créative attirent les autres vers votre vision.","advice":"Faites confiance à votre présence, encouragez les autres et ne réduisez pas votre ambition.","yesNoMeaning":"La Reine de Bâtons penche oui : faites confiance à votre présence, encouragez les autres et ne réduisez pas votre ambition."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-wands', 'fr', '{"name":"Roi de Bâtons","meaning":"Une vision mature transforme l''inspiration en leadership décisif et éthique.","advice":"Dirigez à partir d''un objectif plus grand et donnez aux autres l''espace pour contribuer.","yesNoMeaning":"Le Roi de Bâtons penche vers oui : dirigez-vous à partir d''un objectif plus large et donnez aux autres l''espace pour contribuer."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-cups', 'fr', '{"name":"As de Coupes","meaning":"Le cœur s''ouvre à de nouveaux sentiments, à la compassion et au renouveau émotionnel.","advice":"Recevez le sentiment honnêtement et laissez le soin couler sans forcer un résultat.","yesNoMeaning":"L''As de Coupes penche vers le oui : Recevez le sentiment honnêtement et laissez l''attention circuler sans forcer un résultat."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-cups', 'fr', '{"name":"Deux de Coupes","meaning":"La reconnaissance mutuelle crée un partenariat, une attraction ou un accord sincère.","advice":"Rencontrez l''autre personne en tant qu''égal et parlez avec le cœur.","yesNoMeaning":"Le Deux de Coupes penche vers oui : rencontrez l''autre personne en tant qu''égal et parlez avec le cœur."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-cups', 'fr', '{"name":"Trois de Coupes","meaning":"L''amitié, la communauté et la joie partagée apportent un soutien émotionnel.","advice":"Célébrez ensemble et souvenez-vous de ceux qui se présentent vraiment pour vous.","yesNoMeaning":"Le Trois de Coupes penche vers oui : célébrez ensemble et souvenez-vous de ceux qui se présentent réellement pour vous."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-cups', 'fr', '{"name":"Quatre de Coupes","meaning":"Le retrait émotionnel rend difficile de remarquer un cadeau disponible.","advice":"Mettez la comparaison en pause et regardez à nouveau ce qui est tranquillement offert.","yesNoMeaning":"Le Quatre de Coupes penche vers non : pausez la comparaison et regardez à nouveau ce qui est offert silencieusement."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-cups', 'fr', '{"name":"Cinq de Coupes","meaning":"La perte attire l''attention sur ce qui s''est répandu tandis que quelque chose de significatif reste.","advice":"Honorez la déception, puis tournez-vous vers le soutien toujours présent.","yesNoMeaning":"Le Cinq de Coupes penche vers non : honorez la déception, puis tournez-vous vers le soutien encore présent."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-cups', 'fr', '{"name":"Six de Coupes","meaning":"La mémoire, l''innocence ou un lien familier revient avec une chaleur douce.","advice":"Accueillez la gentillesse du passé sans prétendre que vous devez y vivre à nouveau.","yesNoMeaning":"Le Six de Coupes penche vers oui : accueillez la gentillesse du passé sans prétendre que vous devez y vivre à nouveau."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-cups', 'fr', '{"name":"Sept de Coupes","meaning":"De nombreuses possibilités attrayantes brouillent la différence entre vision et illusion.","advice":"Réduisez les choix et testez un rêve contre la réalité avant de vous engager.","yesNoMeaning":"Le Sept de Coupes n''est pas encore clair : restreignez les choix et testez un rêve contre la réalité avant de vous engager."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-cups', 'fr', '{"name":"Huit de Coupes","meaning":"Une situation autrefois significative ne nourrit plus le cœur.","advice":"Partez avec honnêteté et allez vers l''épanouissement plus profond dont vous avez maintenant besoin.","yesNoMeaning":"Le Huit de Coupes penche pour non : partez avec honnêteté et avancez vers la satisfaction plus profonde dont vous avez maintenant besoin."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-cups', 'fr', '{"name":"Neuf de Coupes","meaning":"Le contentement et la gratitude rendent un souhait sincère proche de se réaliser.","advice":"Appréciez ce qui est ici et demandez-vous si le souhait sert également vos valeurs profondes.","yesNoMeaning":"Le Neuf de Coupes penche oui : profitez de ce qui est là et demandez si le souhait sert également vos valeurs profondes."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-cups', 'fr', '{"name":"Dix de Coupes","meaning":"Harmonie émotionnelle, sentiment d''appartenance et connexion durable entourent le foyer.","advice":"Entretenez les liens qui rendent la joie durable et partagée.","yesNoMeaning":"Le Dix de Coupes penche vers oui : entretenez les liens qui rendent la joie durable et partagée."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-cups', 'fr', '{"name":"Valet de Coupes","meaning":"Un message tendre ou une découverte intuitive invite à l''ouverture émotionnelle.","advice":"Restez curieux du ressenti et répondez avec sincérité plutôt qu''avec des suppositions.","yesNoMeaning":"Le Valet de Coupes reste conditionnel : restez curieux du sentiment et répondez avec sincérité plutôt qu''avec des suppositions."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-cups', 'fr', '{"name":"Chevalier de Coupes","meaning":"Le romantisme, l''imagination ou un idéal attire le cœur vers l''avant.","advice":"Suivez l''invitation, mais gardez un pied sur terre à mesure que les promesses se réalisent.","yesNoMeaning":"Le Cavalier de Coupes penche vers oui : suivez l''invitation, mais gardez un pied sur terre pendant que les promesses se réalisent."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-cups', 'fr', '{"name":"Reine de Coupes","meaning":"Une profonde empathie et intuition créent un espace calme pour la vérité.","advice":"Écoutez avec compassion tout en préservant les limites qui maintiennent les soins en bonne santé.","yesNoMeaning":"La Reine de Coupes penche vers le oui : écoutez avec compassion tout en préservant les limites qui maintiennent le soin en bonne santé."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-cups', 'fr', '{"name":"Roi de Coupes","meaning":"Maturité émotionnelle stabilise les sentiments forts sans les réprimer.","advice":"Répondez avec compassion et maîtrise de soi, surtout lorsque les autres sont réactifs.","yesNoMeaning":"Le Roi de Coupes penche vers oui : répondez avec compassion et maîtrise de soi, surtout lorsque les autres réagissent."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-swords', 'fr', '{"name":"As d''Épées","meaning":"Une vision claire perce la confusion et révèle une nouvelle vérité.","advice":"Nommez le problème clairement et utilisez la clarté au service d''une décision juste.","yesNoMeaning":"L''As d''Épées penche pour oui : nommez le problème clairement et utilisez la clarté au service d''une décision juste."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-swords', 'fr', '{"name":"Deux d''Épées","meaning":"Un impasse prudente retarde un choix qui ne peut rester en suspens éternellement.","advice":"Retirez le bandeau doucement, rassemblez le fait manquant et décidez à partir de l''équilibre.","yesNoMeaning":"Les Deux d''Épées ne sont pas encore clairs : retirez le bandeau doucement, rassemblez le fait manquant, et décidez à partir de l''équilibre."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-swords', 'fr', '{"name":"Trois d''Épées","meaning":"Une vérité douloureuse, une séparation ou une déception demande à être reconnue.","advice":"Laissez le sentiment vous traverser et évitez de transformer la douleur en une histoire permanente.","yesNoMeaning":"Le Trois d''Épées penche non : laissez le sentiment vous traverser et évitez de transformer la douleur en une histoire permanente."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-swords', 'fr', '{"name":"Quatre d''Épées","meaning":"Le repos et le calme mental sont nécessaires après une pression ou un conflit.","advice":"Faites une pause avant de répondre ; la récupération est productive quand elle restaure la clarté de la pensée.","yesNoMeaning":"Le Quatre d''Épées penche vers non : pausez avant de répondre ; le rétablissement est productif lorsqu''il restaure la clarté de la pensée."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-swords', 'fr', '{"name":"Cinq d''Épées","meaning":"Le conflit peut produire une victoire creuse ou laisser la confiance endommagée.","advice":"Choisissez la dignité plutôt que la victoire et éloignez-vous de tactiques trop coûteuses.","yesNoMeaning":"Le Cinq d''Épées penche vers non : choisissez la dignité plutôt que la victoire et éloignez-vous des tactiques qui coûtent trop."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-swords', 'fr', '{"name":"Six d''Épées","meaning":"Un passage difficile évolue progressivement vers des conditions plus calmes.","advice":"Prenez ce que vous avez appris, acceptez le soutien et continuez à vous éloigner du tumulte.","yesNoMeaning":"Le Six d''Épées penche vers oui : prenez ce que vous avez appris, acceptez le soutien et continuez à vous éloigner des tourments."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-swords', 'fr', '{"name":"Sept d''Épées","meaning":"Stratégie, secret ou évitement compliquent le chemin.","advice":"Agis avec intelligence mais en toute transparence ; les raccourcis qui trahissent la confiance reviendront sous forme de problèmes.","yesNoMeaning":"Le Sept d''Épées penche vers le non : agissez intelligemment mais de manière transparente ; les raccourcis qui trahissent la confiance reviendront sous forme de problèmes."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-swords', 'fr', '{"name":"Huit d''Épées","meaning":"La peur et les croyances restrictives rendent difficiles à voir les options disponibles.","advice":"Remettez en question la pensée qui dit que vous êtes piégé et prenez une petite action libératrice.","yesNoMeaning":"Le Huit d''Épées penche pour non : remettez en question la pensée qui dit que vous êtes piégé et faites une petite action libératrice."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-swords', 'fr', '{"name":"Neuf d''Épées","meaning":"L''anxiété amplifie le danger dans l''obscurité et épuise l''esprit.","advice":"Amenez la peur à la lumière du jour, cherchez du soutien et séparez les faits des résultats imaginés.","yesNoMeaning":"Le Neuf d''Épées penche non : mettez la peur au grand jour, cherchez du soutien et séparez les faits des résultats imaginés."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-swords', 'fr', '{"name":"Dix d''Épées","meaning":"Un cycle douloureux atteint sa limite finale et ne peut pas continuer inchangé.","advice":"Acceptez la fin, protégez votre rétablissement et permettez à un nouveau début d''émerger.","yesNoMeaning":"Le Dix d''Épées penche vers non : acceptez la fin, protégez votre rétablissement et permettez à un autre commencement d''émerger."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-swords', 'fr', '{"name":"Valet d’Épées","meaning":"La curiosité alerte recherche des faits, pose des questions et observe les changements.","advice":"Recherchez soigneusement et parlez avec précision plutôt que de réagir à chaque signal.","yesNoMeaning":"Le Valet d''Épées reste conditionnel : faites des recherches avec soin et parlez avec précision plutôt que de réagir à chaque signal."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-swords', 'fr', '{"name":"Chevalier d''Épées","meaning":"Un intellect concentré agit rapidement et affronte directement les obstacles.","advice":"Avancez avec courage, mais assez lentement pour entendre ce que votre certitude pourrait manquer.","yesNoMeaning":"Le Chevalier d''Épées reste conditionnel : avancez avec courage, mais assez lentement pour entendre ce que votre certitude pourrait manquer."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-swords', 'fr', '{"name":"Reine d''Épées","meaning":"La perception claire et des limites honnêtes éliminent la confusion.","advice":"Dis ce qui est vrai avec compassion et laisse l''expérience t''affûter, pas te durcir.","yesNoMeaning":"La Reine d''Épées penche vers le oui : dites ce qui est vrai avec compassion et laissez l''expérience vous affûter, non vous durcir."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-swords', 'fr', '{"name":"Roi d''Épées","meaning":"La raison, l''équité et un jugement discipliné guident une décision importante.","advice":"Utilisez des preuves, définissez la norme et écartez les préjugés personnels du verdict.","yesNoMeaning":"Le Roi d''Épées penche vers oui : utilisez des preuves, définissez la norme et gardez les préjugés personnels hors du verdict."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-pentacles', 'fr', '{"name":"As de Pentacles","meaning":"Une opportunité tangible offre la graine de prospérité, de travail ou de bien-être.","advice":"Ancrez l''opportunité dans un plan pratique et prenez-en soin de manière constante.","yesNoMeaning":"L''As de Pentacles penche vers le oui : Ancrez l''opportunité dans un plan pratique et prenez-en soin régulièrement."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-pentacles', 'fr', '{"name":"Deux de Pentacles","meaning":"Plusieurs priorités avancent en même temps et nécessitent un équilibre flexible.","advice":"Ajustez le rythme, protégez l''essentiel et évitez de promettre plus que ce que vous pouvez porter.","yesNoMeaning":"Le Deux de Pentacles reste conditionnel : ajustez le rythme, protégez l''essentiel et évitez de promettre plus que ce que vous pouvez porter."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-pentacles', 'fr', '{"name":"Trois de Pentacles","meaning":"La compétence croît grâce à la collaboration, aux retours et au travail minutieux.","advice":"Apportez votre force, respectez l''expertise et construisez selon une norme partagée.","yesNoMeaning":"Les Trois de Pentacles penchent pour oui : apportez votre force, respectez l''expertise et construisez selon une norme partagée."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-pentacles', 'fr', '{"name":"Quatre de Pentacles","meaning":"S''accrocher fermement à la sécurité peut préserver les ressources mais restreindre le flux sain.","advice":"Protégez ce qui compte sans laisser la peur prendre toutes vos décisions.","yesNoMeaning":"Le Quatre de Pentacles reste conditionnel : protégez ce qui compte sans laisser la peur dicter chaque décision."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-pentacles', 'fr', '{"name":"Cinq de Pentacles","meaning":"La tension ou l''exclusion matérielle crée de l''inquiétude et un sentiment de rareté.","advice":"Demandez une aide pratique et remarquez la porte que les difficultés ont rendue facile à négliger.","yesNoMeaning":"Le Cinq de Pentacles penche vers non : demandez de l''aide pratique et remarquez la porte que les difficultés ont rendu facile à négliger."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-pentacles', 'fr', '{"name":"Six de Pentacles","meaning":"Les ressources sont échangées, soulevant des questions de générosité, de pouvoir et d''équité.","advice":"Donner ou recevoir avec des termes clairs afin que le soutien préserve la dignité des deux côtés.","yesNoMeaning":"Le Six de Pentacles penche pour oui : donner ou recevoir avec des conditions claires afin que le soutien préserve la dignité des deux côtés."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-pentacles', 'fr', '{"name":"Sept de Pentacles","meaning":"L’investissement patient atteint un point d’évaluation avant le prochain effort.","advice":"Examine ce qui pousse, améliorez la méthode et donnez du temps aux résultats valables.","yesNoMeaning":"Le Sept de Pentacles reste conditionnel : examinez ce qui pousse, améliorez la méthode et laissez le temps aux résultats valables."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-pentacles', 'fr', '{"name":"Huit de Deniers","meaning":"La répétition concentrée développe la maîtrise et des résultats fiables.","advice":"Pratiquez la compétence essentielle, accueillez la correction et laissez la qualité s''accumuler.","yesNoMeaning":"Le Huit de Pentacles penche pour oui : pratiquez la compétence essentielle, accueillez les corrections et laissez la qualité s''accumuler."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-pentacles', 'fr', '{"name":"Neuf de Pentacles","meaning":"L''indépendance et le confort cultivé reflètent un progrès discipliné.","advice":"Profitez de ce que vous avez construit et maintenez l''indépendance liée à la gratitude.","yesNoMeaning":"Le Neuf de Pentacles penche oui : profitez de ce que vous avez construit et gardez l''indépendance reliée à la gratitude."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-pentacles', 'fr', '{"name":"Dix de Pentacles","meaning":"La sécurité à long terme se développe grâce à l''héritage, la famille et les fondations partagées.","advice":"Planifiez au-delà du gain immédiat et protégez ce qui peut soutenir les autres au fil du temps.","yesNoMeaning":"Le Dix de Pentacles penche vers oui : planifiez au-delà du gain immédiat et protégez ce qui peut soutenir les autres sur le long terme."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-pentacles', 'fr', '{"name":"Valet de Pentacles","meaning":"Un message pratique invite à l''étude, à la planification ou à une nouvelle entreprise concrète.","advice":"Apprenez les bases, définissez la prochaine tâche et prouvez l''idée par un travail constant.","yesNoMeaning":"Le Valet de Pentacles penche vers le oui : apprenez les bases, définissez la tâche suivante et démontrez l''idée par un travail régulier."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-pentacles', 'fr', '{"name":"Chevalier de Deniers","meaning":"Un effort fiable progresse lentement mais abandonne rarement la tâche.","advice":"Gardez la routine honnête et cohérente ; le progrès compte plus que l''excitation.","yesNoMeaning":"Le Cavalier de Pentacles penche vers oui : maintenez la routine honnête et cohérente ; le progrès compte plus que l''excitation."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-pentacles', 'fr', '{"name":"Reine de Pentacles","meaning":"Des soins ingénieux créent le confort, la santé et l''abondance pratique.","advice":"Nourrissez les personnes et les projets d’une manière qui reste durable pour vous.","yesNoMeaning":"La Reine de Pentacles penche vers le oui : nourrissez les personnes et les plans de manière à rester durable pour vous."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-pentacles', 'fr', '{"name":"Roi de Pentacles","meaning":"Le leadership matériel transforme l''expérience en gérance stable et généreuse.","advice":"Faites le choix sonore à long terme et utilisez le succès de manière responsable.","yesNoMeaning":"Le Roi de Pentacles penche vers oui : faites le choix solide à long terme et utilisez le succès de manière responsable."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aries', 'fr', '{"name":"Bélier","dateRange":"21 mars – 19 avril","rulingPlanet":"Mars","summary":"Les débuts audacieux et l''action directe définissent le Bélier, dont l''étincelle transforme l''intention en élan.","originStory":"Le Bélier est lié au bélier d''or qui a sauvé Phrixos dans la mythologie grecque. Sa toison est ensuite devenue le prix de Jason et des Argonautes, conservant le signe comme symbole de courage, de sauvetage et du premier pas courageux.","traits":["Courageux","Énergique","Indépendant","Direct"],"strengths":["Initiative","Confiance","Résilience"],"challenges":["Impatience","Impulsivité","Commencer plus vite que ce que vous pouvez soutenir"],"compatibleSigns":["Lion","Sagittaire","Gémeaux"],"reflectionPrompt":"Choisissez un début courageux et donnez-lui suffisamment de patience pour grandir."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'day', 'fr', '{"overview":"Aujourd''hui favorise une étape claire et intentionnelle. Le Bélier traverse l''énergie du feu. Des débuts audacieux et une action directe définissent le Bélier, dont l''étincelle transforme l''intention en élan.","love":"En amour aujourd''hui, choisissez la présence plutôt que les suppositions. Vos dons d''initiative, de confiance et de résilience peuvent vous aider à vous connecter sans jouer un rôle.","career":"Au travail, accomplissez la tâche la plus significative avant de chercher un nouvel élan. Utilisez courageux, énergique, indépendant, direct comme des outils, pas comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Gardez les choix financiers d''aujourd''hui simples et ancrés. Remarquez quand l''impatience, l''impulsivité, le fait de commencer plus vite que vous ne pouvez soutenir commence à influencer une décision pratique.","wellbeing":"Une petite pause peut réinitialiser votre énergie. Choisissez un début courageux et donnez-lui assez de patience pour grandir.","guidance":"Avant que la journée ne se termine, souvenez-vous : Choisissez un début courageux et accordez-lui suffisamment de patience pour grandir."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'week', 'fr', '{"overview":"Cette semaine se développe à travers des choix constants plutôt qu''un moment dramatique. Le Bélier évolue à travers l''énergie du feu. Des débuts audacieux et une action directe définissent le Bélier, dont l''étincelle transforme l''intention en élan.","love":"Les relations bénéficient d''une conversation qui laisse de la place à la fois à l''honnêteté et à la chaleur. Vos dons d''initiative, de confiance et de résilience peuvent vous aider à établir des liens sans avoir à jouer un rôle.","career":"Votre meilleur progrès professionnel vient du choix d''une priorité et de la protection du temps pour celle-ci. Utilisez le courage, l''énergie, l''indépendance et la franchise comme outils, et non comme des attentes à satisfaire toutes en même temps.","finance":"Examinez le schéma de vos dépenses avant de prendre un engagement plus important. Remarquez quand l''impatience, l''impulsivité, commencer plus vite que ce que vous pouvez soutenir commencent à influencer une décision pratique.","wellbeing":"Équilibrez le mouvement avec une récupération véritable tout au long de la semaine. Choisissez un début courageux et donnez-lui suffisamment de patience pour grandir.","guidance":"Laissez cette question guider la semaine : Choisissez un début courageux et donnez-lui assez de patience pour grandir."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'year', 'fr', '{"overview":"Cette année invite à une croissance patiente autour de l''identité, du but et de la façon dont vous utilisez votre énergie. Le Bélier évolue à travers l''énergie du feu. Les débuts audacieux et l''action directe définissent le Bélier, dont l''étincelle transforme l''intention en élan.","love":"L''amour s''approfondit lorsque vous pratiquez la constance et permettez à la connexion d''évoluer à un rythme humain. Vos dons d''initiative, de confiance et de résilience peuvent vous aider à vous connecter sans avoir à performer.","career":"Le travail à long terme devient plus solide lorsque l''ambition est associée à une structure que vous pouvez maintenir. Utilisez courageux, énergique, indépendant, direct comme des outils, et non comme des attentes que vous devez satisfaire toutes à la fois.","finance":"Construisez la confiance financière grâce à des habitudes répétables plutôt qu''à des prévisions parfaites. Remarquez quand l''impatience, l''impulsivité, le fait de commencer plus vite que vous ne pouvez soutenir commencent à influencer une décision pratique.","wellbeing":"Considérez le bien-être comme une fondation pour la vie que vous construisez, et non comme une récompense après l''avoir terminée. Choisissez un commencement courageux et accordez-lui suffisamment de patience pour grandir.","guidance":"Revenez à cette boussole tout au long de l''année : Choisissez un début courageux et donnez-lui suffisamment de patience pour grandir."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('taurus', 'fr', '{"name":"Taureau","dateRange":"20 avril – 20 mai","rulingPlanet":"Vénus","summary":"Stable, sensuel et enraciné, le Taureau construit une valeur durable par la patience et le soin.","originStory":"Le Taureau rappelle Zeus prenant la forme d''un magnifique taureau blanc pour transporter Europe à travers la mer. L''image est devenue associée à la beauté, la fertilité, l''abondance terrestre et le pouvoir exprimé à travers une persistance calme.","traits":["Ancré","Loyal","Patient","Sensuel"],"strengths":["Fiabilité","Sagesse pratique","Dévotion"],"challenges":["Entêtement","Résistance au changement","S''accrocher trop longtemps"],"compatibleSigns":["Vierge","Capricorne","Cancer"],"reflectionPrompt":"Protégez ce qui compte sans confondre le confort avec la permanence."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'day', 'fr', '{"overview":"Aujourd''hui favorise une étape claire et intentionnelle. Le Taureau avance à travers l''énergie de la terre. Stable, sensuel et ancré, le Taureau construit une valeur durable grâce à la patience et au soin.","love":"En amour aujourd''hui, choisissez la présence plutôt que les suppositions. Vos dons de fiabilité, de sagesse pratique, de dévotion peuvent vous aider à vous connecter sans devoir jouer un rôle.","career":"Au travail, accomplissez la tâche la plus significative avant de chercher un nouvel élan. Utilisez les qualités d''être ancré, loyal, patient, sensuel comme des outils, et non comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Gardez les choix financiers d''aujourd''hui simples et réalistes. Remarquez quand l''obstination, la résistance au changement ou le fait de s''accrocher trop longtemps commencent à influencer une décision pratique.","wellbeing":"Une petite pause peut réinitialiser votre énergie. Protégez ce qui compte sans confondre le confort avec la permanence.","guidance":"Avant que la journée ne se termine, souvenez-vous : Protégez ce qui compte sans confondre confort et permanence."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'week', 'fr', '{"overview":"Cette semaine se développe à travers des choix réguliers plutôt que par un moment dramatique. Le Taureau traverse l''énergie de la terre. Stable, sensuel et ancré, le Taureau construit une valeur durable grâce à la patience et au soin.","love":"Les relations bénéficient d''une conversation qui laisse de la place à la fois à l''honnêteté et à la chaleur. Vos qualités de fiabilité, de sagesse pratique et de dévouement peuvent vous aider à vous connecter sans jouer un rôle.","career":"Vos meilleurs progrès professionnels viennent de choisir une priorité et de protéger du temps pour celle-ci. Utilisez ancré, loyal, patient, sensuel comme outils, et non comme attentes que vous devez satisfaire toutes à la fois.","finance":"Examinez le schéma de vos dépenses avant de prendre un engagement plus important. Remarquez quand l''obstination, la résistance au changement, ou le fait de s''accrocher trop longtemps commencent à influencer une décision pratique.","wellbeing":"Équilibrez le mouvement avec une récupération authentique tout au long de la semaine. Protégez ce qui compte sans confondre confort et permanence.","guidance":"Laissez cette question guider la semaine : Protégez ce qui compte sans confondre confort et permanence."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'year', 'fr', '{"overview":"Cette année invite à une croissance patiente autour de l''identité, du but et de la façon dont vous utilisez votre énergie. Le Taureau évolue dans l''énergie de la terre. Stable, sensuel et ancré, le Taureau construit une valeur durable grâce à la patience et au soin.","love":"L''amour s''approfondit lorsque vous pratiquez la constance et permettez à la connexion d''évoluer à un rythme humain. Vos dons de fiabilité, de sagesse pratique et de dévouement peuvent vous aider à vous connecter sans avoir à jouer un rôle.","career":"Le travail à long terme devient plus solide lorsque l''ambition est associée à une structure que vous pouvez soutenir. Utilisez les qualités ancrées, loyales, patientes et sensuelles comme des outils, et non comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Renforcez votre confiance financière grâce à des habitudes répétables plutôt qu''à des prévisions parfaites. Remarquez quand l''entêtement, la résistance au changement ou le fait de s''accrocher trop longtemps commence à influencer une décision pratique.","wellbeing":"Considérez le bien-être comme une base pour la vie que vous construisez, et non comme une récompense après l''avoir terminée. Protégez ce qui compte sans confondre le confort avec la permanence.","guidance":"Revenez à cette boussole tout au long de l''année : Protégez ce qui compte sans confondre le confort avec la permanence."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('gemini', 'fr', '{"name":"Gémeaux","dateRange":"21 mai – 20 juin","rulingPlanet":"Mercure","summary":"La curiosité et la connexion guident les Gémeaux, qui rassemblent des idées et révèlent plus d''un côté d''une histoire.","originStory":"Les Gémeaux représentent Castor et Pollux, des jumeaux inséparables qui ont partagé l''immortalité plutôt que de rester séparés. Leur constellation porte des thèmes de compagnie, de double perspective, de communication et de passage entre les mondes.","traits":["Curieux","Adaptable","Expressif","À l''esprit vif"],"strengths":["Communication","Polyvalence","Apprentissage rapide"],"challenges":["Agitation","Concentration dispersée","Trop réfléchir"],"compatibleSigns":["Balance","Verseau","Bélier"],"reflectionPrompt":"Laissez la curiosité ouvrir la porte, puis restez assez longtemps pour comprendre ce que vous trouvez."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'day', 'fr', '{"overview":"Aujourd''hui favorise une étape claire et intentionnelle. Les Gémeaux se déplacent à travers l''énergie de l''air. La curiosité et la connexion guident les Gémeaux, qui rassemblent des idées et révèlent plus d''un aspect d''une histoire.","love":"En amour aujourd''hui, choisissez la présence plutôt que l''hypothèse. Vos dons de communication, de polyvalence, d''apprentissage rapide peuvent vous aider à vous connecter sans performer.","career":"Au travail, accomplissez la tâche la plus significative avant de poursuivre un nouvel élan. Utilisez curieux, adaptable, expressif, vif d''esprit comme des outils, pas comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Gardez les choix financiers d''aujourd''hui simples et ancrés. Remarquez quand l''agitation, la concentration dispersée ou la réflexion excessive commencent à influencer une décision pratique.","wellbeing":"Une petite pause peut réinitialiser votre énergie. Laissez la curiosité ouvrir la porte, puis restez assez longtemps pour comprendre ce que vous trouvez.","guidance":"Avant que la journée ne se termine, souvenez-vous : Laissez la curiosité ouvrir la porte, puis restez assez longtemps pour comprendre ce que vous trouvez."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'week', 'fr', '{"overview":"Cette semaine se développe à travers des choix constants plutôt que par un moment dramatique. Le Gémeaux évolue à travers l''énergie de l''air. La curiosité et la connexion guident les Gémeaux, qui rassemblent des idées et révèlent plus d''un aspect d''une histoire.","love":"Les relations bénéficient d''une conversation qui laisse place à la fois à l''honnêteté et à la chaleur. Vos dons de communication, de polyvalence, d''apprentissage rapide peuvent vous aider à vous connecter sans jouer un rôle.","career":"Vos meilleurs progrès professionnels viennent de choisir une priorité et de protéger du temps pour celle-ci. Utilisez curieux, adaptable, expressif, vif d''esprit comme outils, et non comme attentes que vous devez satisfaire toutes à la fois.","finance":"Examinez le schéma de vos dépenses avant de prendre un engagement plus important. Remarquez quand l''agitation, la concentration dispersée et la sur-réflexion commencent à influencer une décision pratique.","wellbeing":"Équilibrez le mouvement avec une récupération véritable tout au long de la semaine. Laissez la curiosité ouvrir la porte, puis restez assez longtemps pour comprendre ce que vous trouvez.","guidance":"Laissez cette question guider la semaine : Laissez la curiosité ouvrir la porte, puis restez assez longtemps pour comprendre ce que vous trouvez."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'year', 'fr', '{"overview":"Cette année invite à une croissance patiente autour de l''identité, du but et de la façon dont vous utilisez votre énergie. Les Gémeaux évoluent à travers l''énergie de l''air. La curiosité et la connexion guident les Gémeaux, qui rassemblent des idées et révèlent plus d''un côté d''une histoire.","love":"L''amour s''approfondit lorsque vous pratiquez la constance et permettez à la connexion d''évoluer à un rythme humain. Vos dons de communication, de polyvalence, d''apprentissage rapide peuvent vous aider à vous connecter sans jouer un rôle.","career":"Le travail à long terme devient plus solide lorsque l''ambition est associée à une structure que vous pouvez maintenir. Utilisez la curiosité, l''adaptabilité, l''expressivité et l''esprit vif comme des outils, et non comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Construisez la confiance financière grâce à des habitudes répétables plutôt qu''à des prédictions parfaites. Remarquez quand l''agitation, la concentration dispersée et la surpensée commencent à influencer une décision pratique.","wellbeing":"Considérez le bien-être comme une base pour la vie que vous construisez, et non comme une récompense après l''avoir terminée. Laissez la curiosité ouvrir la porte, puis restez assez longtemps pour comprendre ce que vous y trouvez.","guidance":"Revenez à cette boussole tout au long de l''année : Laissez la curiosité ouvrir la porte, puis restez assez longtemps pour comprendre ce que vous trouvez."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('cancer', 'fr', '{"name":"Cancer","dateRange":"21 juin – 22 juil.","rulingPlanet":"Lune","summary":"Protectrice et intuitive, le Cancer crée un sentiment d''appartenance en honorant la mémoire, les sentiments et le foyer.","originStory":"Le Cancer est associé au crabe Karkinos, placé parmi les étoiles après avoir montré sa loyauté pendant le combat d''Héraclès contre l''Hydre. Sa carapace et sa domination lunaire reflètent la protection, les marées émotionnelles et la dévotion envers son cercle intime.","traits":["Intuitif","Attentionné","Protecteur","Imaginatif"],"strengths":["Empathie","Loyauté","Perspicacité émotionnelle"],"challenges":["Mauvais humeur","Se replier derrière des défenses","Prendre les choses personnellement"],"compatibleSigns":["Scorpion","Poissons","Taureau"],"reflectionPrompt":"Prenez soin de votre monde intérieur tout en laissant une porte ouverte à une connexion honnête."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'day', 'fr', '{"overview":"Aujourd''hui favorise une étape claire et intentionnelle. Le Cancer se déplace à travers l''énergie de l''eau. Protecteur et intuitif, le Cancer crée un sentiment d''appartenance en honorant la mémoire, les émotions et la maison.","love":"En amour aujourd''hui, choisissez la présence plutôt que les suppositions. Vos dons d''empathie, de loyauté et d''intuition émotionnelle peuvent vous aider à vous connecter sans jouer un rôle.","career":"Au travail, terminez la tâche la plus significative avant de poursuivre un nouvel élan. Utilisez intuitif, attentionné, protecteur, imaginatif comme outils, et non comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Gardez les choix financiers d''aujourd''hui simples et réalistes. Remarquez quand l''humeur changeante, le repli derrière des défenses, la prise des choses personnellement commence à influencer une décision pratique.","wellbeing":"Une petite pause peut réinitialiser votre énergie. Prenez soin de votre monde intérieur tout en laissant une porte ouverte à une connexion honnête.","guidance":"Avant que la journée ne se termine, souvenez-vous : Prenez soin de votre monde intérieur tout en laissant une porte ouverte à une connexion honnête."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'week', 'fr', '{"overview":"Cette semaine se développe à travers des choix constants plutôt qu''un moment dramatique. Le Cancer évolue à travers l''énergie de l''eau. Protecteur et intuitif, le Crabe crée un sentiment d''appartenance en honorant la mémoire, le ressenti et le foyer.","love":"Les relations bénéficient d''une conversation qui laisse de la place à la fois à l''honnêteté et à la chaleur. Vos dons d''empathie, de loyauté et de perspicacité émotionnelle peuvent vous aider à vous connecter sans jouer un rôle.","career":"Votre meilleur progrès professionnel vient du choix d''une priorité et de la protection du temps pour celle-ci. Utilisez intuitif, attentionné, protecteur, imaginatif comme outils, pas comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Examinez le schéma de vos dépenses avant de prendre un engagement plus important. Remarquez quand la mauvaise humeur, le repli derrière des défenses, le fait de prendre les choses personnellement commencent à influencer une décision pratique.","wellbeing":"Équilibrez le mouvement avec une récupération véritable tout au long de la semaine. Prenez soin de votre monde intérieur tout en laissant une porte ouverte à une connexion honnête.","guidance":"Laissez cette question guider la semaine : Prenez soin de votre monde intérieur tout en laissant une porte ouverte à une connexion honnête."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'year', 'fr', '{"overview":"Cette année invite à une croissance patiente autour de l''identité, du but et de la façon dont vous utilisez votre énergie. Le Cancer évolue à travers l''énergie de l''eau. Protecteur et intuitif, le Crabe crée un sentiment d''appartenance en honorant la mémoire, le ressenti et le foyer.","love":"L''amour s''approfondit lorsque vous pratiquez la constance et permettez à la connexion d''évoluer à un rythme humain. Vos dons d''empathie, de loyauté et de perspicacité émotionnelle peuvent vous aider à vous connecter sans jouer un rôle.","career":"Le travail à long terme devient plus solide lorsque l''ambition est associée à une structure que vous pouvez soutenir. Utilisez l''intuition, la bienveillance, la protection et l''imagination comme des outils, et non comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Renforcez votre confiance financière grâce à des habitudes répétables plutôt qu''à des prévisions parfaites. Remarquez quand la mauvaise humeur, le repli derrière des défenses, ou le fait de prendre les choses personnellement commencent à influencer une décision pratique.","wellbeing":"Considérez le bien-être comme une fondation pour la vie que vous construisez, et non comme une récompense après l''avoir achevée. Prenez soin de votre monde intérieur tout en laissant une porte ouverte à une connexion honnête.","guidance":"Revenez à cette boussole tout au long de l''année : Prenez soin de votre monde intérieur tout en laissant une porte ouverte à une connexion honnête."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('leo', 'fr', '{"name":"Lion","dateRange":"23 juil. – 22 août","rulingPlanet":"Soleil","summary":"La chaleur, la créativité et l''expression de soi généreuse font du Lion une source naturelle de lumière.","originStory":"Léo est lié au Lion de Némée, la créature presque invulnérable vaincue lors du premier travail d''Héraclès. Élevé aux cieux, il est devenu un emblème de courage, de présence souveraine et de la force créatrice du Soleil.","traits":["Chaud","Créatif","Généreux","Confiant"],"strengths":["Leadership","Loyauté","Expression sincère"],"challenges":["Fierté","Besoin de reconnaissance","Dramatiser les revers"],"compatibleSigns":["Bélier","Sagittaire","Balance"],"reflectionPrompt":"Partagez généreusement votre lumière et laissez les autres briller à vos côtés."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'day', 'fr', '{"overview":"Aujourd''hui favorise une étape claire et intentionnelle. Le Lion se déplace à travers l''énergie du feu. La chaleur, la créativité et l''expression généreuse de soi font du Lion une source naturelle de lumière.","love":"En amour aujourd''hui, choisissez la présence plutôt que les suppositions. Vos dons de leadership, de loyauté et d''expression sincère peuvent vous aider à vous connecter sans jouer un rôle.","career":"Au travail, accomplissez la tâche la plus significative avant de chercher un nouvel élan. Utilisez chaleureux, créatif, généreux, confiant comme outils, et non comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Gardez les choix financiers d''aujourd''hui simples et ancrés. Remarquez quand la fierté, le besoin de reconnaissance, ou la dramatisation des revers commence à influencer une décision pratique.","wellbeing":"Une petite pause peut recharger votre énergie. Partagez votre lumière généreusement et laissez les autres briller à vos côtés.","guidance":"Avant que la journée ne se termine, souvenez-vous : Partagez votre lumière généreusement et laissez les autres briller à vos côtés."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'week', 'fr', '{"overview":"Cette semaine se développe à travers des choix constants plutôt que par un moment dramatique. Le Lion évolue à travers l''énergie du feu. La chaleur, la créativité et l''expression généreuse de soi font du Lion une source de lumière naturelle.","love":"Les relations bénéficient d''une conversation qui laisse de la place à la fois à l''honnêteté et à la chaleur. Vos dons de leadership, de loyauté et d''expression sincère peuvent vous aider à vous connecter sans avoir à jouer un rôle.","career":"Votre meilleur progrès professionnel vient du choix d''une priorité et de la protection du temps pour celle-ci. Utilisez chaleureux, créatif, généreux, confiant comme outils, pas comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Examinez le schéma de vos dépenses avant de prendre un engagement plus important. Remarquez quand l''orgueil, le besoin de reconnaissance, la dramatisation des revers commencent à influencer une décision pratique.","wellbeing":"Équilibrez le mouvement avec une récupération authentique tout au long de la semaine. Partagez votre lumière généreusement et laissez les autres briller à vos côtés.","guidance":"Laissez cette question guider la semaine : Partagez généreusement votre lumière et laissez les autres briller à vos côtés."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'year', 'fr', '{"overview":"Cette année invite à une croissance patiente autour de l''identité, du but et de la manière dont vous utilisez votre énergie. Leo traverse l''énergie du feu. Chaleur, créativité et expression généreuse de soi font du Lion une source naturelle de lumière.","love":"L''amour s''approfondit lorsque vous pratiquez la constance et permettez à la connexion d''évoluer à un rythme humain. Vos dons de leadership, de loyauté et d''expression sincère peuvent vous aider à vous connecter sans avoir à jouer un rôle.","career":"Le travail à long terme devient plus solide lorsque l''ambition est associée à une structure que vous pouvez soutenir. Utilisez chaleureux, créatif, généreux, confiant comme des outils, et non comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Construisez la confiance financière grâce à des habitudes répétables plutôt qu''à des prédictions parfaites. Remarquez quand l''orgueil, le besoin de reconnaissance, ou la dramatisation des revers commence à influencer une décision pratique.","wellbeing":"Considérez le bien-être comme une base pour la vie que vous êtes en train de construire, et non comme une récompense après l''avoir terminée. Partagez votre lumière généreusement et laissez les autres briller à vos côtés.","guidance":"Revenez à cette boussole tout au long de l''année : Partagez votre lumière généreusement et laissez les autres briller à vos côtés."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('virgo', 'fr', '{"name":"Vierge","dateRange":"23 août – 22 sept","rulingPlanet":"Mercure","summary":"Le discernement et le service guident la Vierge, transformant l''observation attentive en amélioration pratique.","originStory":"La Vierge est souvent associée à Astraea, la jeune fille de la justice qui est restée avec l''humanité après le retrait des autres dieux. Le blé qu''elle porte relie le signe à la récolte, à l''habileté, à la pureté des intentions et au soin de ce qui soutient la vie.","traits":["Observateur","Pratique","Pensif","Précis"],"strengths":["Analyse","Savoir-faire","Service utile"],"challenges":["Perfectionnisme","Autocritique","S''inquiéter des détails"],"compatibleSigns":["Taureau","Capricorne","Cancer"],"reflectionPrompt":"Améliorez ce que vous pouvez, et permettez au bon travail d''être complet avant qu''il soit parfait."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'day', 'fr', '{"overview":"Aujourd''hui favorise une étape claire et intentionnelle. La Vierge avance à travers l''énergie de la terre. Le discernement et le service guident la Vierge, transformant une observation attentive en amélioration pratique.","love":"En amour aujourd''hui, choisissez la présence plutôt que l''hypothèse. Vos dons d''analyse, d''artisanat, de service utile peuvent vous aider à vous connecter sans performer.","career":"Au travail, terminez la tâche la plus significative avant de poursuivre un nouvel élan. Utilisez observateur, pratique, réfléchi, précis comme outils, et non comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Gardez les choix financiers d''aujourd''hui simples et réalistes. Remarquez quand le perfectionnisme, l''autocritique et l''inquiétude pour les détails commencent à influencer une décision pratique.","wellbeing":"Une petite pause peut réinitialiser votre énergie. Améliorez ce que vous pouvez, et permettez à un bon travail d''être complet avant d''être parfait.","guidance":"Avant que la journée ne se termine, souvenez-vous : Améliorez ce que vous pouvez, et permettez à un bon travail d''être complet avant d''être parfait."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'week', 'fr', '{"overview":"Cette semaine se développe à travers des choix constants plutôt qu''un moment dramatique. Vierge évolue à travers l''énergie terrestre. Le discernement et le service guident la Vierge, transformant l''observation attentive en amélioration pratique.","love":"Les relations bénéficient d''une conversation qui laisse place à la fois à l''honnêteté et à la chaleur. Vos dons d''analyse, de savoir-faire, de service utile peuvent vous aider à vous connecter sans jouer un rôle.","career":"Votre meilleur progrès professionnel vient du choix d''une priorité et de la protection du temps pour celle-ci. Utilisez observateur, pratique, réfléchi, précis comme outils, pas comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Examinez le schéma de vos dépenses avant de prendre un engagement plus important. Remarquez quand le perfectionnisme, l''autocritique et l''inquiétude pour les détails commencent à influencer une décision pratique.","wellbeing":"Équilibrez le mouvement avec une récupération véritable tout au long de la semaine. Améliorez ce que vous pouvez, et permettez à un bon travail d''être complet avant qu''il ne soit parfait.","guidance":"Laissez cette question guider la semaine : Améliorez ce que vous pouvez et permettez au bon travail d''être complet avant qu''il ne soit parfait."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'year', 'fr', '{"overview":"Cette année invite à une croissance patiente autour de l''identité, du but et de la façon dont vous utilisez votre énergie. Vierge se déplace à travers l''énergie de la terre. Le discernement et le service guident la Vierge, transformant une observation attentive en amélioration pratique.","love":"L''amour s''approfondit lorsque vous pratiquez la constance et permettez à la connexion d''évoluer à un rythme humain. Vos dons d''analyse, d''artisanat, de service utile peuvent vous aider à vous connecter sans jouer un rôle.","career":"Le travail à long terme devient plus solide lorsque l''ambition est associée à une structure que vous pouvez maintenir. Utilisez observateur, pratique, réfléchi, précis comme des outils, et non comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Renforcez votre confiance financière grâce à des habitudes répétables plutôt qu''à des prévisions parfaites. Remarquez quand le perfectionnisme, l''autocritique ou l''inquiétude pour les détails commence à influencer une décision pratique.","wellbeing":"Considérez le bien-être comme une base pour la vie que vous construisez, et non comme une récompense après l''avoir terminée. Améliorez ce que vous pouvez et permettez au bon travail d''être complet avant qu''il ne soit parfait.","guidance":"Revenez à cette boussole tout au long de l''année : Améliorez ce que vous pouvez, et permettez au bon travail d''être complet avant qu''il ne soit parfait."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('libra', 'fr', '{"name":"Balance","dateRange":"23 sept. – 22 oct.","rulingPlanet":"Vénus","summary":"L''équilibre, la beauté et la réciprocité guident la Balance vers des choix qui honorent chaque voix.","originStory":"Les balances de la Balance sont portées par Astraea, déesse de la justice, et constituent le seul symbole inanimé du zodiaque. Elles représentent le jugement mesuré, l''harmonie sociale et le travail continu de restauration de l''équilibre plutôt que de supposer qu''il existe déjà.","traits":["Diplomatique","Juste","Charmant","Collaboratif"],"strengths":["Médiation","Perspective","Créer l''harmonie"],"challenges":["Indécision","Satisfaction des autres","Éviter les conflits nécessaires"],"compatibleSigns":["Gémeaux","Verseau","Lion"],"reflectionPrompt":"Cherchez l''équité sans abandonner la vérité de vos propres besoins."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'day', 'fr', '{"overview":"Aujourd''hui favorise une étape claire et intentionnelle. La Balance traverse l''énergie de l''air. L''équilibre, la beauté et la réciprocité guident la Balance vers des choix qui honorent chaque voix.","love":"En amour aujourd''hui, choisissez la présence plutôt que les suppositions. Vos dons de médiation, de perspective, de création d''harmonie peuvent vous aider à vous connecter sans devoir jouer un rôle.","career":"Au travail, accomplissez la tâche la plus significative avant de poursuivre un nouvel élan. Utilisez diplomatique, équitable, charmant, collaboratif comme outils, pas comme des attentes que vous devez satisfaire toutes à la fois.","finance":"Gardez les choix financiers d''aujourd''hui simples et réalistes. Remarquez quand l''indécision, le désir de plaire aux autres ou l''évitement des conflits nécessaires commence à influencer une décision pratique.","wellbeing":"Une petite pause peut recharger votre énergie. Cherchez l''équité sans abandonner la vérité de vos propres besoins.","guidance":"Avant que la journée ne se termine, souvenez-vous : Cherchez l''équité sans abandonner la vérité de vos propres besoins."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'week', 'fr', '{"overview":"Cette semaine se développe à travers des choix constants plutôt que par un moment dramatique. La Balance évolue à travers l''énergie de l''air. L''équilibre, la beauté et la réciprocité guident la Balance vers des choix qui honorent chaque voix.","love":"Les relations bénéficient d''une conversation qui laisse de la place à la fois à l''honnêteté et à la chaleur. Vos talents de médiation, de perspective et de création d''harmonie peuvent vous aider à vous connecter sans jouer un rôle.","career":"Vos meilleurs progrès professionnels viennent de choisir une priorité et de protéger du temps pour celle-ci. Utilisez diplomatique, équitable, charmant, collaboratif comme outils, et non comme attentes que vous devez satisfaire toutes à la fois.","finance":"Examinez le schéma de vos dépenses avant de prendre un engagement plus important. Remarquez quand l''indécision, le fait de vouloir plaire aux autres ou d''éviter un conflit nécessaire commence à influencer une décision pratique.","wellbeing":"Équilibrez le mouvement avec une récupération authentique tout au long de la semaine. Cherchez l''équité sans abandonner la vérité de vos propres besoins.","guidance":"Laissez cette question guider la semaine : Cherchez l''équité sans abandonner la vérité de vos propres besoins."}');
