INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('scorpio', 'fr', '{"name":"Scorpion","dateRange":"23 oct. – 21 nov.","rulingPlanet":"Pluton","summary":"La profondeur et la transformation définissent le Scorpion, dont la perspicacité découvre la vérité sous la surface.","originStory":"Le Scorpion se souvient du scorpion envoyé pour affronter le chasseur Orion après que son orgueil ait perturbé l''ordre naturel. Leurs positions opposées dans le ciel évoquent les limites, les conséquences, le mystère et le pouvoir régénérateur que l''on trouve après une fin.","traits":["Intense","Perspicace","Loyal","Ingénieux"],"strengths":["Courage émotionnel","Concentration","Transformation"],"challenges":["Secret","Suspicion","Rancunes"],"compatibleSigns":["Cancer","Poissons","Vierge"],"reflectionPrompt":"Utilisez votre profondeur pour transformer la vérité, pas pour la cacher."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'day', 'fr', '{"overview":"Aujourd''hui favorise une étape claire et intentionnelle. Le Scorpion traverse l''énergie de l''eau. La profondeur et la transformation définissent le Scorpion, dont la perspicacité trouve la vérité sous la surface.","love":"En amour aujourd''hui, choisissez la présence plutôt que l''hypothèse. Vos dons de courage émotionnel, de concentration, de transformation peuvent vous aider à vous connecter sans performer.","career":"Au travail, terminez la tâche la plus significative avant de poursuivre un nouvel élan. Utilisez intense, perspicace, loyal, ingénieux comme outils, et non comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Gardez les choix financiers d''aujourd''hui simples et réalistes. Remarquez lorsque le secret, la suspicion ou le ressentiment commence à influencer une décision pratique.","wellbeing":"Une petite pause peut recharger votre énergie. Utilisez votre profondeur pour transformer la vérité, pas pour la cacher.","guidance":"Avant que la journée ne se termine, souvenez-vous : Utilisez votre profondeur pour transformer la vérité, pas pour la cacher."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'week', 'fr', '{"overview":"Cette semaine se développe à travers des choix réguliers plutôt que par un moment dramatique. Le Scorpion traverse l''énergie de l''eau. La profondeur et la transformation définissent le Scorpion, dont l''intuition découvre la vérité sous la surface.","love":"Les relations bénéficient d''une conversation qui laisse place à la fois à l''honnêteté et à la chaleur. Vos dons de courage émotionnel, de concentration, de transformation peuvent vous aider à vous connecter sans jouer un rôle.","career":"Vos meilleurs progrès professionnels viennent de choisir une priorité et de protéger du temps pour celle-ci. Utilisez intense, perspicace, loyal, ingénieux comme outils, et non comme attentes que vous devez satisfaire toutes à la fois.","finance":"Examinez le schéma de vos dépenses avant de prendre un engagement plus important. Remarquez quand le secret, la suspicion et le ressentiment commencent à influencer une décision pratique.","wellbeing":"Équilibrez le mouvement avec une récupération authentique tout au long de la semaine. Utilisez votre profondeur pour transformer la vérité, pas pour la cacher.","guidance":"Laissez cette question guider la semaine : utilisez votre profondeur pour transformer la vérité, pas pour la cacher."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'year', 'fr', '{"overview":"Cette année invite à une croissance patiente autour de l''identité, du but et de la façon dont vous utilisez votre énergie. Le Scorpion évolue dans l''énergie de l''eau. La profondeur et la transformation définissent le Scorpion, dont l''intuition trouve la vérité sous la surface.","love":"L''amour s''approfondit lorsque vous pratiquez la constance et permettez à la connexion d''évoluer à un rythme humain. Vos dons de courage émotionnel, de concentration, de transformation peuvent vous aider à vous connecter sans jouer un rôle.","career":"Le travail à long terme devient plus solide lorsque l''ambition est associée à une structure que vous pouvez maintenir. Utilisez intense, perspicace, loyal, ingénieux comme des outils, et non comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Renforcez la confiance financière grâce à des habitudes répétables plutôt qu''à des prédictions parfaites. Remarquez quand le secret, la suspicion ou le fait de garder rancune commence à influencer une décision pratique.","wellbeing":"Considérez le bien-être comme une base pour la vie que vous êtes en train de construire, et non comme une récompense après l''avoir terminée. Utilisez votre profondeur pour transformer la vérité, et non pour la cacher.","guidance":"Revenez à cette boussole tout au long de l''année : Utilisez votre profondeur pour transformer la vérité, pas pour la cacher."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('sagittarius', 'fr', '{"name":"Sagittaire","dateRange":"22 nov. – 21 déc.","rulingPlanet":"Jupiter","summary":"Le Tireur cherche des horizons plus larges à travers la vérité, le voyage, l''apprentissage et l''optimisme intentionnel.","originStory":"Le Sagittaire est couramment associé à Chiron, le sage centaure et maître dont la flèche pointe au-delà du familier. La constellation symbolise l''union de l''instinct et de la compréhension supérieure, visant toujours un horizon plus significatif.","traits":["Aventurier","Optimiste","Honnête","Philosophique"],"strengths":["Vision","Enthousiasme","Ouverture d’esprit"],"challenges":["Franc-parler","Promettre trop","Échapper à la routine"],"compatibleSigns":["Bélier","Lion","Verseau"],"reflectionPrompt":"Visez loin, mais choisissez une direction que vos actions quotidiennes peuvent soutenir."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'day', 'fr', '{"overview":"Aujourd''hui favorise une étape claire et intentionnelle. Le Sagittaire traverse l''énergie du feu. L''Archer cherche des horizons plus larges à travers la vérité, les voyages, l''apprentissage et l''optimisme intentionnel.","love":"En amour aujourd''hui, choisissez la présence plutôt que les suppositions. Vos dons de vision, d''enthousiasme, d''ouverture d''esprit peuvent vous aider à vous connecter sans devoir jouer un rôle.","career":"Au travail, terminez la tâche la plus significative avant de chercher un nouvel élan. Utilisez aventureux, optimiste, honnête, philosophique comme outils, et non comme attentes que vous devez satisfaire toutes en même temps.","finance":"Gardez les choix d''argent d''aujourd''hui simples et ancrés. Remarquez quand la franchise, les promesses excessives, l''évasion de la routine commencent à influencer une décision pratique.","wellbeing":"Une petite pause peut recharger votre énergie. Visez loin, mais choisissez une direction que vos actions quotidiennes peuvent soutenir.","guidance":"Avant la fin de la journée, souvenez-vous : Visez loin, mais choisissez une direction que vos actions quotidiennes peuvent soutenir."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'week', 'fr', '{"overview":"Cette semaine se développe à travers des choix réguliers plutôt que par un moment dramatique. Le Sagittaire traverse l''énergie du feu. L''Archer cherche des horizons plus larges à travers la vérité, les voyages, l''apprentissage et l''optimisme intentionnel.","love":"Les relations bénéficient d''une conversation qui laisse de la place à la fois à l''honnêteté et à la chaleur. Vos dons de vision, d''enthousiasme et d''ouverture d''esprit peuvent vous aider à vous connecter sans jouer un rôle.","career":"Vos meilleurs progrès professionnels viennent du choix d''une priorité et de la protection du temps pour celle-ci. Utilisez l''aventure, l''optimisme, l''honnêteté et la philosophie comme des outils, pas comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Examinez le schéma de vos dépenses avant de prendre un engagement plus important. Remarquez quand la franchise, le fait de trop promettre, l''évasion de la routine commencent à influencer une décision pratique.","wellbeing":"Équilibrez le mouvement avec une récupération authentique tout au long de la semaine. Visez loin, mais choisissez une direction que vos actions quotidiennes peuvent soutenir.","guidance":"Laissez cette question guider la semaine : Visez loin, mais choisissez une direction que vos actions quotidiennes peuvent soutenir."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'year', 'fr', '{"overview":"Cette année invite à une croissance patiente autour de l''identité, du but et de la façon dont vous utilisez votre énergie. Le Sagittaire évolue dans l''énergie du feu. L''Archer cherche des horizons plus larges à travers la vérité, le voyage, l''apprentissage et l''optimisme intentionnel.","love":"L''amour s''approfondit lorsque vous pratiquez la constance et permettez à la connexion d''évoluer à un rythme humain. Vos dons de vision, d''enthousiasme, d''ouverture d''esprit peuvent vous aider à vous connecter sans jouer un rôle.","career":"Le travail à long terme devient plus solide lorsque l''ambition est associée à une structure que vous pouvez soutenir. Utilisez l''aventure, l''optimisme, l''honnêteté et la philosophie comme des outils, et non comme des attentes que vous devez satisfaire toutes à la fois.","finance":"Construisez la confiance financière grâce à des habitudes répétables plutôt qu''à des prédictions parfaites. Remarquez lorsque la franchise, les promesses excessives ou l''évasion de la routine commencent à influencer une décision pratique.","wellbeing":"Considérez le bien-être comme une base pour la vie que vous construisez, et non comme une récompense après l''avoir achevée. Visez loin, mais choisissez une direction que vos actions quotidiennes peuvent soutenir.","guidance":"Revenez à cette boussole tout au long de l''année : Visez loin, mais choisissez une direction que vos actions quotidiennes peuvent soutenir."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('capricorn', 'fr', '{"name":"Capricorne","dateRange":"22 déc. – 19 janv.","rulingPlanet":"Saturne","summary":"La discipline et la vision à long terme aident le Capricorne à gravir les sommets tout en restant sage quant aux profondeurs en dessous.","originStory":"La chèvre de mer du Capricorne est associée à Pan, qui s''est partiellement transformé en poisson en fuyant Typhon. Sa nature montagneuse et océanique allie ambition à survie émotionnelle, honorant la maîtrise acquise avec le temps et la responsabilité.","traits":["Ambitieux","Discipliné","Patient","Responsable"],"strengths":["Endurance","Stratégie","Fiabilité"],"challenges":["Rigidité","Pessimisme","Mesurer la valeur à travers la réussite"],"compatibleSigns":["Taureau","Vierge","Scorpion"],"reflectionPrompt":"Construisez pour le long terme tout en gardant à l''esprit que le repos fait partie de la structure."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'day', 'fr', '{"overview":"Aujourd''hui favorise une étape claire et intentionnelle. Le Capricorne se déplace à travers l''énergie de la terre. La discipline et la vision à long terme aident la Chèvre de mer à grimper tout en restant sage face aux profondeurs en dessous.","love":"En amour aujourd''hui, choisissez la présence plutôt que les suppositions. Vos dons d''endurance, de stratégie et de fiabilité peuvent vous aider à vous connecter sans avoir à performer.","career":"Au travail, terminez la tâche la plus significative avant de chercher un nouvel élan. Utilisez ambitieux, discipliné, patient, responsable comme outils, et non comme attentes que vous devez satisfaire toutes en même temps.","finance":"Gardez les choix financiers d''aujourd''hui simples et concrets. Remarquez quand la rigidité, le pessimisme, ou le fait de mesurer la valeur par la réussite commence à influencer une décision pratique.","wellbeing":"Une petite pause peut recharger votre énergie. Construisez pour le long terme tout en vous souvenant que le repos fait partie de la structure.","guidance":"Avant que la journée ne se termine, souvenez-vous : Construisez pour le long terme tout en vous rappelant que le repos fait partie de la structure."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'week', 'fr', '{"overview":"Cette semaine se développe à travers des choix constants plutôt que par un moment dramatique. Le Capricorne évolue à travers l''énergie de la terre. La discipline et la vision à long terme aident la Chèvre de mer à gravir les sommets tout en restant sage face aux profondeurs en dessous.","love":"Les relations bénéficient d''une conversation qui laisse de la place à la fois à l''honnêteté et à la chaleur. Vos qualités d''endurance, de stratégie et de fiabilité peuvent vous aider à vous connecter sans avoir à jouer un rôle.","career":"Vos meilleurs progrès professionnels viennent du choix d''une priorité et de la protection du temps pour celle-ci. Utilisez ambition, discipline, patience, responsabilité comme des outils, et non comme des attentes à satisfaire toutes en même temps.","finance":"Examinez le schéma de vos dépenses avant de prendre un engagement plus important. Remarquez quand la rigidité, le pessimisme, et la mesure de la valeur à travers les réalisations commencent à influencer une décision pratique.","wellbeing":"Équilibrez le mouvement avec une récupération réelle tout au long de la semaine. Construisez sur le long terme tout en vous souvenant que le repos fait partie de la structure.","guidance":"Laissez cette question guider la semaine : Construisez pour le long terme tout en vous rappelant que le repos fait partie de la structure."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'year', 'fr', '{"overview":"Cette année invite à une croissance patiente autour de l''identité, du but et de la façon dont vous utilisez votre énergie. Le Capricorne évolue à travers l''énergie de la terre. La discipline et la vision à long terme aident la Chèvre de mer à grimper tout en restant sage face aux profondeurs en dessous.","love":"L''amour s''approfondit lorsque vous pratiquez la constance et permettez à la connexion d''évoluer à un rythme humain. Vos dons d''endurance, de stratégie et de fiabilité peuvent vous aider à vous connecter sans performer.","career":"Le travail à long terme devient plus solide lorsque l''ambition est associée à une structure que vous pouvez maintenir. Utilisez ambitieux, discipliné, patient, responsable comme des outils, pas comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Construisez la confiance financière grâce à des habitudes répétables plutôt que par des prédictions parfaites. Remarquez lorsque la rigidité, le pessimisme, ou le fait de mesurer la valeur par les réalisations commencent à influencer une décision pratique.","wellbeing":"Considérez le bien-être comme une base pour la vie que vous construisez, et non comme une récompense après l''avoir achevée. Construisez pour le long terme tout en vous souvenant que le repos fait partie de la structure.","guidance":"Revenez à cette boussole tout au long de l''année : Construisez sur le long terme tout en vous rappelant que le repos fait partie de la structure."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aquarius', 'fr', '{"name":"Verseau","dateRange":"20 janv. – 18 fév.","rulingPlanet":"Uranus","summary":"La pensée indépendante et la vision collective guident le Verseau pour verser de nouvelles idées dans le monde.","originStory":"Le Verseau est lié à Ganymède, le porteur de coupe dont le récipient apportait de l''eau aux dieux et, symboliquement, la connaissance à l''humanité. Bien que son image transporte de l''eau, le signe appartient à l''air : les idées, les systèmes et le renouveau partagés pour le bien commun.","traits":["Original","Indépendant","Humanitaire","Inventif"],"strengths":["Innovation","Objectivité","Vision communautaire"],"challenges":["Détachement","Habitudes contraires","Opinions fixes"],"compatibleSigns":["Gémeaux","Balance","Sagittaire"],"reflectionPrompt":"Laisse ta différence servir la connexion plutôt que la distance."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'day', 'fr', '{"overview":"Aujourd''hui favorise une étape claire et intentionnelle. Le Verseau traverse l''énergie de l''air. La pensée indépendante et la vision collective guident le Porteur d''Eau pour verser de nouvelles idées dans le monde.","love":"En amour aujourd''hui, choisissez la présence plutôt que les suppositions. Vos dons d''innovation, d''objectivité et de vision communautaire peuvent vous aider à vous connecter sans jouer un rôle.","career":"Au travail, terminez la tâche la plus significative avant de poursuivre un nouvel élan. Utilisez original, indépendant, humanitaire, inventif comme outils, et non comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Gardez les choix d''argent d''aujourd''hui simples et ancrés. Remarquez quand le détachement, les habitudes contrariennes, les opinions fixes commencent à influencer une décision pratique.","wellbeing":"Une petite pause peut réinitialiser votre énergie. Laissez votre différence servir la connexion plutôt que la distance.","guidance":"Avant que la journée ne se termine, souvenez-vous : Laissez votre différence servir la connexion plutôt que la distance."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'week', 'fr', '{"overview":"Cette semaine se développe à travers des choix constants plutôt qu''un moment dramatique. Le Verseau évolue à travers l''énergie de l''air. La pensée indépendante et la vision collective guident le Porteur d''eau pour verser de nouvelles idées dans le monde.","love":"Les relations bénéficient d''une conversation qui laisse de la place à la fois à l''honnêteté et à la chaleur. Vos dons pour l''innovation, l''objectivité et la vision communautaire peuvent vous aider à vous connecter sans jouer un rôle.","career":"Votre meilleur progrès professionnel vient du choix d''une priorité et de la protection du temps pour celle-ci. Utilisez original, indépendant, humanitaire, inventif comme outils, pas comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Examinez le schéma de vos dépenses avant de prendre un engagement plus important. Remarquez quand le détachement, les habitudes contraires, les opinions fixes commencent à influencer une décision pratique.","wellbeing":"Équilibrez le mouvement avec une récupération véritable tout au long de la semaine. Laissez votre différence servir la connexion plutôt que la distance.","guidance":"Laissez cette question guider la semaine : Laissez votre différence servir la connexion plutôt que la distance."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'year', 'fr', '{"overview":"Cette année invite à une croissance patiente autour de l''identité, du but et de la manière dont vous utilisez votre énergie. Le Verseau évolue à travers l''énergie de l''air. La pensée indépendante et la vision collective guident le Porteur d''eau à verser de nouvelles idées dans le monde.","love":"L''amour s''approfondit lorsque vous pratiquez la constance et permettez à la connexion d''évoluer à un rythme humain. Vos dons d''innovation, d''objectivité et de vision communautaire peuvent vous aider à vous connecter sans jouer un rôle.","career":"Le travail à long terme devient plus solide lorsque l''ambition est associée à une structure que vous pouvez soutenir. Utilisez original, indépendant, humanitaire, inventif comme outils, et non comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Construisez la confiance financière grâce à des habitudes répétables plutôt que des prédictions parfaites. Remarquez quand le détachement, les habitudes contraires, les opinions figées commencent à influencer une décision pratique.","wellbeing":"Considérez le bien-être comme une fondation pour la vie que vous construisez, et non comme une récompense après l''avoir terminée. Laissez votre différence favoriser la connexion plutôt que la distance.","guidance":"Revenez à cette boussole tout au long de l''année : Laissez votre différence servir la connexion plutôt que l''éloignement."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('pisces', 'fr', '{"name":"Poissons","dateRange":"19 fév. – 20 mars","rulingPlanet":"Neptune","summary":"La compassion et l''imagination guident les Poissons entre intuition, rêves et sentiments partagés.","originStory":"Les Poissons rappellent Aphrodite et Éros devenant des poissons et se liant l''un à l''autre pour échapper à Typhon. Le lien entre les deux poissons représente la dévotion, une identité fluide, la sensibilité spirituelle et la recherche de l''unité tout en se mouvant à travers des courants changeants.","traits":["Compatissant","Imaginatif","Intuitif","Douce"],"strengths":["Empathie","Créativité","Intuition spirituelle"],"challenges":["Évasion","Frontières floues","Absorber les émotions des autres"],"compatibleSigns":["Cancer","Scorpion","Capricorne"],"reflectionPrompt":"Honorez votre sensibilité avec des limites suffisamment fortes pour la protéger."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'day', 'fr', '{"overview":"Aujourd''hui favorise une étape claire et intentionnelle. Les Poissons traversent l''énergie de l''eau. La compassion et l''imagination guident les Poissons entre l''intuition, les rêves et le sentiment partagé.","love":"En amour aujourd''hui, choisissez la présence plutôt que l''hypothèse. Vos dons d''empathie, de créativité, d''intuition spirituelle peuvent vous aider à vous connecter sans performer.","career":"Au travail, terminez la tâche la plus significative avant de chercher un nouvel élan. Utilisez compatissant, imaginatif, intuitif, doux comme outils, et non comme attentes que vous devez satisfaire toutes en même temps.","finance":"Gardez les choix financiers d''aujourd''hui simples et ancrés. Remarquez quand l''évasion, les frontières floues et l''absorption des émotions des autres commencent à influencer une décision pratique.","wellbeing":"Une petite pause peut réinitialiser votre énergie. Honorez votre sensibilité avec des limites assez fortes pour la protéger.","guidance":"Avant que la journée ne se termine, souvenez-vous : Honorez votre sensibilité avec des limites suffisamment fortes pour la protéger."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'week', 'fr', '{"overview":"Cette semaine se développe à travers des choix réguliers plutôt que par un moment dramatique. Les Poissons traversent l''énergie de l''eau. La compassion et l''imagination guident les Poissons entre intuition, rêves et sentiments partagés.","love":"Les relations bénéficient d''une conversation qui laisse de la place à la fois à l''honnêteté et à la chaleur. Vos dons d''empathie, de créativité et de perspicacité spirituelle peuvent vous aider à vous connecter sans jouer un rôle.","career":"Vos meilleurs progrès professionnels viennent du choix d''une priorité et de la protection du temps pour celle-ci. Utilisez la compassion, l''imagination, l''intuition et la douceur comme outils, et non comme des attentes à satisfaire toutes en même temps.","finance":"Examinez le schéma de vos dépenses avant de prendre un engagement plus important. Remarquez quand l''évasion, les limites floues, l''absorption des émotions des autres commencent à influencer une décision pratique.","wellbeing":"Équilibrez le mouvement avec une récupération véritable tout au long de la semaine. Honorez votre sensibilité avec des limites suffisamment fortes pour la protéger.","guidance":"Laissez cette question guider la semaine : Honorez votre sensibilité avec des limites assez solides pour la protéger."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'year', 'fr', '{"overview":"Cette année invite à une croissance patiente autour de l''identité, du but et de la manière dont vous utilisez votre énergie. Pisces traverse l''énergie de l''eau. La compassion et l''imagination guident les Poissons entre intuition, rêves et sentiment partagé.","love":"L''amour s''approfondit lorsque vous pratiquez la constance et permettez à la connexion d''évoluer à un rythme humain. Vos dons d''empathie, de créativité et de perspicacité spirituelle peuvent vous aider à vous connecter sans jouer un rôle.","career":"Le travail à long terme devient plus solide lorsque l''ambition est associée à une structure que vous pouvez soutenir. Utilisez la compassion, l''imagination, l''intuition et la douceur comme des outils, pas comme des attentes que vous devez satisfaire toutes en même temps.","finance":"Développez la confiance financière grâce à des habitudes répétables plutôt qu''à des prédictions parfaites. Remarquez lorsque l''évasion, les frontières floues, ou l''absorption des émotions des autres commencent à influencer une décision pratique.","wellbeing":"Considérez le bien-être comme une base pour la vie que vous construisez, et non comme une récompense après l''avoir achevée. Honorez votre sensibilité avec des limites suffisamment solides pour la protéger.","guidance":"Revenez à cette boussole tout au long de l''année : Honorez votre sensibilité avec des limites suffisamment solides pour la protéger."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('fool', 'de', '{"name":"Der Narr","meaning":"Eine leere Seite und ein Sprung ins Unbekannte – eine neue Reise beginnt mit offenem Herzen.","advice":"Vertraue dem Weg vor dir und mache den ersten Schritt, auch ohne alle Antworten zu haben.","yesNoMeaning":"Ein neuer Anfang trägt selten eine feste Antwort — das Ergebnis hängt von dem Schritt ab, den du machst."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('magician', 'de', '{"name":"Der Magier","meaning":"Du hältst alle Werkzeuge, die du brauchst. Fokussiere deinen Willen und verwandle Absicht in Handlung.","advice":"Setze deine Fähigkeiten und Ressourcen gezielt ein — jetzt ist die Zeit, es zu verwirklichen.","yesNoMeaning":"Du besitzt bereits alles, was nötig ist — die Energie unterstützt es, mit Fokus voranzuschreiten."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('high-priestess', 'de', '{"name":"Die Hohepriesterin","meaning":"Leise Weisheit verbirgt sich unter der Oberfläche. Höre auf deine Intuition und innere Stimme.","advice":"Halten Sie inne, gehen Sie nach innen und lassen Sie sich von Ihren Instinkten leiten, bevor Sie handeln.","yesNoMeaning":"Die Antwort ist vorerst unter der Oberfläche verborgen — vertraue deiner Intuition, statt ein klares Ja oder Nein zu erzwingen."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('empress', 'de', '{"name":"Die Kaiserin","meaning":"Wachstum, Fülle und nährende Energie umgeben dich. Lass Schönheit und Fürsorge gedeihen.","advice":"Sei geduldig und großzügig — kreiere mit Liebe und lass die Dinge natürlich reifen.","yesNoMeaning":"Wachstum, Fülle und nährende Energie unterstützen deinen Wunsch — die Antwort ist ein stilles Ja."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('emperor', 'de', '{"name":"Der Kaiser","meaning":"Struktur, Autorität und beständiges Führungsverhalten. Baue auf festem Grund mit Disziplin.","advice":"Übernimm die Führung mit einem klaren Plan; feste Grenzen bringen dauerhafte Stabilität.","yesNoMeaning":"Struktur, Autorität und stetige Disziplin stehen hinter einem selbstbewussten Ja."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hierophant', 'de', '{"name":"Der Hierophant","meaning":"Tradition und vertrauenswürdige Führung bieten einen zuverlässigen Weg. Lerne von dem, was zuvor gekommen ist.","advice":"Folge bewährter Weisheit und suche Rat bei denen, denen du vertraust.","yesNoMeaning":"Tradition und vertrauenswürdige Orientierung weisen auf ein verlässliches Ja hin — stütze dich auf das, was sich bereits bewährt hat."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('lovers', 'de', '{"name":"Die Liebenden","meaning":"Eine bedeutungsvolle Bindung oder eine wichtige Entscheidung. Folge dem, was dein Herz wirklich schätzt.","advice":"Wähle mit Ehrlichkeit und Übereinstimmung — Verbindung vertieft sich, wenn du aufrichtig bist.","yesNoMeaning":"Ihr Herz und Ihre Werte sind hier ausgerichtet — die Antwort ist ja, besonders wenn Sie mit Ehrlichkeit wählen."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('chariot', 'de', '{"name":"Der Wagen","meaning":"Willenskraft und Schwung tragen dich voran. Bleibe fokussiert und du wirst siegen.","advice":"Behalte das Ziel im Auge und steuere mit Zuversicht durch jedes Hindernis.","yesNoMeaning":"Willenskraft und Schwung sind auf deiner Seite — ein fokussiertes Ja, vorausgesetzt, du bleibst engagiert."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('strength', 'de', '{"name":"Stärke","meaning":"Wahre Macht ist sanft — Geduld, Mut und Mitgefühl zähmen jede Herausforderung.","advice":"Führe mit ruhiger Stärke; eine sanfte Hand ist oft die stärkste.","yesNoMeaning":"Sanfter Mut und geduldige Entschlossenheit machen dies zu einem Ja — führe mit Ruhe, nicht mit Gewalt."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hermit', 'de', '{"name":"Der Eremit","meaning":"Zeit, einen Schritt zurückzutreten und innere Klarheit zu suchen. Einsamkeit bringt jetzt tiefere Antworten.","advice":"Kehre nach innen, reflektiere und lasse die Stille offenbaren, was du wirklich brauchst.","yesNoMeaning":"Noch nicht — die Karte fordert Sie auf, einen Schritt zurückzutreten und innere Klarheit zu finden, bevor Sie handeln."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('wheel-of-fortune', 'de', '{"name":"Glücksrad","meaning":"Das Glück wendet sich und Zyklen verändern sich. Was sich jetzt ändert, ist Teil eines größeren Rhythmus.","advice":"Reite die Welle mit Flexibilität – nimm die Wendung an, ob gut oder schlecht.","yesNoMeaning":"Das Glück wendet sich — das Ergebnis hängt davon ab, wie du den Wandel bewältigst, nicht von einem festen Ja oder Nein."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('justice', 'de', '{"name":"Gerechtigkeit","meaning":"Wahrheit und Gerechtigkeit setzen sich durch. Ursache und Wirkung kommen nun ins Gleichgewicht.","advice":"Handeln Sie ehrlich und wägen Sie beide Seiten ab; die Waage wird sich fair einstellen.","yesNoMeaning":"Die Waage ist noch im Gleichgewicht — die faire Antwort hängt von den Fakten und deiner Ehrlichkeit ab."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hanged-man', 'de', '{"name":"Der Gehängte","meaning":"Eine notwendige Pause. Lass die Kontrolle los und betrachte die Situation aus einem neuen Blickwinkel.","advice":"Hör auf zu drängen — übergebe dich dem Moment und lass eine neue Perspektive eintreffen.","yesNoMeaning":"Zuerst ist eine Pause nötig — ein erzwungenes Handeln würde nur eine klarere Antwort zurückhalten."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('death', 'de', '{"name":"Tod","meaning":"Ein Ende schafft Raum für Erneuerung. Lasse los, was seine Zeit gedient hat.","advice":"Lass los ohne Bedauern; eine tiefgreifende Transformation öffnet eine neue Tür.","yesNoMeaning":"Ein Ende schafft Klarheit — der aktuelle Weg schließt sich, damit ein neuer beginnen kann."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('temperance', 'de', '{"name":"Mäßigung","meaning":"Balance und Geduld bringen Harmonie. Vereine Gegensätze mit Anmut.","advice":"Bewegen Sie sich mit Maß und bewahren Sie Ruhe – beständige Schritte erreichen das Ziel.","yesNoMeaning":"Balance und Geduld bringen Harmonie — ein überlegtes Ja, Schritt für Schritt."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('devil', 'de', '{"name":"Der Teufel","meaning":"Sei vorsichtig mit Bindung, Versuchung oder einem fesselnden Muster. Erkenne die Ketten.","advice":"Nenne, was dich hält, und erlange deine Freiheit zurück — die Kette bindet nur, wenn du es zulässt.","yesNoMeaning":"Anhaftung oder ein bindendes Muster steht im Weg — noch nicht, bis die Kette benannt und durchbrochen ist."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('tower', 'de', '{"name":"Der Turm","meaning":"Plötzliche Veränderungen erschüttern das Falsche und offenbaren die Wahrheit. Was fällt, war niemals zum Stehen gedacht.","advice":"Begrüße das Durcheinander; aus den Trümmern kann ein klareres Fundament gebaut werden.","yesNoMeaning":"Plötzliche Veränderungen erschüttern das Alte – der Boden muss sich setzen, bevor ein stabiles Ja möglich ist."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('star', 'de', '{"name":"Der Stern","meaning":"Hoffnung, Heilung und stille Inspiration erneuern deinen Geist nach dem Sturm.","advice":"Vertraue dem Licht vor dir und glaube weiter — deine Wünsche sind greifbar.","yesNoMeaning":"Hoffnung und stille Erneuerung weisen auf Ja hin – vertraue dem Licht voraus und halte deinen Wunsch lebendig."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('moon', 'de', '{"name":"Der Mond","meaning":"Illusion und Unsicherheit verschwimmen den Weg. Vertraue deiner Intuition, nicht den Erscheinungen.","advice":"Langsam machen und genauer hinschauen; Klarheit wird kommen, wenn der Nebel sich lichtet.","yesNoMeaning":"Illusion und Unsicherheit verschwimmen den Weg – die Antwort ist unklar, bis du unter die Oberfläche blickst."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('sun', 'de', '{"name":"Die Sonne","meaning":"Freude, Erfolg und strahlende Klarheit. Alles ist hell und voller Leben.","advice":"Feiere und strahle — positive Energie zieht die Ergebnisse an, die du dir wünschst.","yesNoMeaning":"Freude und strahlende Klarheit bestätigen ein helles Ja — alles arbeitet zu deinen Gunsten."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('judgement', 'de', '{"name":"Urteil","meaning":"Ein Aufruf, aufzustehen, sich zu erneuern und ehrlich zu sich selbst zu sein. Ein Urteil des Erwachens.","advice":"Beantworte den Ruf mit Mut; vergib der Vergangenheit und tritt in dein nächstes Kapitel ein.","yesNoMeaning":"Ein Aufruf, sich zu erheben und zu erneuern – ja, besonders wenn du der Vergangenheit vergibst und ehrlich antwortest."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('world', 'de', '{"name":"Die Welt","meaning":"Abschluss und Erfüllung — ein Zyklus schließt sich in vollkommener Ganzheit.","advice":"Feiere, was du erreicht hast; die Tür ist zu einer größeren Welt geöffnet.","yesNoMeaning":"Abschluss und Ganzheit kennzeichnen dies als ein erfülltes Ja — der Zyklus schließt sich zu deinen Gunsten."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-wands', 'de', '{"name":"Ass der Stäbe","meaning":"Ein Funke der Inspiration öffnet einen mutigen kreativen Weg.","advice":"Beginne, während die Energie frisch ist, und gib der Idee einen echten ersten Schritt.","yesNoMeaning":"Das Stab-Ass tendiert zu Ja: Beginne, solange die Energie frisch ist, und gib der Idee einen echten ersten Schritt."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-wands', 'de', '{"name":"Zwei der Stäbe","meaning":"Eine Zukunft nimmt durch Planung und die Wahl einer Richtung Gestalt an.","advice":"Sieh über das Vertraute hinaus und dann verpflichte dich dem Weg mit Raum zum Wachsen.","yesNoMeaning":"Die Zwei der Stäbe bleibt bedingt: Schau über das Vertraute hinaus und entscheide dich dann für den Weg mit Raum zum Wachsen."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-wands', 'de', '{"name":"Drei der Stäbe","meaning":"Erste Anstrengung erweitert sich, während Chancen und weitere Horizonte sichtbar werden.","advice":"Baue weiter und sei bereit, die Reaktion zu empfangen, die deine Arbeit hervorruft.","yesNoMeaning":"Die Drei der Stäbe tendiert zu ja: Baue weiter auf und sei bereit, auf die Resonanz deiner Arbeit zu reagieren."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-wands', 'de', '{"name":"Vier der Stäbe","meaning":"Stabilität, Willkommen und gemeinsame Feier schaffen eine starke Grundlage.","advice":"Markiere den Meilenstein und lass unterstützende Menschen daran teilhaben.","yesNoMeaning":"Die Vier der Stäbe neigt zu Ja: Markiere den Meilenstein und lasse unterstützende Menschen daran teilhaben."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-wands', 'de', '{"name":"Fünf der Stäbe","meaning":"Wettbewerbende Ziele erzeugen Reibung, Lärm oder eine Prüfung des Vertrauens.","advice":"Verwandle Rivalität in nützliche Praxis und lehne Konflikte ab, die keinen Zweck haben.","yesNoMeaning":"Die Fünf der Stäbe bleibt bedingt: Verwandle Rivalität in nützliche Übung und verweigere Konflikte, die keinen Zweck haben."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-wands', 'de', '{"name":"Sechs der Stäbe","meaning":"Anerkennung folgt auf entschlossenen Einsatz und sichtbare Fortschritte.","advice":"Nimm die Ermutigung an, aber halte dein Vertrauen an ehrlicher Arbeit fest.","yesNoMeaning":"Die Sechs der Stäbe neigt zu Ja: Nimm die Ermutigung an, halte aber dein Selbstvertrauen an ehrlicher Arbeit gebunden."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-wands', 'de', '{"name":"Sieben der Stäbe","meaning":"Du hältst wertvollen Boden, während der Druck deine Entschlossenheit prüft.","advice":"Verteidige, was zählt, mit klaren Grenzen, anstatt jede Herausforderung zu bekämpfen.","yesNoMeaning":"Die Sieben der Stäbe tendiert zu Ja: Verteidige, was wichtig ist, mit klaren Grenzen, anstatt jede Herausforderung zu bekämpfen."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-wands', 'de', '{"name":"Acht der Stäbe","meaning":"Ereignisse beschleunigen sich, Nachrichten kommen an, und der Schwung beseitigt Verzögerungen.","advice":"Handeln Sie zügig und halten Sie die Kommunikation direkt, solange der Weg offen ist.","yesNoMeaning":"Die Acht der Stäbe tendiert zu Ja: Handle prompt und halte die Kommunikation direkt, solange der Weg offen ist."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-wands', 'de', '{"name":"Neun der Stäbe","meaning":"Resilienz ist stark, obwohl frühere Belastung dich wachsam macht.","advice":"Schütze deine Energie und gehe den nächsten Schritt, ohne zu erwarten, dass jede Wunde sich wiederholt.","yesNoMeaning":"Die Neun der Stäbe bleibt bedingt: Schütze deine Energie und mache den nächsten Schritt, ohne zu erwarten, dass jede Wunde sich wiederholt."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-wands', 'de', '{"name":"Zehn der Stäbe","meaning":"Verantwortung ist schwer geworden und Erfolg trägt jetzt eine Last.","advice":"Delegiere, vereinfache und lege Arbeit nieder, die nicht mehr wirklich deine ist.","yesNoMeaning":"Die Zehn der Stäbe tendiert zu nein: delegiere, vereinfache und lege Arbeit ab, die nicht mehr wirklich dir gehört."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-wands', 'de', '{"name":"Bube der Stäbe","meaning":"Neugier bringt eine lebhafte Nachricht, ein Experiment oder ein neues kreatives Interesse.","advice":"Erkunde mit Mut und lass die Energie des Anfängers dich durch Handeln lehren.","yesNoMeaning":"Der Bube der Stäbe tendiert zu ja: Erkunden Sie mit Mut und lassen Sie die Anfängerkraft Sie durch Handeln lehren."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-wands', 'de', '{"name":"Ritter der Stäbe","meaning":"Leidenschaft stürmt schnell voran, bringt Abenteuer und mögliche Ungeduld.","advice":"Nutze die Dynamik, aber wähle eine Richtung, bevor die Geschwindigkeit deine Bemühungen zerstreut.","yesNoMeaning":"Der Ritter der Stäbe bleibt bedingt: Nutze das Momentum, aber wähle eine Richtung, bevor die Geschwindigkeit deine Anstrengung zerstreut."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-wands', 'de', '{"name":"Königin der Stäbe","meaning":"Warme Zuversicht und kreative Unabhängigkeit ziehen andere zu deiner Vision hin.","advice":"Vertraue deiner Präsenz, ermutige andere und mindere nicht deinen Ehrgeiz.","yesNoMeaning":"Die Königin der Stäbe neigt sich ja: Vertraue auf deine Präsenz, ermutige andere und schränke deinen Ehrgeiz nicht ein."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-wands', 'de', '{"name":"König der Stäbe","meaning":"Reife Vision verwandelt Inspiration in entschlossene und ethische Führung.","advice":"Führe aus einem größeren Zweck heraus und gib anderen Raum zur Mitwirkung.","yesNoMeaning":"Der König der Stäbe neigt zu Ja: Führe vom größeren Zweck aus und gib anderen Raum, beizutragen."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-cups', 'de', '{"name":"Ass der Kelche","meaning":"Das Herz öffnet sich für neue Zuneigung, Mitgefühl und emotionale Erneuerung.","advice":"Nimm das Gefühl ehrlich wahr und lasse Fürsorge fließen, ohne ein Ergebnis erzwingen zu müssen.","yesNoMeaning":"Das Ass der Kelche tendiert zu Ja: Nimm das Gefühl ehrlich an und lasse Fürsorge fließen, ohne ein Ergebnis erzwingen zu wollen."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-cups', 'de', '{"name":"Zwei der Kelche","meaning":"Gegenseitige Anerkennung schafft Partnerschaft, Anziehung oder aufrichtige Übereinstimmung.","advice":"Treffen Sie die andere Person auf Augenhöhe und sprechen Sie von Herzen.","yesNoMeaning":"Die Zwei der Kelche tendiert zu ja: Begegne der anderen Person als Gleichwertige/r und sprich von Herzen."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-cups', 'de', '{"name":"Drei der Kelche","meaning":"Freundschaft, Gemeinschaft und geteilte Freude bringen emotionale Unterstützung.","advice":"Feiere gemeinsam und erinnere dich daran, wer wirklich für dich da ist.","yesNoMeaning":"Die Drei der Kelche tendiert zu ja: feiere gemeinsam und erinnere dich daran, wer wirklich für dich da ist."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-cups', 'de', '{"name":"Vier der Kelche","meaning":"Emotionaler Rückzug macht ein verfügbares Geschenk schwer wahrnehmbar.","advice":"Unterbrechen Sie den Vergleich und schauen Sie erneut, was still angeboten wird.","yesNoMeaning":"Die Vier der Kelche lehnt ab: halte den Vergleich inne und schaue erneut, was still angeboten wird."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-cups', 'de', '{"name":"Fünf der Kelche","meaning":"Verlust lenkt die Aufmerksamkeit auf das, was verschüttet wurde, während etwas Bedeutungsvolles bleibt.","advice":"Ehre die Enttäuschung, wende dich dann der Unterstützung zu, die noch da ist.","yesNoMeaning":"Die Fünf der Kelche neigt sich zu nein: Ehre die Enttäuschung und wende dich dann der Unterstützung zu, die noch vorhanden ist."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-cups', 'de', '{"name":"Sechs der Kelche","meaning":"Erinnerung, Unschuld oder eine vertraute Bindung kehrt mit sanfter Wärme zurück.","advice":"Begrüße die Freundlichkeit der Vergangenheit, ohne so zu tun, als müsstest du dort wieder leben.","yesNoMeaning":"Die Sechs der Kelche tendiert zu Ja: Begrüße die Freundlichkeit der Vergangenheit, ohne so zu tun, als müsstest du dort wieder leben."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-cups', 'de', '{"name":"Sieben der Kelche","meaning":"Viele verlockende Möglichkeiten verwischen den Unterschied zwischen Vision und Illusion.","advice":"Eingrenzen Sie die Auswahlmöglichkeiten und prüfen Sie einen Traum an der Realität, bevor Sie sich festlegen.","yesNoMeaning":"Die Sieben der Kelche ist noch nicht klar: Engen Sie die Optionen ein und prüfen Sie einen Traum gegen die Realität, bevor Sie sich festlegen."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-cups', 'de', '{"name":"Acht der Kelche","meaning":"Eine einst bedeutungsvolle Situation nährt das Herz nicht mehr.","advice":"Gehe mit Ehrlichkeit und bewege dich auf die tiefere Erfüllung zu, die du jetzt brauchst.","yesNoMeaning":"Die Acht der Kelche tendiert zu Nein: Gehe ehrlich weg und bewege dich auf die tiefere Erfüllung zu, die du jetzt brauchst."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-cups', 'de', '{"name":"Neun der Kelche","meaning":"Zufriedenheit und Dankbarkeit lassen einen Herzenswunsch nah erscheinen.","advice":"Genießen Sie, was hier ist, und fragen Sie, ob der Wunsch auch Ihren tieferen Werten dient.","yesNoMeaning":"Die Neun der Kelche tendiert zu Ja: Genieße, was da ist, und frage, ob der Wunsch auch deinen tieferen Werten dient."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-cups', 'de', '{"name":"Zehn der Kelche","meaning":"Emotionale Harmonie, Zugehörigkeit und dauerhafte Verbindung umgeben das Zuhause.","advice":"Pflege die Bindungen, die Freude nachhaltig und geteilt machen.","yesNoMeaning":"Die Zehn der Kelche tendiert zu ja: pflege die Bindungen, die Freude nachhaltig und geteilt machen."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-cups', 'de', '{"name":"Bube der Kelche","meaning":"Eine zarte Botschaft oder intuitive Entdeckung lädt zu emotionaler Offenheit ein.","advice":"Bleibe neugierig über das Gefühl und reagiere mit Aufrichtigkeit statt mit Annahmen.","yesNoMeaning":"Der Bube der Kelche bleibt bedingt: Bleiben Sie neugierig auf das Gefühl und reagieren Sie mit Aufrichtigkeit statt mit Annahmen."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-cups', 'de', '{"name":"Ritter der Kelche","meaning":"Romantik, Fantasie oder ein Ideal zieht das Herz vorwärts.","advice":"Folge der Einladung, aber halte einen Fuß auf dem Boden, während sich die Versprechen entfalten.","yesNoMeaning":"Der Ritter der Kelche neigt zu Ja: Folge der Einladung, behalte aber einen Fuß auf dem Boden, während sich Versprechen entfalten."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-cups', 'de', '{"name":"Königin der Kelche","meaning":"Tiefe Empathie und Intuition schaffen einen ruhigen Raum für Wahrheit.","advice":"Höre mit Mitgefühl zu, während du die Grenzen bewahrst, die Fürsorge gesund halten.","yesNoMeaning":"Die Königin der Kelche tendiert zu ja: Hören Sie mit Mitgefühl zu, während Sie die Grenzen wahren, die Fürsorge gesund halten."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-cups', 'de', '{"name":"König der Kelche","meaning":"Emotionale Reife stabilisiert starke Gefühle, ohne sie zu unterdrücken.","advice":"Reagiere mit Mitgefühl und Selbstbeherrschung, besonders wenn andere reaktiv sind.","yesNoMeaning":"Der König der Kelche neigt zu Ja: Reagiere mit Mitgefühl und Selbstbeherrschung, besonders wenn andere reaktiv sind."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-swords', 'de', '{"name":"Ass der Schwerter","meaning":"Eine klare Einsicht durchdringt die Verwirrung und offenbart eine neue Wahrheit.","advice":"Nennen Sie das Problem klar und verwenden Sie Klarheit im Dienst einer fairen Entscheidung.","yesNoMeaning":"Das Schwert-Ass tendiert zu Ja: Nenne das Thema klar und nutze Klarheit zum Dienst einer fairen Entscheidung."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-swords', 'de', '{"name":"Zwei der Schwerter","meaning":"Ein vorsichtiges Patt verzögert eine Entscheidung, die nicht ewig aufgeschoben bleiben kann.","advice":"Entferne die Augenbinde sanft, sammle die fehlenden Fakten und entscheide aus dem Gleichgewicht.","yesNoMeaning":"Die Zwei der Schwerter ist noch unklar: Entferne die Augenbinde behutsam, sammle die fehlenden Fakten und entscheide aus der Balance heraus."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-swords', 'de', '{"name":"Drei der Schwerter","meaning":"Eine schmerzhafte Wahrheit, Trennung oder Enttäuschung verlangt danach, anerkannt zu werden.","advice":"Lass das Gefühl durch dich hindurchfließen und vermeide es, Schmerz in eine dauerhafte Geschichte zu verwandeln.","yesNoMeaning":"Die Drei der Schwerter tendiert zu nein: Lass das Gefühl durch dich hindurchgehen und vermeide, Schmerz in eine permanente Geschichte zu verwandeln."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-swords', 'de', '{"name":"Vier der Schwerter","meaning":"Nach Druck oder Konflikt sind Ruhe und geistige Stille notwendig.","advice":"Pause vor dem Antworten; Erholung ist produktiv, wenn sie klares Denken wiederherstellt.","yesNoMeaning":"Die Vier der Schwerter lehnt sich zurück: Pausiere, bevor du antwortest; Erholung ist produktiv, wenn sie klares Denken wiederherstellt."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-swords', 'de', '{"name":"Fünf der Schwerter","meaning":"Konflikt kann einen hohlen Sieg erzeugen oder das Vertrauen beschädigen.","advice":"Wähle Würde über Sieg und entferne dich von Taktiken, die zu viel kosten.","yesNoMeaning":"Die Fünf der Schwerter neigt sich zu nein: Wähle Würde über Sieg und tritt von Taktiken zurück, die zu viel kosten."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-swords', 'de', '{"name":"Sechs der Schwerter","meaning":"Ein schwieriger Abschnitt bewegt sich allmählich in ruhigere Bedingungen.","advice":"Nimm, was du gelernt hast, akzeptiere Unterstützung und bewege dich weiterhin weg vom Aufruhr.","yesNoMeaning":"Die Sechs der Schwerter neigt sich ja: Nimm, was du gelernt hast, akzeptiere Unterstützung und bewege dich weiter weg vom Aufruhr."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-swords', 'de', '{"name":"Sieben der Schwerter","meaning":"Strategie, Geheimhaltung oder Vermeidung verkomplizieren den Weg.","advice":"Handle clever, aber transparent; Abkürzungen, die Vertrauen verraten, werden als Probleme zurückkehren.","yesNoMeaning":"Die Sieben der Schwerter tendiert zu Nein: Handle klug, aber transparent; Abkürzungen, die Vertrauen verraten, werden als Probleme zurückkehren."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-swords', 'de', '{"name":"Acht der Schwerter","meaning":"Angst und einschränkende Überzeugungen machen die verfügbaren Optionen schwer erkennbar.","advice":"Hinterfrage den Gedanken, der sagt, du seist gefangen, und unternimm eine kleine befreiende Handlung.","yesNoMeaning":"Die Acht der Schwerter tendiert zu Nein: Hinterfrage den Gedanken, der sagt, dass du gefangen bist, und mache eine kleine befreiende Handlung."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-swords', 'de', '{"name":"Neun der Schwerter","meaning":"Angst vergrößert die Gefahr in der Dunkelheit und erschöpft den Geist.","advice":"Bringe die Angst ans Licht, suche Unterstützung und trenne Fakten von eingebildeten Ergebnissen.","yesNoMeaning":"Die Neun der Schwerter tendiert zu Nein: Bring die Angst ans Tageslicht, suche Unterstützung und trenne Fakten von eingebildeten Ergebnissen."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-swords', 'de', '{"name":"Zehn der Schwerter","meaning":"Ein schmerzhafter Zyklus erreicht seine endgültige Grenze und kann nicht unverändert fortgesetzt werden.","advice":"Akzeptiere das Ende, schütze deine Genesung und erlaube einen anderen Anfang zu entstehen.","yesNoMeaning":"Die Zehn der Schwerter tendiert zu nein: akzeptiere das Ende, schütze deine Erholung und erlaube, dass ein anderer Anfang entsteht."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-swords', 'de', '{"name":"Bube der Schwerter","meaning":"Alarmierende Neugier sucht nach Fakten, stellt Fragen und achtet auf Veränderungen.","advice":"Forsche sorgfältig und spreche präzise, anstatt auf jedes Signal zu reagieren.","yesNoMeaning":"Der Bube der Schwerter bleibt bedingt: Forschen Sie sorgfältig und sprechen Sie präzise, statt auf jedes Signal zu reagieren."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-swords', 'de', '{"name":"Ritter der Schwerter","meaning":"Konzentrierter Intellekt bewegt sich schnell und stellt sich Hindernissen direkt.","advice":"Gehen Sie mutig voran, aber langsam genug, um zu hören, was Ihre Sicherheit möglicherweise verpasst.","yesNoMeaning":"Der Ritter der Schwerter bleibt bedingt: Gehe mutig voran, aber langsam genug, um zu hören, was deine Gewissheit möglicherweise übersieht."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-swords', 'de', '{"name":"Königin der Schwerter","meaning":"Klare Wahrnehmung und ehrliche Grenzen beseitigen Verwirrung.","advice":"Sprich, was wahr ist, mit Mitgefühl und lass die Erfahrung dich schärfen, nicht verhärten.","yesNoMeaning":"Die Königin der Schwerter tendiert zu ja: Sagen Sie, was wahr ist, mit Mitgefühl und lassen Sie Erfahrung Sie schärfen, nicht verhärten."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-swords', 'de', '{"name":"König der Schwerter","meaning":"Vernunft, Fairness und diszipliniertes Urteilsvermögen leiten eine folgenschwere Entscheidung.","advice":"Verwende Beweise, definiere den Standard und halte persönliche Vorurteile aus dem Urteil fern.","yesNoMeaning":"Der König der Schwerter neigt zu Ja: Nutze Beweise, definiere den Standard und halte persönliche Voreingenommenheit aus dem Urteil fern."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-pentacles', 'de', '{"name":"Ass der Münzen","meaning":"Eine greifbare Gelegenheit bietet den Samen für Wohlstand, Arbeit oder Wohlbefinden.","advice":"Verankere die Gelegenheit in einem praktischen Plan und pflege sie kontinuierlich.","yesNoMeaning":"Das Ass der Münzen tendiert zu Ja: Verankere die Gelegenheit in einem praktischen Plan und pflege sie konsequent."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-pentacles', 'de', '{"name":"Zwei der Münzen","meaning":"Mehrere Prioritäten bewegen sich gleichzeitig und erfordern ein flexibles Gleichgewicht.","advice":"Passen Sie den Rhythmus an, schützen Sie das Wesentliche und vermeiden Sie es, mehr zu versprechen, als Sie tragen können.","yesNoMeaning":"Die Zwei der Münzen bleibt bedingt: Passe den Rhythmus an, schütze das Wesentliche und vermeide es, mehr zu versprechen, als du tragen kannst."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-pentacles', 'de', '{"name":"Drei der Münzen","meaning":"Fähigkeit wächst durch Zusammenarbeit, Feedback und sorgfältige Handwerkskunst.","advice":"Trage deine Stärke bei, respektiere Fachwissen und baue auf einen gemeinsamen Standard.","yesNoMeaning":"Die Drei der Münzen tendiert zu ja: Trage deine Stärke bei, respektiere Fachwissen und baue nach einem gemeinsamen Standard."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-pentacles', 'de', '{"name":"Vier der Münzen","meaning":"Ein festes Festhalten an Sicherheit kann Ressourcen bewahren, aber den gesunden Fluss einschränken.","advice":"Schütze, was wichtig ist, ohne Angst jede Entscheidung für dich treffen zu lassen.","yesNoMeaning":"Die Vier der Münzen bleibt bedingt: Schütze, was wichtig ist, ohne dass Angst jede Entscheidung für dich trifft."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-pentacles', 'de', '{"name":"Fünf der Münzen","meaning":"Materielle Belastung oder Ausschluss erzeugt Sorge und ein Gefühl der Knappheit.","advice":"Bitte um praktische Hilfe und achte auf die Tür, die durch Schwierigkeiten leicht übersehen werden kann.","yesNoMeaning":"Die Fünf der Münzen neigt sich zu nein: Bitte um praktische Hilfe und achte auf die Tür, die Härte leicht übersehen lässt."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-pentacles', 'de', '{"name":"Sechs der Münzen","meaning":"Ressourcen werden ausgetauscht, was Fragen zu Großzügigkeit, Macht und Fairness aufwirft.","advice":"Gib oder empfange mit klaren Bedingungen, damit die Unterstützung die Würde beider Seiten bewahrt.","yesNoMeaning":"Die Sechs der Münzen tendiert zu Ja: Gib oder empfange mit klaren Bedingungen, damit Unterstützung die Würde auf beiden Seiten bewahrt."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-pentacles', 'de', '{"name":"Sieben der Münzen","meaning":"Geduldige Investition erreicht einen Punkt der Bewertung vor dem nächsten Einsatz.","advice":"Überprüfen Sie, was wächst, verbessern Sie die Methode und geben Sie lohnenswerten Ergebnissen Zeit.","yesNoMeaning":"Die Sieben der Münzen bleibt bedingt: Überprüfe, was wächst, verbessere die Methode und gib lohnenswerten Ergebnissen Zeit."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-pentacles', 'de', '{"name":"Acht der Münzen","meaning":"Fokussierte Wiederholung entwickelt Meisterschaft und verlässliche Ergebnisse.","advice":"Üben Sie die wesentliche Fähigkeit, nehmen Sie Korrektur an und lassen Sie Qualität sich ansammeln.","yesNoMeaning":"Die Acht der Münzen tendiert zu Ja: Übe die wesentliche Fähigkeit, begrüße Korrektur und lasse Qualität entstehen."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-pentacles', 'de', '{"name":"Neun der Münzen","meaning":"Selbstvertrauen und kultivierter Komfort spiegeln disziplinierten Fortschritt wider.","advice":"Genieße, was du aufgebaut hast, und halte Unabhängigkeit mit Dankbarkeit verbunden.","yesNoMeaning":"Die Neun der Münzen tendiert zu Ja: Genieße, was du aufgebaut hast, und halte die Unabhängigkeit im Einklang mit Dankbarkeit."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-pentacles', 'de', '{"name":"Zehn der Münzen","meaning":"Langfristige Sicherheit wächst durch Erbe, Familie und gemeinsame Grundlagen.","advice":"Planen Sie über den unmittelbaren Gewinn hinaus und schützen Sie, was anderen langfristig unterstützen kann.","yesNoMeaning":"Die Zehn der Münzen tendiert zu ja: plane über den unmittelbaren Gewinn hinaus und schütze, was anderen langfristig Unterstützung bieten kann."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-pentacles', 'de', '{"name":"Bube der Münzen","meaning":"Eine praktische Botschaft lädt zu Studium, Planung oder einem fundierten neuen Unternehmen ein.","advice":"Lerne die Grundlagen, definiere die nächste Aufgabe und beweise die Idee durch stetige Arbeit.","yesNoMeaning":"Der Bube der Münzen tendiert zu ja: Lernen Sie die Grundlagen, definieren Sie die nächste Aufgabe und beweisen Sie die Idee durch stetige Arbeit."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-pentacles', 'de', '{"name":"Ritter der Münzen","meaning":"Zuverlässige Arbeit schreitet langsam voran, gibt die Aufgabe aber selten auf.","advice":"Halten Sie die Routine ehrlich und konsequent; Fortschritt ist wichtiger als Aufregung.","yesNoMeaning":"Der Ritter der Münzen neigt zu Ja: Halte die Routine ehrlich und konsistent; Fortschritt ist wichtiger als Aufregung."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-pentacles', 'de', '{"name":"Königin der Münzen","meaning":"Einfallsreiche Fürsorge schafft Komfort, Gesundheit und praktischen Überfluss.","advice":"Pflege Menschen und Pläne auf eine Weise, die für dich nachhaltig bleibt.","yesNoMeaning":"Die Königin der Münzen tendiert zu ja: Pflegen Sie Menschen und Pläne auf eine Weise, die für Sie nachhaltig bleibt."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-pentacles', 'de', '{"name":"König der Münzen","meaning":"Materielle Führung verwandelt Erfahrung in stabile und großzügige Verwaltung.","advice":"Treffe die langfristige Wahl und nutze den Erfolg verantwortungsvoll.","yesNoMeaning":"Der König der Münzen neigt zu Ja: Triff die vernünftige langfristige Wahl und nutze Erfolg verantwortungsvoll."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aries', 'de', '{"name":"Widder","dateRange":"21. März – 19. April","rulingPlanet":"Mars","summary":"Kühne Anfänge und direkte Handlung charakterisieren den Widder, dessen Funke Absicht in Schwung verwandelt.","originStory":"Widder ist mit dem goldenen Widder verbunden, der Phrixus in der griechischen Mythologie rettete. Sein Fell wurde später der Preis von Jason und den Argonauten und bewahrte das Zeichen als Symbol für Mut, Rettung und den ersten mutigen Schritt.","traits":["Mutig","Energiegeladen","Unabhängig","Direkt"],"strengths":["Initiative","Selbstvertrauen","Resilienz"],"challenges":["Ungeduld","Impulsivität","Schneller starten, als man durchhalten kann"],"compatibleSigns":["Löwe","Schütze","Zwillinge"],"reflectionPrompt":"Wähle einen mutigen Anfang und gib ihm genug Geduld, um zu wachsen."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'day', 'de', '{"overview":"Heute begünstigt einen klaren, absichtlichen Schritt. Der Widder bewegt sich durch Feuerenergie. Mutige Anfänge und direktes Handeln definieren den Widder, dessen Funke Absicht in Momentum verwandelt.","love":"In der Liebe heute wähle Präsenz statt Annahme. Deine Gaben von Initiative, Selbstvertrauen und Resilienz können dir helfen, eine Verbindung herzustellen, ohne zu performen.","career":"Bei der Arbeit erledige die sinnvollste Aufgabe, bevor du neuen Schwung verfolgst. Nutze mutig, energisch, unabhängig, direkt als Werkzeuge, nicht als Erwartungen, die du alle auf einmal erfüllen musst.","finance":"Halte die heutigen Geldentscheidungen einfach und geerdet. Achte darauf, wann Ungeduld, Impulsivität oder ein schneller Start, den du nicht aufrechterhalten kannst, beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Eine kurze Pause kann deine Energie wiederherstellen. Wähle einen mutigen Anfang und gib ihm genügend Geduld, um zu wachsen.","guidance":"Bevor der Tag endet, denke daran: Wähle einen mutigen Anfang und gib ihm genug Geduld, um zu wachsen."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'week', 'de', '{"overview":"Diese Woche entwickelt sich durch beständige Entscheidungen statt eines einzigen dramatischen Moments. Widder bewegt sich durch Feuerenergie. Kühnne Anfänge und direkte Aktionen definieren den Widder, dessen Funke Absicht in Schwung verwandelt.","love":"Beziehungen profitieren von einem Gespräch, das sowohl Raum für Ehrlichkeit als auch für Herzlichkeit schafft. Deine Gaben von Initiative, Selbstvertrauen und Belastbarkeit können dir helfen, dich zu verbinden, ohne eine Leistung zu erbringen.","career":"Ihr bester beruflicher Fortschritt entsteht, indem Sie eine Priorität wählen und Zeit dafür schützen. Verwenden Sie mutig, energiegeladen, unabhängig, direkt als Werkzeuge, nicht als Erwartungen, die Sie auf einmal erfüllen müssen.","finance":"Überprüfen Sie das Muster hinter Ihren Ausgaben, bevor Sie eine größere Verpflichtung eingehen. Achten Sie darauf, wann Ungeduld, Impulsivität, schneller anfangen, als Sie durchhalten können, beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Balanciere Bewegung mit echter Erholung während der Woche. Wähle einen mutigen Anfang und gib ihm genug Geduld, um zu wachsen.","guidance":"Lass diese Frage die Woche leiten: Wähle einen mutigen Anfang und gib ihm genug Geduld, um zu wachsen."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'year', 'de', '{"overview":"Dieses Jahr lädt zu geduldigem Wachstum rund um Identität, Zweck und die Art und Weise, wie du deine Energie einsetzt, ein. Widder bewegt sich durch Feuerenergie. Kühne Anfänge und direkte Handlungen definieren den Widder, dessen Funke Absicht in Schwung verwandelt.","love":"Liebe vertieft sich, wenn du Beständigkeit übst und zulässt, dass sich Verbindung in menschlichem Tempo entwickelt. Deine Gaben von Initiative, Selbstvertrauen und Belastbarkeit können dir helfen, dich zu verbinden, ohne zu performen.","career":"Langfristige Arbeit wird stärker, wenn Ehrgeiz mit einer Struktur verbunden ist, die man aufrechterhalten kann. Verwenden Sie mutig, energisch, unabhängig, direkt als Werkzeuge, nicht als Erwartungen, die Sie alle auf einmal erfüllen müssen.","finance":"Stärke finanzielles Selbstvertrauen durch wiederholbare Gewohnheiten statt durch perfekte Vorhersagen. Achte darauf, wann Ungeduld, Impulsivität oder das zu schnelle Beginnen, bevor du es nachhaltig aufrechterhalten kannst, beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Betrachten Sie das Wohlbefinden als Grundlage für das Leben, das Sie aufbauen, nicht als Belohnung, nachdem Sie es beendet haben. Wählen Sie einen mutigen Anfang und geben Sie ihm genug Geduld zum Wachsen.","guidance":"Kehren Sie im Laufe des Jahres immer wieder zu diesem Kompass zurück: Wählen Sie einen mutigen Anfang und geben Sie ihm genügend Geduld, um zu wachsen."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('taurus', 'de', '{"name":"Stier","dateRange":"20. Apr – 20. Mai","rulingPlanet":"Venus","summary":"Stetig, sinnlich und geerdet, baut der Stier durch Geduld und Fürsorge bleibenden Wert auf.","originStory":"Stier erinnert daran, dass Zeus die Gestalt eines prächtigen weißen Stiers annahm, um Europa über das Meer zu tragen. Das Bild wurde mit Schönheit, Fruchtbarkeit, irdischer Fülle und Macht in Verbindung gebracht, die durch ruhige Beharrlichkeit ausgedrückt wird.","traits":["Geerdet","Loyal","Geduldig","Sinnlich"],"strengths":["Zuverlässigkeit","Praktische Weisheit","Hingabe"],"challenges":["Sturheit","Widerstand gegen Veränderungen","Zu lange festhalten"],"compatibleSigns":["Jungfrau","Steinbock","Krebs"],"reflectionPrompt":"Schütze, was wichtig ist, ohne Komfort mit Beständigkeit zu verwechseln."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'day', 'de', '{"overview":"Heute begünstigt einen klaren, bewussten Schritt. Stier bewegt sich durch Erdenergie. Beständig, sinnlich und geerdet baut der Stier durch Geduld und Fürsorge dauerhaften Wert auf.","love":"In der Liebe heute, wähle Präsenz über Annahme. Deine Gaben der Zuverlässigkeit, praktischen Weisheit und Hingabe können dir helfen, in Verbindung zu treten, ohne zu performen.","career":"Bei der Arbeit erledige die sinnvollste Aufgabe, bevor du neuen Schwung verfolgst. Nutze geerdet, loyal, geduldig, sinnlich als Werkzeuge, nicht als Erwartungen, die du alle gleichzeitig erfüllen musst.","finance":"Halten Sie die heutigen Geldentscheidungen einfach und geerdet. Achten Sie darauf, wann Sturheit, Widerstand gegen Veränderung oder das zu lange Festhalten beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Eine kurze Pause kann deine Energie wiederherstellen. Schütze, was wichtig ist, ohne Komfort mit Dauerhaftigkeit zu verwechseln.","guidance":"Bevor der Tag endet, denke daran: Schütze, was wichtig ist, ohne Komfort mit Beständigkeit zu verwechseln."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'week', 'de', '{"overview":"Diese Woche entwickelt sich durch beständige Entscheidungen statt durch einen dramatischen Moment. Stier bewegt sich durch Erdeenergie. Beständig, sinnlich und geerdet baut der Stier bleibenden Wert durch Geduld und Fürsorge auf.","love":"Beziehungen profitieren von einem Gespräch, das Raum für sowohl Ehrlichkeit als auch Wärme bietet. Ihre Gaben der Zuverlässigkeit, praktischen Weisheit und Hingabe können Ihnen helfen, sich zu verbinden, ohne eine Rolle zu spielen.","career":"Ihr bester beruflicher Fortschritt entsteht, indem Sie eine Priorität wählen und Zeit dafür schützen. Nutzen Sie bodenständig, loyal, geduldig, sinnlich als Werkzeuge, nicht als Erwartungen, die Sie alle auf einmal erfüllen müssen.","finance":"Überprüfen Sie das Muster hinter Ihren Ausgaben, bevor Sie eine größere Verpflichtung eingehen. Achten Sie darauf, wann Sturheit, Widerstand gegen Veränderungen, zu langes Festhalten beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Bewegung mit echter Erholung über die Woche hinweg ausgleichen. Schütze, was wichtig ist, ohne Komfort mit Dauerhaftigkeit zu verwechseln.","guidance":"Lass diese Frage die Woche leiten: Schütze, was wichtig ist, ohne Komfort mit Beständigkeit zu verwechseln."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'year', 'de', '{"overview":"Dieses Jahr lädt zu geduldigem Wachstum in Bezug auf Identität, Zweck und die Art und Weise, wie du deine Energie einsetzt, ein. Stier bewegt sich durch Erdenergie. Beständig, sinnlich und geerdet schafft der Stier durch Geduld und Fürsorge bleibenden Wert.","love":"Liebe vertieft sich, wenn du Beständigkeit übst und zulässt, dass Verbindung sich in menschlichem Tempo entwickelt. Deine Gaben für Zuverlässigkeit, praktische Weisheit, Hingabe können dir helfen, ohne Leistung dich zu verbinden.","career":"Langfristige Arbeit wird stärker, wenn Ehrgeiz mit einer Struktur gepaart wird, die man aufrechterhalten kann. Verwende geerdet, loyal, geduldig, sinnlich als Werkzeuge, nicht als Erwartungen, die du sofort erfüllen musst.","finance":"Bauen Sie finanzielles Vertrauen durch wiederholbare Gewohnheiten auf, anstatt auf perfekte Vorhersagen zu setzen. Achten Sie darauf, wann Sturheit, Widerstand gegen Veränderungen und zu langes Festhalten beginnen, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Betrachte das Wohlbefinden als Grundlage für das Leben, das du aufbaust, nicht als Belohnung, nachdem du es beendet hast. Schütze, was wichtig ist, ohne Komfort mit Dauerhaftigkeit zu verwechseln.","guidance":"Kehre im Laufe des Jahres immer wieder zu diesem Kompass zurück: Schütze, was wichtig ist, ohne Komfort mit Dauerhaftigkeit zu verwechseln."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('gemini', 'de', '{"name":"Zwillinge","dateRange":"21. Mai – 20. Juni","rulingPlanet":"Merkur","summary":"Neugier und Verbindung leiten die Zwillinge, die Ideen sammeln und mehr als eine Seite einer Geschichte enthüllen.","originStory":"Die Zwillinge stehen für Kastor und Pollux, unzertrennliche Zwillinge, die Unsterblichkeit teilten, statt getrennt zu bleiben. Ihr Sternbild trägt Themen wie Kameradschaft, doppelte Perspektive, Kommunikation und Bewegung zwischen den Welten.","traits":["Neugierig","Anpassungsfähig","Ausdrucksstark","Schnell denkend"],"strengths":["Kommunikation","Vielseitigkeit","Schnelles Lernen"],"challenges":["Unruhe","Zerstreute Konzentration","Zu viel nachdenken"],"compatibleSigns":["Waage","Wassermann","Widder"],"reflectionPrompt":"Lass die Neugier die Tür öffnen, bleibe dann lange genug, um zu verstehen, was du findest."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'day', 'de', '{"overview":"Heute begünstigt einen klaren, bewussten Schritt. Zwillinge bewegen sich durch Luftenergie. Neugier und Verbindung leiten die Zwillinge, die Ideen sammeln und mehr als eine Seite einer Geschichte offenbaren.","love":"In der Liebe wähle heute Gegenwart statt Annahme. Deine Gaben der Kommunikation, Vielseitigkeit, schnellen Lernfähigkeit können dir helfen, dich zu verbinden, ohne zu performen.","career":"Bei der Arbeit erledige die wichtigste Aufgabe, bevor du nach neuer Dynamik strebst. Nutze neugierig, anpassungsfähig, ausdrucksstark, schlagfertig als Werkzeuge, nicht als Erwartungen, die du alle auf einmal erfüllen musst.","finance":"Halte die heutigen Geldentscheidungen einfach und bodenständig. Achte darauf, wann Unruhe, zerstreute Aufmerksamkeit und Überdenken beginnen, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Eine kurze Pause kann deine Energie wiederherstellen. Lass Neugier die Tür öffnen und bleibe dann lange genug, um zu verstehen, was du findest.","guidance":"Bevor der Tag endet, denke daran: Lass Neugier die Tür öffnen, und bleibe dann lange genug, um zu verstehen, was du findest."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'week', 'de', '{"overview":"Diese Woche entwickelt sich durch beständige Entscheidungen statt durch einen dramatischen Moment. Zwillinge bewegen sich durch Luftenergie. Neugier und Verbindung leiten die Zwillinge, die Ideen sammeln und mehr als eine Seite einer Geschichte enthüllen.","love":"Beziehungen profitieren von einem Gespräch, das sowohl Ehrlichkeit als auch Wärme zulässt. Deine Gaben in Kommunikation, Vielseitigkeit und schnellem Lernen können dir helfen, Verbindungen herzustellen, ohne dich inszenieren zu müssen.","career":"Ihr bester beruflicher Fortschritt entsteht, indem Sie eine Priorität wählen und Zeit dafür schützen. Nutzen Sie Neugier, Anpassungsfähigkeit, Ausdruckskraft und Schlagfertigkeit als Werkzeuge, nicht als Erwartungen, die Sie alle auf einmal erfüllen müssen.","finance":"Überprüfen Sie das Muster hinter Ihren Ausgaben, bevor Sie eine größere Verpflichtung eingehen. Achten Sie darauf, wann Unruhe, zerstreute Aufmerksamkeit, Überdenken beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Balance zwischen Bewegung und echter Erholung während der Woche. Lass Neugier die Tür öffnen und bleib dann lange genug, um zu verstehen, was du findest.","guidance":"Lass diese Frage die Woche leiten: Lass Neugier die Tür öffnen, und bleibe dann lange genug, um zu verstehen, was du findest."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'year', 'de', '{"overview":"Dieses Jahr lädt zu geduldigem Wachstum in Bezug auf Identität, Zweck und die Art und Weise, wie du deine Energie einsetzt, ein. Die Zwillinge bewegen sich durch Luftenergie. Neugier und Verbindung leiten die Zwillinge, die Ideen sammeln und mehr als eine Seite einer Geschichte offenbaren.","love":"Liebe vertieft sich, wenn man Beständigkeit übt und zulässt, dass sich Verbindung in menschlichem Tempo entwickelt. Deine Gaben der Kommunikation, Vielseitigkeit und schnellen Lernfähigkeit können dir helfen, dich zu verbinden, ohne eine Vorstellung zu geben.","career":"Langfristige Arbeit wird stärker, wenn Ehrgeiz mit einer Struktur gepaart wird, die man aufrechterhalten kann. Verwende neugierig, anpassungsfähig, ausdrucksstark, scharfsinnig als Werkzeuge, nicht als Erwartungen, die du sofort erfüllen musst.","finance":"Bauen Sie finanzielles Vertrauen durch wiederholbare Gewohnheiten auf, anstatt auf perfekte Vorhersagen zu setzen. Achten Sie darauf, wann Unruhe, zerstreute Aufmerksamkeit und Überdenken beginnen, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Betrachte das Wohlbefinden als Grundlage für das Leben, das du aufbaust, nicht als Belohnung, nachdem du es beendet hast. Lass Neugier die Tür öffnen und bleibe dann lange genug, um zu verstehen, was du findest.","guidance":"Kehre im Laufe des Jahres immer wieder zu diesem Kompass zurück: Lass Neugier die Tür öffnen, und bleibe dann lange genug, um zu verstehen, was du findest."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('cancer', 'de', '{"name":"Krebs","dateRange":"21. Juni – 22. Juli","rulingPlanet":"Mond","summary":"Beschützend und intuitiv schafft der Krebs Zugehörigkeit, indem er Erinnerung, Gefühl und Zuhause ehrt.","originStory":"Krebs ist mit dem Krebs Karkinos verbunden, der unter die Sterne gesetzt wurde, nachdem er während des Kampfes von Herakles mit der Hydra Loyalität gezeigt hatte. Sein Panzer und seine lunare Herrschaft spiegeln Schutz, emotionale Gezeiten und Hingabe an den eigenen inneren Kreis wider.","traits":["Intuitiv","Fürsorglich","Beschützend","Phantasievoll"],"strengths":["Empathie","Loyalität","Emotionale Einsicht"],"challenges":["Launenhaftigkeit","Hinter Verteidigungen zurückziehen","Alles persönlich nehmen"],"compatibleSigns":["Skorpion","Fische","Stier"],"reflectionPrompt":"Kümmere dich um deine innere Welt, während du eine Tür für ehrliche Verbindung offen lässt."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'day', 'de', '{"overview":"Heute begünstigt einen klaren, gezielten Schritt. Krebs bewegt sich durch Wasserenergie. Schutzbereit und intuitiv schafft der Krebs Zugehörigkeit, indem er Erinnerung, Gefühl und Zuhause ehrt.","love":"In der Liebe heute wähle Präsenz statt Annahme. Deine Gaben von Empathie, Loyalität und emotionalem Einfühlungsvermögen können dir helfen, eine Verbindung herzustellen, ohne zu performen.","career":"Bei der Arbeit erledige die sinnvollste Aufgabe, bevor du neuen Schwung verfolgst. Nutze intuitiv, fürsorglich, schützend, einfallsreich als Werkzeuge, nicht als Erwartungen, die du alle auf einmal erfüllen musst.","finance":"Halten Sie die heutigen Geldentscheidungen einfach und geerdet. Achten Sie darauf, wann Stimmungsschwankungen, das Zurückziehen hinter Abwehrmechanismen oder das Persönlich-nehmen von Dingen beginnen, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Eine kurze Pause kann deine Energie wiederherstellen. Kümmere dich um deine innere Welt, während du eine Tür für ehrliche Verbindung offen lässt.","guidance":"Bevor der Tag endet, denke daran: Kümmere dich um deine innere Welt, während du eine Tür für ehrliche Verbindung offen lässt."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'week', 'de', '{"overview":"Diese Woche entwickelt sich durch beständige Entscheidungen statt eines einzigen dramatischen Moments. Krebs bewegt sich durch Wasserenergie. Beschützend und intuitiv schafft der Krebs Zugehörigkeit, indem er Erinnerung, Gefühl und Heimat ehrt.","love":"Beziehungen profitieren von einem Gespräch, das Raum sowohl für Ehrlichkeit als auch für Wärme lässt. Deine Gaben von Empathie, Loyalität und emotionaler Einsicht können dir helfen, eine Verbindung herzustellen, ohne eine Rolle zu spielen.","career":"Ihr größter beruflicher Fortschritt entsteht, indem Sie eine Priorität wählen und dafür Zeit schützen. Verwenden Sie intuitiv, fürsorglich, schützend, einfallsreich als Werkzeuge, nicht als Erwartungen, die Sie alle auf einmal erfüllen müssen.","finance":"Überprüfen Sie das Muster hinter Ihren Ausgaben, bevor Sie eine größere Verpflichtung eingehen. Achten Sie darauf, wann Launenhaftigkeit, das Zurückziehen hinter Abwehrmechanismen und das Persönlichnehmen von Dingen beginnen, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Balance zwischen Bewegung und echter Erholung während der Woche. Kümmere dich um deine innere Welt und lass gleichzeitig eine Tür zu ehrlicher Verbindung offen.","guidance":"Lass diese Frage die Woche leiten: Kümmere dich um deine innere Welt, während du eine Tür für ehrliche Verbindung offen lässt."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'year', 'de', '{"overview":"Dieses Jahr lädt zu geduldigem Wachstum in Bezug auf Identität, Zweck und die Art und Weise, wie du deine Energie einsetzt, ein. Der Krebs bewegt sich durch Wasserenergie. Schutzbietend und intuitiv schafft der Krebs Zugehörigkeit, indem er Erinnerung, Gefühl und Zuhause ehrt.","love":"Liebe vertieft sich, wenn du Beständigkeit übst und zulässt, dass sich Verbindung in menschlichem Tempo entwickelt. Deine Gaben von Empathie, Loyalität und emotionaler Einsicht können dir helfen, dich zu verbinden, ohne zu performen.","career":"Langfristige Arbeit wird stärker, wenn Ehrgeiz mit einer Struktur kombiniert wird, die Sie aufrechterhalten können. Verwenden Sie intuitiv, fürsorglich, beschützend, einfallsreich als Werkzeuge, nicht als Erwartungen, die Sie auf einmal erfüllen müssen.","finance":"Bauen Sie finanzielles Vertrauen durch wiederholbare Gewohnheiten auf, anstatt durch perfekte Vorhersagen. Achten Sie darauf, wann Launenhaftigkeit, das Zurückziehen hinter Verteidigungen oder das persönlich Nehmen von Dingen beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Betrachten Sie das Wohlbefinden als Grundlage für das Leben, das Sie aufbauen, nicht als Belohnung, nachdem Sie es beendet haben. Kümmern Sie sich um Ihre innere Welt, während Sie eine Tür für ehrliche Verbindung offenlassen.","guidance":"Kehren Sie im Laufe des Jahres immer wieder zu diesem Kompass zurück: Kümmern Sie sich um Ihre innere Welt, während Sie eine Tür für ehrliche Verbindung offenlassen."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('leo', 'de', '{"name":"Löwe","dateRange":"23. Juli – 22. August","rulingPlanet":"Sonne","summary":"Wärme, Kreativität und großzügiger Selbstausdruck machen den Löwen zu einer natürlichen Lichtquelle.","originStory":"Leo ist an den Nemeischen Löwen gebunden, die fast unverwundbare Kreatur, die in Herakles'' erstem Arbeitsauftrag besiegt wurde. In den Himmel erhoben, wurde er zu einem Symbol für Mut, souveräne Präsenz und die schöpferische Kraft der Sonne.","traits":["Warm","Kreativ","Großzügig","Zuversichtlich"],"strengths":["Führung","Loyalität","Herzlicher Ausdruck"],"challenges":["Stolz","Braucht Anerkennung","Dramatisierung von Rückschlägen"],"compatibleSigns":["Widder","Schütze","Waage"],"reflectionPrompt":"Teile dein Licht großzügig und lass andere neben dir strahlen."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'day', 'de', '{"overview":"Heute begünstigt einen klaren, bewussten Schritt. Leo bewegt sich durch Feuerenergie. Wärme, Kreativität und großzügiger Selbstausdruck machen den Löwen zu einer natürlichen Lichtquelle.","love":"In der Liebe heute wähle Präsenz statt Annahme. Deine Gaben von Führung, Loyalität und aufrichtiger Ausdruckskraft können dir helfen, eine Verbindung herzustellen, ohne zu performen.","career":"Bei der Arbeit erledige die wichtigste Aufgabe, bevor du neue Impulse verfolgst. Nutze warmherzig, kreativ, großzügig, selbstbewusst als Werkzeuge, nicht als Erwartungen, die du alle auf einmal erfüllen musst.","finance":"Halte die heutigen Geldentscheidungen einfach und bodenständig. Achte darauf, wann Stolz, das Bedürfnis nach Anerkennung oder das Dramatisieren von Rückschlägen beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Eine kleine Pause kann deine Energie zurücksetzen. Teile dein Licht großzügig und lass andere neben dir erstrahlen.","guidance":"Bevor der Tag zu Ende geht, erinnere dich: Teile dein Licht großzügig und lass andere neben dir strahlen."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'week', 'de', '{"overview":"Diese Woche entwickelt sich durch beständige Entscheidungen statt durch einen einzigen dramatischen Moment. Löwe bewegt sich durch Feuerenergie. Wärme, Kreativität und großzügiger Selbstausdruck machen den Löwen zu einer natürlichen Lichtquelle.","love":"Beziehungen profitieren von einem Gespräch, das Raum für sowohl Ehrlichkeit als auch Wärme bietet. Ihre Gaben der Führung, Loyalität und herzlichen Ausdrucksweise können Ihnen helfen, sich zu verbinden, ohne eine Rolle zu spielen.","career":"Ihr größter beruflicher Fortschritt entsteht, indem Sie eine Priorität wählen und dafür Zeit schützen. Verwenden Sie warm, kreativ, großzügig, selbstbewusst als Werkzeuge, nicht als Erwartungen, die Sie alle auf einmal erfüllen müssen.","finance":"Überprüfen Sie das Muster Ihres Ausgabeverhaltens, bevor Sie sich zu einer größeren Verpflichtung entscheiden. Achten Sie darauf, wann Stolz, das Bedürfnis nach Anerkennung oder das Dramatisieren von Rückschlägen beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Bewegung mit echter Erholung über die Woche hinweg ausgleichen. Teile dein Licht großzügig und lasse andere neben dir erstrahlen.","guidance":"Lass diese Frage die Woche leiten: Teile dein Licht großzügig und lass andere neben dir strahlen."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'year', 'de', '{"overview":"Dieses Jahr lädt zu geduldigem Wachstum in Bezug auf Identität, Zweck und die Art und Weise, wie du deine Energie einsetzt, ein. Löwe bewegt sich durch Feuerenergie. Wärme, Kreativität und großzügiger Selbstausdruck machen den Löwen zu einer natürlichen Lichtquelle.","love":"Liebe vertieft sich, wenn du Beständigkeit übst und zulässt, dass Verbindung sich in menschlichem Tempo entwickelt. Deine Gaben für Führung, Loyalität, herzliche Ausdrucksweise können dir helfen, ohne Leistung dich zu verbinden.","career":"Langfristige Arbeit wird stärker, wenn Ehrgeiz mit einer Struktur kombiniert wird, die Sie aufrechterhalten können. Verwenden Sie warmherzig, kreativ, großzügig, selbstbewusst als Werkzeuge, nicht als Erwartungen, die Sie auf einmal erfüllen müssen.","finance":"Bauen Sie finanzielles Vertrauen durch wiederholbare Gewohnheiten statt durch perfekte Vorhersagen auf. Achten Sie darauf, wann Stolz, das Bedürfnis nach Anerkennung oder das Dramatisieren von Rückschlägen beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Betrachte Wohlbefinden als Grundlage für das Leben, das du aufbaust, nicht als Belohnung danach. Teile dein Licht großzügig und lass andere neben dir strahlen.","guidance":"Kehre im Laufe des Jahres immer wieder zu diesem Kompass zurück: Teile dein Licht großzügig und lass andere an deiner Seite strahlen."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('virgo', 'de', '{"name":"Jungfrau","dateRange":"23. Aug. – 22. Sep.","rulingPlanet":"Merkur","summary":"Urteilsvermögen und Dienst leiten die Jungfrau, indem sorgfältige Beobachtung in praktische Verbesserung umgesetzt wird.","originStory":"Jungfrau wird oft mit Astraea verbunden, der Jungfrau der Gerechtigkeit, die bei den Menschen blieb, nachdem andere Götter sich zurückgezogen hatten. Der Weizen, den sie trägt, verbindet das Zeichen mit Ernte, Geschick, Reinheit der Absichten und der Pflege dessen, was das Leben erhält.","traits":["Beobachtend","Praktisch","Nachdenklich","Präzise"],"strengths":["Analyse","Handwerkskunst","Hilfreicher Service"],"challenges":["Perfektionismus","Selbstkritik","Sich über Details Sorgen machen"],"compatibleSigns":["Stier","Steinbock","Krebs"],"reflectionPrompt":"Verbessere, was du kannst, und erlaube guter Arbeit, abgeschlossen zu sein, bevor sie perfekt ist."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'day', 'de', '{"overview":"Heute begünstigt einen klaren, bewussten Schritt. Die Jungfrau bewegt sich durch Erdenergie. Unterscheidungsvermögen und Dienst leiten die Jungfrau und verwandeln sorgfältige Beobachtung in praktische Verbesserung.","love":"In der Liebe wähle heute Gegenwart statt Annahme. Deine Gaben der Analyse, Handwerkskunst, hilfreichen Dienstleistung können dir helfen, dich zu verbinden, ohne zu performen.","career":"Bei der Arbeit erledige zuerst die wichtigste Aufgabe, bevor du nach neuer Dynamik strebst. Nutze aufmerksam, praktisch, bedacht, präzise als Werkzeuge, nicht als Erwartungen, die du alle auf einmal erfüllen musst.","finance":"Halten Sie die heutigen Geldentscheidungen einfach und bodenständig. Achten Sie darauf, wann Perfektionismus, Selbstkritik und das Grübeln über Details beginnen, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Eine kurze Pause kann deine Energie wiederherstellen. Verbessere, was du kannst, und erlaube gute Arbeit, abgeschlossen zu sein, bevor sie perfekt ist.","guidance":"Bevor der Tag endet, denke daran: Verbessere, was du kannst, und erlaube guter Arbeit, abgeschlossen zu sein, bevor sie perfekt ist."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'week', 'de', '{"overview":"Diese Woche entwickelt sich durch stetige Entscheidungen statt durch einen dramatischen Moment. Die Jungfrau bewegt sich durch Erdenergie. Unterscheidungsvermögen und Dienst leiten die Jungfrau, wobei sorgfältige Beobachtung in praktische Verbesserungen umgesetzt wird.","love":"Beziehungen profitieren von einem Gespräch, das sowohl Ehrlichkeit als auch Wärme zulässt. Deine Gaben in Analyse, Handwerkskunst und hilfreichem Dienst können dir helfen, Verbindungen herzustellen, ohne dich inszenieren zu müssen.","career":"Ihr größter beruflicher Fortschritt entsteht, indem Sie eine Priorität wählen und dafür Zeit schützen. Verwenden Sie aufmerksam, praktisch, nachdenklich, präzise als Werkzeuge, nicht als Erwartungen, die Sie alle auf einmal erfüllen müssen.","finance":"Überprüfen Sie das Muster hinter Ihren Ausgaben, bevor Sie eine größere Verpflichtung eingehen. Achten Sie darauf, wann Perfektionismus, Selbstkritik und das Grübeln über Details beginnen, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Gleiche Bewegung mit echter Erholung während der Woche aus. Verbessern Sie, was Sie können, und lassen Sie gute Arbeit abschließen, bevor sie perfekt ist.","guidance":"Lass diese Frage die Woche leiten: Verbessere, was du kannst, und erlaube guter Arbeit, abgeschlossen zu sein, bevor sie perfekt ist."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'year', 'de', '{"overview":"Dieses Jahr lädt zu geduldigem Wachstum in Bezug auf Identität, Zweck und die Art und Weise, wie du deine Energie einsetzt, ein. Die Jungfrau bewegt sich durch Erdenergie. Urteilsvermögen und Dienst führen die Jungfrau und verwandeln sorgfältige Beobachtung in praktische Verbesserungen.","love":"Liebe vertieft sich, wenn man Beständigkeit übt und zulässt, dass sich Verbindung in menschlichem Tempo entwickelt. Deine Gaben der Analyse, des Handwerks und des hilfreichen Dienstes können dir helfen, dich zu verbinden, ohne zu performen.","career":"Langfristige Arbeit wird stärker, wenn Ehrgeiz mit einer Struktur kombiniert wird, die Sie aufrechterhalten können. Verwenden Sie aufmerksam, praktisch, nachdenklich, genau als Werkzeuge, nicht als Erwartungen, die Sie auf einmal erfüllen müssen.","finance":"Bauen Sie finanzielles Vertrauen durch wiederholbare Gewohnheiten auf, anstatt durch perfekte Vorhersagen. Achten Sie darauf, wann Perfektionismus, Selbstkritik und das Sorgen um Details beginnen, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Betrachte das Wohlbefinden als Grundlage für das Leben, das du aufbaust, nicht als Belohnung, nachdem du es beendet hast. Verbessere, was du kannst, und lass gute Arbeit abgeschlossen sein, bevor sie perfekt ist.","guidance":"Kehre im Laufe des Jahres immer wieder zu diesem Kompass zurück: Verbessere, was du kannst, und erlaube guter Arbeit, abgeschlossen zu sein, bevor sie perfekt ist."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('libra', 'de', '{"name":"Waage","dateRange":"23. Sep – 22. Okt","rulingPlanet":"Venus","summary":"Gleichgewicht, Schönheit und Gegenseitigkeit leiten die Waage zu Entscheidungen, die jede Stimme ehren.","originStory":"Die Waagschalen der Waage werden von Astraea, der Göttin der Gerechtigkeit, getragen und bilden das einzige unbelebte Symbol des Tierkreises. Sie stehen für abgewogene Urteile, soziale Harmonie und die fortwährende Arbeit, das Gleichgewicht wiederherzustellen, anstatt anzunehmen, dass es bereits existiert.","traits":["Diplomatisch","Fair-minded (gerecht denkend)","Charmant","Kooperativ"],"strengths":["Mediation","Perspektive","Harmonie schaffen"],"challenges":["Unentschlossenheit","Menschen gefallen","Notwendigen Konflikten ausweichen"],"compatibleSigns":["Zwillinge","Wassermann","Löwe"],"reflectionPrompt":"Strebe nach Gerechtigkeit, ohne die Wahrheit deiner eigenen Bedürfnisse aufzugeben."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'day', 'de', '{"overview":"Heute begünstigt einen klaren, bewussten Schritt. Waage bewegt sich durch die Luftelementenergie. Gleichgewicht, Schönheit und Gegenseitigkeit führen die Waage zu Entscheidungen, die jede Stimme ehren.","love":"In der Liebe heute, wähle Präsenz über Annahme. Deine Gaben der Vermittlung, Perspektive und Harmoniefindung können dir helfen, in Verbindung zu treten, ohne zu performen.","career":"Bei der Arbeit erledige die bedeutendste Aufgabe, bevor du neuer Dynamik nachjagst. Nutze diplomatisch, fair, charmant, kooperativ als Werkzeuge, nicht als Erwartungen, die du alle auf einmal erfüllen musst.","finance":"Halten Sie die heutigen Geldentscheidungen einfach und bodenständig. Achten Sie darauf, wann Unentschlossenheit, Gefälligkeit gegenüber anderen und das Vermeiden notwendiger Konflikte beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Eine kleine Pause kann deine Energie zurücksetzen. Strebe nach Fairness, ohne die Wahrheit deiner eigenen Bedürfnisse aufzugeben.","guidance":"Bevor der Tag zu Ende geht, erinnere dich: Suche Gerechtigkeit, ohne die Wahrheit deiner eigenen Bedürfnisse zu verleugnen."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'week', 'de', '{"overview":"Diese Woche entwickelt sich durch beständige Entscheidungen statt durch einen einzigen dramatischen Moment. Die Waage bewegt sich durch die Energie der Luft. Gleichgewicht, Schönheit und Gegenseitigkeit leiten die Waagschalen zu Entscheidungen, die jede Stimme ehren.","love":"Beziehungen profitieren von einem Gespräch, das Raum für sowohl Ehrlichkeit als auch Wärme bietet. Ihre Gaben der Vermittlung, Perspektive und Harmoniefindung können Ihnen helfen, sich zu verbinden, ohne eine Rolle zu spielen.","career":"Ihr bester beruflicher Fortschritt entsteht, indem Sie eine Priorität wählen und Zeit dafür schützen. Nutzen Sie diplomatisch, gerecht, charmant, kooperativ als Werkzeuge, nicht als Erwartungen, die Sie alle auf einmal erfüllen müssen.","finance":"Überprüfen Sie das Muster hinter Ihren Ausgaben, bevor Sie eine größere Verpflichtung eingehen. Achten Sie darauf, wann Unentschlossenheit, das Gefallenwollen anderer oder das Vermeiden notwendiger Konflikte beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Bewegung mit echter Erholung über die Woche hinweg ausgleichen. Strebe nach Gerechtigkeit, ohne die Wahrheit deiner eigenen Bedürfnisse zu vernachlässigen.","guidance":"Lass diese Frage die Woche leiten: Suche Gerechtigkeit, ohne die Wahrheit deiner eigenen Bedürfnisse aufzugeben."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'year', 'de', '{"overview":"Dieses Jahr lädt zu geduldigem Wachstum in Bezug auf Identität, Zweck und die Art und Weise, wie du deine Energie einsetzt, ein. Die Waage bewegt sich durch Luftenergie. Gleichgewicht, Schönheit und Gegenseitigkeit führen die Waagschalen zu Entscheidungen, die jede Stimme ehren.","love":"Liebe vertieft sich, wenn du Beständigkeit übst und zulässt, dass Verbindung sich in menschlichem Tempo entwickelt. Deine Gaben für Vermittlung, Perspektive, Harmonie schaffen können dir helfen, ohne Leistung dich zu verbinden.","career":"Langfristige Arbeit wird stärker, wenn Ehrgeiz mit einer Struktur gepaart wird, die man aufrechterhalten kann. Verwende diplomatisch, gerecht, charmant, kooperativ als Werkzeuge, nicht als Erwartungen, die du sofort erfüllen musst.","finance":"Bauen Sie finanzielles Vertrauen durch wiederholbare Gewohnheiten auf, anstatt durch perfekte Vorhersagen. Achten Sie darauf, wann Unentschlossenheit, das Bedürfnis, anderen zu gefallen, oder das Vermeiden notwendiger Konflikte beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Betrachte das Wohlbefinden als Grundlage für das Leben, das du aufbaust, nicht als Belohnung, nachdem du es beendet hast. Strebe nach Fairness, ohne die Wahrheit deiner eigenen Bedürfnisse aufzugeben.","guidance":"Kehre im Laufe des Jahres immer wieder zu diesem Kompass zurück: Suche nach Gerechtigkeit, ohne die Wahrheit deiner eigenen Bedürfnisse aufzugeben."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('scorpio', 'de', '{"name":"Skorpion","dateRange":"23. Okt – 21. Nov","rulingPlanet":"Pluto","summary":"Tiefe und Transformation definieren den Skorpion, dessen Einsicht die Wahrheit unter der Oberfläche findet.","originStory":"Skorpion erinnert an den Skorpion, der geschickt wurde, um den Jäger Orion zu konfrontieren, nachdem sein Stolz die natürliche Ordnung gestört hatte. Ihre gegenüberliegenden Positionen am Himmel rufen Grenzen, Konsequenzen, Geheimnisse und die regenerative Kraft hervor, die nach einem Ende gefunden wird.","traits":["Intensiv","Wahrnehmungsfähig","Loyal","Einfallsreich"],"strengths":["Emotionaler Mut","Fokus","Transformation"],"challenges":["Geheimhaltung","Verdacht","Groll hegen"],"compatibleSigns":["Krebs","Fische","Jungfrau"],"reflectionPrompt":"Nutze deine Tiefe, um die Wahrheit zu transformieren, nicht um sie zu verbergen."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'day', 'de', '{"overview":"Heute begünstigt einen klaren, bewussten Schritt. Der Skorpion bewegt sich durch Wasserenergie. Tiefe und Transformation definieren den Skorpion, dessen Einsicht die Wahrheit unter der Oberfläche findet.","love":"In der Liebe wähle heute Gegenwart statt Annahme. Deine Gaben des emotionalen Mutes, der Konzentration, der Transformation können dir helfen, dich zu verbinden, ohne zu performen.","career":"Bei der Arbeit erledige die wichtigste Aufgabe, bevor du nach neuer Dynamik strebst. Nutze intensiv, einfühlsam, loyal, einfallsreich als Werkzeuge, nicht als Erwartungen, die du alle auf einmal erfüllen musst.","finance":"Halten Sie die heutigen Geldentscheidungen einfach und bodenständig. Achten Sie darauf, wann Geheimniskrämerei, Misstrauen oder Groll beginnen, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Eine kleine Pause kann deine Energie zurücksetzen. Nutze deine Tiefe, um die Wahrheit zu verwandeln, nicht um sie zu verstecken.","guidance":"Bevor der Tag zu Ende geht, erinnere dich: Nutze deine Tiefe, um die Wahrheit zu verwandeln, nicht um sie zu verstecken."}');
