INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('sagittarius', 'de', '{"name":"Schütze","dateRange":"22. Nov – 21. Dez","rulingPlanet":"Jupiter","summary":"Der Bogenschütze sucht weitere Horizonte durch Wahrheit, Reisen, Lernen und zielgerichteten Optimismus.","originStory":"Schütze wird häufig mit Chiron in Verbindung gebracht, dem weisen Zentauren und Lehrer, dessen Pfeil über das Bekannte hinausweist. Das Sternbild symbolisiert die Vereinigung von Instinkt und höherem Verständnis und strebt stets nach einem bedeutungsvolleren Horizont.","traits":["Abenteuerlustig","Optimistisch","Ehrlich","Philosophisch"],"strengths":["Vision","Enthusiasmus","Aufgeschlossenheit"],"challenges":["Direktheit","Zu viel versprechen","Die Routine entkommen"],"compatibleSigns":["Widder","Löwe","Wassermann"],"reflectionPrompt":"Ziele hoch, aber wähle eine Richtung, die deine täglichen Handlungen unterstützen können."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'day', 'de', '{"overview":"Heute begünstigt einen klaren, bewussten Schritt. Schütze bewegt sich durch Feuerenergie. Der Bogenschütze sucht breitere Horizonte durch Wahrheit, Reisen, Lernen und zielgerichteten Optimismus.","love":"In der Liebe heute, wähle Präsenz über Annahme. Deine Gaben von Vision, Begeisterung und Aufgeschlossenheit können dir helfen, in Verbindung zu treten, ohne zu performen.","career":"Bei der Arbeit erledige die bedeutendste Aufgabe, bevor du nach neuem Schwung strebst. Verwende abenteuerlich, optimistisch, ehrlich, philosophisch als Werkzeuge, nicht als Erwartungen, die du alle auf einmal erfüllen musst.","finance":"Halten Sie die heutigen Geldentscheidungen einfach und bodenständig. Achten Sie darauf, wann Direktheit, Überversprechen oder das Entkommen aus der Routine beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Eine kurze Pause kann deine Energie zurücksetzen. Ziele hoch, aber wähle eine Richtung, die deine täglichen Handlungen unterstützen können.","guidance":"Bevor der Tag endet, erinnere dich: Ziele hoch, aber wähle eine Richtung, die deine täglichen Handlungen unterstützen können."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'week', 'de', '{"overview":"Diese Woche entwickelt sich durch beständige Entscheidungen statt durch einen dramatischen Moment. Schütze bewegt sich durch Feuerenergie. Der Bogenschütze sucht weitere Horizonte durch Wahrheit, Reisen, Lernen und zielgerichteten Optimismus.","love":"Beziehungen profitieren von einem Gespräch, das sowohl Ehrlichkeit als auch Wärme zulässt. Ihre Gaben von Weitblick, Begeisterung und Aufgeschlossenheit können Ihnen helfen, sich zu verbinden, ohne eine Rolle zu spielen.","career":"Ihr bester beruflicher Fortschritt entsteht, indem Sie eine Priorität wählen und Zeit dafür schützen. Verwenden Sie abenteuerlustig, optimistisch, ehrlich, philosophisch als Werkzeuge, nicht als Erwartungen, die Sie auf einmal erfüllen müssen.","finance":"Überprüfen Sie das Muster hinter Ihren Ausgaben, bevor Sie eine größere Verpflichtung eingehen. Achten Sie darauf, wann Direktheit, Überversprechen, die Flucht vor Routine beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Bewege dich ausgewogen und gönne dir echte Erholung während der Woche. Ziele weit, wähle aber eine Richtung, die deine täglichen Handlungen unterstützen.","guidance":"Lassen Sie diese Frage die Woche leiten: Zielen Sie hoch, aber wählen Sie eine Richtung, die Ihre täglichen Handlungen unterstützen können."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'year', 'de', '{"overview":"Dieses Jahr lädt zu geduldigem Wachstum rund um Identität, Zweck und die Art und Weise, wie du deine Energie einsetzt, ein. Schütze bewegt sich durch Feuerenergie. Der Bogenschütze sucht durch Wahrheit, Reisen, Lernen und zielgerichteten Optimismus nach weiteren Horizonten.","love":"Liebe vertieft sich, wenn du Beständigkeit übst und zulässt, dass sich Verbindung in menschlichem Tempo entwickelt. Deine Gaben von Vision, Enthusiasmus und Aufgeschlossenheit können dir helfen, dich zu verbinden, ohne etwas vorzutäuschen.","career":"Langfristige Arbeit wird stärker, wenn Ehrgeiz mit einer Struktur verbunden ist, die man aufrechterhalten kann. Verwenden Sie abenteuerlustig, optimistisch, ehrlich, philosophisch als Werkzeuge, nicht als Erwartungen, die Sie alle auf einmal erfüllen müssen.","finance":"Baue finanzielles Vertrauen durch wiederholbare Gewohnheiten statt durch perfekte Vorhersagen auf. Achte darauf, wann Offenheit, Überversprechen oder das Ausweichen aus der Routine beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Betrachte Wohlbefinden als Grundlage für das Leben, das du aufbaust, nicht als Belohnung nach dessen Vollendung. Strebe weit, aber wähle eine Richtung, die deine täglichen Handlungen unterstützen können.","guidance":"Kehren Sie im Laufe des Jahres immer wieder zu diesem Kompass zurück: Streben Sie weit, aber wählen Sie eine Richtung, die Ihre täglichen Handlungen unterstützen können."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('capricorn', 'de', '{"name":"Steinbock","dateRange":"22. Dez – 19. Jan","rulingPlanet":"Saturn","summary":"Disziplin und Weitblick helfen dem Steinbock beim Aufstieg, während er sich der Tiefen darunter bewusst bleibt.","originStory":"Der Meeresziegenbock des Steinbocks wird mit Pan in Verbindung gebracht, der sich teilweise in einen Fisch verwandelte, um Typhon zu entkommen. Seine Berg- und Ozeannatur verbindet Ehrgeiz mit emotionalem Überleben und ehrt die durch Zeit und Verantwortung erlangte Meisterschaft.","traits":["Ambitioniert","Diszipliniert","Geduldig","Verantwortlich"],"strengths":["Ausdauer","Strategie","Zuverlässigkeit"],"challenges":["Starre","Pessimismus","Den Wert durch Leistung messen"],"compatibleSigns":["Stier","Jungfrau","Skorpion"],"reflectionPrompt":"Bauen Sie für die langfristige Perspektive auf, während Sie sich daran erinnern, dass Ruhe Teil der Struktur ist."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'day', 'de', '{"overview":"Heute spricht sich für einen klaren, absichtlichen Schritt aus. Der Steinbock bewegt sich durch Erdenergie. Disziplin und Weitblick helfen dem Steinbock, aufzusteigen, während er dabei die Tiefen darunter weise berücksichtigt.","love":"In der Liebe heute wähle Präsenz statt Annahme. Deine Gaben von Ausdauer, Strategie und Zuverlässigkeit können dir helfen, eine Verbindung herzustellen, ohne zu performen.","career":"Bei der Arbeit erledige die bedeutendste Aufgabe, bevor du nach neuem Schwung strebst. Verwende ehrgeizig, diszipliniert, geduldig, verantwortungsbewusst als Werkzeuge, nicht als Erwartungen, die du alle auf einmal erfüllen musst.","finance":"Halte die heutigen Geldentscheidungen einfach und geerdet. Achte darauf, wann Starrheit, Pessimismus und die Bewertung des Wertes durch Leistung beginnen, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Eine kleine Pause kann Ihre Energie zurücksetzen. Bauen Sie langfristig auf, während Sie daran denken, dass Ruhe Teil der Struktur ist.","guidance":"Bevor der Tag endet, denke daran: Baue für die langfristige Zukunft, während du daran denkst, dass Ruhe Teil der Struktur ist."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'week', 'de', '{"overview":"Diese Woche entwickelt sich durch beständige Entscheidungen anstatt durch einen dramatischen Moment. Der Steinbock bewegt sich durch Erdenergie. Disziplin und Weitblick helfen der Steinziege beim Aufstieg, während sie weise über die Tiefen darunter bleibt.","love":"Beziehungen profitieren von einem Gespräch, das Raum sowohl für Ehrlichkeit als auch für Wärme lässt. Deine Gaben von Ausdauer, Strategie und Zuverlässigkeit können dir helfen, dich zu verbinden, ohne eine Rolle zu spielen.","career":"Ihr bester beruflicher Fortschritt entsteht, indem Sie eine Priorität wählen und Zeit dafür schützen. Verwenden Sie ehrgeizig, diszipliniert, geduldig, verantwortungsbewusst als Werkzeuge, nicht als Erwartungen, die Sie auf einmal erfüllen müssen.","finance":"Überprüfen Sie das Muster hinter Ihren Ausgaben, bevor Sie eine größere Verpflichtung eingehen. Achten Sie darauf, wann Starrheit, Pessimismus, das Messen des Wertes durch Leistung beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Bewege dich ausgewogen und gönne dir echte Erholung während der Woche. Baue für die langfristige Zukunft auf, während du daran denkst, dass Ruhe Teil der Struktur ist.","guidance":"Lass diese Frage die Woche leiten: Baue für die langfristige Zukunft, während du daran denkst, dass Ruhe ein Teil der Struktur ist."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'year', 'de', '{"overview":"Dieses Jahr lädt zu geduldigem Wachstum in Bezug auf Identität, Zweck und die Art und Weise, wie du deine Energie einsetzt, ein. Der Steinbock bewegt sich durch Erdenergie. Disziplin und langfristige Vision helfen dem Steinbock, zu steigen, während er weise über die Tiefen darunter bleibt.","love":"Liebe vertieft sich, wenn du Beständigkeit übst und zulässt, dass sich Verbindung in menschlichem Tempo entwickelt. Deine Gaben von Ausdauer, Strategie und Zuverlässigkeit können dir helfen, dich zu verbinden, ohne zu performen.","career":"Langfristige Arbeit wird stärker, wenn Ehrgeiz mit einer Struktur verbunden ist, die man aufrechterhalten kann. Verwenden Sie ehrgeizig, diszipliniert, geduldig, verantwortungsbewusst als Werkzeuge, nicht als Erwartungen, die Sie alle auf einmal erfüllen müssen.","finance":"Bauen Sie finanzielles Vertrauen durch wiederholbare Gewohnheiten auf, anstatt auf perfekte Vorhersagen zu setzen. Achten Sie darauf, wann Starrheit, Pessimismus und die Bewertung des eigenen Wertes durch Leistung beginnen, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Betrachten Sie das Wohlbefinden als Grundlage für das Leben, das Sie aufbauen, nicht als Belohnung, nachdem Sie es beendet haben. Bauen Sie für die langfristige Zukunft, während Sie daran denken, dass Ruhe Teil der Struktur ist.","guidance":"Kehren Sie im Laufe des Jahres immer wieder zu diesem Kompass zurück: Bauen Sie für die langfristige Zukunft, während Sie sich daran erinnern, dass Ruhe ein Teil der Struktur ist."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aquarius', 'de', '{"name":"Wassermann","dateRange":"20. Jan – 18. Feb","rulingPlanet":"Uranus","summary":"Unabhängiges Denken und kollektive Vision leiten den Wassermann dazu, neue Ideen in die Welt zu bringen.","originStory":"Wassermann ist mit Ganymed verbunden, dem Kelterträger, dessen Gefäß Wasser zu den Göttern brachte und symbolisch Wissen zur Menschheit. Obwohl sein Bild Wasser trägt, gehört das Zeichen zur Luft: Ideen, Systeme und Erneuerung, die zum Gemeinwohl geteilt werden.","traits":["Original","Unabhängig","Humanitär","Erfinderisch"],"strengths":["Innovation","Objektivität","Gemeinschaftsvision"],"challenges":["Losgelöstheit","Widerspenstige Gewohnheiten","Feste Meinungen"],"compatibleSigns":["Zwillinge","Waage","Schütze"],"reflectionPrompt":"Lass deinen Unterschied der Verbindung dienen, statt der Distanz."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'day', 'de', '{"overview":"Heute begünstigt einen klaren, absichtlichen Schritt. Der Wassermann bewegt sich durch Luftenergie. Unabhängiges Denken und kollektive Vision leiten den Wasserträger, um neue Ideen in die Welt zu bringen.","love":"In der Liebe heute wähle Präsenz statt Annahme. Deine Gaben von Innovation, Objektivität und Gemeinschaftsvision können dir helfen, eine Verbindung herzustellen, ohne zu performen.","career":"Bei der Arbeit erledige die sinnvollste Aufgabe, bevor du neuen Schwung verfolgst. Nutze originell, unabhängig, humanitär, erfinderisch als Werkzeuge, nicht als Erwartungen, die du alle auf einmal erfüllen musst.","finance":"Halte die heutigen Geldentscheidungen einfach und geerdet. Achte darauf, wann sich Losgelöstheit, widersprüchliche Gewohnheiten oder feste Meinungen auf eine praktische Entscheidung auszuwirken beginnen.","wellbeing":"Eine kurze Pause kann deine Energie wiederherstellen. Lass deine Andersartigkeit der Verbindung dienen, statt der Distanz.","guidance":"Bevor der Tag endet, denke daran: Lass deinen Unterschied der Verbindung dienen, statt Distanz zu schaffen."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'week', 'de', '{"overview":"Diese Woche entwickelt sich durch beständige Entscheidungen statt eines einzigen dramatischen Moments. Wassermann bewegt sich durch Luftenergie. Unabhängiges Denken und kollektive Vision leiten den Wasserträger, neue Ideen in die Welt zu gießen.","love":"Beziehungen profitieren von einem Gespräch, das Raum für sowohl Ehrlichkeit als auch Wärme bietet. Ihre Gaben der Innovation, Objektivität und Gemeinschaftsvision können Ihnen helfen, sich zu verbinden, ohne eine Rolle zu spielen.","career":"Ihr größter beruflicher Fortschritt entsteht, indem Sie eine Priorität wählen und dafür Zeit schützen. Verwenden Sie originell, unabhängig, humanitär, erfinderisch als Werkzeuge, nicht als Erwartungen, die Sie alle auf einmal erfüllen müssen.","finance":"Überprüfen Sie das Muster hinter Ihren Ausgaben, bevor Sie eine größere Verpflichtung eingehen. Achten Sie darauf, wann Abgeklärtheit, gegensätzliche Gewohnheiten, feste Meinungen beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Balance zwischen Bewegung und echter Erholung während der Woche. Lass deine Differenz der Verbindung statt der Distanz dienen.","guidance":"Lass diese Frage die Woche leiten: Lass deinen Unterschied der Verbindung dienen, statt der Distanz."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'year', 'de', '{"overview":"Dieses Jahr lädt zu geduldigem Wachstum rund um Identität, Zweck und die Art und Weise, wie du deine Energie einsetzt, ein. Wassermann bewegt sich durch Luftenergie. Unabhängiges Denken und kollektive Vision führen den Wasserträger dazu, neue Ideen in die Welt zu tragen.","love":"Liebe vertieft sich, wenn du Beständigkeit übst und zulässt, dass Verbindung sich in menschlichem Tempo entwickelt. Deine Gaben für Innovation, Objektivität, Gemeinschaftsvision können dir helfen, ohne Leistung dich zu verbinden.","career":"Langfristige Arbeit wird stärker, wenn Ehrgeiz mit einer Struktur kombiniert wird, die Sie aufrechterhalten können. Verwenden Sie originell, unabhängig, humanitär, erfinderisch als Werkzeuge, nicht als Erwartungen, die Sie auf einmal erfüllen müssen.","finance":"Baue finanzielles Vertrauen durch wiederholbare Gewohnheiten statt durch perfekte Vorhersagen auf. Achte darauf, wann Distanz, konträre Gewohnheiten und feste Meinungen beginnen, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Betrachte das Wohlbefinden als Grundlage für das Leben, das du aufbaust, nicht als Belohnung, nachdem du es beendet hast. Lass deinen Unterschied der Verbindung dienen, statt der Distanz.","guidance":"Kehre im Laufe des Jahres immer wieder zu diesem Kompass zurück: Lass deinen Unterschied Verbindung dienen, statt Distanz zu schaffen."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('pisces', 'de', '{"name":"Fische","dateRange":"19. Feb – 20. Mär","rulingPlanet":"Neptun","summary":"Mitgefühl und Vorstellungskraft leiten die Fische zwischen Intuition, Träumen und gemeinsamem Empfinden.","originStory":"Fische erinnern an Aphrodite und Eros, die zu Fischen wurden und sich zusammenbanden, um Typhon zu entkommen. Die Bindung zwischen den beiden Fischen steht für Hingabe, flexible Identität, spirituelle Sensibilität und die Einheit in bewegten Strömungen zu finden.","traits":["Mitfühlend","Phantasievoll","Intuitiv","Sanft"],"strengths":["Empathie","Kreativität","Spirituelle Einsicht"],"challenges":["Flucht aus der Realität","Verschwommene Grenzen","Die Emotionen anderer aufnehmen"],"compatibleSigns":["Krebs","Skorpion","Steinbock"],"reflectionPrompt":"Ehre deine Sensibilität mit Grenzen, die stark genug sind, um sie zu schützen."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'day', 'de', '{"overview":"Heute begünstigt einen klaren, bewussten Schritt. Fische bewegen sich durch Wasserenergie. Mitgefühl und Vorstellungskraft führen die Fische zwischen Intuition, Träumen und gemeinsamem Gefühl.","love":"In der Liebe wähle heute Gegenwart statt Annahme. Deine Gaben der Empathie, Kreativität, spirituellen Einsicht können dir helfen, dich zu verbinden, ohne zu performen.","career":"Bei der Arbeit erledige die bedeutendste Aufgabe, bevor du nach neuem Schwung strebst. Verwende mitfühlend, fantasievoll, intuitiv, sanft als Werkzeuge, nicht als Erwartungen, die du alle auf einmal erfüllen musst.","finance":"Halte die heutigen Geldentscheidungen einfach und bodenständig. Achte darauf, wann Eskapismus, verschwommene Grenzen und das Aufnehmen der Emotionen anderer beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Eine kurze Pause kann deine Energie wiederherstellen. Ehre deine Sensibilität mit Grenzen, die stark genug sind, sie zu schützen.","guidance":"Bevor der Tag endet, denke daran: Ehre deine Sensibilität mit Grenzen, die stark genug sind, um sie zu schützen."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'week', 'de', '{"overview":"Diese Woche entwickelt sich durch beständige Entscheidungen statt durch einen dramatischen Moment. Fische bewegen sich durch Wasserenergie. Mitgefühl und Fantasie leiten die Fische zwischen Intuition, Träumen und geteilten Gefühlen.","love":"Beziehungen profitieren von einem Gespräch, das Raum sowohl für Ehrlichkeit als auch für Wärme lässt. Deine Gaben von Empathie, Kreativität und spirituellem Einblick können dir helfen, dich zu verbinden, ohne eine Rolle zu spielen.","career":"Ihr bester beruflicher Fortschritt entsteht, indem Sie eine Priorität wählen und Zeit dafür schützen. Verwenden Sie mitfühlend, fantasievoll, intuitiv, sanft als Werkzeuge, nicht als Erwartungen, die Sie auf einmal erfüllen müssen.","finance":"Überprüfen Sie das Muster hinter Ihren Ausgaben, bevor Sie eine größere Verpflichtung eingehen. Achten Sie darauf, wann Eskapismus, verwischte Grenzen, das Aufnehmen der Emotionen anderer beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Balanciere Bewegung mit echter Erholung während der Woche. Respektiere deine Sensibilität mit Grenzen, die stark genug sind, um sie zu schützen.","guidance":"Lass diese Frage die Woche leiten: Ehre deine Sensibilität mit Grenzen, die stark genug sind, sie zu schützen."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'year', 'de', '{"overview":"Dieses Jahr lädt zu geduldigem Wachstum rund um Identität, Zweck und die Art und Weise, wie du deine Energie einsetzt, ein. Fische bewegen sich durch Wasserenergie. Mitgefühl und Fantasie leiten die Fische zwischen Intuition, Träumen und geteilten Gefühlen.","love":"Liebe vertieft sich, wenn du Beständigkeit übst und zulässt, dass sich Verbindung in menschlichem Tempo entwickelt. Deine Gaben von Empathie, Kreativität und spiritueller Einsicht können dir helfen, dich zu verbinden, ohne zu performen.","career":"Langfristige Arbeit wird stärker, wenn Ehrgeiz mit einer Struktur verbunden ist, die man aufrechterhalten kann. Verwenden Sie mitfühlend, einfallsreich, intuitiv, sanft als Werkzeuge, nicht als Erwartungen, die Sie auf einmal erfüllen müssen.","finance":"Stärken Sie Ihr finanzielles Selbstvertrauen durch wiederholbare Gewohnheiten statt durch perfekte Vorhersagen. Achten Sie darauf, wann Eskapismus, verschwommene Grenzen oder das Aufsaugen der Emotionen anderer beginnt, eine praktische Entscheidung zu beeinflussen.","wellbeing":"Betrachten Sie das Wohlbefinden als Grundlage für das Leben, das Sie aufbauen, nicht als Belohnung, nachdem Sie es beendet haben. Ehre deine Sensibilität mit Grenzen, die stark genug sind, sie zu schützen.","guidance":"Kehren Sie im Laufe des Jahres immer wieder zu diesem Kompass zurück: Ehren Sie Ihre Sensibilität mit Grenzen, die stark genug sind, sie zu schützen."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('fool', 'ja', '{"name":"愚者","meaning":"真っ白なページと信念のジャンプ — 心を開いて新たな旅が始まります。","advice":"目の前の道を信じ、すべての答えがなくても最初の一歩を踏み出してください。","yesNoMeaning":"新しい始まりはめったに固定された答えを持たない — 結果はあなたが踏み出す一歩にかかっています。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('magician', 'ja', '{"name":"魔術師","meaning":"あなたは必要なすべての道具を持っています。意志を集中させ、意図を行動に変えましょう。","advice":"スキルと資源を意図的に使う — 今こそ実行する時","yesNoMeaning":"あなたはすでに必要なすべてを持っています — このエネルギーは集中して前進することをサポートします。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('high-priestess', 'ja', '{"name":"女教皇","meaning":"静かな知恵は表面の下に隠れています。直感と思考に耳を傾けましょう。","advice":"立ち止まり、内面に向かい、行動する前に本能に導かれるようにしてください。","yesNoMeaning":"答えはまだ表面下に隠れている — 無理に明確な肯定や否定を求めず、直感を信じましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('empress', 'ja', '{"name":"女帝","meaning":"成長、豊かさ、そして育むエネルギーがあなたを取り囲んでいます。美しさとケアを花開かせましょう。","advice":"辛抱強く、寛大でありなさい — 愛を持って創造し、物事を自然に熟成させなさい。","yesNoMeaning":"成長、豊かさ、そして育むエネルギーがあなたの願いを支えてくれます — 答えは静かな肯定です。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('emperor', 'ja', '{"name":"皇帝","meaning":"構造、権威、そして安定したリーダーシップ。規律をもって確かな基盤の上に築く。","advice":"明確な計画で主導権を握りましょう；確固たる境界が持続的な安定をもたらします。","yesNoMeaning":"構造、権威、そして着実な規律が自信ある「はい」を支える。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hierophant', 'ja', '{"name":"法王","meaning":"伝統と信頼できる指南は確かな道を提供します。過去からの教訓を学びましょう。","advice":"確立された知恵に従い、信頼できる人々に助言を求める。","yesNoMeaning":"伝統と信頼できる指針は信頼できる「はい」を示しています ― 既に実証されているものに頼りましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('lovers', 'ja', '{"name":"恋人たち","meaning":"意味のある絆や重要な選択。心が本当に価値を置くものに従ってください。","advice":"誠実さと整合性を持って選ぶ — 誠実であるとき、つながりは深まる。","yesNoMeaning":"あなたの心と価値観はここで一致しています — 特に正直に選ぶとき、答えはイエスです。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('chariot', 'ja', '{"name":"戦車","meaning":"意志力と勢いがあなたを前進させます。集中を維持すれば、成功するでしょう。","advice":"目標に目を向け、すべての障害を自信を持って乗り越えながら進みなさい。","yesNoMeaning":"意志力と勢いはあなたの味方です — 集中した「はい」、ただし継続を約束する場合に限ります。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('strength', 'ja', '{"name":"強さ","meaning":"真の力は穏やかです—忍耐、勇気、そして思いやりがあらゆる挑戦を和らげます。","advice":"穏やかな力で導きなさい；柔らかい手はしばしば最も強い手です。","yesNoMeaning":"穏やかな勇気と忍耐強い決意がこれを「はい」にする — 力ではなく冷静さで導く。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hermit', 'ja', '{"name":"隠者","meaning":"一歩引いて内なる明晰さを求める時です。今、孤独はより深い答えをもたらします。","advice":"内面に向かい、振り返り、静けさの中で本当に必要なものを見つけてください。","yesNoMeaning":"まだです — カードは行動する前に一歩引いて内なる明確さを見つけるよう求めています。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('wheel-of-fortune', 'ja', '{"name":"運命の輪","meaning":"運は巡り、サイクルは変わる。今変わるものは、より大きなリズムの一部です。","advice":"柔軟に潮流に乗る — 良いことでも悪いことでも変化を受け入れましょう。","yesNoMeaning":"運は変わりつつある — 結果は固定されたはい・いいえではなく、変化にどう対応するかによる。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('justice', 'ja', '{"name":"正義","meaning":"真実と公正が勝利をもたらします。原因と結果が今、均衡に戻ります。","advice":"正直に行動し、両方の側面を考慮しなさい；天秤は公平に落ち着くでしょう。","yesNoMeaning":"天秤はまだ測定中です — 公正な答えは事実とあなたの正直さに依存します。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hanged-man', 'ja', '{"name":"吊るされた男","meaning":"必要な一時停止。コントロールを手放し、新しい角度から状況を見てみましょう。","advice":"無理をせず、瞬間に身を委ね、新しい視点を受け入れなさい。","yesNoMeaning":"まず一時停止が必要である — 今これを無理に行うことは、より明確な答えを妨げるだけである。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('death', 'ja', '{"name":"死","meaning":"終わりは再生の道を開く。その役目を果たしたものを手放そう。","advice":"後悔せずに手放すこと；深い変容が新しい扉を開こうとしています。","yesNoMeaning":"終わりは道を清める — 現在の道は閉じつつあり、新しい道が始まる。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('temperance', 'ja', '{"name":"節制","meaning":"バランスと忍耐は調和をもたらします。対立するものを優雅に融合させましょう。","advice":"ほどほどに行動し、冷静さを保つ — 着実な一歩が目的地に到達する。","yesNoMeaning":"バランスと忍耐は調和をもたらします — 一歩ずつ着実に進める慎重な「はい」。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('devil', 'ja', '{"name":"悪魔","meaning":"執着、誘惑、あるいは束縛のパターンに注意しなさい。鎖に気づきなさい。","advice":"自分を束縛しているものを名付け、自由を取り戻す — チェーンは許可しなければ縛ることはない。","yesNoMeaning":"執着や縛るパターンが邪魔をしています — まだではありません、その鎖が名付けられ、断ち切られるまでは。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('tower', 'ja', '{"name":"塔","meaning":"突然の変化は偽りを打ち砕き、真実を明らかにする。倒れるものは決して立つべきものではなかった。","advice":"混乱を歓迎してください；瓦礫の中からより明確な基盤を築くことができます。","yesNoMeaning":"突然の変化が古いものを壊している — 安定した「はい」が可能になる前に、基盤は落ち着かなければならない。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('star', 'ja', '{"name":"星","meaning":"希望、癒し、そして静かなインスピレーションが嵐の後にあなたの精神を新たにします。","advice":"前方の光を信じ、信じ続けてください—あなたの願いは手の届くところにあります。","yesNoMeaning":"希望と静かな再生は「はい」を示しています — 先にある光を信じて、あなたの願いを生かし続けましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('moon', 'ja', '{"name":"月","meaning":"幻想と不確実性が道を曖昧にする。外見ではなく直感を信じなさい。","advice":"速度を落として深く見つめてください；霧が晴れると明確さがやってきます。","yesNoMeaning":"幻想と不確実性が道を曖昧にする — 外見の下を見ない限り答えは明確ではない。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('sun', 'ja', '{"name":"太陽","meaning":"喜び、成功、そして輝く明晰さ。すべてが明るく、生命にあふれています。","advice":"祝って輝きましょう — ポジティブなエネルギーは望む結果を引き寄せます。","yesNoMeaning":"喜びと輝く明晰さが明るいイエスを確認します — すべてがあなたの味方に働いています。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('judgement', 'ja', '{"name":"審判","meaning":"立ち上がり新たにし、自分に正直である呼びかけ。覚醒の判断。","advice":"勇気を持って呼びかけに応じ、過去を許し、次の章に踏み出せ。","yesNoMeaning":"立ち上がり新たにする呼びかけ — 過去を許し正直に答えたなら、特にそうです。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('world', 'ja', '{"name":"世界","meaning":"完成と充足 — サイクルは完全な全体性で閉じる。","advice":"達成したことを祝いましょう；扉はより広い世界に開かれています。","yesNoMeaning":"完成と全体性は、これを成就した「はい」として示す — サイクルはあなたに有利に閉じる。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-wands', 'ja', '{"name":"ワンドのエース","meaning":"ひらめきの火花は大胆な創造的な道を開きます。","advice":"エネルギーが新鮮なうちに始め、アイデアに本当の第一歩を踏ませる。","yesNoMeaning":"ワンドのエースは肯定傾向: エネルギーが新鮮なうちに始め、アイデアに実際の第一歩を与える。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-wands', 'ja', '{"name":"ワンドの2","meaning":"計画と方向の選択を通じて未来が形作られつつあります。","advice":"慣れ親しんだものの先を見つめ、成長の余地がある道に身を委ねなさい。","yesNoMeaning":"ワンドの2は条件付きです：慣れ親しんだものを超えて見つめ、その後成長の余地のある道にコミットしましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-wands', 'ja', '{"name":"ワンドの3","meaning":"初期の努力は、機会やより広い視野が見えてくるにつれて拡大します。","advice":"作り続け、あなたの仕事が引き寄せる反応に備えなさい。","yesNoMeaning":"ワンドの3は「はい」に傾く：建設を続け、あなたの仕事が引き寄せる反応に応じる準備をしましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-wands', 'ja', '{"name":"ワンドの4","meaning":"安定、歓迎、そして共有の祝祭が強固な基盤を作ります。","advice":"節目を記して、支えてくれる人々と共有しましょう。","yesNoMeaning":"ワンドの4はイエス傾向：節目を祝し、支えてくれる人たちと分かち合いましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-wands', 'ja', '{"name":"ワンドの5","meaning":"競合する目標は摩擦、ノイズ、または自信の試練を生む。","advice":"競争心を有益な練習に変え、意味のない対立を拒否してください。","yesNoMeaning":"ワンドの5は条件付きのまま：ライバル関係を有益な練習に変え、目的のない対立を拒む。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-wands', 'ja', '{"name":"ワンドの6","meaning":"認識は、決意ある努力と目に見える進展に続きます。","advice":"励ましを受け入れなさい、しかし自信は正直な仕事に結びつけたままにしなさい。","yesNoMeaning":"ワンドの6はイエスの傾き: 励ましを受け入れつつ、自信は正直な仕事に結びつけ続けましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-wands', 'ja', '{"name":"ワンドの7","meaning":"あなたは貴重な立場を保持しており、プレッシャーがあなたの決意を試します。","advice":"すべての挑戦と戦うのではなく、明確な境界を持って大切なものを守りなさい。","yesNoMeaning":"ワンドの7はイエスの傾き: すべての挑戦と戦うのではなく、明確な境界線で大切なものを守りましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-wands', 'ja', '{"name":"ワンドの8","meaning":"出来事が加速し、メッセージが届き、勢いが遅れを解消する。","advice":"迅速に行動し、道が開かれている間は直接的なコミュニケーションを保ちなさい。","yesNoMeaning":"ワンドの8は「はい」に傾く：道が開いている間に素早く行動し、直接的にコミュニケーションを取りましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-wands', 'ja', '{"name":"ワンドの9","meaning":"レジリエンスは強いが、過去の負荷があなたを用心深くさせる。","advice":"すべての傷が繰り返されることを期待せずに、自分のエネルギーを守りながら次のステップを踏む。","yesNoMeaning":"ワンドの9は条件付きのままです：自分のエネルギーを守り、すべての傷が繰り返されることを期待せずに次のステップを踏んでください。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-wands', 'ja', '{"name":"ワンドの10","meaning":"責任は重くなり、成功は今や負担を伴うようになりました。","advice":"仕事を委任し、簡素化し、もはや本当に自分のものでない仕事を手放しなさい。","yesNoMeaning":"ワンドの10は「いいえ」に傾く：委任し、簡素化し、もはや自分のものではない仕事を手放しましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-wands', 'ja', '{"name":"ワンドのペイジ","meaning":"好奇心は生き生きとしたメッセージ、実験、または新しい創造的興味をもたらします。","advice":"勇気を持って探求し、初心者のエネルギーから行動を通じて学ぶ。","yesNoMeaning":"ワンドのペイジはやや肯定です：勇気を持って探求し、初心者のエネルギーから行動を通じて学びましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-wands', 'ja', '{"name":"ワンドのナイト","meaning":"情熱は迅速に突き進み、冒険や場合によっては焦りをもたらす。","advice":"勢いを利用するが、速度に努力が散らされる前に方向を選ぶ","yesNoMeaning":"ワンドのナイトは条件付きです：勢いを活かすが、速度が努力を散らさないうちに方向を選ぶこと。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-wands', 'ja', '{"name":"ワンドの女王","meaning":"暖かい自信と創造的独立心が、他者をあなたのビジョンに引きつけます。","advice":"自分の存在を信じ、他者を励まし、野心を縮めないでください。","yesNoMeaning":"ワンドの女王は肯定的です：自分の存在を信じ、他者を励まし、野心を縮小させないでください。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-wands', 'ja', '{"name":"ワンドのキング","meaning":"成熟したビジョンは、インスピレーションを決断力のある倫理的なリーダーシップに変えます。","advice":"より大きな目的に従って導き、他の人が貢献できる余地を与える。","yesNoMeaning":"ワンドの王はイエス傾向：大きな目的から導き、他者が貢献できる余地を与えましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-cups', 'ja', '{"name":"カップのエース","meaning":"心は新しい愛情、思いやり、感情の再生に開かれています。","advice":"感情を正直に受け取り、結果を強制せずに思いやりを流しましょう。","yesNoMeaning":"カップのエースは肯定傾向: 感情を正直に受け取り、結果を強制せずに配慮を流す。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-cups', 'ja', '{"name":"カップの2","meaning":"相互認識はパートナーシップ、魅力、または誠実な合意を生む。","advice":"他者と対等に会い、心から話す。","yesNoMeaning":"カップの2は肯定的です：相手を対等に受け止め、心から語りましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-cups', 'ja', '{"name":"カップの3","meaning":"友情、コミュニティ、共有された喜びが感情的支えをもたらす。","advice":"一緒に祝って、誰が本当にあなたのために現れるかを覚えておきましょう。","yesNoMeaning":"カップの3は「はい」に傾く：一緒に祝福し、誰が本当にあなたのために現れるかを覚えておきましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-cups', 'ja', '{"name":"カップの4","meaning":"感情的な撤退は、利用可能な贈り物に気づくことを難しくします。","advice":"比較を一時停止して、静かに提供されているものをもう一度見てください。","yesNoMeaning":"カップの4は「いいえ」の傾き：比較を一時停止し、静かに提供されているものを再確認する。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-cups', 'ja', '{"name":"カップの5","meaning":"喪失は、何か意味のあるものが残る一方で、こぼれたものに注意を向けさせる。","advice":"失望を尊重し、それからまだ存在する支援の方へ向かう。","yesNoMeaning":"カップの5は「いいえ」に傾く：失望を認めた後、まだ存在する支えの方に向かいましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-cups', 'ja', '{"name":"カップの6","meaning":"記憶、無垢、または親しみのある絆が穏やかな温かさとともに戻ってくる。","advice":"過去の親切を歓迎し、再びそこに住まなければならないふりをしないでください。","yesNoMeaning":"カップの6はイエスの傾き: 過去の優しさを歓迎しつつ、そこに再び住まなければならないふりはしないでください。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-cups', 'ja', '{"name":"カップの7","meaning":"多くの魅力的な可能性は、ビジョンと幻想の違いを曖昧にします。","advice":"選択肢を絞り、夢を現実と照らし合わせてテストしてから決める。","yesNoMeaning":"カップの7はまだ不明確です：選択肢を絞り、一つの夢を現実と照らし合わせてからコミットしましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-cups', 'ja', '{"name":"カップの8","meaning":"かつて意味のあった状況はもはや心を養わない。","advice":"正直に去り、今必要なより深い充実に向かって進みなさい。","yesNoMeaning":"カップの8は「いいえ」に傾く：正直に去り、今必要なより深い充足へ向かいましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-cups', 'ja', '{"name":"カップの9","meaning":"満足と感謝は、心からの願いを近くに感じさせる。","advice":"ここにあるものを楽しみ、願いが自分のより深い価値観にもかなうかを問いかけてください。","yesNoMeaning":"カップの9は肯定的です：ここにあるものを楽しみ、願いが自分のより深い価値観にも役立つかどうかを問うこと。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-cups', 'ja', '{"name":"カップの10","meaning":"家を取り巻く感情的な調和、帰属意識、そして持続するつながり。","advice":"喜びを持続可能かつ共有できる絆を育てましょう。","yesNoMeaning":"カップの10はイエスの傾き: 喜びを持続的かつ共有できるものにする絆を育んでください。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-cups', 'ja', '{"name":"カップのペイジ","meaning":"優しいメッセージや直感的な発見は感情の開放を促します。","advice":"感覚に好奇心を持ち、仮定ではなく誠実に反応してください。","yesNoMeaning":"カップのペイジは条件付きのままです：感情に対して好奇心を持ち、推測ではなく誠意をもって対応してください。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-cups', 'ja', '{"name":"カップのナイト","meaning":"ロマンス、想像力、または理想が心を前に進ませます。","advice":"招待に従うが、約束が展開する間は足を地に着けておく。","yesNoMeaning":"カップの騎士はイエス傾向：招待に従いながら、約束が進展する中で地に足をつけ続けましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-cups', 'ja', '{"name":"カップのクイーン","meaning":"深い共感と直感が真実のための落ち着いた空間を作ります。","advice":"思いやりを持って聞きながら、ケアを健全に保つ境界を守る。","yesNoMeaning":"カップのクイーンはやや肯定です：思いやりを持って耳を傾けつつ、ケアを健全に保つ境界線を守ってください。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-cups', 'ja', '{"name":"カップのキング","meaning":"感情の成熟は、感情を抑圧せずに強い感情を安定させます。","advice":"他人が反応的なときには、特に思いやりと自己抑制をもって応答してください。","yesNoMeaning":"カップの王はイエス傾向：特に他者が反応的な時に、思いやりと自己制御をもって対応しましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-swords', 'ja', '{"name":"ソードのエース","meaning":"明確な洞察が混乱を切り裂き、新しい真実を明らかにします。","advice":"問題をはっきりと名指しし、公正な決定のために明確さを活用する。","yesNoMeaning":"ソードのエースは肯定傾向: 問題を率直に指摘し、公正な判断のために明確さを活用する。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-swords', 'ja', '{"name":"ソードの2","meaning":"慎重な膠着状態は、永遠に保つことのできない選択を遅らせます。","advice":"目隠しを優しく外し、欠けている事実を集め、バランスから判断する。","yesNoMeaning":"ソードの2はまだはっきりしていません：目隠しを優しく外し、欠けている事実を集め、バランスから決めましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-swords', 'ja', '{"name":"ソードの3","meaning":"痛みを伴う真実、別れ、または失望は、認められることを求めています。","advice":"感情を通して動かし、傷を永続的な物語にしないようにしましょう。","yesNoMeaning":"ソードの3は「いいえ」に傾く：感情を通過させ、傷を永続的な物語に変えないようにしましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-swords', 'ja', '{"name":"ソードの4","meaning":"プレッシャーや対立の後には、休息と心の静けさが必要です。","advice":"答える前に一時停止すること；回復は、明確な思考を取り戻すときに生産的である。","yesNoMeaning":"ソードの4は「いいえ」の傾き：答える前に一息つく；回復は明確な思考を取り戻すときに有益である。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-swords', 'ja', '{"name":"剣の5","meaning":"対立は空虚な勝利を生むか、信頼を損なうことがある。","advice":"勝つことより尊厳を選び、代償の大きすぎる戦術から離れる。","yesNoMeaning":"ソードの5は「いいえ」の傾き：勝つことより尊厳を選び、あまりにも代償の大きい戦術からは身を引く。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-swords', 'ja', '{"name":"ソードの6","meaning":"困難な通過が徐々に穏やかな状態に向かいます。","advice":"学んだことを活かし、支援を受け入れ、混乱から離れ続けなさい。","yesNoMeaning":"ソードの6はイエスの傾き: 学んだことを持ち、支援を受け入れ、混乱から遠ざかり続けましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-swords', 'ja', '{"name":"ソードの7","meaning":"戦略、秘密主義、または回避は道を複雑にする。","advice":"賢く行動しなさい、しかし透明性を持って行動して。信頼を裏切る近道は問題として戻ってくるでしょう。","yesNoMeaning":"ソードの7は否定的です：賢く行動しつつ透明性を保ち、信頼を裏切るような近道は問題として返ってきます。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-swords', 'ja', '{"name":"ソードの8","meaning":"恐れや制限的な信念により、利用可能な選択肢が見えにくくなる。","advice":"自分が閉じ込められているという考えに疑問を持ち、一つ小さな解放の行動を取ってみましょう。","yesNoMeaning":"ソードの8は「いいえ」に傾く：自分が閉じ込められているという思いを疑い、一歩の小さな解放行動を取りましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-swords', 'ja', '{"name":"ソードの9","meaning":"不安は暗闇で危険を拡大し、心を消耗させる。","advice":"恐怖を日の光のもとに出し、サポートを求め、事実と想像の結果を区別する。","yesNoMeaning":"ソードの9は否定的です：恐怖を日の光にさらし、支援を求め、事実と想像上の結果を区別すること。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-swords', 'ja', '{"name":"ソードの10","meaning":"苦しい循環は最終限界に達し、変わらずに続くことはできない。","advice":"終わりを受け入れ、回復を守り、異なる始まりが現れることを許しなさい。","yesNoMeaning":"ソードの10は「いいえ」に傾く：終わりを受け入れ、回復を守り、別の始まりが現れるのを許しましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-swords', 'ja', '{"name":"ソードのペイジ","meaning":"好奇心は事実を求め、質問をし、変化に注目する。","advice":"注意深く研究し、あらゆる信号に反応するのではなく、正確に話すこと。","yesNoMeaning":"ソードのペイジは条件付きのままです：慎重に調査し、すべての信号に反応するのではなく正確に話してください。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-swords', 'ja', '{"name":"ソードのナイト","meaning":"集中した知性は素早く動き、障害に直接立ち向かう。","advice":"勇気を持って進みなさい、しかし自信が見逃すかもしれないことに耳を傾けるために十分にゆっくり進みなさい。","yesNoMeaning":"ソードのナイトは条件付きです：勇気をもって前進するが、自分の確信が見逃すかもしれないことも聞くためにゆっくり進むこと。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-swords', 'ja', '{"name":"ソードのクイーン","meaning":"明瞭な知覚と正直な境界は混乱を取り除く。","advice":"思いやりをもって真実を語り、経験により自分を研ぎ澄ませ、硬直させないようにしましょう。","yesNoMeaning":"ソードの女王は肯定的です：真実を思いやりを持って語り、経験によって硬くなるのではなく研ぎ澄まされるようにしましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-swords', 'ja', '{"name":"ソードのキング","meaning":"理由、公正、そして規律ある判断が重要な決定を導きます。","advice":"証拠を使い、基準を定義し、個人的な偏見を判決に入れない","yesNoMeaning":"剣の王はイエス傾向：証拠を用い、基準を定め、個人的な偏見を判断に持ち込まないようにしましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-pentacles', 'ja', '{"name":"ペンタクルのエース","meaning":"具体的な機会は、繁栄、仕事、または幸福の種を提供します。","advice":"機会を現実的な計画に基づかせ、継続的に大切に育ててください。","yesNoMeaning":"ペンタクルのエースは肯定傾向: 機会を実践的な計画に基づかせ、継続的に大切にする。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-pentacles', 'ja', '{"name":"ペンタクルの2","meaning":"いくつかの優先事項が同時に動き、柔軟なバランスを必要とします。","advice":"リズムを調整し、重要なものを守り、運べる以上の約束は避けなさい。","yesNoMeaning":"ペンタクルの2は条件付きです：リズムを調整し、重要なものを守り、運べる以上の約束を避けましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-pentacles', 'ja', '{"name":"ペンタクルの3","meaning":"スキルは協力、フィードバック、そして慎重な技術によって成長します。","advice":"自分の力を貢献し、専門知識を尊重し、共有された基準に向けて構築する。","yesNoMeaning":"ペンタクルの3は「はい」に傾く：自分の力を提供し、専門知識を尊重し、共通の基準に沿って築きましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-pentacles', 'ja', '{"name":"ペンタクルの4","meaning":"安全にしがみつくことは資源を守ることができるが、健全な流れを制限することがある。","advice":"恐れにすべての判断を委ねず、大切なものを守る。","yesNoMeaning":"ペンタクルの4は条件付きのまま：恐れにすべての判断を委ねることなく、大切なものを守る。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-pentacles', 'ja', '{"name":"ペンタクルの5","meaning":"物質的な負担や排除は、不安や不足感を生みます。","advice":"実際的な助けを求め、困難によって見落としやすくなった扉に気づきなさい。","yesNoMeaning":"ペンタクルの5は「いいえ」の傾き：実際的な助けを求め、困難が気づきにくくした扉に注意を払う。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-pentacles', 'ja', '{"name":"ペンタクルの6","meaning":"資源が交換され、寛大さ、権力、公平性の問題が生じる。","advice":"明確な条件で与えたり受け取ったりすることで、支援が両者の尊厳を保つ。","yesNoMeaning":"ペンタクルの6はイエスの傾き: サポートが双方の尊厳を守るように、明確な条件で与えたり受け取ったりしましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-pentacles', 'ja', '{"name":"ペンタクルの7","meaning":"忍耐強い投資は、次の努力の前に評価の段階に達する。","advice":"育っているものを見直し、方法を改善し、価値のある結果に時間を与えましょう。","yesNoMeaning":"ペンタクルの7は条件付きです：成長しているものを見直し、方法を改善し、価値のある結果には時間を与えましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-pentacles', 'ja', '{"name":"ペンタクルの8","meaning":"集中した反復は熟練と信頼できる結果を生む。","advice":"基本的なスキルを実践し、訂正を歓迎し、質を蓄積する。","yesNoMeaning":"ペンタクルの8は「はい」に傾く：基本的なスキルを練習し、訂正を受け入れ、質を積み重ねましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-pentacles', 'ja', '{"name":"ペンタクルの9","meaning":"自立と培われた快適さは、規律ある進歩を反映します。","advice":"築き上げたものを楽しみ、感謝と結びつけた独立心を維持してください。","yesNoMeaning":"ペンタクルの9は肯定的です：自分が築いたものを楽しみ、独立を感謝と結びつけて保つこと。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-pentacles', 'ja', '{"name":"ペンタクルの10","meaning":"長期的なセキュリティは、遺産、家族、共有基盤を通じて成長します。","advice":"目先の勝利を超えて計画し、他者を長期的に支えるものを守りましょう。","yesNoMeaning":"ペンタクルの10は「はい」に傾く：目先の勝利を超えて計画し、時間をかけて他者を支えられるものを守りましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-pentacles', 'ja', '{"name":"ペンタクルのペイジ","meaning":"実用的なメッセージは、学習、計画、または地に足の着いた新しい取り組みを促します。","advice":"基本を学び、次のタスクを定義し、着実な作業を通じてアイデアを証明する。","yesNoMeaning":"ペンタクルのペイジはやや肯定です：基本を学び、次の課題を定義し、着実な努力でアイデアを証明してください。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-pentacles', 'ja', '{"name":"ペンタクルのナイト","meaning":"信頼できる努力はゆっくり進むが、めったにその課題を放棄しない。","advice":"日課を正直かつ一貫して保ちなさい；興奮よりも進歩が重要です。","yesNoMeaning":"ペンタクルのナイトは肯定的です：ルーチンを正直で一貫したものに保つこと。進歩は刺激よりも重要です。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-pentacles', 'ja', '{"name":"ペンタクルのクイーン","meaning":"機知に富んだケアは快適さ、健康、実用的な豊かさを生み出す。","advice":"自分にとって持続可能な方法で人々と計画を育てましょう。","yesNoMeaning":"ペンタクルの女王は肯定的です：自分にとって持続可能な方法で人や計画を育てましょう。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-pentacles', 'ja', '{"name":"ペンタクルのキング","meaning":"物質的なリーダーシップは、経験を安定した寛大な管理に変えます。","advice":"長期的な選択を行い、成功を責任を持って活用してください。","yesNoMeaning":"ペンタクルの王はイエス傾向：健全な長期的選択を行い、成功を責任をもって活用しましょう。"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aries', 'ja', '{"name":"牡羊座","dateRange":"3月21日 – 4月19日","rulingPlanet":"火星","summary":"大胆な始まりと直接的な行動が牡羊座を特徴づけ、そのひらめきは意図を勢いに変える。","originStory":"牡羊座はギリシャ神話でフリクソスを救った黄金の牡羊に関連しています。その羊毛は後にイアソンとアルゴナウタイによって手に入れられ、勇気、救助、最初の勇敢な一歩の象徴としてこの星座を位置づけました。","traits":["勇敢","エネルギッシュ","独立","率直"],"strengths":["イニシアチブ","自信","レジリエンス"],"challenges":["せっかち","衝動的","維持できる以上に早く始める"],"compatibleSigns":["レオ","射手座","ふたご座"],"reflectionPrompt":"勇敢な始まりを一つ選び、それが成長するのに十分な忍耐を与える。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'day', 'ja', '{"overview":"今日は一つの明確で意図的な一歩を後押しします。牡羊座は火のエネルギーを通過します。大胆な始まりと直接的な行動が牡羊座を特徴づけ、その火花が意図を勢いに変えます。","love":"今日の恋愛では、推測よりも存在感を選びましょう。あなたの率先力、自信、回復力という才能が、演じることなくつながる助けになります。","career":"仕事では、新しい勢いを追い求める前に、最も意味のある仕事を完了させなさい。勇敢さ、活力、自立、率直さを、すぐにすべて満たすべき期待ではなく、道具として使いなさい。","finance":"今日のお金の選択はシンプルで現実的に保ちましょう。忍耐力の欠如や衝動性、持続できる以上に早く始めてしまうことが実際の判断に影響を与え始めるときに気づきましょう。","wellbeing":"小さな休止はあなたのエネルギーをリセットすることができます。勇気ある一つの始まりを選び、それが成長するまで十分な忍耐を与えましょう。","guidance":"一日が終わる前に覚えておいてください：勇敢な一つの始まりを選び、それが育つのに十分な忍耐を与えましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'week', 'ja', '{"overview":"今週は、劇的な瞬間よりも着実な選択によって進展します。牡羊座は火のエネルギーを通じて進みます。大胆な始まりと直接的な行動が牡羊座を特徴づけ、その火花が意図を勢いに変えます。","love":"関係は、正直さと温かさの両方に余地を持たせた会話から利益を得ます。あなたの自発性、自信、回復力という才能は、演じることなく人とつながるのに役立ちます。","career":"あなたの最高の職業上の進歩は、優先順位を選び、それに時間を確保することから生まれます。勇気、エネルギー、独立性、率直さを道具として使い、すべてを一度に満たさなければならない期待として使わないでください。","finance":"大きなコミットメントをする前に、自分の支出のパターンを見直してください。焦りや衝動、維持できるよりも早く始めることが実用的な判断に影響を与え始める時に気づいてください。","wellbeing":"一週間を通して、運動と本物の回復のバランスを取りましょう。一つの勇敢な始まりを選び、それが成長するための十分な忍耐を与えましょう。","guidance":"今週の指針としてこの問いを心に留めてください：一つの勇敢な始まりを選び、それが成長するのに十分な忍耐を与えましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'year', 'ja', '{"overview":"今年は、自己のアイデンティティ、目的、そしてエネルギーの使い方に関して、忍耐強い成長を促します。牡羊座は火のエネルギーを通して進みます。大胆な始まりと直接的な行動が牡羊座を特徴づけ、その火花は意図を勢いに変えます。","love":"愛は、一貫性を実践し、人間のペースでつながりが進化することを許すと深まります。あなたの自主性、自信、回復力は、見せかけることなくつながるのに役立ちます。","career":"長期的な仕事は、野心が維持可能な構造と組み合わさることでより強くなります。勇敢さ、エネルギー、独立性、直接性をツールとして使い、一度にすべて満たさなければならない期待としてではなく活用してください。","finance":"完璧な予測ではなく、繰り返しできる習慣を通じて金融に対する自信を築きましょう。忍耐力のなさ、衝動性、持続できる以上に早く始めることが現実的な判断に影響し始めるときに気づきましょう。","wellbeing":"幸福を、人生を完成させたあとに得られる報酬としてではなく、今築いている人生の基盤として扱いなさい。一つの勇敢な始まりを選び、それが成長するのに十分な忍耐を与えなさい。","guidance":"一年を通してこのコンパスに立ち返りなさい：勇敢な始まりを一つ選び、それが成長するのに十分な忍耐を与えなさい。"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('taurus', 'ja', '{"name":"おうし座","dateRange":"4月20日 – 5月20日","rulingPlanet":"金星","summary":"着実で官能的、地に足のついた牡牛座は、忍耐と配慮によって長続きする価値を築く。","originStory":"おうし座は、ゼウスが壮大な白い雄牛の姿を取り、エウロパを海を越えて運んだことを思い起こさせる。このイメージは、美、繁栄、地上の豊かさ、そして穏やかな持続を通した力と関連付けられるようになった。","traits":["地に足のついた","忠実","辛抱強い","官能的"],"strengths":["信頼性","実践的な知恵","献身"],"challenges":["頑固さ","変化への抵抗","あまりに長く握り続けること"],"compatibleSigns":["乙女座","やぎ座","がん"],"reflectionPrompt":"安らぎを永続と誤解せず、大切なものを守る。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'day', 'ja', '{"overview":"今日は明確で意図的な一歩を踏み出すことに適しています。牡牛座は地のエネルギーを通過します。安定していて感覚的で現実的な牡牛は、忍耐と注意を通じて長続きする価値を築きます。","love":"今日の恋愛では、推測よりも存在感を選びましょう。あなたの信頼性、実用的な知恵、献身の才能は、演じることなくつながる助けになります。","career":"仕事では、新しい勢いを追い求める前に、最も意味のある仕事を完了させなさい。地に足のついた、忠実な、忍耐強い、感覚的なものを、一度にすべて満たさなければならない期待ではなく、道具として使いなさい。","finance":"今日の金銭の選択は、シンプルで現実的に保ちましょう。頑固さや変化への抵抗、長く手放さないことが実際的な決定に影響を与え始めたときに気づきましょう。","wellbeing":"小さな休止がエネルギーをリセットすることがあります。快適さを永続と誤解せず、大切なものを守りましょう。","guidance":"一日が終わる前に、覚えておいてください：快適さを永続と勘違いせず、大切なものを守りましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'week', 'ja', '{"overview":"今週は、一度の劇的な瞬間よりも、着実な選択を通じて展開します。牡牛座は地のエネルギーを通って進みます。安定して感覚的で地に足がついた牡牛座は、忍耐と配慮を通じて持続的な価値を築きます。","love":"人間関係は、正直さと温かさの両方に余裕を持たせる会話から恩恵を受けます。あなたの信頼性、実用的な知恵、献身という才能は、演じることなくつながる助けになります。","career":"あなたの最高の専門的な進歩は、優先事項を選び、それに時間を確保することで得られます。「地に足のついた」「忠実な」「忍耐強い」「感覚的な」を道具として使い、すべてを一度に満たすべき期待としては使わないでください。","finance":"大きな支出をする前に、自分の支出パターンを確認してください。頑固さや変化への抵抗、長く執着しすぎることが実際的な判断に影響を与え始める時に気づいてください。","wellbeing":"週を通して、真の回復とバランスを取りながら動くこと。快適さを永続性と勘違いせず、大切なものを守ること。","guidance":"この質問を週の指針としましょう：快適さを永続と勘違いせずに、大切なものを守りましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'year', 'ja', '{"overview":"今年は、アイデンティティ、目的、そしてエネルギーの使い方に関して、忍耐強い成長を促します。おうし座は地のエネルギーを通ります。安定して官能的で地に足のついた牡牛座は、忍耐と気配りを通じて持続的な価値を築きます。","love":"愛は、一貫性を実践し、人間のペースでつながりが進化することを許すと深まります。あなたの信頼性、実践的な知恵、献身といった才能は、演じることなくつながる手助けになります。","career":"長期的な仕事は、野心が維持可能な構造と組み合わさることでより強くなります。地に足のついた、忠実な、忍耐強い、官能的なものを、同時にすべて満たさなければならない期待ではなく、道具として使いなさい。","finance":"完璧な予測ではなく、繰り返し行える習慣を通じて経済的自信を築きましょう。頑固さ、変化への抵抗、長く引きずりすぎることが実践的な判断に影響を与え始める時に気づきましょう。","wellbeing":"幸福を、人生を完成させた後のご褒美ではなく、築いている人生の基盤として扱いなさい。快適さを永続性と勘違いせず、大切なものを守りなさい。","guidance":"一年を通してこのコンパスに立ち戻ろう：安らぎを永続と勘違いせず、大切なものを守ろう。"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('gemini', 'ja', '{"name":"ふたご座","dateRange":"5月21日 – 6月20日","rulingPlanet":"水星","summary":"好奇心とつながりが双子座を導き、アイデアを集め、一つの物語の複数の側面を明らかにします。","originStory":"ふたご座はカストルとポルックスを象徴しています。二人は離れることなく、不死を共有した切り離せない双子です。この星座は、友情、二重の視点、コミュニケーション、そして世界間の移動というテーマを持っています。","traits":["好奇心旺盛","適応力がある","表現力豊か","頭の回転が速い"],"strengths":["コミュニケーション","多才","素早く学ぶ"],"challenges":["落ち着きのなさ","散漫な注意","考えすぎ"],"compatibleSigns":["てんびん座","みずがめ座","牡羊座"],"reflectionPrompt":"好奇心に扉を開かせ、そして見つけたものを理解するのに十分な時間をそこに留まりましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'day', 'ja', '{"overview":"今日は、一つの明確で意図的な一歩が吉と出る日です。双子座は風のエネルギーを通して動きます。好奇心とつながりが双子座を導き、アイデアを集め、物語の一面以上を明らかにします。","love":"今日の恋愛では、推測よりも存在感を選びましょう。あなたのコミュニケーション、柔軟性、学習の速さという才能は、演じることなく他者とつながる助けになります。","career":"仕事では、新しい勢いを追いかける前に、最も意味のあるタスクを完了させましょう。好奇心旺盛で適応力があり、表現力豊かで機知に富むことを、同時にすべて満たさなければならない期待ではなく、道具として使いましょう。","finance":"今日の金銭に関する選択は、シンプルで現実的に保ちましょう。落ち着きのなさ、注意の散漫、考えすぎが、実践的な判断に影響を及ぼし始めるときに気づきましょう。","wellbeing":"小さな休止はあなたのエネルギーをリセットすることができます。好奇心に扉を開かせ、そこで見つけたものを理解するのに十分な時間を過ごしましょう。","guidance":"一日が終わる前に覚えておいてください：好奇心に扉を開かせ、その後見つけたものを理解するために十分な時間を費やしましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'week', 'ja', '{"overview":"今週は、劇的な瞬間よりも着実な選択によって展開します。双子座は風のエネルギーを通して進みます。好奇心とつながりが双子を導き、アイデアを集め、物語の複数の側面を明らかにします。","love":"関係は、正直さと温かさの両方の余地を持つ会話から恩恵を受けます。あなたのコミュニケーション能力、多才さ、学習の速さは、演じることなく他者とつながるのに役立ちます。","career":"あなたの最高の職業上の進歩は、優先順位を選び、それに時間を確保することから生まれます。好奇心、適応力、表現力、機知を道具として使い、すべてを一度に満たさなければならない期待として使わないでください。","finance":"大きな支出をする前に、自分の支出のパターンを見直してください。落ち着かない気持ち、気が散ること、考えすぎが実際的な決定に影響し始める時に注意してください。","wellbeing":"一週間を通して、運動と本物の回復のバランスを取りましょう。好奇心に扉を開かせ、そして見つけたことを理解するために十分な時間滞在しましょう。","guidance":"今週の指針としてこの問いを心に留めてください：好奇心に扉を開かせ、その後見つけたものを理解するのに十分な時間を過ごしましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'year', 'ja', '{"overview":"今年は、アイデンティティ、目的、そして自分のエネルギーの使い方に関して忍耐強い成長を促します。双子座は風のエネルギーの中を進みます。好奇心とつながりが双子座を導き、アイデアを集め、一つの物語の複数の側面を明らかにします。","love":"一貫性を実践し、つながりを人間のペースで進化させることを許すと、愛は深まります。コミュニケーション力、柔軟性、学習の速さが、演じることなくつながる手助けになります。","career":"野心を維持可能な構造と組み合わせると、長期的な仕事はより強くなります。好奇心旺盛で、適応力があり、表現力豊かで、機知に富むことを、すぐにすべて満たさなければならない期待ではなく、道具として使ってください。","finance":"完璧な予測ではなく、繰り返し行える習慣を通じて経済的自信を築きましょう。不安や集中力の散漫、考えすぎが実際の判断に影響を与え始めたときに気づきましょう。","wellbeing":"幸福を、人生を完成させたあとに得られる報酬としてではなく、今築いている人生の基盤として扱いなさい。好奇心に扉を開かせ、それから見つけたものを理解するのに十分な時間を過ごしなさい。","guidance":"一年を通してこのコンパスに立ち返りなさい：好奇心に扉を開かせ、そして見つけたものを理解するのに十分な時間滞在しなさい。"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('cancer', 'ja', '{"name":"がん","dateRange":"6月21日 – 7月22日","rulingPlanet":"月","summary":"保護的で直感的な蟹座は、記憶、感情、家庭を尊重することで所属感を生み出す。","originStory":"がんはカニ座のカリクノスに関連しており、ヘラクレスのヒドラとの戦いの際に忠誠心を示した後、星の中に置かれました。その甲羅と月の支配は、保護、感情の潮の動き、そして身近な人々への献身を反映しています。","traits":["直感的な","思いやり","保護的","想像力豊か"],"strengths":["共感","忠誠","感情的洞察"],"challenges":["気まぐれ","防御の背後に退く","物事を個人的に受け取る"],"compatibleSigns":["蠍座","うお座","おうし座"],"reflectionPrompt":"正直なつながりのための扉を開けながら、内なる世界を大切にしましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'day', 'ja', '{"overview":"今日は、一つの明確で意図的なステップが吉です。かに座は水のエネルギーの中を動きます。保護的で直感的なかに座は、記憶、感情、家を敬うことで帰属意識を生み出します。","love":"今日の恋愛では、推測よりも現在の瞬間を選びましょう。あなたの共感力、忠誠心、感情的洞察力が、演じることなくつながる助けとなります。","career":"仕事では、新しい勢いを追いかける前に、最も重要なタスクを完了してください。直感的な、思いやりのある、守護的な、創造的なを道具として使い、一度にすべて満たさなければならない期待としてではありません。","finance":"今日の金銭に関する選択は、シンプルで現実的に保ちましょう。気分の変わりやすさ、防御の背後に隠れること、物事を個人的に受け取ることが、実践的な判断に影響を及ぼし始めるときに気づきましょう。","wellbeing":"小さな休止はあなたのエネルギーをリセットすることができます。正直なつながりへの扉を開けたまま、内面を大切にしましょう。","guidance":"一日が終わる前に覚えておいてください：自分の内面を大切にしながら、正直なつながりのための扉を開けておきましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'week', 'ja', '{"overview":"今週は、劇的な瞬間よりも着実な選択を通じて進展します。かに座は水のエネルギーを通じて動きます。保護的で直感的なかに座は、記憶、感情、家庭を大切にすることで所属感を生み出します。","love":"関係は、正直さと温かさの両方の余地を持つ会話から恩恵を受けます。共感、忠誠心、感情的洞察のあなたの才能は、演じることなくつながる手助けとなります。","career":"あなたの最高の専門的な成長は、優先事項を選び、それに時間を確保することで得られます。直感的で、思いやりがあり、守護的で、想像力豊かであることを、同時にすべて満たさなければならない期待ではなく、ツールとして使いましょう。","finance":"大きな支出をする前に、自分の支出パターンを確認してください。気分の浮き沈み、防衛的になること、物事を個人的に受け取る傾向が実際の決定に影響を与え始めるタイミングに気づいてください。","wellbeing":"一週間を通して、運動と本物の回復のバランスを取りましょう。正直なつながりのための扉を開けながら、内なる世界を大切にしましょう。","guidance":"今週の指針としてこの問いを心に留めてください：内面を大切にしつつ、誠実なつながりのために扉を開けておきましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'year', 'ja', '{"overview":"今年は、アイデンティティ、目的、そして自分のエネルギーの使い方に関して忍耐強い成長を促します。かに座は水のエネルギーを通って進みます。守護的で直感的なかに座は、記憶、感情、そして家庭を尊重することで帰属感を作り出します。","love":"愛は、一貫性を実践し、人間のペースでつながりが進化することを許すと深まります。あなたの共感力、忠誠心、感情の洞察力は、見せかけることなくつながるのに役立ちます。","career":"長期的な仕事は、野心が維持可能な構造と組み合わさることでより強くなります。直感的で、思いやりがあり、保護的で、想像力豊かなものを、すぐにすべて満たさなければならない期待ではなく、道具として使いましょう。","finance":"完璧な予測ではなく、繰り返し行える習慣を通じて経済的自信を築きましょう。気分の変動、防御的になって引きこもること、物事を個人的に受け取ることが実際の判断に影響を与え始める時に気づきましょう。","wellbeing":"ウェルビーイングを、達成した後の報酬ではなく、築いている人生の基盤として扱いましょう。正直なつながりに扉を開けながら、内面の世界を大切にしましょう。","guidance":"一年を通してこの指針に立ち返りなさい：正直なつながりに向けて扉を開けたまま、自分の内面の世界を大切にしなさい。"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('leo', 'ja', '{"name":"レオ","dateRange":"7月23日 – 8月22日","rulingPlanet":"太陽","summary":"温かさ、創造性、そして惜しみない自己表現は、獅子座を自然な光の源にします。","originStory":"レオはネメアのライオンに結び付けられています。このライオンはヘラクレスの最初の功業で倒されたほとんど無敵の生き物です。天に昇り、勇気、君主の存在、そして太陽の創造力の象徴となりました。","traits":["暖かい","創造的","寛大な","自信がある"],"strengths":["リーダーシップ","忠誠","心からの表現"],"challenges":["誇り","認識を必要とする","挫折を大げさに表現する"],"compatibleSigns":["牡羊座","射手座","てんびん座"],"reflectionPrompt":"あなたの光を惜しみなく分かち合い、他の人があなたのそばで輝くことを許してください。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'day', 'ja', '{"overview":"今日は、一つの明確で意図的な一歩が吉と出る日です。獅子座は火のエネルギーを通して動きます。温かさ、創造性、そして寛大な自己表現がライオンを自然な光の源にします。","love":"今日の恋愛では、推測よりも存在感を選びましょう。あなたのリーダーシップ、忠誠心、心からの表現という才能が、演じることなくつながる助けになります。","career":"仕事では、新しい勢いを追いかける前に、最も意味のあるタスクを完了させてください。温かさ、創造性、寛大さ、自信を、同時にすべてを満たすべき期待としてではなく、道具として使いましょう。","finance":"今日の金銭に関する選択は、シンプルで現実的に保ちましょう。誇り、承認欲求、挫折の演出が、実践的な判断に影響を及ぼし始めるときに気づきましょう。","wellbeing":"小さな休憩はあなたのエネルギーをリセットすることができます。光を惜しみなく分かち合い、他の人もあなたのそばで輝かせましょう。","guidance":"一日の終わりまでに思い出してください：あなたの光を惜しみなく分かち合い、他の人があなたのそばで輝けるようにしましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'week', 'ja', '{"overview":"今週は、劇的な瞬間よりも着実な選択によって展開します。獅子座は火のエネルギーを通して進みます。温かさ、創造性、そして寛大な自己表現が獅子座を自然な光の源とします。","love":"関係は、正直さと温かさの両方に余地を持たせた会話から利益を得ます。あなたのリーダーシップ、忠誠心、心からの表現という才能は、演じることなく人とつながるのに役立ちます。","career":"あなたの最高の職業上の進歩は、優先事項を選び、それに時間を確保することから生まれます。温かく、創造的で、寛大で、自信に満ちたものを道具として使い、一度にすべてを満たすべき期待としてではありません。","finance":"大きな支出をする前に、自分の支出のパターンを見直しましょう。誇りや承認欲求、失敗を大げさに表現することが実際の判断に影響し始める時に注意してください。","wellbeing":"週を通して、真の回復とともに運動のバランスを取ってください。あなたの光を惜しみなく分かち合い、他の人があなたのそばで輝くようにしましょう。","guidance":"今週の指針としてこの質問を用いましょう：あなたの光を惜しみなく分かち合い、他の人があなたのそばで輝けるようにしましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'year', 'ja', '{"overview":"今年は、アイデンティティ、目的、そしてエネルギーの使い方に関して、忍耐強い成長を促します。レオは火のエネルギーを通して進みます。温かさ、創造性、そして寛大な自己表現が、ライオンを自然な光の源にします。","love":"愛は、一貫性を実践し、人間のペースでつながりが進化することを許すと深まります。あなたのリーダーシップ、忠誠心、心からの表現という才能は、演じることなくつながる手助けになります。","career":"長期的な仕事は、野心が維持可能な構造と組み合わさることでより強くなります。温かさ、創造性、寛大さ、自信を、すぐにすべて満たさなければならない期待ではなく、道具として使いましょう。","finance":"完璧な予測ではなく、繰り返し可能な習慣を通じて経済的自信を築きましょう。誇り、承認欲求、挫折の大げさな表現が実際の判断に影響を与え始めたときに気づきましょう。","wellbeing":"幸福を、人生を完成させた後のご褒美ではなく、築いている人生の基盤として扱いなさい。自分の光を惜しみなく分かち合い、他の人々もあなたのそばで輝かせなさい。","guidance":"一年を通してこの指針に立ち返りましょう：自分の光を惜しみなく分かち合い、他の人もあなたのそばで輝かせましょう。"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('virgo', 'ja', '{"name":"乙女座","dateRange":"8月23日 – 9月22日","rulingPlanet":"水星","summary":"識別力と奉仕の心が乙女座を導き、注意深い観察を実用的な改善へと変える。","originStory":"乙女座はしばしば正義の乙女アストライアと結びつけられます。アストライアは他の神々が引き上げた後も人類と共に残りました。彼女が運ぶ小麦は、この星座を収穫、技術、意図の純粋さ、そして生命を支えるものの世話と結びつけます。","traits":["観察力がある","実践的","思慮深い","正確"],"strengths":["分析","職人技","役立つサービス"],"challenges":["完璧主義","自己批判","細部を心配すること"],"compatibleSigns":["おうし座","やぎ座","がん"],"reflectionPrompt":"改善できることを改善し、完全でなくても良い仕事は完了させることを許しなさい。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'day', 'ja', '{"overview":"今日は明確で意図的な一歩が有利です。乙女座は地のエネルギーを通ります。識別力と奉仕が乙女座を導き、慎重な観察を実用的な改善へと変えます。","love":"今日の恋愛では、推測よりも存在感を選びましょう。あなたの分析力、職人技、役立つサービスという才能は、演じることなくつながる手助けになります。","career":"仕事では、新しい勢いを追いかける前に、最も重要なタスクを完了してください。観察力のある、実用的な、思慮深い、正確なを道具として使い、一度にすべて満たさなければならない期待としてではありません。","finance":"今日の金銭に関する選択は、シンプルで現実的に保ちましょう。完璧主義、自己批判、細部への過度の心配が、実践的な判断に影響を及ぼし始めるときに気づきましょう。","wellbeing":"小さな休止はあなたのエネルギーをリセットすることができます。できることを改善し、完璧になる前に良い仕事が完成することを許しましょう。","guidance":"一日の終わりまでに覚えておいてください：改善できることを改善し、完璧でなくても良い仕事を完成させることを許してください。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'week', 'ja', '{"overview":"今週は、一度の劇的な瞬間よりも、着実な選択を通じて展開します。乙女座は地のエネルギーを通って進みます。洞察と奉仕が乙女座を導き、注意深い観察を実用的な改善に変えます。","love":"関係は、正直さと温かさの両方に余地を与える会話から利益を得ます。分析力、職人技、役立つサービスの才能は、演じることなくつながりを助けることができます。","career":"あなたの最高の専門的な進歩は、優先事項を選び、それに時間を確保することから生まれます。観察力、実用性、思慮深さ、正確さを、同時にすべて満たすべき期待ではなく、道具として使いましょう。","finance":"大きな投資をする前に、自分の支出パターンを確認してください。完璧主義や自己批判、細部への心配が実際的な判断に影響を与え始める時に気づくようにしてください。","wellbeing":"一週間を通して、運動と本物の回復のバランスを取りましょう。できることを改善し、完璧になる前に良い仕事は完成を許しましょう。","guidance":"今週の指針としてこの問いを心に留めてください：改善できるものは改善し、完璧になる前に良い仕事は完成と認めましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'year', 'ja', '{"overview":"今年は、アイデンティティ、目的、そしてエネルギーの使い方に関して、忍耐強い成長を促します。おとめ座は地のエネルギーを通ります。識別力と奉仕の心が乙女座を導き、注意深い観察を実践的な改善に変えます。","love":"一貫性を実践し、つながりを人間のペースで進化させることを許すと、愛は深まります。分析力、職人技、役立つサービスの才能が、演じることなくつながる手助けになります。","career":"野心が維持可能な構造と組み合わさると、長期的な仕事は強くなります。観察力、実践力、思慮深さ、正確さを、一度にすべて満たさなければならない期待ではなく、道具として使いなさい。","finance":"完璧な予測ではなく、繰り返し行える習慣を通じて経済的自信を築きましょう。完璧主義や自己批判、細部への過度な心配が実際の判断に影響を与え始めていると気付いてください。","wellbeing":"幸福を、人生を完成させたあとに得られる報酬としてではなく、今築いている人生の基盤として扱いなさい。改善できることを改善し、完璧である前に良い仕事は完了したものと認めなさい。","guidance":"一年を通してこのコンパスに立ち返りなさい：できることを改善し、良い仕事が完璧でなくても完成することを許しなさい。"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('libra', 'ja', '{"name":"てんびん座","dateRange":"9月23日 – 10月22日","rulingPlanet":"金星","summary":"バランス、美、そして相互性が、秤をすべての声を尊重する選択へ導く。","originStory":"天秤座の天秤は、正義の女神アストライアによって持たれており、黄道帯で唯一の無生物の象徴を形成しています。それらは、衡量された判断、社会的調和、そして既に存在すると仮定するのではなく、バランスを取り戻すための継続的な努力を表しています。","traits":["外交的","公平な考え方","魅力的","協力的"],"strengths":["仲裁","視点","調和を作る"],"challenges":["優柔不断","人を喜ばせること","必要な対立を避けること"],"compatibleSigns":["ふたご座","みずがめ座","レオ"],"reflectionPrompt":"自分のニーズの真実を放棄せずに、公平さを求めましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'day', 'ja', '{"overview":"今日は、一つの明確で意図的な一歩が吉と出る日です。天秤座は風のエネルギーを通して動きます。バランス、美しさ、そして相互関係が天秤座を導き、すべての声を尊重する選択に導きます。","love":"今日の恋愛では、推測よりも存在感を選びましょう。あなたの調停力、視点、調和を作る力という才能が、演じることなくつながる助けになります。","career":"仕事では、新しい勢いを追いかける前に、最も意味のあるタスクを完了させてください。外交的で、公平かつ魅力的で、協力的であることをツールとして使い、一度にすべて満たすべき期待としてではなく活用してください。","finance":"今日の金銭の選択は、シンプルで現実的に保ちましょう。優柔不断、人に気を使いすぎること、必要な対立を避けることが実際的な判断に影響を与え始めるときに気づきましょう。","wellbeing":"小さな休止はエネルギーをリセットすることができます。自分のニーズの真実を放棄することなく、公平さを求めましょう。","guidance":"日が終わる前に、覚えておいてください：自分のニーズの真実を放棄せずに、公平さを求めましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'week', 'ja', '{"overview":"今週は劇的な瞬間というより、着実な選択を通じて展開します。天秤座は風のエネルギーを通じて進んでいきます。バランス、美しさ、そして相互性が、すべての声を尊重する選択に向かって天秤座を導きます。","love":"人間関係は、正直さと温かさの両方に余裕を持たせる会話から恩恵を受けます。あなたの仲裁、人の見方、調和を作る才能は、演じることなくつながる助けになります。","career":"あなたの最高の職業上の進歩は、優先順位を選び、それに時間を確保することから生まれます。外交的、公正、魅力的、協力的であることを道具として使い、すべてを一度に満たさなければならない期待として使わないでください。","finance":"大きな支出をする前に、自分の支出パターンを確認してください。優柔不断、人に気を使いすぎること、避けるべき対立を避けることが実際の決断に影響を与え始めるタイミングに気づいてください。","wellbeing":"週を通して、真の回復とともに動きをバランスさせましょう。自分のニーズの真実を放棄せずに、公平さを追求してください。","guidance":"この質問を週の指針としましょう：自分自身のニーズの真実を捨てずに、公平さを求めましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'year', 'ja', '{"overview":"今年は、アイデンティティ、目的、そしてエネルギーの使い方に関して、忍耐強い成長を促します。天秤座は風のエネルギーの中を進みます。バランス、美、美的感覚、そして相互性が、すべての声を尊重する選択へと天秤を導きます。","love":"愛は、一貫性を実践し、人間のペースでつながりが進化することを許すと深まります。あなたの瞑想、視点、調和を生み出す才能は、演じることなくつながるのに役立ちます。","career":"野心が維持可能な構造と組み合わさると、長期的な仕事は強くなります。外交的、公正、魅力的、協力的な態度をツールとして使い、一度にすべてを満たすべき期待としてではなく活用してください。","finance":"完璧な予測ではなく、繰り返し行える習慣を通じて経済的自信を築きましょう。優柔不断、人に気を使うこと、必要な対立を避けることが実際の判断に影響し始めていると気付いてください。","wellbeing":"幸福を、人生を完成させた後のご褒美ではなく、築いている人生の基盤として扱いなさい。自分の必要を否定することなく、公平を求めなさい。","guidance":"一年を通してこの指針に立ち返りなさい：自分のニーズの真実を捨てずに、公平を求めなさい。"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('scorpio', 'ja', '{"name":"蠍座","dateRange":"10月23日 – 11月21日","rulingPlanet":"冥王星","summary":"深さと変容が蠍座を定義し、その洞察力は表面下の真実を見つける。","originStory":"蠍座は、オリオンという狩人が傲慢さで自然の秩序を乱した後に対峙するために送られたサソリを思い出させます。天空における彼らの対立する位置は、境界、結果、神秘、そして終わりの後に見つかる再生の力を喚起します。","traits":["強烈","洞察力のある","忠実","機知に富む"],"strengths":["感情的勇気","集中","変革"],"challenges":["秘密","疑い","恨みを抱くこと"],"compatibleSigns":["がん","うお座","乙女座"],"reflectionPrompt":"真実を隠すのではなく、深さを使って変革する"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'day', 'ja', '{"overview":"今日は一歩をはっきりと意図的に踏み出すことが吉です。蠍座は水のエネルギーの中を進みます。深さと変容が蠍座を特徴づけ、その洞察力は表面の下にある真実を見つけます。","love":"今日の恋愛では、推測よりも現在の瞬間を選びましょう。あなたの感情的な勇気、集中力、変容の才能が、演じることなくつながる助けとなります。","career":"仕事では、新しい勢いを追いかける前に、最も重要なタスクを完了してください。激しい、洞察力のある、忠実な、機転の利くを道具として使い、一度にすべて満たさなければならない期待としてではありません。","finance":"今日のお金の選択はシンプルで現実的に保ちましょう。秘密や疑念、恨みが実用的な判断に影響を与え始めるときに注意してください。","wellbeing":"小さな休止はあなたのエネルギーをリセットすることができます。真実を隠すのではなく、あなたの深さを使ってそれを変容させなさい。","guidance":"一日の終わりまでに思い出してください：真実を隠すのではなく、それを変えるためにあなたの深さを使いましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'week', 'ja', '{"overview":"今週は、一度の劇的な瞬間よりも、着実な選択を通じて展開します。蠍座は水のエネルギーを通って進みます。深さと変容が蠍座を特徴づけ、その洞察は表面の下にある真実を見出します。","love":"関係は、正直さと温かさの両方の余地を持つ会話から恩恵を受けます。あなたの感情的な勇気、集中力、変容の贈り物は、演じることなくつながるのに役立ちます。","career":"あなたの最も良い専門的な進歩は、優先事項を選び、それに時間を確保することから生まれます。集中力、洞察力、忠実さ、機転を、一度にすべて満たさなければならない期待ではなく、道具として使いなさい。","finance":"大きな支出をする前に、支出のパターンを見直してください。秘密や疑念、恨みが実際的な決定に影響を及ぼし始める時に気づきましょう。","wellbeing":"週を通して本物の回復とバランスの取れた動きを心がけましょう。真実を隠すためではなく、深みを使って真実を変えるのです。","guidance":"今週の指針としてこの質問を用いましょう：真実を隠すためではなく、その真実を変えるためにあなたの深みを使いましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'year', 'ja', '{"overview":"今年は、アイデンティティ、目的、そしてエネルギーの使い方に関して、忍耐強い成長を促します。さそり座は水のエネルギーを通ります。深さと変容がさそり座を定義し、その洞察力は表面の下に真実を見出します。","love":"一貫性を実践し、つながりを人間のペースで進化させることを許すと、愛は深まります。感情的勇気、集中、変容の才能が、演じることなくつながる手助けになります。","career":"野心を維持可能な構造と組み合わせると、長期的な仕事はより強くなります。強烈で、洞察力があり、忠実で、機転が利くことを道具として使い、一度にすべて満たさなければならない期待とはしないでください。","finance":"完璧な予測ではなく、繰り返しできる習慣を通じて経済的な自信を築きましょう。秘密主義、疑念、恨みが実際的な判断に影響を与え始めるときを意識してください。","wellbeing":"幸福を、人生を完成させた後のご褒美ではなく、築いている人生の基盤として扱いなさい。その深みを使って真実を変えるのではなく、隠すために使いなさい。","guidance":"一年を通してこのコンパスに戻ってください：真実を隠すのではなく、あなたの深さを使って真実を変容させてください。"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('sagittarius', 'ja', '{"name":"射手座","dateRange":"11月22日 – 12月21日","rulingPlanet":"木星","summary":"射手は、真実、旅、学び、そして目的を持った楽観主義を通じて、より広い視野を求めます。","originStory":"射手座は一般的に、熟練したケンタウロスであり教師であるカイロンに関連付けられ、彼の矢は馴染みのあるものを超えて向かいます。この星座は本能と高次の理解の結合を象徴し、常により意味のある地平を目指しています。","traits":["冒険好き","楽観的","正直","哲学的"],"strengths":["ビジョン","熱意","心を開くこと"],"challenges":["無愛想さ","過剰約束","日常からの逃避"],"compatibleSigns":["牡羊座","レオ","みずがめ座"],"reflectionPrompt":"高く目指せ、しかし日々の行動で支えられる方向を選べ。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'day', 'ja', '{"overview":"今日は一歩をはっきりと意図的に踏み出すことが吉です。射手座は火のエネルギーの中を進みます。射手座の人は、真実、旅行、学び、そして目的ある楽観主義を通して、より広い地平を求めます。","love":"今日の恋愛では、推測よりも存在感を選びましょう。あなたのビジョン、熱意、開かれた心の才能は、演じることなくつながる助けになります。","career":"仕事では、新しい勢いを追い求める前に、最も意味のある仕事を完了させなさい。冒険的で、楽観的で、正直で、哲学的であることを道具として使い、一度にすべて満たすべき期待としてではなく活用しなさい。","finance":"今日のお金の選択はシンプルで現実的に保ちなさい。率直さ、過度な約束、日課からの逃避が実用的な判断に影響し始める時に気付くこと。","wellbeing":"小さな休止がエネルギーをリセットすることがあります。遠くを目指しつつ、日常の行動で支えられる方向を選びましょう。","guidance":"日が終わる前に覚えておきなさい：遠くを目指しつつも、日々の行動が支えられる方向を選びなさい。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'week', 'ja', '{"overview":"今週は、劇的な瞬間よりも着実な選択によって進展します。射手座は火のエネルギーを通じて進みます。射手座の射手は、真実、旅行、学び、そして目的のある楽観主義を通じて、より広い地平を求めます。","love":"人間関係は、正直さと温かさの両方に余裕を持たせる会話から恩恵を受けます。あなたのビジョン、熱意、心の広さという才能は、演じることなくつながる助けになります。","career":"あなたの最高の専門的進歩は、優先事項を選び、それに時間を確保することから生まれます。冒険的、楽観的、正直、哲学的なものをツールとして使い、一度にすべてを満たすべき期待としてではなく使いましょう。","finance":"大きな支出をする前に、自分の支出のパターンを見直してください。率直すぎること、過剰な約束、日常からの逃避が実際的な判断に影響を与え始める時に気づきましょう。","wellbeing":"週を通して運動と本物の回復をバランスさせましょう。遠くを目指しつつ、日々の行動で支えられる方向を選びましょう。","guidance":"今週の指針としてこの問いを心に留めてください：遠い目標を持ちながらも、日々の行動で支えられる方向を選びましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'year', 'ja', '{"overview":"今年は、自己のアイデンティティ、目的、そしてエネルギーの使い方に関して、忍耐強い成長を促します。射手座は火のエネルギーを通過します。アーチャーは、真実、旅行、学び、そして意図的な楽観を通じて、より広い視野を求めます。","love":"愛は、一貫性を実践し、人間のペースでつながりが進化することを許すと深まります。あなたのビジョン、熱意、柔軟な考え方という才能は、演技せずに人とつながる助けになります。","career":"長期的な仕事は、野心が維持可能な構造と組み合わさることでより強くなります。冒険的、楽観的、正直、哲学的なものを道具として使い、一度にすべて満たさなければならない期待として使わないでください。","finance":"完璧な予測ではなく、繰り返し可能な習慣を通じて金融の自信を築きましょう。率直すぎる態度、過剰な約束、日課からの逃避が実際の判断に影響を与え始めていると気付いてください。","wellbeing":"ウェルビーイングを、達成した後の報酬ではなく、築いている人生の基盤として扱いましょう。遠くを目指しつつ、あなたの日々の行動が支えられる方向を選びましょう。","guidance":"一年を通してこの羅針盤に立ち返りなさい：遠くを目指しなさい、しかし日々の行動で支えられる方向を選びなさい。"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('capricorn', 'ja', '{"name":"やぎ座","dateRange":"12月22日 – 1月19日","rulingPlanet":"土星","summary":"規律と長期的視野が、山羊座が上昇するのを助け、下にある深みについて賢明であり続ける。","originStory":"山羊座の海山羊はパーンと関連しており、パーンはタイフォンから逃れる際に部分的に魚に変身しました。その山と海の性質は、野心と感情的な生存を結びつけ、時間と責任を通じて得た熟練を尊重します。","traits":["野心的","規律正しい","辛抱強い","責任感がある"],"strengths":["忍耐","戦略","信頼性"],"challenges":["硬直","悲観主義","業績によって価値を測る"],"compatibleSigns":["おうし座","乙女座","蠍座"],"reflectionPrompt":"休息も構造の一部であることを覚えながら、長期的な視野で築いていきなさい。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'day', 'ja', '{"overview":"今日は一つの明確で意図的な一歩が吉と出ます。山羊座は地のエネルギーを通過します。規律と長期的なビジョンが、シーゴート（山羊座の別名）を登らせる一方で、下の深みに関しても賢明でいられる手助けとなります。","love":"今日の恋愛では、推測よりも存在感を選びましょう。あなたの忍耐力、戦略、信頼性という才能が、演じることなくつながる助けになります。","career":"仕事では、新しい勢いを追い求める前に、最も意味のある仕事を完了させなさい。野心的で、規律正しく、忍耐強く、責任感を持つことを、同時にすべて満たすべき期待ではなく、道具として使いなさい。","finance":"今日の金銭に関する選択は、シンプルで現実的に保ちましょう。硬直性、悲観主義、成果によって自分の価値を測ることが、実践的な判断に影響を及ぼし始めるときに気づきましょう。","wellbeing":"小さな休止はあなたのエネルギーをリセットすることができます。休息も構造の一部であることを忘れずに、長期的な視点で築きましょう。","guidance":"日が終わる前に覚えておきなさい：休息も構造の一部であることを忘れずに、長期的な視点で築きなさい。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'week', 'ja', '{"overview":"今週は、劇的な瞬間よりも着実な選択によって展開します。山羊座は地のエネルギーを通して進みます。規律と長期的なビジョンが、海山羊座を高みに登らせつつ、下にある深みについて賢明さを保つ助けになります。","love":"関係は、正直さと温かさの両方に余地を持たせた会話から利益を得ます。あなたの忍耐力、戦略性、信頼性という才能は、演じることなく人とつながるのに役立ちます。","career":"あなたの最高の専門的進歩は、優先事項を選び、それに時間を確保することから生まれます。野心的、規律ある、忍耐強い、責任感のあるものをツールとして使い、一度にすべてを満たすべき期待としてではなく使いましょう。","finance":"大きな支出をする前に、自分の支出のパターンを見直してください。実用的な判断に影響を与え始める硬直性、悲観主義、業績による価値の測定に気づいてください。","wellbeing":"週を通して運動と本物の回復をバランスさせましょう。長期的に構築しながら、休息も構造の一部であることを忘れないでください。","guidance":"今週の指針としてこの問いを心に留めてください：休息も構造の一部であることを忘れずに、長期的な視点で築きましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'year', 'ja', '{"overview":"今年は、自己認識、目的、そして自分のエネルギーの使い方に関して忍耐強い成長を促します。山羊座は地のエネルギーを通って進みます。規律と長期的なビジョンが、シーゴートが下の深みについて賢明でありながら登るのを助けます。","love":"愛は、一貫性を実践し、人間のペースでつながりが進化することを許すと深まります。あなたの忍耐力、戦略性、信頼性は、見せかけることなくつながるのに役立ちます。","career":"長期的な仕事は、野心が維持可能な構造と組み合わさることでより強くなります。野心的で、規律正しく、忍耐強く、責任感を持つことを、すぐにすべて満たさなければならない期待ではなく、道具として使いなさい。","finance":"完璧な予測ではなく、繰り返し可能な習慣を通じて金融の自信を築きましょう。実用的な判断に影響を与え始める時、硬直性、悲観、成果による価値の測定に気づきましょう。","wellbeing":"ウェルビーイングを、達成した後の報酬ではなく、築いている人生の基盤として扱いましょう。休息も構造の一部であることを忘れず、長期的な視野で築きましょう。","guidance":"一年を通してこの指針に立ち返りなさい：休息も構造の一部であることを忘れずに、長期的な視点で築きなさい。"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aquarius', 'ja', '{"name":"みずがめ座","dateRange":"1月20日 – 2月18日","rulingPlanet":"天王星","summary":"独立した思考と集団的なビジョンが、水瓶座の人を導いて、新しいアイデアを世界に注ぎ込ませます。","originStory":"水瓶座はガニメデスに関連しており、彼は神々に水をもたらし、象徴的には人類に知識をもたらす杯の運び手です。そのイメージは水を運んでいますが、この星座は空気の星座であり、共通の利益のために共有されるアイデアやシステム、新しい変革を表しています。","traits":["オリジナル","独立","人道主義者","創造的な"],"strengths":["イノベーション","客観性","コミュニティのビジョン"],"challenges":["超然","反対習慣","固定された意見"],"compatibleSigns":["ふたご座","てんびん座","射手座"],"reflectionPrompt":"あなたの違いを、距離ではなくつながりのために役立てなさい。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'day', 'ja', '{"overview":"今日は一つの明確で意図的な一歩が吉とされます。水瓶座は風のエネルギーを通過します。独立した考えと集合的なビジョンが、水瓶座に新しいアイデアを世界に注ぎ込むよう導きます。","love":"今日の恋愛では、推測よりも存在感を選びましょう。あなたの革新力、客観性、コミュニティビジョンという才能が、演じることなくつながる助けになります。","career":"仕事では、新しい勢いを追いかける前に、最も重要なタスクを完了してください。独創的な、独立した、人道的な、発明的なを道具として使い、一度にすべて満たさなければならない期待としてではありません。","finance":"今日の金銭の選択はシンプルで現実的に保ちましょう。実用的な決定に影響を与え始める、離脱、逆張りの習慣、固定観念に気づきましょう。","wellbeing":"小さな休止はあなたのエネルギーをリセットすることができます。あなたの違いを距離ではなく、つながりのために役立てなさい。","guidance":"一日が終わる前に、覚えておいてください：あなたの違いを距離ではなく、つながりのために使いなさい。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'week', 'ja', '{"overview":"今週は一度の劇的な瞬間よりも、着実な選択を通して進展します。水瓶座は空気のエネルギーを通して動きます。独立した思考と集団のビジョンが、水瓶座に新しいアイデアを世界に注ぎ込むよう導きます。","love":"関係は、正直さと温かさの両方に余地を持たせた会話から利益を得ます。あなたの革新性、客観性、コミュニティビジョンという才能は、演じることなく人とつながるのに役立ちます。","career":"あなたの最高の職業上の進歩は、優先事項を選び、それに時間を確保することから生まれます。独創的で独立、人道的、発明的なものを道具として使い、一度にすべてを満たすべき期待としてではありません。","finance":"大きな支出をする前に、自分の支出のパターンを見直してください。実用的な判断に影響を与え始めるのは、執着心、反対的な習慣、固定観念がいつかに注目してください。","wellbeing":"週を通して、真の回復とバランスの取れた動きを心がけましょう。あなたの違いは、距離を生むのではなく、つながりを生むものにしてください。","guidance":"この質問を週の指針としましょう：違いを距離ではなくつながりに役立てましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'year', 'ja', '{"overview":"今年は、自己認識、目的、そして自分のエネルギーの使い方に関して忍耐強い成長を促します。水瓶座は風のエネルギーの中を進みます。独立した思考と集合的なビジョンが、水瓶座の人に新しいアイデアを世界に注ぎ込むよう導きます。","love":"愛は、一貫性を実践し、人間のペースでつながりが進化することを許すと深まります。あなたの革新性、客観性、コミュニティビジョンという才能は、演じることなくつながる手助けになります。","career":"長期的な仕事は、野心が維持可能な構造と組み合わさることでより強くなります。オリジナルで独立的で人道的で創造的なものを、同時にすべて満たすべき期待ではなく、道具として使いなさい。","finance":"完璧な予測ではなく、繰り返し可能な習慣を通じて金融の自信を築きましょう。実用的な意思決定に対して、無関心、逆張りの習慣、固定観念が影響を与え始めていると気付いてください。","wellbeing":"幸福を、人生を完成させた後のご褒美ではなく、築いている人生の基盤として扱いなさい。あなたの違いを距離ではなく、つながりに役立てなさい。","guidance":"一年を通してこのコンパスに立ち返りなさい：あなたの違いを、距離ではなくつながりのために生かしなさい。"}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('pisces', 'ja', '{"name":"うお座","dateRange":"2月19日 – 3月20日","rulingPlanet":"海王星","summary":"思いやりと想像力が、直感、夢、共有された感情の間で魚たちを導く。","originStory":"うお座は、アフロディーテとエロスが魚になり、ティフォンから逃れるために互いに結びついたことを思い出させます。二匹の魚の絆は、献身、流動的なアイデンティティ、精神的な感受性、そして変わる流れの中で統一を見つけることを表しています。","traits":["思いやりがある","想像力豊か","直感的な","優しい"],"strengths":["共感","創造性","霊的洞察"],"challenges":["現実逃避","あいまいな境界","他人の感情を吸収すること"],"compatibleSigns":["がん","蠍座","やぎ座"],"reflectionPrompt":"あなたの敏感さを守るのに十分な強さの境界線で敬意を払いなさい。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'day', 'ja', '{"overview":"今日は、一つの明確で意図的な一歩が吉と出る日です。魚座は水のエネルギーを通して動きます。思いやりと想像力が魚座を直感、夢、そして共有される感情の間に導きます。","love":"今日の恋愛では、推測よりも現在の瞬間を選びましょう。あなたの共感力、創造力、霊的洞察力が、演じることなくつながる助けとなります。","career":"仕事では、新しい勢いを追い求める前に、最も意味のある仕事を完了させなさい。思いやり、想像力、直感、優しさを、一度にすべて満たさなければならない期待ではなく、道具として使いなさい。","finance":"今日のお金の選択はシンプルで現実的に保ちましょう。現実的な判断に影響を与え始める逃避、境界線の曖昧さ、他人の感情の吸収に気づいてください。","wellbeing":"小さな休止はあなたのエネルギーをリセットすることができます。あなたの敏感さを守るのに十分な境界を設けて尊重しましょう。","guidance":"一日の終わりまでに覚えておいてください：自分の敏感さを守るために十分に強い境界線で敬意を払ってください。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'week', 'ja', '{"overview":"今週は、1つの劇的な瞬間よりも、着実な選択を通じて進んでいきます。魚座は水のエネルギーを通り抜けます。思いやりと想像力が、魚座を直感、夢、そして共有された感情の間で導きます。","love":"人間関係は、正直さと温かさの両方に余地を持たせる会話から恩恵を受けます。あなたの共感、創造性、精神的洞察の才能は、演じることなくつながるのに役立ちます。","career":"あなたの最高の職業上の進歩は、優先順位を選び、それに時間を確保することから生まれます。思いやり、想像力、直感、優しさを道具として使い、すべてを一度に満たさなければならない期待として使わないでください。","finance":"大きな支出をする前に、自分の支出のパターンを確認してください。現実逃避や境界があいまいになること、他人の感情に影響されることが実際の決断に影響を及ぼし始める時に気づいてください。","wellbeing":"一週間を通して、運動と本物の回復のバランスを取りましょう。それを守るのに十分な境界を持って、自分の敏感さを尊重しましょう。","guidance":"今週の指針としてこの問いを心に留めてください：自分の敏感さを尊重し、それを守るのに十分な強い境界を設けましょう。"}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'year', 'ja', '{"overview":"今年は、自己のアイデンティティ、目的、そしてエネルギーの使い方に関して、忍耐強い成長を促します。魚座は水のエネルギーを通過します。思いやりと想像力が、魚座を直感、夢、そして共有された感情の間で導きます。","love":"愛は、一貫性を実践し、人間のペースでつながりが進化することを許すと深まります。あなたの共感力、創造力、精神的洞察力は、見せかけることなくつながるのに役立ちます。","career":"長期的な仕事は、野心が維持可能な構造と組み合わさることでより強くなります。思いやり、想像力、直感、優しさを、すぐにすべて満たさなければならない期待ではなく、道具として使いましょう。","finance":"完璧な予測ではなく、繰り返し行える習慣を通じて経済的自信を築きましょう。現実的な判断に影響を与え始める逃避、境界の曖昧さ、他人の感情の吸収に気づいてください。","wellbeing":"幸福を、人生を完成させたあとに得られる報酬としてではなく、今築いている人生の基盤として扱いなさい。自分の感受性を守るのに十分強い境界線でそれを尊重しなさい。","guidance":"一年を通してこのコンパスに立ち返りなさい：十分にそれを守ることのできる境界で、自分の敏感さを尊重しなさい。"}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('fool', 'ko', '{"name":"바보","meaning":"빈 페이지와 믿음의 도약 — 열린 마음으로 새로운 여정이 시작됩니다.","advice":"당신 앞의 길을 믿고 모든 답을 알지 못하더라도 첫걸음을 내디디세요.","yesNoMeaning":"새로운 시작은 거의 고정된 답을 가지지 않습니다 — 결과는 당신이 취하는 단계에 달려 있습니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('magician', 'ko', '{"name":"마술사","meaning":"당신은 필요한 모든 도구를 가지고 있습니다. 의지를 집중하고 의도를 행동으로 바꾸세요.","advice":"당신의 기술과 자원을 신중하게 사용하세요 — 지금이 실현할 때입니다.","yesNoMeaning":"당신은 이미 필요한 모든 것을 가지고 있다 — 에너지가 집중하여 앞으로 나아가는 것을 지지한다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('high-priestess', 'ko', '{"name":"여교황","meaning":"조용한 지혜가 표면 아래에 숨어 있습니다. 직관과 내면의 목소리에 귀를 기울이세요.","advice":"잠시 멈추고 내면으로 들어가 행동하기 전에 본능이 안내하도록 하세요.","yesNoMeaning":"정답은 지금은 표면 아래에 숨겨져 있습니다 — 명확한 예 또는 아니오를 강요하기보다는 직관을 신뢰하세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('empress', 'ko', '{"name":"황후","meaning":"성장, 풍요, 그리고 돌보는 에너지가 당신을 둘러싸고 있습니다. 아름다움과 돌봄이 번성하게 하세요.","advice":"인내심을 가지고 관대하게 — 사랑으로 창조하고 일이 자연스럽게 무르익게 두세요.","yesNoMeaning":"성장, 풍요, 그리고 돌보는 에너지가 당신의 소원을 지지합니다 — 답은 조용한 ''예''입니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('emperor', 'ko', '{"name":"황제","meaning":"구조, 권위, 그리고 꾸준한 리더십. 훈육과 함께 견고한 기반 위에 세우세요.","advice":"명확한 계획으로 주도권을 잡으세요; 확고한 경계는 지속적인 안정감을 가져옵니다.","yesNoMeaning":"구조, 권위 및 꾸준한 훈육이 자신 있는 ''예''를 뒷받침합니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hierophant', 'ko', '{"name":"교황","meaning":"전통과 신뢰할 수 있는 지침은 신뢰할 수 있는 길을 제공합니다. 이전에 있었던 일에서 배우세요.","advice":"정립된 지혜를 따르고 신뢰하는 사람에게 조언을 구하세요.","yesNoMeaning":"전통과 신뢰할 수 있는 지침은 믿을 만한 ''예''를 가리킨다 — 이미 증명된 것에 기대라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('lovers', 'ko', '{"name":"연인들","meaning":"의미 있는 유대 또는 중요한 선택. 마음이 진정으로 가치를 두는 것을 따르세요.","advice":"정직과 일치를 기준으로 선택하세요 — 진실할 때 연결이 깊어집니다.","yesNoMeaning":"당신의 마음과 가치는 여기서 일치합니다 — 답은 예입니다. 특히 정직하게 선택할 때 그렇습니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('chariot', 'ko', '{"name":"전차","meaning":"의지력과 추진력이 당신을 앞으로 나아가게 한다. 집중하면 승리할 것이다.","advice":"목표에 집중하고 모든 장애물을 자신 있게 헤쳐 나가세요.","yesNoMeaning":"의지력과 추진력이 당신 편이다 — 헌신을 유지하면 명확한 예입니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('strength', 'ko', '{"name":"힘","meaning":"진정한 힘은 부드럽습니다 — 인내, 용기, 그리고 자비가 어떤 도전도 길들입니다.","advice":"차분한 힘으로 이끄세요; 부드러운 손이 종종 가장 강한 손입니다.","yesNoMeaning":"부드러운 용기와 인내심 있는 결단이 이것을 예스로 만듭니다 — 힘이 아닌 침착함으로 이끄세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hermit', 'ko', '{"name":"은둔자","meaning":"한 걸음 물러서서 내면의 명확함을 찾을 시간입니다. 지금의 고독이 더 깊은 답을 줍니다.","advice":"내면으로 돌아가고, 반성하며, 조용함이 당신이 진정으로 필요한 것을 드러내게 하세요.","yesNoMeaning":"아직 — 카드가 행동하기 전에 한발 물러서서 내면의 명확성을 찾으라고 요청합니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('wheel-of-fortune', 'ko', '{"name":"운명의 수레바퀴","meaning":"운은 변하고 주기는 바뀝니다. 지금 일어나는 변화는 더 큰 리듬의 일부입니다.","advice":"유연하게 흐름을 따르세요 — 좋든 나쁘든 전환을 받아들이세요.","yesNoMeaning":"운이 돌아오고 있습니다 — 결과는 고정된 예 또는 아니오가 아니라 변화에 어떻게 대응하느냐에 달려 있습니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('justice', 'ko', '{"name":"정의","meaning":"진실과 공정함이 승리를 가져옵니다. 원인과 결과가 이제 균형을 이룹니다.","advice":"정직하게 행동하고 양쪽을 저울질하세요; 저울은 공정하게 균형을 잡을 것입니다.","yesNoMeaning":"저울은 아직도 무게를 재고 있습니다 — 공정한 답은 사실과 당신의 정직함에 달려 있습니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('hanged-man', 'ko', '{"name":"매달린 남자","meaning":"필요한 휴식. 통제에서 벗어나 새로운 시각으로 상황을 바라보세요.","advice":"밀지 마세요 — 순간에 맡기고 새로운 관점이 도래하게 하세요.","yesNoMeaning":"먼저 일시정지가 필요합니다 — 지금 억지로 진행하면 더 명확한 답변을 방해할 뿐입니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('death', 'ko', '{"name":"죽음","meaning":"결말은 새로움을 위한 길을 열어줍니다. 제 역할을 다한 것을 놓아주세요.","advice":"후회 없이 놓아주세요; 깊은 변형이 새로운 문을 열고 있습니다.","yesNoMeaning":"결말은 길을 열어주고 있습니다 — 현재의 길이 닫히면서 새로운 길이 시작될 수 있습니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('temperance', 'ko', '{"name":"절제","meaning":"균형과 인내는 조화를 가져옵니다. 반대를 우아하게 조화시키세요.","advice":"절제하며 움직이고 침착함을 유지하세요 — 꾸준한 발걸음이 목적지에 도달합니다.","yesNoMeaning":"균형과 인내는 조화를 가져옵니다 — 신중한 ‘예’를 한 번에 한 걸음씩 나아가면서 취하세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('devil', 'ko', '{"name":"악마","meaning":"집착, 유혹 또는 구속하는 패턴을 조심하세요. 사슬을 인식하세요.","advice":"나를 억누르는 것을 명확히 하고 자유를 되찾으세요 — 사슬은 허락할 때만 묶습니다.","yesNoMeaning":"집착이나 구속적인 패턴이 방해가 됩니다 — 아직은 아니지만, 사슬이 이름 붙여지고 끊어질 때까지는 그렇습니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('tower', 'ko', '{"name":"탑","meaning":"갑작스러운 변화는 거짓을 깨뜨리고 진실을 드러냅니다. 무너진 것은 결코 서있도록 만들어지지 않았습니다.","advice":"뒤흔들림을 환영하세요; 잔해 속에서 더 명확한 기초가 세워질 수 있습니다.","yesNoMeaning":"갑작스러운 변화가 오래된 것을 깨뜨립니다 — 안정적인 ''예''가 가능하려면 땅이 가라앉아야 합니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('star', 'ko', '{"name":"별","meaning":"희망, 치유, 조용한 영감이 폭풍 후 당신의 영혼을 새롭게 합니다.","advice":"앞에 있는 빛을 믿고 계속 믿으세요 — 당신의 소원은 손에 닿을 수 있습니다.","yesNoMeaning":"희망과 조용한 재생은 ''예''를 가리킵니다 — 앞의 빛을 믿고 당신의 소원을 지키세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('moon', 'ko', '{"name":"달","meaning":"환상과 불확실성이 길을 흐리게 합니다. 겉모습이 아니라 직감을 믿으세요.","advice":"속도를 늦추고 더 깊이 살펴보세요; 안개가 걷히면 명확성이 올 것입니다.","yesNoMeaning":"환상과 불확실성이 길을 흐리게 합니다 — 겉모습 아래를 보기 전까지 답은 명확하지 않습니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('sun', 'ko', '{"name":"태양","meaning":"기쁨, 성공, 그리고 빛나는 명료함. 모든 것이 밝고 생명력으로 가득 차 있습니다.","advice":"축하하고 빛나세요 — 긍정적인 에너지가 원하는 결과를 끌어옵니다.","yesNoMeaning":"기쁨과 빛나는 명료함이 밝은 긍정을 확인합니다 — 모든 것이 당신에게 유리하게 작용하고 있습니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('judgement', 'ko', '{"name":"심판","meaning":"일어나고 새로워지며 자신에게 정직하라는 부름. 각성의 판결.","advice":"용기를 가지고 부름에 응하세요; 과거를 용서하고 다음 장으로 나아가세요.","yesNoMeaning":"일어나고 새로워지라는 부름 — 특히 과거를 용서하고 정직하게 응답할 때 그렇습니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('world', 'ko', '{"name":"세계","meaning":"완성과 충만 — 한 주기가 완벽한 전체로 닫힙니다.","advice":"당신이 성취한 것을 축하하세요; 문은 더 넓은 세상으로 열려 있습니다.","yesNoMeaning":"완성과 온전함은 이것이 충족된 ''예''임을 나타냅니다 — 주기가 당신에게 유리하게 닫힙니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-wands', 'ko', '{"name":"완드의 에이스","meaning":"한 줄기 영감이 대담한 창의적 길을 열어줍니다.","advice":"에너지가 충만할 때 시작하고 그 아이디어에 실제 첫걸음을 내딛으세요.","yesNoMeaning":"완드의 에이스는 긍정에 기울어 있습니다: 에너지가 신선할 때 시작하고 아이디어에 실제 첫걸음을 주세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-wands', 'ko', '{"name":"완드 두 장","meaning":"미래는 계획과 방향 선택을 통해 형성되고 있습니다.","advice":"익숙한 것 너머를 바라본 후, 성장할 수 있는 여지가 있는 길에 헌신하세요.","yesNoMeaning":"완드의 투는 조건적임: 익숙한 것을 넘어 바라본 후, 성장할 여지가 있는 길에 헌신하라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-wands', 'ko', '{"name":"완드 3","meaning":"초기의 노력은 기회와 더 넓은 시야가 보이기 시작하면서 확대됩니다.","advice":"계속해서 쌓아 나가고, 당신의 노력이 끌어오는 반응을 만날 준비를 하십시오.","yesNoMeaning":"완 3카드는 긍정 성향: 계속 구축하고 당신의 일이 불러오는 반응을 맞이할 준비를 하세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-wands', 'ko', '{"name":"완드 4","meaning":"안정, 환영, 그리고 공유된 축하가 강한 기반을 만듭니다.","advice":"이정표를 표시하고 지지하는 사람들이 함께 나누도록 하라.","yesNoMeaning":"완드 4는 긍정적인 의미를 기울입니다: 이정표를 기념하고 지지하는 사람들과 함께 나누세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-wands', 'ko', '{"name":"완드의 오형","meaning":"상충되는 목표는 마찰, 소음, 혹은 자신감 시험을 유발합니다.","advice":"경쟁을 유용한 연습으로 바꾸고 목적 없는 갈등은 거부하세요.","yesNoMeaning":"막대 다섯은 조건부로 유지된다: 경쟁을 유용한 연습으로 바꾸고, 목적 없는 갈등은 거부하라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-wands', 'ko', '{"name":"완드의 여섯","meaning":"인정은 결단력 있는 노력과 눈에 보이는 발전 뒤에 따라옵니다.","advice":"격려를 받아들이되, 자신감을 정직한 일에 묶어 두세요.","yesNoMeaning":"완드 6번 카드는 예 쪽으로 기울어져 있습니다: 격려를 받아들이되, 자신감을 정직한 일에 묶어 두세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-wands', 'ko', '{"name":"완드의 7","meaning":"압박이 당신의 결단력을 시험할 때, 당신은 소중한 기반을 지킵니다.","advice":"모든 도전과 싸우기보다는 명확한 경계로 중요한 것을 지켜라.","yesNoMeaning":"완드 7번 카드는 예 쪽으로 기울어져 있습니다: 모든 도전에 맞서기보다는 명확한 경계로 중요한 것을 지키세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-wands', 'ko', '{"name":"완드의 8","meaning":"사건이 가속화되고, 메시지가 도착하며, 모멘텀이 지연을 없앤다.","advice":"신속하게 행동하고 길이 열려 있는 동안 소통을 직접적으로 유지하세요.","yesNoMeaning":"완드의 여덟은 그렇다고 기운다: 길이 열려 있는 동안 신속하게 행동하고 의사소통을 직접적으로 유지하라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-wands', 'ko', '{"name":"완드의 아홉","meaning":"회복력은 강하지만, 과거의 부담 때문에 조심스럽게 만들곤 합니다.","advice":"에너지를 보호하고 모든 상처가 반복될 것을 기대하지 않고 다음 단계를 밟으세요.","yesNoMeaning":"완드 9은 조건적입니다: 당신의 에너지를 보호하고 모든 상처가 반복될 것을 기대하지 않고 다음 단계를 밟으세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-wands', 'ko', '{"name":"완드의 열","meaning":"책임이 무거워졌고 성공은 이제 짐이 되었다.","advice":"위임하고 단순화하며 더 이상 진정으로 자신의 것이 아닌 일을 내려놓아라.","yesNoMeaning":"완 10카드는 부정 성향: 일을 위임하고 단순화하며 더 이상 진정으로 당신의 것이 아닌 일을 내려놓으세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-wands', 'ko', '{"name":"완드의 기사","meaning":"호기심은 활기찬 메시지, 실험 또는 새로운 창의적 관심을 가져온다.","advice":"용기를 가지고 탐험하고, 초심자의 에너지가 행동을 통해 당신을 가르치도록 하세요.","yesNoMeaning":"완드의 시종은 긍정 쪽으로 기울입니다: 용기를 가지고 탐험하며 초보자의 에너지가 행동을 통해 당신을 가르치게 하세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-wands', 'ko', '{"name":"완드의 기사","meaning":"열정이 빠르게 앞장서며 모험과 가능한 조급함을 가져옵니다.","advice":"운동량을 이용하되, 속도가 노력을 흩뜨리기 전에 방향을 선택하세요.","yesNoMeaning":"완드의 기사: 조건부 - 추진력을 사용하되, 속도가 노력을 흩뜨리기 전에 방향을 선택하라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-wands', 'ko', '{"name":"완드의 여왕","meaning":"따뜻한 자신감과 창의적 독립성은 다른 사람들을 당신의 비전으로 이끕니다.","advice":"자신의 존재를 신뢰하고, 다른 사람들을 격려하며, 당신의 야망을 줄이지 마세요.","yesNoMeaning":"완드의 여왕은 긍정에 기울어 있습니다: 자신의 존재를 믿고, 다른 사람을 격려하며, 야망을 줄이지 마세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-wands', 'ko', '{"name":"완즈의 왕","meaning":"성숙한 비전은 영감을 결정적이고 윤리적인 리더십으로 바꿉니다.","advice":"더 큰 목적에서 이끌고 다른 사람들이 기여할 공간을 주십시오.","yesNoMeaning":"완드의 왕은 긍정적인 의미를 기울입니다: 더 큰 목적에서 이끌고 다른 사람들이 기여할 공간을 주세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-cups', 'ko', '{"name":"컵의 에이스","meaning":"마음이 새로운 애정, 연민, 그리고 감정적 재생에 열립니다.","advice":"감정을 솔직하게 받아들이고 결과를 강요하지 않고 배려를 흘러가게 두세요.","yesNoMeaning":"컵의 에이스는 긍정에 기울어 있습니다: 감정을 솔직하게 받고 결과를 강요하지 않고 배려를 흘려보내세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-cups', 'ko', '{"name":"컵 2","meaning":"상호 인식은 파트너십, 매력 또는 진정한 합의를 만듭니다.","advice":"상대방을 평등한 사람으로 만나고 마음에서 우러나오는 말을 하세요.","yesNoMeaning":"컵의 투는 긍정으로 기울어짐: 상대를 동등하게 만나고 진심으로 이야기하라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-cups', 'ko', '{"name":"컵 3","meaning":"우정, 공동체, 그리고 나누는 기쁨이 정서적 지지를 제공합니다.","advice":"함께 축하하고 진심으로 당신을 위해 나타나는 사람들을 기억하세요.","yesNoMeaning":"컵 3카드는 긍정 성향: 함께 축하하고 진심으로 당신을 위해 나타나는 사람이 누구인지 기억하세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-cups', 'ko', '{"name":"컵 4","meaning":"감정적 철수는 제공 가능한 선물을 알아차리기 어렵게 만듭니다.","advice":"비교를 잠시 멈추고 조용히 제공되고 있는 것을 다시 보세요.","yesNoMeaning":"컵 네는 ''아니오'' 쪽으로 기울어진다: 비교를 잠시 멈추고, 조용히 제공되고 있는 것을 다시 보라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-cups', 'ko', '{"name":"컵 5장","meaning":"손실은 의미 있는 것이 남아 있는 동안 흘러간 것에 주의를 가져오게 합니다.","advice":"실망을 존중한 후, 여전히 존재하는 지지를 향해 돌아서세요.","yesNoMeaning":"컵의 다섯은 아니라고 기운다: 실망을 존중한 후, 여전히 존재하는 지지로 향하라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-cups', 'ko', '{"name":"컵의 여섯","meaning":"기억, 순수함, 또는 익숙한 유대가 부드러운 온기와 함께 돌아옵니다.","advice":"과거의 친절을 환영하되, 다시 그곳에 살아야 한다고 가장하지 마세요.","yesNoMeaning":"컵 6번 카드는 예 쪽으로 기울어져 있습니다: 과거의 친절을 환영하되, 다시 그곳에서 살아야 한다고 가장하지 마세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-cups', 'ko', '{"name":"컵의 7","meaning":"많은 매력적인 가능성들이 비전과 환상의 차이를 흐리게 한다.","advice":"선택지를 좁히고 한 가지 꿈을 현실과 비교한 후에 결정하세요.","yesNoMeaning":"컵의 7은 아직 명확하지 않습니다: 선택을 좁히고 한 가지 꿈을 현실과 비교하여 검토한 후 헌신하세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-cups', 'ko', '{"name":"컵의 8","meaning":"한때 의미 있었던 상황이 더 이상 마음을 채우지 않습니다.","advice":"정직하게 떠나고, 이제 필요로 하는 더 깊은 성취를 향해 나아가세요.","yesNoMeaning":"컵의 여덟은 아니라고 기운다: 정직하게 떠나고 지금 필요한 더 깊은 충만으로 나아가라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-cups', 'ko', '{"name":"컵의 아홉","meaning":"만족과 감사는 진심 어린 소원이 가까이 느껴지게 합니다.","advice":"여기에 있는 것을 즐기고, 그 소망이 당신의 깊은 가치에도 부합하는지 물어보세요.","yesNoMeaning":"컵의 9: 예로 기울어짐 - 여기 있는 것을 즐기고, 소원이 당신의 깊은 가치에 부합하는지 물어보라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-cups', 'ko', '{"name":"컵의 열","meaning":"감정적 조화, 소속감, 그리고 지속적인 연결이 집안을 둘러싸고 있습니다.","advice":"기쁨을 지속 가능하고 함께 나눌 수 있는 유대를 돌보세요.","yesNoMeaning":"컵 10번 카드는 예 쪽으로 기울어져 있습니다: 기쁨을 지속적이고 공유 가능하게 만드는 유대감을 키우세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-cups', 'ko', '{"name":"컵의 기사","meaning":"다정한 메시지나 직관적인 발견이 감정적 개방을 초대합니다.","advice":"감정에 대해 호기심을 가지고, 추측보다는 성실하게 반응하세요.","yesNoMeaning":"컵의 시종은 조건적입니다: 감정에 대해 호기심을 유지하고 가정이 아니라 진심으로 반응하세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-cups', 'ko', '{"name":"컵의 기사","meaning":"낭만, 상상력, 또는 이상이 마음을 앞으로 이끕니다.","advice":"초대를 따르되, 약속이 이루어짐에 따라 한 발은 현실에 두세요.","yesNoMeaning":"컵의 기사은 긍정적인 의미를 기울입니다: 초대를 따르되 약속이 펼쳐질 때 한 발은 현실에 두세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-cups', 'ko', '{"name":"컵의 여왕","meaning":"깊은 공감과 직관은 진리를 위한 차분한 공간을 만든다.","advice":"돌봄을 건강하게 유지하는 경계를 지키면서도 동정심 있게 경청하세요.","yesNoMeaning":"컵의 여왕은 긍정 쪽으로 기울입니다: 돌봄을 건강하게 유지하는 경계를 지키면서 공감하게 들어주세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-cups', 'ko', '{"name":"컵의 왕","meaning":"감정적 성숙은 강한 감정을 억누르지 않고 안정시킵니다.","advice":"특히 다른 사람들이 반응적일 때에는 연민과 자기절제를 가지고 대응하세요.","yesNoMeaning":"컵의 왕은 긍정적인 의미를 기울입니다: 다른 사람들이 반응할 때에도 연민과 자기 통제를 가지고 대응하세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-swords', 'ko', '{"name":"소드의 에이스","meaning":"명확한 통찰이 혼란을 뚫고 새로운 진실을 드러냅니다.","advice":"문제를 명확히 밝히고 공정한 결정을 위해 명료함을 사용하세요.","yesNoMeaning":"검의 에이스는 긍정에 기울어 있습니다: 문제를 분명히 이름 짓고 공정한 결정을 위해 명료함을 사용하세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-swords', 'ko', '{"name":"검 두 장","meaning":"조심스러운 교착 상태가 선택을 지연시키지만, 선택은 영원히 미뤄질 수 없습니다.","advice":"눈가리개를 부드럽게 제거하고, 누락된 사실을 수집한 후 균형을 기준으로 결정한다.","yesNoMeaning":"소드의 투는 아직 명확하지 않음: 눈가리개를 부드럽게 제거하고, 누락된 사실을 수집한 후 균형에서 판단하라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-swords', 'ko', '{"name":"검 3","meaning":"고통스러운 진실, 이별, 또는 실망은 인정받기를 요구합니다.","advice":"감정이 당신을 통해 흐르게 하고, 상처를 영구적인 이야기로 만들지 마세요.","yesNoMeaning":"검 3카드는 부정 성향: 감정을 통해 흘려보내고 상처를 영구적인 이야기로 만들지 마세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-swords', 'ko', '{"name":"검 4","meaning":"압력이나 갈등 후에는 휴식과 정신적인 평온이 필요하다.","advice":"답변 전에 잠시 멈추기; 명확한 생각을 회복할 때 회복이 생산적입니다.","yesNoMeaning":"검 네는 ''아니오'' 쪽으로 기울어진다: 답하기 전에 잠시 멈추라; 회복은 명확한 사고를 회복할 때 생산적이다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-swords', 'ko', '{"name":"검의 오형","meaning":"갈등은 허망한 승리를 만들거나 신뢰를 손상시킬 수 있습니다.","advice":"승리보다 품위를 선택하고 너무 많은 비용이 드는 전략에서는 물러서세요.","yesNoMeaning":"검 다섯은 ''아니오'' 쪽으로 기울어진다: 승리보다 존엄을 선택하고, 너무 큰 대가를 치르는 전략에서 물러나라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-swords', 'ko', '{"name":"검의 여섯","meaning":"어려운 통과가 점차 안정된 상태로 이동합니다.","advice":"배운 것을 받아들이고, 도움을 받아들이며, 혼란에서 계속 벗어나세요.","yesNoMeaning":"소드 6번 카드는 예 쪽으로 기울어져 있습니다: 배운 것을 가져가고, 지원을 받아들이며, 혼란으로부터 계속 멀어지세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-swords', 'ko', '{"name":"검의 7","meaning":"전략, 비밀 유지 또는 회피는 길을 복잡하게 만듭니다.","advice":"영리하지만 투명하게 행동하세요; 신뢰를 배신하는 지름길은 문제로 돌아옵니다.","yesNoMeaning":"검의 7은 부정에 기울어 있습니다: 영리하지만 투명하게 행동하세요; 신뢰를 배반하는 지름길은 문제로 돌아옵니다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-swords', 'ko', '{"name":"검의 8","meaning":"두려움과 제한적인 믿음 때문에 가능한 선택지를 보기 어렵다.","advice":"스스로 갇혀 있다고 생각하는 마음에 의문을 제기하고 작은 자유로운 행동 하나를 취하세요.","yesNoMeaning":"검의 여덟은 아니라고 기운다: 자신이 갇혔다고 말하는 생각에 의문을 제기하고 작은 자유로운 행동 하나를 취하라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-swords', 'ko', '{"name":"검의 아홉","meaning":"불안은 어둠 속에서 위험을 확대하고 마음을 지치게 합니다.","advice":"두려움을 낮에 드러내고, 지원을 구하며, 사실과 상상된 결과를 구분하세요.","yesNoMeaning":"검의 9: 아니오로 기울어짐 - 두려움을 낮의 빛으로 가져오고, 지원을 구하며, 사실과 상상된 결과를 분리하라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-swords', 'ko', '{"name":"검의 열","meaning":"고통스러운 순환이 최종 한계에 도달하여 변화 없이 계속될 수 없습니다.","advice":"끝을 받아들이고, 회복을 보호하며, 다른 시작이 나타나도록 허용하세요.","yesNoMeaning":"검 10카드는 부정 성향: 끝을 받아들이고 회복을 보호하며 새로운 시작이 나타나도록 허용하세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-swords', 'ko', '{"name":"검의 기사","meaning":"호기심 경보는 사실을 찾고, 질문하며, 변화를 관찰합니다.","advice":"모든 신호에 반응하기보다는 신중하게 조사하고 정확하게 말하세요.","yesNoMeaning":"검의 시종은 조건적입니다: 신중하게 조사하고 모든 신호에 반응하기보다는 정확하게 말하세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-swords', 'ko', '{"name":"검의 기사","meaning":"집중된 지성은 빠르게 움직이며 장애물을 직접적으로 맞섭니다.","advice":"용기를 가지고 나아가되, 확신이 놓칠 수 있는 것을 들을 수 있을 만큼 천천히 움직이세요.","yesNoMeaning":"검의 기사: 조건부 - 용기를 가지고 나아가지만, 확신이 놓칠 수 있는 것을 들을 수 있을 만큼 천천히 진행하라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-swords', 'ko', '{"name":"검의 여왕","meaning":"명확한 인식과 정직한 경계가 혼란을 없애줍니다.","advice":"연민과 함께 진실을 말하고, 경험이 당신을 단단하게 만들지 않고, 다듬도록 하세요.","yesNoMeaning":"검의 여왕은 긍정에 기울어 있습니다: 진실을 연민과 함께 말하고, 경험이 당신을 단단하게 하기보다 날카롭게 하도록 하세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-swords', 'ko', '{"name":"검의 왕","meaning":"이성과 공정함, 그리고 규율 있는 판단이 중요한 결정을 이끕니다.","advice":"증거를 사용하고, 기준을 정의하며, 개인적 편견을 평결에서 제외하세요.","yesNoMeaning":"검의 왕은 긍정적인 의미를 기울입니다: 증거를 사용하고 기준을 정의하며, 개인적인 편견을 판결에 개입시키지 마세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ace-of-pentacles', 'ko', '{"name":"펜타클의 에이스","meaning":"실질적인 기회는 번영, 일, 또는 웰빙의 씨앗을 제공합니다.","advice":"기회를 실질적인 계획에 기반하고 꾸준히 돌보세요.","yesNoMeaning":"펜타클의 에이스는 긍정에 기울어 있습니다: 기회를 실질적인 계획에 기반하고 꾸준히 돌보세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('two-of-pentacles', 'ko', '{"name":"펜타클 2","meaning":"여러 가지 우선순위가 동시에 움직이며 유연한 균형을 요구합니다.","advice":"리듬을 조정하고, 필수적인 것을 보호하며, 감당할 수 있는 것 이상을 약속하지 마세요.","yesNoMeaning":"펜타클의 투는 조건적임: 리듬을 조정하고, 필수적인 것을 보호하며, 감당할 수 있는 것 이상을 약속하지 마라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('three-of-pentacles', 'ko', '{"name":"펜타클 3","meaning":"기술은 협업, 피드백, 그리고 세심한 제작을 통해 성장합니다.","advice":"당신의 힘을 기여하고, 전문성을 존중하며, 공동 표준에 맞춰 구축하세요.","yesNoMeaning":"펜타클 3카드는 긍정 성향: 당신의 힘을 기여하고, 전문성을 존중하며, 공동 기준에 맞추어 구축하세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('four-of-pentacles', 'ko', '{"name":"펜타클 4","meaning":"안전을 지나치게 붙잡는 것은 자원을 보존할 수 있지만 건강한 흐름을 제한할 수 있습니다.","advice":"두려움이 모든 결정을 내리게 하지 않고 중요한 것을 보호하세요.","yesNoMeaning":"펜타클 네는 조건부로 유지된다: 중요한 것을 보호하되, 두려움이 모든 결정을 내리게 하지 말라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('five-of-pentacles', 'ko', '{"name":"펜타클의 오형","meaning":"물질적 압박이나 배제는 걱정과 부족감의 감각을 만들어낸다.","advice":"실질적인 도움을 요청하고, 고난 때문에 쉽게 간과하게 된 문을 주목하라.","yesNoMeaning":"펜타클 다섯은 ''아니오'' 쪽으로 기울어진다: 실질적인 도움을 요청하고, 어려움 때문에 쉽게 간과하게 되는 문을 주목하라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('six-of-pentacles', 'ko', '{"name":"펜타클의 여섯","meaning":"자원이 교환되며, 관대함, 권력, 공정성에 대한 질문을 제기합니다.","advice":"명확한 조건으로 주거나 받아서 지원이 양쪽 모두의 존엄을 지킬 수 있게 하세요.","yesNoMeaning":"펜타클 6번 카드는 예 쪽으로 기울어져 있습니다: 지원이 양쪽 모두의 존엄성을 지킬 수 있도록 명확한 조건으로 주거나 받으세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('seven-of-pentacles', 'ko', '{"name":"펜타클의 7","meaning":"인내심 있는 투자는 다음 노력을 시작하기 전에 평가 지점에 도달합니다.","advice":"자라는 것을 검토하고, 방법을 개선하며, 가치 있는 결과가 나타날 시간을 허용하십시오.","yesNoMeaning":"펜타클의 7은 조건부로 남아 있습니다: 자라고 있는 것을 검토하고, 방법을 개선하며, 가치 있는 결과에 시간을 주세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('eight-of-pentacles', 'ko', '{"name":"펜타클의 8","meaning":"집중된 반복은 숙련과 신뢰할 수 있는 결과를 발전시킵니다.","advice":"필수 기술을 연습하고, 교정을 환영하며, 품질을 축적하세요.","yesNoMeaning":"펜타클의 여덟은 그렇다고 기운다: 필수 기술을 연습하고, 교정을 받아들이며, 질을 쌓게 하라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('nine-of-pentacles', 'ko', '{"name":"펜타클의 아홉","meaning":"자기 의지와 길러진 안락함은 규율 있는 진보를 반영한다.","advice":"당신이 쌓아 올린 것을 즐기고, 감사와 연결된 독립성을 유지하세요.","yesNoMeaning":"펜타클의 9: 예로 기울어짐 - 당신이 쌓아 올린 것을 즐기고, 독립성을 감사와 연결하여 유지하라."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('ten-of-pentacles', 'ko', '{"name":"펜타클의 열","meaning":"장기적인 보안은 유산, 가족, 공유된 기반을 통해 성장합니다.","advice":"즉각적인 승리를 넘어 계획하고 시간이 지나면서 다른 사람들을 지원할 수 있는 것을 보호하세요.","yesNoMeaning":"펜타클 10카드는 긍정 성향: 즉각적인 승리 너머를 계획하고 시간이 지나도 다른 사람을 지원할 수 있는 것을 보호하세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('page-of-pentacles', 'ko', '{"name":"펜타클의 기사","meaning":"실질적인 메시지는 학습, 계획, 또는 현실적인 새로운 사업을 초대합니다.","advice":"기본을 배우고, 다음 과제를 정의하며, 꾸준한 작업을 통해 아이디어를 증명하세요.","yesNoMeaning":"펜타클의 시종은 긍정 쪽으로 기울입니다: 기본을 배우고, 다음 과제를 정의하며, 꾸준한 노력으로 아이디어를 증명하세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('knight-of-pentacles', 'ko', '{"name":"펜타클의 기사","meaning":"신뢰할 수 있는 노력은 천천히 진행되지만 거의 과제를 포기하지 않는다.","advice":"루틴을 정직하고 일관되게 유지하십시오; 흥분보다는 진전이 더 중요합니다.","yesNoMeaning":"펜타클의 기사: 예로 기울어짐 - 일상을 정직하고 꾸준하게 유지하라; 진전이 흥분보다 중요하다."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('queen-of-pentacles', 'ko', '{"name":"펜타클의 여왕","meaning":"지략 있는 돌봄은 편안함, 건강, 실질적인 풍요를 창출합니다.","advice":"자신에게 지속 가능한 방식으로 사람과 계획을 돌보세요.","yesNoMeaning":"펜타클의 여왕은 긍정에 기울어 있습니다: 지속 가능하게 사람과 계획을 돌보세요."}');
INSERT INTO card_translations (card_id, locale, payload) VALUES ('king-of-pentacles', 'ko', '{"name":"펜타클의 왕","meaning":"물질적인 리더십은 경험을 안정적이고 관대한 관리로 변환한다.","advice":"장기적인 선택을 하고 성공을 책임감 있게 사용하라.","yesNoMeaning":"펜타클의 왕은 긍정적인 의미를 기울입니다: 장기적인 선택을 하고 성공을 책임감 있게 사용하세요."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aries', 'ko', '{"name":"양자리","dateRange":"3월 21일 – 4월 19일","rulingPlanet":"화성","summary":"대담한 시작과 직설적인 행동은 계획을 추진력으로 바꾸는 불꽃을 지닌 양자리를 정의합니다.","originStory":"양자리는 그리스 신화에서 프릭수스를 구한 황금 양과 관련이 있습니다. 그 양의 털은 나중에 제이슨과 아르고 원정대의 상이 되었으며, 이 별자리는 용기, 구조, 그리고 첫 번째 용감한 발걸음의 상징으로 남게 되었습니다.","traits":["용감한","활기찬","독립적","직설적"],"strengths":["주도권","자신감","회복력"],"challenges":["조급함","충동적임","지속할 수 있는 것보다 더 빨리 시작"],"compatibleSigns":["사자자리","궁수자리","쌍둥이자리"],"reflectionPrompt":"용감한 시작 하나를 선택하고 성장할 수 있도록 충분한 인내를 주세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'day', 'ko', '{"overview":"오늘은 하나의 명확하고 의도적인 한 걸음을 지지합니다. 양자리는 불의 에너지를 통해 움직입니다. 대담한 시작과 직접적인 행동이 양을 정의하며, 그 불꽃은 의도를 추진력으로 바꿉니다.","love":"오늘 사랑에서는 추측보다 현재에 집중하세요. 주도권, 자신감, 회복력을 갖춘 당신의 선물은 꾸미지 않아도 관계를 맺는 데 도움을 줄 수 있습니다.","career":"직장에서, 새로운 동력을 쫓기 전에 가장 의미 있는 업무를 완료하세요. 용기 있고, 활기차고, 독립적이며, 직설적인 태도를 도구로 사용하고, 한꺼번에 모두 만족시켜야 하는 기대치로 보지 마세요.","finance":"오늘의 돈 관련 선택은 간단하고 현실적으로 유지하세요. 조급함, 충동, 지속할 수 있는 속도보다 빨리 시작하는 경향이 실질적인 결정에 영향을 미치기 시작할 때 이를 알아차리세요.","wellbeing":"작은 휴식은 당신의 에너지를 재설정할 수 있습니다. 하나의 용감한 시작을 선택하고 그것이 성장할 수 있도록 충분한 인내를 주세요.","guidance":"하루가 끝나기 전에 기억하세요: 용기 있는 시작 하나를 선택하고 그것이 성장할 충분한 인내를 주세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'week', 'ko', '{"overview":"이번 주는 극적인 순간 하나보다는 꾸준한 선택을 통해 전개됩니다. 양자리는 불의 에너지를 통해 나아갑니다. 대담한 시작과 직접적인 행동이 양자리의 특징이며, 그 불꽃은 의도를 추진력으로 바꿉니다.","love":"관계는 정직함과 따뜻함 모두를 위한 여지를 만드는 대화에서 혜택을 얻습니다. 당신의 주도력, 자신감, 회복력의 능력은 연기하지 않고도 연결하는 데 도움을 줄 수 있습니다.","career":"당신의 최고의 직업적 성장은 우선순위를 선택하고 그것을 위한 시간을 지키는 데서 옵니다. 용기 있고, 활기차고, 독립적이며, 직설적인 태도를 도구로 사용하세요. 한 번에 모두 충족시켜야 할 기대가 아니라 도구로 활용하세요.","finance":"더 큰 지출을 하기 전에 자신의 지출 패턴을 검토하세요. 인내심 부족, 충동적 행동, 지속할 수 있는 것보다 빨리 시작하는 경향이 실질적인 결정에 영향을 미치기 시작할 때를 주의하세요.","wellbeing":"주중 내내 진정한 회복과 함께 움직임의 균형을 맞추세요. 하나의 용감한 시작을 선택하고 그것이 자랄 수 있도록 충분한 인내를 주세요.","guidance":"이번 주를 안내할 질문으로 삼으세요: 하나의 용감한 시작을 선택하고 성장할 수 있도록 충분한 인내를 주세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aries', 'year', 'ko', '{"overview":"올해는 정체성, 목적, 그리고 에너지를 사용하는 방식에 대한 인내심 있는 성장을 초대합니다. 양자리는 불의 에너지를 통해 움직입니다. 대담한 시작과 직설적인 행동은 양자리를 정의하며, 그 불꽃은 의도를 추진력으로 바꿉니다.","love":"사랑은 일관성을 실천하고 연결이 인간의 속도로 발전하도록 허용할 때 깊어진다. 주도권, 자신감, 회복력의 재능은 연기하지 않고도 당신이 연결될 수 있도록 도와준다.","career":"장기적인 일은 야망이 지속할 수 있는 구조와 결합될 때 더 강해집니다. 용감하고, 에너지가 넘치며, 독립적이고, 직설적인 태도를 도구로 사용하고, 한 번에 모두 충족해야 할 기대치로 사용하지 마세요.","finance":"완벽한 예측 대신 반복 가능한 습관을 통해 재정적 자신감을 쌓으세요. 조급함, 충동성, 지속할 수 있는 것보다 빠르게 시작하는 것이 실질적인 결정에 영향을 미치기 시작할 때 이를 알아차리세요.","wellbeing":"웰빙을 인생을 마친 후 받는 보상이 아니라, 당신이 만들어가는 삶의 기초로 여기세요. 하나의 용기 있는 시작을 선택하고 그것이 성장할 수 있도록 충분한 인내를 주세요.","guidance":"일년 내내 이 나침반으로 돌아가라: 하나의 용감한 시작을 선택하고 그것이 성장할 수 있도록 충분한 인내를 주라."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('taurus', 'ko', '{"name":"황소자리","dateRange":"4월 20일 – 5월 20일","rulingPlanet":"금성","summary":"꾸준하고, 감각적이며, 현실적인 황소자리는 인내와 세심함을 통해 지속적인 가치를 쌓습니다.","originStory":"황소자리는 제우스가 유로파를 바다 건너 데려가기 위해 웅장한 흰 황소의 모습을 취한 것을 떠올리게 합니다. 이 이미지는 아름다움, 번식력, 지상의 풍요로움, 그리고 차분한 끈기를 통해 표현되는 힘과 연관되었습니다.","traits":["근거 있는","충직한","인내심 있는","관능적인"],"strengths":["신뢰성","실용적 지혜","헌신"],"challenges":["고집","변화에 대한 저항","너무 오래 붙들기"],"compatibleSigns":["처녀자리","염소자리","게자리"],"reflectionPrompt":"편안함을 영원함으로 착각하지 않고 중요한 것을 보호하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'day', 'ko', '{"overview":"오늘은 명확하고 의도적인 한 걸음을 내딛기에 좋은 날입니다. 황소자리는 흙의 에너지를 통해 움직입니다. 안정적이고 감각적이며 현실적인 황소는 인내와 세심함을 통해 지속적인 가치를 쌓습니다.","love":"오늘 사랑에서는 추측보다 현재에 집중하세요. 신뢰할 수 있음, 실용적인 지혜, 헌신이라는 당신의 선물이 연기하지 않고도 연결될 수 있도록 도와줄 수 있습니다.","career":"직장에서, 새로운 동력을 쫓기 전에 가장 의미 있는 업무를 완료하세요. 현실적이고, 충성스럽고, 인내심 있으며, 감각적인 태도를 도구로 사용하고, 한꺼번에 모두 만족시켜야 하는 기대치로 보지 마세요.","finance":"오늘의 금전적 선택은 단순하고 현실적으로 유지하세요. 고집, 변화에 대한 저항, 너무 오래 붙잡고 있는 것이 실질적인 결정에 영향을 미치기 시작할 때 알아차리세요.","wellbeing":"작은 휴식은 당신의 에너지를 다시 설정할 수 있습니다. 편안함을 영원함으로 착각하지 말고 중요한 것을 지키세요.","guidance":"하루가 끝나기 전에 기억하세요: 편안함을 영속으로 착각하지 말고 중요한 것을 지키세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'week', 'ko', '{"overview":"이번 주는 한 번의 극적인 순간보다는 꾸준한 선택을 통해 전개됩니다. 황소자리는 땅의 에너지를 통해 움직입니다. 안정적이고 감각적이며 땅에 뿌리를 둔 황소자리는 인내와 관심을 통해 지속적인 가치를 구축합니다.","love":"관계는 정직함과 따뜻함을 모두 수용할 수 있는 대화에서 혜택을 받습니다. 당신의 신뢰성, 실용적인 지혜, 헌신이라는 선물은 연기하지 않고도 연결할 수 있도록 도와줄 수 있습니다.","career":"당신의 최고의 직업적 성장은 우선순위를 선택하고 그것을 위해 시간을 확보함으로써 이루어집니다. 현실적이고, 충실하고, 인내심 있고, 감각적인 것을 도구로 사용하세요. 한꺼번에 모두 충족해야 하는 기대가 아니라 도구로 사용하세요.","finance":"더 큰 금전적 결정을 내리기 전에 지출 패턴을 검토하세요. 완고함, 변화에 대한 저항, 너무 오래 매달리는 것이 실제적인 결정에 영향을 미치기 시작할 때를 알아차리세요.","wellbeing":"일주일 내내 진정한 회복과 함께 움직임의 균형을 유지하세요. 편안함을 영구적인 것으로 착각하지 말고 중요한 것을 보호하세요.","guidance":"이번 주에는 이 질문이 길잡이가 되게 하세요: 편안함을 영속성으로 착각하지 말고 중요한 것을 보호하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('taurus', 'year', 'ko', '{"overview":"올해는 정체성, 목적, 그리고 에너지를 사용하는 방식에 대한 인내심 있는 성장을 초대합니다. 황소자리는 흙의 에너지를 통과합니다. 안정적이고, 감각적이며, 현실적인 황소자리는 인내와 관심을 통해 지속적인 가치를 쌓습니다.","love":"사랑은 일관성을 실천하고 인간의 속도로 연결이 진화하도록 허용할 때 깊어집니다. 신뢰할 수 있는 선물, 실용적인 지혜, 헌신은 연기하지 않고도 연결될 수 있도록 도와줍니다.","career":"장기적인 일은 야망이 지속할 수 있는 구조와 결합될 때 더 강해집니다. 현실적이고, 충실하며, 인내심 있고, 감각적인 것을 도구로 사용하고, 한 번에 모두 충족해야 하는 기대치로 사용하지 마십시오.","finance":"반복 가능한 습관을 통해 재정적 자신감을 구축하고 완벽한 예측을 따르지 마십시오. 고집, 변화에 대한 저항, 너무 오래 붙잡고 있는 것이 실질적인 결정에 영향을 미치기 시작할 때 이를 주의하십시오.","wellbeing":"웰빙을 삶을 완성한 후 얻는 보상이 아니라, 당신이 만들어가는 삶의 기반으로 여기세요. 안락함을 영속성과 혼동하지 말고 중요한 것을 보호하세요.","guidance":"일 년 내내 이 나침반으로 돌아가세요: 편안함을 영구적인 것으로 착각하지 말고 중요한 것을 보호하세요."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('gemini', 'ko', '{"name":"쌍둥이자리","dateRange":"5월 21일 – 6월 20일","rulingPlanet":"수성","summary":"호기심과 연결은 쌍둥이를 안내하며, 아이디어를 모으고 이야기의 여러 면을 드러낸다.","originStory":"쌍둥이자리(Gemini)는 별자리를 나뉘지 않고 불멸을 나눈 불가분의 쌍둥이 카스토르와 폴룩스를 나타냅니다. 이 별자리는 동료애, 이중 관점, 소통, 그리고 세계 사이의 이동이라는 주제를 담고 있습니다.","traits":["호기심 있는","적응력 있는","표현력이 풍부한","재치 있음"],"strengths":["커뮤니케이션","다재다능함","빠르게 배우기"],"challenges":["불안","분산된 집중","과도한 생각"],"compatibleSigns":["천칭자리","물병자리","양자리"],"reflectionPrompt":"호기심이 문을 열게 두고, 발견한 것을 이해할 수 있을 만큼 충분히 머무르세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'day', 'ko', '{"overview":"오늘은 한 가지 분명하고 의도적인 단계를 지지합니다. 쌍둥이자리는 공기의 에너지를 통과합니다. 호기심과 연결이 쌍둥이를 이끌며, 아이디어를 모으고 이야기의 여러 면을 드러냅니다.","love":"오늘 사랑에서는 추측보다 현재에 집중하세요. 소통, 다재다능, 빠른 학습이라는 당신의 선물은 연기하지 않고도 연결될 수 있게 도와줍니다.","career":"직장에서, 새로운 동력을 쫓기 전에 가장 의미 있는 업무를 완료하세요. 호기심 많고, 적응력이 있으며, 표현력이 풍부하고, 재치 있는 태도를 도구로 사용하고, 한꺼번에 모두 만족시켜야 하는 기대치로 보지 마세요.","finance":"오늘의 돈 관련 선택을 단순하고 현실적으로 유지하세요. 안절부절 못함, 집중력 흩어짐, 과도한 생각이 실질적인 결정에 영향을 미치기 시작할 때 이를 주목하세요.","wellbeing":"작은 휴식은 당신의 에너지를 재설정할 수 있습니다. 호기심이 문을 열게 하고, 발견한 것을 이해할 수 있을 만큼 충분히 머무르세요.","guidance":"하루가 끝나기 전에 기억하세요: 호기심이 문을 열게 하고, 발견한 것을 이해할 충분한 시간 동안 머물러 보세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'week', 'ko', '{"overview":"이번 주는 한 번의 극적인 순간보다 꾸준한 선택을 통해 전개됩니다. 쌍둥이자리는 공기의 에너지를 통해 움직입니다. 호기심과 연결이 쌍둥이를 안내하며, 아이디어를 모으고 이야기의 여러 면을 드러냅니다.","love":"관계는 정직함과 따뜻함을 모두 수용할 수 있는 대화에서 혜택을 받습니다. 당신의 의사소통 능력, 다재다능함, 빠르게 배우는 능력은 공연하지 않고도 관계를 연결하는 데 도움이 될 수 있습니다.","career":"당신의 최고의 전문적 성장은 우선 순위를 정하고 그것을 위한 시간을 지키는 데서 옵니다. 호기심 많고, 적응력이 뛰어나며, 표현력이 풍부하고, 재치 있는 것을 도구로 사용하세요. 한 번에 모두 충족해야 할 기대치로 여기지 마세요.","finance":"더 큰 금전적 결정을 내리기 전에 지출 패턴을 검토하세요. 안절부절못함, 집중력 분산, 과도한 생각이 실제적인 결정에 영향을 미치기 시작할 때를 알아차리세요.","wellbeing":"일주일 동안 진정한 회복과 함께 운동의 균형을 유지하세요. 호기심이 문을 열게 하고, 그 후 발견한 것을 이해할 수 있을 만큼 충분히 머무르세요.","guidance":"이번 주를 안내할 질문으로 삼으세요: 호기심이 문을 열게 하고, 발견한 것을 이해할 수 있을 만큼 충분히 머무르세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('gemini', 'year', 'ko', '{"overview":"올해는 정체성, 목적, 그리고 당신이 에너지를 사용하는 방식에 대한 인내심 있는 성장을 초대합니다. 쌍둥이는 공기 에너지를 통해 움직입니다. 호기심과 연결이 쌍둥이를 이끌며, 그들은 아이디어를 모으고 이야기의 한 가지 이상을 드러냅니다.","love":"일관성을 실천하고 인간적인 속도로 관계가 발전하도록 허용할 때 사랑은 깊어집니다. 의사소통 능력, 다재다능함, 빠른 학습 능력이라는 당신의 재능은 공연하지 않고도 관계를 맺는 데 도움이 될 수 있습니다.","career":"야망을 지속할 수 있는 구조와 결합할 때 장기적인 노력은 더 강해집니다. 호기심 많고, 적응력이 있으며, 표현력이 풍부하고, 재치 있는 것을 한 번에 모두 충족해야 하는 기대가 아니라 도구로 사용하세요.","finance":"완벽한 예측 대신 반복 가능한 습관을 통해 금융 신뢰를 쌓으세요. 불안, 산만한 집중, 과도한 생각이 실질적인 결정에 영향을 미치기 시작할 때 이를 알아차리세요.","wellbeing":"복지를 당신이 구축하고 있는 삶의 완료 후 보상이 아니라 기초로 다루세요. 호기심이 문을 열게 두고, 발견한 것을 이해할 수 있을 만큼 충분히 머무르세요.","guidance":"일 년 내내 이 나침반으로 돌아가라: 호기심이 문을 열게 하고, 그런 다음 발견한 것을 이해할 수 있을 만큼 충분히 오래 머물러라."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('cancer', 'ko', '{"name":"게자리","dateRange":"6월 21일 – 7월 22일","rulingPlanet":"달","summary":"보호적이고 직관적인 게자리(Crab)는 기억, 감정, 집을 존중하며 소속감을 창조합니다.","originStory":"게자리는 게 카르키노스와 관련이 있으며, 헤라클레스가 히드라와 싸우는 동안 충성을 보여 별들 사이에 놓였습니다. 게의 등껍질과 달의 지배는 보호, 감정의 흐름, 그리고 내면의 사람들에게 대한 헌신을 반영합니다.","traits":["직관적인","배려","보호하는","상상력이 풍부한"],"strengths":["공감","충성","감정적 통찰"],"challenges":["변덕","방어 뒤로 물러나기","사적인 문제로 받아들이기"],"compatibleSigns":["전갈자리","물고기자리","황소자리"],"reflectionPrompt":"정직한 연결을 위한 문을 열어 두면서 내면 세계를 돌보세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'day', 'ko', '{"overview":"오늘은 하나의 명확하고 의도적인 한 걸음을 지지합니다. 게자리는 물의 에너지를 통해 움직입니다. 보호적이며 직관적인 게는 기억, 감정, 집을 존중함으로써 소속감을 만듭니다.","love":"오늘 사랑에서는 추측보다 현재에 집중하세요. 공감, 충성심, 감정적 통찰력이라는 당신의 선물은 연기하지 않고도 연결될 수 있게 도와줍니다.","career":"직장에서, 새로운 동력을 쫓기 전에 가장 의미 있는 업무를 완료하세요. 직관적이고, 배려하며, 보호적이고, 상상력이 풍부한 것을 도구로 사용하고 동시에 모두 만족시켜야 하는 기대가 아니라고 생각하세요.","finance":"오늘의 돈 관련 선택을 단순하고 현실적으로 유지하세요. 기분 변화, 방어적으로 물러서기, 개인적으로 받아들이기가 실질적인 결정에 영향을 미치기 시작할 때 이를 주목하세요.","wellbeing":"작은 휴식은 당신의 에너지를 재설정할 수 있습니다. 솔직한 연결의 문을 열어두면서 내면 세계를 돌보세요.","guidance":"하루가 끝나기 전에 기억하세요: 내면 세계를 돌보면서 솔직한 연결을 위한 문은 열어 두세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'week', 'ko', '{"overview":"이번 주는 한 번의 극적인 순간보다는 꾸준한 선택을 통해 전개됩니다. 게자리는 물의 에너지를 통해 움직입니다. 보호적이고 직관적인 게는 기억, 감정, 집을 존중함으로써 소속감을 만듭니다.","love":"관계는 정직함과 따뜻함을 모두 수용할 수 있는 대화에서 혜택을 받습니다. 공감, 충성심, 감정적 통찰력이라는 당신의 선물은 연기하지 않고도 연결할 수 있도록 도와줄 수 있습니다.","career":"당신의 최고의 직업적 성장은 우선순위를 선택하고 그것을 위해 시간을 확보함으로써 이루어집니다. 직관적이고, 배려하며, 보호적이고, 상상력이 풍부한 것을 도구로 사용하세요. 한꺼번에 모두 충족해야 하는 기대가 아니라 도구로 사용하세요.","finance":"더 큰 지출을 하기 전에 자신의 소비 패턴을 검토하세요. 기분 변화, 방어 태세로 물러나기, 사소한 일에 개인적으로 반응하는 것이 실질적인 결정에 영향을 미치기 시작할 때를 주의하세요.","wellbeing":"주간 내내 진정한 회복과 함께 균형 잡힌 움직임을 유지하세요. 솔직한 연결에 대한 문을 열어 두면서 내면의 세계도 돌보세요.","guidance":"이번 주를 안내할 질문으로 삼으세요: 정직한 연결을 위한 문을 열어두면서 내면 세계를 돌보세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('cancer', 'year', 'ko', '{"overview":"올해는 정체성, 목적, 그리고 에너지를 사용하는 방식에 대한 인내심 있는 성장을 초대합니다. 게자리는 물의 에너지를 통해 움직입니다. 보호적이고 직관적인 게자리는 기억, 감정, 집을 존중함으로써 소속감을 만들어냅니다.","love":"사랑은 일관성을 실천하고 연결이 인간의 속도로 발전하도록 허용할 때 깊어진다. 공감, 충성, 감정적 통찰의 재능은 연기하지 않고도 당신이 연결될 수 있도록 도와준다.","career":"장기적인 일은 야망이 지속할 수 있는 구조와 결합될 때 더 강해집니다. 직관적이고, 배려하며, 보호적이고, 상상력 있는 것을 도구로 사용하고 한 번에 모두 충족해야 하는 기대치로 사용하지 마십시오.","finance":"완벽한 예측 대신 반복 가능한 습관을 통해 재정적 자신감을 쌓으세요. 변덕스러움, 방어 뒤로 물러남, 일을 개인적으로 받아들이는 것이 실질적인 결정에 영향을 미치기 시작할 때 이를 알아차리세요.","wellbeing":"복지를 당신이 쌓아가는 삶의 기초로 삼아라, 그것을 다 끝낸 후 얻는 보상으로 여기지 마라. 정직한 연결을 위한 문을 열어두면서 당신의 내면 세계를 돌보라.","guidance":"일년 내내 이 나침반으로 돌아가라: 정직한 연결을 위한 문을 열어두면서 내면의 세계를 보살피라."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('leo', 'ko', '{"name":"사자자리","dateRange":"7월 23일 – 8월 22일","rulingPlanet":"태양","summary":"따뜻함, 창의성, 그리고 관대한 자기 표현은 사자를 자연스러운 빛의 근원으로 만듭니다.","originStory":"사자자리는 거의 무적에 가까운 생물인 네메아의 사자와 관련이 있으며, 헤라클레스의 첫 번째 과업에서 물리쳐졌습니다. 하늘로 올라간 이 사자는 용기, 주권적 존재감, 태양의 창조적 힘의 상징이 되었습니다.","traits":["따뜻함","창의적인","관대한","자신감 있는"],"strengths":["리더십","충성","진심 어린 표현"],"challenges":["자존심","인정을 필요로 함","좌절을 과장함"],"compatibleSigns":["양자리","궁수자리","천칭자리"],"reflectionPrompt":"빛을 너그럽게 나누고 다른 사람들이 당신 곁에서 빛나도록 하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'day', 'ko', '{"overview":"오늘은 한 가지 분명하고 의도적인 단계를 지지합니다. 사자자리는 불의 에너지를 통과합니다. 따뜻함, 창의성, 관대한 자기 표현이 사자를 자연스러운 빛의 원천으로 만듭니다.","love":"오늘 사랑에서는 추측보다 현재에 집중하세요. 리더십, 충성심, 진심 어린 표현을 갖춘 당신의 선물은 꾸미지 않아도 관계를 맺는 데 도움을 줄 수 있습니다.","career":"직장에서 새로운 추진력을 쫓기 전에 가장 의미 있는 과제를 먼저 완수하세요. 따뜻함, 창의성, 너그러움, 자신감을 도구로 사용하고, 한 번에 모두 만족시켜야 하는 기대치로 사용하지 마세요.","finance":"오늘의 돈 관련 선택을 단순하고 현실적으로 유지하세요. 자부심, 인정받고자 하는 욕구, 좌절을 극적으로 바라보는 것이 실질적인 결정에 영향을 미치기 시작할 때 이를 주목하세요.","wellbeing":"작은 휴식은 당신의 에너지를 다시 설정할 수 있습니다. 당신의 빛을 아낌없이 나누고 다른 사람들이 당신 곁에서 빛나게 하세요.","guidance":"하루가 끝나기 전에 기억하세요: 당신의 빛을 아낌없이 나누고 다른 사람들이 당신 곁에서 빛나게 하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'week', 'ko', '{"overview":"이번 주는 한 번의 극적인 순간보다 꾸준한 선택을 통해 전개됩니다. 사자자리는 불의 에너지를 통해 움직입니다. 따뜻함, 창의성, 관대한 자기 표현이 사자를 자연스러운 빛의 원천으로 만듭니다.","love":"관계는 정직함과 따뜻함 모두를 위한 여지를 만드는 대화에서 혜택을 얻습니다. 당신의 리더십, 충성심, 진심 어린 표현 능력은 연기하지 않고도 연결하는 데 도움을 줄 수 있습니다.","career":"가장 뛰어난 직업적 성장은 우선순위를 선택하고 그 시간을 지키는 데서 옵니다. 따뜻하고, 창의적이며, 관대하고, 자신감 있는 것을 도구로 사용하세요. 동시에 모두를 충족시켜야 하는 기대치로 생각하지 마세요.","finance":"더 큰 지출을 하기 전에 자신의 지출 패턴을 검토하세요. 자부심, 인정받고자 하는 욕구, 좌절을 과장하는 태도가 실질적인 결정에 영향을 미치기 시작할 때를 주목하세요.","wellbeing":"일주일 내내 진정한 회복과 함께 움직임의 균형을 맞추세요. 당신의 빛을 아낌없이 나누고 다른 사람들이 당신 곁에서 빛나도록 하세요.","guidance":"이번 주에는 이 질문이 길잡이가 되게 하세요: 당신의 빛을 넉넉히 나누고 다른 사람들이 당신 곁에서 빛날 수 있게 하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('leo', 'year', 'ko', '{"overview":"올해는 정체성, 목적, 그리고 에너지를 사용하는 방식에 대해 인내심 있는 성장을 초대합니다. 사자는 불의 에너지를 통해 움직입니다. 따뜻함, 창의성, 그리고 관대한 자기 표현은 사자를 자연스러운 빛의 원천으로 만듭니다.","love":"사랑은 일관성을 실천하고 인간의 속도로 연결이 진화하도록 허용할 때 깊어집니다. 당신의 리더십, 충성심, 진심 어린 표현의 선물은 연기하지 않고도 연결될 수 있게 도와줍니다.","career":"장기적인 일은 야망이 지속할 수 있는 구조와 결합될 때 더 강해집니다. 따뜻함, 창의성, 관대함, 자신감을 한꺼번에 충족시켜야 하는 기대가 아니라 도구로 사용하세요.","finance":"완벽한 예측 대신 반복 가능한 습관을 통해 금융적 자신감을 쌓으세요. 자부심, 인정받고자 하는 욕구, 좌절을 과장하는 마음이 실질적인 결정에 영향을 미치기 시작할 때 이를 알아차리세요.","wellbeing":"웰빙을 삶을 완성한 후의 보상으로 여기지 말고, 당신이 세워가는 삶의 기반으로 여기세요. 당신의 빛을 아낌없이 나누고 다른 사람들이 당신 곁에서 빛나도록 하세요.","guidance":"일 년 내내 이 나침반으로 돌아오세요: 당신의 빛을 넉넉히 나누고 다른 사람들이 당신 곁에서 빛날 수 있도록 하세요."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('virgo', 'ko', '{"name":"처녀자리","dateRange":"8월 23일 – 9월 22일","rulingPlanet":"수성","summary":"분별력과 봉사는 처녀자리를 인도하며, 세심한 관찰을 실용적인 개선으로 바꿉니다.","originStory":"처녀자리는 종종 정의의 처녀 아스트라이아와 연결되는데, 그녀는 다른 신들이 떠난 후에도 인류와 함께 남았습니다. 그녀가 들고 있는 밀 이삭은 이 별자리를 수확, 기술, 순수한 의도, 생명을 유지하는 것을 돌보는 것과 연결시킵니다.","traits":["관찰력 있는","실용적인","사려 깊은","정확한"],"strengths":["분석","장인정신","도움이 되는 봉사"],"challenges":["완벽주의","자기 비판","세부사항에 대한 걱정"],"compatibleSigns":["황소자리","염소자리","게자리"],"reflectionPrompt":"할 수 있는 것을 향상시키고, 완벽하지 않더라도 좋은 작업이 완성되도록 두세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'day', 'ko', '{"overview":"오늘은 명확하고 의도적인 한 걸음을 지지합니다. 처녀자리는 땅의 에너지를 통과합니다. 분별력과 봉사는 소녀를 인도하며, 세심한 관찰을 실질적인 개선으로 전환합니다.","love":"오늘 사랑에서는 추측보다 현재에 집중하세요. 분석, 공예, 도움되는 봉사라는 당신의 선물은 연기하지 않고도 연결될 수 있게 도와줍니다.","career":"직장에서, 새로운 동력을 쫓기 전에 가장 의미 있는 업무를 완료하세요. 관찰력 있고, 실용적이며, 사려 깊고, 정확한 것을 도구로 사용하고 동시에 모두 만족시켜야 하는 기대가 아니라고 생각하세요.","finance":"오늘의 돈 관련 선택을 단순하고 현실적으로 유지하세요. 완벽주의, 자기 비판, 세부 사항에 대한 걱정이 실질적인 결정에 영향을 미치기 시작할 때 이를 주목하세요.","wellbeing":"작은 휴식은 당신의 에너지를 재설정할 수 있습니다. 할 수 있는 것을 개선하고, 완벽해지기 전에 좋은 일이 완성될 수 있도록 허용하세요.","guidance":"하루가 끝나기 전에 기억하세요: 개선할 수 있는 것은 개선하고, 좋은 일이 완벽하기 전에 완성될 수 있도록 허락하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'week', 'ko', '{"overview":"이번 주는 한 번의 극적인 순간보다는 꾸준한 선택을 통해 전개됩니다. 처녀자리는 땅의 에너지를 통해 움직입니다. 판단력과 봉사는 처녀자리를 안내하며, 세심한 관찰을 실질적인 개선으로 전환합니다.","love":"관계는 정직함과 따뜻함을 모두 담을 수 있는 대화로 혜택을 봅니다. 분석, 장인 정신, 도움 되는 봉사의 당신의 재능이 수행 없이 연결될 수 있도록 도와줄 수 있습니다.","career":"당신의 최고의 직업적 성장은 우선순위를 선택하고 그것을 위해 시간을 확보함으로써 이루어집니다. 관찰력이 있고, 실용적이며, 사려 깊고, 정밀한 것을 도구로 사용하세요. 한꺼번에 모두 충족해야 하는 기대가 아니라 도구로 사용하세요.","finance":"더 큰 지출을 하기 전에 자신의 소비 패턴을 검토하세요. 완벽주의, 자기 비판, 세부 사항에 대한 걱정이 실질적인 결정에 영향을 미치기 시작할 때를 주목하세요.","wellbeing":"일주일 동안 진정한 회복과 함께 운동의 균형을 유지하세요. 할 수 있는 것을 개선하고, 완벽해지기 전에 좋은 성과가 완성되도록 허용하세요.","guidance":"이번 주를 안내할 질문으로 삼으세요: 할 수 있는 것을 개선하고, 완벽해지기 전에 좋은 작업이 완성되도록 허용하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('virgo', 'year', 'ko', '{"overview":"올해는 정체성, 목적, 그리고 에너지를 사용하는 방식에 대한 인내심 있는 성장을 초대합니다. 처녀자리는 흙의 에너지를 통과합니다. 분별력과 봉사는 처녀자리를 이끌며, 세심한 관찰을 실질적인 개선으로 전환합니다.","love":"일관성을 실천하고 인간적인 속도로 관계가 발전하도록 허용할 때 사랑은 깊어집니다. 분석력, 솜씨, 도움이 되는 서비스라는 당신의 재능은 공연하지 않고도 관계를 맺는 데 도움이 될 수 있습니다.","career":"장기적인 작업은 야망이 지속할 수 있는 구조와 결합될 때 더 강해집니다. 관찰력 있고 실용적이며 사려 깊고 정확한 것을 도구로 사용하세요, 한 번에 모두 충족해야 하는 기대가 아니라.","finance":"완벽한 예측 대신 반복 가능한 습관을 통해 재정적 자신감을 쌓으세요. 완벽주의, 자기 비판, 세부 사항에 대한 걱정이 실질적인 결정에 영향을 미치기 시작할 때 이를 알아차리세요.","wellbeing":"복지를 당신이 구축하고 있는 삶의 완료 후 보상이 아니라 기초로 다루세요. 개선할 수 있는 것을 개선하고, 좋은 일이 완벽해지기 전에 완성되도록 두세요.","guidance":"일년 내내 이 나침반으로 돌아가라: 개선할 수 있는 것을 개선하고, 좋은 작업이 완벽해지기 전에 완성될 수 있도록 허락하라."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('libra', 'ko', '{"name":"천칭자리","dateRange":"9월 23일 – 10월 22일","rulingPlanet":"금성","summary":"균형, 아름다움, 그리고 상호성이 저울을 모든 목소리를 존중하는 선택으로 이끕니다.","originStory":"천칭자리의 저울은 정의의 여신 아스트라이아가 들고 있으며, 별자리 중 유일한 무생물 상징을 형성합니다. 그것들은 신중한 판단, 사회적 조화, 이미 존재한다고 가정하기보다는 균형을 회복하는 지속적인 노력을 나타냅니다.","traits":["외교적","공정한 마음","매력적인","협력적인"],"strengths":["중재","관점","조화를 창조하기"],"challenges":["우유부단","사람들을 기쁘게 하기","필요한 갈등을 피하기"],"compatibleSigns":["쌍둥이자리","물병자리","사자자리"],"reflectionPrompt":"자신의 필요에 대한 진실을 포기하지 않고 공정함을 추구하라."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'day', 'ko', '{"overview":"오늘은 한 가지 분명하고 의도적인 단계를 지지합니다. 천칭자리는 공기의 에너지를 통과합니다. 균형, 아름다움, 상호성이 천칭을 이끌어 모든 목소리를 존중하는 선택으로 안내합니다.","love":"오늘 사랑에서는 추측보다 현재에 집중하세요. 중재, 관점, 조화를 이루는 능력을 갖춘 당신의 선물은 꾸미지 않아도 관계를 맺는 데 도움을 줄 수 있습니다.","career":"직장에서, 새로운 동력을 쫓기 전에 가장 의미 있는 업무를 완료하세요. 외교적이고, 공정하며, 매력적이고, 협력적인 태도를 도구로 사용하고, 한꺼번에 모두 만족시켜야 하는 기대치로 보지 마세요.","finance":"오늘의 금전 선택은 단순하고 현실적으로 유지하세요. 실용적인 결정에 영향을 미치기 시작하는 우유부단함, 다른 사람 맞춤, 필요한 갈등 회피를 알아차리세요.","wellbeing":"작은 휴식은 당신의 에너지를 다시 설정할 수 있습니다. 자신의 필요라는 진실을 버리지 않고 공정함을 추구하세요.","guidance":"하루가 끝나기 전에 기억하세요: 자신의 필요의 진실을 포기하지 않고 공정을 추구하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'week', 'ko', '{"overview":"이번 주는 한 번의 극적인 순간보다는 꾸준한 선택을 통해 전개됩니다. 천칭자리는 공기의 에너지를 통해 움직입니다. 균형, 아름다움, 상호성을 통해 천칭자리는 모든 목소리를 존중하는 선택을 하도록 안내받습니다.","love":"관계는 정직함과 따뜻함을 모두 수용할 수 있는 대화에서 혜택을 받습니다. 중재, 관점 제시, 조화 창출과 같은 당신의 능력은 연기하지 않고도 연결할 수 있도록 도와줄 수 있습니다.","career":"가장 뛰어난 직업적 성장은 우선 순위를 정하고 그것을 위한 시간을 지키는 데서 옵니다. 외교적이고, 공정하며, 매력적이고, 협력적인 태도를 도구로 사용하세요. 이것들을 한꺼번에 모두 충족해야 하는 기대치로 생각하지 마세요.","finance":"더 큰 지출을 하기 전에 자신의 소비 패턴을 검토하세요. 우유부단함, 다른 사람을 기쁘게 하려는 성향, 필요한 갈등 회피가 실질적인 결정에 영향을 미치기 시작할 때를 주목하세요.","wellbeing":"일주일 내내 진정한 회복과 함께 움직임의 균형을 맞추세요. 자신의 필요에 대한 진실을 버리지 않고 공정을 추구하세요.","guidance":"이번 주에는 이 질문이 길잡이가 되게 하세요: 자신의 필요에 대한 진실을 포기하지 않고 공정함을 추구하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('libra', 'year', 'ko', '{"overview":"올해는 정체성, 목적, 그리고 에너지를 사용하는 방식에 있어 인내심 있는 성장을 초대합니다. 천칭자리는 공기 에너지를 통과합니다. 균형, 아름다움, 상호 존중이 저울자리를 모든 목소리를 존중하는 선택으로 인도합니다.","love":"사랑은 일관성을 실천하고 인간의 속도로 연결이 진화하도록 허용할 때 깊어집니다. 당신의 명상, 관점, 조화 창조의 선물은 연기하지 않고도 연결되는 데 도움을 줄 수 있습니다.","career":"장기적인 작업은 지속할 수 있는 구조와 야망이 결합될 때 더 강해집니다. 외교적이고, 공정하며, 매력적이고, 협력적인 태도를 도구로 사용하고, 한꺼번에 모두 충족해야 할 기대치로 사용하지 마세요.","finance":"완벽한 예측 대신 반복 가능한 습관을 통해 재정적 자신감을 쌓으세요. 우유부단, 다른 사람을 기쁘게 하려는 마음, 필요한 갈등을 회피하는 것이 실질적인 결정에 영향을 미치기 시작할 때 이를 알아차리세요.","wellbeing":"웰빙을 삶을 완성한 후의 보상으로 여기지 말고, 당신이 세워가는 삶의 기반으로 여기세요. 자신의 필요에 대한 진실을 포기하지 않고 공정을 추구하세요.","guidance":"일 년 내내 이 나침반으로 돌아가라: 자신의 필요에 대한 진실을 포기하지 않으면서 공정을 추구하라."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('scorpio', 'ko', '{"name":"전갈자리","dateRange":"10월 23일 – 11월 21일","rulingPlanet":"명왕성","summary":"깊이와 변형은 전갈자리를 정의하며, 그의 통찰력은 표면 아래의 진실을 찾아냅니다.","originStory":"전갈자리는 자신의 자만심이 자연의 질서를 방해한 후 사냥꾼 오리온과 맞서도록 보내진 전갈을 기억한다. 하늘에서 그들의 상반된 위치는 경계, 결과, 신비, 그리고 끝난 후에 찾아오는 재생의 힘을 떠올리게 한다.","traits":["강렬한","통찰력 있는","충직한","지략이 있는"],"strengths":["감정적 용기","집중","변화"],"challenges":["비밀","의심","원한을 품기"],"compatibleSigns":["게자리","물고기자리","처녀자리"],"reflectionPrompt":"진실을 숨기기 위해서가 아니라, 변형시키기 위해 당신의 깊이를 사용하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'day', 'ko', '{"overview":"오늘은 명확하고 의도적인 한 걸음을 내딛기에 좋은 날입니다. 전갈자리는 물의 에너지를 통해 움직입니다. 깊이와 변형이 전갈자리를 정의하며, 그들의 통찰력은 표면 아래에서 진리를 찾습니다.","love":"오늘 사랑에서는 추측보다 현재에 집중하세요. 감정적 용기, 집중, 변형이라는 당신의 선물은 연기하지 않고도 연결될 수 있게 도와줍니다.","career":"직장에서, 새로운 동력을 쫓기 전에 가장 의미 있는 업무를 완료하세요. 강렬하고, 통찰력 있으며, 충성스럽고, 재치 있는 것을 도구로 사용하고 동시에 모두 만족시켜야 하는 기대가 아니라고 생각하세요.","finance":"오늘의 금전적 선택은 단순하고 현실적으로 유지하세요. 비밀, 의심, 원한이 실질적인 결정에 영향을 미치기 시작할 때 알아차리세요.","wellbeing":"작은 휴식은 당신의 에너지를 다시 설정할 수 있습니다. 진실을 숨기지 말고, 변형시키는 데 당신의 깊이를 사용하세요.","guidance":"하루가 끝나기 전에 기억하세요: 진실을 숨기기 위해 깊이를 쓰지 말고, 진실을 변형하는 데 사용하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'week', 'ko', '{"overview":"이번 주는 한 번의 극적인 순간보다는 꾸준한 선택을 통해 전개됩니다. 전갈자리는 물의 에너지를 통해 움직입니다. 깊이와 변형은 전갈자리를 정의하며, 그 통찰력은 표면 아래의 진실을 발견합니다.","love":"관계는 정직함과 따뜻함을 모두 수용할 수 있는 대화에서 혜택을 받습니다. 감정적 용기, 집중, 변화를 선물로 가진 당신은 연기하지 않고도 연결할 수 있습니다.","career":"당신의 최고의 직업적 성장은 우선순위를 선택하고 그것을 위해 시간을 확보함으로써 이루어집니다. 강렬하고, 통찰력 있으며, 충실하고, 자원이 풍부한 것을 도구로 사용하세요. 한꺼번에 모두 충족해야 하는 기대가 아니라 도구로 사용하세요.","finance":"더 큰 금전적 결정을 내리기 전에 지출 패턴을 검토하세요. 비밀주의, 의심, 원한을 품는 것이 실제적인 결정에 영향을 미치기 시작할 때를 알아차리세요.","wellbeing":"주 내내 진정한 회복과 함께 움직임의 균형을 맞추세요. 진실을 숨기기 위해서가 아니라 변형시키기 위해 당신의 깊이를 사용하세요.","guidance":"이번 주를 이 질문이 안내하게 하세요: 진실을 숨기기 위해서가 아니라, 진실을 변형시키기 위해 당신의 깊이를 사용하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('scorpio', 'year', 'ko', '{"overview":"올해는 정체성, 목적, 그리고 에너지를 사용하는 방식에 대한 인내심 있는 성장을 초대합니다. 전갈자리는 물의 에너지를 통과합니다. 깊이와 변형이 전갈자리를 정의하며, 그 통찰력은 표면 아래의 진실을 발견합니다.","love":"일관성을 실천하고 인간적인 속도로 관계가 발전하도록 허용할 때 사랑은 깊어집니다. 감정적 용기, 집중력, 변화를 다루는 재능은 공연하지 않고도 관계를 맺는 데 도움이 될 수 있습니다.","career":"야망을 지속할 수 있는 구조와 결합할 때 장기적인 노력은 더 강해집니다. 강렬하고, 통찰력 있으며, 충성스럽고, 지략 있는 것을 도구로 사용하고, 한꺼번에 모두 충족해야 할 기대치로 사용하지 마세요.","finance":"반복 가능한 습관을 통해 재정적 자신감을 구축하고 완벽한 예측을 따르지 마십시오. 비밀 유지, 의심, 원한이 실질적인 결정에 영향을 미치기 시작할 때 이를 주의하십시오.","wellbeing":"건강과 행복을 완성 후의 보상으로 여기지 말고, 당신이 세워가는 삶의 기반으로 삼으세요. 진리를 숨기기 위해서가 아니라, 진리를 변화시키기 위해 당신의 깊이를 사용하세요.","guidance":"일 년 내내 이 나침반으로 돌아가라: 진실을 숨기기 위해서가 아니라 그것을 변형시키기 위해 당신의 깊이를 사용하라."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('sagittarius', 'ko', '{"name":"궁수자리","dateRange":"11월 22일 – 12월 21일","rulingPlanet":"목성","summary":"궁수는 진리, 여행, 학습, 그리고 목적 있는 낙관을 통해 더 넓은 지평을 추구한다.","originStory":"궁수자리는 일반적으로 친근한 것을 넘어 화살을 겨누는 지혜로운 켄타우로스이자 교사 키론과 연결됩니다. 이 별자리는 본능과 더 높은 이해의 결합을 상징하며, 항상 더 의미 있는 수평선을 향해 나아갑니다.","traits":["모험적인","낙관적인","정직한","철학적"],"strengths":["비전","열정","열린 마음"],"challenges":["직설적임","과대 약속","일상 탈출"],"compatibleSigns":["양자리","사자자리","물병자리"],"reflectionPrompt":"멀리 목표를 두되, 일상적인 행동으로 뒷받침할 수 있는 방향을 선택하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'day', 'ko', '{"overview":"오늘은 명확하고 의도적인 한 걸음을 내딛기에 좋은 날입니다. 사수자리는 불의 에너지를 통해 움직입니다. 궁수는 진리, 여행, 학습, 그리고 목적 있는 낙관을 통해 더 넓은 지평을 찾습니다.","love":"오늘 사랑에서는 추측보다 현재에 집중하세요. 비전, 열정, 열린 마음이라는 당신의 선물이 공연하지 않고도 다른 사람과 연결되는 데 도움을 줄 수 있습니다.","career":"일할 때는 새로운 동력을 쫓기 전에 가장 의미 있는 작업을 완료하십시오. 모험적이고, 낙관적이며, 정직하고, 철학적인 태도를 도구로 사용하고, 한꺼번에 모두 만족시켜야 하는 기대치로 사용하지 마십시오.","finance":"오늘의 금전 선택을 단순하고 현실적으로 유지하십시오. 무뚝뚝함, 과잉 약속, 루틴 회피가 실질적인 결정에 영향을 미치기 시작할 때 주목하십시오.","wellbeing":"작은 휴식이 에너지를 재설정할 수 있습니다. 멀리 목표를 잡되, 일상 행동이 지원할 수 있는 방향을 선택하세요.","guidance":"하루가 끝나기 전에 기억하세요: 멀리 목표를 두되, 일상적인 행동이 지탱할 수 있는 방향을 선택하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'week', 'ko', '{"overview":"이번 주는 한 번의 극적인 순간보다는 꾸준한 선택을 통해 전개됩니다. 사수자리는 불의 에너지를 통해 움직입니다. 궁수자리는 진리, 여행, 학습, 그리고 목적 있는 낙관을 통해 더 넓은 지평을 추구합니다.","love":"관계는 정직함과 따뜻함 모두를 수용할 수 있는 대화에서 이익을 얻습니다. 당신의 통찰력, 열정, 열린 마음이라는 재능은 공연하지 않고도 사람들과 연결되는 데 도움이 될 수 있습니다.","career":"최고의 직업적 성장은 우선순위를 선택하고 그것을 위한 시간을 지키는 데서 옵니다. 모험적이고, 낙관적이며, 정직하고, 철학적인 것을 도구로 사용하세요. 한 번에 모두 만족시켜야 하는 기대가 아닙니다.","finance":"더 큰 지출을 하기 전에 자신의 소비 패턴을 검토하세요. 솔직함, 과도한 약속, 일상 탈출이 실질적인 결정에 영향을 미치기 시작하는 시점을 알아차리세요.","wellbeing":"주중 내내 운동과 진정한 회복의 균형을 맞추세요. 멀리 목표를 잡되, 일상의 행동이 지지할 수 있는 방향을 선택하세요.","guidance":"이번 주를 안내할 질문으로 삼으세요: 목표를 높게 잡되, 일상적인 행동으로 지탱할 수 있는 방향을 선택하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('sagittarius', 'year', 'ko', '{"overview":"올해는 정체성, 목적, 그리고 에너지를 사용하는 방식에 있어 인내심 있는 성장을 초대합니다. 사수자리는 불의 에너지를 지나갑니다. 궁수는 진리, 여행, 학습, 그리고 목표 있는 낙관을 통해 더 넓은 지평을 추구합니다.","love":"사랑은 일관성을 실천하고 인간적인 속도로 관계가 발전하도록 허용할 때 깊어진다. 당신의 비전, 열정, 열린 마음이라는 선물은 연기하지 않고도 연결될 수 있도록 도와준다.","career":"장기적인 일은 야망이 지속할 수 있는 구조와 결합될 때 더 강해집니다. 모험적이고, 낙관적이며, 정직하고, 철학적인 것을 도구로 사용하고, 한 번에 모두 만족시켜야 할 기대치로 사용하지 마세요.","finance":"완벽한 예측 대신 반복 가능한 습관을 통해 재정적 자신감을 쌓으세요. 솔직함, 과장된 약속, 일상 탈출이 실질적인 결정에 영향을 미치기 시작할 때 이를 알아차리세요.","wellbeing":"복지를 당신이 쌓아가는 삶의 기초로 삼아라, 그것을 다 끝낸 후 얻는 보상으로 여기지 마라. 멀리 목표를 두되, 당신의 일상적인 행동이 지탱할 수 있는 방향을 선택하라.","guidance":"일년 내내 이 나침반으로 돌아가라: 멀리 목표를 잡되, 당신의 일상적 행동이 지지할 수 있는 방향을 선택하라."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('capricorn', 'ko', '{"name":"염소자리","dateRange":"12월 22일 – 1월 19일","rulingPlanet":"토성","summary":"규율과 장기적인 비전은 염소자리가 아래의 깊이를 현명하게 고려하면서 올라가도록 도와줍니다.","originStory":"염소자리의 바다염소는 타이폰을 피하면서 일부는 물고기로 변한 판과 관련이 있습니다. 산과 바다의 성질은 야망과 감정적 생존을 결합하며, 시간과 책임을 통해 얻은 숙련을 존중합니다.","traits":["야심 있는","규율 있는","인내심 있는","책임이 있는"],"strengths":["인내","전략","신뢰성"],"challenges":["경직","비관주의","업적을 통해 가치 측정"],"compatibleSigns":["황소자리","처녀자리","전갈자리"],"reflectionPrompt":"휴식도 구조의 일부임을 기억하면서 장기적인 계획을 세우십시오."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'day', 'ko', '{"overview":"오늘은 하나의 명확하고 의도적인 한 걸음을 지지합니다. 염소자리는 흙의 에너지를 통해 움직입니다. 규율과 장기적인 비전은 바다염소가 깊이를 현명하게 인식하면서 오를 수 있도록 도와줍니다.","love":"오늘 사랑에서는 추측보다 현재에 집중하세요. 인내, 전략, 신뢰성을 갖춘 당신의 선물은 꾸미지 않아도 관계를 맺는 데 도움을 줄 수 있습니다.","career":"직장에서 새로운 추진력을 쫓기 전에 가장 의미 있는 과제를 완수하세요. 야심차고, 규율 있고, 인내하며, 책임감 있는 것을 도구로 사용하고, 한 번에 모두 충족해야 하는 기대치로 여기지 마세요.","finance":"오늘의 돈 관련 선택을 단순하고 현실적으로 유지하세요. 경직됨, 비관주의, 성취로 자신의 가치를 평가하는 것이 실질적인 결정에 영향을 미치기 시작할 때 이를 주목하세요.","wellbeing":"작은 휴식은 당신의 에너지를 재설정할 수 있습니다. 휴식이 구조의 일부임을 기억하면서 장기적으로 구축하세요.","guidance":"하루가 끝나기 전에 기억하세요: 장기적인 관점에서 구축하되, 휴식이 구조의 일부임을 기억하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'week', 'ko', '{"overview":"이번 주는 한 번의 극적인 순간보다 꾸준한 선택을 통해 전개됩니다. 염소자리는 땅의 에너지를 통해 움직입니다. 규율과 장기적인 시야가 바다염소가 오르면서 아래 깊이에 대해 현명함을 유지하도록 돕습니다.","love":"관계는 정직함과 따뜻함 모두를 위한 여지를 만드는 대화에서 혜택을 얻습니다. 당신의 인내, 전략, 신뢰성의 능력은 연기하지 않고도 연결하는 데 도움을 줄 수 있습니다.","career":"최고의 직업적 성장은 우선순위를 선택하고 그것을 위한 시간을 지키는 데서 옵니다. 야망 있고, 규율 있으며, 인내심 있고, 책임감 있는 것을 도구로 사용하세요. 한 번에 모두 만족시켜야 하는 기대가 아닙니다.","finance":"더 큰 금전적 결정을 내리기 전에 지출 패턴을 검토하세요. 경직됨, 비관주의, 성과를 통해 가치를 측정하는 것이 실제적인 결정에 영향을 미치기 시작할 때를 알아차리세요.","wellbeing":"주중 내내 운동과 진정한 회복의 균형을 맞추세요. 휴식이 구조의 일부임을 기억하면서 장기적으로 쌓아가세요.","guidance":"이번 주를 안내할 질문으로 삼으세요: 휴식이 구조의 일부임을 기억하면서 장기적인 관점으로 구축하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('capricorn', 'year', 'ko', '{"overview":"올해는 정체성, 목적, 그리고 에너지를 사용하는 방식에 대한 인내심 있는 성장을 초대합니다. 염소자리는 지구의 에너지를 통해 움직입니다. 규율과 장기적인 시야가 바닷염소가 아래 깊이에 대해 현명함을 유지하며 올라가는 데 도움을 줍니다.","love":"사랑은 일관성을 실천하고 연결이 인간의 속도로 발전하도록 허용할 때 깊어진다. 인내, 전략, 신뢰성의 재능은 연기하지 않고도 당신이 연결될 수 있도록 도와준다.","career":"장기적인 노력은 야망이 지속할 수 있는 구조와 결합될 때 더 강해집니다. 야망 있고, 규율 있고, 인내심 있으며, 책임감 있는 것을 도구로 사용하고, 한 번에 모두 충족해야 하는 기대치로 사용하지 마십시오.","finance":"완벽한 예측 대신 반복 가능한 습관을 통해 재정적 자신감을 쌓으세요. 경직됨, 비관주의, 성취를 통해 가치를 측정하는 것이 실질적인 결정에 영향을 미치기 시작할 때 이를 알아차리세요.","wellbeing":"복지를 당신이 쌓아가는 삶의 기초로 삼아라, 그것을 다 끝낸 후 얻는 보상으로 여기지 마라. 장기적인 관점에서 구축하되, 휴식이 구조의 일부임을 기억하라.","guidance":"일년 내내 이 나침반으로 돌아가라: 휴식이 구조의 일부라는 것을 기억하면서 장기적으로 건설하라."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('aquarius', 'ko', '{"name":"물병자리","dateRange":"1월 20일 – 2월 18일","rulingPlanet":"천왕성","summary":"독립적인 사고와 집단적인 비전은 물병자리가 세상에 새로운 아이디어를 쏟아낼 수 있도록 인도합니다.","originStory":"물병자리는 신들에게 물을 가져다 준 잔을 가진 술 시중꾼 가니메데와 연결되어 있으며, 상징적으로 인간에게 지식을 가져다 준 존재입니다. 비록 그 이미지가 물을 담고 있지만, 이 별자리는 공기와 관련이 있습니다: 공공의 선을 위해 나누어지는 아이디어, 체계, 그리고 갱신입니다.","traits":["원본","독립적","인도주의자","창의적인"],"strengths":["혁신","객관성","공동체 비전"],"challenges":["분리","반대 습관","확고한 의견"],"compatibleSigns":["쌍둥이자리","천칭자리","궁수자리"],"reflectionPrompt":"당신의 차이를 거리를 두는 대신 연결을 위해 사용하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'day', 'ko', '{"overview":"오늘은 명확하고 의도적인 한 걸음을 내딛기에 좋습니다. 물병자리는 공기의 에너지를 통해 움직입니다. 독립적인 사고와 집단적인 비전이 물병자리에게 세상에 새로운 아이디어를 쏟아내도록 이끌어줍니다.","love":"오늘 사랑에서는 추측보다 현재에 집중하세요. 혁신, 객관성, 공동체 비전을 갖춘 당신의 선물은 꾸미지 않아도 관계를 맺는 데 도움을 줄 수 있습니다.","career":"직장에서, 새로운 동력을 쫓기 전에 가장 의미 있는 업무를 완료하세요. 독창적이고, 독립적이며, 인도주의적이고, 창의적인 것을 도구로 사용하고 동시에 모두 만족시켜야 하는 기대가 아니라고 생각하세요.","finance":"오늘의 금전 선택은 단순하고 현실적으로 유지하세요. 실용적인 결정에 영향을 미치기 시작할 때, 초연함, 반대 습관, 고정된 의견을 인지하세요.","wellbeing":"작은 휴식은 당신의 에너지를 다시 설정할 수 있습니다. 당신의 차이가 거리감을 만들기보다는 연결을 만들도록 하세요.","guidance":"하루가 끝나기 전에 기억하세요: 당신의 차이가 거리를 만들기보다 연결을 돕게 하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'week', 'ko', '{"overview":"이번 주는 한 번의 극적인 순간보다는 꾸준한 선택을 통해 전개됩니다. 물병자리는 공기 기운을 통해 움직입니다. 독립적인 사고와 집단적 비전이 물병자리에게 세상에 새로운 아이디어를 쏟아내도록 안내합니다.","love":"관계는 정직함과 따뜻함 모두를 위한 여지를 만드는 대화에서 혜택을 얻습니다. 당신의 혁신, 객관성, 공동체 비전의 능력은 연기하지 않고도 연결하는 데 도움을 줄 수 있습니다.","career":"가장 뛰어난 직업적 성장은 우선순위를 선택하고 그 시간을 지키는 데서 옵니다. 독창적이고, 독립적이며, 인간적이고, 창의적인 것을 도구로 사용하세요. 동시에 모두를 충족시켜야 하는 기대치로 생각하지 마세요.","finance":"더 큰 지출을 하기 전에 자신의 소비 패턴을 검토하세요. 초연함, 반대 습관, 고정된 의견이 실질적인 결정에 영향을 미치기 시작하는 시점을 알아차리세요.","wellbeing":"일주일 내내 진정한 회복과 함께 움직임의 균형을 맞추세요. 당신의 차이가 거리가 아니라 연결에 도움이 되도록 하세요.","guidance":"이번 주를 이 질문이 안내하게 하라: 당신의 차이를 거리감을 만드는 것이 아니라 연결을 만드는 데 사용하라."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('aquarius', 'year', 'ko', '{"overview":"올해는 정체성, 목적, 그리고 에너지를 사용하는 방식에 대한 인내심 있는 성장을 초대합니다. 물병자리는 공기의 에너지를 통해 움직입니다. 독립적인 사고와 집단적 비전은 물병자리에게 세상에 새로운 아이디어를 쏟아내도록 안내합니다.","love":"일관성을 실천하고 인간의 속도로 연결이 진화하도록 허용할 때 사랑은 깊어집니다. 당신의 혁신, 객관성, 공동체 비전의 선물은 공연하지 않고도 연결되는 데 도움을 줄 수 있습니다.","career":"장기적인 일은 야망이 지속할 수 있는 구조와 결합될 때 더 강해집니다. 독창적이고, 독립적이며, 인간적이고, 창의적인 것을 도구로 사용하고 한 번에 모두 충족해야 하는 기대치로 사용하지 마십시오.","finance":"완벽한 예측 대신 반복 가능한 습관을 통해 재정적 자신감을 쌓으세요. 초연함, 반대 습관, 고정된 의견이 실질적인 결정에 영향을 미치기 시작할 때 이를 알아차리세요.","wellbeing":"웰빙을 인생을 완성한 후 얻는 보상이 아니라, 당신이 만들어가는 삶의 기반으로 여기세요. 당신의 차이가 거리를 두기보다는 연결에 기여하도록 하세요.","guidance":"일년 내내 이 나침반으로 돌아가라: 너의 차이가 거리가 아니라 연결을 이루게 하라."}');
INSERT INTO zodiac_translations (sign_id, locale, payload) VALUES ('pisces', 'ko', '{"name":"물고기자리","dateRange":"2월 19일 – 3월 20일","rulingPlanet":"해왕성","summary":"연민과 상상력이 직관, 꿈, 공유된 감정 사이에서 물고기들을 안내합니다.","originStory":"물고기자리는 아프로디테와 에로스가 물고기가 되어 타이폰을 피하기 위해 자신을 묶었다는 이야기를 떠올리게 합니다. 두 물고기 사이의 유대는 헌신, 유동적인 정체성, 영적 민감성, 변화하는 흐름 속에서 통합을 찾는 것을 의미합니다.","traits":["자비로운","상상력이 풍부한","직관적인","부드러운"],"strengths":["공감","창의성","영적 통찰"],"challenges":["도피주의","흐려진 경계","다른 사람의 감정을 흡수하기"],"compatibleSigns":["게자리","전갈자리","염소자리"],"reflectionPrompt":"당신의 민감함을 보호할 수 있을 만큼 강한 경계로 존중하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'day', 'ko', '{"overview":"오늘은 한 가지 분명하고 의도적인 단계를 지지합니다. 물고기자리는 물의 에너지를 통과합니다. 연민과 상상력이 물고기를 직관, 꿈, 공유된 감정 사이에서 인도합니다.","love":"오늘 사랑에서는 추측보다 현재에 집중하세요. 공감, 창의성, 영적 통찰력이라는 당신의 선물은 연기하지 않고도 연결될 수 있게 도와줍니다.","career":"직장에서 새로운 추진력을 쫓기 전에 가장 의미 있는 과제를 완수하세요. 자비롭고, 상상력이 풍부하며, 직관적이고, 부드러운 것을 도구로 사용하고, 한 번에 모두 충족해야 하는 기대치로 여기지 마세요.","finance":"오늘의 금전 선택은 단순하고 현실적으로 유지하세요. 도피, 흐려진 경계, 다른 사람의 감정을 흡수하는 것이 현실적인 결정에 영향을 미치기 시작할 때 이를 알아차리세요.","wellbeing":"작은 휴식은 당신의 에너지를 재설정할 수 있습니다. 그것을 보호할 수 있을 만큼 강한 경계로 당신의 감수성을 존중하세요.","guidance":"하루가 끝나기 전에 기억하세요: 당신의 민감함을 보호할 수 있을 만큼 강한 경계로 존중하세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'week', 'ko', '{"overview":"이번 주는 한 번의 극적인 순간보다는 꾸준한 선택을 통해 전개됩니다. 물고기자리는 물의 에너지를 통해 움직입니다. 연민과 상상력이 물고기자리를 직관, 꿈, 그리고 공유된 감정 사이에서 안내합니다.","love":"관계는 정직함과 따뜻함을 모두 수용할 수 있는 대화에서 혜택을 받습니다. 당신의 공감, 창의성, 영적 통찰력이라는 선물은 연기하지 않고도 연결하는 데 도움이 될 수 있습니다.","career":"당신의 최고의 직업적 성장은 우선순위를 선택하고 그것을 위한 시간을 지키는 데서 옵니다. 연민, 상상력, 직관, 부드러움을 도구로 사용하세요, 한 번에 모두 충족해야 하는 기대가 아니라.","finance":"더 큰 지출을 하기 전에 자신의 소비 패턴을 검토하세요. 현실 도피, 경계 모호함, 다른 사람의 감정을 흡수하는 것이 실질적인 결정에 영향을 미치기 시작할 때를 알아차리세요.","wellbeing":"일주일 내내 진정한 회복과 함께 움직임의 균형을 맞추세요. 자신의 민감함을 보호할 수 있을 만큼 강한 경계로 존중하세요.","guidance":"이번 주를 안내할 질문으로 삼으세요: 민감함을 존중하며 그것을 보호할 수 있을 만큼 강한 경계를 세우세요."}');
INSERT INTO horoscope_translations (sign_id, period, locale, payload) VALUES ('pisces', 'year', 'ko', '{"overview":"올해는 정체성, 목적, 그리고 에너지를 사용하는 방식에 있어 인내심 있는 성장을 초대합니다. 물고기자리는 물의 에너지를 통해 움직입니다. 연민과 상상력이 물고기자리를 직관, 꿈, 그리고 공유된 감정 사이에서 안내합니다.","love":"사랑은 일관성을 실천하고 연결이 인간의 속도로 발전하도록 허용할 때 깊어진다. 공감, 창의성, 영적 통찰의 재능은 연기하지 않고도 당신이 연결될 수 있도록 도와준다.","career":"장기적인 일은 야망이 지속할 수 있는 구조와 결합될 때 더 강해집니다. 동정심, 상상력, 직관, 온화함을 도구로 사용하고, 한꺼번에 모두 충족해야 하는 기대가 되지 않도록 하세요.","finance":"완벽한 예측 대신 반복 가능한 습관을 통해 재정적 자신감을 쌓으세요. 도피, 경계가 흐려짐, 다른 사람의 감정을 흡수하는 것이 실질적인 결정에 영향을 미치기 시작할 때 이를 알아차리세요.","wellbeing":"웰빙을 삶을 완성한 후의 보상으로 여기지 말고, 당신이 세워가는 삶의 기반으로 여기세요. 자신의 민감함을 보호할 수 있을 만큼 강한 경계로 존중하세요.","guidance":"일년 내내 이 나침반으로 돌아가라: 당신의 민감함을 보호할 수 있을 만큼 강한 경계로 존중하라."}');
